(window.GIM_TP=window.GIM_TP||{})["Z.IdraRabba.0"]={"from":0,"a":[[[],[],[]],[["(אמר אברהם המגיה להסיר מכשול מדרך המעיינים אשר לא הופיע עליהם עדין אור בקבלה השומע ישמע והמבין יבין כי כל המלות אשר הביא האלהי רשב\"י בזה הספר הקדוש כגון מצחא דגולגלתא, שערי דרישא, חללי דמוחא, חוטמא דעתיקא, אודנין, ידין, ורגלין וזולתם מהכלים הגשמיים ותארים אחרים שתאר בהם ה' ית' ובפרט באדרא קדישא רבא ובאדרא קדישא זוטא כי באלו השני מקומות רבו התארים הללו, הלא המה מורים מדות וספירות וענינים פנמיים שכליים וכל האברים שבנו החכמים הללו הם לדמיון וסימנים לדברים סתומים ונעלמים לא לשום דבר גשמי וחמרי חלילה וחס כי אין דמיון בינו ית' וביננו בשום צד מהצדדים וכל שכן מצד העצם והתבנית ה' יצילנו משגיאות. אכי\"ר.) \u0003האדרא רבא קדישא\u0004 תַּנְיָא, אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּיא, עַד אֵימַת נֵיתִיב בְּקַיְּימָא דְּחַד סַמְכָא. כְּתִיב (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ הֵפֵרוּ תּוֹרָתֶךָ. יוֹמִין זְעִירִין, וּמָארֵי דְּחוֹבָא דָּחִיק. כָּרוֹזָא קָארֵי כָּל יוֹמָא, וּמְחַצְדֵּי חַקְלָא זְעִירִין אִינּוּן. וְאִינְהוּ בְּשׁוּלֵי (נ\"א בשורי) כַּרְמָא. לָא אַשְׁגְּחָן, וְלָא יַדְעִין, לְאָן אֲתָר אָזְלִין כְּמָה דְּיָאוּת.","אִתְכָּנָשׁוּ חַבְרַיָיא לְבֵי אִדָּרָא, מְלוּבָּשִׁין שַׁרְיָין סַיְיפֵי וְרוּמְחֵי בִּידֵיכוֹן, אִזְדְרָזוּ בְּתִקּוּנֵיכוֹן. בְּעֵיטָא, בְּחָכְמְתָא. בְּסוּכְלְתָנוּ. בְּדַעְתָּא. בְּחֵיזוּ. בְּיַדִין. בְּרַגְלִין (נ\"א בחילא דידין ורגלין). אַמְלִכוּ עֲלֵיכוֹן לְמַאן (ס\"א למלכא) דְּבִרְשׁוּתֵיהּ חַיֵּי וּמוֹתָא. לְמִגְזַר מִלִּין דִּקְשׁוֹט. מִלִּין דְּקַדִּישֵׁי עֶלְיוֹנִין צַיְיתֵי לְהוּ, וַחֲדָאן לְמִשְׁמַע לְהוּ, וּלְמִנְדַּע לְהוּ.","יָתִיב רַבִּי שִׁמְעוֹן וּבָכָה, וְאָמַר וַוי אִי גָּלֵינָא, וַוי אִי לָא גָּלֵינָא. חַבְרַיָיא דְּהֲוָה תַּמָּן אִשְׁתִּיקוּ. קָם רִבִּי אַבָּא וְאָמַר לֵיהּ, אִי נִיחָא קַמֵּיהּ דְּמֹר לְגַלָּאָה, הָא כְּתִיב (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו, וְהָא חַבְרַיָיא אִלֵּין דַחֲלִין דְקוּדְשָׁא בְּרִיךְ הוּא אִינּוּן, וּכְבַר עָאלוּ בְּאִדָרָא דְּבֵי מַשְׁכְּנָא, מִנְּהוֹן עָאלוּ, מִנְּהוֹן נַפְקוּ.","תָּאנָא, אִתְמָנוּ חַבְרַיָיא קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, וְאִשְׁתְּכָחוּ, רִבִּי אֶלְעָזָר בְּרֵיהּ. וְרִבִּי אַבָּא. וְרִבִּי יְהוּדָה. וְרִבִּי יוֹסֵי בַּר יַעֲקֹב. וְרִבִּי יִצְחָק. וְרִבִּי חִזְקִיָּה בַּר רַב. ורִבִּי חִיָּיא. וְרִבִּי יוֹסֵי. וְרִבִּי יֵיסָא. יְדִין יָהַבוּ לְרַבִּי שִׁמְעוֹן, וְאֶצְבְּעָן זַקְפוּ לְעֵילָּא. וְעָאלוּ בְּחַקְלָא בֵּינֵי אִילָנֵי וְיָתְבוּ. קָם רַבִּי שִׁמְעוֹן וְצַלֵּי צְלוֹתֵיהּ, יָתִיב בְּגַוַּויְיהוּ וְאָמַר, כָּל חַד יְשַׁוִּי יְדוֹי בְּתוּקְפֵּיהּ. שַׁווּ יְדַיְיהוּ, וְנָסִיב לוֹן פָּתַח וְאָמַר (דברים כ״ז:ט״ו) אָרוּר הָאִישׁ אֲשֶׁר יַעֲשֶׂה פֶסֶל וּמַסֵּכָה מַעֲשֵׂה יְדֵי חָרָשׁ וְשָׂם בַּסָּתֶר וְעָנּוּ (ס\"א כל העם) כֻּלָּם וְאָמְרוּ אָמֵן."],[[0,"תניא אמר ר״ש","וכו׳: למדנו, אר״ש לחברים, עד מתי נשב בקיום של \u0003עמוד אחד.\u0004 דהיינו בבחינת עולם התהו, שז״ת היו בקו אחד זה למעלה מזה. ור״ש היה רוצה לגלות להם כאן ענין המדרגות של עולם התקון. שהם \u0003בג׳ עמודים,\u0004 דהיינו סוד ג׳ קוין ימין שמאל אמצע. כתוב עת לעשות לה׳ הפרו תורתך. הימים מועטים ובעל החטאים, דהיינו המקטרג, דוחק. הכרוז קורא כל יום, לתשובה, וקוצרי השדה מועטים המה. דהיינו אותם שזכו בתבואת השדה העליון, שהוא המלכות שהם השגות סודות התורה. והם, ואפילו אותם שהשיגו, נמצאים בסוף הכרם. שהוא המלכות, ואינם משגיחים ואינם יודעים כראוי לאיזה מקום הם הולכים."],[1,"אתכנשו חברייא לבי","וכו׳: התאספו חברים אל מקום המושב, מלובשים במגינים, וחרבות ורמחים בידכם, שה״ס יחודים להשבית הקליפות (עי׳ ת״ז תכ״א דף מט.) הזדרזו בתקוניכם דהיינו שיזדרזו לעשות התקונים של ג׳ קוין: חב״ד, חג״ת, נה״י. בעצה בחכמה בתבונה בדעת במראה, בידים, שה״ס חג״ת וברגלים, שה״ס נה״י. המליכו עליכם את מי שברשותו חיים ומות, לגזור דברי אמת, דברים שקדושים עליונים מקשיבים להם, ושמחים לשמעם ולדעת אותם. \u0003אדרא\u0004 פירושו מושב, מלשון אדרא דאזהרה (מדרש שה״ש על הכתוב שררך אגן הסהר) שפירושו מושב הסנהדרין המזהירים העם. כמ״ש להלאה (אות ד׳) ועאלו בחקלא ביני אילני ויתבו."],[2,"יתיב ר״ש ובכה","וכו׳: ישב ר׳ שמעון ובכה. ואמר, אוי אם אגלה, אוי אם לא אגלה. שאם לא יגלה יאבדו חידושי התורה, ואם יגלה, אולי ישמע מי שאינו ראוי לסודות התורה. החברים שהיו שם שתקו. קם ר׳ אבא ואמר לו. אם טוב לפני אדוני לגלות, הרי כתוב, סוד ה׳ ליראיו. והרי חברים אלו יראי הקב״ה הם, וכבר נכנסו באדרא דבי משכנא. (לעיל משפטים אות תק״כ) למדנו, שמהם נכנסו באדרא רבא זו ומהם יצאו, אבל לא כולם. כי ג׳ חברים נפטרו (כמ״ש להלאה אות שנ״ג)."],[3,"תאנא אתמנו חברייא","וכו׳: למדנו, נמנו החברים לפני ר׳ שמעון, ונמצא ר׳ אלעזר בנו, ור׳ אבא, ור׳ יהודה, ורבי יוסי בר יעקב, ור׳ יצחק, ור׳ חזקיה בר רב, ור׳ חייא, ור׳ יוסי, ור׳ ייסא. הידים נתנו לר׳ שמעון, והאצבעות זקפו למעלה. ונכנסו בשדה בין האילנות, וישבו. קם ר״ש, והתפלל תפלתו. ישב ביניהם ואמר, כל אחד ישום ידיו בחיקו. שמו ידיהם, כל אחד בחיקו, ולקחם ר״ש. פתח ואמר, ארור האיש אשר יעשה פסל ומסכה מעשה ידי חרש ושם בסתר. וענו כלם, כל החברים, ואמרו אמן."],[3,"","פירוש. מיד אחד שנמנו החברים לפניו, קיימו מה שהזהירם (לעיל אות ב׳) \u0003אזדרזו בתקוניכון,\u0004 ועשו תיכף ומיד את היחוד דג׳ קוין, ימין ושמאל ואמצע, להמשיכם אל המלכות. ועשו מעשה למטה כדי לעורר דוגמתו למעלה, וז״ש, \u0003ידין יהבו לר״ש,\u0004 כי ר״ש היה סוד הדעת, שהוא שורש קו האמצעי, וע״כ נתנו לו ידיהם, שהם יד ימין ויד שמאל, ונתיחדו ונכללו ימינם ושמאלם זה בזה, על ידי ר״ש, שהוא קו האמצעי. ועי״ז נתעורר למעלה היחוד דג׳ קוין. ואז, \u0003ואצבען,\u0004 הרומזות על הארת החכמה שבאצבעות (כמ״ש לעיל ב״א דף ק״כ ד״ה אצבען ע״ש) \u0003זקפו לעילא,\u0004 דהיינו שיאירו רק ממטה למעלה. כי אחר שימין ושמאל נכללים יחד ע״י קו האמצעי אין החכמה שבשמאל מאירה רק ממטה למעלה (כמ״ש לעיל ב״א דף ס׳ ד״ה מחלוקת ע״ש) ואח״ז היו צריכים להמשיך כל הארת ג׳ הקוין אל המלכות, וז״ש, \u0003ועאלו בחקלא ביני אילני ויתבו,\u0004 דהיינו סוד חקל תפוחין קדישין, שהוא המלכות. וישבו. להמשיך בה החכמה בבחינת ישיבה. שה״ס ו״ק דחכמה."],[3,"","וז״ש, \u0003כל חד ישוי ידוי בתוקפיה,\u0004 שכל אחד ישום ידו בחיקו. שחיקו מורה על העלם ג״ר, כי שימת יד בחיק הוא מעשה של העלם. אמנם יש ב׳ בחינות של הבאת היד בחיק, בחינה אחת בסוד הבאת ה \u0003י׳\u0004 ב \u0003אור,\u0004 שהאור נהפך ל \u0003אויר,\u0004 הנוהג בקו ימין, בסוד נקודת החולם, שנעשה מחמת זה ו״ק בלי ראש (כנ״ל בראשית א׳ דף ט״ו ד״ה ההיא עש״ה כל ההמשך). ויש הבאת היד בחיק, הנוהג בקו האמצעי, שגורם רק מיעוט הג״ר דחכמה, אבל ו״ק דחכמה נשארים שם. (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) שקו האמצעי ממעט קו השמאל שיאיר רק ממטה למעלה, שהוא בחי׳ ו״ק דחכמה. וכדי להסביר זה, אבאר סוד הכתוב, (שמות ד׳) ויאמר לו ה׳ עוד הבא נא ידך בחיקך. \u0003ויבא ידו בחיקו,\u0004 שז״ס הבאת הי׳ באור הממעטו לאויר, שה״ס ו״ק בלי ראש הנוהג בקו ימין בנקודת החולם. ואח״כ \u0003ויוציאה,\u0004 דהיינו שחזר והוציא ה \u0003י׳\u0004 מאויר, והאויר חזר לאור, ונגלה אור החכמה ממעלה למטה, הנוהג בקו שמאל בנקודת השורק מטרם התקון דקו האמצעי, שאז יש בו דינים קשים, שנסתרים ונסתמים כל האורות, מפני שהחכמה היא בלי חסדים (כנ״ל ב״א מ\"ז אות ל\"ד ד״ה נפק ובהקסה״ז דף י״ז ד״ה קיימא) ולפיכך, \u0003והנה ידו מצורעת כשלג.\u0004 כי סתימת וסגירת האורות ה״ס צרעת. שע״כ צרעת מתרגמינן סגירו. ואחר זה נגלה התקון דקו האמצעי, וז״ס \u0003ויאמר השב ידך אל חיקך,\u0004 שה״ס פעולה ראשונה של קו האמצעי המעורר מסך דחירק מבחינת המנעולא, הממעטו לו״ק (כמ״ש לך דף י״ג ד״ה ונתבאר ע״ש) ואח״כ \u0003ויוציאה מחיקו,\u0004 בסוד פעולה שניה (כמ״ש שם) אשר המלה מחיקו, הוא בדיוק, שפירושו שהוציאה, דהיינו שחזר וגילה החכמה אבל הגילוי היה בלבוש של החיק, דהיינו שהמשיך רק ו״ק דחכמה (כמ״ש שם). ואז נתיחדו כל ג׳ הקוין זה בזה והחכמה נתלבשה בחסדים, וז״ס \u0003והנה שבה כבשרו.\u0004 שחזרה בבחינת ג״ר. אלא בו״ק דחכמה כנ״ל."],[3,"","וז״ש כאן, \u0003כל חד ישוי ידוי בתוקפיה,\u0004 דהיינו בחיק של קו האמצעי, שאז כשיוציאו מחיק, תאיר היד השמאלית רק ממטה למעלה, דהיינו בלבושו של החיק. כי זהו עיקר כל התקון של קו האמצעי, שה״ס חירק. וע״כ ר״ש שהוא בחינת קו האמצעי הזהירם על זה. וז״ש, \u0003שוו ידייהו. ונסיב לון.\u0004 שהם שמו ידיהם בחיקם, ור״ש לקח אותם מן חיקם, כלומר שהוציא ידיהם מן החיק עם הלבוש של החיק, כדרך קו האמצעי. וז״ש \u0003פתח ואמר ארור האיש אשר יעשה פסל\u0004 וגו׳ כי המשכת החכמה ממעלה למטה, היא שורש פסל ומסכה מעשה ידי חרש השם בסתרו של עולם. כלומר המגלה מה שצריך לכסות ולהסתיר. וע״כ, לבסוף השביעם על זה."]],[[0,"","לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, עַד מָתַי נֵשֵׁב בְּקִיּוּם עַמּוּד אֶחָד? כָּתוּב (תהלים קיט) עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תּוֹרָתֶךְ. הַיָּמִים קְטַנִּים, וּבַעֲלֵי הַחוֹב דּוֹחֵק. הַכָּרוֹז קוֹרֵא כָּל יוֹם, וְקוֹצְרֵי הַשָּׂדֶה קְטַנִּים הֵם, וְהֵם בְּשׁוּלֵי הַכֶּרֶם, לֹא מַשְׁגִּיחִים וְלֹא יוֹדְעִים לְאֵיזֶה מָקוֹם הוֹלְכִים כָּרָאוּי."],[1,"","הִתְכַּנְּסוּ הַחֲבֵרִים לְבֵית הָאִדְּרָא, לְבוּשִׁים שִׁרְיוֹן סַיִף, וּרְמָחִים בִּידֵיכֶם! הִזְדָּרְזוּ בְתִקּוּנֵיכֶם, בְּעֵצָה, בְּחָכְמָה, בְּשֵׂכֶל, בְּדַעַת, בְּמַרְאֶה, בַּיָּדַיִם, בָּרַגְלַיִם. הַמְלִיכוּ עֲלֵיהֶם לְמִי שֶׁבִּרְשׁוּתוֹ חַיִּים וּמָוֶת, לִגְזֹר דִּבְרֵי אֱמֶת, דְּבָרִים שֶׁקְּדוֹשִׁים עֶלְיוֹנִים מַקְשִׁיבִים לָהֶם וּשְׂמֵחִים לְשָׁמְעָם וְלָדַעַת אוֹתָם."],[2,"","יָשַׁב רַבִּי שִׁמְעוֹן וּבָכָה וְאָמַר, אוֹי אִם אֲגַלֶּה! אוֹי אִם לֹא אֲגַלֶּה! הַחֲבֵרִים שֶׁהָיוּ שָׁם שָׁתְקוּ. עָמַד רַבִּי אָמַר וְאָמַר לוֹ, אִם נוֹחַ לִפְנֵי מַר לְגַלּוֹת, הֲרֵי כָּתוּב (שם כה) סוֹד ה' לִירֵאָיו, וַהֲרֵי חֲבֵרִים אֵלּוּ הֵם יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְבָר נִכְנְסוּ בְּאִדְּרַת בֵּית הַמִּשְׁכָּן, מֵהֶם נִכְנְסוּ, מֵהֶם יָצְאוּ."],[3,"","שָׁנִינוּ, נִמְנוּ הַחֲבֵרִים לִפְנֵי רַבִּי שִׁמְעוֹן, וְנִמְצְאוּ רַבִּי אֶלְעָזָר בְּנוֹ, וְרַבִּי אַבָּא, וְרַבִּי יְהוּדָה, וְרַבִּי יוֹסֵי בַּר יַעֲקֹב, וְרַבִּי יִצְחָק, וְרַבִּי חִזְקִיָּה בַּר רַב, וְרַבִּי חִיָּיא, וְרַבִּי יוֹסֵי, וְרַבִּי יֵיסָא. יָדַיִם נָתְנוּ לְרַבִּי שִׁמְעוֹן, וְאֶצְבָּעוֹת זָקְפוּ לְמַעְלָה, וְנִכְנְסוּ בְשָׂדֶה בֵּין הָעֵצִים וְיָשְׁבוּ. קָם רַבִּי שִׁמְעוֹן וְהִתְפַּלֵּל תְּפִלָּתוֹ, יָשַׁב בְּתוֹכָם וְאָמַר, כָּל אֶחָד יָשִׂים יָדוֹ בְּחָזְקוֹ. שָׂמוּ יְדֵיהֶם, וְלָקַח אוֹתָם. פָּתַח וְאָמַר, (דברים כז) אָרוּר הָאִישׁ אֲשֶׁר יַעֲשֶׂה פֶסֶל וּמַסֵּכָה (וגו') מַעֲשֵׂה יְדֵי חָרָשׁ וְשָׂם בַּסָּתֶר וְעָנוּ כָל הָעָם וְאָמְרוּ אָמֵן."]]],[["פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ, אֲמַאי עֵת לַעֲשׂוֹת לַיְיָ. מִשּׁוּם דְּהֵפֵרוּ תּוֹרָתֶךָ. מַאי הֵפֵרוּ תּוֹרָתֶךָ, תּוֹרָה דִּלְעֵילָּא. דְּאִיהִי מִתְבַּטְּלָא אִי לָא יִתְעֲבִיד בְּתִקּוּנוֹי (ס\"א שמא) דָּא. וּלְעַתִּיק יוֹמִין אִתְּמַר. כְּתִיב (דברים ל״ג:כ״ט) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךָ. וּכְתִיב, (שמות ט״ו:י״א) מִי כָמוֹךָ בָּאֵלִים יְיָ.","קָרָא לְרִבִּי אֶלְעָזָר בְּרֵיהּ, אוֹתְבֵיהּ קַמֵּיהּ, וּלְרַבִּי אַבָּא מִסִּטְרָא אַחֲרָא, וְאָמַר אֲנָן כְּלָלָא דְּכוֹלָא. עַד הַשְׁתָּא אִתְתְּקָנוּ קַיָימִין. אִשְׁתִּיקוּ, שַׁמְעֵי קָלָא, וְאַרְכּוּבָתָן דָא לְדָא נַקְשָׁן. מַאי קָלָא. קָלָא דִּכְנוּפְיָיא עִלָּאָה דְּמִתְכַּנְּפֵי.","חַדֵּי רַבִּי שִׁמְעוֹן וְאָמַר, (חבקוק ג׳:ב׳) יְיָ שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי. (אמר) (קל\"ח ע\"ב) הָתָם יֵאוֹת הֲוָה לְמֶהֱוִי דָּחִיל. אֲנָן בַּחֲבִיבוּתָא תַּלְיָיא מִלְּתָא, דִּכְתִּיב, (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ אֱלֹהֶיךָ, וּכְתִיב (דברים ז׳:ח׳) מֵאַהֲבַת יְיָ אֶתְכֶם, וּכְתִיב (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם וְגוֹ'.","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי י״א:י״ג) הוֹלֵךְ רָכִיל מְגַלֶּה סּוֹד וְנֶאֱמַן רוּחַ מְכַסֶּה דָבָר. הוֹלֵךְ רָכִיל, הַאי קְרָא קַשְׁיָא, (כיון דאתמר רכיל אמאי הולך) אִישׁ רָכִיל מִבָּעֵי לֵיהּ לְמֵימַר, מַאן הוֹלֵךְ. אֶלָּא מַאן דְּלָא אִתְיְישָׁב בְּרוּחֵיהּ, וְלָא הֲוִי מְהֵימָנָא, הַהוּא מִלָּה דְּשָׁמַע, אָזִיל בְּגַוִויהּ כְּחִיזְרָא בְּמַיָּא, עַד דְּרָמֵּי לֵיהּ לְבַר. מַאי טַעְמָא. מִשּׁוּם דְּלֵית רוּחֵיהּ רוּחָא דְּקִיּוּמָא. אֲבָל מַאן דְּרוּחֵיהּ רוּחָא דְּקִיּוּמָא, בֵּיהּ כְּתִיב, וְנֶאֱמַן רוּחַ מְכַסֶּה דָבָר. וְנֶאֱמַן רוּחַ, קִיוּמָא דְּרוּחָא. (כמו (ישעיהו כ״ב:כ״ג) ותקעתיו יתד במקום נאמן) בְּרוּחָא תַּלְיָיא (נ\"א ברזא) מִלְּתָא. וּכְתִיב, (קהלת ה׳:ה׳) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ.","וְלֵית עָלְמָא מִתְקַיְּימָא אֶלָּא בְּרָזָא. וְכִי אִי (קל\"ח ע\"א) בְּמִלֵּי עָלְמָא אִצְטְרִיךְ רָזָא. בְּמִלִּין רָזִין דְּרָזַיָיא דְּעַתִּיק יוֹמִין, דְּלָא אִתְמַסְרָאן אֲפִילּוּ לְמַלְאָכִין עִלָּאִין עַל אַחַת כַּמָּה וְכַמָּה. אָמַר רַבִּי שִׁמְעוֹן, לִשְׁמַיָּא לָא אֵימָא דְּיֵצִיתוּן (ס\"א דיציתן), לְאַרְעָא לָא אֵימָא דְּתִשְׁמַע, דְּהָא אֲנָן קִיוּמֵי עָלְמִין. תָּנָא רָזִין דְּרָזִין, כַּד פָּתַח רַבִּי שִׁמְעוֹן בְּרָזֵי דְּרָזִין, אִזְדַּעְזָע אַתְרָא, וַחֲבֵרִין אִתְחַלְחָלוּ.","גַּלֵּי בְּרָזָא וּפָתַח וְאָמַר, כְּתִיב (בראשית ל״ו:ל״א) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ וְגוֹ'. זַכָּאִין אַתּוּן צַדִּיקַיָּיא, דְּאִתְגְלֵי לְכוֹן רָזֵי דְּרָזִין דְּאוֹרַיְיתָא, דְּלָא אִתְגַּלְּיָין לְקַדִּישֵׁי עֶלְיוֹנִין, מַאן יַשְׁגַּח בְּהַאי, וּמַאן יִזְכֶּה בְּהַאי, דְּהוּא סַהֲדוּתָא עַל מְהֵימְנוּתָא (דמהימנותא) דְּכֹלָּא (ק\"ל ע\"ב, קכ\"ט ע\"א, קל\"ו ע\"א). (דנהיר למאתאן ושבעין עלמין ומניה נהיר אורייתא דנהירין ביה צדיקייא לעלמא דאתי. הדא הוא דכתיב (משלי ד׳:י״ח) וארח צדיקים כאור נגה הולך ואור עד נכון היום. מן ההוא ארחא מתפרשן לשית מאה ותליסר אורחיה דפליג בזעיר אנפין דכתיב (תהילים כ״ה:י׳) כל ארחות יי חסד ואמת לנוצרי בריתו וגו') צְלוֹתָא בְּרַעֲוָא יְהֵא, דְּלָא יִתְחֲשָׁב לְחוֹבָא לְגַלָּאָה דָּא. וּמַה יֵימְרוּן חַבְרַיָיא, דְּהַאי קְרָא קַשְׁיָא הוּא, דְּהָא לָא הֲוָה לֵיהּ לְמִכְתַּב הָכִי, דְּהָא חֲזֵינָן כַּמָה מְלָכִים הֲווֹ, עַד דְּלָא יֵיתוּן בְּנֵי יִשְׂרָאֵל, וְעַד לָא יְהִי מַלְכָּא לִבְנֵי יִשְׂרָאֵל וּמַה אִתְחֲזֵי הָכָא, וּבְדָא אַתְּעֲרוּ חַבְרַיָיא. אֶלָּא רָזָא דְּרָזִין הוּא, דְּלָא יַכְלִין בְּנֵי נָשָׁא לְמִנְדַּע וּלְאִשְׁתְּמוֹדַע וּלְמִרְחַשׁ בְּדַעֲתַּיְיהוּ בְּהַאי.","תָּאנָא, (קל\"ד, קמ\"ב ע\"א) עַתִּיקָא דְּעַתִּיקִין, טְמִירָא דִּטְמִירִין, עַד לָא זַמִּין תִּקּוּנוֹי (דמלכא), וְעִטּוּרֵי עִטּוּרִין, שֵׁירוּתָא וְסִיּוּמָא לָא הֲוָה. וַהֲוָה מַגְלִיף וּמְשַׁעֵר בֵּיהּ. וּפָרִיס קַמֵּיהּ חַד פַּרְסָא, וּבָה גְּלִיף וְשִׁיעֵר מַלְכִּין.","וְתִקּוּנוֹי לָא אִתְקְיָימוּ, הֲדָא הוּא דִכְתִיב וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. מַלְכָּא קַדְמָאָה, לִבְנֵי יִשְׂרָאֵל קַדְמָאָה. וְכֻלְּהוּ דִּגְלִיפוּ (ולא אתקיימו) בִּשְׁמָהָן אִתְקְרוּן. וְלָא אִתְקְיָימוּ, עַד דְּאָנַח לְהוּ, וְאַצְנַע לְהוּ, וּלְבָתַר זִמְנָא הוּא אִסְתְּלַּק (נ\"א הוה מסתכל) בְּהַהוּא פַּרְסָא, וְאִתְתְּקַּן בְּתִקּוּנוֹי.","וְתָאנָא, כַּד סָלִיק בִּרְעוּתָא, לְמִבְרֵי אוֹרַיְיתָא טְמִירָא תְּרֵי אַלְפֵי שְׁנִין, וְאַפְּקָה, מִיַּד אָמְרָה קַמֵּיהּ, מַאן דְּבָעֵי לְאַתְקְנָא וּלְמֶעְבַּד (קל\"ה ע\"א), יְתַקֵּן בְּקַדְמִיתָא תִּקּוּנוֹי."],[[0,"פתח ר״ש ואמר","וכו׳: פתח ר׳ שמעון ואמר, עת לעשות לה׳ הפרו תורתך. פירושו, למה עת לעשות לה׳ הוא משום שהפרו תורתך. מה הפרו תורתך. היינו שהפרו תורה של מעלה, שה״ס ז״א, כי היא מתבטלת אם אינה נעשית בתיקוניה אלו, כמו שיבאר לפנינו. ומקרא זה נאמר לעתיק יומין, שממנו מתחיל שורש כל התקונים, כמ״ש לפנינו. וכתוב, אשריך ישראל מי כמוך. שהוא משום שהם דבוקים בקו האמצעי. וכתוב, מי כמוך באלים ה׳. שזה סובב על ז״א שהוא קו האמצעי."],[1,"קרא לרבי אלעזר","וכו׳: קרא את ר״א בנו והושיבו לפניו ולר׳ אבא מצד האחר, ואמר אנחנו כלל הכל. כי נשמת ר׳ אלעזר היתה מסוד החכמה, ושל ר׳ אבא היתה מבינה, ור׳ שמעון עצמו היה הדעת המיחד חו״ב זה בזה. וע״כ אמר אנו כלל הכל. כי חב״ד הם כלל כל המדרגות. עד עתה נתקנו העמודים, דהיינו עד עתה, עסקו בתקון ג׳ הקוים, הנקראים ג׳ עמודים. שתקו. שמעו קול, וברכיהם זו לזו דופקות, מחמת פחד. מה היה הקול. היינו קול חבריא העליונה שמתאספים, דהיינו המרכבות של הקב״ה. כמ״ש באדרת האזינו אות כ\"ט."],[2,"חדי ר״ש ואמר","וכו׳: שמח ר״ש ואמר, ה׳ שמעתי שמעך יראתי. שם נכון היה שיהיה מתירא. משום ששורשו היה מקו שמאל, אבל אנחנו המיוחדים בקו האמצעי, באהבה תלוי הדבר, דהיינו בחסדים שהם בחינת אהבה. שכתוב, ואהבת את ה׳ אלקיך. וכתוב, מאהבת ה׳ אתכם. וכתוב אהבתי אתכם וגו׳."],[3,"ר״ש פתח ואמר","וכו׳: ר״ש פו״א, הולך רכיל מגלה סוד ונאמן רוח מכסה דבר. \u0003הולך רכיל.\u0004 מקרא זה קשה, איש רכיל, היה צריך לומר, מהו, הולך רכיל. ומשיב, אלא מי שאינו מיושב ברוחו ואינו נאמן, דבר ההוא ששמע, הולך בתוכו, כמוץ במים, שאינו נשקע בהם, עד שמשליך אותו לחוץ. כלומר שאין לו מנוחה, עד שמגלה הדבר ששמע, לאחר. מהו הטעם. הוא משום שרוחו אינו רוח מתקיים ומיושב, אבל מי שרוחו הוא רוח מיושב ושל קיום, בו כתוב, ונאמן רוח מכסה דבר. ונאמן רוח, פירושו רוח מתקיים. וברוח תלוי הדבר. וכתוב אל תתן את פיך לחטיא את בשרך."],[4,"ולית עלמא מתקיימא","וכו׳: ואין העולם מתקיים אלא בסוד, וכי, אם בדברי העולם צריכים סוד, בדברי סודי הסודות דעתיק יומין, שאינם נמסרים אפילו למלאכים עליונים, על אחת כמה וכמה. א״ר שמעון, לשמים איני אומר שיאזינו. לארץ איני אומר שתשמע. שהרי אנו מקיימי העולמות. כלומר משה וישעיה היו מעידים את השמים וארץ שאם בני ישראל לא יקיימו העולמות יענישו אותם שהשמים לא יתנו מטר וארץ לא תתן יבולה. אבל ר״ש היה מדבר לצדיקים מקיימי העולמות שאיו צריכים לעדות. למדנו, סודי הסודות, כשפתח ר״ש בסודות הסודות, נזדעזע המקום. והחברים נתחלחלו."],[5,"גלי ברזא ופתח","וכו׳: גילה בסוד ופתח ואמר, כתוב ואלה המלכים אשר מלכו בארץ אדום לפגי מלך מלך וגו׳. אשריכם הצדיקים שנתגלו לכם סודי הסודות של התורה, שאינם מתגלים לקדושים העליונים דהיינו למלאכים. מי ישגיח בזה ומי יזכה בזה, בזה הכתוב ואלה המלכים וגו׳, שהוא עדות על האמונה של הכל. התפלה תהיה לרצון שלא יהיה נחשב לחטא לגלות זה. ומה יאמרו החברים, שהרי מקרא זה קשה הוא שהרי לא היה צריך לכתוב כך, כי אנו רואים כמה מלכים שהיו לאדום, מטרם שבאו בני ישראל, ומטרם שהיה מלך לבני ישראל. ומה מראה לנו כאן, אלא סוד הסודות הוא, ובני אדם אינם יכולים לדעת ולהוודע ולעיין בדעתם בזה. להיותו מרמז לעולמות עליונים. כמ״ש לפנינו."],[6,"תאנא עתיקא דעתיקין","וכו׳: למדנו, עתיק של כל העתיקין הצפון מכל צפון, מטרם שהכין תקוניו ועטרי עטרות, הכנת הכלים והכשרתם לקבל האורות נקראים תקונים. והאורות עצמם נקראים עטרות. מלשון הכתוב בעטרה שעטרה לו אמו. עוד לא היה ראשית וסיום, שהם חכמה עלאה שהיא ראשית הגילוי. וחכמה תתאה שהיא סוף הגילוי. (כמ״ש באדרא זוטא אות ע') והיה מחוקק ומשער בה דהיינו בגילוי הראש והסיום. ופרש לפניו גבול אחד ובו חקק ושיער מלכים. \u0003פרסא.\u0004 פירושו מסך וגבול. מלשון פורסא דדמא כל ל׳ יום. שפירושו גבול הזמן. (שבת קכט.)."],[7,"ותקונוי לא אתקיימו","וכו׳: ותקוניו לא נתקיימו. ז״ש ואלה המלכים אשר מלכו בארץ אדום לפני מלך מלך לבני ישראל, שפירושו, לפני מלך הראשון שמלך לבני ישראל הראשון. וכולם שנחקקו נקראים בשמותיהם, ולא נתקיימו עד שעזב אותם והצניע אותם. ולאחר כך היה מתעלה בגבול ההוא ונתתקן בתקוניו."],[7,"","ביאור הדברים. נודע שתחילה ברא הקב״ה את העולם במדת הדין, דהיינו במלכות שהיא מדת הדין ונסתיימו האורות במקום המלכות, שנתצמצמה שלא לקבל אור. וזה נקרא צמצום א׳. ומבחינת גבול הזה דצמצום א׳, יצאו ג׳ פרצופי אדם קדמון, הנקראים גלגלתא, ע״ב, ס״ג דא״ק. וראה המאציל שהעולם לא יוכל להתקיים במדת הדין הזו, של המלכות, שיתף עמה מדת הרחמים, שהעלה המלכות וערב אותה בבינה שנקראת מדת הרחמים. (כמ״ש זה בבראשית א׳ דף ז׳ ד״ה וכבר). ונסתיימו מחמת זה האורות, במקום בינה, וזה נקרא צמצום ב׳, וגבול החדש הזה שבמקום בינה, נקרא \u0003פרסא.\u0004"],[7,"","ופרסא זו נעשתה בפרצוף שני דס״ג דא״ק, הנקרא נקודות דס״ג דא״ק, או עולם הנקודים, ולפיכך מגלגלתא ע״ב ס״ג דא״ק, אין לנו מושג כלל, להיותם מבחינת המלכות דצמצום א׳. והזהר אינו מדבר מהם, אלא ברמזים דקים מן הדקים, ותחילת הדבור של חכמי הזהר ורשב״י, הוא מעולם הנקודים הנזכר, שכבר נתתקן שם הפרסא, שה״ס המיתוק של המלכות בבינה, שהעולם מתקיים על ידה."],[7,"","ופרסא זו היא סבה לתקון ג׳ קוין. כי עם תקון הפרסא, דהיינו עם עלית המלכות לבינה, יצאה נקודת החולם, שה״ס קו ימין. הנעשה ע״י ביאת ה \u0003י׳\u0004 באור החכמה ונעשה אויר. ואח״כ ע״י הארת ע״ב ס״ג דא״ק שאין בהם פרסא, מורידים המלכות ממקום בינה למקומה, ויוצאת נקודת השורק, שה״ס קו שמאל הנעשה ע״י יציאת ה \u0003י׳\u0004 מאויר, וחזר להיות אור החכמה, ואח״כ ע״י עלית ז״א המיחד ימין ושמאל, יוצאת נקודת החירק, שה״ס קו האמצעי (כנ״ל ב״א דף ט״ו ד״ה ההוא ע״ש)."],[7,"","ובענין קו האמצעי המיחד ימין ושמאל זה בזה, יש ב׳ מיני יחודים, א) הוא בג״ר דבינה, כי מתוך שג״ר דבינה הם בסוד חפץ חסד הוא, ואינם חפצים חכמה, ע״כ אינם רוצים לקבל חכמה מא״א, רק בשעה שז״א עולה להם למ״ן, והטעם הוא, כי מתוך הקשר שיש לבינה דאור ישר אל ז״א דאור ישר להשפיע לו הארת חכמה, (כמ״ש בתלמוד עשר ספירות שיעור א׳ דף ר ד״ה וטעם, ע״ש) אף בפרצופין כן הוא, שבעת שז״א עולה לג״ר דבינה, שה״ס או״א עלאין, אז עולים או״א עלאין ומקבלים חכמה מא״א, ומשפיעים לישסו״ת, ומישסו״ת לז״א. וזה נבחן לתקון קוין דג״ר. יחוד ב) הוא תקון קוין דו״ק דבינה. והיינו אחר שאו״א שקבלו החכמה מא״א, השפיעו אותה לו״ק דבינה. ויצאה שם נקודת השורק, אז נעשתה מחלוקת בין קו ימין לקו שמאל, ואור החכמה שבקו שמאל נסתם, מחמת חסרון חסדים ונעשה לחשך. ואז בא ז״א בסוד המסך דחירק שבו ויחד ימין ושמאל זב״ז וקיים הארת שניהם, באפן שהחסדים שבקו ימין יאירו ממעלה למטה, והחכמה שבקו שמאל תאיר ממטה למעלה. כמ״ש לעיל (ב״א דף ס׳ ד״ה מחלוקת) ומכח זה אין הפרסא נבטלת לעולם, ואע״פ שהמלכות יוצאת מן הפרסא ובאה למקומה בעת הארת נקודת השורק, שאז כל בינה ותו״מ שנפלו לתחתון מחמת גבול החדש שבבינה, חוזרים למדרגתם (כנ״ל ב״א דף ר״צ ד״ה בגין). הפירוש הוא שבינה ותו״מ אלו עולים למעלה מפרסא ושם למעלה מפרסא מתחברים למדרגתם ומתתקנים שם בבחינת שמאל לכתר וחכמה שנשארו במדרגה, כמ״ש זה באורך (ויקהל אות קל\"א בהסולם) עש״ה. ולפיכך אין הפרסא נפגעת כלום מחמת יציאת הי׳ מאויר, שה״ס הארת השורק."],[7,"","והנה בעולם הנקודים, אע״פ שכבר היה שם תקון הפרסא, עכ״ז עוד לא היה שם יחוד הב׳ דתקון קוין, שהוא תקון קוין דו״ק דבינה. אלא יחוד הא׳, שהוא תקון קוין בג״ר דבינה, וע״כ אחר שיצאה המלכות מן הפרסא, שהיא במקום בינה, וחזרה למקומה, נתבטל הפרסא מחמת זה, כי חזרה הפרסא להיות בינה ממש, אחר שכבר יצאה ממנה המלכות. ואז נמשכה אור החכמה שבשמאל ממעלה למטה, דהיינו מפרסא העומדת בסיום האצילות, למטה לבי״ע, ואז נשברו כל הכלים והאורות נסתלקו, ועלו לשורשם. שזה נבחן למיתת המלכים, כי מי שיוצא מעולם לעולם נבחן שמת. כן אלו ח׳ מלכים דעולם הנקודים יצאו מאצילות לבי״ע שיציאה זו היא יציאת נשמתם. כי האורות לא נמשכו עם הכלים וע״כ נבחן שמתו."],[7,"","וזה אמרו (באות י״א) \u0003עתיקא דעתיקין טמירא דטמירין.\u0004 שהוא פרצוף נקודות דס״ג דא״ק, דהיינו עולם הנקודים, \u0003עד לא זמין תקונוי,\u0004 דהיינו התקונים שלא תתבטל הפרסא, עוד לא היו, \u0003ועטורי עטורין,\u0004 היינו הג״ר דחסדים המעטרים את החכמה. החכמה נקראת עטרין, והחסדים, עיטורי אותם העטרין דחכמה. \u0003שירותא וסיומא לא הוה,\u0004 כי אחר התקון דקו אמצעי בו״ק דבינה, שהחכמה לא תאיר אלא ממטה למעלה, נמצא שהג״ר דבינה, שה״ס או״א עלאין מקבלים החכמה מא״א ע״י יחוד הא׳ דקו האמצעי. ואו״א נקראים משום זה \u0003חכמה עלאה,\u0004 ונקראים \u0003שירותא,\u0004 כי בהם מתחיל גילוי החכמה, אבל בהם עצמם אין החכמה מקובלת כלל, אלא הם משפיעים לו״ק דבינה, שה״ס ישסו״ת, ושם נעשה יחוד הב׳ דקו האמצעי, המתקן את החכמה שלא תשפיע ממעלה למטה אלא ממטה למעלה, באופן שאחר שהחכמה מקובלת במלכות, היא נעשית סיום על החכמה, שממנה ולמטה אין החכמה מושפעת. וע״כ נקראת המלכות חכמה תתאה. שאחריה עוד אין החכמה נמצאת. וכל זה עוד לא היה בעולם הנקודים כי שם היה חסר יחוד קו האמצעי השני, שבו״ק דבינה, וע״כ לא היה התיקון הזה שהחכמה תאיר בסוד \u0003שירותא וסיומא.\u0004 אלא שהיתה נמשכת ממלכות דאצילות ולמטה לבי״ע. כנ״ל."],[7,"","וזה אמרו, \u0003והוה מגליף ומשער ביה ופריס קמיה חד פרסא,\u0004 דהיינו אחר שכבר היה נפרש לפניו הפרסא היה מגליף ומשער, להמשיך אור החכמה, \u0003ובה, גליף ושיער מלכין,\u0004 הקטנות ה״ס גליף, והגדלות ה״ס שיער. ואומר, שהן הקטנות והן הגדלות היו נבחנות אז בגופא של הפרסא. שבקטנות נפרס הפרסה ובגדלות נתבטלה הפרסא, כנ״ל, וחזר אל הגבול הישן דצמצום א׳. וע״כ \u0003ותקונוי לא אתקיימו,\u0004 אלא שז׳ המלכים נשברו ומתו, כנ״ל. \u0003הה״ד ואלה המלכים וגו׳.\u0004 שז׳ מלכים אלו נאמר בהם וימלוך וימת, שהם רומזים על ז׳ מלכים הנ״ל דנקודים, ולפי שיצאו מבחינת השמאל הם נקראים מלכי אדום. דהיינו בינה שנקראת כן בהיותה בבחינת השמאל שלה. \u0003לפני מלך מלך לבני ישראל. מלכא קדמאה לבני ישראל קדמאה.\u0004 בני ישראל הם הספירות של ז״א שבעולם התקון, דהיינו אחר שנתתקן היחוד דקו האמצעי בו״ק דבינה, שז״ס שלו חג״ת נהי״מ הם בני ישראל, והמלך הראשון שלו הוא חסד. וז״ש, \u0003וכלהו דגליפו בשמהן אתקרון,\u0004 הגדלות ה״ס קריאת שם, ואומר שכולם שנחקקו בקטנות ע״י הפרסה, חזרו וקבלו הגדלות, ונקראו בשמות. \u0003ולא אתקיימו, עד דאנח להו ואצנע להו,\u0004 דהיינו שנשברו ומתו כמ״ש בהם וימלוך וימת, ועזב את הכלים והצניע את האורות."],[7,"","וז״ש \u0003ולבתר זמנא הוא אסתלק בההוא פרסא ואתתקן בתקונוי,\u0004 ולאחר כך, היה מתעלה בפרסא ההיא, ונתתקן בתקוניו, כלומר שנתתקן שהאור יהיה מתעלה מפרסא ולמעלה, דהיינו ע״י יחוד ב׳ דקו אמצעי שבו״ק דבינה. ונתתקן בכל התקונים שיתבארו לפנינו. שכל אלו נעשו בתקון פרצופי אצילות ובי״ע, הנקראים עולם התקון."],[8,"ותאנא כד סליק","וכו׳: ולמדנו, כשעלה ברצונו של המאציל, לברוא תורה נסתרת שני אלפים שנה, והוציאה, דהיינו שבראה, מיד אמרה לפניו, מי שרוצה לתקן ולעשות, יתקן תחילה תקוניו."],[8,"","פירוש. ז״א, שהוא קו האמצעי, נקרא תורה ומקומו הוא לאחר חכמה ובינה הנקראים ב׳ אלפים שנה. אמנם מתוך שכל ספירה נכללת מע״ס, יש בחינת ז״א הנקרא תורה, גם בכתר. והוא נקרא שם \u0003אורייתא טמירא ב׳ אלפי שנין,\u0004 כי להיותו שם קודם ב׳ אלפי שני, שהם חכמה ובינה, נמצא שהוא טמיר ונסתר מהם."],[8,"","וז״ש \u0003ואפקה, מיד אמרה קמיה,\u0004 וכו׳. דהיינו שאמרה ועשתה, \u0003מאן דבעי לאתקנא,\u0004 דהיינו הפרסה, שבה רצה המאציל לשתף מדת הרחמים בדין, ולתקן שהעולם יוכל להתקיים. כנ״ל בדבור הסמוך, \u0003יתקן בקדמיתא תקונוי,\u0004 דהיינו שיתקן תחילה תקונים בשביל הפרסא שלא תתבטל בעת יציאת הארת השורק, כנ״ל בדבור הסמוך, ומיד עשתה התורה, שהוא קו האמצעי, היחוד דימין ושמאל שבו״ק הבינה, שהוא התקון העקרי שהפרסא לא תתבטלה. כנ״ל בדבור הסמוך. ומ״ש שאמרה תורה, היינו אומר ועושה, כי האמירה מספקת למעשה ממש."]],[[0,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, עֵת לַעֲשׂוֹת לַה', מַדּוּעַ עֵת לַעֲשׂוֹת לַה'? מִשּׁוּם הֵפֵרוּ תּוֹרָתֶךְ. מַה זֶּה הֵפֵרוּ תּוֹרָתֶךְ? תּוֹרָה שֶׁלְּמַעְלָה שֶׁהִיא מִתְבַּטֶּלֶת אִם לֹא יַעֲשֶׂה בְּתִקּוּנֵי זֶה. וּלְעַתִּיק הַיָּמִים נֶאֱמַר. כָּתוּב (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ, וְכָתוּב (שמות טו) מִי כָמוֹךְ בָּאֵלִים ה'."],[1,"","קָרָא לְרַבִּי אֶלְעָזָר בְּנוֹ, הוֹשִׁיבוֹ לְפָנָיו, וּלְרַבִּי אַבָּא מִצַּד אַחֵר, וְאָמַר, אָנוּ כְּלַל הַכֹּל. עַד עַכְשָׁו הִתְתַּקְּנוּ הָעוֹמְדִים. שָׁתְקוּ. שָׁמְעוּ קוֹל, וְאַרְכֻּבּוֹתֵיהֶם נָקְשׁוּ זֶה לָזֶה. אֵיזֶה קוֹל? קוֹל שֶׁל כְּנֻפְיָה הָעֶלְיוֹנָה שֶׁמִּתְכַּנְּסִים."],[2,"","שָׂמַח רַבִּי שִׁמְעוֹן וְאָמַר, (חבקוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי. שָׁם רָאוּי לִהְיוֹת יָרֵא. אָנוּ בַּחֲבִיבוּת תָּלוּי הַדָּבָר, שֶׁכָּתוּב (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ, וְכָתוּב (שם ז) מֵאַהֲבַת ה' אֶתְכֶם, וְכָתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם וְגוֹ'."],[3,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי יא) הוֹלֵךְ רָכִיל מְגַלֶּה סּוֹד וְנֶאֱמַן רוּחַ מְכַסֶּה דָבָר. הוֹלֵךְ רָכִיל, פָּסוּק זֶה קָשֶׁה, אִישׁ רָכִיל הָיָה לוֹ לוֹמַר, מַה זֶּה הוֹלֵךְ? אֶלָּא מִי שֶׁלֹּא הִתְיַשֵּׁב בְּרוּחוֹ וְאֵינוֹ נֶאֱמָן, אוֹתוֹ דָּבָר שֶׁשָּׁמַע הוֹלֵךְ בְּתוֹכוֹ כְּקָנֶה בְמַיִם עַד שֶׁמּוֹצִיאוֹ הַחוּצָה. מָה הַטַּעַם? מִשּׁוּם שֶׁאֵין רוּחוֹ רוּחַ שֶׁל עֲמִידָה. אֲבָל מִי שֶׁרוּחוֹ רוּחַ עֲמִידָה, כָּתוּב בּוֹ וְנֶאֱמַן רוּחַ מְכַסֶּה דָבָר. וְנֶאֱמַן רוּחַ, קִיּוּם הָרוּחַ. (כמו ותקעתיו יתד במקום נאמן) בָּרוּחַ (בסוד) הַדָּבָר תָּלוּי. וְכָתוּב (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ."],[4,"","וְאֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא בְּסוֹד. וְכִי אִם בְּדִבְרֵי הָעוֹלָם צָרִיךְ סוֹד - בִּדְבָרִים סוֹדִיִּים שֶׁל סוֹדוֹת עַתִּיק הַיָּמִים שֶׁלֹּא נִמְסְרוּ אֲפִלּוּ לְמַלְאָכִים עֶלְיוֹנִים עַל אַחַת כַּמָּה וְכַמָּה. אָמַר רַבִּי שִׁמְעוֹן, לַשָּׁמַיִם לֹא אֹמַר שֶׁיַּקְשִׁיבוּ, לָאָרֶץ לֹא אֹמַר שֶׁתִּשְׁמַע, שֶׁהֲרֵי אָנוּ קִיּוּמֵי הָעוֹלָמוֹת. לָמַדְנוּ סוֹדֵי הַסּוֹדוֹת. כְּשֶׁפָּתַח רַבִּי שִׁמְעוֹן בְּסוֹדֵי הַסּוֹדוֹת, הִזְדַּעֲזַע הַמָּקוֹם, וְהַחֲבֵרִים הִתְחַלְחֲלוּ."]]],[["תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, עַתִּיקָא דְּעַתִּיקִין, סִתְרָא דְּסִתְרִין טָמִיר דִּטְמִירִין, אִתְתְּקַּן וְאִזְדְּמַן, (כלומר אשתכח, ולא אשכח ממש, אבל אתתקן ולא דידע ליה משום דהוה עתיק דעתיקין) (אבל בתיקוני ידיע) כְּחַד סָבָא דְּסָבִין, עַתִּיק מֵעַתִּיקִין, טָמִיר מִטְּמִירִין, וּבְתִּיקוּנוֹי יְדִיעַ וְלָא יְדִיעַ. מָארֵי דְּחִוָּור כְּסוּ (ס\"א בסומק), וְחֵיזוּ בּוּסִיטָא (ס\"א בוצינא) דְּאַנְפּוֹי (נ\"א באנפוי), יָתִיב עַל כּוּרְסְיָיא דִּשְׁבִיבִין, לְאַכְפְּיָיא לוֹן.","אַרְבַּע מְאָה אַלְפֵי עָלְמִין, אִתְפְּשָׁט חִוָּורָא דְּגוּלְגַּלְתָּא דְּרֵישׁוֹי. וּמִנְהִירוּ דְּהַאי חִיוָּורָא, יַרְתֵּי צַדִּיקַיָּיא לְעָלְמָא דְּאָתֵי, ד' מְאָה עָלְמִין, הֲדָא הוּא דִכְתִיב, (בראשית כ״ג:ט״ז) אַרְבַּע מֵאוֹת שֶׁקֶל כֶּסֶף עוֹבֵר לַסּוֹחֵר.","בְּגוּלְגַּלְתָּא, (בכל יומא) יַתְבִין תְּלֵיסַר (ס\"א תריסר) אַלְפֵי רִבּוֹא עָלְמִין, דְּנַטְלִין עֲלוֹי רַגְלִין, וְסַמְכִין עֲלוֹי. וּמֵהַאי גּוּלְגַּלְתָּא נָטִיף טַלָּא, לְהַהוּא דִּלְבַר, וּמַלְיָיא לְרֵישֵׁיהּ בְּכָל יוֹמָא, דִּכְתִּיב, (שיר השירים ה׳:ב׳) שֶׁרֹאשִׁי נִמְלָא טָל.","וּמֵהַהוּא טַלָּא דְּאַנְעַר מֵרֵישֵׁיהּ, הַהוּא דְּאִיהוּ לְבַר, יִתְּעֲרוּן מֵתַיָּיא לְעָלְמָא דְּאָתֵי. דִּכְתִיב (שראשי נמלא טל, מלאתי טל לא כתיב, אלא נמלא) דִּכְתִיב (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ, אוֹרוֹת נְהוֹרָא דְּחִוַורְתָּא דְּעַתִּיקָא. וּמֵהַהוּא טַלָּא, מִתְקַיְּימִין קַדִּישֵׁי עֶלְיוֹנִין. וְהוּא (רצ\"ב) מָנָא דְּטַחְנֵי לְצַדִּיקַיָּיא לְעָלְמָא דְּאָתֵי. וְנָטִיף הַהוּא טַלָּא לְחַקְלָא דְּתַפּוּחִין קַדִּישִׁין. הֲדָא הוּא דִכְתִיב, (שמות ט״ז:י״ד) וַתַּעַל שִׁכְבַת הַטָּל וְהִנֵּה עַל פְּנֵי הַמִּדְבָּר דַּק מְחוּסְפָּס. וְחֵיזוּ הַהוּא טַלָּא חִוָּור. כְּהַאי גַּוְונָא דְּאַבְנִין (מ\"ט) דִּבְדּוֹלְחָא, דְּאִתְחַזְיָיא כָּל גַּוְונִין בְּגַוָּוהּ. הֲדָא הוּא דִכְתִיב, (במדבר י״א:ז׳) וְעֵינוֹ כְּעֵין הַבְּדוֹלַח.","הַאי גּוּלְגַּלְתָּא. חִוָּורָא דִּילֵיהּ, אַנְהִיר לִתְלֵיסַר (רפ\"ח) עִיבָר גְּלִיפִין בְּסַחֲרָנוֹי. לְאַרְבַּע עִיבָר בְּסִטְרָא חַד, וּלְאַרְבַּע עִיבָר בְּסִטְרָא דָּא, בְּסִטְרָא דְּאַנְפּוֹי. וּלְאַרְבַּע עִיבָר בְּסִטְרָא דָּא, לְסִטְרָא דְּאֲחוֹרָא. וְחַד לְעֵילָּא דְּגוּלְגַּלְתָּא. (כלומר לסטרא דלעילא).","וּמֵהַאי אִתְפְּשָׁט אוֹרְכָא דְּאַנְפּוֹי, לִתְלַת מְאָה וְשִׁבְעִין רִבּוֹא עָלְמִין. וְהַהוּא אִתְקְרֵי אֶרֶךְ אַפַּיִם. (כלומר אורכא דאנפין) וְהַאי עַתִּיקָא דְּעַתִּיקִין אִתְקְרֵי אֲרִיכָא דְּאַנְפִּין. וְהַהוּא דִּלְבַר אִתְקְרֵי זְעֵיר אַנְפִּין. לָקֳבְלֵיהּ דְּעַתִּיקָא סָבָא, קֹדֶשׁ קֳדָשִׁים דְּקֻדְשַׁיָא. וּזְעֵיר אַנְפִּין (קל\"ה ע\"ב) כַּד אִסְתָּכַּל לְהַאי, כֹּלָּא (ס\"א טלא) דִּלְתַּתָּא אִתְתְּקַּן, וְאַנְפּוֹי מִתְפַּשְּׁטִין וַאֲרִיכִין בְּהַהוּא זִמְנָא, אֲבָל לָא כָּל שַׁעֲתָא כְּמָה דְּעַתִּיקָא.","וּמֵהַאי גּוּלְגַּלְתָּא, נָפִיק חַד עִיבָר חִיוָּר לְגוּלְגַּלְתָּא דִּזְעֵיר אַנְפִּין, לְתַקְּנָא רֵישֵׁיהּ. וּמֵהַאי לִשְׁאַר גּוּלְגַּלְתִּין דִּלְתַּתָּא, דְּלֵית לוֹן חוּשְׁבָּנָא. וְכָל גּוּלְגַּלְתָּא יָהֲבִין אֲגָר חִיוַרְתָּא (ס\"א אוראותא) לְעַתִּיק יוֹמִין. כַּד עָאלִין בְּחוּשְׁבָּנָא תְּחוֹת שַׁרְבִיטָא. וְלָקֳבֵיל דָּא, (קל\"ו) בֶּקַע לַגוּלְגּוֹלֶת לְתַתָּא, כַּד עָאלִין בְּחוּשְׁבָּנָא.","בְּחַלָלָא דְּגוּלְגַּלְתָּא, קְרוּמָא דַּאֲוִירָא דְּחָכְמְתָא עִלָּאָה סְתִימָה דְּלָא פָּסַק. וְהַאי לָא שְׁכִיחַ (קכ\"ט), וְלָא אִתְפְּתַח. וְהַאי קְרוּמָא אִתְחַפְּיָיא עַל מוֹחָא דְּאִיהוּ חָכְמְתָא סְתִימָאָה. וּבְגִינֵי כַּךְ אִתְכַּסְּיָא (ס\"א ובגין דאתכסיא) הַאי חָכְמְתָא בְּהַהוּא קְרוּמָא, דְּלָא אִתְפַּתְּחָא. (ס\"א בגין דא אקרי חכמתא סתימאה).","וְהַאי מוֹחָא, דְּאִיהוּ הַאי חָכְמְתָא סְתִימָאָה. שָׁקִיט וְאִשְׁתְּכִיךְ בְּאַתְרֵיהּ, כַּחֲמָר טַב עַל דּוּרְדְּיֵיהּ, וְהַיְינוּ דְּאָמְרֵי סָבָא דַּעְתּוֹי סָתִים, וּמוֹחֵיהּ סָתִים וְשָׁכִיךְ.","וְהַאי קְרוּמָא אִתְפְּסָק מִזְּעֵיר אַפִּין, וּבְגִינֵי כַּךְ מוֹחֵיהּ אִתְפְּשַׁט וְנָפִיק לִתְלָתִין וּתְרֵין שְׁבִילִין, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. מַאי טַעְמָא. מִשּׁוּם דִּקְרוּמָא אִתְפְּסָק, דְּלָא מְחַפְּיָא עַל מוֹחָא. (ועל כל פנים קרומא פסיק לתתא) וְהַיְינוּ דְּתָנֵינָן בְּרֵישׁוּמֵי אַתְוָון, תָּי\"ו רָשִׁים רִישׁוּמָא לְעַתִּיק יוֹמִין דְּלֵית דִּכְוָותֵיהּ. (דביה תליא תמים דעות שלים מכל סטרוי וסתים ושכיך ושקיט כחמר טב על דורדייה)","תָּאנָא, בְּגוּלְגַּלְתָּא דְּרֵישָׁא, תַּלְיָין אֶלֶף אַלְפִין רִבּוֹא, וְשִׁבְעַת אַלְפִין, וַחֲמֵשׁ מְאָה קוֹצֵי דְּשַׂעְרֵי, חִוָּור וְנָקִי, כְּהַאי עַמְרָא כַּד אִיהוּ נָקִי, דְּלָא אִסְתְּבַּךְ דָּא בְּדָא. דְּלָא לְאַחֲזָאָה עִרְבּוּבְיָה בְּתִקּוּנוֹי. אֶלָּא כֹּלָּא עַל בּוּרְיֵיהּ, דְּלָא נָפִיק נִימָא מִנִימָא, וְשַׂעֲרָא מִשַׂעֲרָא.","וְכָל קוֹצָא וְקוֹצָא, אִית בֵּיהּ אַרְבַּע מְאָה וָעֶשֶׂר נִימֵי דְּשַׂעְרֵי, כְּחוּשְׁבַּן קָדוֹ\"שׁ. וְכָל נִימָא וְנִימָא לָהִיט בְּאַרְבַּע מְאָה וָעֶשֶׂר עָלְמִין. וְכָל עָלְמָא וְעָלְמָא סָתִים וְגָנִיז, וְלֵית דְּיֵדָע לוֹן, בַּר אִיהוּ. וְלָהִיט לְשֶׁבַע (ס\"א לארבע) מְאָה וָעֶשֶׂר עִיבָר."],[[0,"תאנא בצניעותא דספרא","וכו׳: למדנו בצניעותא דספרא, עתיק העתיקים, סתר הסתרים, צפון הצפונים נתתקן ונזדמן, כמו זקן הזקנים עתיק העתיקים, צפון הצפונים. ובתיקוניו הוא ידוע ולא ידוע. בעל כסות הלבן, ומראה הארת פניו הלבן, הוא יושב על כסא של שביבי אש כדי להכניע אותם. \u0003בוסיטא דאנפוי\u0004 פירושו הארת הפנים לפי הענין."],[0,"","ביאור הדברים. עתה מבאר והולך העשר ספירות כח״ב תו״מ שבאצילות בעולם התקון. ונודע שב׳ פרצופין נתתקנו בספירת הכתר, שהם עתיק וא״א. וההפרש ביניהם הוא, כי הע״ס דעתיק מרוממות כולם מחכמה, והחכמה שבהן היא בבחינת \u0003סתרא דסתרין.\u0004 אבל פרצוף ב׳ של הכתר, שהוא א״א, כבר החכמה שבו בבחינת \u0003ידיע ולא ידיע,\u0004 ולפיכך על פרצוף עתיק רמזו להלן (באדרא זוטא אות ל\"ז), \u0003דא לעילא מן דא,\u0004 שהכתר הוא למעלה מחכמה, כלומר שהוא כמו נבדל מגילוי חכמה. ועל פרצוף א״א אומר, \u0003דא לגו מן דא,\u0004 שהחכמה היא בפנימיות הכתר, שהיא כבר ידיע בה מעט כנ״ל. וע״כ אין האידרא מדבר מבחינות שבפרצוף עתיק, אלא ברמז, ומתחיל ביאורו מכתר דפרצוף א״א. משום שבו מתחיל גילוי החכמה."],[0,"","וזהו שמרמז בתחילת דבריו, שכח״ב דעתיק, שהם, \u0003עתיקא דעתקין\u0004 כתר, \u0003סתרא דסתרין,\u0004 חכמה, \u0003טמיר דטמירין,\u0004 בינה, \u0003אתתקן ואזדמן\u0004 בפרצוף ב׳ דכתר, שהוא א״א \u0003כחד סבא דסבין\u0004 וכו׳. דהיינו שנגלה בה החכמה המכונה זקן, כי אין זקן אלא מי שקנה חכמה. (קידושין לב.) \u0003עתיק מעתיקין,\u0004 כתר. \u0003טמיר מטמירין\u0004 בינה. דהיינו כח״ב דא״א. ומקדים בו החכמה לכתר, שאומר תחילה סבא דסבין, ואחר כך עתיק מעתיקין. הוא מטעם שזהו כל החידוש דפרצוף הב׳ על פרצוף הא׳. שבפרצוף הא׳ מכונה החכמה \u0003סתרא דסתרין,\u0004 לרוב העלמתה שם. ובפרצוף הב׳ \u0003סבא דסבין.\u0004 ומ״ש סבא דסבין ולא כחד סבא. הוא להשמיענו שבחינת גילוי חכמה שבא״א אינו רק לאו״א הנקראים זקנים, בסוד בינה שחזרה לראש א״א ומקבלת ממנו חכמה. אבל עצמותה של חכמה דא״א אינה מגולה לתחתונים. וז״ש \u0003סבא דסבין,\u0004 כלומר שהסבין שהם או״א מקבלים ממנו הארת חכמה, אבל לא לאחרים. וז״ש \u0003ידיע ולא ידיע,\u0004 כי החכמה ידיע בו באפן שבינה תחזור בו להיות חכמה, אבל עצמותה אינה ידועה. כי ע״כ נקרא חכמה סתימאה, כי נסתמה בקרום ואינה מאירה לפרצופי אצילות."],[0,"","והטעם שנבררו ב׳ פרצופי כתר, ולא היה די בפרצוף אחד. הוא מטעם שכל הזך ביותר נברר ונתתקן תחילה. והנה כתר שה״ס אור החסדים הוא כולו רחמים ואין בו שום אחיזה לדינים ולקליפות. כי כל הצמצום היה רק על אור החכמה, ולא על אור החסדים. לפיכך נבחנת החכמה כלפי הכתר לבחינת \u0003כורסייא דשביבין.\u0004 וע״כ תחילה נתקן פרצוף הכתר שיהיה בתכלית הפרישות מאור החכמה, שהוא פרצוף הא׳ הנקרא עתיק. שהוא כולו רחמים פשוטים שאינו נותן שום גילוי לאחיזה לדינים וקליפות ואורו אינו מתעבה במשהו לעולם ואפילו יהיה בסיום כל המדרגות. אמנם כדי לתת גילוי השגה לתחתונים, שזה נמשך רק מחכמה, נתגלה הכתר שוב בפרצוף הב׳ בסוד \u0003דא לגו מן דא,\u0004 שהוא כולל בתוכו את החכמה. ונצרך לזה, כדי שהכתר ישלוט על החכמה ויכניע ויבטל כל הדינים והקליפות הנמשכים ממנו בסיום האורות."],[0,"","וז״ש, \u0003מארי דחוור כסו וחיזו בוסיטא דאנפוי,\u0004 בעל כסות הלבן, ומראה הארת הפנים הלבן, כלומר שאין אחיזה לשום דין ולשום קליפה בהתפשטות אורו, שהוא כתר, הוא \u0003יתיב על כורסייא דשביבין לאכפייא ליה\u0004 הוא קבל לתוכו החכמה, הנבחנת בערכו לכורסיא דשביבין, כדי להכניע הדינים הנמשכים מהתפשטותה. כי או״א עלאין מקבלים מחכמה זו ומשפיעים לקו שמאל דישסו״ת, וקו שמאל דישסו״ת משפיע לקו שמאל דז״א ודמלכות שנקרא \u0003אלקים.\u0004 ומשם מתפשטים \u0003ק״כ צירופי אלקים\u0004 לעולם הבריאה, ובסוף צירופי אלקים דבוקים אלהים אחרים דסטרא אחרא ויונקת מהם. ומטעם זה נבחנה החכמה כלפי הכתר \u0003לכורסיא דשביבין.\u0004"],[1,"ארבע מאה אלפי","וכו׳: ארבע מאות אלף עולמות, מתפשט הלבנונית של הגלגלתא דראש אריך אנפין, ומאור של לבנונית הזה, יורשים הצדיקים לעולם הבא ארבע מאות עולמות. ז״ש ארבע מאות שקל כסף עובר לסוחר."],[1,"","פירוש, ג׳ הויות יש בגלגלת שבכל אחת חו״ב תו״מ הויה דאו״א בימין, לצד הפנים, והויה דישסו״ת בשמאל, והויה דז״א, באמצע באחורי הראש כמ״ש לפנינו. ואלו הד׳ שבאחורי הראש שהם דז״א, נמשכים לצדיקים לעתיד לבא. ומ״ש \u0003ד׳ מאה אלפי עלמין,\u0004 היינו, משום שכל ספירה מאלו הם מאה אלף. כי מספר יחידות הוא במלכות. ועשיריות בז״א ומאות בישסו״ת, ואלפים באו״א, ורבוא בחכמה סתימאה דא״א, ומאה אלף בגלגלתא דא״א. וכיון שהם ד׳ ספירות חו״ב תו״מ שבכל אחת מאה אלף הם ד׳ מאה אלף. \u0003וחוורא דגלגלתא,\u0004 פירושו חסדים. והצדיקים שמקבלים אור החסדים הזה בעולם הבא, שהוא אמא, שספירותיה בסוד מאות, הם נבחנים רק לד׳ \u0003מאות עלמין,\u0004 וה״ס ארבע מאות שקל כסף עובר לסוחר."],[2,"בגולגלתא יתבין תליסר","וכו׳: בגלגלתא, שהוא כתר דא״א, יושבים י״ג אלף רבוא עולמות, שנוסעים על רגלים, וסומכים עליהם. ומגלגלתא הזו נוטף טל בכל יום לאותו שמבחוץ, שהוא ז״א, וממלא ראשו בכל יום שכתוב, שראשי נמלא טל."],[2,"","פירוש, כבר הזכרנו שיש ג׳ הויות בגלגלתא שהם מאו״א ומישסו״ת ומז״א. שה״ס ג׳ קוין ימין שמאל אמצע. ויש בחינת מלכות המקבלת מג׳ קוין, שה״ס עיבר חוורתא שעל הראש כמ״ש לפנינו. וג״פ חו״ב תו״מ הם י״ב ועם העיבר שעל הראש הם י״ג. וכל ספירה מהם היא בסוד אלף רבוא. כי כבר בארנו לעיל שכל ספירה שבגלגלתא היא מאה אלף כנ״ל בדבור הסמוך. וכשהע״ס דגלגלתא נכללים זמ״ז ויש בכל ספירה ע״ס נמצא שכל ספירה עולה במספר כולם עשר פעמים מאה אלף, דהיינו אלף אלפים. ומלבד זה כל קו כלול בתוכו ג׳ קוין שבכל אחד מהם ג׳ קוין, נמצא שיש בכל קו ט׳ קוין, שהם ט״פ אלף אלפים, ועם המלכות המקבלתם שהיא ג״כ אלף אלפים, הרי יש רבוא אלפים. וז״ש \u0003בגלגלתא יתבין תליסר אלפי רבוא עלמין,\u0004 כי כל קו יש בו רבוא אלפים. וכן העיבר חוורתא שעל הראש, וע״כ יש בהם י״ג אלף רבוא עלמין."],[2,"","וישיבה ה״ס הארת ו״ק, משום שנה״י שה״ס הרגלין אינם פועלים בישיבה, וכשחסר נה״י דכלים הוא חסר ג״ר דאורות. ומחמת שעתה נעשה תקון קו האמצעי גם בו״ק דבינה (כנ״ל אות י״ג) נתמעטה הארת החכמה להארת ממטה למעלה שה״ס ו״ק דחכמה. וז״ש \u0003בגלגלתא יתבין תליסר\u0004 וכו׳. שהארת החכמה המתגלה כאן בסוד י״ג שהם ג׳ הויות דהיינו ג׳ קוין, הוא רק בבחינת ישיבה. וזהו בקביעות, אמנם בשעת הנסיעה, מתגלות בהכרח גם ג״ר דחכמה, אלא שמסתלקות תיכף, וז״ש, \u0003דנטלין עלוי רגלין,\u0004 שנוסעים על רגלים, שבשעת נסיעתם מתגלים הכלים הנקראים רגלין, עם האורות דג״ר דחכמה. \u0003וסמכין עלוי,\u0004 אבל תיכף מסתלקים הג״ר ונשאר הו״ק שהם נסמכים על הג״ר שנגלו בעת הנסיעה. (כנ״ל בשלח דף ל״ט ד״ה וג') ולפיכך הם נבחנים בקביעות כיושבים, שה״ס ו״ק דחכמה. (ועי׳ להלן אות קפ״ד בהסולם)."],[2,"","ואלו אורות בי״ג חוורתא נקראים טל, כמ״ש לפנינו. והם נמשכים לז״א, וז״ש, \u0003ומהאי גלגלתא נטיף טלא לההוא דלבר,\u0004 שהוא ז״א, הנמצא בנה״י דא״א, ונה״י נחשבים שהם לבר מגופא."],[3,"ומההוא טלא דאנער","וכו׳: ומטל ההוא שאותו שמבחוץ, שהוא ז״א, מנער מראשו, מתעוררים המתים לתחיה לעולם הבא. שכתוב, כי טל אורות טלך, שטל הזה הוא אורות אור החוורתא של עתיקא, דהיינו חוורתא דגלגלתא הנקרא עתיקא. ומטל ההוא מתקיימים קדושים עליונים, והוא המן שטוחנים בשביל הצדיקים לעתיד לבא. וטל הזה נוטף לחקל תפוחין קדישין, שהוא המלכות, ז״ש ותעל שכבת \u0003הטל\u0004 והנה על פני המדבר דק מחוספס. והמראה של טל ההוא, הוא לבן, כעין זה של אבני בדולח, שנראים כל הגוונים בתוכו. ז״ש ועינו כעין הבדולח."],[3,"","פירוש. אע״פ שה״ס החוורתא שכולו לבן בלי שום גוון אחר, מ״מ כשיורד אל המלכות, נמצאים בתוכו כל ג׳ גוונים לבן אדום ירוק שה״ס ג׳ הקוין שבי״ג חוורתא. אלא כעין הבדולח, שאע״פ שכולו לבן עכ״ז יש להבחין בו כל הגוונים. שפירושו, שלהיותם בכתר, הם בטלים כולם לשליטת הכתר שהוא לבן, ואע״פ שנמצאים בו גם אדום וירוק, אין להם גילוי שליטה שמה, אלא כשיורד למלכות מתגלה מעט האדום וירוק, אבל לא לגמרי אלא כעין הבדלה. ועי׳ להלן (אות קפ״ה)."],[4,"האי גלגלתא חוורא","וכו׳: גלגלתא זו, שהיא כתר דא״א, הלבנונית שלו מאירה לי״ג עברים החקוקים סביב לה: ד׳ עברים בצד זה של הפנים, וד׳ עברים בצד זה מצד הפנים, דהיינו בימין ושמאל דגלגלתא בצד שהוא כנגד הפנים. וד׳ עברים בצד זה שמצד האחור. ועבר אחד על הגלגלתא, דהיינו באמצע בין ימין ושמאל."],[4,"","פירוש. כי יש בגלגלתא עשר ספירות כח״ב חג״ת נהי״מ. אמנם בכתר וחכמה דגלגלתא אין לנו כח לעסוק בהם ותחילת העסק הוא בבינה שלה. וע״כ כשמדבר מהארת הגלגלתא הנקראת חוורתא, הוא מדבר מבינה ולמטה, שהם ג״ר דבינה, הנקראים או״א עלאין, וו״ק דבינה הנקראים ישסו״ת, וז״א. וה״ס \u0003ם׳ ל׳ צ׳\u0004 דצלם. וה״ס חב״ד חג״ת נה״י, וה״ס ג׳ קוין, שאו״א הם קו ימין וישסו״ת הם קו שמאל, וז״א הם קו האמצעי. אשר בכל אחד מג׳ קוין יש חו״ב תו״מ, שהם ד׳ אותיות הויה, והם המכונים ד׳ עברים. שמהויה שבימין של הגלגלתא כנגד הפנים, הם ד׳ עברים חו״ב תו״מ דאו״א. ומהויה שבשמאל דגלגלתא כנגד הפנים, הם ד׳ עברים חו״ב תו״מ דישסו״ת. ומהויה שבאמצעם מאחורי הגלגלתא, הם ד׳ עברים חו״ב תו״מ דז״א. שביחד הם י״ב עברים, ועוד עבר אחד ממעל הגלגלתא, בין ימין ושמאל שלה, הוא כנגד המלכות המקבלת מכל ג׳ קוין. והם י״ג עיברי חוורתא."],[5,"ומהאי אתפשט אורכא","וכו׳: ומזה מתפשט אורך הפנים דא״א, לשלש מאות וע׳ רבוא עולמות, וזה נקרא ארך אפים. וע״כ עתיקא דעתיקא הזה, נקרא אריך אנפין, שהוא תרגומו של ארך אפים, ואותו שמבחוץ, דהיינו אותו שמלביש מטבור ולמטה דא״א, ששם נבחן שהוא מבחוץ לגוף, נקרא זעיר אנפין. שז״א הוא כנגד עתיקא הזקן קדש קדשים של הקדשים. שהוא א״א. כלומר שז״א ועתיקא צריכים להיות אחד, אלא בקטנות כשהתחתונים אינם כדאים הוא מלביש מטבור ולמטה דא״א. ובעת רצון עולה ומלביש בראש א״א (כמ״ש באד״ז אות קכ\"ג). וז״א כשהוא מסתכל לא״א, כל מה שלמטה מתתקן ופניו מתפשטים וארוכים בעת ההוא. אבל זה רק בעת רצון ולא בכל עת, כמו עתיקא, שהוא א״א."],[5,"","פירוש. כי נתבאר שספירות דגלגלתא הן כל אחת מאה אלף. וכשהע״ס נכללות זו מזו, הן כל אחת אלף אלפים (כנ״ל אות ט״ז). שהוא מאה רבוא. ונמצא שד׳ ספירות חו״ב תו״מ, שבד׳ אותיות הויה דאו״א, שבימין דגלגלתא הם ד׳ פעמים מאה רבוא, אכן במלכות שבהן אין מאה רבוא שלמים מטעם היותה חסר מלכות דבחינת עצמה, שה״ס מנעולא, וע״כ אינה אלא ז״ת חסר ג״ר, וע״כ היא רק ע׳ רבוא. באפן שחכמה בינה ז״א שהם יה״ו, הם ג׳ מאות רבוא. והמלכות שהיא ה׳ אחרונה, היא ע׳ רבוא, וביחד ש״ע רבוא. ועד״ז גם הויה השמאלית מישסו״ת שבשמאל דגלגלתא, עולים ג״כ ש״ע רבוא. ואלו ב׳ הויות שבימין ושמאל דגלגלתא מאירים בימין ושמאל של הפנים דא״א, הויה דאו״א שבימין בפן הימין, הויה דישסו״ת שבשמאל מאירה בפן השמאל, וע״כ נתפשט גם פן השמאל לש״ע רבוא. וז״ש, \u0003ומהאי אתפשט אורכא דאנפוי לתלת מאה ושבעין רבוא עלמין.\u0004 דהיינו ש״ע רבוא עלמין בפן הימין, וש״ע רבוא עלמין בפן השמאל, כמבואר."],[6,"ומהאי גלגלתא נפיק","וכו׳: ומגלגלתא הזו שהיא כתר דא״א, יוצא עיבר אחד לבן, מי״ג חוורתא דגלגלתא, אל הגלגלתא דזעיר אנפין, שהיא כתר שלו. כדי לתקן ראשו, דהיינו לתקן לו ג״ר הנקראות ראש. ומגלגלתא זו דז״א, נמשכת הארת החוורתא הזו לשאר גלגלתין שלמטה, דהיינו הכתרים שבמדרגות בי״ע שאין להם חשבון, וכל גלגלתא נותנת שכר בעד הארת החוורתא לעתיק יומין, כשהם עולים בחשבון תחת השרביט. וכנגד זה היא בקע לגלגלת שנותנים ישראל למטה, כשהם עולים בחשבון. (כמ״ש להלאה אות קפ״ח ע״ש)."],[7,"בחללא דגלגלתא קרומא","וכו׳: בחלל הגלגלתא יש קרום האויר של חכמה עלאה סתימאה, שאינו נפסק. כלומר, בתוך נקבי הגלגלתא יש מוחא דאוירא דחכמה עלאה ומתחת מוחא דאוירא יש קרום שאינו נפסק. וזה לא שכיח שיהיה נפסק, ואינו נפתח לעולם, וקרום הזה מכסה על המוח, שהוא חכמה סתימאה דא״א. ויש כאן בא״א ג׳ ראשים, חוץ מראש הא׳ שהוא עתיק, שהם גלגלתא. וחכמה עלאה סתימאה הנקרא מוחא דאוירא, שהוא בנקבי הגלגלתא, שהוא ראש הב׳. וחכמה סתימאה שלמטה בחלל הגלגלתא שהוא ראש הג׳. והקרום נמצא תחת מוחא דאוירא, וממעל לחכמה סתימאה, והוא מכסה את החכמה סתימאה שלא תאיר לחוץ מקרומא. ומשום זה נתכסתה חכמה זו בקרום הזה שאינו נפתח."],[7,"","[\u0003קרום שאינו נפסק\u0004 - עי' ד\"ה אמנם נתבאר ; ד\"ה אמנם התחלקות]"],[8,"והאי מוחא דאיהו","וכו׳: ומוח הזה שהוא חכמה סתימאה, זו דהיינו ראש הג׳ דא״א, שקט ונשקט במקומו כיין הטוב על שמריו, והיינו שאומרים שזקן דעתו סתום, ומוחו סתום ושקט."],[9,"והאי קרומא אתפסק","וכו׳: וקרום הזה נפסק מז״א, ומשום זה נתפשט מוחו ויוצא לל״ב שבילים. ז״ש, ונהר יוצא מעדן. מהו הטעם משום שנפסק הקרום ואינו מכסה על המוח. והיינו שלמדנו ברשומות האותיות. אשר \u0003תיו,\u0004 רשם רושם לעתיק יומין, שהוא א״א, שאין כמוהו."],[9,"","באור הדברים. כי כבר בארנו הצורך לב׳ פרצופי הכתר עתיק וא״א, כי להיות החכמה השורש לכל הדינים הנמשכים מקו שמאל דפרצופין תחתונים ע״כ הוצרך להתתקן הכתר תחילה בבחינת \u0003דא לעילא מן דא,\u0004 שלא יהיה בו גילוי חכמה כלל, ומתוך שבאפן זה אין בו אחיזה לשום דין שבעולם הוא יכול לתקן בהארתו שאר הפרצופין הנמשכים מחכמה ולמטה. ואחריו נתקנה החכמה בסוד \u0003דא לגו מן דא,\u0004 החכמה בפנימיות הכתר. שהכתר כבר יש לו שיכות עם החכמה שבתוכה, אלא שהיא מגבילה שלא תאיר אלא בדרכיה. וז״ס יתיב על כורסייא דשביבין לאכפייא לון (כנ״ל אות י״ד)."],[9,"","ומאותו הטעם נתתקנו ג״כ ב׳ מדרגות בבחינת \u0003דא לגו מן דא,\u0004 א׳ היא חכמה סתימאה במקומה. ב׳ היא חכמה עליונה סתימאה שבנקבי הגלגלתא, שהיא כמעט אחת עם הגלגלתא. אשר חכמה סתימאה שבמקומה נסתמה לגמרי שאין התחתונים יכולים לינק ממנו, והיא כחמרא על דורדיא כנ״ל. וכל החכמה המקובלת היא ע״י הבינה העולה לראש א״א ומקבלת מחכמה העליונה הסתימאה שהיא בנקבי הגלגלתא, שלהיותה מעורבת עם הכתר נמצאים הדינים שבה נמתקים והתחתונים יכולים לינק ממנה. ולפיכך יצאו ד׳ ראשים, א׳ עתיק, שהוא לעילא מחכמה לגמרי. וג׳ ראשים בא״א: א׳, גלגלתא דא״א. ב׳ חכמה עליונה סתימאה שבגלגלתא המעורבת בה, והיא נקראת ג״כ מוחא דאוירא. ג׳ היא חכמה סתימאה שבמקומה."],[9,"","וז״ש \u0003בחללא דגלגלתא קרומא דאוירא דחכמתא עלאה סתימאה.\u0004 דהיינו ראש הב׳ דא״א שהחכמה מעורבת בנקבי גלגלתא דא״א. \u0003והאי קרומא אתחפייא על מוחא דאיהו חכמתא סתימאה,\u0004 היינו חכמה סתימאה שבמקומה שהיא ראש הג׳ דא״א."],[9,"","והקרום המובא כאן הוא סוד הפרסא שנעשתה באמצע כל מדרגה מחמת עלית המלכות לבינה של אותו המדרגה. וכמו שיש בגוף דכל מדרגה פרסא מחזה לטבור, כך יש בראש של כל מדרגה פרסא באמצע הת״ת שבראש. כי מכתר וחכמה דראש א״א אין עסק בהם, והגלגלתא היא ג״ר דבינה דראש, דהיינו חב״ד, וחכמה עלאה שבנקבי דגלגלתא, הנקרא מוחא דאוירא, הוא ו״ק דבינה דראש דהיינו חג״ת, וחכמה סתימאה שבמקומה, נחשבת לז״א דראש, ולבחינת נהי״מ, והפרסא עומדת באמצע ת״ת דראש, ומפסקת בין חג״ת דראש לנהי״מ דראש. באפן שהפרסא נמצאת תחת מוחא דאוירא ומפסקת על מוחא סתימאה שבמקומה, שבעת בקיעת הפרסאות דהיינו בגדלות (כנ״ל, ב״א דף צ׳ ד\"ה בגין) שאז כל תחתון עולה למעלה מפרסא, נמצא אז חכמה סתימאה יוצאת מכלל הזה, שהיא אינה יכולה לעלות להתחבר עם חכמה סתימא העליונה הנקרא מוחא דאוירא. וז״ש, \u0003קרומא דאוירא דחכמתא עלאה סתימאה דלא פסק\u0004 וכו׳ כי קרום הזה משונה מכל הפרסאות, שאפילו בגדלות ג״כ אינה נבקעת."],[9,"","והטעם היא שנתתקן כך שלא תבקע הפרסא. היא כמ״ש לעיל שאין התחתונים יכולים לקבל חכמה מחכמה סתימאה שבמקומה, אלא מחכמה עליונה המעורבת בכתר. ע״ש, ואם היתה עולה חכמה סתימאה אל חכמה עליונה דכתר בעת בקיעת הפרסאות, היתה הבינה העולה לראש א״א מקבלת מחכמה סתימאה שבמקומה. ולפיכך אין הקרום שלה נפתח לעולם. וז״ש \u0003ובגיני כך אתכסיא האי חכמתא בההוא קרומא דלא אתפתחא.\u0004 אבל בז״א למטה, אותה הפרסה המפסקת בין ישסו״ת לז״א המונעת את המוח שלו מלינק מישסו״ת, הנה בעת גדלות נבקעת הפרסה וז״א עולה למקום ישסו״ת והמוח שלו מקבל מישסו״ת. וז״ש, \u0003והאי קרומא אתפסק מז״א, ובגיני כך מוחיה אתפשט ונפיק לל״ב שבילין,\u0004 דהיינו שמקבל מישסו״ת ל״ב נתיבות החכמה."],[9,"","ונתבאר בפתיחה לחכמת הקבלה (אות י״ט), ששיעור קומה של כל המדרגה תלוי בעבי המסך שעליו מכה אור העליון. ונתבאר שם, שהעבי היותר גדול שבמסך, מוציא שיעור קומה יותר גדול, עש״ה. וז״ש, \u0003תיו רשים רישומא לעתיק יומין, דלית דכוותיה.\u0004 תיו, היינו המסך, הוא רושם רשימת קומת של עתיק יומין, שהוא עתיק, שאין כמוהו. כי המסך דעתיק הוא מסך דבחי״ד המוציא קומת כתר, שאין כמוהו, דהיינו כגובה קומתו, בכל האצילות. כי המסך דא״א הוא בחי״ג, ודאו״א וישסו״ת הוא בחי״ב, ודז״א בחי״א (כמ״ש שם) גם יש לפרש שעתיק יומין הוא א״א, שהמסך שלו הוא בחי״ג, ומה שאומר דלית דכותיה. היינו ממנו ולמטה, ועתיק שלמעלה מא״א אינו בחשבון פרצופי אצילות."],[10,"תאנא בגלגלתא דרישא","וכו׳: למדנו, בגלגלת של הראש, דהיינו בכתר דא״א, תלויות אלף אלפים רבוא ושבעת אלפים וחמש מאות קבוצות שערות. לבן ונקי כמו צמר הזה שהוא נקי, שאינן מסובכות זו בזו, שלא להראות עירוב בתקוניו, אלא הכל הוא על מכונו שאינה יוצאת נימא מנימא ושערא משערא."],[10,"","ביאור הדברים. השערות ה״ס דינים מלשון סערות. ומקורם שה״ס כלים ואו״ח שהיו מלבישים לג״ר דחכמה, ובתקון קרומא דאוירא נסתלקו הג״ר דחכמה, והאו״ח שהלבישם יצאו מראש בסוד סערות ופסולת. (כנ״ל בספד״צ דף י״ב ד״ה ביאור). אמנם דינים אלו הם הכנה לכל האורות והמוחין של בי״ע. והטעם הוא משום שהם באים ונמשכים מקרומא דאוירא שהוא גרם יציאתן מראש, שה״ס הפרסא שבראש, שפירושה, עירוב המלכות בבינה, ואח״כ, בסוד התקונים. מקבלת המלכות צורת בינה באופן שדינים דמלכות נמתקים ויוצאים כמו מבינה, ומי שמקבל דינים ההם. נמשכת לו הקטנות מבינה, ואחר שמשיג הקטנות מבינה ראוי הוא לקבל גם הגדלות מבינה. ולולא הקטנות דבינה, הבא מעירוב הזה שבפרסא, לא היו זו״ן דאצילות וכל המדרגות שבבי״ע ראוים לקבל מאור העליון, (כמ״ש בב״א דף ז׳ ד״ה וכבר) וז״ס שאמרו, בני חיי ומזוני לאו בזכותא תליא מילתא אלא במזלא תלייא מילתא, שה״ס שערות דיקנא המכונים מזלא. ושערות הראש ושערות דיקנא הם מדרגה אחת, אלא שהמדרגה נבקעת ע״י כח הקרומא דאוירא שהוא מקורה, אשר כתר וחכמה וחצי בינה נשאר בהמדרגה, וחצי בינה ותו״מ נופלים ממנה ויוצאים לבר מראש, ונדבקים בלחי התחתון בסוד שערות דיקנא. ולפי שנפלו ממדרגת שערות ראש, ע״כ יש בהם יותר דינים, בסוד ששערות דיקנא קשישי, וכל זה הוא בבחינת הכלים של השערות. אבל האורות שבהם נמשכים מחכמה סתימאה, כי להיותה נסתמת בקרום הזה דאוירא, ע״כ בשעת גדלות שהקרום נזדכך הארתה בוקעת בקרומא דאוירא, וממנה באה לשערות ודרך השערות באה הארתה לפרצופים התחתונים. וע״י אורות אלו נעשו י״ג נימין דשערי, כלומר שמתחלקים להארת חכמה בינה דעת כמ״ש לפנינו. אמנם הכלים הם מקרומא דאוירא, ובהם ג׳ כלים, שהם מחצית מדרגה העליונה דשערות, שנקראות שערות ראש, דהיינו כתר וחכמה וחצי בינה."],[10,"","וז״ש \u0003בגולגלתא דרישא תליין אלף אלפין רבוא, ושבעת אלפין, וחמש מאה קוצי דשערי,\u0004 כי ספירות הכתר דשערות מתחברות כל כך בגלגלתא עד שהם כמספר הספירות דגלגלתא, שהיא \u0003אלף אלפים\u0004 (כנ״ל באות ט״ז) מה שאין כן החכמה דשערות, כבר נפלה הרבה ממדרגות הגלגלתא, כי עליה שולטת קרומא דאוירא, שממעטה מג״ר, ועל כן אינה אלא \u0003ז׳ אלפים,\u0004 בחוסר ג׳ ראשונות. והם מכונים אלפים כי ספירות החכמה היא במספר אלפים. והבינה דשערות אינה אלא ה׳ מאות, דהיינו רק ה׳ ספירות חג״ת נ״ה, כי בינה עד הוד אתפשטותה, ולא יותר, וספירותיה הן במספר מאות. ומה שאומר אלף אלפין \u0003רבוא,\u0004 היא מטעם ההתכללות שבהם ממלכות דמנעולא, שהארתה למעלה היא בסוד רבוא."],[10,"","ואע״פ שאמרנו, שהשערות הם דינים נמשכים מפרסא, היינו בהתפשטותם לפרצופין התחתונים, אבל בהיותם נשרשים כאן הן כולן חסדים ורחמים. מטעם כי כאן אינן נמצאות השערות בפעולת הדינים שבהן, אלא הן כאן בבחינות התוצאות של פעולת הדינים שלמטה, שהתוצאות שלהם הן בני חיי ומזוני וכל המוחין הגדולים, ואלו התוצאות נדבקות כאן בגלגלתא דא״א, ומבחינה זו אנו מכנים אותן שערות, וע״כ נבחנות שהן לבנות ונקיות, וז״ש \u0003חוור ונקי בהאי עמרא, כך איהו נקי דלא אסתבך דא בדא.\u0004 וכו׳, כי ד׳ מיני דינים יש בשערות אלו, שהם באים מתוך העירוב של בינה ומלכות זו בזו, והן בחינות בינה ומלכות בבינה, ובחינות בינה ומלכות במלכות. אשר ג׳ בחינות הראשונות הן ממותקות ברחמים, והד׳ שהיא מלכות שבמלכות היא בחינת מלכות דמדת הדין שלא נמתקה. ואומר הזהר שד׳ מיני דינים אלו אע״פ שנתערבו הם מסתדרים כאן כל אחת למינה, ואינם מסתבכים אחת בחברתה. ולמשל אם היתה מתגלה המלכות דמדת הדין בעת שליטת מלכות הממותקת, היו כל האורות מסתלקים. (כנ״ל ויצא י״ג ד״ה סתרא) וז״ש, \u0003דלא לאחזאה ערבוביא בתקונוי.\u0004 שמחמת ערבוביא הזו היו מסתלקים האורות. וכן אע״פ שמלכות הבלתי נמתקת היא מקור של כל המלכיות הנמתקות, מ״מ לא ניכר זה, אלא, \u0003דלא נפיק נימא מנימא ושערא משערא,\u0004 וכל אחת שולטת בפני עצמה בלי שום קשר עם חברתה."],[11,"וכל קוצא וקוצא","וכו׳: וכל קבוצה וקבוצה של השערות, יש בו ארבע מאה ועשר אגודות של שערות כחשבון קדוש. וכל נימא ונימא לוהטת בת״י עולמות, כחשבון קדוש. שכל עולם ועולם סתום וגנוז ואין מי שידע אותו, חוץ הוא עצמו. ולוהט לארבע מאה ועשרה עיבר שהם ג״כ כחשבון קדוש. ואלו הם סוד ג׳ קדושות, שאומרים, קדוש קדוש קדוש."],[11,"","פירוש. שכל אחת מן קבוצות השערות כלולה מד׳ אותיות שהם חו״ב תו״מ, והמלכות שבהם כלולה משתים, מהממותקת, ומהבלתי נמתקת, כנ״ל. ואלו חו״ב תו״מ להיותן מבינה, ה״ס ארבע מאות שספירות הבינה הן במספר מאות. והמלכות הבלתי נמתקת הנתוספת עליהם שהיא בחשבון עשרה, ע״כ הם ארבע מאות ועשרה נימין היוצאות מכל קוץ וקוץ. וז״ש, \u0003וכל קוצא וקוצא אית ביה ת״י נימי דשערי כחושבן קדוש\u0004 וחושב כאן ג׳ בחינות שהם ת״י נימין ות״י עלמין ות״י עיברים. שהם כנגד ג״פ קדוש, שיש באו״א וישסו״ת וזו״ן."]],[]],[["וּבְכָל נִימָא וְנִימָא, אִית מַבּוּעָ דְּנָפִק מִמּוֹחָא סְתִימָאָה, (דבתר כותלא) וְנָהִיר וְנָגִיד בְּהַהוּא נִימָא, לְנִימִין דִּזְעֵיר אַנְפִּין. וּמֵהַאי מִתְקַּן (ס\"א מתזן) מוֹחֵיהּ. וּכְדֵין, נָגִיד הַהוּא מוֹחָא, לִתְלָּתִין וּתְרֵין שְׁבִילִין.","וְכָל קוֹצָא וְקוֹצָא מִתְלַהֲטָן, וְתַלְיָין. מִתְתַּקְּנָן בְּתִקּוּנָא יָאֶה, בְּתִקּוּנָא שַׁפִּירָא. מְחַפְּיָין עַל גּוּלְגַּלְתָּא. מִתְתַּקְנֵי קוֹצֵי דְּנִימִין, מֵהַאי סִטְרָא, וּמֵהַאי סִטְרָא, עַל גּוּלְגַּלְתָּא. וְתָאנָא, כָּל נִימָא וְנִימָא, אִקְרֵי (ס\"א איהי) מְשִׁיכָא מִמַּבּוּעַ (ס\"א ממבועין) (ס\"א ואינון מבועין) סְתִימִין, דְּנָפְקִין מִמּוֹחָא סְתִימָאָה.","וְתָאנָא, מִשַׂעְרוֹי דְּבַּר נָשׁ, אִשְׁתְּמוֹדַע מַאי הוּא, אִי דִּינָא אִי רַחֲמֵי. מִכַּד עַבְרִין עֲלוֹי אַרְבְּעִין שְׁנִין. וַאֲפִילּוּ כַּד אִיהוּ עוּלֶם, בְּשַׂעְרֵיהּ בְּתִיקוּנֵיהּ (ס\"א בדיוקניה) (ס\"א בדיקניה) וּבִגְבִינֵי עֵינוֹי.","קוֹצִין דְּשַׂעֲרֵי, תַּלְיָין בְּתִקּוּנֵי נַקְיֵי כַּעֲמַר נְקֵא עַד כִּתְפּוֹי. עַד כִּתְפּוֹי סַלְּקָא דַּעְתָּךְ. אֶלָּא עַד רֵישֵׁי דְּכִתְפּוֹי, דְּלָא אִתְחֲזֵי קוּדְלָא. מִשּׁוּם דִּכְתִּיב, (ירמיהו ב׳:כ״ז) כִּי פָנוּ אֵלַי עוֹרֶף וְלֹא פָנִים. וְשַׂעֲרָא סָלִיק אֲבַתְרוֹי דְּאוּדְנִין, דְּלָא לְחַפְּיָיא עֲלוֹי, דִּכְתִּיב לִהְיוֹת אָזְנֶיךָ פְּקוּחוֹת.","שַׂעֲרָא דְּנָפִיק מִבָּתַר אוּדְנוֹי, כּוּלֵיהּ בְּשִׁקּוּלָא. לָא נָפִיק דָּא מִן דָּא, תִּקּוּנָא שְׁלִים. תִּקּוּנָא יָאֶה. תִּקּוּנָא שַׁפִּירָא. תָּאִיב לְמֵחמֵי. תִּיאוּבְתָּא וְחֶדְוָותָא דְּצַדִּיקַיָּיא, דְּאִינּוּן בִּזְעֵיר אַפִּין, לְמֵחֱמֵי וּלְאִתְדַּבְּקָא בְּתִקּוּנוֹי. דְּעַתִּיקָא סְתִימָאָה דְּכֹלָּא.","י\"ג נִימִין דְּשַׂעְרִין, קַיְימֵי מֵהַאי סִטְרָא, וּמֵהַאי סִטְרָא דְּגוּלְגַּלְתָּא, לָקֳבֵיל אַנְפּוֹי. וּבְאִינּוּן שַׁרְיָין שַׂעְרֵי לְאִתְפַּלְגָא. לֵית שְׂמָאלָא בְּהַאי עַתִּיקָא סְתִימָאָה, כֹּלָּא יְמִינָא. אִתְחֲזֵי וְלָא אִתְחֲזֵי. סָתִים וְלָא סָתִים. וְהַאי בְּתִקּוּנֵיהּ, כָּל שֶׁכֵּן בֵּיהּ. (שמות פ\"ד ע\"ב).","וְעַל הַאי, תָּאִיבוּ בְּנֵי יִשְׂרָאֵל לְצָרְפָא בְּלִבְּהוֹן, דִּכְתִּיב, (שמות י״ז:ז׳) הֲיֵשׁ יְיָ בְּקִרְבֵּנוּ אִם אָיִן. בֵּין זְעֵיר אַנְפִּין דְּאִקְרֵי יְיָ, וּבֵין אָרִיךְ אַנְפִּין דְּאִקְרֵי אַיִ\"ן. אֲמַאי אִתְעֲנָשׁוּ. מִשּׁוּם דְּלָא עַבְדוּ בַּחֲבִיבוּתָא, אֶלָּא בְּנִסְיוֹנָא. דִּכְתִּיב, (שמות י״ז:ז׳) וְעַל נַסּוֹתָם אֶת יְיָ לֵאמֹר הֲיֵשׁ יְיָ בְּקִרְבֵּנוּ אִם אָיִן.","בְּפַלְגוּתָא דְּשַׂעְרֵי, אָזִיל חַד אָרְחָא דְּנָהִיר לְמָאתָן וְשִׁבְעִין עָלְמִין. וּמִנֵּיהּ נָהִיר אָרְחָא דִּזְעֵיר אַנְפִּין, דִּנְהִירִין בֵּיהּ צַדִּיקַיָּיא לְעָלְמָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, (משלי ד׳:י״ח) וְאוֹרַח צַדִּיקִים כְּאוֹר נוֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. וּמִן הַהוּא אָרְחָא אִתְפָּרְשָׁא לְשִׁית מֵאָה וּתְלֵיסָר אוֹרְחִין דְּאוֹרַיְיתָא, דְּפָלִיג בִּזְעֵיר אַפִּין. דִּכְתִּיב בֵּיהּ (תהילים כ״ה:י׳) כָּל אָרְחוֹת יְיָ חֶסֶד וְאֱמֶת וְגוֹ'.","מִצְחָא דְגֻלְגַּלְתָּא רַעֲוָא דְרַעֲוִין, רְעוּתָא דִזְעֵיר אַנְפִּין לָקָבְלֵי הַהוּא רְעוּתָא (נ\"א מצחא דגולגלתא, רצון אקרי. דהא רעוא דרעוין אתגלי בההוא מצחא לקבל דא לתתא. כתיב) דִּכְתִּיב (שמות כ״ח:ל״ח) וְהָיָה עַל מִצְחוֹ תָּמִיד לְרָצוֹן וְגוֹ' וְהַהוּא מִצְחָא דְּאִקְרֵי רָצוֹן, הוּא גִּלּוּיָיא דְּכָל רֵישָׁא וְגוּלְגַּלְתָּא, דְּמִתְכַּסְּיָיא בְּאַרְבַּע מְאָה וְעֶשְׂרִין (נ\"א ועשר) עָלְמִין.","וְכַד אִתְגַּלְיָא, אִתְקַבְּלָא צְלוֹתְהוֹן דְּיִשְׂרָאֵל. אֵימָתַי אִתְגַּלְיָא. שָׁתִיק רַבִּי שִׁמְעוֹן. שָׁאַל תִּנְיָינוּת אֵימָתַי. אָמַר רַבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרֵיהּ, אֵימָתַי אִתְגַּלְיָא. אָמַר לֵיהּ בְּשַׁעֲתָא דִּצְלוֹתָא (רפ\"ח) דְּמִנְחָה דְּשַׁבְּתָא. אָמַר לֵיהּ מַאי טַעְמָא. אָמַר לֵיהּ, מִשּׁוּם דְּהַהִיא שַׁעֲתָא בְּיוֹמֵי דְּחוֹל, תַּלְיָא דִּינָא לְתַתָּא בִּזְעֵיר אַפִּין. וּבְשַׁבְּתָא אִתְגַּלְיָא מִצְחָא דְּאִתְקְרֵי רָצוֹן. בְּהַהִיא שַׁעֲתָא אִשְׁתְּכִיךְ רוּגְזָא. וְאִשְׁתְּכַח רַעֲוָא, וּמִתְקַבְּלָא צְלוֹתָא. הֲדָא הוּא דִכְתִיב, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ עֵת רָצוֹן. וְעֵת רָצוֹן מֵעַתִּיק יוֹמִין, לְגַלָּאָה מִצְחָא. וּבְגִין כָּךְ אִתְתָּקַּן הַאי קְרָא, לְמֵימְרֵיהּ בִּצְלוֹתָא דְּמִנְחָה בְּשַׁבְּתָא. אָמַר רַבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרֵיהּ, בְּרִיךְ בְּרִי לְעַתִּיק יוֹמִין, רַעֲוָא דְּמִצְחָא תִּשְׁכַּח בְּשַׁעֲתָא דְּתִצְטְרִיךְ לֵיהּ.","תָּא חֲזֵי, בִּשְׁאָר (ס\"א בשעתא) דִּלְתַתָּא, כַּד אִתְגְּלֵי מִצְחָא אִשְׁתְּכַח חוּצְפָּא, הֲדָא הוּא דִכְתִיב (תא חזי בשאר דלתתא כד אתגלי מצחא דינא אתער ואשתכח ואתעביד מצחא דאשגחותא לחייבי עלמא לאינון דלא מתכספי בעובדייהו כמה דאת אמר) (ירמיהו ג׳:ג׳) וּמֵצַח (קל\"ו) אִשָּׁה זוֹנָה הָיָה לָךְ מֵאַנְתְּ הִכָּלֵם. וְהָכָא כַּד אִתְגְּלֵי מִצְחָא, תִּיּוּבְתָּא (ס\"א חביבותא) וְרַעֲוָא שְׁלִים אִשְׁתְּכַח, וְכָל רוּגְזִין אִשְׁתְּכָכוּ וּמִתְכַּפְיָין קַמֵּיהּ.","מֵהַאי מִצְחָא (ס\"א דלתתא), נַהֲרִין אַרְבַּע מְאָה בָּתֵּי דִּינִין. כַּד אִתְגַּלְיָיא הַאי עֵת רָצוֹן, כֻּלְּהוּ מִשְׁתַּכְכִין קַמֵּיהּ, הֲדָא הוּא דִּכְתִּיב, (דניאל ז׳:י׳) דִּינָא יְתִיב. (כלומר יתיב באתריה ודינא לא אתעביד) וְתָאנָא, שַׂעֲרָא לָא קָאִים בְּהַאי אֲתָר, מִשּׁוּם דְּמִתְגַּלְיָיא, וְלָא אִתְכַּסְּיָיא. אִתְגַּלְיָא, דְּיִסְתַּכְּלוּן מָארֵי דְּדִינָא, וְיִשְׁתַּכְּכוּן. וְלָא אִתְעֲבִידוּ."],[[0,"ובכל נימא ונימא","וכו׳: ובכל נימא ונימא יש מבוע היוצא ממוחא סתימאה. שהוא ראש הג׳ דא״א, ומאיר ונמשך מנימין האלו לנימין דז״א, ומאלו מתתקן מוחו של ז״א. כלומר שמקבל ג״ר. ואז נמשך מוח ז״א לל״ב שבילי החכמה."],[0,"","פירוש. עצם השערות, דהיינו בחינת הכלים, נמשכות מקרומא דאוירא (כנ״ל באות כ״ד) אמנם האור שבהם מקבלים ממו״ס, שבהיותו מוקף וסתום בקרומא דאוירא ההוא כנ״ל, הנה בעת גדלות שהקרום מזדכך (כנ״ל בספרא דצניעותא אות ו׳) בוקע אור חכמה סתימא דרך הקרומא דאוירא וממלא השערות מאורו. ומהם נמשך ג״ר לז״א דרך שערותיו, וז״ש \u0003ומהאי מתקן מוחיה\u0004 וכו׳."],[1,"וכל קוצא וקוצא","וכו׳: וכל קוץ וקוץ, דהיינו בכל קבוצה וקבוצה של השערות מתלהטות ותלויות, ומתתקנות בתקון נאה בתקון יפה, ומכסות על הגלגלתא. וקבוצות של נימין מתתקנות מצד זה ומצד זה על הגלגלתא. דהיינו בימין ושמאל ואמצע. ולמדנו כל אגודה ואגודה של השערות היא המשכה של מבועים הסתומים היוצאים ממוחא סתימאה. שהוא ראש הג׳ דא״א. כמ״ש לעיל."],[2,"ותאנא משערוי דבר נש","וכו׳: ולמדנו. משערותיו של אדם ניכר מה הוא, אם הוא דין או רחמים. והוא אחר שעברו עליו ארבעים שנה. ואפילו כשהוא צעיר ניכר ג״כ בשערותיו ובצורתו ובגבות עיניו."],[3,"קוצין דשערי תליין","וכו׳: קבוצות השער תלויות בתקונן עד כתפיו נקיות כצמר נקי. היעלה על דעתך עד כתפיו. אלא עד ראשי כתפיו, שלא נראה העורף. משום שכתוב, כי פנו אלי עורף ולא פנים. והשערות עולות מאחורי האזנים, כדי שלא לכסות האזנים. שכתוב, להיות אזנך פקוחות."],[3,"","פירוש. בעת שישראל חוטאים וגורמים פירוד בין ימין לשמאל של מעלה, אז נבחן שהחזירו עורף שלהם להקב״ה. מפני שגורמים גם למעלה שלא יאיר להם הפנים אלא העורף, שהוא בחינת אחורים ודינים, ונמצאים יונקים מן העורף שלמעלה. שעי״ז מגבירים השמאל על הימין. וע״י השפעת השערות דא״א מתכסה העורף באופן שגם מן העורף לא יוכלו לינק, ואז מוכרחים לחזור בתשובה ולהמשיך הפנים. וקבלת התפלה של התחתונים מכונה אזנים. וז״ש \u0003ושערוי סליק אבתרוי דאודנין\u0004 וכו׳. כדי שהדינים שבשערות לא יעכבו קבלת התפלה שז״ס \u0003להיות אזנך פקוחות.\u0004 וענין הסתלקות השער לאחורי אזנים עי׳ בספרא דצניעותא (דף י״ט ד״ה תקון)."],[4,"שערא דנפיק מבתר","וכו׳: השערות היוצאות לאחורי אזניו כולן הן בשוה אינן יוצאות זה מזה (כמ״ש לעיל אות כ״ד) והוא תקון שלם, תקון נאה, תקון יפה, נחמד למראה. התשוקה והשמחה של הצדיקים, שהם בז״א, הוא לראות ולהתדבק בתקוניו של עתיק הסתום מכל. שהוא א״א."],[5,"י״ג נימין דשערין","וכו׳: י״ג נימין, דהיינו אגודות שערות עומדות מצד זה ומצד זה של הגלגלת, שהוא הכתר דא״א, כנגד פניו. ובהן מתחילות השערות להתחלק. אין בחינת שמאל בעתיק הסתום הזה, שהוא א״א. הוא כלו ימין. נראה ואינו נראה סתום ואינו סתום, וזה הוא בתקוניו, כל שכן בו עצמו."],[5,"","פירוש. כמו שיש י״ג חוורתא, שהם בחינות גלגלתא, כן יש י״ג נימין דשערי שהן בחינות קרומא דאוירא, כנ״ל. וענינם שוה זה לזה, שה״ס או״א וישסו״ת בימין ושמאל של הפנים שה״ס ב׳ הויות במילוי ע״ב ס״ג. ובחינת ז״א באמצעם מאחוריהם, שה״ס הויה דמ״ה. והם בחינת ג׳ קוין. ועם המלכות המקבלתם הם י״ג (כנ״ל אות י״ח)."],[6,"ועל האי תאיבו","וכו׳: ועליו, חשקו בני ישראל לצרף ולהבחין בלבם, שכתוב, היש ה׳ בקרבנו אם \u0003אין.\u0004 היינו בין ז״א שנקרא ה׳ ובין א״א, שנקרא \u0003אין.\u0004 שואל, א״כ, למה נענשו. ומשיב, משום שלא עשו זה מתוך אהבה אלא בנסיון. שכתוב, ועל נסותם את ה׳ לאמר היש ה׳ בקרבנו אם אין."],[6,"","פירוש. שכתוב, ויקרא שם המקום מסה ומריבה על ריב בני ישראל ועל נסותם את ה׳ וגו׳. משמע שמלבד הריב שהיה להם עם משה על המים, שמטעם זה נקרא המקום מריבה, חטאו עוד על נסותם את ה׳ לאמר היש ה׳ בקרבנו אם אין. שמטעם זה נענשו במלחמת עמלק. ומפרש, שהחטא היה שבני ישראל רצו לדעת אם מדרגת ז״א שוכן בלבבם או מדרגת א״א. והחטא היה מפני שנסו את ה׳. ולא היה מטעם אהבתם את ה׳. וההבדל ביניהם דק מאד, כי סוף סוף הוא אותו הדבר, אלא ההבדל הוא בהמטרה שגורמת לזה, אם להרבות האהבה היתה המטרה, או לנסות לדעת, היא המטרה. ויש להסביר זה בדרך משל, באדם המסתכל ביופי של אשה לאחר שהיא אשתו, או מטרם שנשאה. כי לאחר הנשואין אינו מסתכל בה להבחין אם לקרבה או לרחקה, אלא כדי להרבות אהבה. וע״כ אין הסתכלותו עליה לטרח ואדרבה נהנית מאד מזה. משא״כ מטרם שנשאה, אם מסתכל עליה, אז היא אינה סובלת ומצטערת מהסתכלותו, משום שחוששת אולי יתדמה לו איזה חסרון, וידחה אותה. וע״כ מרגשת הסתכלותו לגסות ולא תוכל לסבול. ודו״ק."],[7,"בפלגותא דשערי אזיל","וכו׳: בהתחלקות השער שעל הגלגלתא לימין ושמאל, הולך ביניהם דרך אחד המאיר לר״ע עולמות. וממנו, מאיר הארח שבמקום התחלקות השער שעל גלגלתא דז״א, שהצדיקים מאירים ממנו לעולם הבא. ז״ש, וארח צדיקים כאור נגה הולך ואור עד נכון היום. ומארח הזה שבז״א, מתחלק לשש מאות ושלשה עשר דרכים של התורה המתחלקים בז״א. דהיינו תרי״ג מצות. שכתוב בו כל ארחות ה׳ חסד ואמת."],[7,"","פירוש. השערות הם דינים כנ״ל. והדינים מתחלקים לימין ושמאל, שהדינים דנוקבא הבאים מכח הצמצום והמסך שבמלכות, הם בחינות ימין. והדינים דדכורא, הנמשכים מקו שמאל, הם בחינות שמאל, (עי׳ תזריע אות קנ״ב) ואלו ב׳ מיני דינים הם השורשים לכל מיני דינים ועונשים שבעולם. וכשהצדיקים מסתכלים באלו הדינים, יודעים ומכירים הדרך שהוא באמצעם, באפן שההולך בו אינו נכשל לא בדינים דימין ולא בדינים דשמאל. ודרך הזה נקרא \u0003אורחא דפלגותא דשערי.\u0004 וכבר ידעת שאלו השערות דא״א אינם דינים, כי אינם דינים רק בז״א, ולא בא״א שהוא כולו רחמים וכולו ימין. אמנם שם הם תוצאות הנפעלות בסוף הכל מאותם הדינים. בסו״ה לא ידח ממנו נדח. ולפיכך, כיון שהם תוצאות האורות הנפעלות משערות, דז״א, הן מאירות וממתיקות את השערות דז״א. וז״ש \u0003ומניה נהיר ארחא דז״א.\u0004 ואע״פ שהארח בין ימין ושמאל דשערות דז״א אינו נקי כל כך כמו בא״א, מ״מ מקבל הארתו מאורחא דפלגותא דשערי דא״א. שבו בא״א מאיר אורח הזה \u0003למאתן ושבעין עלמין.\u0004 ומרמז כאן לאותיות \u0003רע\u0004 שהם מספר מאתן ושבעין, כלומר שכל ה \u0003רע\u0004 הנמצא בעולמות מתמתקים ומקבלים תקונם מאורח דפלגותא דשערי שבא״א. וענין אורחא דפלגותא דשערי שבז״א, וסו״ה כל ארחות ה׳ חסד ואמת נתבאר לעיל בספרא דצניעותא (דף י״ט ד״ה תקון הג׳ ע״ש)."],[8,"מצחא דגולגלתא רצון","וכו׳: המצח שבגלגלת דא״א, נקרא רצון. כי רצון הרצונות נגלה במצח ההוא. כנגד זה למטה כתוב, והיה על מצחו תמיד לרצון וגו׳. ומצח הזה שנקרא רצון, הוא הגילוי האורות של כל הראש והגלגלתא, המתכסים בארבע מאות ועשר עולמות."],[8,"","פירוש. הגולגלתא מתחלק לב׳ ראשים גולגלתא ואוירא. (כנ״ל אות כ״ג) שה״ס \u0003ם׳ ל׳\u0004 דצלם. דהיינו בחינת או״א וישסו״ת שב \u0003ם׳ דצלם אין הי׳\u0004 יוצאת מאויר לעולם כמו באו״א. וה״ס ראש הנק׳ גלגלתא. ובמוחא דאוירא שהוא ראש הב׳. וסוד \u0003ל׳\u0004 דצלם שהיא בחינת ישסו״ת, בו יוצא הי׳ מאויר בשעת גדלות. (כנ״ל בספרא דצניעותא דף ד׳ ד״ה פירוש ע״ש) וכנגדם מתחלקים ג״כ הכלים דחצוניות ראש דא״א ל \u0003ם׳\u0004 ו \u0003ל׳\u0004 אשר בחינת ה \u0003ם׳\u0004 שבחיצוניות הראש, הוא מקום השערות שמקורם מקרומא דאוירא, דהיינו \u0003י׳\u0004 שנכנסה באור, וכיון שה \u0003י׳\u0004 אינה יוצאת עוד משם ע״כ נקבע שם מקום השערות בקביעות. ובחינת ה \u0003ל׳\u0004 שבחיצוניות הראש הוא ממצח דא״א ולמטה, כי מחמת שה \u0003י׳\u0004 יוצאת שם מאויר, אין שם מקום לצמיחת שערות בקביעות. אלא בשעה שאין \u0003עת רצון,\u0004 נמצאים שערות הגלגלתא יורדים ומכסים \u0003המצח,\u0004 ובעת רצון מסתלקים השערות מלכסות המצח, והמצח מתגלה. ואז מתגלים שם האורות המכוסים ב \u0003ם׳\u0004 דצלם שה״ס הגלגלתא וז״ש, \u0003וההוא מצחא דאקרי רצון הוא גילויא דכל רישא וגלגלתא,\u0004 כי כל האורות המכוסים בגלגלתא, שה״ס \u0003ם׳\u0004 דצלם, מתגלים במצחא, שה״ס \u0003ל׳\u0004 דצלם."],[8,"","ומספר ארבע מאות ועשר רומז על סוד הכיסוי, שסוד העשר העודפות על ארבע מאות ה״ס המלכות הבלתי ממותקת שנתערבה בבינה, בסוד הי׳ שנכנסה באור. וע״כ יש חו״ב תו״מ עם מלכות ממותקת ועשרה נוספות ממלכות הבלתי נמתקת. שמטעם המצא מלכות הזו בקביעות ב \u0003ם׳\u0004 דצלם ע״כ האורות דגלגלתא, שהיא סוד \u0003ם׳,\u0004 מכוסים ונעלמים. וז״ש \u0003גלוייא דכל רישא וגלגלתא דמתכסייא בארבע מאה ועשר עלמין.\u0004 שה״ס חו״ב תו״מ, שכל אחת מאה, ומלכות הבלתי נמתקת הקבועה שמה שה״ס עשרה. כמ״ש לעיל (באות כ״ה) אמנם במצחא מתגלים."],[9,"וכד אתגליא אתקבלא","וכו׳: וכשנתגלה המצח, מתקבלות תפלות ישראל. מתי מתגלה. שתק ר״ש כדי שיענה מי מהחברים. שאל פעם שניה מתי. ולא ענו לו. א״ר שמעון לד׳ אלעזר בנו, מתי מתגלה המצח. אמר לו, בשעת תפלת המנחה של שבת. אמר לו ר״ש, מהו הטעם שמתגלה המצח בשעת תפלת מנחת שבת. אמר לו ר״א, משום שבשעה הזאת בימות החול, תלוי הדין למטה בז״א, כי יצחק, שה״ס קו שמאל דז״א תקן תפלת המנחה, ומהארת החכמה שבשמאל נמשכים דינים (כנ״ל צו אות קי״ד) ובשבת הוא להיפך, כי מתגלה המצח דא״א שנקרא רצון בשעה ההיא נשקט הרוגז, ונמצא הרצון, והתפלה מתקבלת. ז״ש ואני תפלתי לך ה׳ עת רצון. כי עת רצון הוא מעתיק יומין לגלות המצח. ומשום זה נתתקן מקרא הזה לאמרו בתפלת מנחת שבת. אר״ש לר״א בנו ברוך תהיה בני לעתיק יומין. ותמצא רצון המצח בשעה שתצטרך לו."],[10,"ת״ח בשאר דלתתא","וכו׳: בוא וראה, בשאר של מטה, כשנגלה המצח נמצא עזות, ז״ש ומצח אשה זונה היה לך מאנת הכלם. וכאן בא״א, כשנגלה המצח, נמצא האהבה והרצון השלם וכל מיני רוגז נשקטים ונכנעים לפניו."],[11,"מהאי מצחא דלתתא","וכו׳: ממצח הזה שלמטה מאירים ארבע מאות בתי דינים. שה״ס חו\"ב תו״מ, הנמשכים מקו שמאל דאמא לז״א, שכל אחת במספר מאה. וכשנתגלה עת רצון הזה במצח א״א, כולם נשקטים לפניו. ז״ש, דינא יתיב. שפירושו שנשאר במקומו והדין אינו נעשה. ולמדנו שלא נמצא שערות במקום הזה, במצח, משום שמתגלה, שיוצאת ה \u0003י׳\u0004 מאויר (כנ״ל אות ל״ג) ואינו מתכסה, כמו בגלגלתא המלאה שערות. הוא נתגלה, כדי שיסתכלו בעלי הדין, ויהיו נשקטים, והדינים לא יעשו."]],[]],[["תָּאנָא, הַאי מִצְחָא אִתְפְּשָׁט בְּמָאתָן וְשִׁבְעִין אַלְפִין נְהִירִין בּוּצִינִין (ס\"א דנהרין) מֵעֵדֶן עִלָּאָה. דְּתַנְיָא, אִית עֵדֶן דְּנָהִיר לְעֵדֶן. עֵדֶן עִלָּאָה לָא אִתְגַּלְיָיא, וְהוּא סָתִים בִּסְתִּימָא וְלָא מִתְפָּרְשָׁא לְאָרְחִין כִּדְקָאַמְרָן. וְהַאי עֵדֶן דִּלְתַּתָּא, מִתְפְּרַשׁ בִּשְׁבִילוֹי, לִתְלָּתִין וּתְרֵין (עיבר) שְׁבִילִין.","וְאַף עַל גַּב דְּמִתְפְּרַשׁ הַאי עֵדֶן בִּשְׁבִילוֹי, לֵית דְּיֵדַע לֵיהּ, בַּר הַאי זְעֵיר אַפִּין. וְעֵדֶן דִּלְעֵילָּא, לֵית דְּיֵדַע לֵיהּ, וְלָא שְׁבִילוֹי, בַּר הַהוּא אֲרִיךְ אַנְפִּין. הֲדָא הוּא דִכְתִיב, (איוב כ״ח:כ״ג) אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ. אֱלֹהִים הֵבִין דַּרְכָּהּ, דָּא עֵדֶן דִּלְתַּתָּא, דְּיָדַע זְעֵיר אַפִּין. וְהוּא יָדַע אֶת מְקוֹמָהּ, דָּא עֵדֶן דִּלְעֵילָּא, דְּיָדַע עַתִּיק יוֹמִין, סְתִימָאָה דְּכֹלָּא.","עֵינוֹי דְּרֵישָׁא חִוָּורָא, מִשְׁתַּנְיָין מִשְּׁאַר עַיְינִין, לֵית כְּסוּתָא עַל עֵינָא. וְלֵית גְּבִינִין עַל עֵינָא. מַאי טַעְמָא. דִּכְתִּיב (תהילים קכ״א:ד׳) הִנֵּה לֹא יָנוּם וְלֹא יִישָׁן שׁוֹמֵר יִשְׂרָאֵל. יִשְׂרָאֵל דִּלְעֵילָּא. וּכְתִיב (ירמיהו ל״ב:י״ט) אֲשֶׁר עֵינֶיךָ פְּקוּחוֹת. וְתָאנָא, כָּל מַה דְּאָתֵי בְּרַחֲמֵי, לֵית כְּסוּתָא עַל עֵינָא, וְלֵית גְּבִינִין עַל עֵינָא. כָּל שֶׁכֵּן רֵישָׁא חִוָּורָא, דְּלָא בָּעָא מִידִי. (ס\"א נטירו)","אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אַבָּא לְמָאי הִיא רְמִיזָא. אָמַר לֵיהּ לְנוּנֵי יַמָּא, דְּלֵית כְּסוּתָא עַל עֵינָא, וְלֵית גְּבִינִין עַל עֵינָא, וְלָא נַיְימִין, וְלָא בַּעְיָין נְטוּרָא עַל עֵינָא. כָּל שֶׁכֵּן עַתִּיקָא דְּעַתִּיקָא, דְּלָא בָּעֵי נְטוּרָא. וְכָּל שֶׁכֵּן דְּאִיהוּ מַשְׁגַּח לְכֹלָּא, וְכֹלָּא מִתְּזָן בֵּיהּ וְלָא נָאִים. הֲדָא הוּא דִכְתִיב, הִנֵּה לֹא יָנוּם וְלֹא יִישָׁן שׁוֹמֵר יִשְׂרָאֵל, יִשְׂרָאֵל דִּלְעֵילָּא.","כְּתִיב (תהילים ל״ג:י״ח) הִנֵּה עֵין יְיָ אֶל יְרֵאָיו. וּכְתִיב (זכריה ד׳:י׳) עֵינֵי יְיָ הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ. לָא קַשְׁיָא, הָא בִּזְעֵיר אַפִּין. הָא בַּאֲרִיךְ אַנְפִּין. וְעִם כָּל דָּא תְּרֵי עַיְינִין אִינּוּן וְאִתְחַוָורוּ (ס\"א ואתחזרו) לְחָד, עֵינָא דְּאִיהִי חִוָּור בְּגוֹ חִוָּור וְחִוָּור דְּכָלִיל כָּל חִוָּור.","חִוָּורָא קַדְמָאָה, נָהִיר וְסָלִיק, וְנָחִית לְאִסְתַּכְּלָא (ס\"א לאתכללא), דְּצָּרִיר בִּצְרוֹרָא. תָּאנָא, בָּטַשׁ הַאי חִיוָּרָא, וְאַדְלִיק ג' בּוֹצִינֵי, דְּאִקְרוּן: הוֹד. וְהָדָר. וְחֶדְוָה. וְלַהֲטִין בְּחֶדְוָותָא בִּשְׁלֵימוּתָא.","חִוָּורָא תִּנְיָינָא, נָהִיר, וְסָלִיק וְנָחִית, וּבָטַשׁ וְאַפִּיק (ס\"א ואדליק) ג' בּוֹצִינִין אַחֲרָנִין, דְּאִקְרוּן נֶצַח וָחֶסֶד וְתִפְאֶרֶת, וְלַהֲטִין בִּשְׁלֵימוּתָא בְּחֶדְוָותָא.","חִוָּורָא תְּלִיתָאָה, לָהִיט וְנָהִיר, וְנָחִית וְסָלִיק, וְנָפִיק מִסְּתִימוּתָא דְּמוֹחָא, וּבָטַשׁ בְּבוּצִינָא אֶמְצָעִיתָא שְׁבִיעָאָה. וְאַפִּיק אָרְחָא לְמוֹחָא תַּתָּאָה, (נ\"א ואפיק ארחא ללבא תתאה) וּמִתְלַהֲטָן כֻּלְּהוּ בּוֹצִינִין דִּלְתַּתָּא. אָמַר רַבִּי שִׁמְעוֹן יָאוּת הוּא, וְעַתִּיק יוֹמִין יִפְקַח עֵינָא דָּא עֲלָךְ, בְּשַׁעֲתָא דְּתִצְטְרִיךְ לֵיהּ.","תָּאנָא חִוָּור בְּגוֹ חִוָּור. וְחִוָּור דְּכָלִיל כָּל חִוָּור. חִוָּורָא קַדְמָאָה, נָהִיר, וְסָלִיק. וְנָחִית לְתַתָּא (ס\"א לתלת) בּוּצִינֵי דְּלִסְטַר שְׂמָאלָא, וְלַהֲטִין וְאַסְחַן בְּהַאי חִוָּורָא, כְּמַאן דְּאַסְחֵי גּוּפֵיהּ בְּבוּסְמִין טָבִין, וּבְרֵיחִין, עַל מַה דַּהֲווֹ עֲלוֹי בְּקַדְמִיתָא.","חִוָּורָא תִּנְיָינָא, נָחִית, וְסָלִיק, וְנָהִיר לִתְלַת בּוֹצִינֵי, דְּלִסְטַר יְמִינָא. וְלַהֲטִין וְאַסְחִין בְּהַאי חִוָּורָא, כְּמַאן דְּאַסְחֵי בְּבוּסְמִין טָבִין וּבְרֵיחִין, עַל מַה דַּהֲווֹ עֲלוֹי בְּקַדְמִיתָא.","חִוָּורָא תְּלִיתָאָה, נָהִיר וְסָלִיק וְנָחִית, וְנָפִיק נְהִירוּ דְּחִוָּורָא, דִּלְגוֹ לְגוֹ מִן מוֹחָא, וּבָטַשׁ בְּשַׂעְרָא אוּכָמָא, כַּד אִצְטְרִיךְ. וּבְרֵישָׁא. וּבְמוֹחָא דְּרֵישָׁא. וְנָהִיר לִתְלַת כִּתְרִין דְּאִשְׁתָּאָרוּ, כְּמָה דְּאִצְטְרִיךְ לְגַלָּאָה. אִי נִיחָא קַמֵּי עַתִּיק סְתִימָא דְּכֹלָּא.","וְתָאנָא לָא סָתִים הַאי עֵינָא. ואִינּוּן תְּרֵין וּמִתְחַוְורָן (ס\"א ואתחזרו) לְחָד. כֹּלָּא הוּא יְמִינָא. לָא הֲוִי (ס\"א לית ביה) שְׂמָאלָא. לָא נָאִים וְלָא אַדְמִיךְ, וְלָא בָּעֵי נְטִירוּתָא. לֵית מַאן דְּאָגִּין עָלֵיהּ. הוּא אַגִּין עַל כֹּלָּא, וְהוּא אַשְׁגַּח עַל כֹּלָּא. וּמֵאַשְׁגָּחוּתָא דְּהַאי עֵינָא מִתְּזְנָן כֻּלְּהוּ.","תָּאנָא, אִי עֵינָא דָּא אַסְתִּים רִגְעָא חֲדָא, לָא יַכְלִין לְקַיְּימָא כֻּלְּהוּ, בְּגִין כָּךְ אִקְרֵי עֵינָא פְּקִיחָא. עֵינָא עִלָּאָה. עֵינָא קַדִּישָׁא. עֵינָא דְּאַשְׁגָּחוּתָא. עֵינָא דְּלָא אַדְמִיךְ וְלָא נָאִים. עֵינָא דְּהוּא נְטוּרָא דְּכֹלָּא. עֵינָא דְּהוּא קִיוּמָא דְּכֹלָּא. וְעַל הַאי כְּתִיב (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ, אַל תִּקְרֵי יְבוֹרָךְ אֶלָּא יְבָרֵךְ. דְּהַאי אִתְקְרֵי טוֹב עַיִן, וּמִנֵּיהּ מְבָרֵךְ לְכֹלָּא."],[[0,"תאנא האי מצחא","וכו׳: למדנו, מצח הזה נתפשט במאתים ושבעים אלף אורות הנרות המאירים מעדן העליון. עדן, פירושו חכמה. שלמדנו, שיש עדן מאיר לעדן. עדן העליון, שהוא חכמה סתימאה דא״א, אינו מתגלה והוא סתום בסתימא, דהיינו מקרומא דאוירא המקיפו (כנ״ל אות כ״א) ואינו מתחלק לדרכים כמו שאמרנו. שאין הארתו יוצא לחוץ ועדן הזה שלמטה, שהוא בינה שחזרה לחכמה דהיינו ישסו״ת, מתפרש בשבילים שלו לל״ב שבילים של חכמה."],[1,"ואע״ג דמתפרש האי","וכו׳: ואע״פ שעדן הזה שלמטה, בינה, מתחלק בשבילים שלו, לל״ב שבילי החכמה, אין מי שישיג אותו חוץ מז״א הזה, ועדן שלמעלה אין מי שישיג אותו ואת השבילים שלו חוץ מאותו אריך אנפין. ז״ש אלקים הבין דרכה והוא ידע את מקומה. \u0003אלקים הבין דרכה,\u0004 זהו עדן שלמטה, דהיינו החכמה הנמשכת מישסו״ת, שיודע אותה ז״א, ולא אחר, אבל הוא משפיע אותה למלכות. \u0003והוא ידע מקומה,\u0004 זהו עדן שלמעלה, שהוא חכמה סתימאה דא״א, שיודע אותה עתיק יומין הסתום מכל. ואינו משפיע אותה למטה. ומ״ש בז״א שאחר אינו יודע אותה, היינו הבא לקבל חכמה ממנו עצמו. אבל הבא לקבל מן המלכות. יודע אותה."],[2,"עינוי דרישא חוורא","וכו׳: העינים של ראש הלבן, שהוא כתר דא״א הנקרא גולגלתא. משתנות משאר עינים. אין כסות על העין ואין גבות על העין. מהו הטעם. הוא משום שכתוב, הנה לא ינום ולא יישן שומר ישראל. שפירושו ששומר ישראל שלמעלה, שהוא ז״א שעיניו דא״א שומרים אותו. וכתוב, אשר עיניך פקוחות, בלי כסות, ולמדנו, כל מה שבא ברחמים אין לו כסות על העין ואין לו גבות על העין, כל שכן הראש הלבן שאינו צריך כלום."],[2,"","פירוש. כמ״ש לעיל (אות ל״ג) שכמו שיש בפנימיות הראש דא״א גלגלתא ומוחא דאוירא, כן הוא בחיצוניות הראש. וע״כ הוא מתחלק לב׳ חלקים למקום שערות, שה\"ס \u0003ם׳\u0004 דצלם, שאין היוד יוצא מאויר. ומקום הפנים החלק משערות, שה״ס \u0003ל׳\u0004 דצלם, שבו יוצא ה \u0003י׳\u0004 מאויר, שהוא שורש השערות, וע״כ אין שם שערות. אמנם גם החלק משערות שהוא \u0003ל׳\u0004 דצלם מתחלק לפי עצמו ב \u0003מ׳ ל׳ צ׳.\u0004 אשר ב׳ אודנין ומצחא ה״ס ה \u0003ם׳\u0004 של ה \u0003ל׳\u0004 שה״ס חב״ד, וב׳ עיינין וחוטמא הם חג״ת, ב׳ שפוון ולשון הם נה״י. והפה הוא מלכות. וז״ס שהעינים אע״פ שהם חכמה מכל מקום אינם מאירים בבחינת חו״ב, אלא בבחינת \u0003חו״ג\u0004 שהם ו״ק דחכמה. כי האודנין הם חו״ב והם נכסו בסוד \u0003ם׳\u0004 דצלם. וע״כ לא נזכר תקון אודנין בא״א. באפן שב׳ עינים ה״ס ו״ק דחכמה. ונבחנים משום זה לחו״ג דגלגלתא דא״א. (ועי׳ כל זה בתלמוד עשר ספירות חלק י״ג דף אלף תע\"א אות פ׳)"],[2,"","והנה בהארת החכמה בז״א נוהג הופעת הדינים בסוד השמירה והכיסוי על הארת החכמה שלא יינקו ממנה החצונים. (כנ״ל פקודי אות שע״ו, צו אות קט״ו) משא״כ בא״א ששם כולו רחמים. וז״ש \u0003לית כסותא על עינא\u0004 שאין פחד מפני יניקת חיצונים שאינם מגיעים ח״ו למקום גבוה הזה. \u0003ולית גבינין על עינא,\u0004 שהם יורים על דינים, וא״א הוא כולו רחמים. וז״ש \u0003כל מה דאתי ברחמי לית כסותא על עינא,\u0004 כי הכיסוי היא דינים המכסים הארת החכמה. שאין זה נוהג במקום רחמים כ״ש \u0003רישא חוורא דלא בעא מידי.\u0004 כי החיצונים לא יגיעו אליו מחמת גבהו. ואין חשש מפני יניקתם. ומה גם שהוא כולו רחמים ואין בו דין."],[3,"אמר ר׳ שמעון","וכו׳: א״ר שמעון לר׳ אבא, למה זה רמוז. אמר לו, לדגת הים, שאין להם כסות על העין ואין להם גבות עינים, ואינם ישנים, ואינם צריכים שמירה על עיניהם, מפני שנמשכים ברחמים. כל שכן עתיק מכל עתיק שאינו צריך שמירה. וכל שכן שהוא משגיח על הכל והכל נזונים בו, ואינו ישן. ז״ש הנה לא ינום ולא יישן שומר ישראל. ששומר ישראל של מעלה, שהוא ז״א."],[4,"כתיב הנה עין","וגו׳: כתוב, הנה עין ה׳ אל יראיו, שמשמע עין אחת. וכתוב, עיני ה׳ המה משוטטות בכל הארץ. שמשמע שתי עינים. ומשיב, לא קשיא, כאן בז״א, הן ב׳ עינים. כאן בא״א, הן עין אחת. ועם כל זה שתי עינים הן, אלא שנחזרו לאחת, עין, שהיא לבן בתוך לבן, ולבן הכולל כל לבן."],[4,"","פירוש. בז״א, עין ימין היא חסדים ועין שמאל היא הארת חכמה, וע״כ הן ב׳ בחינות. מה שאין כן בא״א, שאין בו שמאל והוא כולו ימין, ונמצא שגם עין שמאל שבו אע״פ שהיא חכמה, מכל מקום היא מוחזרת לחסדים, כלומר שאין לחכמה שום שליטה. ושתיהן בבחינה אחת, שהיא חסדים. וז״ש, \u0003ועכ״ד תרי עיינין אינון ואתחזרו לחד,\u0004 שאין הפירוש שגם עין שמאל הוא חסדים שא״כ היו באמת רק עין אחת, אלא הפירוש שהם ב׳ עינים, ב׳ בחינות, שהימין הוא חסד, והשמאל היא חכמה, אלא שנחזרו לאחת. שהשליטה היא לאחת שהיא חסדים."],[4,"","ונודע שיש בכל עין ג׳ גווני עינא, שהם לבן אדום ירוק, שה״ס ג׳ קוין, ימין, שמאל, אמצע, שימין הוא חסדים, ושמאל הוא חכמה, ואמצע הוא כלול משניהם. ולפי האמור שבא״א כולו ימין, איך מתבארים בו ג׳ גווני עינא. וז״ש, \u0003עינא דאיהי חוור בגו חוור, וחוור דכליל כל חוור,\u0004 והוא כעין שאומר הזהר לחלק בין עתיק לא״א, שעתיק הוא בבחינת \u0003דא לעילא מן דא,\u0004 שהוא בחינת כתר המרומם לגמרי מחכמה, אבל א״א יש בו ג״כ חכמה, אלא הוא \u0003דא לגו מן דא,\u0004 שהחכמה סתימאה שלו הוא בתוך הגלגלתא שהיא הכתר, והשליטה היא לגלגלתא, אף כאן יש ב׳ עינים חסדים וחכמה, אלא שהשמאלית שהיא חכמה היא בתוך הימנית שהיא חסדים. ועד״ז ב׳ קוין ימין ושמאל שבכל עין שלו הם ג״כ דא בגו דא, שקו השמאל הוא בתוך קו הימין, וע״כ אע״פ שקו שמאל הוא אדום הוחזר להיות לבן, וב׳ הקוין הן \u0003חוור בגו חוור.\u0004 ולפי״ז קו האמצעי הכולל ימין ושמאל, שהם בכל מקום, לבן ואדום, שבשביל זה נעשה קו האמצעי ירוק, הכלול מלבן ואדום, כמו החמה. אבל כאן שהשמאל אינו אדום אלא הוחזר ללבן. נמצא קו האמצעי כולל ב׳ בחינות לבן. וז״ש, \u0003חוור דכליל כל חוור,\u0004 דהיינו קו האמצעי שבעין דא״א, שאינו ירוק, אלא לבן הכולל כל לבן, שכולל לבן של ימין והלבן של שמאל. וההפרש ביניהם הוא שזה לבן ממקורו, וזה אדום ממקורו אלא שהוחזר ללבן."],[5,"חוורא קדמאה","וכו׳: לבן הראשון, מאיר ועולה ויורד להסתכל בזה שצרור בצרור. למדנו, הכה לבן הזה, והדליק ג׳ נרות הנקראים הוד והדר וחדוה. ולוהטים בשמחה בשלמות."],[5,"","פירוש. שעתה מבאר ג׳ גווני דעינא שבעין ימין דא״א, שהם סוד ג׳ קוין, כנ״ל בדבור הסמוך. ומפרש תחלה קו השמאל שבעין ימין דא״א. ונודע שכל קו מג׳ קוין כלול משלשתם, וע״כ מפרש ג׳ בחינות הארות בקו השמאל הזה, שהם בחינות ג׳ קוין שבו. וז״ש \u0003חוורא קדמאה,\u0004 שהוא שמאל, \u0003נהיר\u0004 בחסדים דקו ימין שבו, \u0003וסליק,\u0004 היינו הארת חכמה שמאירה ממטה למעלה, החוזרת לחסד כנ״ל. \u0003ונחית,\u0004 היינו בחסדים דקו אמצעי שבו, המאיר ממעלה למטה. \u0003לאסתכלא דצריר בצרורא,\u0004 היינו להשפיע כל ג׳ קוין אלו אל המלכות, שנקראת צרור החיים. ונודע שכל עין כולל ע״ס, שהם חג״ת נהי״מ והחסד כלול מג״ר. והן מתחלקות בג׳ קוין אלו, גבורה הוד יסוד, הם בקו שמאל, וחסד נצח ת״ת, הם בקו ימין, וכללוה הג״ר שבחסד נמשך בקו אמצעי. כמ״ש לפנינו. וכאן מפרש ג׳ ספירות שבקו שמאל. וז״ש, \u0003בטש האי חוורא,\u0004 דהיינו שנזדווג בבחינת המלכות שבו, \u0003ואדליק ג׳ בוציני דאקרון הוד והדר וחדוה,\u0004 דהיינו הוד יסוד גבורה. כי הדר הוא יסוד. וחדוה היא גבורה, בסוד שהוא יין המשמח. ומה שחושב יסוד בשמאל, הוא כי קו האמצעי שהוא ת״ת ויסוד, נחלקים לב׳ בחינות, שהת״ת נוטה לחסד ולימין, והיסוד לגבורה ולקו שמאל."],[6,"חוורא תנינא","וכו׳: לבן השני, שהוא קו ימין שבעין ימין דא״א. מאיר, מבחינת ימין שבו, ועולה, מבחינת שמאל, המאיר בו ממטה למעלה, ויורד, הארתו ממעלה למטה בבחינת קו האמצעי. והכה והוציא ג׳ נרות אחרים הנקראים נצח חסד ותפארת. ולוהטים בשלמות בשמחה. כמ״ש כל זה לעיל בדבור הסמוך."],[7,"חוורא תליתאה","וכו׳: לבן השלישי, שהוא קו האמצעי שבעין ימין דא״א, מאיר ג״כ בג׳ הארות דג׳ קוין, לוהט ומאיר, מבחינת ימין, ויורד, מבחינת קו אמצעי, ועולה, מבחינת הארת השמאל החוזר לימין כנ״ל. ויוצא מסתימת המוח, כלומר שמוציא הארה ממוחא סתימאה הכוללת ג״ר. ומכה בנר האמצעי שבשביעי, דהיינו שמזדווג בקו האמצעי שבבינה הנקראת שביעי. שקו האמצעי שבה היא דעת. שעי״ז היא מוציא מן הבינה כללות הג״ר. ומוציא דרך להאיר למוח התחתון, לז״א, ולוהטים כל הנרות שלמטה. שבז״א. פירוש. כי ז״א שהוא קו אמצעי שלמטה מקבל מקו האמצעי הזה, שבעין דא״א, בעת שמתדבק בו בסוד אשר עין בעין נראה אתה ה׳. כמ״ש לפנינו. אמר ר׳ שמעון, יפה הוא. ועתיק יומין יפקח עין זו עליך בשעה שתצרך לו. וע״כ ביאר ג׳ גווני עינא שבעין ימין דא״א, שכל אחד מהם מאיר בג׳ קוין."],[8,"תאנא חוור בגו","וכו׳: אחר שפירש ג׳ חוורין דעין ימין, ממשיך לפרש ג׳ חוורין דעינא שבעין שמאל דא״א. ואומר, למדנו, לבן בתוך לבן, שקו השמאל הוחזר ללבן, מחמת שבא בתוך לבו שבימין. כנ״ל. ולבן הכולל כל לבן, שהוא קו האמצעי, הכולל ימין ושמאל שהם לבן תוך לבן. ומפרש. לבן הראשון, שהוא השמאל שבעין שמאל שהוחזר ללבן, מאיר מהארת ימין, ועולה מהארת שמאל, ויורד למטה מהארת קו האמצעי, לשלשה נרות שבצד שמאל, שהם גבורה הוד יסוד כנ״ל, ולוהטים. ורוחצים כלבן הזה כמי שרוחץ גופו בבשמים טובים ובריחות, על מה שעבר עליו בתחילה."],[8,"","פירוש כל אלו הפרצופין נתקנו מז׳ מלכים דנקודים שנשברו. ונתבאר לעיל סבת שבירתם מפני שלא היה תקון קוין בז״ת, והיה השמאל מתגבר ומאיר ממעלה למטה ובא לבי״ע וע״כ נשברו ומתו (כנ״ל אות י״ב ע״ש) ולפיכך עתה, כשחזר קו השמאל להתתקן באצילות, בבחינת עין שמאל דא״א, ובבחינת \u0003דא לגו מן דא,\u0004 דהיינו \u0003חוור בגו חוור\u0004 (כנ״ל אות מ״ב) שהשמאל הוחזר כולו לימין, היה רוחץ עצמו בלבן הזה, כלומר, שע״י התכללותו בלבן, דהיינו בחסדים, נטהר מכל הפגמים שהיו לו בעת שבירת הכלים. וז״ש, \u0003ואסחן בהאי חוורא כמאן דאסחי גופיה בבוסמין טבין ובריחין,\u0004 כי החסדים שהשמאל נכלל בהם היה לו כבשמים וריחות, \u0003על מה דהוו עלוי בקדמיתא,\u0004 דהיינו שנטהר מכל מה שהיה עליו בתחילה, בעת שבירת הכלים. ונפטר מכל הדינים הללו ע״י התכללותו זו."],[9,"חוורא תנינא","וכו׳: אחר שביאר בחינת קו שמאל שבעין שמאל דא״א, מבאר, לבן השני, שהוא בחינת הימין שבעין שמאל דא״א, יורד ועולה ומאיר, דהיינו בהארות ג׳ קוין כנ״ל, לג׳ נרות שבצד ימין, שהם חסד ת״ת, נצח, כנ״ל. ולוהטים ומתרחצים בלבן הזה שבעין ימין, שנכללו בו בסוד חוור גו חוור כנ״ל, כמי שרוחץ גופו בבשמים טובים ובריחות על מה שהיה עליו בתחילה, דהיינו בזמן שבירת הכלים כנ״ל. ואין להקשות הרי הוא בחינת ימין, וא״כ מה לו להתרחץ בלבן של עין ימין בסוד חוור גו חוור. כי הענין הוא, שאפילו קו ימין דעין שמאל, היה בעת שבירת הכלים תחת שליטת השמאל, וצריך עתה להתמתק בלבן שבעין ימין דא״א."],[10,"חוורא תליתאה","וכו׳: אחר שכבר ביאר ב׳ חוורין, שהם ב׳ קוין ימין ושמאל שבעין שמאל דא״א, מבאר עתה לבן השלישי, שהוא קו האמצעי שבעין שמאל דא״א. הוא מאיר ועולה ויורד, דהיינו כדרך הארת ג׳ קוין כנ״ל, ועל ידו, יוצא אור לבן, דהיינו חסדים, מפנימי פנימיות של המוח, דהיינו מח״ס דא״א, ובוטש בשער שחור דז״א, כאשר צריך, ובראש, ובמוח של ראש של ז״א. ומאיר לשלש ספירות שנשארו, שהם חכמה בינה דעת, כי לא נגלה עד עתה רק חג״ת נה״י. והם נגלות כפי שנצרך לגלות, אם טוב לפני עתיק הסתום מכל, לגלות."],[10,"","פירוש כמו שחוורא תליתאה דעין ימין דא״א האיר למוחא תתאה, שהוא ז״א, מטעם שנתבאר לעיל (אות מ״ה) אף כאן חוורא תליתאי דעין שמאל דא״א מאיר לז״א. וז״ש \u0003ובטש בשערא אוכמא,\u0004 דהיינו ז״א ששערותיו שחורות בסו״ה שחורות כעורב. \u0003וברישא\u0004 שהוא גלגלתא שלו. \u0003ובמוחא דרישא,\u0004 שהוא חב״ד שלו."],[10,"","ואין להקשות, הרי מקודם לכן אמר, שבא״א הוא עין אחת, ולמה חושב כאן ב׳ עינים. והענין כי ע״כ מקדים ואומר (באות מ״ב) וכן להלן, \u0003תרי עיינין אינון ואתחזרו לחד,\u0004 כלומר שהם באמת ב׳ עינים, אלא לפי שגם השמאל הוא לבן וחסדים כמו הימין, נחשבים שתיהן כאחת. אמנם הם ב׳ עינים ובכל אחת ג׳ חוורין, כמבואר."],[11,"ותאנא לא סתים","וכו׳: ולמדנו, העין ההיא דא״א אינה סתומה, והם שתי עינים, והוחזרו לאחת. כי הכל הוא ימין ואין בו שמאל לא ינום ולא יישן, ואינו צריך שמירה. אין מי שיגין עליו, הוא מגין על הכל, והוא משגיח על הכל. ומההשגחה של העין הזו נזונים כולם."],[12,"תאנא אי עינא","וכו׳: למדנו אם עין זו דא״א היתה נסתמת רגע אחד, לא יכלו כולם להתקיים. משום זה נקראת עין פקוחה עין עליונה, עין קדושה, עין של ההשגחה, עין שלא ינום ולא יישן, עין שהיא שמירת הכל, עין שהיא קיום הכל. ועל זה כתוב, טוב עין הוא יבורך. אל תקרא יבורך אלא יברך. כי זה, נקרא טוב עין, וממנו מברך לכל."]],[]],[["וְתָאנָא, לֵית נְהִירוּ לְעֵינָא תַּתָּאָה, לְאִסְתַּחֲאָה מֵאַדְמִימוּתָא מֵאוּכָמוּתָא בַּר כַּד חֲזִי (ס\"א אתחזי) (ס\"א אתסחי) מֵהַאי נְהוֹרָא חִוָּורָא דְּעֵינָא עִלָּאָה דְּאִקְרֵי טוֹב עַיִן. וְלֵית דְּיָדַע כַּד נָהִיר עֵינָא עִלָּאָה דָּא קַדִּישָׁא וְאַסְחֵי לְעֵינָא תַּתָּאָה דָּא. בַּר אִיהוּ.","וּזְמִינִין צַדִּיקַיָּיא, זַכָּאֵי עֶלְיוֹנִין, לְמֵחֱמֵי דָּא בְּרוּחָא דְּחָכְמְתָא, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ב:ח׳) כִּי עַיִן בְּעַיִן יִרְאוּ. אֵימָתַי. בְּשׁוּב יְיָ צִיּוֹן. וּכְתִיב (במדבר י״ד:י״ד) אֲשֶׁר עַיִן בְּעַיִן נִרְאָה אַתָּה יְיָ. וְאִלְמָלֵא עֵינָא טָבָא עִלָּאָה, דְּאַשְׁגַּח וְאַסְחֵי לְעֵינָא תַּתָּאָה, לָא יָכִיל עָלְמָא לְמֵיקָם רִגְעָא חֲדָא.","תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, אַשְׁגָּחוּתָא דְּעֵינָא תַּתָּאָה, כַּד אַשְׁגַּח נְהִירוּ עִלָּאָה בֵּיהּ, וְעָיִיל הַהוּא נְהִירוּ דְּעִלָּאָה בְּתַתָּאָה. דְּמִנֵיהּ נָהִיר כֹּלָּא הֲדָא הוּא דִכְתִיב אֲשֶׁר עַיִן בְּעַיִן נִרְאָה אַתָּה יְיָ.","כְּתִיב (תהילים ל״ג:י״ח) הִנֵּה עֵין יְיָ אֶל יְרֵאָיו. וּכְתִיב (זכריה ד׳:י׳-י״א) עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ. זָכוּ, עֵינֵי יְיָ אֶל יְרֵאָיו, עֵינָא דִּלְעֵילָּא. לָא זָכוּ, עֵינֵי יְיָ הֵמָּה מְשׁוֹטְטוֹת, עֵינָא דִּלְתַּתָּא.","דְּתַנְיָא, מִפְּנֵי מַה זָכָה יוֹסֵף דְּלָא שַׁלְטָא בֵּיהּ עֵינָא בִּישָׁא, מִפְּנֵי שֶׁזָּכָה לְאִשְׁתַּגְּחָא בְּעֵינָא טָבָא עִילָּאָה, הֲדָא הוּא דִכְתִיב, (בראשית מ״ט:כ״ב) בֵּן פּוֹרָת יוֹסֵף בֵּן פּוֹרָת עֲלֵי עָיִן. אֲמַאי הוּא בֵּן פּוֹרָת. עֲלֵי עָיִן. כְּלוֹמַר עַל סִבַּת עַיִן דְּאִשְׁתְּגַח בֵּיהּ.","וּכְתִיב טוֹב עַיִן הוּא יְבוֹרָךְ, מַאי טַעְמָא. כִּי נָתַן מִלַּחְמוֹ לַדָּל. מַאי טַעְמָא אִקְרֵי חַד. תָּא חֲזֵי, בְּעֵינֵיהּ דְּתַתָּאָה אִית עֵינָא יְמִינָא, וְאִית עֵינָא דִּשְׂמָאלָא. וְאִינּוּן תְּרֵי, בִּתְרֵי גְּוָונֵי. אֲבָל הָכָא, לֵית עֵינָא שְׂמָאלָא. וְתַרְוַויְיהוּ בְּדַרְגָּא חַד סַלְקֵי, וְכֹלָּא יְמִינָא. וּבְגִינֵי כַּךְ, עֵינָא חַד, וְלָא תְּרֵין.","וְתָאנָא, עֵינָא דָּא, דְּהוּא עֵינָא דְּאַשְׁגָּחוּתָא. פְּקִיחָא תָּדִיר. חַיְיכָאן תָּדִיר. וְחַדָּאן (ס\"א וחזאן) תָּדִיר, דְּלָא הֲוִי הָכִי לְתַתָּאָה, דִּכְלִילָן בְּסוּמָקָא וּבְאוּכָמָא וּבְחִוָּורָא, בְּג' גְּוָונֵי, וְלָא הֲוָה תָּדִיר פְּקִיחָא (ס\"א דליה גבינא) דְּלֵית גַבְהָנָא סוּטְרָא (ס\"א כליה גביני סודרא) (ס\"א דליה עיניה בגביני דמכסאן) עַל עֵינָא. וְעַל דָּא כְּתִיב, (תהילים מ״ד:כ״ד) עוּרָה לָמָּה תִישַׁן יְיָ. (מלכים ב י״ט:ט״ז) פְּקַח יְיָ עֵינֶיךָ.","כַּד אִתְפְּקַח, אִית לְמַאן דְּאִתְפְּקַח לְטָב. וּלְמַאן דְּלָא אִתְפְּקַח לְטָב. וַוי לְמַאן דְּאִתְפְּקַח וְעֵינָא אִתְעֲרָב בְּסוּמָקָא, וְסוּמָקָא אִתְחֲזֵי לָקֳבְלֵיהּ, וּמְכַסְּיָא עֵינָא. מַאן יִשְׁתְּזִיב מִנֵּיהּ. אֲבָל עַתִּיק יוֹמִין, טָבָא דְּעֵינָא. חִוָּור בְּגוֹ חִוָּור. חִוָּור דְּכָלִיל כָּל חִוָּורֵי. זַכָּאָה חוּלָקֵיהּ, לְמַאן דְּיִשְׁגַּח עִלָּוִיהּ, חַד חִוָּור מִנַּיְיהוּ. וְעַל דָּא וַדַּאי כְּתִיב טוֹב עַיִן הוּא יְבוֹרָךְ. וּכְתִיב (ישעיהו ב׳:ה׳) בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר יְיָ.","תָּאנָא, (עם כל דא) שְׁמֵיהּ דְּעַתִּיקָא סָתִים מִכֹּלָּא, וְלָא מִתְפְּרַשׁ בְּאוֹרַיְיתָא, בַּר מִן אֲתָר חַד, דְּאוֹמֵי זְעֵיר אַפִּין לְאַבְרָהָם, דִּכְתִּיב, (בראשית כ״ב:ט״ז) בִּי נִשְׁבַּעְתִּי נְאֻם יְיָ. נְאֻם דִּזְעֵיר אַפִּין. וּכְתִיב, (בראשית מ״ח:כ׳) בְּךָ יְבָרֵךְ יִשְׂרָאֵל, יִשְׂרָאֵל דִּלְעֵילָּא. וּכְתִיב (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר, לְיִשְׂרָאֵל קָאָמַר דָּא. וְתָנֵינָן עַתִּיק יוֹמִין אֲמָרוֹ וְהַאי וְהַאי שַׁפִּיר.","תַּנְיָא, כְּתִיב (דניאל ז׳:ט׳) חָזֵה הֲוִית עַד דִּי כָּרְסָוָון רְמִיו וְעַתִּיק יוֹמִין יְתִיב. כָּרְסָוָון רְמִיו, מַאן הוּא. אָמַר לְרַבִּי יְהוּדָה, קוּם בְּקִיּוּמָךְ וְאַתְקִין כָּרְסְיָיא דָּא.","אָמַר רִבִּי יְהוּדָה, כְּתִיב (דניאל ז׳:ט׳) כּוֹרְסְיֵיהּ שְׁבִיבִין דִּינוּר. וְעַתִּיק יוֹמִין יְתִיב עַל הַאי כֻּרְסְיָּיא. מַאי טַעְמָא. דְּתַנְיָא אִי עַתִּיק יוֹמִין לָא יָתִיב עַל הַאי כָּרְסְיָּיא, לָא יָכִיל לְאִתְקַיְּימָא עָלְמָא, מִקַּמֵּי הַהוּא כּוּרְסְיָיא. כַּד יְתִיב עַתִּיק יוֹמִין עָלֵיהּ לְכַּפְיָיא (ס\"א אתכפייא) לְהַהוּא כּוּרְסְיָּיא, וּמַאן דְּרָכִיב שַׁלִּיט. בְּעִידָנָא דְּנָטִיל מֵהַאי כֻּרְסְיָיא, וְיָתִיב עַל כּוּרְסְיָיא אַחֲרָא, כּוּרְסְיָיא קַדְמָאָה רְמִיוּ, דְּלָא שַׁלְטָא אֶלָּא אִיהוּ דְּרָכִיב בֵּיהּ עַתִּיק יוֹמִין. אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי יְהוּדָה, יִתְתְּקַּן אָרְחָךְ, וְיֵיתֵי בָּךְ מֵעַתִּיק יוֹמִין.","וְתָּא חֲזֵי כְּתִיב (ישעיהו מ״א:ד׳) אֲנִי יְיָ רִאשׁוֹן וְאֶת אַחֲרוֹנִים אֲנִי הוּא. כֹּלָּא הוּא, וְהוּא סָתִים מִכָּל סִטְרוֹי. (בהאי) חוֹטָמָא. תָּאנָא, בְּחוֹטָמָא אִשְׁתְּמוֹדַע פַּרְצוּפָא."],[[0,"ותאנא לית נהירו","וכו׳: ולמדנו, אין אור לעין התחתונה דז״א, להתרחץ מאדמימות ומשחרות, חוץ כשהוא רואה מאור הלבן של העין העליונה דא״א, הנקרא טוב עין. ואין מי שיודע כאשר מאירה העין העליונה הקדושה הזו דא״א, ורוחצת לעין התחתונה הזו דז״א חוץ ממנו."],[1,"וזמינין צדיקייא זכאי","וכו׳: ועתידים הצדיקים, זכאים עליונים, לראות זה, העין דא״א, ברוח החכמה. ז״ש, כי עין בעין יראו. מתי יהיה זה, בשוב ה׳ ציון. וכתוב, כי עין בעין נראה אתה ה׳. ואם לא העין הטובה העליונה, דא״א, שמשגיחה ורוחצת את העין התחתונה, דז״א, לא היה יכול העולם להתקיים אפילו רגע אחד."],[2,"תאנא בצניעותא דספרא","וכו׳: למדנו, בצניעותא דספרא, ההשגחה של העין התחתונה כאשר אור העין העליונה משגיח בו, ונכנס אור זה של העין העליונה בעין התחתונה דז״א, מאיר הכל ממנו, ז״ש, אשר עין בעין נראה אתה ה׳."],[3,"כתיב הנה עין","וגו׳: כתוב, הנה עין ה׳ אל יראיו, וכתוב, עיני ה׳ המה משוטטים בכל הארץ. היינו, אם זכו, עין ה׳ אל יראיו. שהיא העין העליונה דא״א, לא זכו, עיני ה׳ המה משוטטים, שהיא עין שלמטה, דז״א."],[4,"דתניא מפני מה","וכו׳: שלמדנו, מפני מה זכה יוסף שלא שלט בו עין הרע, הוא מפני שזכה להיות מושגח בעין טוב העליון, דא״א. ז״ש, בן פורת יוסף בן פורת עלי עין. שפירושו, למה הוא \u0003בן פורת\u0004 שלא שלט בו עין הרע, מפני \u0003עלי עין\u0004 כלומר על סבת עין העליון דא״א שהיה מושגח בו."],[5,"וכתיב טוב עין","וגו׳: וכתוב, טוב עין הוא יבורך. מהו הטעם. הוא כי נתן מלחמו לדל. שואל, מהו הטעם שנקרא עין אחד. ולא אמר טוב עינים הוא יבורך. ומשיב, בוא וראה, בעין התחתונה דז״א, יש עין ימין, ויש עין שמאל. והם שתים בשתי בחינות מיוחדות, שהימנית היא חסדים, והשמאלית היא הארת חכמה. אבל כאן, בא״א, אין עין שמאלית, ושתיהן עולות במדרגה אחת, והכל ימין, דהיינו חוור גו חוור כנ״ל, ומשום זה כתוב, עין אחת, דהיינו טוב עין הוא יבורך, ולא שתים. כי הנותן מלחמו לדל, זוכה לברכת העין העליונה דא״א שהיא עין אחת."],[6,"ותאנא עינא דא","וכו׳: ולמדנו, עין זו דא״א, שהיא העין של ההשגחה, פתוחה תמיד, צוחקים תמיד, ושמחים תמיד. מה שאין כן למטה, בז״א, שהן כלולות באדום ובשחור ובלבן, בג׳ גוונים, ואינן תמיד פתוחות, שיש לו גבות בעיניו המכסים על העין. וז״ש עורה למה תישן ה׳. פקח עיניך וראה. שמשמע שאינן תמיד פתוחות."],[7,"כד אתפקח אית","וכו׳: כשנפקחו עינין דז״א, יש מי שנפתחו עליו העינים לטוב, ויש מי שלא נפתחו עליו לטוב. אוי למי שנפקחו עליו העינים והעין מעורבת באדום, שהוא גוון דין, והאדום נראה כנגדו ומכסה על העין. מי ינצל ממנו. כלומר מי שאינו זוכה מאיר לו השמאל בלי ימין, שה״ס גוון אדום, שאז כל דינים קשים נמשכים ממנו (כנ״ל ב״א דף מ״ז אות ל\"ד ד״ה נפק) אבל עתיק יומין, שהוא א״א, הוא טוב עין, שהיא לבן תוך לבן, ולבן הכולל כל לבן. (כנ״ל אות מ״ב) אשרי חלקו של מי שהשגיח עליו לבן אחד מהם. וע״כ ודאי כתוב, טוב עין הוא יבורך. וכתוב בית יעקב לכו ונלכה באור ה׳. דהיינו שנלך בהשגחה של אור ה׳, שהוא טוב עין כנ״ל."],[8,"תאנא שמיה דעתיקא","וכו׳: למדנו, שמו של עתיק שהוא א״א, סתום מכל, ואינו מפורש בתורה חוץ ממקום אחד, שנשבע ז״א לאברהם, שכתוב, בי נשבעתי נאם ה׳. דהיינו נאם דז״א, שנשבע בעתיק, וכתוב, בך יברך ישראל, דהיינו ישראל של מעלה, וא״כ בך יברך נאמר לעתיק, שהוא א״א. וכתוב, ישראל אשר בך אתפאר. לישראל אמר זה. ולמדנו, עתיק יומין אמרו לז״א, שהוא ישראל שלמעלה, וזה וזה טוב. כי ב׳ הפרושים אמיתים."],[8,"","ומה שאמר שלא נזכר בתורה רק במקום אחד, ומביא ג׳ מקומות שנזכר בהם עתיק יומין. הכוונה היא, שלא נזכר במפורש רק במקום אחד כי בכתוב בי נשבעתי הוא בהכרח במדרגה עליונה ממנו שהוא א״א. אבל בשאר הכתובים אינו מפורש כל כך."],[9,"תניא כתיב חזה","וכו׳: למדנו, כתוב, חזה הוית עד די כורסוון רמיו ועתיק יומין יתיב. שואל \u0003כורסוון רמיו,\u0004 מה הוא. אמר לרבי יהודה קום בקיומך, והתקן כסא הזה."],[10,"א״ר יהודה כתיב","וכו׳: אר״י כתוב, כורסייא שביבין די נור. ועתיק יומין יושב על כסא הזה. מה הטעם שיושב על כסא של שביבי אש. למדנו, אם עתיק יומין לא היה יושב על הכסא הזה, לא היה יכול העולם להתקיים מלפני כסא זה, וכשעתיק יומין יושב עליו נכפה הכסא ההוא. ומי שרוכב שולט. ובעת שנוסע מכסא זה, ויושב על כסא אחר, הושלך כסא הראשון, כי אינו שולט אלא אותו הכסא שעתיק יומין רוכב עליו. אר״ש לר׳ יהודה, יתתקן דרכך ויבא בך מהארת עתיק יומין."],[10,"","פירוש. החכמה דא״א היא כסא לכתר דא״א, כי נתתקנו בסוד \u0003דא לגו מן דא.\u0004 ומשום שמחכמה נמשכים, אחר השתלשלויות מרובות דינים (כנ״ל אות י״ד) ע״כ היא נקראת כורסייא שביבין די נור, (כמ״ש שם) וע״כ כיון שרוכב עליו א״א הוא שולט עליו ואין הדינים נמשכים ממנו. וז״ש, \u0003אי עתיק יומין לא יתיב על האי כורסיא לא יכיל לאתקיימא עלמא מקמי ההוא כרסייא.\u0004 דהיינו מחמת רוב הדינים שהיו נמשכים ממנו. \u0003ומאן דרכיב שליט.\u0004 כי ישיבה ורכיבה פירושן שליטה. ואם הכתר דא״א רוצה להשפיע חסדים, ויושב על כסא של אור החסדים. אז כסא החכמה אינו יכול להשפיע כלום, משום שעתיק יומין כבר אינו רוכב עליו. וז״ש, \u0003בעידנא דנטיל מהאי כורסיא, ויתיב על כורסייא אחרא, כורסייא קדמאה רמיו,\u0004 כי אינו שולט בו אלא אותו שרוכב בו שהוא א״א, וכיון שא״א רוכב על כסא אחר, אין כסא החכמה יכול לשלוט מעצמו. שז״ס, כורסייא רמיו. כלומר שהושלך השליטה של הכסא."],[11,"ות״ח כתיב אני","וגו׳: ובוא וראה, כתוב, אני ה׳ ראשון ואת אחרונים אני הוא. הכל הוא, דהיינו א״א, והוא סתום מכל צדדיו. חוטם, מהו. למדנו, בחוטם ניכר הפרצוף. כי אין מעידים על פרצוף אלא עם החוטם (יבמות ק״כ)."]],[]],[["וְתָא חֲזֵי מַה בֵּין עַתִּיקָא, לִזְעֵיר אַפִּין. דָּא מָארֵיהּ דְּחוֹטָמָא מֵחַד נוּקְבָּא חַיִּין, וּמֵחַד נוּקְבָּא חַיִּין דְּחַיִּין. הַאי חוֹטָמָא. הוּא פַּרְדַּשְׁקָא, דְּבֵיהּ נָשִׁיב רוּחָא דְּחַיֵּי, לִזְעֵיר אַפִּין. וְקָרֵינָן לֵיהּ סְלִיחָה. וְהוּא נַחַת רוּחַ, אִתְבַּסְּמוּתָא דְּרוּחָא.","דְּרוּחָא דְּנָפִיק (מהכא) מֵאִינּוּן נוּקְבֵי, חַד רוּחָא נָפִיק לִזְעֵיר אַפִּין. לְאַתְּעָרָא (ס\"א חיין מכל סטרין, חירו מכל סטרי, חיין דחיין) לֵיהּ בְּגִנְתָּא דְּעֵדֶן. וְחַד רוּחָא דְּחַיֵּי, דְּבֵיהּ זַמִּין לְזַמָנָא לִבְרֵיהּ דְּדָוִד, לְמִנְדַּע חָכְמְתָא. וּמֵהַהוּא נוּקְבָּא, אִתְּעַר וְנָפִיק רוּחָא מִמּוֹחָא סְתִימָאָה, וְזַמִּין לְאַשְׁרָאָה עַל מַלְכָּא מְשִׁיחָא, דִּכְתִּיב, (ישעיהו י״א:ב׳) וְנָחָה עָלָיו רוּחַ יְיָ רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יְיָ. הָא הָכָא ד' רוּחִין, וְהָא רוּחָא חֲדָא אַמְרֵינָן. אֲמַאי תְּלַת. קוּם רִבִּי יוֹסֵי בְּקִיּוּמָךְ.","קָם רִבִּי יוֹסֵי וְאָמַר. בְּיוֹמוֹי דְּמַלְכָּא מְשִׁיחָא, לָא יֵימְרוּן חַד לְחַד, אֲלִיף לִי חָכְמְתָא, דִּכְתִּיב, (ירמיהו ל״א:ל״ד) וְלֹא יְלַמְּדוּ עוֹד אִישׁ אֶת רֵעֵהוּ וְגוֹ', כִּי כֻלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם. וּבְהַהוּא זִמְנָא, יִתְּעַר עַתִּיק יוֹמִין, רוּחָא דְּנָפִיק מִמּוֹחָא סְתִימָאָה דְּכֹלָּא, וְכַד יִשְׁלוֹף דָּא, כָּל רוּחִין דִּלְתַּתָּא יִתְּעֲרוּן עִמֵּיהּ. וּמַאן אִינּוּן. אִינּוּן (תרין) כִּתְרִין קַדִּישִׁין דִּזְעֵיר אַפִּין. וְאִינּוּן שִׁיתָא רוּחִין אַחֲרָנִין, דְּיַהֲבֵי (ס\"א דהכי) אִינּוּן (ס\"א שיתא רוחין, ג' רוחין אינון דכללינן תלת אחרנין) דִּכְתִּיב רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יְיָ.","דְּתָנֵינָן, כְּתִיב (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא יְיָ. וּכְתִיב (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וּמַלְכָּא מְשִׁיחָא זַמִּין לְמֵיתַב בְּשִׁבְעָה. שִׁיתָא אִינּוּן וְרוּחָא דְּעַתִּיק יוֹמִין דְּעָלַיְיהוּ, הָא שִׁבְעָה. כְּמָה דְּאִתְּמַר. (ג' רוחי אינון דכללינן ג' אחרנין) אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, רוּחֲךָ יָנוּח לְעָלְמָא דְּאָתֵי.","תָּא חֲזֵי, כְּתִיב (יחזקאל ל״ז:ט׳) כֹּה אָמַר יְיָ (בראשית קל\"ט ע\"א, רל\"ה ע\"א) מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ וְגוֹ'. וְכִי אַרְבַּע רוּחֵי עָלְמָא, מַאי עַבְדֵּי הָכָא. אֶלָּא אַרְבַּע רוּחֵי יִתְּעֲרוּן. ג' אִינּוּן. וְרוּחָא דְּעַתִּיקָא סְתִימָא אַרְבַּע, וְהָכִי הֲווֹ. דְּכַד יִפּוּק דָּא, נָפְקִין עִמֵּיהּ תְּלָתָא, דִּכְלִילָן בְּגוֹ תְּלָתָא אַחֲרָנִין.","וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא חַד רוּחָא דְּכָלִיל מִכֻּלְּהוּ. דִּכְתִּיב מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ. אַרְבַּע רוּחוֹת בֹּאִי לָא כְּתִיב כָּאן, אֶלָּא מֵאַרְבַּע רוּחוֹת בֹּאִי. וּבְיוֹמֵי דְּמַלְכָּא מְשִׁיחָא, לָא יִצְטָרְכוּן לְמֵילַף חַד לְחַד, דְּהָא רוּחָא דִּלְהוֹן דְּכָלִיל מִכָּל רוּחִין. יְדִיעַ כֹּלָּא. חָכְמָה וּבִינָה עֵצָה וּגְבוּרָה (רוח) דַּעַת וְיִרְאַת יְיָ. מִשּׁוּם רוּחָא דִּכְלִילָא מִכָּל רוּחֵי. בְּגִין כָּךְ כְּתִיב, מֵאַרְבַּע רוּחוֹת, דְּאִינּוּן אַרְבַּע דִּכְלִילָן בְּשִׁבְעָה דַּרְגִּין עִלָּאִין דְּאַמָרָן. וְתָאנָא, דְּכֻלְּהוּ כְּלִילָן בְּהַאי רוּחָא דְּעַתִּיקָא דְּעַתִּיקִין, דְּנָפִיק מִמּוֹחָא סְתִימָאָה לְנוּקְבָּא דְּחוֹטָמָא.","וְתָּא חֲזֵי, מַה בֵּין חוֹטָמָא לְחוֹטָמָא. חוֹטָמָא דְּעַתִּיק יוֹמִין חַיִּין מִכָּל סִטְרוֹי. חוֹטָמָא דִּזְעֵיר אַפִּין, כְּתִיב, (שמואל ב כ״ב:ט׳) עָלָה עָשָׁן בְּאַפּוֹ וְאֵשׁ מִפִּיו תֹּאכֵל וְגוֹ'. עָלָה עָשָׁן בְּאַפּוֹ, וּמֵהַהוּא עָשָׁן דָּלִיק נוּר, כַּד סָלִיק תְּנָנָא לְבָתַר. גֶּחָלִים בָּעֲרוּ מִמֶּנּוּ. מַהוּ מִמֶּנּוּ (ג' נוסחי). מֵאוֹתוֹ עָשָׁן. מֵהַהוּא חוֹטָמָא, מֵהַהוּא אֶשָּׁא.","תָּאנָא, כַּד הֲוָה רַב הַמְנוּנָא סָבָא בָּעֵי לְצַלָּאָה צְלוֹתֵיהּ, אָמַר לְבַעַל הַחוֹטֶם אֲנִי מִתְפַּלֵל, לְבַעַל הַחוֹטֶם אֲנִי מִתְחַנֵּן. וְהַיְינוּ דִּכְתִּיב, (ישעיהו מ״ח:ט׳) וּתְהִלָּתִי אֶחטָם לָךְ, הַאי קְרָא לְעַתִּיק יוֹמִין אֲמָרוֹ.","תָּנָא, אוֹרְכָא דְּחוֹטָמָא, תְּלַת מְאָה וע\"ה עָלְמִין, אִתְמַלְּיָין מִן הַהוּא חוֹטָמָא. וְכֻלְּהוּ מִתְדַּבְּקִן בִּזְעֵיר אַפִּין. הַאי תּוּשְׁבַּחְתָּא דְּתִקּוּנָא דְּחוֹטָמָא הוּא. וְכָל תִּקּוּנֵי דְּעַתִּיק יוֹמִין, אִתְחָזוּן וְלָא אִתְחָזוּן, אִתְחָזוּן לְמָארֵי מִדִּין, וְלָא אִתְחָזוּן לְכֹלָּא.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, וַוי מַאן דְּאוֹשִׁיט יְדוֹי בְּדִיקְנָא יַקִּירָא עִלָּאָה, דְּסָבָא קַדִּישָׁא, טְמִירָא וּסְתִימָא (נ\"א טמיר וסתים) מִכֹּלָּא דִּיקְנָא דְּהַהִיא תּוּשְׁבַּחְתָּא. דִּיקְנָא דְּסָתִים וְיַקִּיר מִכָּל תִּקּוּנוֹי. דִּיקְנָא דְּלָא יַדְעִין עִלָּאִין וְתַתָּאִין. דִּיקְנָא דְּהִיא תּוּשְׁבַּחְתָּא דְּכָל תּוּשְׁבָּחִין. דִּיקְנָא דְּלָא הֲוִי בַּר נָשׁ נְבִיאָה וְקַדִּישָׁא דְּיִקְרַב לְמֵחֱמֵי לֵיהּ. דִּיקְנָא דְּהִיא תַּלְיָיא בְּשַׂעֲרוֹי עַד טַבּוּרָא דְּלִבָּא. חִוָּורָא כְּתַלְגָּא יַקִּירָא דְּיַקִּירִין. טְמִירָא דִּטְמִירִין. מְהֵימְנוּתָא דִּמְהֵימְנוּתָא דְּכֹלָּא."],[[0,"ותא חזי מה","וכו׳: ובוא וראה, מה בין עתיק לז״א, זה, עתיק, הוא בעל החוטם, מנקב אחד מושפע החיים, ומנקב אחד מושפע חיי החיים, דהיינו אור החיים של תחית המתים. חוטם זה, הוא חלון שבו נושב רוח החיים אל ז״א, וקוראים אותו סליחה. כי רוח החיים הוא הארת החכמה ומחכמה היא סליחת העונות. והוא נחת רוח, התבשמות הרוח. \u0003פרדשקא,\u0004 פירושו חלון לפי הענין. ויש לפרשו ממלא מקום, (כנ״ל בספרא דצניעותא אות ו׳ בהסולם)."],[0,"","פירוש נקב ימין ה״ס חסדים אלא שכלול בו הארת חכמה שה״ס אור חיה. וע״כ נקרא \u0003חיין.\u0004 ונקב שמאל שם עקרו חכמה שהוא \u0003חיין דחיין,\u0004 שמחמתו ומהתכללותו יש \u0003חיין\u0004 בימין."],[1,"דרוחא דנפיק מאינון","וכו׳: כי הרוח היוצא מאלו הנקבים דחוטמא, רוח אחד יוצא לז״א לעורר אותו בגן עדן. ורוח אחד של חיים יוצא ממנו, שבו עתידים לזמן בנו של דוד לדעת חכמה. כי ב׳ רוחין אלו דב׳ נוקבי דפרדשקא הם מבחינת יסוד ומלכות (כנ״ל בספד״צ אות ו׳ ע״ש) וע״כ מרוח של יסוד נמשך לז״א, שהוא מנקב ימין. ומרוח של מלכות שהוא בנקב שמאל נמשך לבריה דדוד, שה״ס מלכות. ומאותו נקב השמאל, מתעורר ויוצא רוח ממוחא סתימאה, שהוא חכמה דא״א, ועתיד לשרות על מלך המשיח. שכתוב, ונחה עליו רוח ה׳. רוח חכמה ובינה רוח עצה וגבורה רוח דעת ויראת ה׳. שואל. הרי יש כאן ד׳ רוחות בכתוב, והרי רוח אחד אנו אומרים, שיוצא מנקב השמאלי דא״א ולמה שלשה. קום ר׳ יוסי על מעמדך. ותתרץ את זה."],[2,"קם ר׳ יוסי","וכו׳: קם ר״י ואמר, בימיו של מלך המשיח לא יאמרו אחד לאחד, למדני חכמה. שכתוב, ולא ילמדו עוד איש את רעהו וגו׳ כי כולם ידעו אותי למקטנם ועד גדולם. ובזמן ההוא יעורר עתיק יומין רוח היוצא ממוח הסתום מכל, שהוא חכמה דא״א. וכשיוציא את זה, כל הרוחות שלמטה יתעוררו עמו. ומי הם הרוחות שלמטה. הן הספירות הקדושות דז״א, שהן ששה רוחות אחרים שהם כך, שכתוב, עליהן רוח חכמה ובינה רוח עצה וגבורה רוח דעת ויראת ה׳. שהם בחינות חג״ת נה״י דז״א."],[3,"דתנינן כתיב וישב","וגו׳: שלמדנו, כתוב, וישב שלמה על כסא ה׳. וכתוב, שש מעלות לכסא, כנגד חג״ת נה״י, ומלך המשיח עתיד לשבת בכסא של שבע מעלות, שש הן כנגד חג״ת נה״י. ועם הרוח של עתיק יומין שעליהם, היוצא מנקב שמאלי של חוטמא כנ״ל, הרי שבע, כמו שלמדנו, א״ר ר״ש, ינוח רוחך לעולם הבא."],[4,"ת״ח כתיב כה","וגו׳: בוא וראה, כתוב, כה אמר ה׳ מארבע רוחות באי הרוח וגו׳. שואל, וכי ארבע רוחות העולם מה עושים כאן, ומשיב, אלא ארבע רוחות יתעוררו, שלשה הם, דהיינו ג׳ פעמים רוח הנאמרים בכתוב, רוח חכמה ובינה וגו׳. והרוח של עתיק הסתום, מחוטמא, הן ארבע. וכך הם, כי כשזה הרוח של החוטמא יוצא, יוצאים עמו ג׳ רוחות הכלולים בג׳ אחרים. כי נאמר ג״פ רוח. ובכל רוח שתי בחינות, דהיינו \u0003רוח\u0004 חכמה ובינה, \u0003רוח\u0004 עצה וגבורה, \u0003רוח\u0004 דעת ויראת ה׳."],[5,"וזמין קב״ה לאפקא","וכו׳: ועתיד הקב״ה להוציא רוח אחד הכלול מכולם, מכל ז׳ רוחות הנ״ל. שכתוב, \u0003מארבע\u0004 רוחות באי הרוח, \u0003ארבע\u0004 רוחות באי, לא כתוב כאן, אלא \u0003מארבע\u0004 רוחות באי, שמשמעו באי הרוח הכלול מארבע רוחות, שהם ששה. כנ״ל ובימיו של מלך המשיח לא יצרכו ללמד אחד לאחד, כי הרוח שלהם כלול מכל הרוחות, ויודע הכל, חכמה ובינה עצה וגבורה דעת ויראת ה׳, משום שהרוח שלהם כלול מכל הרוחות, משום זה כתוב, \u0003מארבע\u0004 רוחות, שהן ארבע הכלולות בשבע מדרגות עליונות שאמרנו. ולמדנו, שכולן כלולות ברוח הזה של עתיק דעתיקין, שהוא א״א, היוצא ממוחא סתימאה שהוא חכמה שלו, לנקב החוטם שלו, שה״ס מלכות שלו (כנ״ל אות ס״ד)."],[6,"ות״ח מה בין","וכו׳: ובוא וראה, מה בין חוטם לחוטם דהיינו בין חוטם דא״א לחוטם דז״א. הוא, כי חוטם דעתיק יומין, שהוא א״א, הוא חיים מכל צדדיו. הן חיי עולם הזה והן חיים של עתיד לבא, כנ״ל. וחוטם של ז״א, כתוב, עלה עשן באפי ואש מפיו תאכל וגו׳. \u0003עלה עשן באפו,\u0004 ומעשן ההוא נדלק אש כשעולה אח״כ עשן, כמ״ש לעיל (ב״ב אות רמ״א בהסולם ע״ש) \u0003גחלים בערו ממנו,\u0004 מהו ממנו. הוא מאותו עשן. כי מן העשן נדלק אש. כנ״ל."],[6,"","פירוש. כמו בחוטם דא״א כן בחוטם דז״א מושפע רוח חיים, שה״ס רוח החכמה הנקרא אור חיה. וההפרש הוא, כי בא״א שכולו ימין, לא יקרה בו שהחכמה תאיר בלי חסדים. וע״כ \u0003חוטמא דעתיק יומין חיין מכל סטרוי.\u0004 מה שאין כן בז״א, שבו יקרה שהחכמה מאירה בלי חסדים, שאז כבה אור החכמה ונעשה חשך (כנ״ל ב״א דף מ״ז אות ל\"ד ד״ה נפק) ונהפך לעשן. וזסו״ה עלה עשן באפו. כי בעון התחתונים מאירה החכמה מן החוטם בלי חסדים, ונהפכה לעשן. וכדי לעורר החסדים, עושה קו האמצעי זווג על מסך דחירק, הממעט ג״ר דשמאל ומיחדו עם הימין (כנ״ל לך י״ג ד״ה ונתבאר) והדינים דמסך דחירק נבחנים ג״כ לעשן, אלא עשן הזה, מדליק את העשן שנעשה מכיבוי החכמה, דהיינו שממעט ושורף הג״ר שלו, שאז מתיחד עם הימין. וז״ש \u0003ומההוא עשן,\u0004 דהיינו עשן שנעשה מכיבוי החכמה, \u0003דליק נור כד סליק תננא לבתר,\u0004 דהיינו העשן מהדינים דמסך דחירק העולה אליו אח״כ, בעת שקו אמצעי מיחדו עם הימין, שאז נדלק העשן של החכמה, ונשרפו הג״ר שלו. וז״ש, \u0003גחלים בערו ממנו, מהו ממנו, מאותו עשן.\u0004 דהיינו מאותו עשן החכמה, שנדלק ע״י עשן דמסך דחירק ונשרפו הג״ר שלו, ונעשו גחלים בוערות. (ועי׳ לעיל בראשית ב׳ אות רמ״א בהסולם, שמביא שם כעין זה)."],[7,"תאנא כד הוה","וכו׳: למדנו, כשרב המנונא סבא רצה להתפלל תפלתו, אמר, לבעל החוטם אני מתפלל לבעל החוטם אני מתחנן. דהיינו לא״א שהוא בעל החוטם. והיינו שכתוב, ותהלתי אחטם לך. שמקרא זה לעתיק יומין אמרו. שהוא א״א, שהחוטם שלו הוא חיים מכל צדדיו."],[8,"תנא אורכא דחוטמא","וכו׳: למדנו, אורך החוטם, שע״ה עולמות מתמלאים מחוטם ההוא, וכולם מתדבקים בז״א. זו היא התשבחה של תקון החוטם. וכל תקוני עתיק יומין נראים ואינם נראים, נראים ליושבים על כסא מדין. ואינם נראים לכל."],[8,"","פירוש מספר \u0003שע״ה\u0004 עולמות רומזים על סוד ואל קין ואל מנחתו לא \u0003שע״ה,\u0004 ועלמין, הוא לשון העלם. משום שקין משך הארת החכמה ממעלה למטה. והפריד קו השמאל מן הימין, וע״כ נתרוקן מאורותיו, וכתוב עליו לא שע״ה. אמנם הזוכה לאורך החוטם דא״א, מתמלאים שע״ה עלמין הנ״ל באפן שלא יתרוקנו אורותיו לעולם."],[9,"פתח ר״ש ואמר","וכו׳: פתח ר״ש ואמר, אוי למי שמושיט ידו בדיקנא היקר העליון, של הסבא הקדוש, שהוא א״א, הנסתר והסתום מכל. דיקנא של תשבחה ההיא, דיקנא, הסתום ויקר מכל תקוניו של א״א, דיקנא, שאין יודעים אותו עליונים ותחתונים, דיקנא, שהוא תשבחה של כל התשבחות, דיקנא, שלא היה אדם נביא וקדוש שיקרב לראותו, דיקנא, שהיא תלויה בשערותיו עד טבור הלב. הוא לבן כשלג, יקר מכל יקר, נסתר מכל נסתר, האמונה של אמונת כל."]],[]],[["תָּאנָא, בִּצְנִיעוּתָא דְּסִפְרָא, דְּהַאי דִּיקְנָא מְהֵימְנוּתָא דְּכֹלָּא, נָפִיק מֵאוּדְנוֹי, וְנָחִית סוֹחֲרָנֵיהּ דְּפוּמָא קַדִּישָׁא, וְנָחִית וְסָלִיק וְחָפֵי, בְּתַקְרוּבְתָּא (סגי) דְּבוּסְמָא טָבָא, חִוָּורָא דְּיַקִּירָא (ס\"א דבדיקניה). וְנָחִית (ס\"א חוורא יקירא דדיקניה נחית) בְּשִׁקּוּלָא, וְחָפֵי עַד טַבּוּרָא. הוּא דִּיקְנָא יַקִּירָא, מְהֵימָנָא שְׁלֵימָא, דְּנַגְדִּין בֵּיהּ י\"ג נְבִיעִין, מַבּוּעִין דִּמְשַׁח רְבוּת טָבָא, בִּתְלַת עֲשַׂר תִּקּוּנִין מִתְתַּקְּנָא.","תִּקּוּנָא קַדְמָאָה. מִתְתַּקֵּן שַׂעֲרָא מִלְּעֵילָּא, וְשָׁארִי מֵהַהוּא תִּקּוּנָא דִּשְׂעַר רֵישֵׁיהּ, דְּסָלִיק בְּתִקּוּנוֹי לְעֵילָּא מֵאוּדְנוֹי, וְנָחִית מִקַּמֵּי פִּתְחָא דְּאוּדְנִין, בְּחַד חוּטָא בְּשִׁקּוּלָא טָבָא, עַד רֵישָׁא דְּפוּמָא.","תִּקּוּנָא תִּנְיָינָא. מִתְתָּקַּן שַׂעֲרָא מֵרֵישָׁא דְּפוּמָא, (וסליק) עַד רֵישָׁא אַחֲרָא דְּפוּמָא, בְּתִקּוּנָא שָׁקִיל.","תִּקּוּנָא תְּלִיתָאָה. מֵאֶמְצָעִיתָא דִּתְחוֹת (ס\"א דהאי) חוֹטָמָא, מִתְּחוֹת תְּרֵין נוּקְבִין, נָפִיק חַד אוֹרְחָא, וְשַׂעֲרָא אִתְפְּסַק בְּהַהוּא אָרְחָא, וּמַלְיָא מֵהַאי גִּיסָא, וּמֵהַאי גִּיסָא שַׂעֲרָא, מְתִקּוּנָא שְׁלִים סוֹחֲרָנֵיהּ דְּהַהוּא אוֹרְחָא.","תִּקּוּנָא רְבִיעָאָה. מִתְתָּקַּן שַׂעֲרָא (ונחית) תְּחוֹת פּוּמָא, מֵרֵישָׁא חֲדָא לְרֵישָׁא חֲדָא, בְּתִקּוּנָא שְׁלִים.","תִּקּוּנָא חֲמִישָׁאָה. תְּחוֹת פּוּמָא נָפִיק אָרְחָא אַחֲרָא, בְּשִׁקּוּלָא דְּאָרְחָא דִּלְעֵילָּא, וְאִלֵּין תְּרֵין אָרְחִין רְשִׁימִין עַל פּוּמָא, מִכָּאן מִכָּאן.","תִּקּוּנָא שְׁתִּיתָאָה. מִתְתַּקֵּן שַׂעֲרָא, וְסָלִיק וְנָפִיק מִלְּרַע לְעֵיל לְרֵישָׁא דְּפוּמָא. וְחָפֵי תַּקְרוּבְתָּא דְּבוּסְמָא טָבָא, עַד רֵישָׁא דְּפוּמָא דִּלְעֵילָּא. וְנָחִית שַׂעֲרָא לְרֵישָׁא דְּפִתְחָא דְּאוֹרְחָא תַּתָּאָה דְּפוּמָא.","תִּקּוּנָא שְׁבִיעָאָה. פָּסִיק שַׂעֲרָא, וְאִתְחָזְן תְּרֵין תַּפּוּחִין, בְּתַקְרוּבְתָּא דְּבוּסְמָא טָבָא, שַׁפִּירָן וְיָאָן לְמֵחזֵי. בְּגִינֵיהוֹן אִתְקְיָים עָלְמָא, הֲדָא הוּא דִכְתִיב, (משלי ט״ז:ט״ו) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים.","תִּקּוּנָא תְּמִינָאָה. נָפִיק חַד חוּטָא דְּשַׂעְרֵי סוֹחֲרָנֵי דְּדִיקְנָא, וְתַלְיָין בְּשִׁקּוּלָא עַד טַבּוּרָא.","תִּקּוּנָא תְּשִׁיעָאָה. מִתְעָרֵי וּמִתְעָרְבִין שַׂעְרֵי דִּיקְנָא, עִם אִינּוּן שַׂעְרֵי דְּתַלְיָין בְּשִׁקּוּלָא, (דתליין) וְלָא נַפְקֵי דָּא מִן דָּא.","תִּקּוּנָא עֲשִׁירָאָה. (מתערבין) נַחְתִּין שַׂעְרֵי תְּחוֹת דִּיקְנָא. וְחַפְּיָין בִּגְרוֹנָא תְּחוֹת דִּיקְנָא.","תִּקּוּנָא חַד סָר. דְּלָא נָפְקִין נִימָא מִן נִימָא, וּמִתְשַׁעְרָן בְּשִׁיעוּרָא שְׁלִים.","תִּקּוּנָא תְּרֵיסָר. דְּלָא תַּלְיָין שַׂעְרֵי עַל פּוּמָא, וּפוּמָא אִתְפְּנֵי מִכָּל סִטְרוֹי. וְיָאָן שַׂעְרֵי סְחוֹר סְחוֹר לֵיהּ.","תִּקּוּנָא תְּלֵיסַר. דְּתַלְיָין שַׂעַרָן בִּתְחוֹת דִּיקְנָא, מִכָּאן וּמִכָּאן, בִּיקָרָא יָאָה, בִּיקָרָא שַׁפִּירָא. מְחַפְּיָין עַד טַבּוּרָא. לָא אִתְחֲזֵי (ס\"א לאתחזאה) מִכָּל אַנְפֵּי תַּקְרוּבָא דְּבוּסְמָא, בַּר אִינּוּן תַּפּוּחִין שַׁפִּירִין חִוָּורִין, דְּמַפִּקִין חַיִּין לְעָלְמָא, וּמְחַזְיָין חֵדוּ לִזְעֵיר אַפִּין.","בִּתְלֵיסָר תִּקּוּנִין אִלֵּין, נַגְדִּין וְנָפְקִין תְּלֵיסַר מַבּוּעִין דִּמְשַׁח רְבוּת, וְנַגְדִּין לְכָל אִינּוּן דִּלְתַּתָּא. וּנְהִרִין בְּהַהוּא מִשְׁחָא. וּמְשִׁיחִין מֵהַהוּא מִשְׁחָא, דְּבִתְלֵיסָר תִּקּוּנִין אִלֵּין. בִּתְלֵיסָר תִּקּוּנִין אִלֵּין אִתְרְשִׁים דִּיקְנָא יַקִּירָא, סְתִימָאָה דְּכֹלָּא, דְּעַתִּיק דְּעַתִּיקִין. מִתְּרֵי תַּפּוּחִין שַׁפִּירָן דְּאַנְפּוֹי, נְהִירִין אַנְפּוֹי דִּזְעֵיר אַנְפִּין, וְכָל חִיוָּור (ס\"א חיזור) וְשׁוּשָן דְּאִשְתַּכְחָן לְתַתָּא, נְהִירִין וּמִתְלַהֲטִין מֵהַהוּא נְהוֹרָא דִּלְעֵילָּא. תִּקּוּנִין תְּלֵיסַר אִלֵּין, אִשְׁתְּכָחוּ בְּדִיקְנָא, וּבִשְׁלֵימוּת דִּיקְנָא בְּתִקּוּנוֹי, אִתְקְרֵי בַּר נָשׁ נֶאֱמָן. דְּכָל דְּחָמֵי דִּיקְנֵיהּ, תָּלֵי בֵּיהּ מְהֵימְנוּתָא.","תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, תְּלֵיסַר תִּקּוּנִין אִלֵּין דְּתַלְיָין בְּדִיקְנָא יַקִּירָא, בִּשְׁבִיעָאָה (מנהון) מִשְׁתַּכְּחֵי בְּעָלְמָא, וּמִתְפַּתְּחֵי בִּתְלֵיסָר תַּרְעֵי דְּרַחֲמֵי. וּמַאן דְּאוֹשִׁיט יְדֵיהּ לְאוּמָאָה, כְּמַאן דְּאוֹמֵי בִּתְלֵיסָר תִּקּוּנֵי דִּיקְנָא. הַאי בַּאֲרִיךְ אַפִּין. בִּזְעֵיר אַפִּין בְּכַמָּה. אָמַר לְרִבִּי יִצְחָק, קוּם בְּקִיּוּמָךְ, וְסַלְסֵל בְּסַלְסְלָא דְּתִקּוּנָא דְּמַלְכָּא (ס\"א בדיקנא) קַדִּישָׁא הֵיאַךְ יִתְתַּקְּנוּן.","קָם רִבִּי יִצְחָק, פָּתַח וְאָמַר, (מיכה ז׳:כ׳) מִי אֵל כָּמוֹךָ נוֹשֵׂא עָוֹן וְגוֹ', יָשׁוּב יְרַחֲמֵנוּ וְגוֹ', תִּתֵּן אֱמֶת לְיַעֲקֹב וְגוֹ'. תָּאנָא, תְּלֵיסַר מְכִילִין אִתְחָזוּן הָכָא, וְכֻלְּהוּ נָפְקִין מִתְּלֵיסַר מַבּוּעִין דִּמְשַׁח רְבוּת דְּתִיקּוּנֵי דִּיקְנָא קַדִּישָׁא, עַתִּיקָא דְּעַתִּיקִין. טְמִירָא דִּטְמִירִין. תָּנָא, תִּקּוּנָא דְּדִיקְנָא טָמִיר וְסָתִים, טָמִיר וְלָא טָמִיר. סָתִים וְלָא סָתִים. בְּתִקּוּנוֹי יְדִיעַ וְלָא יְדִיעַ."],[[0,"תאנא בצניעותא דספרא","וכו׳: למדנו בספרא דצניעותא, שזקן ההוא שהוא אמונת כל. יוצא מתחת אזניו ויורד סביב הפה הקדוש, ויורד ועולה ומכסה במנחה של הבושם הטוב את הלבן של היקר, דהיינו שמכסה עור הפנים דא״א, שהוא לבן, ויורד בשוה ומכסה עד הטבור של הלב. הוא דיקנא היקר האמונה השלמה שנוזלין בו י״ג מבועים הנובעים של שמן המשחה הטוב. בי״ג תקונים היא מתתקנת."],[1,"תקונא קדמאה","וכו׳: תקון הראשון די״ג תקוני דיקנא. השערות מתתקנות למעלה, ומתחילות מאותו התקון דשערות ראשו, העולה בתקונו למעלה מאזניו, ויורד לפני פתח האזנים, בחוט אחד, במשקל טוב עד התחלת הפה. הביאור הוא להלאה."],[2,"תקונא תניינא","וכו׳: תקון הב׳, השערות מתתקנות מראש הפה עד ראש האחר של הפה בתקון שוה."],[3,"תקונא תליתאה","וכו׳: תקון הג׳, מתחת החוטם באמצע, מתחת ב׳ נקבי החוטם, יוצא ארח אחד, והשערות נפסקו מארח הזה, והוא מלא שערות מצד זה ומצד זה של הארח, בתקון שלם, מסביב ארח הזה."],[4,"תקונא רביעאה","וכו׳: התקון הרביעי, מתתקנות השערות תחת הפה מראש אחד לראש השני, בתקון שלם. דהיינו הנקרא שבולת הזקן."],[5,"תקונא חמישאה","וכו׳: התקון החמישי. תחת הפה יוצא אורח אחר במשקל כנגד ארח העליון שמתחת החוטם. ואלו ב׳ אורחות רשומים על הפה מכאן ומכאן, ארח העליון ממעל הפה וארח התחתון מתחת לפה."],[6,"תקונא שתיתאה","וכו׳: תקון הששי. השערות מתתקנות ועולות ויוצאות ממטה למעלה לראש הפה, ומכסה מנחת הבשמים הטובים, עד ראש הפה למעלה, ויורדות משם השערות עד ראש הפתח דאורח התחתון שמתחת הפה."],[7,"תקונא שביעאה","וכו׳: תקון השביעי. השערות נפסקות מלצמוח, ונראים ב׳ פנים, דהיינו פן הימני ופן השמאלי, בלי שערות, במנחת בשמים טובים, יפים וטובים למראה. בשבילם מתקיים העולם. ז״ש, באור \u0003פני\u0004 מלך חיים."],[8,"תקונא תמינאה","וכו׳: תקון השמיני. יוצא חוט אחד של שערות מסביב הזקן, ותלוים במשקל עד הטבור."],[9,"תקונא תשיעאה","וכו׳: תקון התשיעי. השערות מתעוררות ושערות דיקנא מתערבות עם אותן השערות התלויות בגרון, והן במשקל, דהיינו בשוה, ואינן יוצאות זו מזו."],[10,"תקונא עשיראה","וכו׳: תקון העשירי. השערות יורדות תחת הזקן, ומכסות הגרון שמתחת הזקן."],[11,"תקונא חד סר","וכו׳: תקון אחד עשר. שאין שערה יוצאות משערה ומשוערות בשיעור שלם."],[12,"תקונא תריסר","וכו׳: תקון שנים עשר. שעל הפה אין תלויות שערות, והפה נתפנה משערות מכל צדדיו, וסביב סביב לו השערות נאות."],[13,"תקונא תליסר","וכו׳: תקון שלשה עשר. שתלויות שערות מתחת הזקן מכאן ומכאן, דהיינו כל שטח השערות שבאחורי הזקן, ביקר נאה, ביקר יפה, ומכסות עד הטבור דלב, ולא נראה מכל פני מנחת הבשמים חוץ מאלו הפנים היפים הלבנים, שמשפיעים חיים לעולם, ומראים שמחה לז״א."],[14,"בתליסר תקונין","וכו׳: בי״ג תקונים אלו נמשכים ויוצאים י״ג מבועים של שמן המשחה ונמשכים לכל אלו שלמטה, ומאירים משמן הזה, ומשיחים משמן ההוא שבי״ג תקונים אלו. בי״ג תקונים אלו נרשם הדיקנא היקר הסתום מכל של עתיק דעתיקין, שהוא א״א. מב׳ עגולים היקרים של פניו, מאירים פניו של ז״א, וכל כפתור ופרח, דהיינו כל מיני המדרגות, הנמצאים למטה, מאירים ומתלהטים מאור ההוא של מעלה. י״ג תקונים אלו נמצאים בדיקנא, ובשלמות הזקן בתקוניו, נקרא האדם נאמן, שכל שרואה זקנו, תולה בו אמונה."],[15,"תאנא בצניעותא דספרא","וכו׳: למדנו בספרא דצניעותא, י״ג תקונים אלו התלוים בדיקנא היקר, בחדש השביעי דהיינו בעשי״ת, נמצאים בעולם, ונפתחים בי״ג שערי רחמים. ומי שמושיט ידו להשבע בזקנו, הוא כמי שנשבע בי״ג תקוני דיקנא. זה הוא בא״א, שיש בו י״ג תקוני דיקנא. בזעיר אנפין בכמה. כמה תקוני דיקנא יש בו. אמר ר״ש לר׳ יצחק, עמוד על עמדך וסלסל בסלסול התקונים של המלך הקדוש, שהוא א״א, איך הם מתתקנים."],[16,"קם ר׳ יצחק","וכו׳: קם ר״י פתח ואמר, מי אל כמוך נושא עון וגו׳. ישוב ירחמנו וגו׳ תתן אמת ליעקב וגו׳. למדנו י״ג מדות נראות כאן, במקרא הזה, וכולן יוצאות מי״ג מבועים של שמן המשחה של י״ג תקוני דיקנא הקדוש דעתיק דעתיקין הנסתר מכל הנסתרים. שהוא א״א. למדנו, תקוני דיקנא נסתרים וסתומים, נסתר ולא נסתר, סתום ולא סתום, בתקוניו ידוע ואינו \u0003ידוע.\u0004 כלומר להכדאים לו הוא מגולה וידוע, ולשאינו כדאים לו הוא נסתר ולא ידוע."]],[]],[["תִּקּוּנָא קַדְמָאָה. הָא תָּנֵינָן, דְּכָל שַׂעֲרָא וְשַׂעֲרָא וְכָל נִימָא וְנִימָא לָא מִתְדַּבְּקָא לְחֲבֵרְתָּה. וְשָׁאֲרוּ נִימִין דְּדִיקְנָא לְאַתְקְנָא, מְתִקּוּנָא דִּשְׂעַר רֵישָׁא.","הָכָא אִית לְאִסְתַּכְּלָא, אִי כָּל נִימִין דִּשְׂעַר רֵישָׁא, וְנִימִין דְּדִיקְנָא יַקִּירָא עִלָּאָה, בְּחַד נִימָא אִתְכְּלָלוּ, (ס\"א בחד מתקלא אתקלו) אֲמַאי אִלֵּין אֲרִיכִין, וְאִלֵּין לָא אֲרִיכִין. אֲמַאי (ק\"מ) נִימִין דְּדִיקְנָא לָא אֲרִיכִין כּוּלֵי הַאי, וְקַשְׁיָין. וְאִלֵּין דְּרֵישָׁא לָא קַשְׁיָין, אֶלָּא שְׁעִיעִין.","אֶלָּא, כָּל נִימִין שְׁקִילִין דְּרֵישָׁא וְדִיקְנָא. דְּרֵישָׁא אֲרִיכִין עַל כַּתְפִין, לְמֵיגַד לְרֵישָׁא (ד\"א מרישא) דִּזְעֵיר אַפִּין, מֵהַהוּא מְשִׁיכָא דְּמוֹחָא, לְמוֹחָא דִּילֵיהּ. וּבְגִּינֵי כַּךְ לָא הֲווֹ קַשְׁיָין. וְעַל דָּא אִתְחָזוּן לְמֶהֱוִי רְכִיכֵי.","תָּאנָא, מַאי (ע\"ח ע\"א, ק\"מ ע\"א, רס\"ב ע\"א) דִּכְתִּיב, (משלי א׳:כ׳) חָכְמוֹת בַּחוּץ תָּרֹנָּה. וּלְבַסּוֹף כְּתִיב, בָּרְחוֹבוֹת תִּתֵּן קוֹלָהּ. הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. אֶלָּא חָכְמוֹת בַּחוּץ תָּרֹנָּה, כַּד נָגִיד מִמּוֹחָא סְתִימָאָה דַּאֲרִיךְ אַפִּין, לְמוֹחָא דִּזְעֵיר אַפִּין, בְּאִינּוּן נִימִין. כְּאִלּוּ מִתְחַבְּרָאן לְבַר, תְּרֵין (בראשית קמ\"א ע\"ב, ק\"מ) מוֹחִין, וְאִתְעָבִיד חַד מוֹחָא, בְּגִין דְּלֵית קִיוּמָא לְמוֹחָא תַּתָּאָה, אֶלָּא בְּקִיּוּמָא דְּמוֹחָא עִלָּאָה. וְכַד נָגִיד מֵהַאי לְהַאי, כְּתִיב תִתֵּן קוֹלָהּ חַד.","וּבְגִין דְּנָגִיד מִמּוֹחָא לְמוֹחָא בְּאִינּוּן נִימִין (כאלו מתחבראן לבר תרין מוחין ואתעביד חד מוחא באינון נימין) אִינּוּן לָא אִשְׁתְּכָחוּ קְשִׁישִׁין. מַאי טַעְמָא. מִשּׁוּם דְּאִי אִשְׁתַּכְּחוּ קְשִׁישִׁין, לָא נָגִיד חָכְמְתָא לְמוֹחָא בְּהוֹן. בְּגִינֵי כַּךְ, לֵית חָכְמְתָא נָפְקָא מִבַּר נָשׁ דְּאִיהוּ קְשִׁישָׁא (ס\"א קשיא) וּמָארֵי דְּרוּגְזָא. דִּכְתִּיב, (קהלת ט׳:י״ז) דִּבְרֵי חֲכָמִים בְּנַחַת נִשְׁמָעִים. וּמֵהָכָא אוֹלִיפְנָא, מַאן דְּשַׂעְרוֹי דְּרֵישֵׁיהּ קְשִׁישָׁן, לָאו חָכְמְתָא מִתְיַשְּׁבָא עִמֵּיהּ.","וְעַל דָּא אִינּוּן אֲרִיכֵי, לְמֵיתֵי תּוֹעַלְתָּא לְכֹלָּא. מַאי לְכֹלָּא. לְמֵיעַל עַל חוּטָא דְּשִׁדְרָה, דְּמִתְשַׁקְיָין מִן מוֹחָא. וּבְגִין דָּא לָא תָּלֵי שַׂעֲרָא דְּרֵישָׁא עַל שַׂעֲרָא דְּדִיקְנָא. דְּשַׂעֲרָא דְּרֵישָׁא תָּלֵי וְסָלִיק עַל אוּדְנִין לַאֲחוֹרוֹי, וְלָא תָּלֵי עַל דִּיקְנָא, מִשּׁוּם דְּלָא אִצְטְרִיךְ לְאִתְעָרְבָא אִלֵּין בְּאִלֵּין. דְּכֻלְּהוּ מִתְפָּרְשָׁן בְּאָרְחַיְיהוּ.","תָּאנָא, כֻּלְּהוּ שַׂעְרֵי בֵּין דְּרֵישָׁא, בֵּין דְּדִיקְנָא, כֻּלְּהוּ חִוָּורֵי כְּתַלְגָּא. וְתָאנָא, אִינְהוּ דְּדִיקְנָא קְשִׁישָׁאֵי כֻּלְּהוּ. מַאי טַעְמָא. מִשּׁוּם דְּאִינּוּן תַּקִּיפָא דְתַקִּיפִין, לְאַחֲסִין (נ\"א לאחתא) אִינּוּן י\"ג מְכִילָן, מֵעַתִּיק דְּעַתִּיקִין. וַהֲנֵי מְכִילָן מִקַּמֵּי אוּדְנוֹי שַׁרְיָין, וַהֲנֵי מְכִילָן סְתִימָן אִינּוּן. דְּלָא יִתְעָרְבוּן בְּאַחֲרָנִין. (דאתחסינו לתתא והכי תנינא מקמי אודנוי שריין שערי משום דבלחודייהו אינון ולא אתערבו באחרנין).","וְאִי תֵּימָא דְּלֵית אַחֲרָנִין כְּוָותַיְיהוּ. לָא. דְּתַנְיָא תְּלֵיסַר מְכִילָן דְּרַחֲמֵי מֵעַתִּיקָא קַדִּישָׁא: מִי אֵל כָּמוֹךָ, חַד. (ק\"מ) נוֹשֵׂא עָוֹן, תְּרֵי. וְעוֹבֵר עַל פֶּשַׁע, תְּלַת. לִשְׁאֵרִית נַחֲלָתוֹ, אַרְבַּע. לֹא הֶחֱזִיק לָעַד אַפּוֹ, חָמֵשׁ. כִּי חָפֵץ חֶסֶד הוּא, שִׁית. יָשׁוּב יְרַחֲמֵנוּ, שִׁבְעָה. יִכְבּוֹש עֲוֹנוֹתֵינוּ, תְּמַנְיָא. וְתַשְׁלִיךְ בִּמְצוּלוֹת יָם כָּל חַטֹּאתָם, תִּשְׁעָה. תִּתֵּן אֱמֶת לְיַעֲקֹב, עַשְׂרָה. חֶסֶד לְאַבְרָהָם, חַד סָר. אֲשֶׁר נִשְׁבַּעְתָּ לַאֲבוֹתֵינוּ, תְּרֵיסָר. מֵימֵי קֶדֶם, תְּלֵיסַר. לָקֳבֵיל דָּא, אֵל רַחוּם וְחַנּוּן וְגוֹ', אִינּוּן לְתַתָּא.","וְאִי תֵּימָא, מֹשֶׁה אֵיךְ לָא אָמַר אִלֵּין עִלָּאִין. (קל\"ח) אֶלָּא, מֹשֶׁה לָא אִצְטְרִיךְ, אֶלָּא לְאֲתָר דְּדִינָא אִשְׁתְּכַח, וּבַאֲתָר דְּדִינָא אִשְׁתְּכַח, לָא בָּעֵי הָכִי לְמֵימַר. וּמֹשֶׁה לָא אָמַר, אֶלָּא בְּעִידָנָא דְּיִשְׂרָאֵל חָאבוּ, וְדִינָא הֲוָה תַּלְיָיא, וּבְגִינֵי כַּךְ לָא אָמַר מֹשֶׁה, אֶלָּא בַּאֲתָר דְּדִינָא אִשְׁתְּכַח. אֲבָל בְּהַאי אֲתָר, סִדוּרָא דִּשְׁבָחָא דְּעַתִּיק יוֹמִין מְסַדֵּר נְבִיאָה.","וְאִינּוּן תְּלֵיסָר תִּקּוּנִין דְּדִיקְנָא עִלָּאָה קַדִישָׁא, טְמִירָא דִּטְמִירִין, תַּקִּיפִין, לְתַּבְרָא וּלְאַכְפְּיָיא כָּל גִּזְרֵי דִּינִין. מַאן חָמֵי דִּיקְנָא עִלָּאָה קַדִּישָׁא, טְמִירָא דִּטְמִירִין דְּלָא אַכְסִיף (קל\"ב) (ס\"א אתכסי) מִנֵּיהּ. וּבְגִין כָּךְ, כָּל שַׂעֲרוֹי קְשִׁישִׁין, וְתַקִיפִין בְּתִקּוּנוֹי."],[[0,"תקונא קדמאה","וכו׳: תקון הראשון. הרי למדנו, שכל שערה ושערה וכל נימא ונימא אינה מתדבקה לחברתה. והנימין דדיקנא מתחילות להתתקן מן התקון דשערות ראש. דהיינו שמתחילות מפאתי הראש."],[0,"","פירוש. כבר ידעת ששורש השערות ה״ס ה \u0003י׳\u0004 שנכנסה ל \u0003אור\u0004 הבינה ונעשה ל \u0003אויר.\u0004 דהיינו שג״ר דחכמה נעלמו ונשארו רק ו״ק שהוא אור הרוח הנקרא אויר. אמנם הן פרצוף שלם של כח״ב תו״מ, דהיינו הע״ס דכלים, שהלבישו את ג״ר דחכמה אלו, לפני שהסתלקו מחמת הי׳ שעלתה לאור. וכיון שהאור נסתלק לשורשו, נשארו הכלים בבחינת מותרי מוחא, והוכרחו לצאת לחוץ מראש מחמת עוביותם. וכיון ששלט בהן ה \u0003י׳\u0004 שנכנסה לאור, שה״ס המלכות שעלתה לבינה, המחלקת כל מדרגה, לכו״ח ובינה ותו״מ, נחלקו בהכרח גם הן לב׳ חצאים, אשר כתר וחכמה שבהן, נתדבקו על הגולגלתא, בסוד שערות רישא, שהסיום שלהם הוא פאתי הראש, ששם כח ה \u0003י׳\u0004 שנכנסה ב \u0003אור\u0004 ונעשה \u0003אויר,\u0004 שה״ס הפרסה המסיימת מדרגת ראש שבהם. ובינה ותו״מ שבהן יצאו לחוץ ממדרגת ראש, ונתדבקו בפנים בלחי התחתון בסוד שערות דיקנא."],[0,"","וז״ש, \u0003ושארו נימין דדיקנא לאתקנא מתקונא דשער רישא,\u0004 דהיינו בפאתי הראש, ששם ה״ס הפרסה המבדלת בין שערות ראש לשערות דיקנא, ומפרסא זו הן יוצאות. ומתוך שפרצוף השערות בכללו היו מלבישים לג״ר דחכמה, שהפרסא לא שלט שמה, שהמלכות ירדה מן הפרסא למקומה במלכות דמדת הדין. ע״כ אפילו אחר שה \u0003י׳\u0004 עלתה לאור הבינה, ונתקנה המלכות דצמצום ב׳, הרי נשאר בהם גם כח המלכות דצמצום א׳ ממלכות דמדת הדין. וב׳ המלכיות שולטים בסיום פאתי הראש, וכמו כן בשערות דיקנא הנמשכים מהם. וז״ש, \u0003דכל שערא ושערא וכל נימא ונימא לא מתדבקא לחברתה.\u0004 כלומר, שהשערות הנמשכות מב׳ מלכיות אלו, אין מתערבים ואין מתדבקים זה בזה אלא כל אחת שולטת לפי עצמה. כי אם היו מתדבקות זו בזו, היתה המלכות הנמתקת בבינה מתבטלת במלכות דצמצום א׳, דמדת הדין."],[1,"הכא אית לאסתכלא","וכו׳: כאן יש להסתכל. אם כל הנימין של שערות ראש, והנימין של שערות דיקנא היקר והעליון נכללו בנימא אחד. כלומר שהן מדרגה אחת ויוצאות משורש אחד, מקרומא דאוירא, כנ״ל, א״כ, למה אלו, שערות ראש, ארוכות, ואלו, שערות דיקנא, אינן ארוכות, ולמה הנימין דשערות דיקנא, אינן ארוכות כל כך, והן קשות. ואלו של ראש, אינן קשות אלא חלקות."],[2,"אלא כל נימין","וכו׳: ומשיב, אלא כל הנימין, של הראש ושל הזקן הן שקולות, כל אחת לפי בחינתה. ושל ראש הן ארוכות עד הכתפים, כדי להמשיך אל הראש דז״א, מהמשכה ההיא של המוח שלו, אל המוח דז״א. ומשום זה אינן קשות, וע״כ ראויות להיות רכות."],[3,"תאנא מאי דכתיב","וכו׳: למדנו, מה שכתוב, חכמות בחוץ תרנה, ולבסוף כתוב, ברחובות תתן קולה. מקרא זה אין ראשו סופו, ואין סופו ראשו, שמתחילה אומר חכמות לשון רבים, ולבסוף אומר, קולה לשון יחיד. ומשיב, אלא \u0003חכמות בחוץ תרנה,\u0004 שאומר לשון רבים, הוא, כשנמשך החכמה ממוח הסתום דא״א באלו הנימין, דשערות רישא, אל המוח דז״א. שהוא כאלו מתחבר בחוץ, במקום ז״א, שהוא מחוץ לא״א, ב׳ מוחין, דהיינו חכמה דא״א וחכמה דז״א, ונעשים מוח אחד, משום שאין קיום למוח התחתון דז״א, אלא בקיום מוח העליון דא״א, וע״כ נאמר חכמות, להיותם ב׳ חכמות. ואחר שנמשך מזה לזה, דהיינו אחר שחכמה דז״א כבר קבלה החכמה ממוחא סתימאה, כתוב, \u0003תתן קולה,\u0004 שהיא חכמה אחת. חכמה דז״א."],[4,"ובגין דנגיד ממוחא","וכו׳: ומשום שהחכמה נמשכת ממוח דא״א למוח דז״א דרך אלו הנימין דשערות רישא, הן אינן נמצאות קשות. מהו הטעם. הוא משום, שאם היו נמצאות קשות לא היתה החכמה נמשכת בהם למוח ז״א. ומשום זה אין חכמה יוצא מאדם שהוא קשה ובעל כעס. שכתוב, דברי חכמים בנחת נשמעים. ומכאן למדנו, מי ששערות ראשו קשות, אין החכמה מתישבת בו."],[5,"וע״ד אינון אריכי","וכו׳: וע״כ, שערות רישא הן ארוכות, להביא תועלת לכל. מהו לכל. היינו כדי שהחכמה תכנס דרך השערות לחוט השדרה, שהוא נשקה מן המוח, וע״כ הן ארוכות עד רישי דכתפין. ששם חוט השדרה. ומשום זה אין שערות ראש תלויות על שערות הזקן, כי שערות ראש תלויות ועולות מעל האזנים לאחורי הראש, ואינן תלויות על הזקן, משום שאין צריכים לערב אלו באלו, שכל אחד מתחלק לפי דרכו."],[5,"","ביאור הדברים. תחלה יש להבין לפי מה שנתבאר לעיל (באות ל״ד) שגלגלתא ה״ס \u0003ם׳\u0004 דצלם, וע״כ נדבקו בה השערות, משום שב \u0003ם׳\u0004 דצלם אין ה \u0003י\u0004 ׳ יוצאת מאויר. והפנים ממצח ולמטה ה״ס \u0003ל׳ צ׳\u0004 דצלם, שבהם יוצאת ה \u0003י׳\u0004 מאויר, וע״כ ממצח ולמטה אין שערות. וכיון שכן, למה נדבקו שוב שערות דיקנא בפנים ובלחי התחתון דא״א. הרי הם כבר ממצח ולמטה. והענין הוא, כי כבר נתבאר שבאמת שערות ראש ושערות דיקנא פרצוף אחד הן, אלא כמו שהמסך דצמצום ב׳, שמתחת חכמה סתימאה דא״א, הוציא בינה ותו״מ דפנימיות הראש דא״א, אל הגוף, כך הוציא בינה ותו״מ דפרצוף השערות מן הראש אל הגוף, באפן שהן בפנימיות הראש דא״א והן בחיצוניות הראש לא נשארו אלא כתר וחכמה, ובינה ותו״מ דפנימיות וחיצוניות הראש, יצאו מראש אל הגוף, ונתפשטו עד החזה שלו, הנקרא טבורא דלבא. כמ״ש לעיל (אות ע״ג) \u0003דהאי דיקנא מהימנותא\u0004 וכו׳ \u0003וחפי עד טבורא.\u0004"],[5,"","ונודע שגם הגוף מתחלק \u0003למל״צ,\u0004 דצלם, אשר מפה עד החזה הוא \u0003ם׳\u0004 דצלם, ושם הוא בחינת או״א עלאין, שאין ה \u0003י׳\u0004 יוצאת מאויר שלהם לעולם. ומחזה עד טבור דגוף, הוא בחינת ישסו״ת, דהיינו \u0003ל׳\u0004 דצלם, שבהם יוצאת ה \u0003י׳\u0004 מאויר. ומטבור ולמטה הוא \u0003צ׳\u0004 דצלם. ולפיכך גם השערות דיקנא שיצאו מחיצוניות הראש דא״א נתדבקו בלחי התחתון, וחופפים על חלק העליון מן הגוף מפה עד החזה, ששם \u0003ם׳\u0004 דצלם, שאין ה \u0003י׳\u0004 יוצאת שם מן האויר. באפן, שכו״ח דשערות נדבקו ב \u0003ם׳\u0004 דראש א״א, ובינה ותו״מ דשערות נדבקו ב \u0003ם׳\u0004 דגוף א״א."],[5,"","וזה הכלל. אין שערות נמשכות אלא מ \u0003י׳\u0004 שנכנסה באור ונעשה אויר. ואין שערות מתדבקות בקביעות אלא ב \u0003ם׳\u0004 דצלם, משום ששם גם ה \u0003י׳\u0004 שנכנסה באור היא בקביעות, שאינה יוצאת מאויר לעולם. משא״כ ב \u0003ל״צ\u0004 דצלם ששם ה \u0003י׳\u0004 חוזרת ויוצאת מן האויר, אי אפשר שתהיינה שמה שערות בקביעות. ובכל פרצוף יש ד׳ \u0003ממין, ם׳\u0004 דראש, שהיא הגלגלתא, ו \u0003ם׳\u0004 דגוף בכללו, שהיא מפה עד החזה. ו \u0003ם׳\u0004 דנה״י בפרטות, שה״ס ב׳ פרקי נצח והוד שלמעלה מיסוד. כי נה״י לפי עצמם נחלקים למל״צ כמ״ש במקומו. ו \u0003ם׳\u0004 דחג״ת בפרטות, שהוא תחת אצילי הידים. כי החג״ת לפי עצמם נחלקים למל״צ. ולפיכך יש ד׳ מקומות של שערות קבועות א׳, שערות ראש ב \u0003ם׳\u0004 דראש. ב׳, שערות דיקנא ב \u0003ם׳\u0004 דגוף. ג׳, שערות זקן התחתון בם׳ דנה״י. ד׳, הוא בראש חלק העליון של הידים שהוא \u0003ם׳\u0004 דחג״ת. והנה נתבאר ששערות דיקנא ואו״א עלאין הם כמעט בחינה אחת, ששניהם בחי׳ \u0003ם׳\u0004 דצלם, ומקום שניהם הוא מפה עד החזה. ובזה תבין מ״ש האריז״ל שע״כ לא נזכרו או״א באדרא רבא, משום שאו״א בדיקנא אתכלילו. שלכאורה תמוה, מה ענין או״א אצל דיקנא. ובהאמור תבין שהם כמעט בחינה אחת ממש. ולפיכך נפסקים שערות דיקנא על החזה דא״א, הנקרא טבורא דלבא, משום שמשם ולמטה עד הטבור, כבר הוא מקום ישסו״ת, שה״ס \u0003ל׳\u0004 דצלם. שבו יוצאת ה \u0003י׳\u0004 מאויר. ודומה כמו מצח דא״א."],[5,"","וזה אמרו (באות צ״ב) \u0003אלא כל נימין שקילין דרישא ודיקנא,\u0004 דהיינו שהן פרצוף אחד בן ע״ס כח״ב תו״מ, כנ״ל. \u0003דרישא אריכין על כתפין,\u0004 אריכות מורה על הארת חכמה, \u0003למיגד לרישא דז״א,\u0004 וכו׳, כי כל פרצוף השערות משפיע לז״א, שערות רישא דא״א לראש דז״א, ושערות דיקנא דא״א לשערות דיקנא דז״א, כל אחד להבחינה שכנגדו. כמ״ש במקומו. וז״ש (באות צ״א) \u0003נימין דדיקנא לא אריכין כולי האי,\u0004 כלומר, שאין בהם כל כך חכמה כמו שערות ראש, משום שהם ממסך דפאתי הראש ולמטה. \u0003וקשיין,\u0004 כי מתוך ששערות דיקנא נמצאים מתחת המסך שבפאתי הראש המובא לעיל (בהסולם אות צ׳) ע״כ כבר יש בהם דינים, וע״כ הם קשים משא״כ שערות רישא, כיון שהמסך נמצא בפאתי הראש למטה, אין כח המסך יכול לפעול למעלה ממקום מציאותו וע״כ אין בהם דינים. וז״ש, \u0003וע״ד אתחזון למהוי רכיכי\u0004 כי אין בהם דינים ולפיכך. מושפע בהם החכמה למוח דז״א. בסו״ה חכמות בחוץ תרנה."],[5,"","וז״ש (באות צ״ה) \u0003ובג״ד לא תלי שערא דרישא על שערא דדיקנא\u0004 וכו׳ \u0003דלא אצטריך לאתערבא אלין באלין,\u0004 כי שערות רישא חשובים הרבה על שערות דיקנא, \u0003דכלהו מתפרשן בארחייהו,\u0004 שהן ב׳ בחינות מיוחדות, וכל אחת מתפרשת לפי דרכה."],[6,"תאנא כלהו שערי","וכו׳: למדנו, כל השערות בין של ראש ובין של הזקן, דא״א, כולן לבנות כשלג. ולמדנו, אלו של הזקן, כולן קשות. מה הטעם. הוא משום שהן חזקות מכל חזק להוריד לתחתונים אלו י״ג מדות, מי״ג תקוני דיקנא, שבעתיק דעתיקין, שהוא א״א. ואלו י״ג מדות מתחילות מלפני האזנים. ואלו י״ג מדות הן סתומות כדי שלא תתערבנה באחרות. בי״ג מדות דז״א."],[7,"ואי תימא דלית אחרנין","וכו׳: ואם תאמר שאין אחרות כמוהן. לא כן. כי למדנו, י״ג מדות הרחמים מעתיקא קדישא הן, \u0003מי אל כמוך,\u0004 אחת. \u0003נושא עון,\u0004 שתים. \u0003ועובר על פשע,\u0004 שלש. \u0003לשארית נחלתו,\u0004 ארבע. \u0003לא החזיק לעד אפו,\u0004 חמש. \u0003כי חפץ חסד הוא,\u0004 שש. \u0003ישוב ירחמנו,\u0004 שבע. \u0003יכבוש עונותינו,\u0004 שמונה. \u0003ותשליך במצולות ים כל חטאתם,\u0004 תשע. \u0003תתן אמת ליעקב,\u0004 עשר. \u0003חסד לאברהם,\u0004 אחת עשרה. \u0003אשר נשבעת לאבותינו,\u0004 שתים עשרה. \u0003מימי קדם,\u0004 שלש עשרה. וכנגד אלו, יש י״ג מדות שבז״א, שהם אל רחום וחנון ארך אפים וגו׳. שהן למטה. בז״א."],[8,"ואי תימא משה","וכו׳: ואם תאמר, איך לא אמר משה אלו י״ג מדות העליונים דא״א, שהן, מי אל כמוך וגו׳. אלא שאמר אל רחום וחנון, שהן י״ג מדות דז״א. ומשיב, אלא משה לא היה צריך רק למקום שהדין נמצא, שהוא ז״א, ובמקום שהדין נמצא אינו צריך לומר כך, דהיינו י״ג מדות דא״א. ומשה לא אמר, אלא בשעה שחטאו ישראל, והדין היה תולה עליהם, ומשום זה לא אמר משה י״ג מדות הרחמים, אלא במקום שהדין נמצא, דהיינו בז״א. אבל במקום זה שהוא סדר השבח של י״ג מדות דעתיק יומין, דהיינו מי אל כמוך וגו׳, מסדר אותם הנביא."],[9,"ואינון תליסר תקונין","וכו׳: ואלו י״ג תקונים דדיקנא עלאה קדישא דא״א, הן נסתרות שבנסתרות, והן חזקות לשבור ולהכניע כל גזרות הדינים, מי ראה דיקנא העליון הקדוש, הנסתר שבנסתרות, שלא יבוש ממנו. ומשום זה כל שערותיו קשות, וחזקות בתקונן."],[9,"","פירוש. כי האורות הגדולים ביותר, המכונים בני חיי ומזוני, אינם תלוים בזכות, אלא במזלא, שה״ס הארת י״ג תקוני דיקנא האלו. וע״כ הצדיקים הגדולים, אחר שכבר זככו את גופם להיות כמלאכי השרת, והגיע זמנם לזכות באלו האורות הגדולים שהם בני חיי ומזוני, צריכים לקבל מקודם העוביות והדינים המושפעים ע״י שערות דיקנא הללו, שנקראות מזל, ואח״כ הם זוכים על ידיהן בני חיי ומזוני. ובעת שמושפע להם העוביות דשערות דיקנא הללו אחר כל זיכוכם הנפלא, שחשבו שהם כבר זכים כמלאכי השרת, הנה הם בושים ונכלמים מאד בעוביות הזו שנפלו בה פתאום. וז״ש, \u0003מאן חמי דיקנא עלאה\u0004 וכו׳ \u0003דלא אכסיף מניה.\u0004"]],[]],[["וְאִי תֵּימָא, אִי הָכִי הָא שַׂעְרֵי דִּלְתַתָּא, אִינּוּן אוּכָמֵי, אֲמַאי לָא הֲווֹ דָּא כְּדָּא. דְּתַנְיָא כְּתִיב, (שיר השירים ה׳:י״א) קְווּצּוֹתָיו תַּלְתַּלִּים שְׁחוֹרוֹת כָּעוֹרֵב. וּכְתִיב, (דניאל ז׳:ט׳) וּשְׂעַר רֵישֵׁיהּ כַּעֲמַר נְקֵא. לָא קַשְׁיָא, הָא בְּדִיקְנָא עִלָּאָה, הָא בְּדִיקְנָא תַּתָּאָה. וְעַל דָּא, כַּד אִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל, אִתְיְיהִיבַת בְּאֵשׁ שְׁחוֹרָה עַל גַּבֵּי אֵשׁ לְבָנָה. וְעִקָּרָא דְּמִלָּה מִשּׁוּם דְּהָנֵי שַׂעְרֵי בְּגִין דְּמִמּוֹחָא אִשְׁתְּכָחוּ לְאִתְמַשְּׁכָא לְמוֹחָא דִּלְתַּתָּא וְאִינּוּן לְעֵילָּא מִן דִּיקְנָא דִּיקְנָא בִּלְחוֹדוֹי הוּא. וְכָל תִּקּוּנוֹי בִּלְחוֹדֵיהוֹן אִשְׁתְּכָחוּ. דִּיקְנָא בִּלְחוֹדוֹי. וְשַׁעְרֵי בִּלְחוֹדַיְיהוּ.","תִּקּוּנָא קַדְמָאָה תִּקּוּנָא דְּשָׁארִי מֵרֵישָׁא דְּשַׂעֲרֵי דְּרֵישָׁא. וְתָאנָא, כָּל תִּקּוּנֵי דִּיקְנָא לָא אִשְׁתְּכַח אֶלָּא (מחומא דלבא) מִמּוֹחָא דְּרֵישָׁא, (ס\"א מתיקוני דרישא) וְהָכָא לָא פָּרִישׁ הָכִי, דְּהָא לָא הֲוִי. אֶלָּא תִּקּוּנָא דָּא, דְּנָחִית מִן רֵישָׁא דְּשַׂעְרֵי דְּרֵישָׁא, הָכִי אִשְׁתְּכַח. (חסר כאן)","וּמֵהַאי דִּיקְנָא אִשְׁתְּמוֹדַע, כָּל מַה דַּהֲוִי בְּרֵישָׁא, דְּאֶלֶף עָלְמִין דְּחַתִּימִין (ס\"א אלף עלמין חתימין) בְּעִזְקָא דְּדַכְיָא. עִזְקָא, דְּכָלִיל כָּל עִזְקִין.","אוֹרְכָּא דְּכָל שַׂעֲרָא, דְּנָחִית מִקַּמֵּי אוּדְנוֹי, לָא הֲוִי אֲרִיכָא. וְלָא אִתְדְּבַק דָּא בְּדָא, וְלָא (ס\"א דכלא) נַחְתִּין. אִלֵּין שַׂעֲרִין. מִכַּד נַגְדִּין אִתְמַשְּׁכָן (ס\"א אלא מכד נחתין אלין, שערין. נגדין ואתמשכן) וְתַלְיָין.","וְשִׁירוּתָא דְּתִקּוּנָא קַדְמָאָה, תְּלָתִין וְחַד קוֹצֵי, שְׁקִילָן, אִתְמַשְּׁכָן עַד רֵישָׁא דְּפוּמָא. וּתְלַת מְאָה וְתִשְׁעִין נִימִין אִשְׁתַּכְּחָן בְּכָל קוֹצָא וְקוֹצָא.","תְּלָתִין וְחַד קוֹצֵי שְׁקִילִין, דַּהֲווּ בְּתִקּוּנָא קַדְמָאָה תַּקִּיפִין, לְאַכְפְּיָיא לְתַתָּא, כְּחוּשְׁבָּן אֵ\"ל. מַהוּ אֵ\"ל. תַּקִּיף יָכוֹל. וּבְכָל קוֹצָא וְקוֹצָא, מִתְפָּרְשִׁין תְּלָתִין וְחַד עָלְמִין, תַּקִּיפִין שָׁלְטִין, לְאִתְעָיְינָא (ס\"א לאתפשטא) (ס\"א לאכפיא, ואתפשטו) ל\"א בְּהַאי סְטָר, וְלֹ\"א בְּהַאי סְטָר. וְכָל עָלְמָא וְעָלְמָא מִנֵּיהּ, מִתְפְּרַשׁ לְאֶלֶף עָלְמִין דִּכְסִיפִין לְעִדּוּנָא רַבָּא. וְכֹלָּא סָתִים בְּרֵישָׁא דְּדִיקְנָא, דְּכָלִיל תַּקִּיפָא, וּכְלִילָן בְּהַאי אֵ\"ל. וְעִם כָּל דָא, הַאי אֵ\"ל אִתְכַּפְיָיא לְרַחֲמֵי, דְּרַחֲמֵי דְּעַתִּיק יוֹמִין, (אתבסם) וְאִתְכְּלַל וְאִתְפָּשַּׁט בֵּיהּ.","אֲמַאי עַד פּוּמָא. מִשּׁוּם דִּכְתִּיב, (דניאל ז׳:י׳) דִּינָא יְתִיב וְסִפְרִין וְגוֹ'. מַאי דִּינָא יְתִיב. יְתִיב לְאַתְרֵיהּ דְּלָא שַׁלְטָא. הֲדָא הוּא דִכְתִיב, (ישעיהו ט׳:ה׳) פֶּלֶא יוֹעֵץ אֵל גִּבּוֹר. אֵל דְּהוּא גִּבּוֹר, וְאִתְבְּסָם בְּדִיּוּקְנָא (ס\"א בדיקנא) קַדִּישָׁא דְּעַתִּיק יוֹמִין. וְרָזָא דִּכְתִּיב, מִי אֵל כָּמוֹךָ בְּעַתִּיק יוֹמִין אִתְּמַר, בְּתִקּוּנָא קַדְמָאָה דְּדִיקְנָא קַדִּישָׁא עִלָּאָה.","עָלְמָא קַדְמָאָה, דְּנָפִיק מְתִּקוּנָא קַדְמָאָה, שַׁלִּיט וְנָחִית. וְסָלִיק לְאֶלֶף אַלְפִין וְרִבּוֹא רִבְּבָן מָארֵי תְּרִיסִין. וּמִנֵּיהּ מִתְאַחֲדִין, בְּקִסְטָא בְּעִזְקָא רַבָּא.","עָלְמָא תִּנְיָינָא. דְּנָפִיק מֵהַאי תִּקּוּנָא. שַׁלִּיט וְנָפִיק, וְנָחִית וְסָלִיק, לְשִׁבְעָה וְחַמְשִׁין אֶלֶף דַּרְגִּין, מָארֵי דִּיבָבָא. וּמִתְאַחֲדָן מִנֵּיהּ, לְאַכְפְּיָיא בְּקוּדְלָא בְּחִיוָּרָא. (ס\"א בחיזרא)","עָלְמָא תְּלִיתָאָה. דְּנָפִיק מֵהַאי תִּקּוּנָא שַׁלִּיט וְנָחִית, וְסָלִיק לצ\"ו אַלְפִין מָארֵי דִּילָלָה, וּמִתְאַחֲדָן מִנֵּיהּ (בבוסיטא לקוסטירא) (ס\"א כבוסינא לקוסרא) (בבוצינא קמורא), וּמֵהַאי תִּקּוּנָא, מִתְכַּפְיָין כֻּלְּהוּ, וּמִתְבַּסְּמָן בִּמְרִירָא דְּדִמְעִין, דְּמִתְבַּסְּמִין בְּיַמָּא רַבָּא.","מַאן חָמֵי תִּקּוּנָא דָא, דְּדִיקְנָא קַדִּישָׁא, עִלָּאָה, יַקִּירָא, דְּלָא אַכְסִיף מִנֵּיהּ. מַאן חָמֵי טְמִירוּתָא (ס\"א יקירותא) דְּקוֹצִין דְּשַׂעְרֵי דְּתַּלְיָין מֵהַאי סָבָא. יְתִיב בְּעִיטְרָא דְּעִטְרִין, עִטְרִין דְּכָל עִטְרִין. עִטְרִין דְּלָא אִתְכָּלָלוּ בְּעִטְרִין. עִטְרִין דְּלָא כִּשְׁאַר עִטְרִין. עִטְרִין, דְּעִטְרִין דִּלְתַּתָּא מִתְאַחֲדָן מִנְּהוֹן. וּבְגִין כָּךְ, הָנֵי תִּקּוּנִין, אִינּוּן תִּקּוּנִין דִּלְתַּתָּא מִנְּהוֹן מִתְאַחֲדִין.","תִּקּוּנֵי דְּאִתְתְּקַן, דְּאִצְטְרִיךְ לְאִתְבָּרְכָא, מַאן דְּבָעֵי בְּרָכָה. דְּכָל תִּקּוּנִין דְּאִתְתְּקַן בְּקָבְלֵהוֹן, בִּרְכָאן מִשְׁתַּכְּחִין (לקבליהון) וְאִתְעָבִיד מַה דְּאִתְעָבִיד. כֹּלָּא כָּלִיל בְּהָנֵי תִּקּוּנִין. כֹּלָּא זַקְפָן לָקָבְלֵיה תִּקּוּנִין דְּמַלְכָּא תַּקִּיפָא, עַתִּיקָא, סְתִימָא דְּכֹלָּא. וְכֻלְּהוּ אִתְבַּסְּמָן מִתִּקּוּנִין אִלֵּין. (דמלכא עתיקא)","תָּאנָא. אִי עַתִּיק דְּעַתִּיקִין, קַדִּישָׁא דְּקַדִּישִין, לָא אִתְתְּקַּן בְּאִלֵּין תִּקּוּנִין, לָא אִשְׁתְּכָחוּ עִלָּאִין וְתַתָּאִין. וְכֹלָּא הֲוִי כֹּלָּא הֲוִי. וְתַנְיָא, עַד כַּמָה זְהִירִין אִלֵּין (ס\"א אתתקן באלין ל\"ג) תִּקּוּנֵי דְּדִיקְנָא. עַד תְּלֵיסַר (דלתתא), וְכָל זִמְנָא דִּתְלֵיסָר אִלֵּין מִשְׁתַּכְּחִין, זְהִירִין אִלֵּין דִּלְתַתָּא. וְכֹלָּא. בְּחוּשְׁבָּנָא דְּאִלֵּין תְּלֵיסַר, אִשְׁתְּכַח דִּיקְנָא דְּמַלְכָּא עַתִּיקָא יַקִּירָא מִכֹּלָּא. כֹּלָּא בְּחַד אִיהוּ טְמִירָא וְיַקִּירָא."],[[0,"","[א] \u0003ואי תימא אי\u0004 וכו׳: ואם תאמר, אם כן, הרי השערות שלמטה, של ז״א, הן שחורות, ולמה לא היו אלו כאלו דא״א שהן לבנות. שלמדנו, כתוב, קווצותיו תלתלים שחורות כעורב. וכתוב, ושער רישיה כעמר נקא. דהיינו לבנות. שהכתובים סותרים זה את זה. ומשיב, לא קשה. כאן שאומר, כעמר נקא, הוא בזקן העליון דא״א. וכאן שאומר, שחורות כעורב, הוא בדיקנא התחתון דז״א. וע״כ כשניתנה התורה לישראל, ניתנה באש שחורה על אש לבנה."],[0,"","פירוש כמו אותיות התורה, שזולת הקלף הלבן אין להם שום מציאות, ועכ״ז האותיות בעצמן הן שחורות. כך התורה שלמעלה שה״ס ז״א כלול מחסד וגבורה, שה״ס אש לבנה ואש שחורה, וכך הן בחינות שערות דיקנא שהן בשורשן בא\"א, אש לבנה, ובז״א אש שחורה."],[0,"","[ב] \u0003ועקרא דמלה משום\u0004 וכו׳: ועיקר הדבר, משום ששערות אלו, להיותם נמצאים מן המוח, להמשך למוח התחתון, דז״א, הן למעלה משערות דיקנא. והדיקנא היא בפני עצמה, וכל תקוני דיקנא נמצאים בפני עצמם. הזקן הוא בפני עצמו, ושערות ראש הן בפני עצמן."],[1,"תקונא קדמאה","וכו׳: תקון הראשון של שערות דיקנא. הוא תקון המתחיל מתחילת שערות של הראש, דהיינו מפאתי הראש, שהיא ראשית שערות ראש ממטה למעלה, וה״ס מלכות שלהן. (כמ״ש לעיל אות ע״ד) ולמדנו, כל תקוני דיקנא אינם נמצאים אלא ממוח הראש. וכאן, בתקון הראשון, אינו מפרש כך, כי אומר שנמצא מפאתי הראש, משום שהוא אינו נמצא ממוח הראש. אלא מפאתי הראש. כי מוחא סתימאה דא״א מתחיל להשפיע מתקון ב׳ והלאה, ולא בתקון א׳. שהוא שורש שערות הדיקנא, ומטרם נמתקה המלכות במדת הרחמים. כמ״ש לפנינו. וע״כ תקון זה הראשון כך הוא נמצא, שיורד מתחילת שערות הראש. ולא ממוחא סתימאה."],[2,"ומהאי דיקנא אשתמודע","וכו׳: ומכללות דיקנא זו, נודע כל מה שהוא בראש, דהיינו אלף העולמות החתומים בטבעת טהורה, טבעת הכולל כל הטבעות. שה״ס חכמה סתימאה שבראש דא״א."],[2,"","פירוש. כי חכמה מרומזת באלף, בסוד ואאלפך חכמה. והיא סתומה כמו בטבעת סביב לה, שלא תגלה ממנה לחוץ. אמנם בדרך השערות היא מתגלה, לאט לאט עד גמר התקון."],[3,"אורכא דכל שערא","וכו׳: האורך של כל שערה היורדת מלפני האזנים אינה ארוכה. כלומר שאין החכמה המכונה אורך, מתגלה שמה. והשערות אינן מתדבקות זו בזו. והן קצרות ואינן יורדות למטה. ואלו השערות כשנמשכות, הן נמשכות ותלויות למעלה."],[3,"","פירוש. כי שערות אלו, היוצאות מפאתי הראש, כוללות בתוכן גם המלכות דמדת הדין, (כנ״ל באות צ׳ ע״ש) וכל שערה יש לה מבוע בפני עצמה ואלו הנמשכות ממלכות הממותקת אינן מתערבות באלו הנמשכות ממלכות דמדת הדין. וז״ש \u0003ולא אתדבק דא בדא.\u0004 וכמו כן הדין שבמלכות דמדת הדין אינה נמשכת בשאר תקוני דיקנא, וז״ש \u0003ולא נחתין,\u0004 אלא נשאר במקומו, בסוד \u0003דינא יתיב,\u0004 שיושב במקומו ואינו מתפשט. כמ״ש לפנינו."],[4,"ושרותא דתקונא קדמאה","וכו׳: ובהתחלה של תקון הראשון, ל״א קבוצות שער, שהן שקולות, נמשכות עד ראש הפה. וש״צ נימין נמצאות בכל קבוצה וקבוצה."],[4,"","פירוש. שמלמדנו בזה, כי אע״פ שהמלכות דמדת הדין נמצאת בתקון ראשון דדיקנא היוצא מפאתי הראש, כנ״ל בדבור הסמוך, עם כל זה, אין זה עצם המלכות דמדת הדין, שהרי היא נגנזה בראש עתיק, אלא רק הארתה של המלכות הזו. ועצמותה אין כאן. וז״ש, \u0003תלתין וחד קוצי שקילן אתמשכן\u0004 וכו׳, שזה יורה על השם \u0003א״ל,\u0004 והיינו על שם מדת הדין שבמלכות, שעליה נאמר \u0003ואל\u0004 זועם בכל יום. וזהו בכללות התקון, שהארת המלכות דמדת הדין מאירה בכללות. אבל בפרטות, אין שם עצמות המלכות דמדת הדין, וז״ש, \u0003וש״צ נימין אשתכחן בכל קוצא וקוצא,\u0004 שזה יורה שבהתפרטות ד׳ ספירות חו״ב תו״מ שבכל קוצא, שכל אחת כלולה ממאה, תהיינה הע״ס של המלכות רק צ׳, ולא מאה, משום שהמלכות דמלכות, שהיא עצמותה של המלכות דמדת הדין, חסרה שמה, וע״כ אינם אלא ש״צ נימין ולא ת׳."],[5,"תלתין וחד קוצי","וכו׳: ומפרש הדברים מבחינת כללות התקון. ואומר, \u0003ל״א\u0004 קוצין, השקולות בשוה, שהם בתקון ראשון, הם קשים, מהארת המלכות דמדת הדין, כדי להכניע הדינים למטה, והן כחשבון \u0003א״ל.\u0004 מהו \u0003אל.\u0004 היינו אל חזק, ויכול להכניע הכל. ובכל קוץ וקוץ, מבחינת כללותו, מתחלקים ל״א עולמות חזקים שולטים להכניע הדינים, ונתפשטו ל״א מצד זה ול״א מצד זה של הפנים. וכל עולם ועולם ממנו מתחלק לאלף עולמות של חמדה לעדן הגדול, וכל זה סתום בתחילת הדיקנא שכולל דין חזק, ממלכות דמדת הדין, וכלולים כולם בשם \u0003אל\u0004 הזה. ועם כל זה, שם \u0003אל\u0004 הזה, נכנע לרחמי דרחמים של עתיק יומין, ונכלל ונתפשט בו."],[5,"","פירוש אע״פ שכל קוץ וקוץ יש בו ש״צ נימין, זהו מבחינת הפרטות, אבל בכללות מאיר בו הכח של שם \u0003אל,\u0004 היורה על הארת המלכות דמדת הדין, וע״כ \u0003ל״א\u0004 קוצין הם, וכל קוץ מתחלק ג״כ ל \u0003ל״א\u0004 עולמות, שכל זה יורה על הדין הכלול בקוצין הללו. ועכ״ז מתפשט כל עולם לאלף עולמות של חמדה לעדן הגדול, שהוא חכמה סתימאה, כי עדן הוא חכמה. וכן מספר אלף יורה על חכמה. והיינו משום שכח הדין שבשם \u0003אל,\u0004 נכנע לרחמי דרחמים דא״א. אמנם כל זה אמור בהתפשטות העולמות, אבל בל״א קוצין עצמם, כל העולמות סתומים בו מחמת הדין החזק."],[6,"אמאי עד פומא","וכו׳: שואל למה מתפשט תקון הא׳ מתחת האזנים עד הפה. ומשיב, הוא משום שכתוב, דינא יתיב וספרין וגו׳. מהו \u0003דינא יתיב.\u0004 היינו שהדין יושב במקומו ואינו שולט. ז״ש פלא יועץ \u0003אל\u0004 גבור, דהיינו אל שהוא גבור, המרומז בל״א קוצין הנ״ל, והוא מתבסם בדיקנא הקדוש דעתיק יומין. וסוד הכתוב, \u0003מי אל כמוך,\u0004 נאמר בעתיק יומין בתקון הא' של דיקנא הקדוש העליון."],[6,"","פירוש. כבר נתבאר שלהיות הדיקנא בחינת בינה ותו״מ שיצאו משערות ראש לבחינת גוף ע״כ מקומם בלחי התחתון, משפה התחתונה של הפה עד החזה (כנ״ל אות צ״ה ע״ש) וזהו ששואל, \u0003אמאי עד פומא,\u0004 למה נתפשט תקון הא׳ עד הפה, דהיינו עד השערות של שפה עליונה דפה. ששם לחי העליון. ומשיב שז״ס \u0003דינא יתיב, יתיב לאתריה דלא שלטא,\u0004 שהדין יושב בתקון האי ונבלע במקומו ואינו שולט. כי בסיומו, מתחילים השערות לעלות על שפה עליונה של הפה ששם לחי העליון, שהוא בחינת גלגלתא ומקום בינה, והדין דמלכות נמתק שם במדת הרחמים דבינה, ומשם ואילך נגנז כח המלכות דמדת הדין השולט בתקון הא׳. וע״כ \u0003דינא יתיב לאתריה דלא שלטא,\u0004 שהוא נבלע במקומו בתקון הא', ואינו שולט יותר."],[7,"עלמא קדמאה","וכו׳: עולם הראשון היוצא מתקון הא׳, שולט ויורד, ועולה לאלף אלפים ורבוא רבבות \u0003בעלי מגינים,\u0004 ומתאחזים ממנו במדדן של טבעת הגדולה. \u0003קסטא\u0004 פירושו מדה. על, הין, מתרגם יונתן קסטא דסכומיה י״ב לוגין (שמות ל׳ כ״ד)"],[8,"עלמא תניינא","וכו׳: עולם השני היוצא מתקון הזה. שולט ויוצא ויורד למטה, ועולה לנ״ז אלף מדרגות \u0003בעלי יבבא,\u0004 ומתאחזים ממנו, כדי להכנע, בעורף בלבן שבו, כלומר בבשר העורף."],[9,"עלמא תליתאה","וכו׳: עולם השלישי היוצא מתקון הזה, שולט ויורד למטה, ועולה לצ״ו אלף \u0003בעלי יללה,\u0004 ומתאחזים ממנו בנר המכוסה, דהיינו במלכות דמדת הדין שבתקון הא׳, שעצמותה נגנזה בראש עתיק, ומתקון הזה נכנעים כולם ומתבשמים במרירות הדמעות המתבשמות בים הגדול. \u0003בבוצינא קמורא, קמורא\u0004 הוא מלשון ועינו קמורה (אהלות פ״ה משנה א׳) שפירושו סגורה."],[9,"","פירוש. כבר ידעת ששערות דיקנא הן ג׳ ספירות בינה ותו״מ שיצאו לחוץ משערות ראש. (כנ״ל אות צ״ה). ולפיכך כנגד ג׳ ספירות אלו יצאו ג׳ עלמין מתיקון הא'. ואלו שנמשכו מבינה דשערות, עלו ונתאחזו בתקון \u0003ם׳\u0004 דצלם שבשערות, הנקרא עזקא רבא. שכן נקרא תקון \u0003ם׳\u0004 דצלם, להיותו מקיף המוח מסביב שלא יתפשט ממנו ולמטה. ולפיכך, \u0003וסליק לאלף אלפין ורבוא רבבן מארי תריסין,\u0004 כלומר שיש בתוכו חכמה הנק׳ אלף אלפין, וגם חסדים הנקראים רבוא רבבן. ונקראים \u0003מארי תריסין,\u0004 משום, \u0003ומניה מתאחדין בקסטא בעזקא רבא,\u0004 כי כל מעלתם הוא מפני שמתאחזים במדת טבעת הגדולה שה״ס \u0003ם׳\u0004 דצלם, שהיא \u0003מגינה\u0004 עליהם מכל התפשטות דין. וע״כ נקראים בעלי מגינים. והם עולם הא׳."],[9,"","ועולם השני. הוא הנמשך מת״ת דשערות, שאינו ראוי להאחז בעזקא רבא, והוא נאחז בעורף א״א, שיש שם ב׳ מיעוטים, א׳ שכבר נגמר עצם הגלגלתא שהוא \u0003ם׳\u0004 דצלם, (כנ״ל אות ל״ד) ב׳ שהוא ערף ולא פנים, וע״כ הארתם בבחינת ו״ק, וגם זה רק מאחורים. וע״כ כיון שיצאו משערות ראש ונפלו למקום ו״ק, הם מיבבים תמיד. מחמת הדינין דאחורים השורים עליהם. וז״ש, \u0003וסליק לנ״ז אלף דרגין מארי דיבבא,\u0004 כי מיבבים תמיד. והוא משום, \u0003ומתאחדן מניה לאכפייא בקודלא בחיורא.\u0004 משום שהם נאחזים בעורף ולא בפנים. אמנם סתימה זו שבעורף, גורמת להם להכנע, ולא להמשיך חכמה כלל. וז״ש \u0003ומתאחדן מניה לאכפייא,\u0004 דהיינו להכנע ולא להמשיך חכמה משם. ומספר נ״ז, שאומר, רומז ליחוד \u0003אל הויה,\u0004 שהוא בחשבון נ״ז. כי להיותן בחינת ת״ת, מרומזים בהויה, ולהיות, שסתימת תקון א׳ שולט עליהם, שה״ס השם \u0003אל\u0004 תקיף כנ״ל, ע״כ השם \u0003אל\u0004 מתיחד עם שם \u0003הויה,\u0004 ושומר עליהם."],[9,"","ועולם השלישי, הוא הנמשך ממלכות דשערות, שמלכות זו שעודנה בתקון הא׳, עוד לא נמתקה במדת הרחמים, ומדת הדין שולט עליה (כנ״ל אות צ׳) ולפיכך אותם שהן בעולמות אלו מיללים תמיד מרוב הדינין האלו שבמלכות דמדת הדין. וז״ש, \u0003וסליק לצ״ו אלפין מארי דיללה,\u0004 כי גרוע להם הרבה יותר מבעלי יבבא הנ״ל. והוא משום, \u0003ומתאחדן מניה בבוצינא קמורא,\u0004 שנאחזים בנר הסגור והמכוסה, שהוא מלכות דמדת הדין. ומספר צ״ו רומז על יחוד \u0003אל אדני,\u0004 שהוא בגימטריא צ״ו. כי להיותם מן המלכות דשערות, ה״ס שם אדנ״י. וסתימת התקון השולט עליהם ה״ס השם \u0003אל\u0004 גבור ותקיף השולט בתקון הא׳, ושומר עליהם. וע״כ נרמזים ביחוד אל אדני."],[9,"","ונודע שיש במלכות ב׳ נקודות, א׳ דמלכות דמדת הדין, וב' הנמתקת במדת הרחמים, שע״כ נקראת עץ הדעת טוב ורע, וכשהיא בתקון השלם אז נגנזה בה המלכות דמדת הדין, והמלכות דמדת הרחמים שולטת (כנ״ל בהקסה״ז אות קכ״ג) וב׳ נקודות אלו ה״ס שתי דמעות. וכאן בתקון הא׳ מטרם שנעשה התקון דגניזת המלכות דמדת הדין, נמצאות ב׳ דמעות אלו מרירות. וז״ש \u0003ומתבסמן במרירא דדמעין דמתבסמין בימא רבא,\u0004 דהיינו שתקונם היא לקבל בתוכם עתה את המרירות של ב׳ הנקודות, כי הן מתבסמות אח״כ בים הגדול, שהוא מלכות. והנקודה דמדת הרחמים תהיה לבדה בשליטה. כמ״ש בתקונים הבאים."],[10,"מאן חמי תקונא","וכו׳: מי ראה תקון הזה של הדיקנא הקדוש, העליון, היקר, שלא נתבייש ממנו. (דהיינו כמ״ש באות צ״ט) מי ראה היקר של קוצין דשערי התלויות מסבא הזה, הוא יושב בעטרי עטרות, שהם י״ג תיקוני דיקנא הנקראים עטרות. שהן עטרות של כל העטרות, כי תקוני דיקנא דז״א נמשכים מתקוני דיקנא אלו דא״א. וע״כ הן עטרות של כל עטרות. והן עטרות שלא נכללו בעטרות דז״א, כלומר שאינן יורדות להתלבש בהן. שהן עטרות שאינם כשאר עטרות דז״א, כי עטרות דא״א הן כעמר נקי ועטרות דז״א הן שחורות כעורב. והן עטרות שעטרות של מטה, דז״א, מתאחזות בהם. שתקוני דיקנא דז״א מקבלים מי״ג תקוני דיקנא דא״א. ומשום זה נתתקנו אלו התקונים, כדי שאלו התקונים שלמטה, דז״א, יהיו מתאחזים בהם."],[11,"תקוני דאתתקן","וכו׳: התקונים שנתתקנו, הם, משום שצריכים לברך למי שצריך ברכה, כי כל התקונים שנתתקנו למטה כנגדם, נמצאות כנגדם ברכות ונעשה מה שנעשה. אם ברכת בנים או חיים או מזונות. הכל כלול באלו התקונים. וכולם זוקפים קומתם כנגד התקונים של המלך התקיף, עתיק, הסתום מכל. וכולם מתבשמים מתקונים אלו."],[12,"תאנא אי עתיק","וכו׳: למדנו, אם עתיק העתיקים קדוש הקדושים, שהוא א״א, לא היה מתתקן בתקונים אלו, לא היו נמצאים העליונים והתחתונים. והכל היה כלא היה. כי זולתם לא היה בני חיי ומזוני, לא למעלה ולא למטה. ולמדנו, עד כמה מאירים תקוני דיקנא אלו. עד י״ג. וכל זמן שי״ג אלו נמצאים, מאירים אלו שלמטה, והכל. בחשבון י״ג אלו נמצא הדיקנא של מלך העתיק היקר מכל, וכולם כאחד נסתר ויקר."]],[]],[["וּבְגִין דְּאִיהוּ יַקִּירָא וּטְמִירָא מִכֹּלָּא, לָא אִדְכַּר בֵּיהּ בְּאַתָר דְּאוֹרַיְיתָא (ס\"א לא אדכר באורייתא), וְלָא אִתְגַלְיָיא. וּמַה דִּיקְנָא אִתְגַלְיָיא. דִּיקְנָא דְּכַהֲנָא רַבָּא עִלָּאָה. וּמֵהַאי דִּיקְנָא, נָחִית לְדִיקְנָא דְּכַהֲנָא רַבָּא דִּלְתַּתָּא. (מאי דיקנא דכהנא רבא) דִּיקְנָא דְּכַהֲנָא רַבָּא בִּתְמַנְיָא תִּקּוּנִין אִתְתָּקַּן. וּבְגִין כַּךְ, תְּמַנְיָא תִּקּוּנִין לְכַהֲנָא רַבָּא, כַּד מִשְׁחָא נָחִית עַל דִּקְנֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים קל״ג:ב׳) כַּשֶׁמֶן הַטּוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן וְגוֹ'.","ומְנָא לָן. דִּכְתִּיב, (תהילים קל״ג:א׳) שֶׁבֶת אַחִים גַּם יָחַד. גַּם לְרַבּוֹת כֹּהֵן גָּדוֹל דִּלְתַּתָּא. דְּכָל זִמְנָא דְּכַהֲנָא רַבָּא דִּלְתַּתָּא, מְשַׁמֵּשׁ בִּכְהוּנָא רַבָּא, כִּבְיָכוֹל כֹּהֵן גָּדוֹל דִּלְעֵילָּא, מְשַׁמֵּשׁ בִּכְהוּנָא רַבָּא.","דָּא תִּקּוּנָא חַד, דְּדִיקְנָא דְּעַתִּיקָא סְתִימָא דְּכֹלָּא. אָמַר לֵיהּ רִבִּי שִׁמְעוֹן, יָאוּת אַנְתְּ רִבִּי יִצְחָק, לְמֵחֱמֵי בְּיָקִירָא דְּתִקּוּנֵי דְּדִיקְנָא, וּסְבַר אַפֵּי דְּעַתִּיק יוֹמִין, עַתִּיקָא דְּעַתִּיקִין. זַכָּאָה חוּלָקָךְ, וְזַכָּאָה חוּלָקִי עִמְּכוֹן בְּעָלְמָא דְּאָתֵי.","תִּקּוּנָא תִּנְיָינָא. מִתְתָּקַן שַׂעֲרָא, מֵרֵישָׁא דְּפוּמָא, עַד רֵישָׁא אַחֲרָא דְּפוּמָא, בְּתִקּוּנָא שָׁקִיל.","קוּם רִבִּי חִזְקִיָּה, וְקָאִים בְּקִיּוּמָךְ, וְאוֹקִיר יְקָרָא דְּתִקּוּנָא דָּא דְּדִיקְנָא קַדִּישָׁא. קָם רִבִּי חִזְקִיָּה, שָׁארֵי וְאָמַר, (שיר השירים ז׳:י״א) אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ מִי גָּרַם שֶׁאֲנִי לְדוֹדִי. מִשּׁוּם דְּעָלַי תְּשׁוּקָתוֹ.","מִסְתַּכֵּל הֲוִינָא, וַאֲרוּ חָמִית, נְהוֹרָא יַקִּירָא דְּבוּצִינָא עִלָּאָה, נָהִיר וְסָלִיק לִתְלַת מְאָה וַחֲמִשָּׁה וְעֶשְׂרִין עִיבָר. וְחַד חָשׁוֹךְ הֲוָה אִתְסָחֵי בְּהַהוּא נְהוֹרָא, כְּמַאן דְּאִתְסְחֵי בְּהַהוּא נַהֲרָא עֲמִיקָא, דְּמֵימוֹי מִתְפַּלְּגִין, וּנְהִרִין, וְנַגְדִּין לְכָל עִיבָר, מִמָּה דְּעָלוֹי. וְסָלִיק הַהוּא נְהוֹרָא, בִּשְׂפָתָא דְּיַמָּא עִלָּאָה עֲמִיקָא, דְּכָל פִּתְחִין טָבִין וְיַקִּירִין, בְּהַהוּא פִּתְחָא אִתְפַּתְּחָן.","אֲנָא שָׁאִיל מֵהֶם (ס\"א מהו), פִּשְרָא דְּחָמֵית. פָּתְחוּ וְאָמְרוּ, נוֹשֵׂא עָוֹן חֲמֵיתָא. אָמַר, דָּא הוּא תִּקּוּנָא תִּנְיָינָא. יָתִיב. אָמַר רִבִּי שִׁמְעוֹן, הָאִידָנָא אִתְקַשַּׁר (ס\"א אתבסם) עָלְמָא. בְּרִיךְ אַנְתְּ רִבִּי חִזְקִיָּה, לְעַתִּיקָא דְּעַתִּיקִין.","אָמַר רַבִּי שִׁמְעוֹן, כֻּלְּהוּ בּוּצִינִין חַבְרִין, דְּאַתְיָין בְּהַאי עִזְקָא קַדִּישָׁא. אַסְהַדְנָא עָלַי שְׁמַיָיא עִלָאִין דְּעִלָּאִין, וְאַרְעָא קַדִּישָׁא עִלָּאָה דְּעִלָּאָה. דַּאֲנָא חָמֵי הַשְׁתָּא, מַה דְּלָא חָמָא בַּר נָשׁ, מִיּוֹמָא דְּסָלִיק מֹשֶׁה זִמְנָא תִּנְיָינָא לְטוּרָא דְּסִינַי. דַּאֲנָא חֲמֵינָא אַנְפָּאִי נְהִירִין, כִּנְהוֹרָא דְּשִׁמְשָׁא תַּקִּיפָא, דְּזַמִּין לְמֵיפַּק בְּאַסְוָותָא לְעָלְמָא. דִּכְתִּיב, (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ. וְעוֹד דַּאֲנָא יְדַעְנָא דְּאַנְפָּאי נְהִירִין, וּמֹשֶׁה לָא יָדַע וְלָא אִסְתָּכַּל. הֲדָא הוּא דִכְתִיב, (שמות ל״ד:כ״ט) וּמֹשֶׁה לָא יָדַע כִּי קָרַן עוֹר פָּנָיו.","וְעוֹד, דַּאֲנָא חָמֵי בְּעֵינַי, תְּלֵיסַר מְכִילִין גְּלִיפִין קַמָּאי, וּנְהִירִין כְּבוּצִינִין. וְכַד אִתְפְּרִישׁ כָּל חַד מִנַּיְיהוּ מִפּוּמֵיכוֹן, אִסְתָּלִיק וְאִתְתְּקַן, וְאִתְעַטָּר וְאִתְטָמַּר בִּטְמִירוּתָא דְּתִקּוּנֵי דְּדִיקְנָא, וְכָל אַחֲרָנִין אִשְׁתַּאֲרָן. וּבְעוֹד דְּכָל חַד מִתְפְּרַשׁ בְּפוּמַיְיכוּ, נָהִיר וְאִתְעַטָּר וְיָתִיב כְּמַלְכָּא בְּגוֹ חֵילֵיהּ. וְכַד אִסְתְּיָים לְאִתְפָּרְשָׁא, סָלִיק וְאִתְעַטָּר בְּעִטְרָא קַדִּישָׁא, וְאִתְתָּקַּן וְאִתְטָמַּר, וְיָתִיב בְּתִקּוּנוֹי דְּדִיקְנָא קַדִּישָׁא, וְכֵן לְכָל חַד וְחָד. אִזְדְּרָזוּ חַבְרִין קַדִּישִׁין, דְּהָא בְּקִיּוּמָא דָּא, לָא יְהֵא עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא.","קוּם רִבִּי חִזְקִיָּה תִּנְיָינוּת. וְאוֹקִיר תִּיקוּנָא תְּלִיתָאָה, דְּדִיקְנָא קַדִּישָׁא. תָּנָא, עַד לָא קָם רִבִּי חִזְקִיָּה, קָלָא נָפַק וְאָמַר, אֵין מַלְאָךְ אֶחָד עוֹשֶׂה שְׁתֵּי שְׁלִיחוּת. אִתְרְגִישׁ רַבִּי שִׁמְעוֹן וְאָמַר, וַדַּאי כָּל חַד וְחַד בְּאַתְרֵיהּ. וַאֲנָא, וְרִבִּי אֶלְעָזָר בְּרִי, וְרִבִּי אַבָּא, אִשְׁתְּלִים שְׁלֵימָתָא עִלָּאָה.","קוּם רִבִּי חִיָיא. קָם רִבִּי חִיָּיא, פָּתַח וְאָמַר, (ירמיהו א׳:ו׳) וָאוֹמַר אֲהָהּ יְיָ אֱלֹהִים הִנֵּה לָא יָדַעְתִּי דַּבֵּר כִּי נַעַר אָנֹכִי. וְכִי יִרְמִיָּה לָא הֲוָה יָדַע לְמַלְּלָא, וְהָא כַּמָה מִלוּלִין נַפְקֵי מִפּוּמוֹי, עַד לָא אָמַר דָּא. וְהוּא אָמַר מִלָּה כְּדִיבָא, דִּכְתִּיב הִנֵּה לֹא יָדַעְתִּי דַּבֵּר. אֶלָּא (תאנא) חַס וְשָׁלוֹם דְּאִיהוּ אָמַר עַל דָּא. אֶלָּא הָכִי תָּאנָא, מַה בֵּין דִּבּוּר לַאֲמִירָה. אֲמִירָה הוּא דְּלָא בָּעֵי לְאַרְמָא קָלָא, דִּבּוּר, בָּעֵי לְאַרְמָא קָלָא, וּלְאַכְרְזָא מִלִּין."],[[0,"ובגין דאיהו יקירא","וכו׳: ומשום שהוא יקר ונסתר מכל נביא, לא נזכר הדיקנא בתורה ולא נתגלה בה. ואיזה דיקנא נתגלה. הוא הזקן של הכהן הגדול העליון, שהוא חסד דז״א. ומדיקנא הזה יורד לדיקנא של כהן גדול התחתון. הדיקנא של הכהן גדול, של ז״א, נתתקן בשמונה תקונים, ועם המלכות הכוללתם הם תשעה. (כמ״ש להלן אות רמ״ט) ומשום זה יש שמונה תקונים לכהן גדול כששמן יורד על זקנו, דהיינו ח׳ בגדי כהונה. ז״ש, כשמן הטוב יורד על הראש יורד על הזקן וגו׳."],[1,"ומנ״ל דכתיב שבת","וגו׳: ומאין לנו שכהן גדול של מטה הוא מכוון כנגד כהן גדול שלמעלה. כי כתוב שבת אחים גם יחד. \u0003גם\u0004 בא לרבות כהן גדול שלמטה, שכל זמן שכהן הגדול שלמטה משמש בכהונה גדולה, כביכול כהן הגדול שלמעלה משמש בכהונה גדולה."],[2,"דא תקונא חד","וכו׳: זה הוא תקון אחד של דיקנא דעתיק הסתום מכל. אמר לו ר״ש, נאה לך ר׳ יצחק לראות ביקר תקוני דיקנא וסבר פנים של עתיק יומין, עתיק העתיקין. אשרי חלקך, ואשרי חלקי עמכם בעולם הבא."],[3,"תקונא תניינא","וכו׳: התקון השני. השערות מתתקנות מראש הפה עד ראש האחר של הפה בתקון שקול. פירוש. כי שערות הדיקנא שמקומן הוא בלחי התחתונה, שיצאו בתקון הראשון, מתחת האזנים ונמשכו עד ראש הפה ולא נתפשטו יותר, משום ששפה עלאה היא סיום גלגלתא, שהיא בינה, (כנ״ל אות י״ח) נמשכו עתה, בסוד התקון של עלית המלכות לבינה, ועלו בשפה עלאה מראש הפה עד ראש האחר של הפה, ששם מקום בינה. והיה זה כדי להמתיק המלכות דמדת הדין שבשערות דיקנא (כנ״ל אות ק״ו) במקום בינה, שהוא רחמים. שה״ס המתוק הראשון של שערות דיקנא. וזהו תקון הב׳."],[4,"קום ר׳ חזקיה","וכו׳: קום ר״ח, ועמוד על עמדך, והוקר יקר תקון זה של הדיקנא הקדושה. קם ר׳ חזקיה. התחיל ואמר. אני לדודי ועלי תשוקתו. פירושו, מי גרם שאני לדודי, משום שעלי תשוקתו."],[5,"מסתכל הוינא וארו","וכו׳: מסתכל הייתי, והנה ראיתי אור יקר של נר העליון, בינה, מאיר ועולה ל שכ״ה צדדים, וחשוך אחד היה מתרחץ באור ההוא כמי שמתרחץ באותו נהר העמוק, שהוא בינה, שמימיו מתחלקים, ומאירים ונמשכים לכל צד ממה שעבר עליו. כלומר, שמאירים על אותו חשוך להמתיקו על כל הדינים שעברו עליו עד הנה. ועלה אור ההוא בשפת ים העליון העמוק, שכל פתחים טובים ויקרים נפתחים בפתח ההוא."],[5,"","פירוש. שהיה רואה, איך חשוך אחד, שהוא מדת הדין שבמלכות דצמצום א׳, היה מתרחץ ממדת הדין שבו, בתוך אור היקר של הבינה. שאור זה הסיר מעליו העוביות דצמצום א׳ הנבחן כמו רחיצה. ונתדמה בזה לשורשו שבראש, שהוא קרומא דאוירא, שהמלכות דצמצום א׳ עלתה שמה לבינה דגלגלתא, וחצתה הבינה לב׳ מדרגות לג״ר דבינה, שנקראת גלגלתא, ולז״ת דבינה שנקראות מוחא דאוירא, (כנ״ל אות כ״ג ע״ש). וז״ש, \u0003וארו חמית נהורא יקירא דבוצינא עלאה,\u0004 שהוא אור הבינה, \u0003נהיר וסליק לשכ״ה עיבר,\u0004 שמאיר ועולה, לתקן הדינים שבשביה״כ שנתפזרו לשכ״ה ניצוצין, \u0003וחד חשוך,\u0004 שהוא המלכות דצמצום א׳, שהיא חושך מכח הצמצום הרוכב עליה שלא לקבל אור, \u0003הוה אתסחי בההוא נהורא,\u0004 שרחץ והסיר הדינים והעוביות שבו דצמצום א׳ ע״י אור הרחמים הזה של הבינה, והוא מתדמה במעשה זו, \u0003כמאן דאתסחי בההוא נהרא עמיקא דמימוי מתפלגין,\u0004 דהיינו כמו המלכות שעלתה לבינה דגלגלתא להתמתק, שע״י כך נתחלקה הבינה לב׳ מדרגות כנ״ל, כן המלכות שנכללה בשערות דיקנא עלתה לאור הבינה להתמתק שמה. ומימי הבינה, \u0003נהרין ונגדין לכל עיבר,\u0004 שמאירים על המלכות מכל עבריהם \u0003ממה דעלוי,\u0004 להסיר כל העוביות שעליה. וזהו שמסיים \u0003וסליק ההוא נהורא בשפתא דימא עלאה עמיקא,\u0004 שאור ההוא עם אותו חשוך שבתוכו עלה בשפת ים העליון העמוק שהוא בינה. דהיינו בשפה עלאה דדיקנא, ששם הוא סיום הלחי העליונה והגלגלתא שהוא בינה. ונודע שהבינה מתמעטת מג״ר על ידי ההתכללות הזו של המלכות, וע״כ ממיעוט הזה דבינה, יצאו \u0003שערות בשפה עלאה,\u0004 מראש הפה עד ראש האחר של הפה. כי שערות מורות על מיעוטים ודינים. והנה תקון זה של עלית המלכות להכלל במקום בינה. הוא פתח לכל האורות והמוחין של פרצופי האצילות (כנ״ל ב״א דף ז׳ ד״ה וכבר ע״ש) וז״ש, \u0003דכל פתחין טבין ויקירין בההוא פתחא אתפתחן,\u0004 כי ע״י הפתח שנעשה בעלית המלכות דשערות לבינה, ראוים תקוני השערות לקבל כל המוחין הגדולים דבינה (כמ״ש שם)."],[6,"אנא שאיל מהם","וכו׳: אני שאלתי מהם פשר הדבר שראיתי. פתחו ואמרו, \u0003נושא עון,\u0004 ראית. אמר, זה הוא התקון השני. ישב. א״ר שמעון, עתה נתבשם העולם. דהיינו המלכות שנקראת עולם, נתבשמה ונמתקה בבינה, ע״י התקון הזה. ברוך אתה, ר׳ חזקיה, לעתיק העתיקין."],[6,"","פירוש. השם נושא עון, הוא על הבינה, שאע״פ שהיא נקייה מכל צמצום ודין, לקחה לתוכה את המלכות דמדת הדין המצומצמת, ומשום זה נתמעטה הבינה, ונעשתה \u0003למעוות\u0004 דהיינו ו״ק בחסרון ג״ר. שז״ס נושא \u0003עון.\u0004 והיא עשתה זאת כדי לתקן את זו״ן במדת הרחמים שיהיו ראוים לקבל אורות דגדלות (כנ״ל ב״א דף ז׳ ד״ה וכבר) ולפיכך בי״ג מדות שבתורה שהם של ז״א נק׳ תקון ב׳ הזה בשם \u0003רחום,\u0004 כי בזה נמתקה המלכות במדת הרחמים. וההפרש מהשמות די״ג תיקוני דיקנא דא״א, שבמיכה, וי״ג תי״ד דז״א שבתורה. הוא, כי א״א הוא השורש המשפיע אותם אל ז״א. ולפיכך תקון הא׳ דא״א הוא, \u0003מי אל כמוך.\u0004 להיות בו אל תקיף וגבור השורשי, ותקון א׳ דז״א שבתורה, הוא \u0003אל,\u0004 סתם, להיותו מקבל התוקף מא״א. ותקון הב׳ דא״א הוא \u0003נושא עון,\u0004 שמורה על הבינה שנושאת המעוות של המלכות כדי להשפיע רחמים לזו״ן. וע״כ תקון הב׳ דז״א, הוא \u0003רחום.\u0004 דהיינו שמקבל הרחמים."],[7,"אמר ר״ש כלהו","וכו׳: אר״ש אל החברים, כל המאורות, שהם, אתם החברים שבאים להתתקן בטבעת הקדושה הזו, דהיינו בי״ג תקוני דיקנא. שמעו. אני מעיד עלי שמים העליונים דעליונים והארץ הקדושה העליונה דעליונה, שה״ס שמים חדשים והארץ החדשה הנעשים ע״י רזין דאורייתא כנ״ל בהקסה״ז (אות ס״ד ע״ש) שאני רואה עתה מה שלא ראה אדם, מיום שעלה משה בפעם השניה להר סיני. כי אני רואה פני מאירים כאור השמש החזק שעתיד לצאת לרפאות לעולם. שכתוב וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה. ועוד שאני יודע שפני מאירים ומשה לא היה יודע ולא היה מסתכל. ז״ש, ומשה לא ידע כי קרן עור פניו."],[7,"","פירוש. כי משה רבנו היה סוד דעת הפנימי שהימין שולט בו, וע״כ היה סוד שושבינא דמלכא. ולפיכך לא רצה לברך את \u0003שמעון\u0004 בן יעקב בין השבטים, כי השם \u0003שמעון\u0004 מורה על קו השמאל, כי הוא אותיות \u0003שם עון,\u0004 דהיינו אם ממשיכים החכמה שבקו שמאל ממעלה למטה הוא העון הגדול דעץ הדעת. וסוד \u0003קרן עור פניו\u0004 הנאמר במשה ה״ס הארת חכמה, בסו״ה חכמת אדם תאיר פניו. והיינו הארת חכמה הנמשכת ע״י הדעת שה״ס משה, אבל משה עצמו לא ידע, כלומר שהיה בשליטת ימין שעקרו חסדים. כטבע הדעת הפנימית. אבל ר׳ שמעון בן יוחאי, היה מקורו מבחינת ה׳ גבורות, שה״ס חג״ת נ״ה שבקו שמאל, שע״כ היה שמו \u0003שמעון,\u0004 כמו שמעון בן יעקב. אלא ע״י תורתו ועבודתו נתעלה עד שזכה לסוד הדעת, בדומה למשה עצמו, ועכ״ז היה הפרש ביניהם, כי משה לא ידע כי קרן עור פניו, כי היה תמיד בשליטת החסדים, אבל ר׳ שמעון בן יוחאי, כיון שראשית מקורו היה בקו שמאל, ע״כ ידע כי פניו מאירים בהארת החכמה. וגם התפאר בזה. וז״ש \u0003ועוד דאנא ידענא דאנפאי נהירין ומשה לא ידע ולא אסתכל.\u0004 שמשה היה בשליטת ימין ע״כ \u0003לא הסתכל\u0004 בהארת חכמה שלו. אבל אני מסתכל ויודע."],[7,"","אמנם כדי שלא יטעה מי שהוא שעודו קשור בקו שמאל, ע״כ מדייק ואומר, \u0003דאנא חמינא אנפאי נהירין כנהורא דשמשא תקיפא דזמין למיפק באסוותא לעלמא\u0004 כי לעתיד לבא מוציא הקב״ה את החמה מנרתיקה, שפירושו שז״א הנקרא חמה, שקו שמאל שבו מלובש בנרתק דמסך דחירק, שלא יאיר ממעלה למטה, (כנ״ל לך י״ג ד״ה ונתבאר) הנה לעתיד יתבטל נרתיק זה, וקו השמאל יאיר בכל תוקפו, והרשעים שיתדבקו אז בשמאל ידונו בה, והצדיקים יתרפאו בה (נדרים ח:) כי הקב״ה יכסה אותם בסוד הכנפים שלו מקו האמצעי. וז״ש וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה. ורמז ר״ש שהארת פניו הוא במדרגת כנפי השמש שלעתיד לבא. שממנה נמשכת רפואה לצדיקים."],[8,"ועוד דאנא חמי","וכו׳: ועוד שאני רואה בעיני י״ג מדות חקוקות לפני ומאירות כנרות, וכשמתבאר כל אחד מהם מפיכם, עולה ומתתקן תקון הזה על דרך שבארתם, ומתעטר ומסתתר בנסתרות של תקוני הדיקנא למעלה. וכל האחרים שעוד לא בארתם נשארים ומחכים לסדר הביאור שלכם. ובעוד שכל אחד, מן התקונים, מתבאר בפיכם, אותו התקון מאיר ומתעטר ויושב כמלך בתוך צבאותיו. וכשנשלם הביאור, התקון עולה ומתעטר בעטרה קדושה, ומתתקן ומסתתר ויושב בין התקונים של הדיקנא הקדוש למעלה. וכן בכל אחד ואחד המתבאר מפיכם. הזדרזו חברים הקדושים, כי בקיום הזה לא יהיה העולם, עד שיבא מלך המשיח."],[9,"קום ר׳ חזקיה","וכו׳: קום ר׳ חזקיה שנית והוקר תקון השלישי של הדיקנא הקדוש. למדנו, מטרם שר׳ חזקיה קם, יצא קול ואמר, אין מלאך אחד עושה שתי שליחות. נתפעל ר״ש ואמר, ודאי כל אחד ואחד במקומו. כלומר, שיש גבול לכל אחד, שאינו יכול לתקן למעלה ממקום אחיזתו. ואני ור׳ אלעזר בני ור׳ אבא, נשלמה עמנו השלמות העליונה. כלומר, שלהיותם במדרגת חב״ד, (כנ״ל אות ו׳) יכולים להשלים החסרון של כל אחד ואחד."],[10,"קום ר׳ חייא","וכו׳: קום ר״ח. קם ר׳ חייא. פתח ואמר, ואומר אהה ה׳ אלקים הנה לא ידעתי דבר כי נער אנכי. שואל, וכי ירמיה לא היה יכול לדבר, והרי כמה דבורים יצאו מפיו מטרם שאמר זה, והוא אמר דבר שקר, שכתוב, הנה לא ידעתי דבר. ומשיב, אלא חס ושלום שהוא אמר זה, אלא כך למדנו, מהו בין דבור לאמירה. אמירה היא, שאין צורך להרמת קול. בדבור צריך להרמת הקול ולהכריז הדברים."]],[]],[["דִּכְתִּיב, (שמות כ׳:א׳) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. וְתָאנָא, כָּל עָלְמָא שָׁמְעוּ הַהוּא דִּבּוּר, וְכָל עָלְמָא אִזְדַּעֲזָעוּ. וּבְגִין כַּךְ כְּתִיב וַיְדַבֵּר, וְלָא כְּתִיב וַיֹּאמֶר. אוּף הָכָא כְּתִיב הִנֵּה לֹא יָדַעְתִּי דַּבֵּר, לְאַכְרְזָא מִלָּה וּלְאוֹכָחָא בְּרוּחַ קֻדְשָׁא לְעָלְמָא.","אִי הָכִי, הָא כְּתִיב (שמות ו׳:י׳) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה לֵאמֹר. אֶלָּא, מַאן הוּא נְבִיאָה עִלָּאָה כְּמֹשֶׁה, דְּלָא זָכָה בַּר נָשׁ כְּוָותֵיהּ. דְּהוּא שָׁמַע דִּבּוּר בְּהַכְרָזָה, וְלָא דָּחִיל, וְלָא אִזְדַּעְזָע. וּשְׁאַר נְבִיאִים אִזְדַּעֲזָעוּ, אֲפִילּוּ בַּאֲמִירָה, וְדַחֲלִין בִּדְחִילוּ.","וְתָאנָא, תִּקּוּנָא קַדְמָאָה דְּדִיקְנָא, וְתִנְיָינָא לְאָתָבָא (ס\"א לאייתאה) (ס\"א לאכפא) לִתְלִיתָאָה. דִּכְתִּיב, (איוב ל״ג:כ״ט) הֶן כָּל אֵלֶּה יִפְעַל אֵל פַעֲמַיִם שָׁלֹשׁ עִם גָּבֶר. (תרין נוסחי) וְתָא חֲזֵי דִתְרֵין תִּקּוּנִין קַדְמָאִין לְמֵיתֵי לְתְלִיתָאָה הֲווּ דְהוּא תִּקּוּנָא תְּלִיתָאָה. מֵאֶמְצָעִיתָא דִּתְחוֹת חוֹטָמָא, מִתְּחוֹת תְּרֵין נוּקְבִין. נָפִיק חַד אָרְחָא, וְשַׂעֲרָא אַפְסִיק (ס\"א אתפסק) בְּהַהוּא אָרְחָא. אֲמַאי אִתְפְּסָק. מִשּׁוּם (דכתיב ועובר על פשע) דְּהַאי אוֹרְחָא אִתְתָּקַּן לְאַעְבְּרָא בֵּיהּ. וּבְגִין כַּךְ, יְתִיב תְּחוֹת נוּקְבֵי חוֹטָמָא הַאי אוֹרְחָא. וְשַׂעֲרָא לָא אִתְרַבֵּי בְּהַאי אוֹרְחָא, מִשּׁוּם דִּכְתִּיב וְעוֹבֵר עַל פֶּשַׁע, לְמֵיהַב אַעְבְּרָא עַד (על) פּוּמָא קַדִּישָׁא, דְּיֵימָּא סָלַחְתִּי. תָּאנָא, כַּמָה עַרְקִיסָאוֹת מְחַכָּאן לְהַהוּא פּוּמָא, וְלָא אִתְגְּלֵי לְחָד מִנַּיְיהוּ, דְּהָא אִסְתְּלַּק וְאִתְעַטָּר, יְדִיעַ וְלָא יְדִיעַ. תָּאנָא, בִּצְנִיעוּתָא דְּסִפְרָא, מַהוּ דִּכְתִּיב פֶּשַׁע. זָכוּ עוֹבֵר, לֹא זָכוּ פֶּשַׁע. (מאי משמע עובר על פשע, שפע דאקדים ש' לפ', לא זכו עומד ולא עובר) (האי) בִּזְעֵיר אַפִּין.","מַאי בֵּין הַאי לְהַאי. בִּזְעֵיר אַפִּין, כַּד נָחִית הַהוּא אוֹרְחָא מִתְּחוֹת נוּקְבֵי חוֹטָמוֹי, כְּתִיב, (במדבר י״ב:ט׳) וַיִּחַר אַף יְיָ בָּם וַיֵּלַךְ. מַאי וַיֵּלַךְ. דְּנָפִיק רוּחָא דְּרוּגְזָא מֵאִינּוּן נוּקְבֵי, וּמַאן דְּאַשְׁכַּח קַמֵּיהּ, אָזִיל וְלָא אִשְׁתְּכַח. הֲדָא הוּא דִכְתִיב, (ישעיהו מ׳:ז׳) כִּי רוּחַ יְיָ נָשְׁבָה בּוֹ וְאֵינֶנּוּ (ס\"א כי רוח עברה בו ואיננו). בְּאֲרִיךְ אַפִּין כְּתִיב, (מיכה ז׳:י״ח) וְעוֹבֵר עַל פֶּשַׁע. וּכְתִיב, (איוב ל״ז:כ״א) וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. וְתָאנָא, הָכָא כְּתִיב, עוֹבֵר עַל פֶּשַׁע בְּהַהוּא אָרְחָא. הָתָם, (שמות י״ב:כ״ג) וְעָבַר יְיָ לִנְגּוֹף אֶת מִצְרַיִם.","זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּזָכֵי לְהַאי. וְדָא הוּא תִּקּוּנָא תְּלִיתָאָה, (דאורחא) דְּדִיקְנָא יַקִּירָא קַדִּישָׁא עִלָּאָה עַתִּיקָא דְּעַתִּיקֵי. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא יַסְגֵּי לְאוֹטָבָא לָךְ, וְיֶחְדֵּי לְאַגָּנָא עֲלָךְ.","וְתָאנָא, מַאי דִּכְתִּיב, (ישעיהו ס״א:י׳) שׂוֹשׂ אָשִׂישׂ בַּיְיָ, בְּעַתִּיק יוֹמִין אִתְּמַר. דְּהָא הוּא חֶדְוָותָא דְּכֹלָּא. תָּאנָא, בְּשַׁעֲתָא דְּאִתְגְּלֵי הַאי אוֹרְחָא דְּדִיקְנָא דְּעַתִּיק יוֹמִין. כֻּלְּהוּ מָארֵי דִּיבָבָא וִילָלָה, וּמָארֵיהוֹן דְּדִינָא סְתִימִין וּשְׁתִּיקִין, וְלֵית דְּיִפְתַּח פִּטְרָא לְאַבְאָשָׁא. מִשּׁוּם דְּהַאי אוֹרְחָא אִתְגַלְיָיא לְתַקְּנָא. וּמֵהַאי, מַאן דְּאָחִיד (נ\"א דאחית) וְאַזְהַר (משום דהאי אורחא סימנא לשתיקותא ומהאי הוא מאן דאחזי ואזהר) לְשַׁתְקָאָה, לְהַאי אוֹרְחָא רְשִׁים, דְּהוּא סִימָנָא דְּעַתִּיקָא קַדִישָׁא.","תִּקּוּנָא רְבִיעָאָה, מִתְתָּקַן שַׂעֲרָא (ונחית) תְּחוֹת פּוּמָא, מֵרֵישָׁא חֲדָא לְרֵישָׁא חֲדָא. הֲדָא הוּא דִכְתִיב, (מיכה ז׳:י״ח) לִשְׁאֵרִית נַחֲלָתוֹ. כְּמָה דְאַתְּ אָמֵר (מלכים ב י״ט:ד׳) וְנָשָׂאתָ תְפִלָּה בְּעַד הַשְּׁאֵרִית הַנִּמְצָאָה. הַנִּמְצָאָה מַמָּשׁ. שְׁאֵרִית דִּכְתִּיב, (צפניה ג׳:י״ג) שְׁאֵרִית יִשְׂרָאֵל לֹא יַעֲשׂוּ עַוְלָה.","תִּקּוּנָא חֲמִישָּׁאָה. נָפִיק אוֹרְחָא אַחֲרָא מִתְּחוֹת פּוּמָא, הֲדָא הוּא דִכְתִיב, (מיכה ז׳:י״ח) לֹא הֶחֱזִיק לָעַד אַפּוֹ. קוּם רִבִּי יוֹסֵי. קָם רִבִּי יוֹסֵי, פָּתַח וְאָמַר, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁיְיָ אֱלֹהָיו. אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ. מַהוּ שֶׁכָּכָה לּוֹ. כְּמָה דְאַתְּ אָמֵר (אסתר ז׳:י׳) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, שָׁכִיךְ מֵרוּגְזֵיה.","דָּבָר אַחֵר. שָׁכִיךְ בְּרוּגְזֵיהּ, הֲדָא הוּא דִכְתִיב, (במדבר י״א:ט״ו) וְאִם כָּכָה אַתְּ עוֹשֶׂה לִּי הָרְגֵנִי נָא הָרוֹג. דָּא הוּא דִּינָא דְּדִינָא. אַשְׁרֵי הָעָם שֶׁיְיָ אֱלֹהָיו, רַחֲמֵי דְּרַחֲמֵי.","דָּבָר אַחֵר, שֶׁכָּכָה, שְׁמָא דְּכָלִיל כָּל שְׁמָהָן, וְקוּדְשָׁא בְּרִיךְ הוּא מַעְבַּר רוּגְזֵיהּ, וַאֲנַח בֵּיהּ לִזְעֵיר אַנְפִּין, וּמַעֲבִיר עַל כָּל אִינּוּן דִּלְבַר.","דְּתַנְיָא, אָרְחָא, עִלָּאָה דְּדִיקְנָא קַדִּישָׁא, (עלאה עתיקא דעתיקי) דְּאִיהוּ נָחִית (בדיקניה) תְּחוֹת נוּקְבֵי דְּחוֹטָמָא דְּעַתִּיקֵי. וְהַאי אָרְחָא דִּלְתַתָּא. שְׁקִילָן אִינּוּן בְּכֹלָּא. דָּא לְעֵילָּא, וְדָא לְתַתָּא. לְעֵילָּא, עוֹבֵר עַל פֶּשַׁע. לְתַתָּא, לֹא הֶחֱזִיק לָעַד אַפּוֹ. וְתָנֵינָן, לֹא הֶחזִיק: דְּלָא אִית אֲתָר לְמֵיתַב. כְּמָה דִּלְעֵילָּא יָהִיב אַתְרָא לְאַעְבְּרָא. כַּךְ לְתַתָּא, יָהִיב אֲתָר לְאַעְבְּרָא."],[[0,"דכתיב וידבר","וגו׳: שכתוב, וידבר אלקים את הדברים האלה לאמר. ולמדנו, כל העולם שמע הדבור ההוא וכל העולם נזדעזע, ומשום זה כתוב וידבר ולא כתוב ויאמר, אף כאן כתוב, הנה לא ידעתי דבר, היינו להכריז דבר ולהוכיח ברוח הקודש אל העולם."],[1,"אי הכי הא","וכו׳: שואל, אם כן הרי כתוב, וידבר ה׳ אל משה לאמר. ולמה אמר ירמיהו לא ידעתי דבר. ומשיב, אלא מי הוא נביא עליון כמשה, שלא זכה אדם כמותו, שהוא שמע דבור בהכרזה, ולא פחד ולא נזדעזע. ושאר הנביאים, נזדעזעו אפילו באמירה, והיו יראים ביראה."],[1,"","פירוש אמירה היא בשליטת החסדים שאין בה אחיזה לדינים, וע״כ יכלו הנביאים לקבל משם. אבל דיבור הוא בהרמת קול, כלומר ביחוד ג״ר, בסוד פנים בפנים דז״א ומלכות המכונים אז קול ודבור. שרק משה היה ראוי לקבל משם ולא שאר הנביאים. וע״ז אמר ירמיהו, הנה לא ידעתי דבר כי נער אנכי. ומתוך שתקון הג׳ ה״ס המשכת הג״ר, ע״כ הקדים לו ר׳ חייא את הכתוב לא ידעתי דבר, הנאמר בירמיהו. ורמז בזה, אשר חכם עדיף מנביא."],[2,"","[א] \u0003ותאנא תקונא קדמאה\u0004 וכו׳: ולמדנו, התקון הראשון של הדיקנא, והתקון השני, הם באו כדי להביא את התקון השלישי. שכתוב הן כל אלה יפעל אל פעמים שלש עם גבר."],[2,"","[ב] \u0003תקונא תליתאה\u0004 וכו׳: התקון השלישי הוא. מאמצע שבתחת החוטם, מתחת ב׳ הנקבים, יוצא אורח אחד והשערות נפסקות בארח ההוא. למה נפסקו. הוא משום שאורח זה נתתקן להעביר בו רוח החכמה של החוטם, ומשום זה יושב אורח הזה תחת נקבי החוטם, ושערות אינן גדלות במקום הזה, משום שכתוב, ועובר על פשע, כדי לתת מעבר עד הפה הקדוש, שיאמר סלחתי. למדנו, כמה בתי דינים מחכים לפה ההוא דא״א, שיאמר סלחתי, ולא נגלה לאחד מהם, כי הוא מתעלה ומתעטר, ידוע ואינו ידוע. \u0003ערקיסאות\u0004 פירושו בתי דינים, לפי הענין."],[2,"","פירוש. כי ב׳ נקבי החוטם דא״א הנה נקב ימין ה״ס השפעת חסדים בעיקר אלא שנכללת בהארת החכמה שמשמאל, ונקב השמאל, עקרו הוא השפעת החכמה (כמ״ש לעיל אות ס״ג ע״ש) וכבד נתבארה יציאת השערות שעל שפה עלאה, שה״ס התמעטות הבינה מג״ר ע״י כחות הדין שקבלה מעלית המלכות (כנ״ל אות קי״ח) וכדי לתקן זה נעשה זווג עליון דע״ב ס״ג דא״ק, המוריד בחזרה את דיני המלכות מן הבינה, וחוזרת הבינה להיות ג״ר. (כנ״ל ויקהל דף מ״א ד״ה והארה) וז״ש, \u0003תקונא תליתאה\u0004 וכו׳ \u0003נפיק חד ארחא, ושערי אתפסק,\u0004 כי ע״י הארה עליונה מע״ב ס״ג דא״ק ירדה המלכות מבינה, וע״כ חזרה הבינה לג״ר, והשערות, שהן המיעוטים של התכללות המלכות, נפסקו. אמנם לפי״ז היו צריכות כל השערות להתבטל משפה עלאה, ולמה רק אורח אחד באמצע השערות. וז״ש, \u0003מאמצעיתא דתחות חוטמא מתחות תרין נוקבין נפיק חד אורחא,\u0004 שארח זה שיצא בשערות השפע נתתקן בבחינת קו \u0003אמצעי\u0004 הכולל ב׳ נקבי החוטם, שה״ס חסדים וחכמה כנ״ל. ולפיכך כדי שלא תתבטל הארת החסדים נשארו השערות מצד זה ומצד זה של השפה, ולא נעשה אלא ארח פנוי משערות באמצע. וזה ששואל, \u0003אמאי אתפסק.\u0004 למה נפסקו השערות מן הארח שבאמצע. ומשיב, \u0003משום דהאי אורחא אתתקן לאעברא ביה,\u0004 דהיינו כדי שרוח החכמה מאמצע החוטם יוכל לעבור דרך השערות, כלומר, רק שהשערות לא ימעטו הבינה מג״ר, ולא שיתבטלו לגמרי כל השערות, כי אז היתה נפסקת הארת החסדים."],[2,"","וז״ש, \u0003ושערא לא אתרבי בהאי אורחא משום דכתיב ועובר על פשע\u0004 שפירושו, \u0003למיהב אעברא עד פומא קדישא דיימא סלחתי,\u0004 דהיינו כנ״ל, ששיעור רוח החכמה מחוטם צריך רק להשיב שמה הג״ר, שנתמעטה מהן הבינה ע״י קבלתה את המלכות, בסוד \u0003נושא עון\u0004 (כנ״ל אות קי״ט ע״ש) כי רק צריכה לסליחת העון, דהיינו שיתוקן המעוות ותשוב לג״ר. ולא יותר, וז״ש, \u0003למיהב אעברא עד פומא קדישא דיימא סלחתי,\u0004 דהיינו שיאמר סלחתי על העון הזה. וע״כ נקרא תקון זה \u0003ועובר על פשע,\u0004 שרוח החכמה עובר שם רק לסלוח הפשע. ולא יותר."],[2,"","אמנם יש לשאול, שהיה לו לומר כאן ועובר על עון, כמו שאומר בתקון הב׳ נושא עון, והענין הוא, כי \u0003עון,\u0004 פירושו הדינים שבבינה שנצמחו בה מחמת עלית המלכות אליה. כי עון משמע שהיה ישר ונעשה מעוות. אבל \u0003פשע,\u0004 מורה על הדינים שבמלכות עצמה, שהיא פשע מעיקרה, ולא שנעשתה למעוות. ומדייק הכתוב, שרוח החכמה העובר באורח הזה מן החוטם, מלבד מה שמטהר את הבינה, מטהר ג״כ הדינים של המלכות הנקראים \u0003פשע,\u0004 כדי שיוכל לעבור ולהאיר דרך שם אל הארח של שפה תתאה הנעשה בשבולת הזקן, ששם בחינת המלכות עצמה (כמ״ש להלן באות קל״א). ותקון זה מעלתו גדלה מאד, וז״ש \u0003כמה ערקיסאות מחכאן\u0004 וכו׳. כי מועטים הם שזוכים לזה בשלמותו."],[2,"","[ג] \u0003תאנא בצניעותא דספרא\u0004 וכו׳: למדנו בספרא דצניעותא, מהו שכתוב, פשע. זכו עובר. לא זכו פשע. וזה נוהג רק בז״א. ולא בא״א שכולו רחמים."],[3,"מאי בין האי להאי","וכו׳: שואל מה בין זה לזה, בין א״א לז״א. ומשיב, בז״א, כשיורד האורח ההוא מתחת נקבי החוטם, כתוב ויחר אף ה׳ בם וילך. מהו וילך. היינו, שיוצא רוח של רוגז מאלו הנקבים, ומי שנמצא לפניו הולך ואינו נמצא. ז״ש, כי רוח ה׳ נשבה בו ואיננו. אבל בא״א, כתוב ועובר על פשע, וכתוב, ורוח עברה ותטהרם. ולמדנו, כאן בארח הזה כתוב, עובר על פשע. ושם, ועבר ה׳ לנגוף את מצרים."],[3,"","פירוש. ארח זה שעל שפה עלאה הוא דרך שיעבור בו רוח החכמה בשביל הצדיקים הנזהרים לקבל בבחינת קו האמצעי ממטה למעלה. וז״ש \u0003זכו עובר לא זכו פשע.\u0004 הצדיקים הזוכים להיות דבוקים בקו האמצעי, ומקבלים הרוח ממטה למעלה, הרי הוא בשבילם \u0003עובר\u0004 על פשע. אבל הרשעים שאינם זוכים להיות דבוקים בקו האמצעי, ורוצים להמשיך הרוח ממעלה למטה הוא להם \u0003פשע,\u0004 כלומר שמתגלים עליהם הדינים דמלכות הנקראים פשע. אבל, \u0003האי בזעיר אפין.\u0004 כי בא״א הוא כולו רחמים ולא שייך שם זה. וז״ש \u0003בזעיר אפין, כד נחית ההוא אורחא מתחות נוקבי חוטמא,\u0004 הנה לאותם שאינם דבוקים כראוי בקו האמצעי נאמר בהם, \u0003ויחר אף ה׳ בם וילך.\u0004 כי אהרן ומרים בעת שהיו מדברים במשה, שה״ס קו האמצעי, לא היו אז דבוקים בו, וע״כ, ויחר אף ה׳ בם וילך. \u0003מאי וילך, דנפיק רוחא דרוגזא מאינון נוקבי,\u0004 דהיינו שמתגלה דרך שם הפשע, כנ״ל לא זכו, פשע. \u0003ומאן דאשכח קמיה אזיל ולא אשתכח.\u0004 מי שנמצא לפניו, דהיינו שזכה לחכמה, הולך משם, והחכמה אינה נמצאת בו עוד. ז״ש, \u0003כי רוח ה׳ נשבה בו ואיננו.\u0004 כי נסתלק מהם. אבל, \u0003באריך אפין כתיב ועובר על פשע.\u0004 שרוח החכמה עובר על הפשע, ומכלה אותו, וכן ורוח עברה ותטהרם. מפני שלא שייכים בו דינים, אלא להיפך הוא משבית הדינים, והוא כולו רחמים. כי ועובר על פשע, פירושו שעובר לכלות את הפשע, כי, \u0003הכא כתיב עובר על פשע בההוא ארחא, התם, ועבר ה׳ לנגוף את מצרים,\u0004 מה \u0003ועבר\u0004 אשר שם, פירושו לכלות את המצרים, אף \u0003עובר\u0004 על פשע שבכאן, פירושו לכלות הפשע."],[4,"זכאה חולקיה","וכו׳: אשרי חלקו מי שזכה לקבל מתקון זה. וזה הוא התקון השלישי של דיקנא היקר הקדוש העליון דעתיק דעתיקין. אמר ר׳ שמעון ודאי שירבה הקב״ה להטיב לך, וישמח להגן עליך."],[5,"ותאנא מאי דכתיב","וכו׳: ולמדנו, מה שכתוב, שוש אשיש בה׳, נאמר בעתיק יומין, כי הוא שמחת הכל. למדנו, בשעה שנגלה הארח הזה של הדיקנא דעתיק יומין, כל בעלי יבבא ויללה (הנ״ל באות ק״ח וק״ט) ובעלי הדין, נסתמים ונשתקים, ואין מי שיפתח פתח להרע, משום שאורח זה יגלה לתקן. ומזה מי שאוחז ומזהיר להשתיק למי, הוא רושם לאורח הזה, שהוא סימן עתיקא קדישא."],[5,"","פירוש. כי מכח הדינים דמלכות דצמצום א׳ שבתקון הא׳, שנתמעטו משם הג״ר, יצאו בעלי יבבה ויללה המיבבים והמיללים על התמעטותם שהשיגו משם, כמ״ש לעיל (באות ק״ח וק״ט) ועתה, כאשר חזרו הג״ר להאיר באורח הזה שבתקון ג׳ בסוד ועובר על פשע, באו אותם בעלי יבבה ויללה על ספוקם, ואינם מיבבים ומיללים עוד. וז״ש, \u0003כלהו מארי דיבבה ויללה ומאריהון דדינא סתימין ושתיקין,\u0004 שאינם מיבבים ומיללים עוד, משום, \u0003ולית דיפתח פטרא לאבאשא,\u0004 כי חזרו להם הג״ר, ואין עוד דינים שיוכלו להזיקם ולמעטם. וז״ש, \u0003משום דהאי אורחא אתגלייא לתקנא,\u0004 כי ארח ההוא שבשפה עלאה, נתגלה לתקן ולהחזיר את הג״ר."],[5,"","וז״ש, \u0003ומהאי מאן דאחיד ואזהר לשתקאה להאי ארחא רשים, דהוא סימנא דעתיקא קדישא,\u0004 כי כמו שגילוי אורח זה בעתיקא קדישא השתיק מארי דיבבא ויללה שלא ייבבו וייללו, כך כל מי שרוצה להשתיק למי, שלא יצעק, מניח אצבעו על הארח שבשפה עלאה שלו."],[5,"","וז״ש (באות קכו/א). \u0003ותאנא, תקונא קדמאה דדיקנא ותניינא, לאייתאה לתליתאה,\u0004 כי בתקון הא׳, יצאה המלכות דמדת הדין לקבל תקון, אמנם במלכות דמדת הדין אין העולם יכול להתקיים. ובתקון הב׳ עלתה המלכות למקום בינה שהיא מדת הרחמים, כנ״ל, אמנם אז נעשה מיעוט ג״ר גם בבינה. ובתקון הג׳ חזרו הג״ר לבינה. ומשום שהמלכות כבר נמתקה בבינה קבלה גם היא הג״ר אלו, בסו״ה ועובר על פשע, כנ״ל. ולזה היתה כל הכונה. כי המלכות דמדת הדין אינה ראויה לקבל ג״ר, לפני גמר התקון, עד שיעברו עליה כל ג׳ התקונים האלו. ונמצא שב׳ תקונים הראשונים, שבהם המלכות עוד נמצאת בבחינת ו״ק, שלא הרויחה עוד כלום, היו אמנם הכנה שבתקון הג׳ תוכל לקבל ג״ר. הרי שב׳ תקונים הראשונים לא באו אלא להביא תקון הג׳. כי רק עתה קבלה המלכות את הריוח ממיתוקה בבינה. ולולא זה לא היה העולם יכול להתקיים (כנ״ל ב״א ז׳ ד״ה וכבר)."],[5,"","והנה בז״א, נקרא תקון ג׳ הזה, בשם \u0003וחנון.\u0004 והוא, כי חנון, פירושו עשית חסד עם מי שאינו הגון ואינו כדאי, כמו שפירשו חז״ל. (ברכות ז.) וכיון שבתקון הזה נעשתה המלכות ראויה לקבלת ג״ר אע״פ שממקורה אינה ראויה לזה. ע״כ נקרא התקון בשם \u0003וחנון.\u0004"],[6,"תקונא רביעאה","וכו׳: התקון הרביעי. השערות מתתקנות תחת הפה, מראש אחד לראש אחד. דהיינו שבולת הזקן. ז״ש, לשארית נחלתו. כש״א, ונשאת תפלה בעד השארית הנמצאה. הנמצאה ממש. שארית, הוא כעין, שכתוב, שארית ישראל לא יעשו עולה."],[6,"","פירוש. אחר שהמלכות דשערות כבר נמתקה כולה במקום בינה, בתקון הג׳ בסוד ועובר על פשע, היא חזרה להתעורר שמה בין השערות שבמקום בינה, כלומר שנגלה שאין מקומה שם בבינה, בלחי העליונה. וע״כ הוכרחו השערות דמלכות הנמתקת לרדת ללחי התחתונה דהיינו תחת שפה תתאה, בסוד שבולת הזקן. וכיון שירדה ממקום בינה נסתלקו ממנה הג״ר וחזרה והיתה לו״ק בלי ראש. וז״ש, \u0003תקונא רביעאה מתתקן שערא תחות פומא\u0004 וכו׳. שה״ס שבולת הזקן. וז״ש, \u0003הה״ד לשארית נחלתו,\u0004 כי תקון ד׳ הזה נקרא בא״א, לשארית נחלתו. שהוא \u0003כד״א ונשאת תפלה בעד השארית הנמצאה,\u0004 כי ע״כ נקראים שערות אלו שארית, מלשון הכתוב, \u0003שארית הנמצאה,\u0004 דהיינו שארית השערות שהוכרו בשפה עלאה שהן מבחינת מלכות ואינן מבחינת בינה, ואין מקומם בלחי העליונה בשפה עלאה, אלא הוכרחו לרדת למטה מפה ללחי התחתונה, לחוץ מראש. וז״ש, \u0003הנמצאה ממש,\u0004 שמקודם לכן היו תחת התקון ועובר על פשע, ולא היו נכרות שמה, ועתה הוכרו ונמצאו. והשם שארית, הוא כמו, \u0003דכתיב, שארית ישראל לא יעשו עולה.\u0004 כלומר אע״פ שהם \u0003שארית,\u0004 ונאבדו הג״ר שלהן, מ״מ אין בזה עולה, אלא להיפך, שהוא תקון גדול אל השערות דמלכות, שהוא כדי שיקבלו תקון הג״ר במקומם עצמם, כמ״ש להלן בתקון החמשי."],[6,"","ויש לדעת שאלו התקונים הם שורשים לעיבור ולידה הנוהגים בפרצופים. כי תקון הב׳, ששערות המלכות עלו להתתקן במקום בינה שהיא שפה עלאה זה שורש לבחינת עיבור המתתקן במעי אמו. כי בינה נבחנת לאם המלכות. וה״ס אור הנפש, שתקון ב׳ הוא ו״ק דנפש, ותקון ג׳ ג״ר דנפש. ותקון הד׳, שהיא ירידת שערות המלכות משפה עלאה לשפה תתאה נבחן כמו לידה. כי המלכות יצאה ממעי הבינה ובאה למקומה ללחי התחתונה. וה״ס אור הרוח, שתקון ד׳ הוא ו״ק דרוח. ותקון ה׳ הוא ג״ר דרוח."],[7,"תקונא חמישאה","וכו׳: התקון החמישי. יוצא אורח אחר מתחת הפה. ז״ש, לא החזיק לעד אפו. קום ר׳ יוסי. קם ר׳ יוסי, פתח ואמר, אשרי העם שככה לו אשרי העם שה׳ אלקיו, שואל, אשרי העם שככה לו, מהו שככה לו. ומשיב, הוא כמו שאתה אומר, וחמת המלך שככה. שפירושו שנשקט מרוגזו."],[8,"ד״א שכיך ברוגזיה","וכו׳: פירוש אחר שנשקט ברוגזו, כלומר שבסבת הרוגז נשקט. ז״ש, ואם ככה את עושה לי הרגני נא הרוג. ונמצא, אשרי העם שככה לו, הוא דין שבדין. אשרי העם שה׳ אלקיו הוא רחמים שברחמים."],[9,"ד״א שככה שמא","וכו׳: פירוש אחר. שככה, הוא שם הכולל כל השמות, שהקב״ה נשקט, כי מעביר רוגזו ועושה נחת לזעיר אנפין. ונשקט, ומעביר רוגזו על כל אלו שבחוץ."],[9,"","פירוש. כי יש ב׳ מיני רוגז יש רוגז מדינין דנוקבא, שהוא מסבת עלית המלכות לבינה, שהבינה נתמעטת לו\"ק בלי ראש. שה״ס הזריעה שבנקודת החולם המובאה לעיל (ב״א ט״ו ד״ה ההוא) ויש רוגז מדינין דדכורא, שהוא מסבת יציאת קו שמאל מטרם שמתיחד בימין, שה״ס הזריעה דנקודת השורק, (כמ״ש שם) או ע״י חטאי התחתונים שרוצים להמשיך החכמה דקו שמאל ממעלה למטה, שעי״ז מפרידין קו שמאל מקו ימין, שאז נמשכים מקו שמאל דינים קשים. שזה בחינת רוגז מדינין דדכורא."],[9,"","וז״ש (באות קל״א) \u0003מהו שככה לו, כד״א וחמת המלך שככה.\u0004 אף כאן, שככה פירושו \u0003שכיך מרוגזיה.\u0004 והיינו מרוגז הדינים דנוקבא, דהיינו ממצב ו״ק בלי ראש. ולפי״ז יהיה פירוש הכתוב, \u0003אשרי העם שככה לו,\u0004 שנשקט מדינין דנוקבא, ונגלו לו ג״ר, שאז \u0003אשרי העם שה׳ אלקיו,\u0004 שיש לו ג״ר שה״ס השם הוי״ה אלקים. וכן פירוש הכתוב, \u0003לא החזיק לעד אפו,\u0004 היינו דינין דנוקבא, כי יצא באמצע שבולת הזקן, אורח הפנוי משערות, שה״ס גילוי הג״ר, ע״י רוח הנושב מן נקבי החוטם דז״א."],[9,"","וז״ש (באות קל״ב) \u0003ד״א שכיך ברוגזיה,\u0004 ושכיך שבכאן, היינו מרוגז הדינין דדכורא, שהם הדינים הקשים דקו שמאל בלי ימין, שה״ס חכמה בלי חסדים. והוא נשקט מהם בסבת רוגזו. כלומר שע״י המסך דחירק שבקו אמצעי, נגלה הרוגז מבחינת המלכות שהיא ממעטת הקו השמאלי לו״ק, ואז, מסבת המיעוט ורוגז הזה הוא מתיחד עם קו ימין והוא נשקט עי״ז מרוגז האחר, שהוא הדינין דשמאל (כנ״ל לך י״ג ד״ה ונתבאר ע״ש) ונמצא שהרוגז דדינים דמלכות, השקיט הדינים דדכורא שמשמאל. וזהו שאומר, \u0003שכיך ברוגזיה,\u0004 שברוגז דדינים דמלכות, נשקט ושכיך הדין והרוגז דשמאל."],[9,"","וז״ש, \u0003הה״ד ואם ככה את עושה לי הרגני נא הרוג.\u0004 כי האספסוף התאוו תאוה, ואמרו מי יאכילנו בשר. ופנימיות הענין, היינו, שהאספסוף נתדבק בקליפה הנקראת קץ כל בשר, דרעותיה למיכל בשרא, שה״ס המשכת הארת השמאל ממעלה למטה, שנקרא \u0003בשר\u0004 (כמ״ש לעיל נח דף מ״ח ד\"ה ת״ח ע״ש) ואז נמשכו דינים הקשים דשמאל בלי ימין. שה״ס דינים דדכורא, שזסו״ה ויחר אף ה׳ מאד ובעיני משה רע. עד שאמר \u0003הרגני נא הרוג\u0004 ואל אראה ברעתי. וז״ש, \u0003דא הוא דיני דדינא,\u0004 שדינים דשמאל אלו הם דינים קשים שבדינא, ועליהם נאמר, אשרי העם שככה לו, שנשקט מדינים הללו. ואז, זוכים אל, \u0003אשרי העם שה׳ אלקיו, רחמי דרחמי.\u0004 ולפי״ז יהיה הפירוש של \u0003לא החזיק לעד אפו,\u0004 על הרגז דדינין דדכורא, שעברו ע״י גילוי האורח שבשפה תתאה."],[9,"","וז״ש (באות קל״ג) \u0003ד״א, שככה, שמא דכליל כל שמהן,\u0004 שהמלה שככה, הוא שם הכולל כל השמות, דהיינו שכולל ב׳ התקונים הנ״ל, הן ששכיך מרוגזיה, והן ששכיך ברוגזיה, שהתקונים נקראים שמות. ומפרש, \u0003וקב״ה מעבר רוגזיה\u0004 דהיינו שמעביר דינין דנוקבא, \u0003ואנח ביה לזעיר אפין,\u0004 שמגלה הג״ר ועושה נחת לז״א, והן \u0003ומעביר\u0004 רוגזא דדכורא, \u0003על כל אינון דלבר,\u0004 דהיינו אותם שמבחוץ הדבוקים בשמאל, מעביר מהם הדינים שמייחד השמאל בימין ע״י גילוי הדינים דמסך דחירק כנ״ל. באפן, אשר, \u0003אשרי העם שככה לו\u0004 כולל ב׳ התקונים הן התקון דשכיך מרוגזיה. שהוא להוציא הג״ר, והן התקון דשכיך ברוגזיה, שהוא לבטל ולהעביר הדינין דשמאל. ועד״ז \u0003לא החזיק לעד אפו,\u0004 כולל ב׳ התקונים הנ״ל \u0003שלא החזיק לעד אפו\u0004 דדינין דנוקבא, וגילה האורח שבאמצעית שערות שפה תתאה. והן \u0003לא החזיק לעד אפו,\u0004 דדינין דדכורא, שמעביר הדינין דדכורא מאורח הזה שנתגלה בשפה תתאה, ע״י יחוד השמאל והימין, בסבת המסך דחירק דקו האמצעי."],[10,"דתניא ארחא עלאה","וכו׳: שלמדנו, ארח העליון של הדיקנא הקדוש, שהוא יורד, על שפה עלאה, תחת נקבי החוטם דעתיק, והאורח הזה שלמטה, באמצעיתא דשערות דשפה תתאה, שוים הם בכל. זה למעלה בשפה עלאה, וזה למטה בשפה תתאה. למעלה נקרא האורח, \u0003עובר על פשע,\u0004 ולמטה נקרא האורח \u0003לא החזיק לעד אפו.\u0004 ולמדנו, \u0003לא החזיק,\u0004 פירושו, שאין מקום לשבת שם. כמו שלמעלה נותן האורח מקום רק שיעבור בו רוח החכמה מן החוטם (כנ״ל אות קכ״ז), כך למטה הוא רק נותן מקום שיעבור בו רוח החכמה."],[10,"","פירוש. עתה מבאר, סוד שככה שבאורחין דשפה עלאה ושפה תתאה, לפי פירוש הג׳, הנ״ל, אשר \u0003שככה\u0004 כולל כל שמהן, הן לדינין דנוקבא והן לדינין דדכורא. וז״ש \u0003ארחא עלאה\u0004 וכו׳ \u0003והאי אורחא דלתתא, שקילן אינון בכלא,\u0004 כי ארחא עלאה מסיר דינין דנוקבא שיצאו עם תקון הב׳, בסוד שכיך מרוגזיה, וכן הוא מסיר הדינין דדכורא היוצאים עם גילוי החכמה, בסוד שכיך ברוגזיה, ועד״ז ארחא תתאה, מסיר דינין דנוקבא שיצאו עם תקון הד׳ בשפה תתאה, ונגלה בו החכמה, בסוד שכיך מרוגזיה, וכן הוא מסיר דינין דדכורא הנגלים עם גילוי החכמה, בסוד שכיך ברוגזיה."],[10,"","וז״ש \u0003לעילא עובר על פשע. לתתא, לא החזיק לעד אפו,\u0004 שב׳ שמות האלו משמעות אחת להם, \u0003ותנינן לא החזיק\u0004 פירושו, \u0003דלא אית אתר למיתב,\u0004 כי מכח שכיך ברוגזיה, המיחד קו שמאל עם הימין, שאז אין החכמה נמשכת ממעלה למטה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) ע״כ אינו מחזיק חכמה באותו אורח בבחינת לשבת שם, אלא רק לגלות שם הג״ר ממטה למעלה בלבד. וז״ש \u0003כמה דלעילא יהיב אתרא לאעברא,\u0004 כמו שלמעלה נותן מקום לעבור רוח חכמה בלבד דהיינו בשיעור שיצאו הג״ר, ואין החכמה מתישבת באורח הזה, כדי שלא ימשכוה ממעלה למטה (כנ״ל אות קכ״ז). \u0003כך לתתא יהיב אתר לאעברא.\u0004 ולא שהחכמה תתישב שמה, כדי שלא ימשכוה ממעלה למטה."]],[]],[["תָּנָא, בְּכָל אֲתָר דִּבְהַאי עַתִּיקָא טְמִירָא דְּכֹלָּא אָרְחָא אִתְגַּלְיָיא, טַב לְכֻלְּהוּ דִּלְתַתָּא, דְּהָא אִתְחֲזֵי עֵיטָא לְמֶעְבַּד טַב לְכֹלָּא. מַאן דְּסָתִים וְלָא אִתְגַּלְיָיא, לֵית עֵיטָא, וְלֵית מַאן דְּיֵדַע לֵיהּ, אֶלָּא הוּא בִּלְחוֹדוֹי. כְּמָה דְּעֵדֶן עִלָּאָה, לֵית דְּיֵדַע לֵיהּ אֶלָּא הוּא עַתִּיקָא דְּעַתִּיקֵי. וְעַל הַאי כְּתִיב, (תהילים צ״ב:ו׳) מַה גָּדְלוּ מַעֲשֶׂיךָ יְיָ מְאֹד עָמְקוּ מַחְשְׁבוֹתֶיךָ. אָמַר רַבִּי שִׁמְעוֹן יִתְתַּקְּנוּן עוֹבָדָךְ לְעָלְמָא דְּאָתֵי. מֵעִם עַתִּיקָא דְּעַתִּיקִין.","תִּקּוּנָא שְׁתִיתָאָה. מִתְתָּקֵן שַׂעֲרָא וְסָלִיק מִלְּרַע לְעֵילָּא, וְחָפֵי תַּקְרוּבְתָּא דְּבוּסְמָא טָבָא עַד רֵישָׁא דְּפוּמָא דִּלְעֵילָּא. וְנָחִית שַׂעֲרָא (דרישא) לְרֵישָׁא דְּפִתְחָא דְּאָרְחָא תַּתָּאָה דְּפוּמָא.","קוּם רִבִּי יֵיסָא וְאַתְקִין תִּקּוּנָא דָּא. קָם רִבִּי יֵיסָא, פָּתַח וְאָמַר, (ישעיהו נ״ד:י׳) וְחַסְדִּי מֵאִתֵּךְ לֹא יָמוּש, וּכְתִיב (ישעיהו נ״ד:ח׳) וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ, הָנֵי קְרָאֵי קַשְׁיָין אֲהַדְדֵי.","וְלָא אַקְשׁוּ, דְּתָנֵינָן, אִית חֶסֶד וְאִית חֶסֶד. אִית חֶסֶד דִּלְגוֹ, וְאִית חֶסֶד דִּלְבַר. חֶסֶד דִּלְגוֹ, הָא דְּאַמָרָן דְּעַתִּיקָא דְּעַתִּיקִין, וְהוּא סָתִים בְּסִטְרָא דָּא דְּדִיקְנָא, דְּאִקְרֵי פְּאַת הַזָּקָן. וְלָא בָּעֵי בַּר נָשׁ לְחַבְּלָא הַאי סִטְרָא, מִשּׁוּם הַאי חֶסֶד דִּלְגוֹ דְּעַתִּיק יוֹמִין. וּבְגִין כָּךְ, בְּכֹהֵן דִּלְתַּתָּא כְּתִיב בֵּיהּ, (ויקרא כ״א:ה׳) לֹא יִקְרְחֻה קָרְחָה בְּרֹאשָׁם וּפְאַת זְקָנָם לֹא יְגַלֵחוּ. מַאי טַעְמָא. בְּגִין דְּלָא לְחַבְּלָא אוֹרְחוֹי דְּחֶסֶד דְּעַתִּיקָא, דְּכֹהֵן מִסִּטְרָא דָּא קָא אָתֵי.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, בְּכֹלָּא אִצְטְרִיךְ חֶסֶד לְאִתְרַבְּאָה וּלְמִבְנֵי, וְלָא לְקַטְעָא לֵיהּ, וְלָא אִשְׁתְּצֵי מֵעָלְמָא. וְהַאי דִּכְתִּיב וְחַסְדִּי מֵאִתֵּךְ לֹא יָמוּש, חֶסֶד דְּעַתִּיק יוֹמִין. וּבְחֶסֶד עוֹלָם, חֶסֶד דְּאִקְרֵי חֶסֶד עוֹלָם, וְהַאי הוּא אַחֲרָא דִּזְעֵיר אַנְפִּין, דִּכְתִּיב, (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה.","וְהַאי חֶסֶד דְּעַתִּיק דְּעַתִּיקִין, הוּא חֶסֶד דִּקְשׁוֹט. וְחֶסֶד דִּקְשׁוֹט לָאו בְּחַיֵּי גּוּפָא אִתְּמַר, אֶלָּא בְּחַיֵּי דְּנִשְׁמְתָא. וּבְגִין כָּךְ כְּתִיב, (מיכה ז׳:י״ח) כִּי חָפֵץ חֶסֶד הוּא. דָּא הוּא תִּקּוּנָא שְׁתִיתָאָה דְּדִיקְנָא יַקִּירָא, דְּעַתִּיק דְּעַתִּיקֵי.","תִּקּוּנָא שְׁבִיעָאָה. פָּסִיק שַׂעֲרָא, וְאִתְחָזְן ב' תַּפּוּחִין בְּתִקְרוּבְתָּא דְּבוּסְמָא, שַׁפִּירָן וְיָאָן לְמֵחזֵי.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (שיר השירים ב׳:ג׳) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. מַה תַּפּוּחַ זֶה כָּלִיל בִּתְלַת גְּוָונֵי, כַּךְ קוּדְשָׁא בְּרִיךְ הוּא, תְּרֵין תַּפּוּחִין כָּלִיל שִׁיתָּא גְּוָונֵי, וּתְרֵין תַּפּוּחִין אִלֵּין, דְּאִינּוּן תִּקּוּנָא ז', אִינּוּן כְּלָלָא דְּכָל שִׁיתָא תִּקּוּנִין דַּאֲמֵינָא. וּבְגִינֵיהוֹן אִתְקָיָּים (משלי ט״ז:ט״ו) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים.","וְתָאנָא, מֵהָנֵי תַּפּוּחִין נָפְקִין חַיִּין לְעָלְמָא, וּמְחַזְיָין חֵידוּ לִזְעֵיר אַפִּין. כְּתִיב (במדבר ו׳:כ״ה) יָאֵר יְיָ פָּנָיו אֵלֶיךָ. וּכְתִיב (משלי ט״ז:ט״ו) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים. בְּאוֹר פְּנֵי מֶלֶךְ אִלֵּין אִינּוּן תְּרֵין תַּפּוּחִין דְּתִקְרוֹבְתָּא דְּבוּסְמָא דַּאֲמֵינָא. יָאֵר יְיָ פָּנָיו אֵלֶיךָ, פָּנִים דִּלְבַר, דְּכַד נְהִרִין מִתְבָּרֵךְ עָלְמָא.","וְתָאנָא, כָּל זְמַן דְּהָנֵי בּוֹצִינֵי דִּלְבַר נְהִירִין, כָּל עָלְמָא מִתְבָּרֵךְ, וְלָא אִשְׁתְּכַח רוּגְזָא בְּעָלְמָא. וּמָה אִי הָנֵי דִּלְבַר כַּךְ. תְּרֵין תַּפּוּחִין דִּנְהִרִין תְּדִירָא, דְּחַדָּאן תְּדִירָא עַל אַחַת כַּמָּה וְכַמָּה.","תַּנְיָא, כַּד אִתְגַּלְּיָין תְּרֵין תַּפּוּחִין אִלֵּין, אִתְחֲזֵי זְעֵיר אַפִּין בְּחֶדְוָותָא. וְכָל אִינּוּן בּוּצִינִין דִּלְתַּתָּא, בְּחֶדְוָותָא. וְכָל אִינּוּן דִּלְתַּתָּא, נְהִרִין, וְכָל עָלְמִין חַדָּאן, וּשְׁלֵימִין מִכָּל שְׁלֵימוּתָא. וְכֹלָּא חַדָּאן וּנְהִרִין. וְכָל טִיבוּ לָא פָּסִיק. כֻּלְּהוּ אִתְמַלְּיָין בְּשַׁעֲתָא חֲדָא, כֻּלְּהוּ חַדָּאן בְּשַׁעֲתָא חֲדָא.","תָּא חֲזֵי, פָּנִים דִּלְבַר, אִית זְמַן דִּנְהִרִין, וְאִית זְמַן דְּלָא נְהִרִין. וּבְגִין כָּךְ כְּתִיב, יָאֵר יְיָ פָּנָיו אֵלֶיךָ. (תהילים ס״ז:ב׳) יָאֵר פָּנָיו אִתָּנוּ סֶלָה. מִכְלָל דְּלָא הֲוִי תְּדִירָא. אֶלָּא כַּד אִתְגַּלְּיָין תַּפּוּחִין דִּלְעֵילָּא.","תָּאנָא, אִלֵּין תַּפּוּחִין דִּסְתִּימִין, נְהִירִין וְחִוָּורִין תְּדִירָא. וּמִנְּהוֹן נְהִירִין לִתְלַת מְאָה וְשִׁבְעִין עִיבָר. וְכָל שִׁיתָא תִּקּוּנִין קַדְמָאִין דִּבְדִּיקְנָא בֵּיהּ כְּלִילָן. הֲדָא הוּא דִּכְתִּיב, (מיכה ז׳:י״ט) יָשׁוּב יְרַחֲמֵנוּ. יָשׁוּב, מִכְלָל דְּזִמְנִין טְמִירִין, וְזִמְנִין אִתְגַּלְּיָין. הָכָא, הוּא יָשׁוּב יְרַחֲמֵנוּ. וּבְהַאי דִּלְתַתָּא, הוּא וְאֱמֶת. דָּא הוּא תִּקּוּנָא שְׁבִיעָאָה, דְּכָלִיל שִׁיתָא, בִּתְרֵין תַּפּוּחִין דִּבְעַתִּיקָא דְּעַתִּיקִין."],[[0,"תנא בכל אתר","וכו׳: למדנו בכל מקום שנגלה אורח, בעתיק הזה הנסתר מכל, טוב לכל המדרגות שלמטה, כי המשמעות של גילוי אורח, הוא שנתגלה עצה לעשות טוב לכל. כלומר שנתגלה עצה שכל התחתונים ימשכו מוחין ממנו, להיותו מראה על הסרת ב׳ בחינות דינין הנ״ל, וגילוי הג״ר. מי שסתום ואינו מגולה, דהיינו המקומות המלאים שערות ואין בהם אורח, זה מראה שאין עצה שיתגלו המוחין לתחתונים. ואין מי שישיג שם אלא הוא בעצמו ולא מדרגה אחרת למטה ממנו, כמו שעדן העליון, שה״ס חכמה סתימאה דא״א, אין מי שישיגו אלא הוא עצמו עתיק העתיקין. ועל זה כתוב, מה גדלו מעשיך ה׳ מאד עמקו מחשבותיך. דהיינו שממציא עצות שיוכלו המוחין להתגלות לתחתונים. אר״ש, יתתקנו מעשיך לעולם הבא מעם עתיקא דעתיקין."],[0,"","ואלו ב׳ תקינים דא״א הד׳ וה׳, שנקראים בו לשארית נחלתו, ולא החזיק לעד אפו. נקראים בז״א, דהיינו בי״ג שבתורה, \u0003ארך אפים.\u0004 והיינו ע״ד שפרשו חז״ל, מאריך אפו וגבה דיליה. כי בתקון הד׳ האריך האף שלו, כי שוב נתגלו הדינים והקטנות בשפה תתאה, ובתקון ה׳, שנעשה גם בשפה תתאה, האורח הפנוי משערות, ומקבל רוח חכמה מנקבי החוטם, דרך אורח העליון שעל שפה עלאה, הרי הוא גבה דילה. שחוזר ומשבית הדינים. ותקון הזה נבחן לשורש לג״ר דרוח (כנ״ל אות ק״ל בהסולם) ונודע שבז״א עוד שולטים במדרגה זו דינים דשמאל. עד שמופיעים הג״ר דנשמה. כמ״ש בתקונים הבאים."],[1,"תקונא שתיתאה","וכו׳: תקון הששי. השערות מתתקנות ועולות ממטה למעלה דהיינו ממקום תחת שפה תתאה שבלחי התחתונה עד למעלה ללחי העליונה והמנחה של בושם הטוב, דהיינו התפשטות השערות, מכסות מתחת שפה תתאה עד ראש הפה שלמעלה שבשפה עלאה, שהוא הלחי העליונה שה״ס שורש עבור ב׳ לצורך נשמה. ואחר העבור, חוזרות ויורדות השערות לראש הפתח של הארח התחתון דפה שמתחת שפה תתאה. דהיינו שנולדים ובאים למקומם הקבוע בלחי התחתונה, וה״ס מרחב הזקן, המתפשט בלחי התחתונה מזוית הלחי עד ראש השפה עלאה ועד תחת שפה תתאה. ונקרא ג״כ פאת הזקן."],[1,"","פירוש, אחר שכבר נשלמו השערות בג״ר דרוח ע״י אורחא תתאה שבשבולת הזקן שמתחת שפה תתאה מגיע הזמן לעלות לעבור לצורך ו״ק דגדלות, וז״ש \u0003מתתקן שערא וסליק מלרע לעילא\u0004 וכו׳ \u0003עד רישא דפומא דלעילא,\u0004 שהיא בחינת עליה למקום בינה, כמו בתקון הב׳. אלא שעבור הזה הוא לצורך קבלת אור הנשמה. שבעבור משיג נפש דנשמה, ואח״כ בסוד הלידה משיג רוח דנשמה. וז״ש, \u0003ונחית שערא לרישא דפתחא דאורחא תתאה דפומא,\u0004 דהיינו שחוזר ויוצא ממעי האם שהיא בינה שהיא הלחי העליונה ויורד למקומו ללחי התחתונה, שה״ס לידה ויניקה, שבירידה זו משיג רוח דנשמה. ויש לו ו״ק דג״ר. ומכונים \u0003תקרובתא דפוסמא,\u0004 משום שהג״ר מכונים בשמים וריח הטוב."],[2,"קום ר׳ ייסא","וכו׳: קום ר״י והתקן תקון הזה. הששי. קם ר׳ ייסא, פתח ואמר, וחסדי מאתך לא ימוש וכתוב, ובחסד עולם רחמתיך. מקראות אלו קשים זה על זה. כי כאן כתוב לא ימיש, שהיא לנצחיות. וכאן אומר ובחסד עולם. שמשמע שאינו נוהג אלא בימי עולם שהוא שתא אלפי שני."],[3,"ולא אקשו, דתנינן","וכו׳: ומשיב ולא קשה. כי למדנו שיש חסד ויש חסד. יש חסד שמבפנים שהוא אור הנשמה, ויש חסד שמבחוץ, שהוא אור הרוח. ומפרש, חסד שמבפנים, הוא שאמרנו בעתיקא דעתיקין, שהוא סתום בצד הזה של הדיקנא שנקרא פאת הזקן (כנ״ל באות קל״ו). שהוא תקון הששי. שהאדם אין צריך להשחית צד הזה, משום חסד הזה שבפנים, שה״ס ו״ק דנשמה (כמ״ש שם) של עתיק יומין. ומשום זה בכהן של מטה כתוב בו, לא יקרחה קרחה בראשם ופאת זקנם לא יגלחו. מהו הטעם. הוא כדי שלא להשחית דרכיו, דהיינו תקוניו, של חסד דעתיק, כי הכהן בא מצד הזה. דהיינו מצד החסד."],[4,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא, בכל אפן צריך החסד להתרבות ולהבנות, ולא לקצץ אותו דהיינו לא להשחית פאת זקנו. כי אינו כלה מן העולם. והיינו שכתוב \u0003וחסדי מאתך לא ימוש.\u0004 שהוא חסד דעתיק יומין. הנמשך ע״י תקון הזה הששי. \u0003ובחסד עולם,\u0004 היינו חסד שנקרא חסד עולם. וזה הוא חסד אחר שבז״א שהוא בחינת רוח, שכתוב אמרתי עולם חסד יבנה."],[5,"והאי חסד דעתיק","וכו׳: וחסד הזה דעתיק דעתיקין שבתקון הששי, הוא חסד של אמת, וחסד של אמת לא נאמר בחיי הגוף, שהוא בחינת רוח, דהיינו ז״א שנקרא גוף. אלא בחיי הנשמה. כי התקון הששי הוא ו״ק דגדלות, שה״ס חיי הנשמה (כנ״ל אות קל״ו) ומשום זה כתוב, \u0003כי חפץ חסד הוא,\u0004 שזה הוא התקון הששי של דיקנא היקר של עתיק דעתיקי, פירוש. כי אור הנשמה נמשך מבינה שהחסד שלה הוא בחינת כי חפץ חסד הוא. שחפצה בחסד יותר מבחכמה, כנודע. ולפיכך נקרא תקון זה כי חפץ חסד הוא. ובי״ג מדות שבתורה נקרא תקון זה בשם \u0003ורב חסד.\u0004 להורות שהוא חסד דנשמה, שהוא חסד רב וגדול."],[6,"תקונא שביעאה","וכו׳: התקון השביעי. השערות נפסקות ונראים ב׳ תפוחים במנחת הבושם. נאים ויפי מראה. כלומר שב׳ צדי הפנים פנוים משערות נראים מתוך שערות הדיקנא, הנקראות מנחת הבושם. להיותן שורשים להארת החכמה הזו המכונה ריח, בסו״ה והריחו ביראת ה׳."],[7,"פתח ר״ש ואמר","וכו׳: פר״ש ואמר, כתפוח בעצי היער וגו׳. מה תפוח הזה כלול ג׳ צבעים, לבן אדום ירוק, כך הקב״ה, תרין תפוחין כלולים ששה צבעים, וב׳ תפוחים אלו, שה״ס ב׳ צדי הפנים הפנוים משערות, שהם התקון הז׳, הם כלל של כל ששה התקונים הקודמים שאמרתי. ובשבילם מתקיים באור פני מלך חיים."],[7,"","פירוש. אחר שנשלמו הו״ק דגדלות ע״י תקון ו׳, הגיע עתה הזמן להמשיך ג״ר דגדלות. וז״ש, \u0003פסיק שערא,\u0004 כי נמשכת הארת החכמה המפסיקה השערות, כנ״ל בתקון ג׳ ותקון ה׳, \u0003ואתחזן ב׳ תפוחין בתקרובתא דבוסמא,\u0004 שנראים ב׳ תפוחי הפנים במנחת הבושם, שה״ס ג״ר דגדלות, שמהם נמשכת הארת החכמה המכונה ריח, וע״כ מכונים \u0003תפוחין,\u0004 כי תפוחים יש להם ריח טוב. וכן הם מכונים \u0003תקרובתא דבוסמא.\u0004 והשם תפוח יש לו הוראה מיוחדת על הארת החכמה הזו שה״ס ו״ק דחכמה, והנמשכת מג׳ קוין, שה״ס חג״ת, שעל זה רומזים ג׳ גוונים לבן אדום ירוק שיש בתפוח. ויש כאן ב׳ תפוחין קדישין, דהיינו בימין ושמאל, שג׳ גוונים שבתפוח הימין נקראים חג״ת וג׳ גוונים שבתפוח השמאל נקראים נה״י, וז״ש, \u0003מה תפוח זה כליל בתלת גווני,\u0004 שה״ס ג׳ קוין, \u0003כך קב״ה, תרין תפוחין כליל שיתא גווני.\u0004 שג׳ קוין שבימין ה״ס חג״ת וג׳ קוין שבשמאל ה״ס נה״י. להורות שהארת חכמה שבהם הוא רק ו״ק דחכמה, דהיינו חג״ת נה״י דחכמה. ואין שם ג״ר דחכמה. וכל ששת התקונים הקודמים לא היו אלא כדי להביא תקון הז׳ הזה, וע״כ הוא כלול מששה תקונים הקודמים. וז״ש, \u0003ותרין תפוחין אלין דאינון תקונא ז׳, אינון כללא דכל שתא תקונין דאמינא.\u0004 כי לא באו אלא להביא תקון השביעי הזה. וז״ש \u0003ובגיניהון אתקיים באור פני מלך חיים,\u0004 שבשביל ששת התקונים הקודמים נתקיים בתקון הז׳, באור פני מלך חיים. דהיינו שנגלתה הארת החכמה בפני המלך, שאור החכמה מכונה חיים. בסו״ה והחכמה תחיה בעליה."],[8,"ותאנא מהני תפוחין","וכו׳: ולמדנו מאלו תפוחים יוצאים חיים לעולם, שה״ס הארת חכמה, ומראים שמחה לזעיר אנפין, שכתוב, יאר ה׳ פניו אליך. וכתוב באור פני מלך חיים. \u0003באור פני מלך,\u0004 אלו הם ב׳ תפוחין של מנחת הבושם שאמרתי, \u0003יאר ה׳ פניו אליך,\u0004 היינו הפנים שבחוץ, דהיינו של ז״א שהוא לחוץ מא״א, כי כשהם מאירים מתברך העולם."],[9,"ותאנא כל זמן","וכו׳: ולמדנו, כל זמן שאלו הנרות שמבחוץ מאירים, שהם זו״ן, כל העולם מתברך ולא נמצא כעס בעולם. ומה אם אלו שמבחוץ כך, ב׳ תפוחים דא״א, שמאירים תמיד ושמחים תמיד, על אחת כמה וכמה."],[10,"תניא כד אתגליין","וכו׳: למדנו, כשב׳ תפוחים אלו מתגלים, נראה זעיר אנפין בשמחה, וכל אלו הנרות שלמטה, שבמלכות, הן בשמחה, וכל אלו שלמטה מאירים, וכל העולמות הם בשמחה ושלמים מכל השלמות. והכל שמחים ומאירים, וכל חסד אינו נפסק, כולם מתמלאים בשפע בשעה אחת, כולם שמחים בשעה אחת."],[11,"ת״ח פנים דלבר","וכו׳: בוא וראה, הפנים שבחוץ, דהיינו של ז״א, יש זמן שמאירים ויש זמן שאינם מאירים. ומשום זה כתוב, יאר ה׳ פניו אליך. יאר פניו אתנו סלה שמשמע מזה שאינו מאיר תמיד. שע״כ אנו מתפללים שיאיר לנו. כי אינם מאירים בז״א, אלא כשנתגלו התפוחים דא״א למעלה."],[12,"תאנא אלין תפוחין","וכו׳: למדנו, אלו תפוחים דא״א הסתומים, מאירים ולבנים תמיד. ומהם מאירים לש״ע צדדים. (כמ״ש לעיל אות י״ט) וכל ששת התקונים הראשונים שבדיקנא כלולים בהם. ז״ש \u0003ישוב ירחמנו,\u0004 ישוב, משמע, שפעמים הם נסתרים ופעמים הם גלוים. כאן בא״א, נקרא תקון הזה \u0003ישוב ירחמנו.\u0004 ובזה שלמטה, שבדיקנא דז״א, דהיינו בי״ג מדות שבתורה, הוא נקרא \u0003ואמת.\u0004 זה הוא תקון השביעי הכולל ששה בשני תפוחים שבעתיק דעתיקין. שהוא א״א. כמ״ש לעיל."]],[]],[["תִּקּוּנָא תְּמִינָאָה. נָפִיק חַד חוּטָא דְּשַׂעְרֵי סוֹחֲרָנֵיהּ דְּדִיקְנָא, וְתַלְיָין בְּשִׁקּוּלָא עַד טַבּוּרָא. קוּם אֶלְעָזָר בְּרִי, אַתְקִין תִּקּוּנָא דָּא.","קָם רִבִּי אֶלְעָזָר (בריה), פָּתַח וְאָמַר, הַכֹּל תָּלוּי בְּמַזָּל, וַאֲפִילּוּ סֵפֶר תּוֹרָה בָּהֵיכָל. מִלָּה דָּא אוֹקִימְנָא בְּסִפְרָא דִּצְנִיעוּתָא, וְהָכָא אִית לְאִסְתַּכְּלָא, וְכִי הַכֹּל תָּלוּי בְּמַזָּל, וְתָנֵינָן, סֵפֶר תּוֹרָה קֹדֶשׁ, וְנַרְתֵּקוֹ קֹדֶשׁ, וְהַהֵיכָל קֹדֶשׁ. וּכְתִיב (ישעיהו ו׳:ג׳) וְקָרָא זֶה אֶל זֶה וְאָמַר קָדשׁ קָדשׁ קָדשׁ, הָא תְּלַת אִינּוּן. וְסֵפֶר תּוֹרָה. לָקֳבְלֵיהוֹן, נַרְתְּקוֹ קֹדֶשׁ, וְהַהֵיכָל קֹדֶשׁ, וְהוּא קָדשׁ. וְהַתּוֹרָה נִתְּנָה בְּג' קְדוּשׁוֹת. בְּשָׁלֹשׁ מַעֲלוֹת, בְּיָּמִים שְׁלֹשָׁה, שְׁכִינָה בְּשָׁלֹשׁ, לוּחוֹת וַאֲרוֹן וְהֵיכַל בְּסֵפֶר תּוֹרָה תַּלְיָא, וְאִיהוּ תַּלְיָא בְּמַזָּל, וּכְתִיב (ירמיהו י׳:ב׳) וּמֵאוֹתוֹת הַשָּׁמַיִם אַל תֵּחָתּוּ. מַאן דְּאִיהוּ בִּקְדוּשׁוֹת הַלָּלוּ לֶהֱוֵי תַּלְיָא בְּמַזָּלָא.","אֶלָּא הָכִי אוֹקִימְנָא בְּסִפְרָא דִּצְנִיעוּתָא, הַאי חוּטָא יַקִּירָא קַדִּישָׁא, דְּכָל שַׂעְרֵי דְּדִיקְנָא תַּלְיָין בֵּיהּ, אִתְקְרֵי מַזָּל. מַאי טַעְמָא. מִשּׁוּם דְּכָל קָדְשֵׁי קוֹדָשִׁין דְּקוּדְשַיָּא, בְּהַאי מַזָּלָא תַּלְיָין. וְסֵפֶר תּוֹרָה, אַף עַל גַּב דְּאִיהוּ קָדוֹשׁ לָא חָל עָלֵיהּ עֶשֶׂר קִדוּשִׁין עַד דְּעָיִיל לָהֵיכָל. כֵּיוָן דְּעָיִיל לָהֵיכָל, אִתְקְרֵי קָדוֹשׁ בְּעֶשֶׂר קְדוּשׁוֹת. כְּגַוְונָא דָּא דְּלָא אִתְקְרֵי הֵיכָל, אֶלָּא כַּד אִתְחַבְּרָן עֶשֶׂר קְדוּשׁוֹת. וְתָאנָא, הַכֹּל תָּלוּי בְּמַזָּל, דְּאִיהוּ הַאי חוּטָא יַקִּירָא קַדִישָׁא, דְּכָל שַׂעֲרִין תַּלְיָין בֵּיהּ.","אֲמַאי אִקְרֵי מַזָּל. מִשּׁוּם דְּמִנֵּיהּ תַּלְיָין מַזָּלֵי, וּמַזְּלֵי מִנֵּיהּ עִלָּאִין וְתַתָּאִין. וּבְגִין כָּךְ אִיהִי תַּלְיָיא. וּבֵיהּ תַּלְיָין כָּל מִלֵּי דְּעָלְמָא עִלָּאִין וְתַתָּאִין. וַאֲפִילּוּ סֵפֶר תּוֹרָה שֶׁבָּהֵיכָל, דְּמִתְעַטֵּר בְּעֶשֶׂר קְדוּשׁוֹת, לָא נָפִיק מִכְּלָלֵיהּ עִם שְׁאַר קִדּוּשִׁין וְכֻלְּהוּ תַּלְיָין בְּהַאי. וּמַאן דְּחָמֵי לְהַאי תִּקּוּנָא, אִתְּכַּבְּשָן חוֹבֵיהוֹן מִקַּמֵּיהּ וּמִתְכַּפְיָין, הֲדָא הוּא דִכְתִיב, (מיכה ז׳:י״ט) יִכְבּוֹש עֲוֹנוֹתֵינוּ. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, בְּרִיךְ בְּרִי לְקוּדְשָׁא דְּקַדִּישִין, עַתִּיק מִכֹּלָּא.","תִּקּוּנָא תְּשִׁיעָאָה. מִתְעָרְבִין שַׂעְרֵי עִם אִינּוּן שַׂעְרֵי דְּתַלְיָין, וְלָא נָפְקִין דָּא מִן דָּא. קוּם רִבִּי אַבָּא, קָם רִבִּי אַבָּא וְאָמַר, אִלֵּין (אינון) שַׂעְרֵי דְּמִתְעָרְבִין עִם אִינּוּן דְּתַלְיָין, אִקְרוּן מְצוּלוֹת יָם. מִשּׁוּם דְּנַפְקֵי מִמּוֹתְרֵי מוֹחָא, וּמֵהַאי אַתְרָא רְמִיוּ, כָּל מָארֵי דְּתַבְעִין חוֹבֵי דִּבְנֵי נָשָׁא וּמִתְכַּפְיָין. אָמַר רַבִּי שִׁמְעוֹן, בְּרִיךְ תְּהֵא לְעַתִּיק יוֹמִין.","תִּקּוּנָא עֲשִׁירָאָה. נַחְתִּין שַׂעְרֵי תְּחוֹת דִּיקְנָא, וְחַפְּיָין בִּגְרוֹנָא תְּחוֹת דִּיקְנָא. קוּם רִבִּי יְהוּדָה. קָם רִבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיהו ב׳:י״ט) וּבָאוּ בִּמְעָרוֹת צוּרִים וּבִמְחִלּוֹת עָפָר מִפְּנֵי פַּחַד יְיָ וְגוֹ'. מִפְּנֵי פַּחַד יְיָ, הָא אִתְיְדַע דְּמַאן דְּאִיהוּ לְבַר, פַּחַד יְיָ אִתְקְרֵי. וּמֵהֲדַר גְּאוֹנוֹ, אִינּוּן שַׂעְרֵי דִּתְחוֹת דִּיקְנָא, וְאִתְקְרוּן הֲדַר גְּאוֹנוֹ, תְּרֵי. תִּקּוּנָא עֲשִׂירָאָה, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב. וְחַד סָר, דְּלָא נַפְקֵי נִימָא מִן נִימָא, חֶסֶד לְאַבְרָהָם.","תִּקּוּנָא דִּתְרֵיסָר. דְּלָא תַּלְיָין שַׂעְרֵי עַל פּוּמָא, וּפוּמָא אִתְפְּנֵי מִכָּל סִטְרִין, וְיָאִין שַׂעְרֵי סְחוֹר סְחוֹר לֵיהּ, בְּגִין דְּלָא אִשְׁתְּכַח טַרְחוּתָא, כְּמָה דְּאִצְטְרִיךְ.","טַרְחוּתָא בְּמַאי קָא מַיְירֵי. דִּינָא. בַּאֲתָר (נ\"א בתר) דִּינָא טַרְחוּתָא אִשְׁתְּכַח. וְכִי שַׂעְרֵי דְּדִיקְנָא טִרְחָא אִינּוּן, אוֹ דִּינָא אִינּוּן, וְהָא כֹּלָּא רַחֲמֵי אִתְחָזוּן. אֶלָּא דְּלָא אִתְטְרַח בְּיִשּׁוּבָא (ס\"א בנשובא) דְּרוּחָא דִּזְעֵיר אַפִּין.","דְּתָאנָא מֵהַאי פּוּמָא קַדִּישָׁא עִלָּאָה, קֹדֶשׁ קֳדָשִׁים, נָשְׁבָא רוּחָא. מַאי רוּחָא. רוּחָא דְּאִיתְּרַק (ס\"א דאתדבק) בֵּיהּ, דְּמִתְלְבַּש בֵּיהּ (נ\"א דאתתקן ומתלבש ביה) זְעֵיר אַפִּין. וּמֵהַאי רוּחָא מִתְלַבְּשִׁין כָּל אִינּוּן דִּלְתַּתָּא. וְכַד הַהוּא רוּחָא נָפִיק, אִתְפְּרַשׁ לִתְלָּתִין וְשִׁבְעָה אֶלֶף עִיבָר. וְאִתְפָּשַּׁט (ס\"א ואתפרשא) כָּל חַד בִּלְחוֹדוֹי לְאַתְרֵיהּ, וְכָל מַאן דְּאִתְחֲזֵי לְאִתְלַבְּשָׁא מִנֵּיהּ אִתְלָבַּשׁ. וְעַל דָּא שַׂעֲרִין לָא אִשְׁתְּכָחוּ עַל פּוּמָא קַדִּישָׁא, מִשּׁוּם דְּרוּחֵיהּ נָפִיק, וְלָא בָּעֵי מִלָּה אַחֲרָא לְאִתְעָרְבָא בֵּיהּ, וּלְקָרְבָא בַּהֲדֵיהּ."],[[0,"תקונא תמינאה","וכו׳: התקון השמיני. יוצא חוט אחד של השערות מסביב הדיקנא, ותלוים בשוד. עד הטבור של הלב. קום אלעזר בני, והתקן תקון הזה."],[1,"קם ר׳ אלעזר","וכו׳: קם ר״א, פתח ואמר, הכל תלוי במזל ואפילו ספר תורה בהיכל. דבר זה העמדנו בספרא דצניעותא. כי כאן יש להסתכל, וכי הכל תלוי במזל. והרי למדנו, ספר תורה הוא קדש, ונרתיקו קדש, וההיכל קדש. וכתוב, וקרא זה אל זה ואמר קדוש קדוש קדוש, הרי הם ג׳ קדושות, וספר התורה הוא כנגדם, שנרתיקו קדש וההיכל קדש והוא קדש. והתורה ניתנה בג׳ קדושות, בשלש מעלות, שהם נהנים לוים וישראלים, בימים שלשה, כמ״ש היו נכונים לשלשת ימים. וכן השכינה היא בשלשה, לוחות וארון והיכל. והכל תלוי בספר תורה. ואתה אומר, שספר התורה תלוי במזל. והרי כתוב, ומאותות השמים אל תחתו. מי שהוא בקדושות הללו יהיה תלוי במזל."],[2,"אלא הכי אוקימנא","וכו׳: ומשיב, אלא כך העמדתי בספרא דצניעותא, חוט הזה היקר והקדוש שכל השערות תלויות בו, דהיינו כללות שטח העליון של שערות הדיקנא המקיף את הפנים כמו חוט של שערות, הוא נקרא \u0003מזל.\u0004 מה הטעם. הוא משום שכל קדשי קדשים של הקדשים, דהיינו כל המדרגות והמוחין הנקראים קודש קדשים, תלוים במזל הזה, כי שפע מזל הזה נקרא קדשי קדשים וספר תורה, שהוא ז״א, אע״פ שהוא קדוש, לא חל עליו עשר קדושות, דהיינו שתהיינה לו ג״ר, עד שנכנס להיכל, שהוא המלכות. כי אינו נשלם בג״ר אלא ע״י זווגו עם המלכות. כיון שנכנס להיכל, דהיינו שמזדווג עם המלכות, נקרא קדוש בעשר קדושות, כעין זה, לא נקרא המלכות היכל אלא כשנתחברו בו עשר קדושות, דהיינו רק כשהוא בזווג עם ז״א, אז יש במלכות עשר קדושות, ולמדנו, הכל תלוי במזל, שכל אלו הג״ר דז״א ומלכות, תלויות במזל, שהוא חוט הזה היקר והקדוש שכל השערות תלויות בו. שממנו מקבלים כל אלו הקדושות."],[3,"אמאי אקרי מזל","וכו׳: שואל, למה נקרא מזל. ומשיב, משום שממנו תלוים ההצלחות, וממנו מזדלזלים העליונים והתחתונים. ומשום זה הוא תלוי, שתלוי ונמשך עד החזה. ובו תלוים כל דברי העולם העליונים ותחתונים, כי בני חיי ומזונא לאו בזכותא תלייא מילתא אלא במזלא תלייא מילתא. ואפילו ספר תורה שבהיכל, המתעטר בעשר קדושות אינו יוצא מכללו עם שאר כל הקדושות, כנ״ל בדבור הסמוך, וכולם תלוים בתקון הזה. ומי שרואה תקון זה נכבשים עונותיו לפניו ונכפים, ז״ש, \u0003יכבוש עונותינו.\u0004 אמר לו ר״ש, ברוך בנו לקדש הקדשים לעתיק מכל. \u0003מזל.\u0004 פירושו הצלחות, כי על הכתוב, הון יוסיף, מתרגם מזלא מוסיף. (משלי י״ט ד׳)"],[3,"","פירוש. אחר שנגלה תקון הז׳, שה״ס הג״ר שנתגלה בסוד אור פני מלך חיים. הגיע הזמן שיתגלה תקון הח׳, שהוא גילוי השבח של כללות השערות דיקנא, וז״ש, \u0003תקונא תמינאה, חד חוטא דשערי סוחרניה דדיקנא\u0004 כלומר, חוט שערות אחד כולל ומקיף כל שערות הדיקנא. כי עתה ניכרים שבחם וחשיבותם של כל השערות, שה״ס המיעוטים, איך כל אלו המוחין הגדולים נתגלו על ידיהם, כי אלו המוחין שנתבארו בכל תקון ותקון, כוללים כל מדרגות המוחין המושגים לאו״א וישסו״ת וזו״ן שבאצילות. ותקון ח׳ הזה כולל את כולם, ואפילו ד׳ תקונים האחרים שיתבארו לפנינו נכללו ג״כ בתקון הזה. וע״כ נקרא \u0003מזל,\u0004 מלשון יזל מים מדליו. וכבר נתבאר לעיל שהדיקנא בכללותה ה״ס \u0003ם׳\u0004 דצלם דגופא, כמו או״א עלאין, (כנ״ל באות צ״ה ע״ש) וז״ש, \u0003ותליין בשקולא עד טבורא.\u0004 דהיינו עד טבורא דלבא (כנ״ל אות ע״ב) שהוא מקום החזה דא״א, ששם מסתיימות ג״ר דגופא, הנבחנות ל \u0003ם׳\u0004 דצלם (כמ״ש שם באות צ\"ה)."],[3,"","וז״ש, (באות ק״נ) \u0003האי חוטא\u0004 וכו׳ \u0003אתקרי מזל. מ״ט משום דכל קדשי קודשין דקודשיא בהאי מזלא תליין.\u0004 כי אבא ואמא נקראים קודשיא, ובעת שהם כלולים בדיקנא, נקרא הדיקנא קדש קדשים, כלומר, קדש שממנו מקבלים הקדשים, שהם או״א הנקראים לפי עצמם, קודשיא, וז״ש \u0003קדשי קודשין דקודשיא.\u0004 ומ״ש קדשי קודשין, לשון רבים, הוא מפני שסובב על השערות. וז״ש, \u0003אמאי אקרי מזל משום דמניה תלייא מזלי,\u0004 כי כל המוחין הגדולים ביותר שאפשר שיבואו בשתא אלפי שני אינם באים אלא ע״י המזל הזה. ומזל, הוא לשון הצלחה שלא כדרך הטבע. ואומר טעם ב׳, \u0003ומזלי מניה עלאין ותתאין,\u0004 כי התחתונים מזדלזלים על ידו כמ״ש לעיל (אות צ״ט ע״ש). והעליונים ג״כ מזדלזלים, משום שמקור הדיקנא הוא מקרומא דאוירא, ששם עלתה הי׳ באור הבינה ונתמעטה לו״ק בלי ראש, וכן בתקון הב׳ דדיקנא ע״ש, וע״כ הם מזדלזלים על ידו. אמנם זלזול זה הוא שבח גדול לתחתונים, כי לולא זה לא היו התחתונים יכולים לקבל אורות החיים (כנ״ל ב״א דף ז׳ ד״ה וכבר)."],[3,"","וכבר נתבאר שעיקר שערות אלו נמשכים ממלכות דמדת הדין, אבל לא ממקומה אלא מקרומא דאוירא, שהיא שמה במקום בינה, בפנימיות הראש דא״א, וכדי למתק אותה ברחמים בשביל התחתונים היתה צריכה המלכות דמדת הדין לצאת מקרומא דאוירא, לחצוניות הראש, בסוד פאתי הראש, ומשם באה לתקון הא׳ של הדיקנא, (כנ״ל באות צ׳ ע״ש) ונתמתקה בחצוניות הראש ע״י תקון הב׳ ע״ש. ואחר שהמלכות דמדת הדין, גרמה ליציאת השערות והאורות הגדולים, של כל אלו שמונה תקוני דיקנא, נתעלתה שבחה, עד שיצאו הדינים והצמצומים שבה שהיו פועלים בכל שערות הדיקנא עד כאן. וז״ש, \u0003ומאן דחמי להאי תקונא אתכבשן חוביהון מקמיה ומתכפיין,\u0004 כי מי שזוכה בכל תקוני דיקנא עד תקון הח׳, כבר נכבשו כל הכחות הדין והצמצום שפעלו בסבת עירוב המלכות בבינה, כי עלה השבח על ההפסד אלף אלפי פעמים, ויותר. וכבר ידעת שכחות הצמצום והדין שקבלה הבינה ממלכות, מכונים מעוות ועון (כנ״ל אות קי״ט) וז״ש, \u0003הה״ד יכבוש עונותינו.\u0004 כי נכבשו ונתבטלו כלא היו, מחמת האורות הגדולים שיצאו בסבתה. ובי״ג מדות שבתורה שהם בז״א, נקרא תקון הזה \u0003ונוצר חסד,\u0004 על שם החסדים המרובים והנאמנים המתגלים בו כמבואר."],[4,"תקונא תשיעאה","וכו׳: תקון התשיעי. השערות מתערבות עם שערות התלויות, ואינן יוצאות זו מן זו. קום ר׳ אבא. קם ר׳ אבא ואמר, שערות אלו המתערבות עם אלו התלויות נקראות מצולות ים, משום שיוצאות מן מותרי המוח. וממקום הזה הושלך כל בעלי הדין התובעים על חטאי בני אדם, ונכנעים. א״ר שמעון ברוך תהיה לעתיק יומין."],[4,"","פירוש. כבר נתבאר סוד מקור השערות, שה״ס לבושי או״ח שהלבישו הג״ר דחכמה שבראש א״א מטרם הסתלקותן. ואחר שנסתלקו הג״ר, יצאו הלבושים מראש דא״א בבחינת פסולת (כנ״ל אות כ״ד ע״ש) שנקראים שערות. וכיון שהשערות היו נכללות מקודם בפנימיות הראש דא״א ע״כ יש בשערות דיקנא מבחינות ב׳ ראשים, מגלגלתא דא״א, וממו״ס דא״א. וההפרש ביניהן רב הוא, כי המוחא סתימאה, אע״פ שנסתם הוא נסתם רק מבחינת חכמה שבו, אבל בינה ותו״מ שבו אינם נסתמים, אלא יוצאים ומאירים לשערות דיקנא. ולפיכך מאותן השערות הנמשכות ממוחא סתימאה מהם נעשו שמונה תקונים הראשונים הנ״ל דשערות דיקנא. וע״כ יש בהם ג״ר, כי בינה זו שבמו״ס, חזרה להיות חכמה. כנודע. מה שאין כן הגלגלתא דא״א שנתקנה בבחינת \u0003ם׳\u0004 דצלם דראש, היא נעלמה מאד, ואותן השערות הנמשכות מן הגלגלתא הן בבחינת ו״ק חסר ראש, ומהן נתקנו ד׳ תקונים האחרונים. ומאותה הסבה, יש גם הפרש במקום תלייתן, כי ח׳ תקוני דיקנא הראשונים הנמשכים ממו״ס, שלא יצאו אלא מבחינת כתר וחכמה שבמו״ס, אבל בינה ותו״מ דמו״ס מאירים עוד בהם, ע״כ גם השערות לא יצאו מראש לגמרי, אלא שנתלו בלחי התחתונה, שרק מבחינת עצמות, הרומזות על חכמה, הוא נפרד מראש, אבל מבחינת גידין בשר עור הרומזים על בינה ותו״מ הוא עוד דבוק ומחובר בראש. אבל ד׳ תקוני דיקנא האחרונים הנמשכים מגלגלתא, שאינם מקבלים מגלגלתא רק ו״ק שהם תו״מ. כבר יצאו מראש א״א לגמרי, והן תלויות על הגרון (כנ״ל בספרא דצניעותא דף י״ד ד״ה פירוש)."],[4,"","ולפיכך אחר שנשלמו כל התקונים של השערות הנמשכות ממוחא סתימאה, שהם ח׳ תקוני דיקנא הראשונים, התחילו לצאת שערות דיקנא דבחינת גלגלתא, והתחילו לצאת מפאתי הראש דא״א, שערות חדשות מבחינת המלכות דמדת הדין. שהם מגלגלתא שבדיקנא, שהם לא קבלו עוד שום מיתוק. והם צריכים לעלות למקום בינה, כמו השערות שממו״ס בתקון ב׳, אמנם הן אינן יכולים ואינן צריכים לעלות ללחי העליונה, אלא שמספיק שיעלו ויתערבו עם שערות דיקנא דמו״ס שכבר נמתקו בבינה. וז״ש, \u0003תקונא תשיעאה מתערבין שערי עם אינון שערי דתליין,\u0004 דהיינו שנצמחות שערות חדשות, שהם ממלכות דמדת הדין, ומתערבות עם אלו השערות דיקנא התלויות עד הטבור, שכבר נמתקו בבינה. ומתמתקות גם הן ביניהן בבינה. וז״ש, \u0003ולא נפקין דא מן דא,\u0004 שהשערות החדשות אינן יוצאות משערות דיקנא התלויות. כי הן יוצאות מפאתי הראש. מבחינת גלגלתא, כנ״ל. וז״ש, \u0003אלין שערין דמתערבין עם אינון דתליין אקרון מצולות ים.\u0004 כלומר, השערות החדשות לפי עצמן אינן נקראות מצולות ים, אלא בעת שהן מתערבות עם שערות התלויות אז נקראות \u0003מצולות ים.\u0004 כי מחמת התערבותן בשערות התלויות שכבר נמתקו בבינה, נעלם מהן כל כח הדין שבהן, בסו״ה ותשליך \u0003במצולות ים\u0004 כל חטאתם במקום אשר לא יזכרו ולא יפקדו ולא יעלו על לב לעולם. כי תקון הב׳ שהעביר הדין משערות דמלכות ע״י עליתן ללחי העליונה לא היה לגמרי בשלמות, כי עוד נשארו השערות דמלכות מדיקנא דגלגלתא שבכאן, שעוד לא היו נמתקות, אבל כאן שגם השערות דמלכות מבחינת גלגלתא נמתקו, כבר כלה כל כח הדין שבמלכות שבשערות, וע״כ נאמר כאן, במקום אשר לא יזכרו ולא יפקדו ולא יעלו על לב לעולם. כי עתה נשלם מתוקה של המלכות מכל וכל."],[4,"","וז״ש, \u0003משום דנפקי ממותרי מוחא,\u0004 דהיינו כמ״ש לעיל, שמקור השערות הן מבחינות לבושי או״ח שהלבישו ג״ר דחכמה מקודם שנסתלקו מפנימיות הראש דא״א, אשר אחר שנסתלקו האורות דג״ר דחכמה נשארו הלבושים בבחינת פסולת \u0003ומותרי מוחא,\u0004 ויצאו לחוץ, ומטעם זה כלולה בהם המלכות דמדת הדין, כנ״ל. \u0003ומהאי אתרא,\u0004 דהיינו במקום ההוא שנתערבו, ששם בחינת בינה, כנ״ל, נעבר מהם כח הדין לגמרי, בסוד מצולות ים, וע״כ, \u0003רמיו כל מארי דתבעין חובי דבני נשא ומתכפיין,\u0004 שהושלך שם כל כחות המקטרגים הנמשכים ממלכות דמדת הדין, ומתבטלים שם. באפן שלא יעלו על לב לעולם."],[4,"","ובי״ג מדות שבתורה נקרא תקון זה, \u0003לאלפים,\u0004 שזה רומז שע״י תקון זה מתגלים ה \u0003אלף\u0004 עלמין דחתימין בעזקא רבא. להיותו מעביר כל כחות הדין מן המלכות."],[5,"תקונא עשיראה","וכו׳: התקון העשירי. השערות יורדות תחת הדיקנא, ומכסים על הגרון תחת הדיקנא. קום ר׳ יהודה, קם ר׳ יהודה. פתח ואמר, ובאו במערות צורים ובמחלות עפר מפני פחד ה׳ וגו׳. \u0003מפני פחד ה׳,\u0004 הרי נודע שמי שהוא מבחוץ, דהיינו ז״א, נקרא פחד ה׳. \u0003ומהדר גאונו,\u0004 אלו הם השערות שבגרון מתחת הדיקנא, ונקראות הדר גאונו. שני תקונים בהן, תקון העשירי, הנקרא \u0003תתן אמת ליעקב.\u0004 ותקון הי״א, שהוא שאין שערה יוצאה משערה כלומר שאין אחת ארוכה מחברתה אלא שהן שוות. והוא נקרא \u0003חסד לאברהם.\u0004"],[5,"","פירוש. כמו שנתבאר לעיל בתקון ד׳ שאחר המתוק במקום בינה בשפה עלאה ירדו ובאו למקומם בשפה תתאה בשבולת הזקן, (כנ״ל אות ק״ל) כך כאן אחר שהשערות דמלכות דמדת הדין קבלו המתוק מן התערבותם בשערות התלויות, בתקון הט׳, ירדו ובאו למקומם, שהוא הגרון, כמ״ש לעיל, שהשערות גלגלתא שבדיקנא להיותם בחינת ו״ק, מקומן בגרון (כנ״ל אות קנ״ב) וז״ש, \u0003תקונא עשיראה נחתין שערי תחות דיקנא וחפיין בגרונא תחות דיקנא,\u0004 שהשערות שנתערבו בשערות התלויות עד הטבור, יצאו וירדו משם למקומם שהוא הגרון."],[5,"","ויש כאן ב׳ בחינות, שהן בינה ומלכות, כי בכל מקום שהמלכות נכללת בבינה נעשה במלכות ב׳ בחינות, א׳ מבחינה הנכללת בה, וא׳ בחינתה עצמה הממותקת בבינה. ולפיכך כשירדו מתקון הט' ובאו למקומן בגרון נעשו מהן ב׳ תקונים, כמ״ש בספרא דצניעותא (אות יז), א׳ \u0003חפיין זעירין על גרונא דיקירו,\u0004 שהוא התקון העשירי הנ״ל שהן ממלכות, וע״כ הן \u0003זעירין,\u0004 כמו האותיות דמלכות שנקראות אתוון זעירין. וב׳, \u0003רברבין,\u0004 חפיין על גרונא, \u0003מתשערין בשיעורא שלים,\u0004 והן בחינות בינה שבהן, וע״כ הן \u0003רברבין,\u0004 כמו האותיות דבינה, שנקראות אתוון רברבן. וזה הוא תקון י״א."],[5,"","וז״ש כאן, \u0003ומהדר גאונו, אינון שערי דתחות דיקנא, ואתקרון הדר גאונו, תרי.\u0004 כי יש בהם ב׳ בחינות, מלכות ובינה, וע״כ נקראו ב׳ שמות, הדר, גאונו. שאחד מהם הוא מלכות, ואחד מהם בינה. והם ב׳ תקונים. \u0003תקונא עשיראה, תתן אמת ליעקב,\u0004 שהן השערות הקצרות דבחינת מלכות כנ״ל. ונקראות \u0003אמת,\u0004 בסו״ה אמת מארץ תצמח, שהיא המלכות, הנקראת ארץ. אמנם זה נעשה ע״י ז״א שנקרא יעקב. וע״כ נקרא התקון הזה בשם, \u0003תתן אמת ליעקב.\u0004 שעל ידו הוא מתגלה ובא בגמר התקון. \u0003וחד סר, דלא נפקי נימא מן נימא.\u0004 והיינו שערות אחרות גדולות, כמ״ש בספרא דצניעותא הנ״ל, \u0003רברבין, מתשערין בשיעורא שלים,\u0004 להיותן בחינת בינה דמלכות, וע״כ הם בשעור שלם שהן שוות ואינן ארוכות זו מזו."],[5,"","ובי״ג שבתורה, נקראו ב׳ תקונים אלו נושא עון, ופשע. שבחינת הבינה דמלכות נקראת \u0003נושא עון,\u0004 כי סליחת עון נוהג בבינה, שהיתה ישרה ונעשתה למעוות מחמת המלכות. ובחינת מלכות עצמה נקראת \u0003ופשע,\u0004 כלומר נושא פשע. שסולח הפשע שלה. כי הדינין שבמלכות נקראות \u0003פשע\u0004 (כנ״ל קכו/ב)."],[6,"תקונא דתריסר","וכו׳: תקון שנים עשר. השערות אינן תלויות על הפה. והפה נתפנה משערות מכל הצדדים, והשערות נאות סביב סביב הפה. כדי שלא תמצא טרחה, כמו שצריך להיות."],[6,"","פירוש. אחר שנתקנו היטב בחינת השערות בג׳ תקונים הראשונים בבחינת ו״ק, נמשכת עתה הארה מדעת דרדל״א, המאירה במוחא דאוירא ונמשכת עד הפה דא״א, כי בחינת הדעת מתפשטת ומאירה בו״ק אלו. ומכח ההארה הגדולה ההיא, נתפנה הפה משערות מכל הצדדים, וז״ש, \u0003דלא תליין שערי על פומא ופומא אתפני מכל סטרין.\u0004 וגם השערות עצמן קנו מתוך זה מדרגה חשובה, וז״ש, \u0003ויאין שערי סחור סחור ליה, בגין דלא אשתכח טרחותא,\u0004 שלא ניכר עליהם שום טרחה. דהיינו דין, כמ״ש לפנינו."],[7,"טרחותא במאי","וכו׳: שואל, טרחה זו, במה הוא המדובר. ומשיב, שפירושו דין, כי במקום דין נמצא טרחה. שואל, וכי שערות דיקנא דא״א הן טרחה או הן דין, והרי הכל נראה בו ברחמים. ומשיב, אלא, ע״כ נפנה הפה משערות, כדי שלא יטריח בנשיבת הרוח לז״א. פירוש. אע״פ שהשערות במקום א״א עצמו הן לבנות ואין בהם שום דין להיותם רק תוצאות הטובות הבאים ע״י דינים שלמטה. אבל כשהארותיהן נמשכות למטה, הן מעוררות דינים. ולפיכך נתפנה הפה משערות כדי שבביאת רוח הפה דא״א לז״א, לא יעורר שם דינים כלל."],[8,"דתאנא מהאי פומא","וכו׳: שלמדנו, מהפה הקדוש העליון הזה שהוא קדש קדשים, נושב רוח. מהו רוח. ומשיב, רוח שנתערה בו בא״א, הנמשך מדעת דרדל״א אל הפה שלו. ושמתלבש בו זעיר אנפין, דהיינו שהרוח נושב מפה דא״א לפה דז״א, וז״א מתלבש בו. ומרוח הזה מתלבשים כל אלו שלמטה. שהם מקבלים אותו דרך הפה דז״א. וכשרוח זה יוצא, מפה דא״א, הוא מתחלק לל״ז אלף צדדים שהוא כמספר \u0003הבל,\u0004 הרומז להבל היוצא מפה. וכל אחד מתפשט לבדו למקומו, וכל מי שראוי להתלבש בו, מתלבש. וע״כ לא נמצאות שערות על הפה הקדוש דא״א, משום שרוחו יוצא דרך שם, ודבר אחר אינו צריך להתערב בו ולקרב אליו."]],[]],[["וְדָא הוּא טְמִירוּתָא דְּכֹלָּא, דְּלָא אִתְדְּבַק לָא לְעֵילָּא וְלָא לְתַתָּא. וְהוּא סָתִים בִּסְתִּימָא דִּסְתִּימִין דְּלָא אִתְיְדַע. דָּא הוּא דְּלָא אִתְתָּקַּן, וְלָא הֲוָה בֵּיהּ תִּקּוּנָא. וּבְגִין כַּךְ, רוּחַ דְּנָפִיק לְבַר (ס\"א דנפיק מההוא דלבר), וּמִתְלַבְּשִׁין בֵּיהּ נְבִיאֵי מְהֵימְנֵי, אִתְקְרֵי פֶּה יְיָ. אֲבָל בְּהַאי עַתִּיקָא דְּעַתִּיקִין לָא אִתְפְּרַשׁ. וְלֵית מַאן דְּיֵדַע רוּחֵיהּ בַּר אִיהוּ. וּבְגִין כַּךְ שַׂעֲרוֹי שְׁקִילִין סוּחֲרָנֵא דְּפוּמָא, וּפוּמָא אִתְפְּנֵי מִכָּל סִטְרוֹי.","וּבְהַאי אִתְרְחִיצוּ אֲבְהֲתָנָא, לְאִתְלַבְּשָׁא בְּהַאי רוּחָא, דְּמִתְפָּשַׁט לְכַמָּה עִיבָרִין, בַּאֲתָר דְּכָל שַׂעְרֵי שְׁקִילִין בְּסוֹחֲרָנוֹי. (הדא הוא דכתיב, (מיכה ז׳:כ׳) אשר נשבעת לאבותינו). וְדָא הוּא תִּקּוּנָא קַדִּישָׁא עִלָּאָה דִּתְרֵיסָר. דְּמִכָּאן אִשְתֶּלְשָׁלוּ י\"ב תְּחוּמִין לְעֵילָּא. י\"ב תְּחוּמִין לְתַתָּא. י\"ב תְּחוּמִין לי\"ב שִׁבְטֵי אֲבָהָתָא. הֲדָא הוּא דִכְתִיב אֲשֶׁר נִשְׁבַּעְתָּ לַאֲבוֹתֵינוּ.","תִּקּוּנָא דִּתְלֵיסָר. תַּלְיָין שַׂעְרֵי דִּתְחוֹת דִּיקְנָא מִכָּאן וּמִכָּאן, בִּיקָרָא יָאָה, וּבִיקָרָא שַׁפִּירָא, וְחַפְּיָין עַד טַבּוּרָא וְלָא אִתְחַזְיָין מֵאַנְפֵּי תַּקְרוּבָא דְּבוּסְמָא, בַּר אִינּוּן תַּפּוּחִין שַׁפִּירָן חִוָּורִין.","אָמַר רִבִּי שִׁמְעוֹן, זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּאִשְׁתְּכַח בְּהַאי אִדָּרָא קַדִּישָׁא עִלָּאָה דַּאֲנָן בֵּיהּ. זַכָּאָה חוּלָקֵיהּ בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. דַּאֲנָן יַתְבִין בִּקְדוּשָׁא עִלָּאָה, אֶשָּׁא עִלָּאָה אַסְחַר לָן (ס\"א בין אשא עלאה דאסחר לן) וְהָא כָּל תִּקּוּנִין עִלָּאִין (לדיוקנא) דְּדִיקְנָא קַדִּישָׁא אִתְתָּקָנוּ, וְאִתְעַטְּרוּ וְאַסְחֲרוּ לְדוּכְתַיְיהוּ.","וְהַאי תִּקּוּנָא דִּתְלֵיסָר, הוּא תִּקּוּנָא יָאֶה, דְּבֵיהּ אֲחִידָן כֹּלָּא. כֻּלְּהוּ מִתְכַּסְּפִין לְמִזְקַף רֵישָׁא לָקֳבְלֵיהּ. מִנֵּיהּ תַּלְיָין כָּל אִינּוּן דְּבִזְעֵיר אַפִּין אֲחִידָן. מִנֵּיהּ תַּלְיָין עִלָּאִין וְתַתָּאִין, וְכָל גִּנְזִין עִלָּאִין וְתַתָּאִין גְּנִיזִין בֵּיהּ, וּבֵיהּ כְּלִילָן. וְאִיהוּ מַזָּלָא דְּמִתְזַלָא מִנֵּיהּ כֹּלָּא, דָּא הוּא תִּקּוּנָא שְׁלֵימָתָא, דְּאַשְׁלִים לְכָל תִּקּוּנִין, דָּא אַשְׁלִים לְכֹלָּא.","תָּאנָא, אִלֵּין תִּקּוּנִין אִקְרוּן יְמֵי קֶדֶם, יוֹמִין קַדְמָאִין דְּקַדְמָאֵי. וְאִינּוּן דְּאִשְׁתְּכָחוּ בִּזְעֵיר אַפִּין, אִקְרוּן (ישעיהו ס״ג:ט׳) יְמֵי עוֹלָם. וְתָאנָא, אִלֵּין יְמֵי קֶדֶם, כֻּלְּהוּ מִתְתָּקְנָן בְּתִקּוּנָא דְּדִיקְנָא דְּעַתִּיקָא דְּעַתִּיקִין, טְמִירָא דִּטְמִירִין (כליל בהו). וְהַאי דִּתְלֵיסָר כָּלִיל לְהוֹן, כְּמָה דְּאִתְּמַר. וְדָא יוֹמָא לָא אִתְכְּלִיל בַּהֲדַיְיהוּ, אֶלָּא הוּא כָּלִיל כֹּלָּא.","וּבְהַהוּא זִמְנָא דְּאִתְּעַר עַתִּיק יוֹמִין בְּתִקוּנִין דִּלְעֵילָּא, הַהוּא אִתְקְרֵי יוֹם אֶחָד, דְּבֵיהּ זַמִּין לְאוֹקִיר דִּיקְנֵיהּ, הֲדָא הוּא דִּכְתִּיב, (זכריה י״ד:ז׳) יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ. הוּא בִּלְחוֹדוֹי יַתִּיר מִכֹּלָּא. הוּא דְּכָלִיל כֹּלָּא, הוּא דְּאִתְקְרֵי בִּשְׁמָא יְדִיעָא.","דְּתָנֵינָן, בַּאֲתָר דְּאִית יוֹם אִית לַיְלָה דְּלֵית יוֹם בְּלָא לַיְלָה. וּמִשּׁוּם דְּהַהוּא זִמְנָא, זְמַן יְהֵא דִּיְקָרָא דְּדִיקְנָא, וְהוּא בִּלְחוֹדוֹי יִשְׁתְּכַּח. לָא אִתְקְרֵי לָא יוֹם וְלָא לַיְלָה. דְּלֵית יוֹם אִקְרֵי, אֶלָּא מִסִּטְרָא דִּילָן. וְלֵית לַיְלָה אִקְרֵי, אֶלָּא מִסִּטְרָא דִּילָן. וּמִשּׁוּם דְּהַאי תִּקּוּנָא כָּלִיל כֹּלָּא, לָא אִתְיְדַע וְלָא אִתְחֲזֵי מִנֵּיהּ, וּמִנֵּיהּ נָגִיד מִשְׁחָא דִּרְבוּתָא לִתְלֵיסַר עִיבָר מַבּוּעִין. לְכָל אִינּוּן דִּלְתַּתָּא, דִּנְהִרִין בְּהַהוּא מִשְׁחָא. (אתתקנו)","בִּתְלֵיסָר תִּקּוּנִין אִלֵּין אִתְתַּקְנָא דִּיקְנָא קַדִּישָׁא עִלָּאָה, וְאִלֵּין תִּקּוּנִין דִּבְהַאי דִּיקְנָא, מִתְתַּקְּנָן וְנַחְתָּן לְכַמָּה עִיבָר. וְלָא אִתְחָזוּן הֵיךְ מִתְפַּשְּׁטִין וְהֵיךְ נָפְקִין, מִכֹּלָּא אַסְתִּימוּ, וּמִכֹּלָּא אִתְטַמָרוּ. לֵית דְּיָדַע אֲתָר לְהַאי עַתִּיקָא, בִּפְשִׁיטוּתָא דִּלְהוֹן כֻּלְּהוֹן כְּלִילָן, כְּמָה דְּאִתְּמַר, אִתְיְדַע וְלָא אִתְיְדַע. טָמִיר וְלָא טָמִיר. עָלֵיהּ אִתְקְרֵי, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן. וּכְתִיב (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. וּכְתִיב (דניאל ז׳:ט׳) וְעַתִּיק יוֹמִין יְתִיב. בְּאַתְרֵיהּ יְתִיב וְלֵית יְדִיעַ לֵיהּ. יְתִיב וְלָא שְׁכִיחַ, וּכְתִיב (תהילים קל״ט:י״ד) אוֹדְךָ עַל כִּי נוֹרָאוֹת נִפְלֵיתִי וְגוֹ'.","אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּיא, כַּד אִתְפְּרִיס פְּרִיסָא דָּא, דְּאַתּוּן חָמָאן עֲלָנָא, אֲנָא חֲמֵינָא דְּנַחְתּוּ כֹּל תִּקּוּנִין בְּגַוָּוה, וּנְהִירוּ בְּאֲתָר דָּא. וְחַד פָּרוֹכְתָּא בּוּצִינָא דְּקוּדְשָׁא (ס\"א בוסיטא דקדושא) בְּרִיךְ הוּא, פְּרִיסָא בְּאַרְבַּע סַמְכִין, לְאַרְבַּע עִיבָר."],[[0,"ודא הוא טמירותא","וכו׳: וזה הרוח של הפה, הוא נסתר מהכל, שאינו מתדבק לא למעלה ולא למטה. והוא סתום בסתום מכל סתום שלא נודע, זה הוא שלא נתתקן ולא היה בו תקון. ומשום זה, רוח היוצא מאותו שמבחוץ, שהוא ז״א, ונביאי אמת נתלבשו בו, נקרא פה ה'. אבל בעתיקא דעתיקין זה, שהוא א\"א, אין מפורש בו פה. כי אין מי שישיג רוחו חוץ ממנו. ומשום זה שערות שלו שוים מסביב הפה, והפה נתפנה מכל צדדיו."],[0,"","פירוש. כי רוח זה שבפה דא״א. כבר נתבאר, שהוא נמשך מדעת דרישא דלא אתיידע (כנ״ל אות קנ״ד) ומאיר במוחא דאוירא, ונמשך אל הפה דא״א. וז״ש, \u0003דלא אתדבק,\u0004 שאינו מושג \u0003לא לעילא,\u0004 במוחא דאוירא, \u0003ולא לתתא,\u0004 בפה דא״א. \u0003והוא סתים בסתימא דסתימין דלא אתידע,\u0004 דהיינו שסתום במקורו בדעת של הראש דלא אתיידע. \u0003דא הוא דלא אתתקן, ולא הוה ביה תקונא,\u0004 דהיינו שלא נתתקן שיהיה בו איזה מושג, ואין בו תקון כזה. אלא בז״א יש בו השגה ברוח הפה שלו, \u0003ומתלבשין ביה נביאי מהימנא, אתקרי פה ה׳.\u0004 דהיינו שנעשה בו תקון להתפשט לתחתונים הנקראים פה ה׳. \u0003אבל בהאי עתיקא דעתיקין לא אתפרש\u0004 שאינו מפורש בו השם פה. שאין בו תקון הזה, \u0003ולית מאן דידע רוחיה בר איהו.\u0004"],[1,"ובהאי אתרחיצו אבהתנא","וכו׳: ובזה בטחו האבות להתלבש ברוח הזה המתפשט לכמה צדדים במקום שכל השערות שוות מסביב לו, שע״כ הרוח נושב משם לז״א בלי טרחה (כנ״ל אות קנ״ד) שכתוב, \u0003אשר נשבעת לאבותינו,\u0004 וזה הוא תקין י״ב הקדוש העליון. שמכאן נשתלשלו י״ב תחומין למעלה, בחג״ת דז״א, י״ב תחומין למטה, במלכות, י״ב תחומין לי״ב שבטי האבות. ז״ש, אשר נשבעת לאבותינו."],[1,"","פירוש. כי י״ב תקונא דיקנא שנתבארו עד כאן הם עיקרי התקונים ותקון י״ג המובא לפנינו, אינו אלא בחינת מלכות המקבלת אותם. ואומר, שמהם נמשך י״ב גבולי אלכסון שבז״א, ושבמלכות, ושל י״ב שבטי יה הנמשכים מי״ב שבמלכות. כי מספר י״ב בכללות תקוני דיקנא, יורה על ג׳ קוין שבכל אחד חו״ג תו״מ. שהם שורש כל מספר י״ב האמור בז״א, ובמלכות, ובבי״ע. ובי״ג שבתורה שהם בז״א, נקרא תקון זה \u0003וחטאה,\u0004 להורות, שיש בו טרחה (כנ״ל אות קנ״ה)."],[2,"תקונא דתליסר","וכו׳: תקון י״ג. השערות תלויות מתחת הדיקנא מכאן ומכאן ביקר נאה, וביקר יפה, ומכסים עד הטבור, דהיינו כל שטח התחתון של הדיקנא הבלתי נראה לעין, ולא נראה מן הפנים של מנחת הבושם, רק אלו ב'. תפוחין היפים והלבנים. שה״ס תקון הז' הנ״ל."],[2,"","כבר נתבאר שתקון י״ג ה״ס מלכות המקבלת מי״ב תקיני דיקנא, ואין בה פעולה מיוחדת כמו בכל תקון די״ב תקוני דיקנא. וע״כ היא מרומזת בשטח התחתון של הדיקנא המקבל מכל שערות דיקנא. ונודע שכל מדרגה נערכת לפי שיעור הקומה העליונה שבה, אשר בתקוני דיקנא הוא תקון הז׳ שה״ס הארת פנים דב׳ תפוחין קדישין, כמ״ש שם, בסו״ה באור פני מלך חיים. וז״ש, \u0003ולא אתחזיין מאנפי תקרובתא דבוסמא,\u0004 דהיינו מכללות הדיקנא שנקראת כן על שם הארת החכמה הנמשכת ממנה, כמ״ש לעיל בתקון ו׳ ובתקון ז', \u0003בר אינון תפוחין שפירן חוורין,\u0004 כי הם שיעור קומה היותר גבוהה מכל תקוני דיקנא. והתקון השמיני, הן השערות הנמשכות אחר גילוי האור הזה, כמ״ש שם, וע״כ הוא בחינת המשפיע אותם, וע״כ נקרא \u0003מזל עליון,\u0004 שממנו נוזל השפע בבחינת זכר של הדיקנא. וגם ד׳ תקונים תחתונים נכללים במזל העליון, להיותו שיעור קומה הגבוה מהם. ותקון י״ג נקרא \u0003מזל תחתון,\u0004 להיותו בחינת מלכות המקבלת י\"ב תקוני דיקנא ומשפעת אותם לתחתונים."],[3,"א״ר שמעון","וכו׳: אר״ש, אשרי חלקו של מי שנמצא באדרא הקדוש הזה העליון שאנו בו, אשרי חלקו בעולם הזה ובעולם הבא. כי אנו יושבים בקדושה עליונה, ואש העליונה מסבבת אותנו. והנה נתתקנו כל תקונים העליונים של דיקנא הקדוש, ונתעטרו וחזרו למקומם. פירוש כל תקון ותקון שעסקו בו, המשיכו אותו ממקומו אליהם, ועטרו אותו בביאור שלהם, ואח״כ חזר התקון למקומו למעלה."],[4,"והאי תקונא דתליסר","וכו׳: ותקון זה הי״ג, הוא תקון נאה, שבו נכללים כל התקונים. וכולם משתוקקים לזקוף ראשם כנגדם, דהיינו לקבל מהם ג״ר הנקראות ראש. ממנו, תלוים כל אלו התקונים האחוזים בזעיר אנפין. דהיינו שתקוניו מקובלים מדיקנא זו, ממנו תלוים העליונים והתחתונים, וכל האוצרות העליונים והתחתונים גנוזים בו, ובו כלולים. והוא \u0003מזל\u0004 שהכל מזדלזלים ממנו (כנ״ל אות קנ״א) זה הוא תקון השלם המשלים לכל התקונים. זה משלים הכל. כי ה״ס מלכות המשלמת לכל הספירות."],[5,"תאנא אלין תקונין","וכו׳: למדנו, תקונים אלו נקראים ימי קדם, ימים ראשונים של ראשונים. ואלו תקונים שנמצאים בז״א, נקראים ימי עולם. ולמדנו, אלו ימי קדם מתתקנים כולם בתקון הדיקנא של עתיק העתיקים הנסתר שבנסתרות, ותקון זה הי״ג כולל אותם, כמו שאמרנו, ויום הזה שהוא תקון י״ג, אינו נכלל עמהם אלא כולל אותם."],[5,"","פירוש. שאין כאן י״ג פעולות, שתקון י״ג יהיה פעולה נוספת על י״ב הפעולות, אלא שתקון י״ג אינו אלא כולל כל י״ב תקונים ומקבל מהם, ובו עצמו אין שום פעולה מיוחדת."],[6,"ובההוא זמנא דאתער","וכו׳: ובזמן ההוא שיתעורר עתיק יומין בתקונים של מעלה דדיקנא, נקרא זה, \u0003יום אחד,\u0004 שבו עתיד להוקיר הדיקנא. ז״ש יום אחד הוא יודע לה׳. שיום ההוא לבדו חשוב יותר מהכל, כי הוא כולל כולם, הוא הנקרא בשם ידוע. דהיינו יום אחד."],[7,"דתנינן באתר דאית","וכו׳: שלמדנו, במקום שיש יום יש לילה, כי אין יום בלי לילה, ומשום שהזמן ההוא יהיה זמן של יקר הדיקנא, והוא לבדו ימצא, אינו נקרא לא יום ולא לילה. כי אין נקרא יום אלא מצד שלנו, ואין נקרא לילה אלא מצד שלנו. ומשום שתקון זה כולל הכל, לא נודע ולא נראה ממנו לפני הזמן ההוא שנקרא יום אחד, אלא שממנו נוזל שמן המשחה לי״ג בחינות מבועים בשביל כל אלו שלמטה המאירים בשמן ההוא."],[8,"בתליסר תקונין אלין","וכו׳: בי״ג תקונים אלו מתתקן דיקנא הקדוש העליון, ואלו תקונים שבדיקנא הזה, מתתקנים ויורדים להאיר לכמה צדדים, ואינם נראים איך מתפשטים ואיך יוצאים, כי המה סתומים מכל, ונסתרים מכל, אין מי שידע מקום לעתיק הזה. בהתפשטות התקונים הכל כלולים, כמו שאמרנו. הוא נודע ואינו נודע, נסתר ואינו נסתר. כלומר לפי עצמו הוא בלתי נודע ונסתר ובתקונים שלו המתפשטים הוא נודע. עליו כתוב, אני ה׳ הוא שמי וכבודי לאחר לא אתן. וכתוב הוא עשנו ולא אנחנו. וכתוב, ועתיק יומין יתיב. היינו שיושב במקומו ואין מי שיודע אותו. יושב ואינו נמצא. וכתוב, אודך על כי נוראות נפליתי וגו׳."],[9,"אמר ר״ש לחברייא","וכו׳: אר״ש לחברים. כשנפרס פרסא זו, שאתם רואים עלינו, אני רואה שכל התקונים ירדו בתוכה, ומאירים במקום זה. ומפרש. ופרכת אחת, דהיינו פרסא, שהיא נרו של הקב״ה נפרש בארבעה עמודים לארבע צדדים."],[9,"","פירוש. \u0003פרסא\u0004 ה״ס גבול החדש שנעשה בסבת עלית המלכות דכל מדרגה לבינה דכל מדרגה. שמסבה זו נסתיימת המדרגה בחצי בינה, ושם נפרש פרסא, וחצי בינה ותו״מ יצאו מכל מדרגה למדרגה שמתחתיה להיותם למטה מפרסא של המדרגה. ופרסא זו נתקנה עוד בעולם התהו, אלא מחמת שלא היו תקון קוין בו״ק נתבטלה הפרסא ויצאו ז״ס דעולם התהו בקו אחד שה״ס חד סמכא, וע״כ נשברו ומתו. ואח״כ בעולם התקון נעשה תקון קוין בו\"ק באופן שלא תתבטל הפרסא אפילו בעת גדלות, ואז נתקשרו כל התקונים בפרסא הזו. כמ״ש לעיל (אות י״ב) ובתחילת האדרא (באות א') אר״ש לחברייא עד אימת ניתוב בקיומא \u0003דחד סמכא,\u0004 דהיינו בעולם התהו, ואספם לאדרא זו והכניסם בעולם התקון, דהיינו שנתקן תקון קוין בו״ק, באפן שלא תתבטל הפרסא לעולם, ואז נתקשרו כל התקונים בפרסא הזו."],[9,"","וז״ש, \u0003כד אתפריס פריסא דא דאתון חמאן עלנא,\u0004 דהיינו הפרסא דעולם התקון, \u0003אנא חמינא דנחתו כל תקונין בגווה,\u0004 שכל התקונים ירדו ונקשרו בפרסא. ומפרש ענין הפרסא בכללות, דהיינו מה שנפעלת על ידה בכל מדרגה ומדרגה. ואומר, \u0003וחד פרוכתא בוצינא דקב״ה,\u0004 דהיינו הפרסא שהיא נרו של המאציל. \u0003פריסא בארבע סמכין לארבע עיבר,\u0004 כי בכל מדרגה יש כח״ב תו״מ. שבכל אחת מהן ע״ס. וכתר אינו מן המנין, וע״כ יש ד׳ עמודים חו״ב תו״מ, שבכל אחד מהם עשר ספירות. והפרסא ירדה בתוכם, דהיינו במקום בינה שבכל סמכא, וסיימה שם מדרגת הסמכא, ונשארו בה כו״ח, ובינה ותו״מ דכל סמכא, יצאה מן המדרגה. וז״ש, \u0003בארבע סמכין לארבע עיבר,\u0004 שהסמכין נמצאים בארבע רוחות, שחו״ב הם דרום צפון, ות״ת ומלכות, הם מזרח ומערב."]],[]],[["סַמְכָא חַד הוּא יָתִיב מִתַּתָּא לְעֵילָּא, וְחַד מַגְרוֹפְיָא בִּידֵיהּ. וּבְמַגְרוֹפְיָא אַרְבַּע מַפְתְּחִי שְּׁנִינָן (ס\"א שניין) מִכָּל סִטְרוֹי. וּמִתְאַחֲדָן פַּרְסָא, וְנַחְתִּין לָהּ מֵעֵילָּא לְתַתָּא. וְכֵן לְסַמְכָא תִּנְיָינָא, וּתְלִיתָאָה וּרְבִיעָאָה. וּבֵין סַמְכָא לְסַמְכָא, אֲחִידָן תִּמְנֵיסָר רַגְלֵי דְּסַמְכִי וּמִתְנַהֲרִין בְּבוּצִינָא דִּגְלִיפָא (בבוסיטא דגליפין) בְּהַהוּא פְּרִיסָא. וְכֵן לְד' עִיבָר.","וַחֲמֵינָא אִלֵּין תִּקּוּנִין דִּנְהִרִין עָלָהּ, וַהֲווּ מְחַכָּאן מִלֵּי דְּפוּמָנָא, לְאִתְעַטְּרָא וּלְאִסְתַּלְּקָא כָּל חַד בְּאַתְרֵיהּ. וְכַד הֲווֹ מִתְתַּקְּנָן מִפּוּמָנָא, כָּל חַד וְחַד סָלִיק וְאִתְעַטָּר וְאִתְתָּקַּן בְּהַהוּא תִּקּוּנָא דְּאִתְתְּקַן הָכָא, מִכָּל (ס\"א בהבל דכל) פּוּמָא דְּחַד מִינָן. וּבְשַׁעֲתָא דְּחַד מִינָן פָּתַח פּוּמָא, לְתַקְּנָא בְּהַהוּא תִּקּוּנָא, הַהוּא תִּקּוּנָא הֲוָה יְתִיב וּמְחַכֶּה לְמִלָּה דְּנָפִיק מִפּוּמֵיכוֹן, וּכְדֵין סַלְּקָא בְּדוּכְתֵּיהּ וְאִתְעַטָּר.","וְכָל סַמְכִין מִכָּאן וּמִכָּאן, חַדָּאן עַל דְּשַׁמְעִין מַה דְּלָא יָדְעוּ, וְצַיְיתִין לְקַלֵּיכוֹן. כַּמָה רְתִיכִין קַיְימִין הָכָא בְּגִינֵיכוֹן. זַכָּאִין אַתּוּן לְעָלְמָא דְּאָתֵי, דְּכֻלְּהוּ מִלֵּי דְּנַפְקֵי מִפּוּמֵיכוֹן, כֻּלְּהוּ מִלִּין קַדִּישִׁין. מִלִּין כַּשְׁרָן דְּלָא אַסְטָאן לִימִינָא וְלִשְׂמָאלָא.","קוּדְשָׁא בְּרִיךְ הוּא חַדֵּי לְמִשְׁמַע, וְצַיִית לְהָנֵי מִלֵּי, עַד דְּהוּא אַגְמָר (ס\"א אגזר) דִּינָא, דִּי לְעָלְמָא דְּאָתֵי תֵּימְרוּן זִמְנָא אַחֲרָא כָּל הָנֵי מִלֵּי קַדִּישִׁין. עָלַיְיכוּ כְּתִיב, (שיר השירים ז׳:י׳) וְחִכֵּךְ כְּיֵין הַטּוֹב וְגוֹ', דּוֹבֵב שִׂפְתֵי יְשֵׁנִים. מַאי דּוֹבֵב שְׂפָתַי יְשֵׁנִים. דְּאֲפִילּוּ לְעָלְמָא דְּאָתֵי מְרַחְשָׁן שִׂפְוָותַיְכוּ אוֹרַיְיתָא קַמֵּיהּ.","הַשְׁתָּא אִתְתָּקָנוּ וְאִתְכָּוְונוּ דַּעְתָּא, לְמִתְקָן תִּקּוּנוֹי דִּזְעֵיר אַפִּין, הֵיךְ יִתְתָּקַּן, וְהֵיךְ יִתְלַבָּשׁ בְּתִקּוּנוֹי מִתִקּוּנֵי עַתִּיק יוֹמִין, קַדִּישָׁא דְּקַדִּישִין, טְמִירָא דִּטְמִירִין, טְמִירָא מִכֹּלָּא. דְּהַשְׁתָּא חוֹבָתָא (חכמתא) עָלַיְיכוּ, לְמִגְזַר דִּינָא קוּשְטָאָה יָאֶה וְשַׁפִּירָא וּלְאַתְקְנָא כָּל תִּקּוּנִין עַל בּוּרְיֵיהּ.","תִּקּוּנֵי דִּזְעֵיר אַפִּין, מִתִּקוּנֵי דַּאֲרִיךְ אַפִּין אִתְתָּקָּנוּ. וְאִתְפָּשָׁטוּ תִּקּוּנוֹי מִכָּאן וּמִכָּאן, כְּחֵיזוּ בַּר נָשׁ, לְמִשְלְטָא (ס\"א ומשלחא) בֵּיהּ רוּחָא דִּטְמִירָא דְּכָל טְמִירִין. בְּגִין לְמֵיתַב עַל כּוּרְסְיָּיא, דִּכְתִּיב, (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. כְּמַרְאֵה אָדָם: דְּכָלִיל כָּל דִּיוּקְנִין. כְּמַרְאֵה אָדָם: דְּכָלִיל כָּל שְׁמָהָן. כְּמַרְאֵה אָדָם: דְּבֵיהּ סְתִימִין כָּל עָלְמִין עִלָּאִין וְתַתָּאִין. כְּמַרְאֵה אָדָם: דְּכָלִיל כָּל רָזִין דְּאִתְאַמָּרוּ וְאִתָּתְקָנוּ עַד דְּלָא אִבְרֵי עָלְמָא, וְאַף עַל גַּב דְּלָא אִתְקָיָּימוּ.","תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, עַתִּיקָא דְּעַתִּיקִין עַד לָא זַמִּין תִּקּוּנוֹי, בָּאנֵי מַלְכִין, כָּנֵס מַלְכִין, (נ\"א (קכ\"ח) גליף מלכין) וּמְשַׁעֵר מַלְכִין, וְלָא הֲווֹ מִתְקַיְּימֵּי, עַד דְּדָחֵי (ס\"א דאנח) לוֹן, וְאַצְנַע לוֹן לְבָתַר זִמְנָא, הֲדָא הוּא דִכְתִיב, (בראשית ל״ו:ל״א) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם. בְּאֶרֶץ אֱדוֹם, בְּאֲתָר דְּכָל דִּינִין מִתְקַיְּימִין תַּמָּן, וְכֻלְּהוּ לָא אִתְקָיָּימוּ.","עַד דְּרֵישָׁא חִוָּורָא עַתִּיקָא דְּעַתִּיקִין אִתְתָּקַּן. כַּד אִתְתָּקַּן, תַּקִּין כָּל תִּקּוּנִין דִּלְתַתָּא, תַּקִּין כָּל תִּקּוּנִין דְּעִלָּאִין וְתַתָּאִין. מִכָּאן אוֹלִיפְנָא, כָּל רֵישָׁא דְּעַמָּא, דְּלָא אִתְתָּקַּן הוּא בְּקַדְמִיתָא, לֵית עַמָּא מִתְתַּקְנָא. וְאִי אִיהוּ מִתְתַּקָּן, כֻּלְּהוּ מִתְתַּקְּנָן. וְאִי אִיהוּ לָא מִתְתַּקֵּן בְּקַדְמִיתָא, לָא יַכְלִין עַמָּא לְאִתְתַּקְּנָא.","מְנָלָן. מֵעַתִּיק יוֹמִין. דְּעַד לָא אִתְתָּקַּן הוּא בְּתִקּוּנוֹי, לָא אִתְתְּקָּנוּ כָּל אִינּוּן דְּבָעוּ לְאִתְתַּקְּנָא, וְכֻלְּהוּ עָלְמִין אִתְחֲרָבוּ. הֲדָא הוּא דִכְתִיב, (בראשית ל״ו:ל״ב) וַיִּמְלוֹךְ בֶּאֱדוֹם בֶּלַע בֶּן בְּעוֹר. וַיִּמְלוֹךְ בֶּאֱדוֹם, רָזָא חֲדָא (ס\"א יקירא) הוּא. אֲתָר דְּכָל דִּינִין מִתְקַטְּרִין תַּמָּן, וְתַּלְיָין, מִתַּמָּן.","בֶּלַע בֶּן בְּעוֹר, תָּאנָא הוּא גִּזְרַת דִּינָא, תַּקִּיפָא דְתַקִּיפִין, דִּבְגִינֵיהּ מִתְקַטְּרָן אֶלֶף אַלְפִין מָארֵי דִּיבָבָא וִילָלָה. (בראשית ל״ו:ל״ב) וְשֵׁם עִירוֹ דִּנְהָבָה. מַאי דִּנְהָבָה. כְּלוֹמַר דִּין הָבָה. כְּמָה דְאַתְּ אָמֵר, (משלי כ) לַעֲלוּקָה שְׁתֵּי בָּנוֹת הַב הַב.","כֵּיוָן דְּסָלִיק לְאִתְיַשְּׁבָא, בֵּיהּ לָא קָאִים, וְלָא הֲוָה יָכִיל לְמֵיקָם, וְכֻלְּהוּ עָלְמִין אִתְחֲרָבוּ. מַאי טַעֲמָא. מִשּׁוּם דְּאָדָם לָא אִתְתָּקַּן. דְּתִקּוּנָא דְּאָדָם בְּדִיוּקְנֵיהּ, כָּלִיל כֹּלָּא, וְיָכִיל כֹּלָּא לְאִתְיַשְּׁבָא בֵּיהּ."],[[0,"סמכא חד הוא","וכו׳: עמוד אחד הוא יושב ממטה למעלה, ומגרופיא אחד בידו, שהוא כלי לנקות בו פסולת, ובמגרופיא ארבעה מפתחות משונים זה מזה, שהם מכל צדדיו. ונאחזים בפרסא ומורידים אותה ממעלה למטה וכן לעמוד השני השלישי והרביעי. ובין עמוד לעמוד, אחוזים י״ח רגלין של הסמכין, ומוארים בנר החקוק בפרסא ההוא. וכן לד׳ צדדים."],[0,"","פירוש. כי נתבאר בסמוך שהפרסא נפרס בתוך ד׳ עמודים דכל מדרגה, דהיינו שהמלכות עלתה לבינה שבכל עמוד, וקבלה הבינה הדינים דמלכות ונסתיימה המדרגה במקום בינה. ולא נשאר בכל עמוד אלא כתר וחכמה דכלים וו״ק דאורות. ונודע שו״ק אינם מאירים אלא ממטה למעלה. וז״ש, \u0003סמכא חד הוא יתיב מתתא לעילא,\u0004 שמאיר רק ממטה למעלה, משום המלכות שעלתה למקום בינה, וקבלה הבינה דינים דמלכות וע״כ הופרס הפרסא שה״ס דסיום של המלכות במקום בינה. ואין שם אלא ו״ק דאורות המאירים ממטה למעלה. וכן הוא בכל ד׳ סמכין, כמו שמסיים. ולפיכך, צריכים למגרופיא, לנקות הדינים ממקום בינה, ולהוריד הפרסא מבינה למלכות, באפן שבינה ותו״מ יעלו למעלה מפרסא, ויוחזרו ג״ר דאורות לכל עמוד. אמנם מגרופיא זו כלול מד׳ בחינות, שה״ס ג׳ קוין, ומלכות המקבלתם, ומכונים ד׳ מפתחות, שהם פותחים הארת הג״ר שיאירו בכל עמוד."],[0,"","וז״ש, \u0003וחד מגרופיא בידיה,\u0004 בידיה פירוש בכחו, שבכחו של כל עמוד יש מגרופיא אחד להוריד הדינים ממנו ולהחזיר הבינה ותו״מ דכלים, והג״ר דאורות. \u0003ובמגרופיא ארבע מפתחי,\u0004 דהיינו ג׳ קוין ומלכות המקבלתם, שעל ידיהם נפתחים הג״ר. \u0003שניין מכל סטרוי,\u0004 כלומר שכל מפתח משונה מחברו. \u0003ומתאחדן פרסא ונחתין לה מעילא לתתא,\u0004 שהם נאחזים בפרסא ומורידים אותה ממקום בינה למטה, כלומר, שלא תסיימה במקום בינה, אלא מתחת המלכות, ואז עולים בינה ותו״מ ומתחברים עם כו״ח של כל עמוד, ונשלמו ע״ס דכלים, ונמשכים נרנח״י דאורות."],[0,"","וז״ש \u0003ובין סמכא לסמכא אחידן תמניסר רגלי דסמכי.\u0004 כי אחר שירדה הפרסה ע״י המפתחות מבינה למטה, למלכות, עלו שם נה״י דכלים, שה״ס בינה ותו״מ הנ״ל, הממשיכים ו׳ קצוות, חג״ת נה״י דג״ר, ונבחן שעלו נה״י לכל קצה וקצה מן ו״ק, שהן ו׳ פעמים ג׳, והם י״ח בחינות נה״י. ונמצא שהמוחין הנמשכים בין עמוד לעמוד, \u0003הם י״ח רגלין,\u0004 כי נה״י נקראים \u0003רגלין.\u0004 וז״ש \u0003וכן לד׳ עיבר,\u0004 כי אלו ח״י בחינות רגלין, ממשיכים המוחין לד׳ רוחות חו״ב תו״מ, וע״כ הם ע״ב בחינות רגלין."],[1,"וחמינא אלין תקונין,","וכו׳: וראיתי אלו התקונים מאירים עליה, והדברים שבפינו, דהיינו ביאורי התקונים שאמרנו, היו מחכים להתעטר ולעלות כל אחד במקומו. וכשהתקונים היו מתתקנים מפינו, כלומר כשהיו מתבארים, כי כפי שביארו כך נתקנו למעלה, כל אחד ואחד עלה ונתעטר ונתתקן בתקון ההוא שנתתקן כאן, מפה כל אחד ממנו. ובשעה שכל אחד ממנו פתח פה, לתקן באיזה תקון, אותו התקון היה יושב ומחכה לדבר שיצא מפיכם, שאח״כ עלה למקומו ונתעטר."],[2,"וכל סמכין מכאן","וכו׳: וכל הסמכין, דהיינו כל המלאכים הסומכים את הכסא שהוא המלכות, מכאן ומכאן, היו שמחים, כי שמעו מה שלא ידעו, והיו מקשיבים לקולכם. כמה מרכבות. דהיינו מלאכים, שהמלכות רוכבת עליהם, היו נמצאים כאן בשבילכם, אשריכם לעולם הבא, שכל הדברים שיצאו מפיכם כולם הם דברים קדושים, דברים ישרים שאינם סרים לימין ולשמאל, אלא שהם מקו האמצעי הכולל אותם."],[3,"קב״ה חדי למשמע","וכו׳: הקב״ה שמח לשמוע ולהקשיב לדברים האלו עד שהוא גומר הדין, דהיינו עד גמר התקון, כי לעולם הבא תאמרו פעם שנית כל אלו הדברים הקדושים. עליכם כתוב, וחכך כיין הטוב וגו', דובב שפתי ישנים. מהו דובב שפתי ישנים, היינו שאפילו לעולם הבא, שפתותיכם תהיינה דובבות לפניו תורה."],[4,"השתא אתתקנו","וכו׳: עתה התתקנו וכוונו דעת לתקן תקוניו של ז״א. איך הוא יתתקן ואיך יתלבש בתקוניו מתקוניו של עתיק יומין, קדוש הקדושים, נסתר מכל נסתר, הנסתר מכל. כי עתה חובתכם לגזור דין אמת נאה ויפה, ולתקן כל התקונים על יסודם."],[5,"תקוני דזעיר אפין","וכו׳: תקוניו של ז״א נתתקנו מתקוניו של אריך אנפין, ונתפשטו תקוניו מכאן ומכאן דהיינו מימין ומשמאל ומאמצע, כמראה אדם, כי אדם יורה, על קו האמצעי שכלולים בו ג׳ קוין, בשביל שישלוט בו הרוח של הנסתר מכל נסתר, שהוא א״א, כדי לשבת על הכסא, שהוא מלכות, שכתוב, ועל דמות הכסא דמות כמראה אדם עליו מלמעלה. \u0003כמראה אדם,\u0004 היינו כפני אדם הכולל כל הצורות, שג׳ פנים אריה שור נשר, כלולים בפני אדם, וזהו מצד המלכות שבו. כי אדם כולל ז״א ומלכות. עוד \u0003כמראה אדם,\u0004 הכולל כל השמות, כי ז״א נקרא הויה, הכולל כל השמות. עוד \u0003כמראה אדם,\u0004 שבו סתומים כל העולמות העליונים והתחתונים. כי ה״ס קו האמצעי הסותם כל העולמות מבחינת ג״ר דחכמה, מטעם שממעט קו השמאל, שלא יאיר אלא ממטה למעלה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) עוד \u0003כמראה אדם,\u0004 שהוא כולל הסודות שנאמרו ונתתקנו מטרם שנברא העולם, דהיינו בז׳ מלכים שבעולם התהו, ואע״פ שנשברו ולא נתקיימו."],[6,"תאנא בצניעותא דספרא","וכו׳: למדנו בספרא דצניעותא, עתיקא דעתיקין, שהוא ס״ג דא״ק, בנה מלכים, בעולם הנקודים, דהיינו שבנה אותם מבחינת צמצום ב׳ שה״ס הפרסא. חקק מלכים, דהיינו בחינת הקטנות ומשער מלכין, היינו שיעורי קומת הגדלות שלהם. ולא היו מתקיימים. עד שדחה אותם והצניע אותם לזמן אחר. ז״ש, ואלה המלכים אשר מלכו בארץ אדום. \u0003בארץ אדום\u0004 פירושו במקום שכל הדינים נמצאים שם, דהיינו בעולם הנקודים. וכולם לא נתקיימו, כי כתוב בכל אחד וימלוך וימת. (וענין זה מתבאר באורך בתלמוד עשר ספירות בחלק ז׳)."],[7,"עד דרישא חוורא","וכו׳: עד שראש הלבן, שהוא גלגלתא דא״א, עתיק העתיקים, נתתקן. וכשנתתקן תקן כל התקונים שלמטה, תקן כל התקונים של העליונים והתחתונים. מכאן למדנו, כל מנהיג העם שהוא לא נתתקן תחילה, אין העם מתתקנים, ואם הוא מתתקן כולם מתתקנים. ואם הוא אינו מתקן עצמו תחילה, אין העם יכולים להתתקן."],[8,"מנלן מעתיק יומין","וכו׳: מאין לנו זה. מעתיק יומין, שכל עוד שהוא לא נתתקן בתקוניו, לא נתתקנו כל אלו שצריכים להתתקן, וכל העולמות נחרבו. דהיינו ז׳ מלכים דנקודים. ז״ש וימלוך באדום בלע בן בעור. \u0003וימלוך באדום,\u0004 הוא סוד יקר, הוא מקום, שכל הדינים נקשרים שם, ותלוים משם."],[8,"","פירוש. שמקור כל התקונים הוא התקון שלא תתבטל עוד הפרסא כמו בז׳ מלכים דעולם הנקודים. (כנ״ל אות י״ב). שה״ס תקון הקוין בז״ת, ואחר שעתיק יומין נתתקן בתקון זה, נתתקנו אחריו כל הפרצופין ונתקיימו. וכל עוד שהוא לא נתתקן בזה לא יכלו שאר הפרצופין להתתקן."],[9,"בלע בן בעור","וכו׳: בלע בן בעור. למדנו, שהוא גזרת דין הקשה שבקשים, שעל ידו מתקשרים אלף אלפים בעלי יבבה ויללה ושם עירו דנהבה. מהו דנהבה, כלומר דין הבה. כש״א, לעלוקה שתי בנות הב הב."],[9,"","פירוש. המלך הראשון שמז' מלכין דנקודים שנשברו, הוא מלך הדעת, שהוא בחינת מלמעלה למטה של קומת הסתכלות עיינין דאו\"א דנקודים, שנמשכה על בחי״ד, (כמ״ש בתלמוד עשר הספירות חלק ז' דף תקי\"ז ד״ה הדעת ע״ש.) ובחי״ד ה״ס מלכות דמדת הדין, ודין הקשה שבקשים. וע״י שבירת מלך הזה יצאו בעלי יבבה ויללה, וז״ש \u0003דבגיניה מתקטרן אלף אלפין מארי דיבבה ויללה.\u0004 כי הארת הדעת היא בסוד הויה דמילוי \u0003אלפין,\u0004 ועל ידה נמשכה החכמה המכונה \u0003אלפים\u0004 בסוד ואאלפך חכמה. וע״כ כשנשברה המדרגה הגדולה הזו, יצאו כנגדה מארי יבבה ויללה המייבבים ומיללים אחריה בשיעור אלף אלפים כפי שיעור הארתה."],[10,"כיון דסליק לאתישבא","וכו׳: כיון שמלך הדעת עלה להתישב במדרגתו לא עמד בה, ולא היה יכול לעמוד בה, מפני שנמשכה מלמעלה למטה ועברה לבי״ע דפרודא (כמ״ש בחלק ז') וכל העולמות נחרבו. מהו הטעם. הוא משום שאדם לא נתתקן, דהיינו תקון קוין בז״ת, וזכר ונקבה, כי תקון אדם בצורתו כלול הכל, והכל יכול להתישב בו ולהתקיים."]],[]],[["וּבְגִין דְּתִקּוּנָא דָּא דְּאָדָם, לָא אִשְׁתְּכַח. לָא יָכִילוּ לְמֵיקָם וּלְאִתְיַשְּׁבָא, וְאִתְבְּטָלוּ. וְאִתְבְּטָלוּ סַלְּקָא דַּעְתָּךְ וְהָא כֻּלְּהוּ בְּאָדָם אִתְכְּלִילָן. אֶלָּא אִתְבְּטָלוּ וְאִסְתַּלָּקוּ מֵהַהוּא תִּקּוּנָא, עַד דְּיֵיתֵי תִּקּוּנָא (נ\"א דיוקנא) דְּאָדָם. וְכַד אָתָא הַאי דִּיּוּקְנָא, אִתְגֵּלָפוּ (ס\"א אתכללו) כֻּלְּהוּ, וְאִתְחֲזָּרוּ לְקִיּוּמָא אַחֲרָא. מִנְּהוֹן אִתְבְּסָמוּ, (ס\"א מנהון אתבסמו ולא אתבסמו) וּמִנְּהוֹן לָא אִתְבְּסָמוּ כְּלָל.","וְאִי תֵּימָא וְהָא כְּתִיב וַיָּמָת, וַיָּמָת. דְּאִתְבְּטָלוּ לְגַמְרֵי. לָאו הָכִי, אֶלָּא כָּל מַאן דְּנָחִית מִדַּרְגָּא קַדְמָאָה דְּהֲוָה בֵּיהּ, קָארֵי בֵּיהּ מִיתָה. כְּמָה דְאַתְּ אָמֵר, (שמות ב׳:כ״ג) וַיָּמָת מֶלֶךְ מִצְרַיִם, דְּנָחַת מִדַּרְגָּא קַדְמָאָה דְּהֲוָה קָם בֵּיהּ. וְכֵיוָן דְּאִתְתָּקַן אָדָם, אִתְקְרוּן בִּשְׁמָהָן אַחֲרָנִין, וְאִתְבְּסָמוּ בְּקִיּוּמָא בֵּיהּ, וְקַיְימִין בְּדוּכְתַּיְיהוּ.","וְכֻלְּהוּ אִתְקְרוּן בִּשְׁמָהָן אַחֲרָנִין מִן קַדְמָאִין, בַּר הַהוּא דִּכְתִּיב בֵּיהּ, (בראשית ל״ו:ל״ט) וְשֵׁם אִשְׁתּוֹ מְהֵיטַבְאֵל בַּת מַטְרֵד בַּת מֵי זָהָב. מַאי טַעְמָא. מִשּׁוּם דְּהָנֵי לָא אִתְבְּטָלוּ כִּשְׁאַר אַחֲרָנִין. מִשּׁוּם דְּהֲוָה דְּכַר וְנוּקְבָּא. כְּהַאי תְּמָרָא, דְּלָא סַלְּקָא אֶלָּא דְּכַר וְנוּקְבָּא. וּבְגִין כָּךְ הַשְׁתָּא דְּאִשְׁתְּכָחוּ דְּכַר וְנוּקְבָּא, לָא כְּתִיב בְּהוּ מִיתָה כְּאַחֲרָנִין, וְאִתְקְיָימוּ. אֲבָל לָא אִתְיָשָׁבוּ, עַד דְּאִתְתְּקַן דִּיּוּקְנָא דְּאָדָם, וְכֵיוָן דְּאִתְתְּקַן דִּיּוּקְנָא דְּאָדָם, אִתְחֲזָרוּ וְאִתְקְיָימוּ בְּקִיּוּמָא אַחֲרָא, וְאִתְיְישָבוּ.","תָּאנָא, כַּד סָלִיק בִּרְעוּתָא דְּרֵישָׁא חִוָּורָא, לְמֶעְבַּד יְקָרָא לִיקָרֵיהּ, תַּקִּין וְזַמִּין וְאַפִּיק מִבּוּצִינָא דְּקַרְדִּינוּתָא, חַד נִיצוֹצָא, נָשַׁב בֵּיהּ אִתְתּוֹקַּר (ס\"א אתתקן) וְסָלִיק (רעותיה) וְאִתְפָּשַּׁט לִתְלַת מְאָה וְשִׁבְעִין עִיבָר. וְנִיצוֹצָא קָאִים, וְשָׁארִי נָפִיק אֲוִירָא דַּכְיָא וּמִתְגַּלְגְּלָא, נָשַׁב בֵּיהּ אִתְתָּקַּן. וְנָפִיק חַד גּוּלְגַלְתָּא תַּקִּיפָא, וְאִתְפָּשַּׁט לְאַרְבַּע סִטְרִין.","וּבְהַאי אֲוִירָא דַּכְיָא, אִשְׁתְּאִיב נִיצוֹצָא וְאִתְאֲחָד, וְכָלִיל (ס\"א ואתכליל) בֵּיהּ. בֵּיהּ סַלְּקָא דַּעְתָּךְ. אֶלָּא אִתְטָמַר בֵּיהּ. וּבְגִין כַּךְ, הַאי גּוּלְגַּלְתָּא אִתְפָּשַׁט בְּסִטְרוֹי, וְהַאי אֲוִירָא הוּא טָמִיר דִּטְמִירִין דְּעַתִּיק יוֹמִין, בְּרוּחָא דְּגָנִיז.","בְּהַאי גּוּלְגַּלְתָּא אִתְפָּשָׁטוּ אֶשָּׁא מִסְּטַר חַד, וַאֲוִירָא מִסְּטַר חַד. וַאֲוִירָא דַּכְיָא קָאִים עָלֵיהּ מֵהַאי סְטָר. וְאֶשָּׁא דַּכְיָא קָאִים מֵהַאי סְטָר. מַאי אֶשָּׁא הָכָא. אֶלָּא לָאו הוּא אֶשָּׁא, אֲבָל בּוּצִינָא דָּא (נ\"א ניצוצא) דְּאִתְכְּלִיל בַּאֲוִירָא דַּכְיָא, נָהִיר לְמָאתָן וְשִׁבְעִין עָלְמִין, וְדִינָא מִסִּטְרוֹי אִשְׁתְּכַח, וּבְגִין דָּא, הַאי גּוּלְגַלְתָּא, אִתְקְרֵי גּוּלְגַּלְתָּא תַּקִּיפָא.","בְּגוּלְגַּלְתָּא דָּא, יַתְבִין תִּשְׁעָה אַלְפֵי רִבּוֹא עָלְמִין, דְּנַטְלִין עֲלוֹי וְסַמְכִין עֲלוֹי. בְּהַאי גּוּלְגַּלְתָּא, נָטִיף טַלָּא מֵרֵישָׁא חִיוָּורָא, דְּאִתְמְלֵּי מִנֵיהּ תָּדִיר. וּמֵהַאי טַלָּא דְּאַנְעַר מֵרֵישֵׁיהּ זְמִינִין מֵיתַיָּיא לְאַחֲיָּאָה.","וְהוּא טַלָּא דְּאִתְכְּלִיל בִּתְרֵי גְּוָונֵי, מִסִּטְרָא דְּרֵישָׁא חִיוָּרָא, חִיוָּור בְּגַוִויהּ (ס\"א בגיניה). דְּכָלִיל כֻּלְּהוּ חִיוָּורֵי (וכלהו חיוורי) אֲבָל כַּד אִתְיַישְּׁבָן בְּהַאי רֵישָׁא דִּזְעֵיר אַפִּין, אִתְחֲזֵי בֵּיהּ סוּמָקָא. כְּהַאי בְּדוֹלְחָא דְּאִיהוּ חִיוָּור, וְאִתְחַזְיָיא גַּוְונָא סוּמָקָא בְּגַוְונָא חִיוָּורָא.","וּבְגִין כַּךְ כְּתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת לְדִרְאוֹן עוֹלָם. לְחַיֵּי עוֹלָם, בְּגִין דְּאִתְחֲזִיאוּ לְהַהוּא חִיוָּורָא, דְּאָתֵי מִסְטַר דְּעַתִּיק יוֹמִין, אֲרִיכָא דְּאַנְפִּין. לַחֲרָפוֹת לְדִרְאוֹן עוֹלָם, בְּגִין דְּאִתְחֲזִיאוּ לְהַהוּא סוּמָקָא דִּזְעֵיר אַפִּין. וְכֹלָּא כָּלִיל בְּהַהוּא טַלָּא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ. אוֹרוֹת: תְּרֵין. וְהַהוּא טַלָּא דְּנָטִיף, נָטִיף כָּל יוֹמָא לְחַקְלָא דְּתַפּוּחִים. כְּגְוָונֵי חִיוָּורָא וְסוּמָקָא.","הַאי גּוּלְגַּלְתָּא אַנְהִיר בִּתְרֵי גְּוָונֵי, לְהַאי סְטָר וּלְהָאי סְטָר. וּמֵהַאי אֲוִירָא דַּכְיָא, אִתְפָּשָׁט מְגוּלְגַּלְתָּא לְאַנְפּוֹי ק\"נ רִבּוֹא עָלְמִין. וּבְגִין כַּךְ אִתְקְרֵי זְעֵיר אַפִּין. וּבְשַׁעֲתָא דְּאִצְטְרִיךְ, אִתְפְּשָׁטוּ אַנְפּוֹי וַאֲרִיכִין בְּהַהוּא זִמְנָא, בְּגִין דְּאַשְׁגַּח בְּאַנְפּוֹי דְּעַתִּיקֵי דְּעַתִּיקִין, וְחָיֵיס לְעָלְמָא.","וּמֵהַאי גּוּלְגַּלְתָּא, נָפִיק חַד עִיבָר, לְכָל אִינּוּן דִּלְתַּתָּא. וְיָהֲבֵי אֲגָר אוֹרָאוּתָא לְעַתִּיק יוֹמִין. כַּד עָאלִין בְּחוּשְׁבָּנָא, תְּחוֹת שַׁרְבִיטָא. וְלָקֳבֵיל דָּא. (שמות ל״ח:כ״ו) בֶּקַע לַגוּלְגֹּלֶת לְתַתָּא, כַּד עָאלִין בְּחוּשְׁבָּנָא. וְהַאי בֶּקַע אֲגָר אוֹרָאוּתָא, אִשְׁתְּכַח מִנֵּיהּ לְעַתִּיק יוֹמִין."],[[0,"ובגין דתקונא דא","וכו׳: ומשום שתקון זה של אדם לא נמצא בהם, לא יכלו ז׳ המלכים לעמוד ולהתישב, ונתבטלו. שואל, וכי יעלה על דעתך שנתבטלו, והרי כולם נכללו אח״כ בעולם התקון באדם. דהיינו בז״א. ומשיב, אלא שנתבטלו ונסתלקו מאותו התקון שהיה להם בנקודים, עד שיבא תקון אדם בעולם התקון. וכשבאה צורת האדם הזה נחקקו כולם בצורתו, וחזרו לקיום אחר. מהם נתבשמו, ומהם שלא נתבשמו כלל."],[0,"","פירוש, כי סוד תקון אדם אינו ממשיך רק ו״ק דחכמה, ונמצא שאותם החלקים של המלכים דנקודים שהיה בהם מבחינת ג״ר דחכמה, לא נכללו ולא נתקנו ע״י תקון אדם שבעולם התקון. וז״ש, \u0003מנהון אתבסמו\u0004 דהיינו החלקים שבו\"ק דחכמה. \u0003ומנהון לא אתבסמו,\u0004 דהיינו החלקים שבג״ר דחכמה."],[1,"ואי תימא והא","וכו׳: ואם תאמר, הרי כתוב, וימת. וימת משמע שנתבטלו לגמרי. ומשיב, אינו כן. אלא כל מי שיורד ממדרגה הראשונה שהיה בו, נקראת בו מיתה. כש״א וימת מלך מצרים, שפירושו, שירד ממדרגתו הקודמת שהיה עומד בו. דהיינו שנצטרע. (שמו\"ר פ״א ל״ג) אף כאן, כיון שירדו מעולם אצילות למדרגת בי״ע נחשב להם למיתה. וכיון שנתקנה בהם צורת אדם, בג׳ קוין, נקראו בשמות אחרים, ונתבשמו על ידו בקיום, ומתקיימים במקומם."],[2,"וכלהו אתקרון בשמהן","וכו׳: וכולם נקראו בשמות אחרים מן הראשונים, חוץ אותו שכתוב בו, ושם אשתו מהיטבאל בת מטרד בת מי זהב. שה״ס שם מ״ה החדש דכר ונוקבא הנקראים הדר ומהיטבאל מה הטעם שלא נקרא בשם אחר. הוא משום שאלו הדר ומהיטבאל לא נתבטלו כשאר ז׳ מלכים האחרים. משום שהיו דכר ונוקבא. בדומה לאותו התמר, שאינו עולה, אלא בזכר ונקבה. ומשום זה עתה שנמצאו זכר ונקבה לא כתובה בהם מיתה כאחרים ונתקיימו, אבל לא נתישבו לגמרי עד שנתקנה צורת אדם. וכיון שנתתקנה צורת אדם, חזרו ונתקיימו בקיום אחר, ונתישבו."],[3,"תאנא כד פליק","וכו׳: למדנו, כשעלה ברצון הראש הלבן. שהוא גלגלתא דא״א, לעשות יקר ליקרו. תקן והכין והוציא מהנר הקשה ניצוץ אחד, ועלה ונתפשט לש״ע צדדים. והניצוץ עומד, ומתחיל לצאת אויר טהור ומתגלגל, נפח בו נתתקן. ויצאה גלגלת אחת חזקה ונתפשטה לארבע צדדים."],[3,"","פירוש. נודע סוד אצילות המוחין דז״א, שהוא בסוד תלת נפקי מחד חד בתלת קיימא. כי אחר שיצא קו השמאל דבינה נעשתה מחלוקת בין ימין ושמאל, ולא יכלו להאיר עד שעלה ז״א בסוד הקו האמצעי והכריע ביניהם, ויצאו ג׳ קוין חכמה בינה דעת בבינה. שז״ס \u0003תלת,\u0004 שהם חב״ד, \u0003נפקי מחד\u0004 שיצאו מז״א. וכל שיעור האור שהתחתון גורם לעליון, זוכה בו גם התחתון, וע״כ \u0003חד בתלת קיימא,\u0004 זכה ז״א ג״כ בתלת מוחין חכמה בינה דעת, ונתפשטו אליו (כנ״ל ב\"א דף רפ״ז ד״ה תלת עש״ה)."],[3,"","וז״ש, \u0003כד סליק ברעותא דרישא חוורא למעבד יקר ליקריה,\u0004 התקונים שברישא חוורא נקראים יקרו. וז״א, הצריך לקבלם נקרא יקר ליקרו. \u0003תקין וזמין,\u0004 דהיינו שתקן והכין תחילה הקטנות דבינה בסוד נקודת החולם. שה״ס עלית המלכות בבינה. ואח״כ \u0003ואפיק מבוצינא דקרדינותא,\u0004 שהוא קו שמאל דא״א, \u0003חד ניצוצא,\u0004 דהיינו שא״א הוציא מקו שמאל של עצמו, את קו השמאל של בינה, \u0003וסליק,\u0004 שקו האמצעי עלה, \u0003ואתפשט לש״ע עיבר,\u0004 דהיינו שעל ידי עלית ז״א לבחינת קו אמצעי ליחד ב׳ קוין ימין ושמאל דבינה זה בזה, יצאו ש״ע עיבר, שהם ג׳ קוין שהם שלש מאות, ומלכות המקבלתם שה״ס שבעים. כי ספירות הבינה הן בסוד מאות, רק המלכות שה״ס אור נקבה חסרה ג״ר, ואין לה אלא ע׳ עיבר. וביחד הם ש״ע עיבר."],[3,"","ואחר שפירש בכללות חוזר ומפרש הדברים בפרטות. ואומר, \u0003וניצוצא קאים,\u0004 ניצוץ אחד, שהוא קו השמאל שבבינה, עומד. \u0003ושארי נפיק אוירא דכייא,\u0004 שהוא קו הימין שבבינה. \u0003ומתגלגלא,\u0004 שהיו מתגלגלין מרחמים לדין ומדין לרחמים, פעם קם השמאל ושלט, ופעם קם הימין ושלט, דהיינו שהיו במחלוקת, ולא יכלו להאיר. \u0003נשב ביה,\u0004 היינו קו אמצעי, שנפח ונשב בקו שמאל ומיעטו, ואז \u0003ואתתקן,\u0004 שב׳ הקוים נתיחדו זה בזה, ויצאו ג׳ קוין חכמה בינה דעת בבינה ואז כיון שתלת נפקי מחד, חד בתלת קיימא, ויצאו חב״ד גם בז״א, וז״ש, \u0003ונפיק חד גלגלתא תקיפא,\u0004 דהיינו גלגלתא דז״א, שה״ס אור מקיף דמוחין שלו, \u0003ואתפשט לארבע סטרין,\u0004 דהיינו חו״ב, וימין ושמאל שבדעת, שהם ג׳ קוין ומלכות המקבלתם, כי השמאל דדעת הוא מלכות, שה״ס ש״ע עיבר כנ״ל. וז״א קיבל אלו ד׳ סטרין מבינה, מטעם הנ״ל, משום שתלת נפקי מחד, חד בתלת קיימא."],[3,"","ומה שמחלק בגלגלתא את קו האמצעי לב׳ סטרין. הוא משום, כי כשיצאו המוחין מנה״י דבינה, שהם ישסו״ת, אל ז״א, יצאו תחלה בבחינת אור מקיף, דהיינו כבחינת או״א עלאין, שבהם לא נפיק ה \u0003י׳\u0004 מאויר שלהם, ויש הפרש בין ימין ושמאל דדעת, שזה חסד וזה דין, אבל בישסו״ת, שהם נה\"י, דבינה, שבהם יוצאת ה \u0003י׳\u0004 מאויר, והקו שמאל מתיחד עם הימין רק ע״י הדין שבמסך דקו האמצעי שהוא השמאל דדעת. ע״כ נעשה הדין דדעת לאחד עם החסד דדעת, שהוא חשוב כמוהו, שהרי לולא הדין דדעת לא נתיחדו הקוין זה בזה. וע״כ נעשו שניהם לבחינה אחת. ותחילה יוצאים בחינת או״א עלאין, שה״ס ד׳ סטרין המאירים בגלגלתא, ואח״כ יוצאים בחינות ישסו״ת, שהם רק ג׳ סטרין חב״ד. והם מתבארים לפנינו בסוד ג׳ חללי גלגלתא שבז״א, שה״ס ג׳ מוחין חב״ד, ולא ד׳ סטרין."],[3,"","ודע שבשעה שהעליון מאציל את התחתון מאציל אותו ממדרגות של עצמו, כי אין העדר ברוחני וכל המדרגות היוצאות בזה אחר זה, אין אחת מבטלת את חברתה, ואין הגדלות מבטלת את הקטנות. וע״כ כשא״א רצה להאציל את הקטנות דז״א העיר בעצמו מדרגת הקטנות, שעקרו הוא עלית המלכות לבינה, והשפיע לבינה ולז״א. ואח״כ כשרצה להשפיע לו קו שמאל, העיר השמאל של עצמו, והשפיע לבינה ולז\"א. וז״ש, \u0003ואפיק מבוצינא דקרדינותא,\u0004 שהוא קו שמאל של עצמו, \u0003חד ניצוצא,\u0004 שהוא קו שמאל שבבינה. וכן בכל מדרגה ומדרגה."],[4,"ובהאי אוירא דכיא","וכו׳: ובאויר הטהור הזה, שבגולגלתא, שה״ס קו ימין נשאב הניצוץ, דהיינו קו שמאל, ונכלל בו, בקו ימין. שואל. היעלה על דעתך שנכלל בו, והלא שניהם צריכים להשאר. ומשיב, אלא שקו השמאל, נסתתר בו, דהיינו שנסתר שליטתו דקו שמאל, שה״ס הארת חכמה ואיני פועל כלום, ורק קו הימין לבדו שולט, שהוא אוירא דכיא, דהיינו חסדים. ומשום זה גולגלתא זו דז״א, נתפשטה בצדדיה, ואויר הזה שבה, דהיינו קו הימין, הוא נסתר הנסתרות מעתיק יומין, ברוח שגנז. דהיינו הי׳ שגנז באויר. כמו שנתבאר לעיל בדבור הסמוך, שאלו ד׳ סטרין דגלגלתא הם בחינת או״א עלאין שהי׳ גנוזה באויר שלה ואינה יוצאת ממנו."],[5,"בהאי גולגלתא אתפשטו","וכו׳: בגלגלת זו דז״א, נתפשטו, אש מצד אחד, ואויר מצד אחד, ואויר טהור עומד עליו מצד זה, ואש טהורה עומדת מצד זה. כי חכמה ובינה נקראים אוירא דכיא ואשא דכיא, וימין שבדעת נקרא אוירא סתם. והשמאל שבדעת נקרא אשא סתם. שואל, מה היא אש כאן, והלא ד׳ סטרין אלו הם בחינות או״א, שאין שם דינים כלום, וכולם חסדים. ומשיב אלא הוא אינו אש אבל ניצוץ זה, דהיינו קו שמאל, שנכלל באויר הטהור, (כנ״ל בדבור הסמוך) מאיר לר״ע עלמין, ודין נמצא מצדו. ומשום זה נקרא גולגלתא זו, גולגלתא תקיפא."],[5,"","פירוש, מחזה ולמטה דאו\"א עלאין, ששם בחינת ישסו״ת, נבחן לר״ע עלמין, כי החזה עומד בסיום שליש עליון דת״ת, ויש ב׳ ספירות ושליש למעלה מחזה, שהם חסד וגבורה ושליש ת״ת, וספירות אלו הם בסוד מאות, והם ר״ל. וב׳ ספירות וב׳ שלישים מחזה ולמטה, שהם ב׳ שלישי ת״ת, ונצח והוד. כי אמא רק עד הוד אתפשטותה. שנצח והוד הם מאתים, וב׳ שלישי ת״ת, הם שבעים. הרי שמחזה ולמטה הם \u0003ר״ע עלמין.\u0004 ונודע שאע״פ שקו שמאל. אינו מאיר באו״א עלאין, כנ״ל שמסתתר באוירא דכיא. וכולו חסדים, עכ״ז בישסו״ת שמחזה ולמטה דאו״א מאיר קו השמאל, כי שם הי׳ יוצאת מאויר וז״ש, \u0003אלא לאו הוא אשא,\u0004 כי באו״א עלאין המאירים בגלגלתא דז״א, אין שום שליטה לקו שמאל, וא״כ אינו אש. \u0003אבל דא ניצוצא דאתכליל באוירא דכיא,\u0004 שניצוץ הזה, שהוא קו שמאל, שנכלל כולו באויר טהור אצל או״א, ואין לו שליטה כלל, \u0003נהיר למאתן ושבעין עלמין,\u0004 דהיינו שמתגלה הארתו מחזה ולמטה דאו״א, ששם ר״ע עלמין כנ״ל, ששם בחינת ישסו״ת שה \u0003י׳\u0004 יוצאת מאויר שלהם, ובהם מתגלים הדינים דקו שמאל, שה״ס אש. ונמצא \u0003ודינא מסטרוי אשתכח,\u0004 שאע״פ שקו שמאל דאו״א אינו בחינת דין כלום, אמנם הדין נמצא מצדו, דהיינו בעת הארתו מחזה דאו״א ולמטה בישסו״ת, וע״כ נבחן גם קו שמאל שלמעלה מחזה בשם אש. כי קו השמאל שבישסו״ת נמשך מקו השמאל דאו״א."],[6,"בגלגלתא דא יתבין","וכו׳: בגלגלתא זו, יושבים ט׳ אלפי רבוא עולמות, שנוסעים עליה ונסמכים עליה. בגולגלתא זו נוטף טל מראש הלבן, דהיינו מגולגלתא דא״א, שנתמלא ממנו תמיד. ומטל זה שמנער מראשו עתידים המתים להחיות."],[6,"","פירוש. כי בגולגלתא דא״א אומר (באות ט״ז) שיושבים עליה י״ג אלפי רבוא עולמות, שה״ס ג׳ הויות, מימין, ומשמאל, ומאחורי הראש. שה״ס \u0003ם׳ ל׳ צ׳,\u0004 וחב״ד חג״ת נה״י. כמ״ש שם. (באות י״ח) ואומר כאן שגולגלתא דז״א מקבל מגולגלתא דא״א, רק ב׳ הויות שמימין ומשמאל, שה״ס חב״ד חג״ת, ובחינת מלכות הכוללת אותם, וחסר להם ד׳ חוורתא של הויה שמאחורי הראש דא״א, דהיינו שיש לו חב״ד חג״ת, וחסר נה״י. ונודע שהחסר נה״י דכלים חסר ג״ר דאורות. וז״ש, \u0003בגולגלתא דא\u0004 דז״א, \u0003יתבין ט׳ אלפי רבוא עלמין,\u0004 דהיינו רק מב׳ הויות שבימין ושמאל דראש לצד פנים, שהם חב״ד חג״ת דכלים וו\"ק חסר ג״ר דאורות. וע״כ אומר, \u0003יתבין,\u0004 כי בישיבה חסרה פעולה מנה״י. וע״כ מורה על חסרון נה״י דכלים וג״ר דאורות. ואע״פ שגם \u0003בגולגלתא\u0004 דא״א, אומר, \u0003יתבין,\u0004 אמנם זה נוהג שם בעת המנוחה, אבל בעת הנסיעה יש שם רגלין שהם נה״י, שאומר שם (באות ט״ז) \u0003דנטלין עלוי רגלין,\u0004 משום שבעת נסיעה מתגלים נה״י דכלים וג״ר דאורות, כי יש שם י״ג חוורתא, שהם חב״ד חג״ת נה״י. כמ״ש שם. אבל כאן בגולגלתא דז״א, אומר, \u0003דנטלין עלוי וסמכין עלוי,\u0004 ואינו מזכיר \u0003רגלין,\u0004 שהם נה״י, כי משום שחסר מד׳ חוורתא דהוי״ה דאחורי ראש דא״א, הוא חסר מנה״י ואין לו רגלין. ולפיכך, אין לו אלא, \u0003ט׳ אלפי רבוא עלמין,\u0004 מן גולגלתא דא״א. וחסר ד׳ אלפי רבוא עלמין מהויה שבאחורי הראש של א\"א. וענין הטל כבר נתבאר לעיל (אות י״ז) וכל זה נאמר בבחינת התפשטות מגלגלתא דז״א לז״א אבל הגלגלת דז״א מבחינת עצמה, יש לה ג״ר, שה״ס ד׳ סטרין, ג׳ קוין ומלכות המקבלתם. כנ״ל."],[7,"והוא טלא דאתכליל","וכו׳: והוא טל שנכלל בב׳ אפנים מצד ראש הלבן, שהוא א״א, א׳, שהוא לבן בעצמו. ב׳, שכולל כל הלבן. אמנם כשהטל מתישב בראש הזה דז״א נראה בו אדום, כבדולח הזה שהוא לבן, ונראה הצבע האדום בתוך הצבע הלבן."],[7,"","פירוש כי בא״א אין שום גילוי לשמאל, וכולו ימין, וע״כ ההפרש מקו ימין לקו שמאל שבו הוא, שמקו ימין \u0003חיוור בגוויה,\u0004 שהוא עצמו לבן. והקו שמאל, \u0003כליל כלהו חיוורי,\u0004 דהיינו כל הלבן שבקו ימין, וגוון אדום הנוהג בשמאל אין בו שום גילוי. אבל בז״א המקבל הטל הזה, כבר יש בו הבחן אדום בקו שמאל שבו, אמנם לא אדום ממש, אלא \u0003כעין הבדלח,\u0004 שהאדום נוצץ בתוך הלבן."],[8,"ובגין כך כתיב","וכו׳: ומשום זה כתוב, ורבים מישני אדמת עפר יקיצו אלה לחיי עולם ואלה לחרפות לדראון עולם. \u0003לחיי עולם,\u0004 היינו אותם שהם ראוים לאותו טל הלבן הבא מצד עתיק יומין, שהוא אריך אנפין. \u0003לחרפות ולדראון עולם,\u0004 היינו אותם הראוים לאותו האדום שבטל שבז״א. והכל כלול בטל ההוא, ז״ש כי טל אורות טלך, \u0003אורות,\u0004 משמעותו שנים, כי טל ההוא הנוטף, נוטף כל יום לחקל תפוחין. שהוא מלכות, יש בו ב׳ אורות, כעין לבן ואדום."],[9,"האי גולגלתא אנהיר","וכו׳: גלגלתא הזו, דז״א שה״ס או״מ (כנ״ל אות קפ\"א) מאירה בב׳ צדדים לצד זה ולצד זה, דהיינו אוירא דכיא ואשא דכיא, ומאוירא דכיא זה מתפשט מגלגלתא שלו אל הפנים שלו ק״נ רבוא עולמות. ומשום זה נקרא זעיר אנפין, שפירושו פנים קטן. ובשעה שצריך, דהיינו בעת שהתחתונים כדאים, מתפשטים פניו וארוכים בעת ההיא כמו אריך אנפין, דהיינו, ש״ע רבוא נהורין, משום שמסתכל בפנים של עתיק העתיקים, ומרחם על העולם. שה\"ס אור מקיף שלו. (כנ״ל אות קפ״א)."],[9,"","פירוש, כבר נתבאר שבגלגלתא דז\"א אין י״ג אלפי רבוא כמו בגלגלתא דא״א, אלא ט׳ אלפי רבוא, שפירושו שאין מתפשט ממנו רק ו״ק, (כנ״ל אות קפ״ד) ובמצב הזה אין ז״א מקבל רק בחינת ימין בלבד שהוא חסדים, ואינו מקבל מבחינת שמאל. ונודע שש״ע רבוא, פירושו ג׳ קוין ומלכות המקבלתם. שעל ידיהם מושפעת הארת החכמה והג״ר. וע״כ מספר זה נבחן לאריכת פנים, כי אורך רומז על החכמה, שזה נוהג בפנים דא״א, המקבל ש״ע נהורין מגלגלתא שלו. אבל ז״א המקבל רק חסדים בלבד מן הגלגלתא שלו, הרי אין שם אלא קו אחד וחצי, דהיינו קו הימין, וחצי הקו הימיני של הדעת, הנקראים אוירא דכיא. ומקו שמאל, וכן חצי קו השמאל, של הדעת אשר נקראים אשא דכיא, אינו מקבל כלום, ומכל שכן שאין לו ממלכות הכוללתם, וכיון שהגלגלתא היא מבינה, ע״כ ספירותיה בסוד מאות, וקו וחצי שבימין ה״ס ק״נ. וז״ש \u0003ומהאי אוירא דכיא,\u0004 דהיינו אוירא דכיא שבקו ימין דגלגלתא, וכן חצי קו הימני של הדעת, הנקרא אוירא, \u0003אתפשט מגלגלתא לאנפוי, ק״נ רבוא עלמין,\u0004 דהיינו קו וחצי דחסדים הנקראים אוירא דכיא. אבל מקו וחצי דגבורות, שמשם נמשכת הארת החכמה אין מהם התפשטות אל פניו. וע״כ הוא חסר ק״נ רבוא דשמאל, וחסר ממלכות הכוללת ג׳ קוין. \u0003ובג״כ אתקרי זעיר אפין.\u0004 אבל, \u0003ובשעתא דאצטריך, אתפשטו אנפוי\u0004 וכו'. דהיינו כשהתחתונים זכאים, ויש לו ג״ר, אז יש לו ש״ע רבוא, כמו א״א, והוא ארוך הפנים כמוהו."],[10,"ומהאי גלגלתא","וכו׳: ומגלגלתא הזו דז״א, יוצא עיבר אחד, דהיינו חוורתא אחת שמקבל מחוורתא דא\"א (כנ״ל אות קפ\"ד) שהוא הארת הג״ר, לכל אלו שלמטה. ונותנים שכר אוראותא, דהיינו שכר הג״ר לעתיק יומין כשהם באים בחשבון תחת השרביט. וכנגד זה \u0003בקע לגלגלת\u0004 שנותנים למטה כשנכנסים לחשבון. ובקע הזה הוא שכר הג״ר הניתן ממנו לעתיק יומין. \u0003אוראותא,\u0004 הוא אותיות \u0003אור ראותא,\u0004 דהיינו אור החכמה הנקרא ראיה או ראות."],[10,"","פירוש. חשבון, פירושו אור החכמה, (כנ״ל פקודי אות כ״ח ע״ש). והוא מקובל רק ע״י העלאת המלכות לבינה, שאז נמשך לתחתונים הקטנות דבינה, שה״ס חצי מדרגה, כו״ח דכלים ונפש רוח דאורות. ואחר שמקבל הקטנות דבינה הוא ראוי לקבל החכמה מקו שמאל דבינה. ומיתוק זה דהעלאת המלכות בבינה, מתחיל בעתיק יומין שה״ס א״א, שמשם מקבלים כל הפרצופין. נמצא שאין התחתונים יכולים לקבל ג״ר מטרם שמעלים מ\"ן להמשיך הקטנות מבינה, שה״ס חצי מדרגה, וע״כ נקרא \u0003בקע.\u0004 והעלאת מ\"ן הזו, נבחן לשכר שנותנים לעתיק יומין בעד השפעת הג״ר שלו מבינה שלו. וז״ש, \u0003ויהבי אגר אוראותא לעתיק יומין,\u0004 כי העלאת מיין להמשכת חצי מדרגה דקטנות הבינה, נבחן לשכר בעד אוראותא, שפירושו אור החכמה המקבלים מבינה דעתיק יומין, שה״ס בינה דא״א שיצאה לחוץ, בסוד ונהר יוצא מעדן. וז״ש, \u0003כד עאלין בחושבנא תחות שרביטא,\u0004 כלומר בשעה שנכנסים בסוד החשבון שפירושו הארת החכמה, שזסו\"ה \u0003כי תשא את ראש בני ישראל\u0004 וגו', דהיינו כי תמשיך את הג״ר, המכונים \u0003ראש,\u0004 לבני ישראל. ונתנו איש כפר נפשו, היינו \u0003בקע לגלגלת,\u0004 שה״ס העלאת מ״ן להמשיך חצי מדרגה, המכונה \u0003בקע.\u0004 וז״ש \u0003לגלגלת,\u0004 כדי להמשיך ג״ר המכונה גלגלת. וז״ש, \u0003ולקביל דא בקע לגלגלת,\u0004 שה״ס שכר אוראותא כמבואר."]],[]],[["בַּחַלָּלֵיהּ דְּגוּלְגַּלְתָּא, (ס\"א בגולגלתא דא) ג' חַלָלִּין אִשְׁתְּכָחוּ, דְּשַׁרְיָיא מוֹחָא בְּהוּ, וּקְרוּמָא דָּקִיק חַפְיָּיא עָלַיְיהוּ. אֲבָל לָא קְרוּמָא קְשִׁישָׁא סְתִימָא כְּעַתִּיק יוֹמִין. וּבְגִין דָּא, הַאי מוֹחָא אִתְפְּשָׁט וְנָהִיר (ס\"א ונפיק) לִתְלָּתִין וּתְרֵין שְׁבִילִין. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן.","וְתָאנָא, בִּתְלַת חַלָלִין דְּגוּלְגַּלְתָּא מוֹחָא שַׁרְיָיא. מֵחַלָלָא חַד מִתְבְּקַע (ס\"א ומתפשט) חַד מַבּוּעָא לְד' סִטְרִין, וְנָפִיק מֵהַהוּא מוֹחָא דְּשַׁרְיָיא בְּהַאי חַלָּלָא, תְּלָתִין וּתְרֵין שְׁבִילִין רוּחִין דְּחָכְמְתָא.","מֵחַלָלָא תִּנְיָינָא, מִתְבְּקַע וּמִתְפָּשַׁט חַד מַבּוּעָא אַחֲרָא. וּמִתְפַּתְחִין ן' תַּרְעִין. מֵאִלֵּין ן' תַּרְעִין, אִתְאַחֲדָן ן' יוֹמִין דְּאוֹרַיְיתָא. ן' שְׁנִין דְּיוֹבְלָא. ן' אֶלֶף דָּרִין, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאָתָבָא רוּחֵיהּ לֵיהּ, וּלְשַׁרְיָיא בֵּיהּ.","מֵחַלָלָא תְּלִיתָאָה, נָפְקִין אֶלֶף אַלְפִין אִדָּרִין וְאַכְסַדְרָאִין, דְּדַעְתָּא שַׁרְיָיא עָלַיְיהוּ, וְדָרֵי בְּהוּ. וְהַאי חַלָּלָא שָׁרֵי חֲלָלֵיה (ס\"א מדוריה) בֵּין הַאי חַלָּלָא וּבֵין הַאי חַלָּלָא, וְאִתְמַלְּיָין מִתְּרֵין סִטְרִין. כָּל אִינּוּן אִדָּרִין. הֲדָא הוּא דִכְתִיב, (משלי כ״ד:ד׳) וּבְדַעַת חֲדָרִים יִמָּלְאוּ. וְאִלֵּין ג' מִתְפַּשְּׁטִין בְּכָל גּוּפָא, לְהַאי סִטְרָא וּלְהַאי סִטְרָא. וּבְאִינּוּן אָחִיד כָּל גּוּפָא וְאָחִיד בְּהוּ גּוּפָא מִכָּל סִטְרוֹי. וּבְכָל גּוּפָא אִתְפַּשְּׁטָן וְאִשְׁתַּכְּחָן.","תָּאנָא, בְּגוּלְגַּלְתָּא דְּרֵישָׁא, תַּלְיָין אֶלֶף אַלְפֵי רִבּוֹא וְרִבּוֹא רִבְּבָן קוֹצֵי דְּשַׂעְרֵי אוּכָמָן, וּמִסְתַּבְּכִין דָּא בְּדָא, וּמִתְעָרְבִין דָּא בְּדָא. וְלֵית חוּשְׁבָּנָא לְנִימִין דְּכָל קוֹצָא וְקוֹצָא, דַּאֲחִידָן בֵּיהּ דַּכְיָין וּמְסַאֲבָן. וּמִכָּאן אִתְאַחֲדָן טַעֲמֵי אוֹרַיְיתָא, בְּדַכְיָא בִּמְסָאֲבָא. בְּכָל אִינּוּן סִטְרִין דְּאִינּוּן דַּכְיָין, בְכָל אִינּוּן סִטְרִין דְּאִינּוּן מִסְאָבָן.","יַתְבִין קוֹצֵי מִסְתַּבְּכִין וְתַקִיפִין. מִנְּהוֹן שְׁעִיעִין, וּמִנְהוֹן תַּקִּיפִין. וּבְכָל קוֹצָא וְקוֹצָא, יַתְבִין נִימִין תִּלִין עַל תִּלִין. מִתְלַהֲטָן וְתַּלְיָין כְּגִיבָּר תַּקִּיף, מָארֵי נַצַח קְרָבִין. בְּתִקּוּנָא יָאֶה בְּתִקּוּנָא שַׁפִּירָא תַּקִּיפָא (בחור כארזים). רַבְרְבִין וְתַקִיפִין. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:ט״ו) בָּחוּר כָּאֲרָזִים.","מִתְתַּקְּנִין קוֹצִין דְּשַׂעְרֵי, וְתַּלְיָין תִּלִין עַל תִּלִין, מֵהַאי סִטְרָא לְהַאי סִטְרָא, עַל גּוּלְגֹּלְתָּא. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:י״א) קְווּצּוֹתָיו תַּלְתַּלִּים. וְתָאנָא יַתְבִין תִּלֵי תִּלִּין, מִשּׁוּם דִּמְשִׁיכִין מִמַּבּוּעִין סַגִּיאִין, דִּתְלַת רַהֲטֵי מוֹחָא. מִמַּבּוּעָא חַלָּלָא חַד דְּגוּלְגַּלְתָּא, אִתְמַשְּׁכָן שַׂעְרֵי בִּמְשִׁיכוּתָא, וּמִתְעָבְדִין תִּלִין, דְּתַּלְיָין מִכַּמָּה מַבּוּעִין, דְּאִתְמַשְּׁכָן מֵהַאי חַלָּלָא. מֵחַלָלָא תִּנְיָינָא, נַפְקֵי חַמְשִׁין מַבּוּעִין, וְאִתְמַשְּׁכָן שַׂעְרֵי מֵאִינּוּן מַבּוּעִין בִּמְשִׁיכוּתָא, וְאִתְעָבְדִין תִּלִין, דְּתַלְיָין וּמִתְעָרְבִין בְּקוֹצִין אַחֲרָנִין. מֵחַלָלָא תְּלִיתָאָה, נָפְקֵי אֶלֶף אַלְפִין אִדָּרִין וְאַכְסַדְרָאִין, וְאִתְמַשְּׁכָן שַׂעְרֵי בִּמְשִׁיכוּתָא מִכֻּלְּהוּ. (ומתעבדין תלין על תלין ומתערבין בקוצין אחרנין) וּבְגִין כָּךְ אִינּוּן קוֹצִין, תִּלִּין עַל תִּלִּין.","וְכֻלְּהוּ מְשִׁיכָן דְּאִתְמַשְּׁכָן מִג' חַלָלִין דְּמוֹחָא דְּגוּלְגַּלְתָּא. וְכָל אִינּוּן נִימִין וְכָל אִינּוּן קוֹצֵי תַּלְיָין וְחַפְּיָין לְסִטְרָא דְּאוּדְנִין. וּבְגִין כָּךְ כְּתִיב, (דניאל ט׳:י״ח) הַטֵּה אֱלֹהַי אָזְנְךָ וּשְׁמָע. וּבְהַאי תִּלִין, תַּלְיָין (נ\"א ובהאי תליין) יְמִינָא וּשְׂמָאלָא, נְהוֹרָא וַחֲשׁוֹכָא, רַחֲמֵי וְדִינָא. וְכָל יְמִינָא וּשְׂמָאלָא תָּלֵי בְּהַאי, וְלָא בְּעַתִּיקָא.","בְּפַלְגוּתָא דְּשַׂעְרֵי, אִתְחֲזֵי חַד אוֹרְחָא דָּקִיק, דְּמִתְאַחֲדָא מֵהַהוּא אָרְחָא דְּעַתִּיק יוֹמִין. וּמֵהַהוּא אָרְחָא, אִתְפָּרְשָׁן שִׁית מְאָה וּתְלֵיסָר אָרְחִין, דְּאִתְפַּלְגוּן בְּאָרְחִין דְּפִקוּדֵי דְּאוֹרַיְיתָא. דִּכְתִּיב, (תהילים כ״ה:י׳) כָּל אָרְחוֹת יְיָ חֶסֶד וְאֱמֶת לְנוֹצְרֵי בְרִיתוֹ וְעֵדוֹתָיו.","תָּנָא, בְּכָל קוֹצָא וְקוֹצָא, מִתְאַחֲדָן אֶלֶף אַלְפִין מָארֵי דִּיבָבָא וִילָלָה, דְּתַּלְיָין בְכָל קוֹצָא וְקוֹצָא מֵאִינּוּן תַּקִּיפִין. וּמֵאִינּוּן שְׁעִיעִין מָארֵיהוֹן דְּמַתְקְלָא, (ס\"א מאריהון דרחימותא ואיהו מתקלא בינייהו) בְּגִין כָּךְ אִית יְמִינָא וְאִית שְׂמָאלָא.","מִצְחָא דְּגוּלְגַּלְתָּא. אַשְׁגָּחוּתָא דְּאַשְׁגָּחוּתָא. וְלָא מִתְגַּלְיָיא, בַּר הַהוּא זִמְנָא, דִּצְרִיכִין חַיָּיבַיָּא לְאִתְפַּקְּדָא, וּלְעַיְּינָא בְּעוֹבָדֵיהוֹן. וְתָאנָא, כַּד אִתְגַּלְיָיא הַאי מִצְחָא, אִתְּעֲרוּ כָּל מָארֵיהוֹן דְּדִינָא, וְכָל עָלְמָא בְּדִינָא אִתְמְסַר. בַּר הַהִיא שַׁעֲתָא, כַּד סְלִיקוּ צְלוֹתְהוֹן דְּיִשְׂרָאֵל לְקַמֵּי עַתִּיק יוֹמִין, וּבָעֵי לְרַחֲמָא עַל בְּנוֹי, גַּלֵּי מִצְחָא דְּרַעֲוָא דְּרַעֲוִין, וְנָהִיר בְּהַאי דִּזְעֵיר אַפִּין, וְאִשְׁתְּכִיךְ דִּינָא."],[[0,"בחלליה דגולגלתא ג׳","וכו׳: בחללו של הגלגלת נמצאים ג׳ חללים שהמוח שורה בהם וקרום דק מכסה עליהם. אבל לא קרום קשה וסתום כמו בעתיק יומין (לעיל אות כ״א) ומשום זה, מוח זה מתפשט ומאיר לל״ב שבילים של חכמה. ז״ש, ונהר יוצא מעדן."],[0,"","כבר נתבאר לעיל שגלגלתא דז\"א מתוקנת בבחינת או״א עלאין, וע״כ יש בה ד׳ מוחין, חכמה, בינה, ימין דדעת, ושמאל דדעת, כי הדעת מחולקת לימין ולשמאל, כי משום שאין שם יחוד קו אמצעי להמשיך חכמה, יש בו היכר בין ימין לשמאל, והם שנים. אבל חללי הגלגלתא הם בחינת ישסו״ת, שהי׳ יוצאת מאויר שלהם, והדעת שהיא קו אמצעי, מיחדת ימין ושמאל, שהם חו״ב, זה בזה, וממשיכה מהם הארת חכמה, וע״כ גם ימין ושמאל שבדעת נעשו אחד, ואין כאן אלא ג׳ מוחין חב״ד, בג׳ חללי גלגלתא. (כנ״ל אות קפ״א)."],[0,"","ונתבאר לעיל (אות כ״ג) שכמו שיש קרום בחזה שבגוף המפסיק בין ג״ר דגוף לו״ק דגוף, כן יש קרום בבחינת חזה שבראש המפסיק בין ג״ר דראש שה״ס הגלגלתא, ובין הו״ק דראש, שה״ס המוחין, אשר בא״א, הוא קרום קשה ואינו נפסק לעולם, דהיינו אפילו בעת גדלות שהמלכות יורדת ממקום בינה והפרסא מתבטלת לשעתו, כדי שחצי המדרגה התחתונה תחזור ותתחבר עם חצי המדרגה העליונה, הנה זה נאמר בשאר הפרצופין ולא בראש דא״א, כי בו אין הפרסה שבראש מתבטלת בשעת הזווג, ואין המוח שבראשו יכול לעלות לבחינת ג״ר שבראש, ולהזדווג עם הגולגלתא מבחינת החכמה שבו. (כמ״ש שם עש״ה) אבל בז״א, הקרום שבראש שבין גלגלתא למוח שלו מתבטל בעת הזווג, ועולה המוח למעלה מקרום, ומתגלות הג״ר שבו. שאלו הג״ר הם חב״ד, והכלים הם ג׳ חללי גולגלתא. וז״ש, \u0003ג׳ חללין אשתכחו דשריא מוחא בהו,\u0004 דהיינו שמתבטל הקרום והמוח שהוא בבחינת מפרסא דראש ולמטה עולה למעלה מפרסא ונעשה לג״ר, שה״ס חב״ד, וז״ש, \u0003וקרומא דקיק חפייא עלייהו,\u0004 כי ע״כ יכלו להעשות ג\"ר, משום שהקרום המפסיק הוא דק, והוא כמו מתבטל בסוד הורדת הפרסא והמוח עולה ונעשה לג׳ מוחין חב״ד. \u0003אבל לא קרומא קשישא סתימא כעתיק יומין,\u0004 כי הקרום שלו אינו נפסק כנ״ל. וז״ש, \u0003ובגין דא האי מוחא אתפשט ונהיר לל״ב שבילין, הה״ד ונהר יוצא מעדן.\u0004 כי סוד ל״ב שבילין דחכמה, אינו עצם החכמה דאור ישר כמו מוח דא״א, אלא שהם בחינת בינה שחזרה לראש דא״א ונעשית לחכמה, שעליה כתוב, ונהר יוצא מעדן וגו׳, כי עי״ז שבינה זו יצאה מראש דא״א שנקרא עדן, שקבלה בתוכה המלכות דמדת הדין, ואח״כ חזרה ובאה לראש דא״א שנקרא עדן, נעשתה בינה זו לבחינת חכמה ומשפעת חכמה לז״א. ומשום שאינה עצם החכמה דאור ישר, ע״כ יכולה להתפשט לז״א, וע״כ אין קרום קשה על המוחין דז״א."],[1,"ותאנא בתלת חללין","וכו': ולמדנו, בשלשה חללים של הגולגלתא שורה המוח של ז״א, מחלל אחד, מתבקע מבוע אחד לד׳ צדדים, ויוצא ממוח ההוא השורה בחלל הזה, ל״ב שבילים של רוח החכמה."],[1,"","פירוש. אע״פ שג' מוחין דז״א שבחללי הגולגלתא, הם בחינת ישסו״ת שהוא \u0003ל׳\u0004 דצלם, שבו יוצאת ה \u0003י׳\u0004 מאויר, והחכמה מתגלה (כנ״ל אות קפ״א) עכ״ז גם ה \u0003ל׳\u0004 מבחינת עצמה מתחלקת ג״כ ל \u0003ם׳ ל׳ צ׳.\u0004 והיינו לפי סדר ג׳ קוין שבו, אשר הימין הוא בחינת \u0003ם׳\u0004 דצלם, והוא נקרא חכמה, והיא משום זה כבחינת או״א עלאין דהיינו בד׳ סטרין, חו״ב, וימין שבדעת ושמאל שבדעת. וקו שמאל שבו הוא כבחינת \u0003ל׳\u0004 דצלם, דהיינו כבחינת ישסו״ת עצמו, שיש בו ג׳ מוחין חב״ד שהימין ושמאל שבדעת הם אחד והוא נקרא בינה. וקו אמצעי, הוא \u0003צ׳\u0004 דצלם. וה״ס הדעת המיחדת ב׳ קוין חכמה ובינה זה בזה."],[1,"","ואע״פ שמוח הימין שבכאן שהוא חכמה דז״א, הוא \u0003ם׳\u0004 דצלם, כמו או״א עלאין, עכ״ז יש הפרש גדול ביניהם, כי או״א עלאין אין הי׳ יוצאת מאויר שלהם, והם בחינת חסדים, ואע״פ שישסו״ת מקבלים מהם חכמה, הנה החכמה שבהם רק בבחינת מעבר לבד. כי הם תמיד בבחינת חסדים. משא״כ הימין שבכאן שהוא בחינת ימין דישסו״ת, אע\"פ שיש לו יחס כמו ה \u0003ם׳\u0004 דצלם, עכ״ז הארת החכמה נפתחת בו כדי לקבל ולהשפיע לקו שמאל שהוא בינה דז״א, משמאל דישסו״ת, ו \u0003ל׳\u0004 דצלם. אמנם עכ״ז, הוא עצמו אינו משמש בהארת החכמה, להיותו קו ימין, וע״כ נחלק גם הוא לד׳ סטרין, כמו או״א עלאין. וז״ש \u0003מחללא חד מתבקע ומתפשט חד מבועא לד׳ סטרין,\u0004 דהיינו מחלל הימין שנקרא חכמה דישסו״ת, מתבקע, בבחינת הקטנות, ואח\"כ מתפשט, בבחינת הגדלות, \u0003מבוע אחד,\u0004 שהוא קו ימין, \u0003לד׳ סטרין,\u0004 שהם חכמה ובינה וימין דדעת ושמאל דדעת, משום שיש לו יחס ל \u0003ם׳\u0004 דצלם. כמבואר."],[1,"","ואלו ד׳ סטרין, חו״ב וימין ושמאל דדעת, חסרים מכתר וחכמה משום שחכמה זו המתגלה בו אינו אלא בינה שחזרה לחכמה (כנ״ל בדבור הסמוך ע״ש) וע״כ נבחן שאין בכל סטר רק שמונה ספירות בינה חג״ת נהי״מ, וד״פ שמונה הם ל״ב. וז״ש, \u0003ונפיק מההוא מוחא דשרייא בהאי חללא ל״ב שבילין רוחין דחכמתא.\u0004 כי המוח הזה השורה בחלל הימין הוא חכמה, אשר כתר וחכמה דאור ישר אין מגולה בו, להיותו כבחינת חכמה סתימאה דא״א, ואין בו אלא ל״ב שבילים שהחכמה מתגלה בהם, דהיינו מבינה ולמטה, שבד׳ סטרין, שבכל סטר רק ח׳ ספירות, והם ל״ב ספירות שרוח החכמה מתגלה בהם. והם הנקראים ל״ב שבילים."],[2,"מחללא תנייינא","וכו׳: מחלל השני. מתבקע ומתפשט מבוע אחד אחר, שה״ס קו שמאל, הנקרא בינה, ונפתחים נ׳ שערים. מאלו נ׳ שערים מתאחדים חמשים יום של התורה, דהיינו ביום החמשים לספירת העומר שבו ניתנה התורה חמשים שנים של יובל. חמשים אלף דורות שעתיד הקב״ה להשיב רוחו בהם, ולשרות בהם."],[2,"","פירוש החלל השני הוא בינה דז״א, ובחינת קו שמאל דישסו״ת, שבה עצם גילוי הארת החכמה, שיש לה יחס של \u0003ל׳\u0004 ד \u0003ל׳\u0004 דצלם כנ״ל בסמוך, כי היא עצם הבינה שחזרה לחכמה, המקבלת מל״ב נתיבות החכמה הנ״ל בסמוך, ובשביל ששיעור החכמה המתגלית היא רק ו״ק דחכמה, אין לה אלא מחסד ולמטה, ומשום שבינה עד הוד אתפשטותה ואין בה יסוד ומלכות, ע״כ נבחנת לה׳ ספירות שבכל אחת עשר ספירות, שזה מורה על ו״ק דג״ר, וה' פעמים עשר ה״ס נ׳ שערים. וה״ס חמשים יום של מתן תורה, ושל יובל, ושל נ׳ אלף דורות, שכל אלו רומזים על שיעור החכמה הנגלה בישסו״ת."],[2,"","והבן ההפרש בין חכמה דז״א לבינה דז״א, כי החכמה דז״א שבחלל הימני, להיותה רק בבחינת פתיחת החכמה להשפעה, ואין בו שום מדובר מבחינת קבלה לעצמו, כנ״ל בדבור הסמוך, ע״כ מבינה ולמטה שבו נחשב לשבילי החכמה, ואע״פ שבינה היא ג״ר מ״מ מבחינת פתיחת החכמה נפתחים גם הג״ר דחכמה. ואינה נסתרת אלא מחכמה דאור ישר בלבד, להיותו נסתמה במו״ס דא״א. משא״כ הבינה ח״א שבחלל השמאלי דגולגלתא. להיות החכמה בה בבחינת הקבלה, ע״כ אין בה אלא נ׳ שערים, דהיינו מחסד ולמטה, ואפילו הבינה אינה מגולה בה, כי בינה בחינת ג\"ר היא, והג״ר דחכמה אינם מקובלים משום הכרעת קו האמצעי, כנודע, וע״כ אין בה מהארת החכמה אלא ו״ק שהם מחסד ולמטה בלבד."],[3,"מחללא תליתאה","וכו׳: מהחלל השלישי, יוצאים אלף אלפים חדרים ואכסדראות שהדעת שורה עליהם ודרה בהם. וחלל זה משים מדורו בין חלל לחלל, כלומר שהוא חלל אמצעי בין חלל הימין וחלל השמאל, וכל אלו חדרים מתמלאים מב׳ צדדים, מימין ומשמאל, ז״ש, ובדעת חדרים ימלאו. ואלו ג׳ חללים שהם חב״ד, מתפשטים בכל הגוף לצד זה ולצד זה ובהם נאחז כל הגוף, והגוף נאחז מהם מכל הצדדים שלהם. ובכל הגוף הם מתפשטים ונמצאים."],[3,"","פירוש. החלל השלישי הוא מוח הדעת דז״א, הנמשך מקו אמצעי דישסו״ת, שה״ס \u0003צ׳\u0004 ד \u0003ל'\u0004 דצל״ם, שבו עיקר הגילוי של החכמה, והוא המיחד ב׳ החללים שהם חכמה ובינה דז״א. וז״ש, \u0003והאי חללא שרי מדוריה בין האי חללא ובין האי חללא,\u0004 דהיינו הקו האמצעי המיחד אותם, וכלול מב׳ סטרין, דהיינו מחסדים ומחכמה. וז״ש, \u0003מחללא תליתאה נפקין אלף אלפין אדרין ואכסדראין,\u0004 שדעת זו מתפשטת ג״כ לגוף שחג״ת שבו נקראים \u0003אדרין,\u0004 ונה״י שבו נקראים \u0003אכסדרין.\u0004 ומספר \u0003אלף אלפים,\u0004 מורה על המשכת החכמה ע״י הדעת הזו, כי החכמה מכונה אלפים, בסוד ואאלפך חכמה, וכשהדעת ממשיכה, נבחנה הדעת בבחינת אלף אלפין. \u0003אדרין\u0004 פירושו חדרים, שהרי מביא ראיה על מילוי האדרין, מכתוב ובדעת \u0003חדרים\u0004 ימלאו."],[4,"תאנא בגולגלתא דרישא","וכו׳: למדנו, בגלגלת הראש דז״א, תלוים אלף אלפי רבוא ורבוא רבבות קווצות שערות שחורות, ומסתבכות זו בזו, ומתערבות זו בזו. ואין חשבון אל הנימין האחוזים בכל קווצה וקווצה של השערות, משום שהן טהורות וטמאות. ומכאן נאחזים טעמי התורה בטומאה וטהרה, בכל אלו הצדדים שהם טהורים ובכל אלו הצדדים שהם טמאים."],[5,"יתבין קוצי מסתבכין","וכו׳: קווצות השערות יושבות על הגלגלתא דז״א, ומסתבכות זו בזו, והן חזקות, מהן רכות ומהן קשות. ובכל קווצה וקווצה יושבים נימי שערות תלי תלים, מתלהטות ותלויות כגבור אמיץ בעל נצחון המלחמות, בתקון נאה, בתקון יפה ואמיץ, גדולות וקשות. ז״ש בחור כארזים."],[6,"מתתקנין קוצין דשערי","וכו׳: מתתקנות קווצות השערות, ותלויות תלי תלים מצד זה לצד זה על הגולגלתא. ז״ש קווצותיו תלתלים. ולמדנו, שיושבות תלי תלים, משום שנמשכות ממבועים רבים של ג׳ קבוצות המוחין, ממבוע חלל הא׳ דגולגלתא, שהוא חכמה דז״א, נמשכות שערות בהמשכה ונעשות תלים התלויות מכמה מבועים הנמשכים מחלל הזה. מחלל השני, שהוא בינה דז״א, יוצאים חמשים מבועים, והשערות נמשכות מאלו המבועים בהמשכה, ונעשות תלים התלויות ומתערבות בקווצות אחרות. מחלל הג', יוצאים אלף אלפים אדרין ואכסדראין, ונמשכות השערות בהמשכות מכולם. ומשום זה אלו הקווצות תלים על תלים."],[7,"וכלהו משיכן דאתמשכן","וכו׳: וכל המשכות שנמשכו מג׳ חללים של מוח הגלגלת, וכל אלו נימי השערות, וכל אלו הקווצות, תלויות ומכסות לצד האזנים, ומשום זה כתוב, הטה אלהי אזנך ושמע. ובתלים אלו תלוים ימין ושמאל, אור וחושך, רחמים ודין. וכל בחינות ימין ושמאל תלוים בזה, בז״א, ולא בעתיק, שהוא א״א."],[7,"","ביאור המאמר. תחילה צריכים להבין עצם השערות מה הן, ומה הם הדינים שבהן, ומאין התקון שבהן. והנה \u0003העצמות\u0004 שבהן, הן ממה שהיו פעם כלים לג״ר דחכמה שבשמאל. \u0003והדינים\u0004 שבהן, באים גם כאן מקרומא דאוירא כמו בא״א, אלא כאן נבחן הקרום הזה, בבחינת קרום דק שעל המוחין. והדינים שבהם הם ב׳ בחינות, א) דינים דנוקבא הבאים מן הקרום שעל המוחין. ב) דינים דדכורא, הבאים מהארת הג״ר דקו שמאל. \u0003והתקון\u0004 שבהם, נמשך מג׳ חללי גלגלתא דהיינו מחב״ד שבהם."],[7,"","וז״ש, \u0003בגולגלתא דרישא תליין אלף אלפי רבוא ורבוא רבוון קוצי דשערי אוכמן.\u0004 המדרגות דחכמה הנמשכות מן השערות ראש בדרך כללות שבהם, נרמזות בחשבון אלף אלפין רבוא, ומדרגות החסדים הנמשכות מהן נרמזים בחשבון רבוא רבבן. ואומר שהן שחורות. והוא משום שיש ב׳ בחינות דינין דנוקבא בשערות דז״א, שהם ממלכות הממותקת בבינה, וממלכות עצמה דמדת הדין וגוון הנמשך מן המלכות עצמה הוא שחור. וגוון הנמשך ממלכות הממותקת בבינה, הוא אדום. ומטעם זה שערות המלכות הן אדומות. כי אין בהן כלום ממלכות דמדת הדין כמו שיש בז״א. כמ״ש במקומו, וז״ש, \u0003ומסתבכין דא בדא ומתערבין דא בדא,\u0004 שאלו ב׳ בחינות דינין דנוקבי הן מתערבות זו בזו ומסתבכות זו בזו."],[7,"","וכדי להבין היטב דברי הזהר וכפילת הלשון ג׳ פעמים בזה אחר זה, הבא באותיות קצ״ג קצ״ד וקצ״ה, צריכים להאריך קצת באלו שערות דז״א. ויש לדעת שיש בז״א ג׳ פרצופין מלובשים זה בתוך זה, שנקראים, פרצוף חב״ד, פרצוף חג״ת, פרצוף נה״י, שהם בחינות נשמה, רוח, נפש דז״א. וכל אחד מלביש מחזה ולמטה של עליונו. ובדרך כלל כשמלובשים זה בזה, הם כולם כמו פרצוף אחד, אשר הגלגלתא דפרצוף נה״י, שהוא נפש דז״א, מתחלת מחזה ולמטה דפרצוף הכולל. והגלגלתא דפרצוף חג״ת, שהוא רוח דז״א, מתחלת מגרון ולמטה דפרצוף הכולל. וע״כ לא נראה מפרצוף חב״ד שהיא נשמה דז״א, אלא הראש שלו בלבד."],[7,"","וע״כ יש כאן ג׳ בחינות שערות, הנקראות, קוצין, נימין, ושערות. כי יש שערות מפרצוף נה״י, ויש שערות מפרצוף חג״ת, ויש שערות מפרצוף חב״ד. וכולן מתקבצות בגלגלתא דפרצוף חב״ד, וע״כ השערות דפרצוף נה״י אשר שם ארוכות עד החזה, ששם הגלגלתא דפרצוף נה״י, והן נקראות \u0003קוצין.\u0004 והשערות דפרצוף חג״ת אשר שם, ארוכות עד הגרון בלבד, ששם הגלגלתא דפרצוף חג״ת, והן נקראות \u0003נימין.\u0004 והשערות דפרצוף חב״ד יושבות על הגלגלתא בלבדה, ואינן נמשכות למטה, כי הן שייכות לראש המגולה שהוא מפרצוף חב״ד בלבד, ואינן צריכות להשפיע לזולתו. ונקראות \u0003שערות.\u0004 ואע״פ שכולן נכללות זו מזו, כמו הע״ס שנכללות זו מזו, ויש קוצין ונימין ושערות אפילו מפרצוף נה״י, וכן מחג״ת וכן בחב״ד. אמנם המדובר הוא לפי השליטה. כי בפרצוף נה״י שולטות \u0003הקוצין,\u0004 ובפרצוף חג״ת שולטות \u0003הנימין,\u0004 ובפרצוף חב״ד שולטות \u0003השערות.\u0004"],[7,"","ובזה תבין כפילות הדברים שבג׳ אותיות הנ״ל. כי באות קצ״ג, מבאר השערות דפרצוף נה״י דז״א העומד מחזה ולמטה דפרצוף הכולל, ששם שולטות \u0003הקוצין,\u0004 וז״ש שם \u0003בגולגלתא דרישא תליין,\u0004 כלומר שהן ארוכות ותלויות למטה עד החזה דפרצוף הכולל. וז״ש, \u0003ולית חושבנא לנימין דכל קוצא וקוצא,\u0004 כלומר שאין שם הארת חכמה הנקראת \u0003חשבון\u0004 (כנ״ל פקודי אות כ״ח) והוא מטעם, \u0003דאחידן ביה דכיין ומסאבן,\u0004 כי להיותן מבחינת מחזה ולמטה, ובחזה דז״א נמצאות ב׳ מלכיות, הנמתקת והבלתי נמתקת, שכחן מתחיל רק למטה ממקום מציאותן, אשר מהמלכות הממותקת נמשכות בחינות דינין טהורים, ומהמלכות הבלתי נמתקת נמשכות דינין טמאים. וז״ש, \u0003ומכאן אתאחדן טעמי אורייתא בדכיא במסאבא,\u0004 שטעמי התורה של טומאה וטהרה נמשכים מן הנימין שבקוצין אלו. כי הכל הוא לפי מעשה התחתונים."],[7,"","ובאות קצ״ד, מבאר השערות דפרצוף חג״ת דז״א העומד מגרון ולמטה דפרצוף הכולל, ששם שולטים \u0003הנימין.\u0004 וז״ש שם \u0003יתבין קוצי,\u0004 כלומר שאינן תלויות כנ״ל בפרצוף נה״י שהן תלויות עד החזה, אלא כאן בפרצוף חג״ת, הן יושבות, כי הן קצרות, ואינן נמשכות רק עד הגרון. דהיינו עד הגלגלתא של פרצוף הזה. וע״כ של נה״י מכונות \u0003תליין.\u0004 ושל חג״ת מכונות \u0003יתבין.\u0004 וז\"ש, \u0003מסתבכין ותקיפין,\u0004 כי ב׳ מלכיות הנ״ל, מעורבות בהם אשר בחטאי התחתונים \u0003מסתבכות\u0004 זו בזו, וכן הן \u0003תקיפין,\u0004 מטעם דינין דדכורא השולטים בהם, אמנם להיותם למעלה מחזה דפרצוף הכולל, שהוא למעלה ממקום מציאות המלכות הבלתי נמתקת, ואין שום עוביות יכולה לפעול למעלה ממציאותו, ע״כ אע״פ שמסתבכות זו בזו, אין טומאה נמשכת מהם כלל, אלא הם טהורים, ורק \u0003מנהון שעיעין, ומנהון תקיפין,\u0004 דהיינו, מהם רכות, שאין בהם דינין דדכורא, ומהם קשות, שיש בהם דינים דדכורא. ולפי שאומר בתחילה שיושבים על הגלגלתא, אפשר לטעות שאינן נמשכות כלום למטה, כמו השערות דפרצוף חב״ד, ע״כ אומר, \u0003מתלהטן ותליין,\u0004 שהן תלויות מעט למטה, דהיינו עד הגרון ששם הגולגלתא דפרצוף הזה. \u0003כגיבר תקיף מארי נצח קרבין,\u0004 דהיינו שהדינים שבהן לוהטות עד שמנצח המלחמות עם הסטרא אחרא הרוצה לינק מהארת חכמה שבהן, וז״ש \u0003בתקונא יאה בתקונא שפירא תקיפא.\u0004 כלומר, אע״פ שהן קשות המורה על הדינים שבו, מ״מ הוא תקון נאה ויפה ותקיף לדחות החצונים, וז״ש \u0003רברבין ותקיפין,\u0004 שמצד אחד הן \u0003גדולות\u0004 שזה מורה על הארת חכמה שבהם, ומצד אחד הן \u0003קשות,\u0004 שזה מורה על הדינין דדכורא שבהן המיועדים להבריח החצונים, וז״ש \u0003הה״ד בחור כארזים.\u0004 כי הן מפרצוף רוח, ופרצוף רוח מכונה \u0003בחור,\u0004 להיותו מוחין דו״ק וקטנות."],[7,"","ובאות קצ״ה, מבאר השערות דפרצוף חב״ד דז״א, שלא נראה ממנו אלא הראש בלבד, שבו שולטות \u0003השערות.\u0004 וז״ש, \u0003מתתקנין קוצין דשערי,\u0004 כי כל התקון של השערות בא מג׳ מוחין חב״ד, כנ״ל, וע״כ אומר בפרצוף הזה \u0003מתתקנין,\u0004 וז״ש, \u0003ותליין תלין על תלין מהאי סטרא להאי סטרא על גולגלתא.\u0004 להורות שבו מתיחדים הימין והשמאל זה בזה, משא״כ בפרצוף חג״ת היתה שליטת השמאל, מטרם שנכלל עם הימין. ומוסיף כאן המלה \u0003על גולגלתא,\u0004 להורות ששורשם מפרצוף חב״ד שגלגלתא דפרציף הכולל הוא שלו. וז״ש, \u0003ותאנא יתבין תלי תלין,\u0004 דהיינו כיון שאמר מקודם לכן \u0003ותליין,\u0004 מזכיר לשון הברייתא שאינו כן, אלא \u0003יתבין,\u0004 דהיינו שאינן נמשכות מגלגלתא ולמטה, כי מקומם הוא בחב״ד, ואינן צריכים להמשך לפרצוף אחר כמו הקודמים. וז״ש \u0003משום דמשיכין ממבועין סגיאין דתלת רהטי מוחא,\u0004 דהיינו שהן נמשכות מפרצוף חב״ד שבג׳ חללי גולגלתא, וז״ש \u0003אתמשכן שערי\u0004 וכו׳ \u0003מהאי חללא,\u0004 דהיינו מחלל הא׳ הימני, שהוא חכמה דז״א, המתפשט לל״ב נתיבות החכמה. שכל נתיב הוא מבוע שנמשכות שערות ממנו. וע״כ הן תלי תלים. \u0003מחללא תניינא,\u0004 שהוא בינה דז״א, שבו חמשים שערי בינה \u0003נפקי חמשין מבועין\u0004 וכו', שכל שער נעשה למבוע. \u0003ואתעבדין תלין דתלין ומתערבין בקוצין אחרנין.\u0004 כי תלי תלים השערות האלה מתערבות עם אלו שבפרצוף חג\"ת, וע״כ נעשו שם גם שערות שעיעין משא״כ שערות הקודמות הנמשכות מחלל א׳ הן רק לגולגלתא לבד, ואינן מתערבות באחרות. \u0003מחללא תליתאה,\u0004 שהוא דעת דז״א, \u0003נפקי אלף\u0004 וכו' \u0003ואתמשכן שערי במשיכותא מכלהו\u0004 וכו', וע״כ הם תלי תלים. \u0003וכלהו,\u0004 כל השערות, \u0003משיכן דאתמשכן מג׳ חללין דמוחא דגלגלתא.\u0004 כי כל השערות דג׳ פרצופין כלולים זו מזו, וע״כ מקבלים כולם מחב״ד, שבפרצוף הג'. אשר פרצוף נה״י, מקבל מחלל הג׳ שהוא דעת. ופרצוף חג״ת, מחלל הב׳ שהוא בינה. ופרצוף חב״ד מחלל הא׳ שהוא חכמה."],[8,"בפלגותא דשערי אתחזי","וכו׳: בהתחלקות השער לימין ושמאל, נראה ארח דק אחד באמצע, הנאחז מאותו ארח עתיק יומין (הנ״ל באות ל״ג) שהוא בחינת קו האמצעי שבשערות, הכלול מימין ומשמאל, ואינו נוטה לא לימין ולא לשמאל, (כמ״ש שם) ומארח זה שבז״א, מתחלקים תרי״ג ארחות המתחלקות בדרכי מצות התורה. כלומר שכל מצוה ומצוה מתרי״ג מצות שבתורה, נמשכת מקו אמצעי ההוא שבין שערות דז״א שכתוב, כל ארחות ה׳ חסד ואמת לנוצרי בריתו ועדותיו."],[9,"תנא בכל קוצא","וכו׳: למדנו, בכל קווצה וקווצה מתאחזים אלף אלפין בעלי יבבה ויללה, התלוים בכל קווצה וקווצה מאלו שערות הקשים. ומאלו הרכים, נמשכים בעלי מתקלא, דהיינו ההולכים בקו האמצעי משום זה יש ימין ויש שמאל בשערות."],[9,"","פירוש כי מובא לעיל (באות קצ״ד) המדבר מבחינת השערות דפרצוף חג״ת, ושהוא מקבל ממוח השמאל דא״א שהוא בינה כמ״ש בסולם באות קל״ג בסופו, מובא, \u0003שמנהון שעיעין ומנהון תקיפין,\u0004 ומפרש כאן, כי \u0003התקיפין\u0004 הם משערות דשמאל לבד, שאינם מיוחדים בימין בכח קו האמצעי. \u0003והשעיעין,\u0004 הן שערות דשמאל המיוחדים בימין, בכח קו האמצעי. וז״ש, \u0003מתאחדן\u0004 וכו׳ \u0003מארי דיבבה ויללה\u0004 וכו' \u0003מאינון תקיפין,\u0004 שהם שמאל דשערות. \u0003ומאינון שעיעין,\u0004 המיוחדים בימין, הם בעלי מתקלא, דהיינו הדבוקים בקו אמצעי. \u0003בג״כ אית ימינא ואית שמאלא,\u0004 בשערות. אשר הדבוקים בשמאל מכונים מארי דיבבה ויללה, מרוב הדינים אשר שמה, וה״ס שערות הקשים שבשמאל. והדבוקים בקו אמצעי, מכונים מארי מתקלא ומבחינתם השערות רכות וכלולים בימין. והם רחמים."],[10,"מצחא דגולגלתא אשגחותא","וכו׳: מצח הגלגלת. הוא השגחה דהשגחה. ואינו מתגלה חוץ מבעת ההוא שהרשעים צריכים להפקד, וצריכים לעיין במעשיהם. ולמדנו, כשמתגלה המצח הזה דז״א, מתעוררים כל בעלי הדין, וכל העולם נמסר בדין. חוץ משעה ההיא כשעולות תפלות ישראל לפני עתיק יומין, ורוצה לרחם על בניו, מגלה המצח שלו שנקרא רעוא דרעוין, ומאיר במצח הזה דזעיר אנפין, והדין נשקט."],[10,"","כבר ידעת סוד גלגלתא והפנים, שדגלגלת ה\"ס \u0003ם׳\u0004 דצלם שה \u0003י'\u0004 אינה יוצאת מאויר אשר בה, וע״כ השערות שמקורם הוא אותה ה \u0003י׳\u0004 שנכנסה באויר, אינם נפרדים משם לעולם. והפנים ה״ס \u0003ל׳\u0004 דצלם, שבו יוצאת ה \u0003י׳\u0004 מאויר והחכמה מתגלה שם, ע״כ אין מקום שם לשערות. וכל הפנים פנוים משערות. (כנ״ל אות ל״ט) אמנם נודע שאפילו במקום שמתגלה החכמה היא רק ו״ק דחכמה, המאירה ממטה למעלה. ולא בחינת ג״ר דחכמה. ולפיכך נחלקים גם הפנים לג״ר וו״ק, שה״ס מצח ועינים, אשר במצח גנוז החכמה, ואסור להמשיך משם חכמה, כי להיות המצח ג״ר דפנים, הרי כל הנמשך ממנו הוא ג״ר, אלא מו\"ק דחכמה, שה״ס העינים, משם מותר להמשיך כל הכדאי לה. ולפיכך נמשכים ממצח דינים קשים לכל הממשיכים חכמה. אמנם אי אפשר להמשיך ו\"ק דחכמה בלי ג״ר, וע״כ בעת הזווג מתגלה ג״כ הג״ר דחכמה במצח, אבל ביחד עם דינים קשים לענוש הרשעים הרוצים להתקרב לינק משם, עד שנגנזו הג״ר דחכמה, ונשארה בחינת ו״ק דחכמה. שה״ס העינים, כמ״ש לפנינו."],[10,"","וז״ש \u0003מצחא דגולגלתא אשגחותא דאשגחותא,\u0004 אשגחותא ה״ס הארת חכמה, כי חכמה נקראת השגחה וראיה. אבל הוא השורש אל השגחה, כי השגחה מקובלת רק מעינים, שהן בחינות ו״ק דחכמה, והמצח שהוא מקום גילוי ג״ר דהשגחה, אינו מאיר רק לבחינת שורש להשגחה בלבד, מטעם שאי אפשר שיצאו ו״ק בלי ג\"ר, אבל כל הרשעים הרוצים להתקרב ולינק בעת גילוי המצח, הם נדונים בדינים קשים ממנו. והנה כל עוד שנמצאים רשעים שירצו לינק מן הג״ר דחכמה, גם הו\"ק דחכמה אינן יכולים להתגלות, כי יש פחד שלא יתדבקו בו\"ק אלו, ויעוררו גם שם המשכת החכמה ממעלה למטה. וע״כ מגלה ז״א המצח שלו, בהארת ג״ר, אשר אז מתקרבים תיכף כל הרשעים לינק ממנו והדינים קשים דמצח מכלה ומשבית אותם, ואז יכולים הו״ק דחכמה להתגלות. וז״ש, \u0003ולא מתגלייא בר ההוא זמנא דצריכין חייביא לאתפקדא ולעיינא בעובדיהון,\u0004 דהיינו כדי לכלות הדינים בהם, ויהיו הו״ק דחכמה משומרים. וז״ש, \u0003כד אתגלייא האי מצחא,\u0004 דהיינו כשמתגלים בו ג״ר דחכמה, \u0003אתערו כל מאריהון דדינא,\u0004 לייסר הרשעים כנ״ל. \u0003וכל עלמא בדינא אתמסר.\u0004 מחמת שליטת הדינים ההם."],[10,"","וכל זה במצח דז״א אבל במצח דא״א כשמתגלה שם הג״ר דחכמה אין שום דינים, מחמת שפגם התחתונים אינו מגיע כלום לא״א, שאין אחיזה לתחתונים רק בז״א, ולא למעלה ממנו, ולא עוד אלא שם בא״א ה״ס \u0003רעוא דרעוין\u0004 (כמ״ש באות ל״ד) וע״כ במנחת שבת, שז״א עולה לא״א, והמצח שלו מקבל מא״א, נשקט הדין במצח דז״א, כי התחתון העולה לעליון הרי הוא כמוהו, וז״ש \u0003בר ההיא שעתא\u0004 וכו' \u0003גלי מצחא דרעוא דרעוין ונהיר בהאי דז״א ואשתכיך דינא.\u0004 וכיון ששורש החכמה שבמצח דז״א נתעלה כל כך, דהיינו בבחינת רעוא דרעוין, נמשכת הארה גדולה אל המצח, משליטת הימין, והדינים נשקטים."]],[]],[["בְּהַאי מִצְחָא, נָפִיק חַד (פקודי רל\"ז ע\"ב) שַׂעֲרָא, דְּמִתְפְּשָׁט בֵּיהּ מִמּוֹחָא דְּאַפִּיק חַמְשִׁין תַּרְעִין. וְכַד אִתְפְּשָׁט, אִתְעֲבִיד מִצְחָא דְּאַשְׁגָּחוּתָא, לְחַיָּיבֵי עָלְמָא, לְאִינּוּן דְּלָא מִתְכַּסְּפֵי בְּעוֹבָדֵיהוֹן. הֲדָא הוּא דִכְתִיב, (ירמיהו ג׳:ג׳) וּמֵצַח אִשָּׁה זוֹנָה הָיָה לָךְ מֵאַנְתְּ הִכָּלֵם.","וְתַנְיָא, שַׂעֲרָא לָא קָאִים בְּהַאי אֲתָר דְּמִצְחָא, בְּגִין דְּאִתְגַּלְיָיא לְאִינּוּן דְּחַצִּיפִין בְּחוֹבַיְיהוּ. וְשַׁעֲתָא דְּמִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא, נְהִירִין אַנְפּוֹהִי דְּעַתִּיק יוֹמִין, בְּאַנְפּוֹי דִּזְעֵיר אַפִּין, וּמִתְגַּלְיָא מִצְחֵיהּ, וְנָהִיר לְהַאי מִצְחָא, וּכְדֵין אִתְקְרֵי עֵת רָצוֹן. וְכָל שַׁעֲתָא וְשַׁעֲתָא דְּדִינָא תָּלֵי, וְהַאי מִצְחָא דִּזְעֵיר אַפִּין אִתְגַּלְיָיא, אִתְגַּלְיָיא מִצְחָא דְּעַתִּיקָא דְּעַתִּיקִין, וְאִשְׁתְּכִיךְ דִּינָא, וְלָא אִתְעָבִיד.","תָּאנָא, הַאי מִצְחָא, אִתְפָּשָׁט בְּמָאתָן אֶלֶף סוּמָקֵי דְּסוּמָקֵי, דְּאִתְאַחֲדָן בֵּיהּ, וּכְלִילָן בֵּיהּ. וְכַד אִתְגַּלְיָיא מִצְחָא דִּזְעֵיר אַפִּין, אִית רְשׁוּתָא לְכֻלְּהוּ לְחַרָבָּא. וְכַד אִתְגַּלְיָיא מִצְחָא דְּרַעֲוָא דְּרַעֲוִין, דְּנָהִיר לְהַאי מִצְחָא, כְּדֵין כֻּלְּהוּ מִשְׁתַּכְכִין. (קכ\"ט, רל\"ג)","וְתַנְיָא, עֶשְׂרִין וְאַרְבַּע בָּתֵּי דִּינִין מִשְׁתַּכְּחִין בְּהַאי מִצְחָא, וְכֻלְּהוּ אִקְרוּן נֶצַח (ס\"א מצחא וכל חד אקרי נצח). וּבְאַתְוָון (דאפין) רְצוּפִין, הוּא מֶצַח. וְאִית נֶצַח דְּאִינּוּן נְצָחִים. וְהַיְינוּ דִּתְנָן נֶצַח נְצָחִים. וְאִינּוּן בְּמִצְחָא, וּמִתְפַּשְּׁטָן מִנְּהוֹן בְּגוּפָא, בְּאַתְרִין יְדִיעָן.","תַּנְיָא, מַאי דִּכְתִּיב, (שמואל א ט״ו:כ״ט) וְגַם נֵצַח יִשְׂרָאֵל לֹא יְשַׁקֵּר וְלֹא יִנָּחֵם כִּי לֹא אָדָם הוּא לְהִנָּחֵם. הַאי רָזָא אוֹקִימְנָא, כָּל הַהוּא נֶצַח דְּאִתְפְּשַׁט בְּגוּפָא, זִמְנִין דְּתָלֵי עַל עָלְמָא לְמֵידָן, וְתָב וּמִתְחָרֵט וְלָא עָבִיד דִּינָא, אִי תַּיְיבִין. מַאי טַעְמָא. מִשּׁוּם דְּקָאֵי בְּדוּכְתָּא דְּאִקְרֵי אָדָם, וְיָכִיל לְאִתְחָרְטָא. אֲבָל אִי בְּאֲתָר דְּאִתְקְרֵי רֹאשׁ, (בהאי מצחא) אִתְחֲזֵי וְאִתְגַּלְיָיא הַאי נֶצַח, לָאו הוּא עִידָּן וַאֲתָר לְאִתְחָרְטָא. מַאי טַעְמָא. מִשּׁוּם דְּלָא הֲוָה מֵאֲתָר דְּאִקְרֵי אָדָם, דְּהָא לָא אִתְגְּלֵי פַּרְצוּפָא וְחוֹטָמָא, אֶלָּא מִצְחָא בִּלְחוֹדוֹי. וּבַאֲתָר דְּלָא אִשְׁתְּכַח פַּרְצוּפָא, לָא אִקְרֵי אָדָם. וּבְגִין כָּךְ לֹא אָדָם הוּא לְהִנָּחֵם כְּנֶצַח דְּבִשְׁאַר תִּקּוּנֵי גּוּפָא.","עֵינוֹי דְּרֵישָׁא, מִשְׁתַּנְיָין מִשְּׁאָר עַיְינִין, שְׂרִקוּתָא דִּבְגַּבְתָּא, דְּעַל רִיסֵי עַיְינִין, מְכַּחֲלָן (דכל עיינין מכחלן) בְּאוּכָּמֻתָא, תַּלְיָין תִּלִּין עַל תִּלִּין דְּשַׂעְרֵי, וְאִינּוּן תִּקּוּנָא דְּעַל עַיְינִין, בְּרֵישָׁא דְּמִצְחָא, וּמִתְאַחֲדָן מִתַּרְוַויְיהוּ שֶׁבַע מְאָה אַלְפֵי מָארֵי דְּאַשְׁגָּחוּתָא. (דעל תריסי דעיינין)","בִּכְסוּתָא דְּעַיְינִין, לַהֲטִין אֶלֶף וְאַרְבַּע מְאָה רִבּוֹא, דְּמִתְאַחֲדָן בִּגְבִינִין דְּאִינְהוּ כְּסוּתָא. וְאַשְׁגָחוּתָא דְּעֵינָא דְּעַתִּיק יוֹמִין עָלַיְיהוּ. וּבְשַׁעֲתָא דְּסַלְּקִין אִינּוּן כְּסוּתָא, אִתְחֲזֵי כְּמַאן דְּאִתְּעַר מִשְּׁנָתֵיהּ, וְאִתְפַּקְּחָן עֵינוֹי, וְחָמָאן לְעֵינָא פְּקִיחָא, וְאִתְסָחָן בְּחַד חִוָּורָא דְּעֵינָא טָבָא, הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:י״ב) רוֹחֲצוֹת בֶּחָלָב. מַאי בֶּחָלָב. בְּחִוָּורָא דִּלְעֵילָּא קַדְמָאָה (נ\"א בחוורא קדמאה דעינא טבא). וּבְהַהִיא שַׁעֲתָא אִשְׁתְּכַח אַשְׁגָּחוּתָא דְּרַחֲמֵי. (ס\"א ובגין כך צלותא דישראל סלקא בגין דיפקח עינוי, ויתסחון בההוא חוורא)","וְעַל דָּא צַלֵּי דָּוִד, (תהילים מ״ד:כ״ד) עוּרָה לָמָּה תִּישָׁן יְיָ הָקִיצָה. דְּיִפְקַח עֵינוֹי, וְיִתְסָחוּן בְּהַהוּא חִוָּורָא. וְכָל זִימְנָא דְּעֵינוֹי לָאו מִתְפַּקְחָן, כָּל מָארֵיהוֹן דְּדִינִין, כַּפְיָין לְהוּ לְיִשְׂרָאֵל, וּשְׁאַר עַמִּין שַׁלְטִין עָלַיְיהוּ. וּבְזִמְנָא דְּיִפְקַח עֵינוֹי, יִתְסָחָן בְּעֵינָא טָבָא, וְרַחֲמֵי עַל יִשְׂרָאֵל. וְאִסְתְּחַר (ס\"א ואתזהר) עֵינָא, וְעָבִיד נוּקְמִין בִּשְׁאַר עַמִּין. הֲדָא הוּא דִכְתִיב, (תהילים ל״ה:כ״ג) הָעִירָה וְהָקִיצָה. הָעִירָה: לְאִתְסָחָאָה בְּהַהִיא חִוָּורָא. הָקִיצָה: לְמֶעְבַּד נוּקְמִין לְאִינּוּן דְּכַפְיָין לוֹן.","עֵינוֹי כַּד אִתְפַּקְחָן, אִתְחָזוּן שַׁפִּירִין כְּהָנֵי יוֹנִים, בְּסוּמָק וְאוּכָם וְיָרוֹק, חִוָּור לָא אִתְגְּלֵי, אֶלָּא בְּזִמְנָא דְּאִסְתָּכַּל בְּעֵינָא טָבָא, וּמִסְתְּחָאן כָּל אִינּוּן גַּוְונִין, בְּהַהוּא חִוָּור.","מֵאִינּוּן גַּוְונִין דְּמִתְגַּלְּיָין, נָפְקִין שִׁבְעָה עַיְינִין דְּאַשְׁגָּחוּתָא. דְּנַפְקֵי מֵאוּכָמָא דְּעֵינָא. הֲדָא הוּא דִכְתִיב, (זכריה ג׳:ט׳) עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם. מַאן אֶבֶן אַחַת. אוּכָמֻתָא דְּעֵינָא."],[[0,"בהאי מצחא נפיק","וכו׳: במצח הזה יוצא שער אחד שמתפשט בו ממוח שהוציא חמשים שערים, דהיינו המוח שהוא בחלל הב׳ דגולגלתא דז״א. שהוא בינה, וכשהשער מתפשט על המצח דז״א, הוא נעשה מצח השגחה לרשעי עולם, כי מקור הדינים שבג״ר דחכמה היא בחלל השמאלי דז״א, והשער המתפשט משם מושך הדינים אל המצח להעניש הרשעים שרוצים לינק מג\"ר שלו, לאותם שאינם מתביישים במעשיהם ז״ש, ומצח אשה זונה היה לך מאנת הכלם."],[1,"ותניא שערא לא","וכו׳: ולמדנו שערות אינן עומדות במקום ההוא של המצח, משום שהמצח מתגלה לאותם המחוצפים בעונותיהם. ובשעה שמתעורר הקב״ה להשתעשע עם הצדיקים מאירים הפנים של עתיק יומין בפנים של ז״א ומתגלה מצחו של א״א, ומאיר לההוא מצח דז״א, ואז נקרא עת רצון. וכל שעה ושעה שהדין תולה ומצח דז״א מתגלה, מתגלה המצח דעתיק דעתיקין והדין נשקט ואינו נעשה."],[1,"","פירוש. גילוי המצח פירושו יציאת הי׳ מאויר, שמתגלה אור החכמה. והצדיקים אינם ממשיכים מאור הזה כלום להיותו ג״ר דחכמה שאסור להמשיך, אלא הרשעים הדבוקים בס״א הם מתקרבים להמשיך מחכמה הזו. ואז הם נענשים כנ״ל. וז״ש, \u0003שערא לא קאים בהאי אתר דמצחא,\u0004 כי מקור השערות הוא ה \u0003י׳\u0004 שנכנסה באויר, ומשום זה אינן במצח, \u0003בגין דאתגלייא לאינון דחציפין בחובייהו,\u0004 כלומר בשביל שיצאה הי׳ מאויר, ונתגלה לרשעים, כי הצדיקים אינם משתמשים בו כנ״ל, ומתוך שאין הי׳ קבועה באויר, כמו בגלגלתא, ע״כ אין שם שערות. ומפרש, שיש זמן שגם הצדיקים משתמשים בגילוי המצח, וז״ש, \u0003ושעתא דמתער קב״ה לאשתעשעא עם צדיקיא נהירין אנפוהי דעתיק יומין\u0004 וכו׳ \u0003וכדין אקרי עת רצון.\u0004 כי בעת שמצח ופנים דא״א מאירים במצח ופנים דז״א מקבלים הצדיקים השעשועים שה״ס אור החכמה מן \u0003הפנים\u0004 דז״א, שה״ס ו״ק, ומקבלים הארת החסדים \u0003ממצח\u0004 דז״א שה״ס ג\"ר, כי אז שולט במצח דז\"א רעוא דרעוין כמו בא״א. ואע״פ, שגילוי רעוא דרעוין במצח דא״א הוא רק בשבת במנחה, עכ״ז רשימו של אור זה נשאר גם לימות החול, וז״ש, \u0003וכל שעתא ושעתא דדינא תלי,\u0004 אפילו בחול ותמיד, \u0003והאי מצחא דז״א אתגליא, אתגליא מצחא דעתיקא דעתיקין ואשתכיך דינא ולא אתעביד.\u0004 דהיינו שמתגלה הרשימו דרעוא דרעוין להאיר במצח, ואז מתגבר הימין, והדינים נשקטים, כמ״ש לפנינו בדבור הסמוך."],[2,"תאנא האי מצחא","וכו׳: למדנו, המצח הזה מתפשט במאתים אלף אדומים שבאדומים המתאחזים בו וכלולים בו. וכשנתגלה המצח דז״א, יש רשות לכולם להחריב, דהיינו לעשות חורבנות, וכשנתגלה המצח דרעוא דרעוין המאיר למצח הזה אז נשקטים כולם."],[2,"","כדי להבין זה, צריכים להבין היטב הפירוש של רעוא דרעוין המתגלה במצח דא״א. כי \u0003רעוא\u0004 סתם נאמר על החסד המתגלה ברצון וחפץ גדול באו\"א, עד שאין ה \u0003י׳\u0004 יוצא מאויר שלהם, והם תמיד בימין, בסו״ה כי \u0003חפץ\u0004 חסד הוא, וחפץ תרגומו \u0003רעוא.\u0004 ורצון זה נבחן לרצון של הימין, או הנוטים לימין. אמנם במקום שהשמאל שולט, וגם בו מתגבר הרצון אל החסדים יותר מבחכמה עד שהוא מפסיק הארת חכמה שבו ומשמש רק בחסדים, נבחן זה ל \u0003רעוא דרעוין,\u0004 כי יש כאן רצון כפול, שאפילו השמאל רוצה בחסדים. ולפיכך אין זה מתגלה אלא בא״א, שהוא כולו ימין, כלומר בשליטת הימין, ובמצח שלו, ששם מקום השליטה של הג״ר דחכמה, שה״ס השמאל, וכיון שהשמאל עזב את שלו ובחר בחסד הימין, נבחן זה לגילוי \u0003רעוא דרעוין,\u0004 שנגלה רצון כפול לחסדים הן מימין והן משמאל, ומבחינת הזמן נגלה זה בשבת, שהוא כולו תחת שליטת הימין, ובזמן תפלת המנחה שתקן יצחק, שאז שליטת השמאל, ואע״פ שהשמאל שולט מגביר חפצו לחסדים בסוד רעוא דרעוין."],[2,"","וכנגד זה, במצח דז״א, יש \u0003סומקי דסומקי,\u0004 כי בעת שמתגלה הג״ר דז״א במצח, גם צד הימין, שהוא חסד, הנקרא לבן, עוזב את החסדים שלו ובוחר בחכמה, שה״ס קו שמאל הנק׳ גוון אדום. ומתגלה כאן אדום כפול, הן מצד השמאל והן מצד הימין, וע״כ נקרא \u0003סומקי דסומקי.\u0004 ובכל קו יש בו ע״ס הכלולות מע״ס, שהן מאה. וב׳ קוין ימין ושמאל שנעשו לאדום כפול, מספרם מאתיים, ולהיותם בבחינת חכמה הם בסוד מאתים אלף. וז״ש \u0003האי מצחא אתפשט במאתן אלף סומקי דסומקי\u0004 וכו׳ \u0003אית רשותא לכלהו לחרבא,\u0004 שכיון שאין בו חסד כלל הם עלולים להחריב הכל, \u0003וכד אתגליא מצחא דרעוא דרעוין\u0004 וכו׳ \u0003כלהו משתככין,\u0004 כי כח הרצון הכפול, המגולה במצח דא״א, מבטל כח האדום והדין הכפול, שבמצח דז״א."],[3,"ותניא עשרין וארבע","וכו׳: ולמדנו כ״ד בתי דין נמצאים במצח הזה, וכולם נקראים \u0003נצח.\u0004 ובאותיות רצופות, דהיינו בחילוף אותיות הסמוכות זו לזו, הוא \u0003מצח,\u0004 כי ה \u0003נ׳\u0004 דנצח מתחלפת ב \u0003מ'.\u0004 ויש נצח שהם נצחים, והיינו שלמדנו \u0003נצח נצחים.\u0004 והם במצח, ומתפשטים מהם בגוף במקומות ידועים."],[3,"","פירוש כבר נתבאר סוד י״ג, שהם חו״ב תו״מ בהארת ג׳ קוין בכל אחד, שהם י״ב, ואחד כולל את כולם דהיינו מלכות המקבלת לתוכו אותם י״ב הארות, ונמצא שיש כאן ב׳ פעמים י״ב, וב״פ י״ב הם כ״ד. ובהם כלולים כל השכר והעונש, כי מקו הימין שבכל בחינה נמשך שכר טוב, ומקו שמאל של כל בחינה נמשכים דינים קשים להפרע מן הרשעים. וכל זה נקבע ע״י הקו האמצעי של כל בחינה ובחינה, שהוא קובע דינים קשים לרשעים הרוצים להמשיך מג\"ר דקו שמאל, והוא קובע שכר טוב לצדיקים הנזהרים לקבל רק מו״ק דשמאל. ומטעם זה נקראים כל כ״ד בחינות הנ״ל בשם כ״ד בתי דין."],[3,"","וז״ש \u0003עשרין וארבע בתי דינין משתכחין בהאי מצחא וכלהו אקרון נצח,\u0004 שזה נעשה ע״י הארת ג׳ קוין שבמצח, כנ״ל. ונקראים נצח מב' טעמים, א׳ שהם מנצחים מלחמה זו להעביר כל החצונים שלא יינקו משם. וטעם ב', מפני שיסוד דבינה מלובש במצח דז״א, והיסוד כלול מנצח והוד, וכיון שכל כ״ד בתי דינים נוטים לכף זכות שהוא ימין, ע״כ הם נקראים \u0003נצח,\u0004 שהוא קו ימין שביסוד. ומטעם זה נקרא המקום של כ״ד בתי דין בשם מצח, כי המ' מתחלפת בנ', ומצח הוא כמו נצח. ואין לתמוה איך יש נצח בראש, הלא נצח הוא אחרי ת״ת דגוף, וז״ש, \u0003ואית נצח דאינון נצחים,\u0004 כי נה״י דבינה המתלבשים בז״א מתחלק כל אחד מהם לג' שלישים. ומנצח, נעשה חכמה חסד נצח, וכן מהוד, נעשה בינה גבורה והוד, וכן מיסוד, נעשה דעת ת״ת ויסוד, אשר ג׳ שלישים עליונים מתלבשים בראש וג״ש אמצעים בחג״ת דגוף, וג״ש תחתונים בנה״י דגוף. הרי שיש ג׳ בחינות נצח, אשר נצח העליון הוא בראש. וז״ש, \u0003ואית נצח דאינון נצחים,\u0004 כלומר שמתחלק לג' בחינות נצח, וע״כ העליון מהם הוא במצח, וז״ש, \u0003והיינו דתנן נצח נצחים\u0004 שלפי שנצח מתחלק לג' שלישים ע״כ אוה״כ נצח נצחים, שהם ג', וע״כ \u0003ואינון במצחא.\u0004 דהיינו שליש העליון דנצח. \u0003ומתפשטן מנהון בגופא, באתרין ידיען,\u0004 דהיינו ב׳ שלישים תחתונים דנצח מתפשטים בגוף במקומות ידועים, דהיינו שליש האמצעי בחסד דגוף, ושליש תחתון בנצח דגוף."],[4,"תניא מאי דכתיב","וכו׳: למדנו, מ״ש, וגם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם. סוד זה העמדנו, כל נצח ההוא המתפשט בגוף, דהיינו בו״ק, פעמים שתולה על העולם לדון, ושב ומתחרט, ואינו עושה דין אם חוזרים בתשובה. מהו הטעם. משום שעומד במקום שנקרא אדם, והוא יכול להנחם. אבל אם במקום הנקרא ראש, דהיינו בג\"ר, נראה ונגלה נצח ההוא, אין הזמן ואין המקום להנחם. מהו הטעם. הוא משום שאין הוא במקום הנקרא אדם שהוא ו״ק, כי לא נגלה פרצוף הפנים והחוטם, שהם ו״ק, הנקרא אדם, אלא המצח בלבד, שהוא ג\"ר. כי המצח והפנים הם ג״ר וו״ק (כנ״ל אות קצ״ט) ובמקום שלא נמצא פרצוף הפנים שהוא ו״ק, דהיינו במצח, אינו נקרא אדם. ומשום זה לא אדם הוא להנחם, כמו הנצח שבשאר תקוני הגוף. דהיינו הנצח שבו״ק. שהוא אדם."],[4,"","פירוש. שיש בתי דין הנקראים נצח, בג״ר, דהיינו במצח. ויש בתי דין הנקראים נצח, בו\"ק, דהיינו בפנים וחוטם, וכן בנה״י דגוף. והרשעים הקרבים למשוך חכמה מג״ר הם נדונים מדינים הקשים אשר שם כנ״ל. ואין תשובה מועילה כאן. משום כי התשובה היא שיתדבקו בקו אמצעי הנקרא אדם, ואם הם מתדבקים שם, כבר הם נמצאים בו״ק. שכל התשובה היא כאן. אבל כל עוד שרוצים לינק מג״ר אין תשובה מועילה. וז״ש, \u0003כל ההוא נצח דאתפשט בגופא\u0004 וכו' \u0003ולא עביד דינא אי תייבין,\u0004 כי בית דין הנקרא נצח העומד בבחינת ו\"ק מעניש רק אם הרשעים עומדים במרדם ורוצים לינק מג״ר, אבל בעת שעושים תשובה ומתדבקים בקו אמצעי הנקרא אדם הוא מתנחם ואינו עושה דין, \u0003אבל אי באתר דאתקרי ראש אתחזי ואתגליא האי נצח,\u0004 דהיינו בית דין הנמצא במקום המצח שהוא ראש וג\"ר, \u0003לאו הוא עידן ואתר לאתחרטא דלא הוה מאתר דאקרי אדם,\u0004 כי הקו האמצעי הנקרא אדם אינו מתקן שם כלום, כי אדרבא, הקו האמצעי ממעט את הג״ר דשמאל שלא יאירו (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) וא״כ אין בג״ר מקום לתשובה. \u0003דהא לא אתגלי פרצופא וחוטמא,\u0004 שלא נגלה הבית דין במקום הפנים וחוטם שיש שם תקון אדם, אלא המצח בלבד."],[5,"עינוי דרישא משתניין","וכו׳: העינים של ראש דז\"א, נשתנו משאר עינים, דהיינו מעינים דא״א. הצבע שבגבות שממעל לעפעפי העינים, צבועים בצבע שחור. ותלוים תלים על תלים של שערות. והם תקון שעל העינים בתחילת המצח. ומתאחזים משניהם, מב׳ הגבות, ז׳ מאה אלף בעלי השגחה."],[5,"","פירוש. עשר הספירות שבראש, מכונים גולגלתא עינים אזן חוטם פה. שגולגלתא ה״ס כתר. ועינים חכמה. ואזן בינה. וחיטם ת״ת. ופה מלכות. והמצח ה״ס הגלגלתא, דהיינו כתר. ובעינים נוהג סתימת עינים ופתיחת עינים, שבעת שליטת השמאל הן נסגרות וע״י הקו האמצעי בכח המסך דחירק הן נפתחות (כנ״ל לך י״ג ד״ה ונתבאר) ויש לדעת, שאפילו בפנים, ששם יוצאת ה \u0003י׳\u0004 מאויר והם פנוים משערות (כנ״ל אות קצ״ט) עכ״ז אותן השערות הבאות ממסך דחירק, נשארות קבועות שם, והוא מטעם שהן באות מקו אמצעי, שזולתם לא היתה נפתחת הסתימה מן החכמה, שה״ס העינים, וע״כ הן צריכות להמצא תמיד. ואלו הן סוד השערות שבהתחלת המצח שממעל עפעפי העינים, שבהן כח פתיחת הסתימה של העינים וז״ש, \u0003שרקותא דבגבתא\u0004 וכו׳ \u0003תליין תלין על תלין דשערי ואינון תקונא דעל עיינין,\u0004 שבהן נתתקן כח המסך דחירק הפותח את העינים. והצבע שלהם \u0003שחור,\u0004 כי הן מסוד המלכות, שהגוון שלה הוא שחור."],[5,"","ונודע שבסבת המסך דחירק שבקו אמצעי מתמעטות הג״ר דחכמה, ואינן משפיעים אלא ממטה למעלה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת ע״ש) וז״ש \u0003ומתאחדן מתרוייהו, שבע מאה אלפי מארי דאשגחותא,\u0004 שהן גורמות שלא יאירו הג״ר דחכמה אלא \u0003ז״ס\u0004 תחתונות חג״ת נהי״מ, ויש בהם חסדים מצד הבינה שה״ס \u0003מאה,\u0004 והחכמה שבהן ה״ס \u0003אלף,\u0004 וע״כ הם ז׳ מאה אלף. ומכונים \u0003מארי דאשגחותא,\u0004 כי הארת העינים שהיא חכמה מכונה השגחה."],[6,"בכסותא דעיינין","וכו׳: בכסות שעל העינים, דהיינו העפעפים, לוהטים אלף וד׳ מאה רבוא המתאחדים בעפעפים שהם כסות. והשגחת עין עתיק יומין עליהם. ובשעה שמסתלקת הכסות מעל העינים, נראה כמי שמקיץ משנתו. ונפקחו עיניו, ורואות עינא פקיחא דא״א, והן רוחצות בלבן אחד שבעין טובה ההיא, ז״ש, רוחצות בחלב. מהו בחלב. הוא בלבן שלמעלה, הראשון שבלבן העין דא״א. ונמצאת בשעה ההיא ההשגחה של הרחמים."],[7,"וע״ד צלי דוד","וכו׳: ועל זה התפלל דוד, עורה למה תישן ה׳ הקיצה. שפירושו, שיפקח עיניו ותתרחצנה בלבן ההוא, הנמשך מעין א״א, וכל זמן שעיניו אינן נפקחות, כל בעלי הדין דוחקים את ישראל, ושאר העמים שולטים עליהם. ובזמן שיפקח עיניו, תתרחצנה בהלבן של העין הטובה, ורחמים על ישראל. ומסבבת העין ועושה נקמות בשאר העמים. ז״ש העירה, והקיצה. \u0003העירה,\u0004 היינו להתרחץ בלבן ההוא. \u0003הקיצה,\u0004 היינו לעשות נקמות לאותם שדוחקים את ישראל."],[7,"","פירוש כשה \u0003י'\u0004 יוצאת מאויר, ובינה ותו״מ שנפלו מהמדרגה חוזרים ומתחברים, ונשלמים כח״ב תו״מ דכלים ונרנח״י דאורות בסוד קו שמאל, דהיינו בסוד נקודת השורק (כנ״ל ב״א ט״ו ד\"ה ההיא) אשר אז החכמה היא בלי חסדים, ואינה יכולה להאיר והיא נסתמת, כמ״ש שם, הנה אז נמשכת \u0003כסות\u0004 על העינים, שמכסה הראיה, שה״ס אור החכמה. ויש בכסות הזה ע״ס שלמות כח״ב תו״מ הנמשכים מנקודת השורק, דהיינו מחיבור כו״ח עם בינה ותו״מ, בעת יציאת ה \u0003י׳\u0004 מאויר הבינה. ואח״כ ע״י קו האמצעי שמעורר המסך בסוד נקודת החירק ומחזיר ה \u0003י׳\u0004 לאויר הבינה (כנ״ל לך י״ג ד״ה ונתבאר) שהמדרגות חוזרות ונבקעות, והג״ר דשמאל מסתלקים, ונשאר בו״ק, הנה אז גם הכסות שעל העין נבקע באמצעו, וכו״ח שבכסות, מתעלים למעלה, ובינה ותו״מ שבכסות, יורדים למטה, ואז העינים נפקחות. ומטרם שנבקע הכסות ע״י קו האמצעי, ששולט בו אז קו השמאל בלבד, נבחן שיש בו רק קו אחד וחצי של צד שמאל, כי הג״ר ה״ס חב״ד שהדעת נחלקת לב' חצאים ז״א ומלכות, ונמצא בצד שמאל קו אחד של בינה, וחצי קו של דעת דהיינו המלכות, ונודע שג\"ר הם במספר ג׳ אלפים, וקו וחצי של צד השמאלי, הם אלף ת״ק, אלא משום שחצי הקו, שהוא מלכות דדעת, אין בו אלא כח\"ב ות״ת, וחסר מלכות דעצמותה, מחמת שנמתקה בבינה, ע״כ אין בו אלא ארבע מאה. וז״ש, \u0003בכסותא דעיינין\u0004 שה״ס הסתימה והכיסוי שעל החכמה בהיותה בבחינת ג\"ר דשמאל, מסוד נקודת השורק, \u0003להטין אלף וארבע מאה רבוא,\u0004 דהיינו רק קו אחד וחצי קו, שבצד שמאל. וקו אחד וחצי קו שבצד ימין, שהם חכמה וצד ימין דדעת, חסרים שם. \u0003וז\"ש דמתאחדן בגבינין,\u0004 דאינהו כסותא, כי מחמת אחיזתם של קו וחצי דשמאל בכסותא, הם סותמים ומכסים על העינים. \u0003ואשגחותא דעינא דעתיק יומין עלייהו,\u0004 כי קו וחצי דימין החסרים להם, הם נמשכים להם מהשגחתה של העין דעתיק יומין, בעת שתתבקע הכסות לב' חצאים כנ״ל, ותפקחנה העינים."],[7,"","וז״ש, \u0003ובשעתא דסלקין אינון כסותא אתחזי כמאן דאתער משנתיה,\u0004 כי כח הסתימה וכיסוי העינים הבאים מג״ר דשמאל, נבחנים כמו שינה, כי הישן, העפעפים שלו נמצאים סתומים ומכסים עיניו, ולפיכך בעת שנסתלקה הכסות, דהיינו שמתבקעת ונפתחת, נראה כמי שמקיץ משנתו. \u0003ואתפקחן עינוי וחמאן לעינא פקיחא\u0004 ונפקחים העינים ע״י קו האמצעי כנ״ל ואז הן רואות העינא פקיחא דא״א, כלומר שמקבלת הלבן שה״ס החסדים, מעין א״א, \u0003ואתסחן בחד חוורא דעינא טבא\u0004 וכו' \u0003בחוורא דלעילא קדמאה,\u0004 דהיינו מחוור גו חוור, שפירושו שחוור של חכמה כלול בחוור של כתר. (כמ״ש לעיל אות מ״ב), ואומר שמקבל מחוור הראשון שה\"ס קו ימין דעין א״א, שהוא כמו כתר המקיף את החכמה. עש\"ה. וממנו נמשכים קו וחצי דצד ימין החסרים בעיני ז״א. כנ״ל. וזה נבחן, כמו שהעינים דז״א, שהן אדומות מקו שמאל, רוחצות מאודם שלהן, בתוך חלב, שה״ס הלבן דעינא פקיחא דא״א. וז״ש, \u0003וכל זמנא דעינוי לאו מתפקחן, כל מאריהון דדינין\u0004 וכו' \u0003ושאר עמין שלטין עלייהו,\u0004 כי כל עוד שיש שליטת ג\"ר דשמאל שה״ס חכמה בלי חסדים נמשכים משם כל דינים קשים כנודע. \u0003ובזמנא דיפקח עינוי\u0004 ע״י מסך דחירק שבקו אמצעי, \u0003יתסחן בעינא טבא,\u0004 שמקבלים שלמות הג״ר מעין א״א, \u0003ורחמי על ישראל,\u0004 שה״ס גילוי קו האמצעי שנקרא רחמים, ואז, \u0003ואסתחר עינא, ועביד נוקמין בשאר עמין,\u0004 דהיינו שממעט הג״ר דשמאל, שבהם אחוזים שאר העמים. ונשאר השמאל רק בו״ק דחכמה שממטה למעלה, שאין העמים יכולים לקבל משם כלום, וניטל מהם חיותם. וז״ש, \u0003העירה, לאתסחאה בההיא חוורא,\u0004 העירה, סובב שיתעורר להמשיך החסדים. \u0003הקיצה, למעבד נוקמין.\u0004 דהיינו למעט הג״ר דשמאל."],[8,"עינוי כד אתפקחן","וכו׳: עיניו של ז״א, כשהן נפקחות, נראות יפות כיונים, באדום ושחור וירוק, ולבן אינו נגלה אלא בזמן שמסתכל בעין טובה דא״א, ומתרחצים כל אלו הגוונים, באותו הלבן, שבעין א״א."],[8,"","פירוש. העינים, ה״ס החכמה כנ״ל, והתחלתם מתחילה מיציאת ה \u0003י׳\u0004 מאויר בסוד נקודת השורק, שאז שולט השמאל בלי ימין, ולפיכך העינים מעצם אצילותן אין בהן ימין, ומתחילים משמאל, שה״ס גוון אדום, וע״כ בעת שנפקחות ע״י הקו האמצעי, לא נראה בהן רק ג׳ גוונים אדום שחור ירוק שהם גבורה ומלכות ות״ת. אבל לבן אין בהם, להיותם אז חכמה בלי חסדים. אלא אחר שנפקחות, הן מסתכלות לעין א״א, ומקבלים ממנו גוון הלבן, ואז יש ד׳ גוונים בעין, לבן אדום ירוק ושחור. וז״ש, \u0003עינוי כד אתפקחן\u0004 וכו' \u0003בסומק ואוכם וירוק,\u0004 שהם גבורה מלכות ות״ת, \u0003חוור לא אתגלי,\u0004 כי במצב נקודת השורק נמצאת החכמה בלי חסדים שהם לבן. \u0003אלא בזמנא דאסתכל בעינא טבא\u0004 וכו' שאז מקבל החסדים מעין א״א."],[9,"מאינון גוונין דמתגליין","וכו׳: מאלו הגוונים המגולים בעין, יוצאות שבעה עינים של השגחה, והן יוצאות מן השחור שבעין. ז״ש, על אבן אחת שבעה עינים. מהן אבן אחת. זו היא השחור שבעין."]],[]],[["מִסּוּמָקָא, נָפְקִין שִׁבְעָה רְהִיטִין, דְּסַמְכִין (נ\"א דסחרן) לִסְטַר שְׂמָאלָא, וּמִתְלַהֲטִין בְּאֶשָּׁא דְּלִסְטַר צָפוֹן, וּמִתְאַחֲדָן לְאִתְפַּשְּׁטָא בְּעָלְמָא, לְגַלָּאָה אָרְחִין דְּחַיָיבַיָּא הֲדָא הוּא דִכְתִיב, (זכריה ד׳:י׳) שִׁבְעָה (ויחי רמ\"ט) אֵלֶּה עֵינֵי יְיָ הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ.","מִירוֹקָא, נָפְקִין שִׁבְעָה טְהִירִין (ס\"א נהירין) דְּקִטְרָא דְּלִסְטַר (נ\"א רהיטין דסחראן לסטר) דָּרוֹמָא, וּמִתְאַחֲדָן לְאִתְפַּשְּׁטָא בְּעָלְמָא, לְגַלָּאָה אָרְחִין וְעוֹבָדִין דִּבְנֵי נָשָׁא, בֵּין טַב בֵּין בִּישׁ, דִּכְתִּיב, (איוב ל״ד:כ״א) כִּי עֵינָיו עַל דַּרְכֵי אִישׁ וְגוֹ'.","וְכַד אִסְתְּחָאן בְּחִוָּורָא, מִשְׁתַּכְּחִין כֻּלְּהוּ לְאַשְׁגָּחָא לְכָל מָארֵי קְשׁוֹט, לְאוֹטָבָא עָלְמָא בְּגִינֵהוֹן. וְכָל אַשְׁגָּחוּתָא דְּהַהוּא חִוָּורָא, הֲוִי לְטַב עַל יִשְׂרָאֵל. וְאַשְׁגַּח בְּסוּמָקָא לְמַאן דְּעָאקִין לְהוּ. הֲדָא הוּא דִכְתִיב, (שמות ג׳:ז׳) רָאֹה רָאִיתִי. רָאֹה: לְאוֹטָבָא לוֹן. רָאִיתִי: לְנַקְמָא לוֹן, מִדְּעָקִין לוֹן, וּבְגִין כַּךְ כְּתִיב, (תהילים מ״ד:כ״ד) עוּרָה לָמָּה תִישַׁן יְיָ הָקִיצָה אַל תִּזְנַח לָנֶצַח. עוּרָה, וְהָקִיצָה, תְּרֵי אַשְׁגָּחוּתָא. תְּרֵי פְּקִיחִין. תְּרֵי טָבָן. רַחֲמֵי וְנוּקְמִין.","גַּוְונָא קַדְמָאָה, סוּמָקָא בְּגוֹ סוּמָקָא כָּלִיל וְסָתִים כָּל סוּמָקִין, מִקָּמֵיהּ לָא אִתְחָזוּן. סוֹחֲרָנֵיהּ דְּהַהוּא סוּמָקָא, אַסְחַר חַד חוּטָא אוּכָמָא, וְאָקִיף לֵיהּ.","גַּוְונָא תִּנְיָינָא, אוּכָמָא. כְּאַבְנָא חַד דְּנָפִיק מִתְּהוֹמָא, חַד זְמַן לְאֶלֶף שָׁנִים, בְּיַמָּא רַבָּא. וְכַד נָפִיק הַאי אַבְנָא, אָתֵי רִגְּשָׁא וְתֻּקְפָא עַל יַמָּא. וְקָלֵיהּ דְּיַמָּא, וְגַלְגַּלּוֹהִי אַזְלִין, וְאִשְׁתַּמְעוּ לְנוּנָא רַבָּא, דְּאִקְרֵי לִוְיָתָן. וְנָפִיק מִתְּהוֹמָא. וְהַאי אַבְנָא מִתְגַּלְגְּלָא בְּתוּקְפָא דְּיַמָּא, וְנָפִיק לְבַר. וְהִיא אוּכָמָא, דְּכָל אוּכָמִין סְתִימִין קָמֵיהּ. (ס\"א והא אוקמוה דכל אורחין סתימין קמה) וְכַךְ הִיא אוּכָמוּתָא דְּעֵינָא אוּכָמָא, דְּכָלִיל וְסָתִים כָּל שְׁאַר אוּכָמִין. וְסוּחֲרָנֵיהּ דְּהַהוּא אוּכָמָא, אַסְחַר חַד חוּטָא סוּמָקָא, (ס\"א לסטר חד) וְאָקִיף לְהַהוּא אוּכָמָא.","גַּוְונָא תְּלִיתָאָה. יְרוֹקָא דִּירוֹקֵי, דְּכָלִיל וְסָתִים כָּל יְרוֹקִין. וּבְסוֹחֲרָנֵיהּ דְּהַהוּא יְרוֹקָא, אַסְחָרוּ תְּרֵין חוּטִין. חוּטָא סוּמָקָא לִסְטַר חַד. וְחַד חוּטָא אוּכָמָא לִסְטַר חַד. וְאַקִּיפִין לְהַהוּא יְרוֹקָא.","וְכַד אִסְתְּחַר (נ\"א אתגלי) חִוָּורָא, וְאִסְתְחָרִי עֵינָא, כָּל אִינּוּן גַּוְונִין לָא מִשְׁתַּכְּחִין, וּמִשְׁתַּקְּעִין לְתַתָּא (סומקא ירוקא אוכמא). לָא אִתְחֲזֵי בַּר הַהוּא חִוָּורָא, דְּנָהִיר מֵעַתִּיק יוֹמִין. וּנְהִירִין מִנֵּיהּ כָּל אִינּוּן דִּלְתַתָּא. (נ\"א הוא).","וְלֵית גַּוְונָא אִתְחַזְיָיא, בַּר הַהוּא חִוָּורָא בִּלְחוֹדוֹי. וּבְגִין כַּךְ אִסְתְּלָקוּ כָּל מָארֵיהוֹן דְּסוּמָקָא וְאוּכָמָא, דְּאִינּוּן תְּאוֹמִין כַּחֲדָא. הֲדָא הוּא דִכְתִיב (שיר השירים ד׳:ב׳) שִׁנַּיִךְ כְּעֵדֶר הַקְּצוּבוֹת שֶׁעָלוּ מִן הָרַחְצָה שֶׁכֻּלָּם מַתְאִימוֹת. מַאי מִן הָרַחְצָה. מֵהַהוּא אַסְחוּתָא דְּעֵינָא קַדִּישָׁא עִלָּאָה. שֶׁכֻּלָּם מַתְאִימוֹת. מִתְעָרְבָן דָּא בְּדָא, וְאִתְדַּבְּקָן דָּא בְּדָא. וּמַה דְּאָמַר שִׁנַּיִךְ כְּעֵדֶר הַקְּצוּבוֹת, וְאַתְּ אַמְרַת שֶׁכֻּלָּם מַתְאִימוֹת. כְּלוֹמַר, חִוָּורָא דִּלְהוֹן, כְּהַהוּא חִוָּורָא דְּעַיְינִין, כַּד אַסְחָן בְּחִוַורְתָּא דְּעֵינָא עִלָּאָה.","וְדָא זְמִינִין לְמִנְדַּע צַדִּיקַיָּיא, לְמֵחזֵי בְּרוּחָא דְּחָכְמְתָא, כְּמָה דְאַתְּ אָמֵר (ישעיה נד) כִּי עַיִן בְּעַיִן יִרְאוּ. אֵימָתַי בְּשׁוּב יְיָ צִיּוֹן. וּכְתִיב (במדבר י״ד:י״ד) אֲשֶׁר עַיִן בְּעַיִן נִרְאָה אַתָּה יְיָ, וּכְדֵין פְּקִיחוּתָא דְּעַיְינִין לְטַב.","וְאִית פְּקִיחוּתָא דְּעַיְינִין לְטַב. וְאִית פְּקִיחוּתָא דְּעַיְינִין לְבִישׁ. כְּמָה דִּכְתִּיב, (דניאל ט׳:י״ח) פְּקַח עֵינֶיךָ וּרְאֵה שׁוֹמְמוֹתֵינוּ וְגוֹ'. וְדָא הָכָא לְטַב, וּלְבִישׁ. וּכְתִיב (ישעיהו ל״ג:כ׳) עֵינֶיךָ תִרְאֶנָה יְרוּשָׁלַם נָוְה שַׁאֲנָן אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח הָא הָכָא לְטַב וּלְבִישׁ. דְּלָא אִתְעָבִיד דָּא בְּלָא דָּא.","תָּנָא בִּצְנִיעוּתָא דְּסִפְרָא, מַהוּ עֵינֶיךָ תִרְאֶנָה יְרוּשָׁלַם נָוְה שַׁאֲנָן. וְכִי יְרוּשָׁלַ ם נָוְה שַׁאֲנָן הוּא, וְהָא כְּתִיב (ישעיהו א׳:כ״א) צֶדֶק יָלִין בָּה. וּבַאֲתָר דְּאִשְׁתְּכַח צֶדֶק, לָאו שָׁקִיט, וְלָאו שַׁאֲנָן הוּא. אֶלָּא עֵינֶיךָ תִרְאֶנָה יְרוּשָׁלַם נָוְה שַׁאֲנָן, נָוְה שַׁאֲנָן, לְעַתִּיק יוֹמִין אִתְּמַר, (דישגח באלין עיינין) דְּהַהוּא עֵינָא שָׁקִיט וְשַׁאֲנַן. עֵינָא דְּרַחֲמֵי, עֵינָא דְּלָא נָטִיל מֵאַשְׁגָּחוּתָא דָּא, לְאַשְׁגָּחוּתָא אַחֲרָא. וּבְגִין כַּךְ כְּתִיב (קמ\"ו ע\"ב), עֵינֶךָ תִּרְאֶינָּה חָסֵר יוֹ\"ד, וְלָא עֵינֶיךָ. וּמַה דְּאָמַר יְרוּשָׁלַם וְלָא צִיּוֹן, הָכִי אִצְטְרִיךְ, לְאַכְפְּיָיא לְדִינָא, דְּאִשְׁתְּכַח בָּה וּלְרַחֲמָא עָלָהּ."],[[0,"מסומקא נפקין שבעה","וכו׳: מהאדום שבעין, יוצאים שבע רצים, הסומכים צד השמאל, ומתלהטים באש שבצד צפון, ומתאחזים בגוון האדום, כדי להתפשט בעולם לגלות דרכיהם של הרשעים. ז״ש, שבעה אלה עיני ה׳ המה משוטטים בכל הארץ."],[1,"מירוקא נפקין שבעה","וכו׳: מן הירוק שבעין, יוצאים שבעה אורות המסבבים לסטר דרום, ומתאחזים בגוון הירוק, להתפשט בעולם לגלות הדרכים והמעשים של בני אדם, בין טוב ובין רע, שכתוב, כי עיניו על דרכי איש וגו׳."],[2,"וכד אסתחאן בחוורא","וכו׳: וכשמתרחצים בלבן, נמצאים כולם להשגיח לכל בעלי האמת להיטיב לעולם בשבילם. וכל ההשגחה של הלבן ההוא, הוא לטוב על ישראל. ומשגיח בהאדום שבעין, לנקום במי שמיצר לישראל. ז״ש ראה ראיתי. \u0003ראה,\u0004 כדי להיטיב לישראל. \u0003ראיתי,\u0004 כדי לנקום בשבילם לאותם שמצירים להם, לישראל. ומשום זה כתוב, \u0003עורה\u0004 למה תישן ה׳ \u0003הקיצה\u0004 אל תזנח לנצח. עורה והקיצה, הם ב׳ השגחות, ב׳ פקיחות העינים, ב׳ מיני טוב, רחמים ונקמות."],[2,"","פירוש. כבר נתבאר שהג״ר דחכמה מסתלקים מעינים ואין בהם אלא ז׳ ספירות תחתונות שהן חג״ת נהי״מ. וע״כ אינו יוצא מאלו הגוונים רק שבעה שבעה, כנגד ז״ת. ועיקר כח הראיה הוא בשחור שבעין, שה״ס מלכות, וז״ש \u0003ז׳ עיינין דאשגחותא דנפקי מאוכמא,\u0004 כי ז׳ ספירות שלה נק׳ ז׳ עינים. הה״ד על אבן אחת שבעה עינים. כי המלכות נקראת אבן, שה״ס השחור שבעין, וז״ס שלה הן ז׳ עינים."],[2,"","וז״ס דקו שמאל שבעין, נקראים שבעה רצים, שה״ס והחיות \u0003רצוא ושוב,\u0004 כי השמאל \u0003רץ\u0004 לגלות החכמה, וע״י הקו האמצעי הוא \u0003שב\u0004 לחסדים. וז״ש \u0003מסומקא נפקין שבעה רהיטין,\u0004 כי ז׳ ספירות של השמאל נקראות ז׳ רצים. \u0003דסמכין לסטר שמאלא,\u0004 שהם מחזיקים צד השמאל, כי להיותם בחינת ז״ת ומחוסרי ג״ר דשמאל, ע״כ נחשבים רק למחזיקים את השמאל. וז״ש \u0003ומתלהטין באשא דלסטר צפון,\u0004 שעם גילוים נגלים דינים קשים מצד צפון, שהוא שמאל, לנקום ברשעים הרוצים להמשיך משם חכמה ממעלה למטה. וז״ש, \u0003ומתאחדן לאתפשטא בעלמא לגלאה אורחין דחייביא.\u0004 דהיינו לענוש בדינים קשים את הרשעים שדרכם להמשיך החכמה ממעלה למטה. \u0003הה״ד שבעה אלה עיני ה' המה משוטטים בכל הארץ.\u0004 שהם משוטטים לגלות את הרשעים, ולהענישם (כנ״ל פקודי אות שע״ו)."],[2,"","והקו האמצעי ה״ס גוון ירוק, ויוצאים ממנו ז׳ אורות שהם חג״ת נהי״מ שבו, והם ממשיכים קו הימין שה״ס חסדים ומיחדים הימין והשמאל זה בזה. וז\"ש, \u0003מירוקא נפקין שבעה טהירין דסחראן לסטר דרומא,\u0004 שהם מסבבים וממשיכים צד דרום שה״ס קו הימין. ומיחד אותו עם השמאל. ולהיותו כלול מימין ומשמאל, ע״כ, \u0003ומתאחדן לאתפשטא בעלמא, לגלאה ארחין ועובדין דבני נשא בין טב ובין ביש,\u0004 כי מצד הימין הוא מגלה מעשים טובים של האדם ונותן שכר טוב לצדיקים. ומצד שמאל הכלול בו, מגלה מעשים רעים שעושים הרשעים ונפרע מהם. דכתיב, \u0003כי עיניו על דרכי איש\u0004 וגו׳. וז״ש, \u0003וכד אסתחאן בחוורא משתכחין כלהו לאשגחא\u0004 וכו' \u0003לאוטבא עלמא,\u0004 כי בעת שעיני ז״א ממשיכים הלבן מעינא פקיחא דא\"א, שולט הלבן שכולו רק להטיב. וז״ש, \u0003וכל אשגחותא דההוא חוורא הוי לטב על ישראל,\u0004 כי הוא כולו טוב. \u0003ואשגח בסומקא למאן דעאקין להו,\u0004 ובאדום הוא משגיח כדי לנקום באותם המצירים לישראל. ונמצא שיש שתי השגחות. ע״ז אומר, עורה והקיצה וכו' שבהשגחה שבימין נאמר עורה. ושבשמאל נאמר הקיצה."],[3,"גוונא קדמאה","וכו׳: גוון הראשון של העין, הוא אדום בתוך אדום הכולל וסותם כל האדומים, שכל האדומים אינם נראים אדום לפניו. ומסביב האדום הזה מסבב חוט שחור אחד ומקיף אותו."],[3,"","פירוש. כבר נתבאר, שאין הארת חכמה נמשכת אלא ע״י ג׳ קוין ומלכות המקבלתם, וזה נוהג בכל המדרגות, משום שיש בהן הארת חכמה בהתכללות. אמנם בעינים דז״א, שהם בחינת חכמה בעצם, שמהן שואבים ונכללות כל המדרגות, נמצא גוון סומק, שה״ס השמאל, שבו הארת החכמה, שהוא בבחינת \u0003סומקא בגו סומקא כליל וסתים כל סומקין.\u0004 כי כל המדרגות שיש בהן סומק שהוא קו שמאל, הרי מהתכללות העינים בהן הוא בא. וע״כ \u0003מקמיה לא אתחזון,\u0004 כי האדום שבהן אינו ניכר לאדום בהשואה לאדום הזה שבעין, שהוא שורשן. אמנם האדום הזה מוקף מחוט שחור, שה״ס הדינים דמסך דחירק הממעטו מג״ר דחכמה. וז״ש, \u0003סוחרניה דההוא סומקא אסחר חד חוטא אוכמא ואקיף ליה,\u0004 שיאיר רק ממטה למעלה ולא יתפשט ממקומו למטה."],[4,"גוונא תניינא","וכו׳: גוון השני שבעין הוא שחור. בדומה, לאבן אחת היוצאת מן התהום פעם אחת לאלף שנים, בים הגדול. וכשאבן זו יוצאת מן התהום, בא רעש וזעף על הים. וקולו של הים וגליו הולכים ונשמעים לדג גדול הנקרא לויתן, והוא יוצא מן התהום. ואבן זו מתגלגלת בזעף הים, ויוצאת לחוץ, והיא שחורה שכל השחורים סתומין לפניה, דהיינו שאינם ניכרים לשחורים בהשואה אליה. וכך הוא השחור שבעין, שהוא שחור הכולל וסותם כל שחורים. דהיינו שאינם ניכרים לשחורים בהשואה אליה. ומסביב השחור ההוא, מסבב חוט אחד אדום, ומקיף לשחור ההוא. \u0003רגשא\u0004 פירושו רעש, מלשון למה רגשו גוים (תהלים ב׳) \u0003תקפא\u0004 פירושו זעף, מלשון תוקפא בביתא (סוטה ג:)."],[4,"","פירוש. המשל הזה שמביא, הוא מן הכללות אל הפרט. כי שורש תקון קוין בכללות ה״ס חולם שורק חירק. שהחולם שה״ס קו ימין, נעשה מעלית המלכות לבינה, בסוד \u0003י׳\u0004 שנכנסה ב \u0003אור\u0004 הבינה ונעשה האור ל \u0003אויר,\u0004 כי נבקעה הבינה מכח המלכות שעשתה סיום שלה בבינה דבינה, ובינה ותו״מ נפלו למטה, וכתר וחכמה דכלים, וקומת נפש רוח דאורות, נשארו בבינה. וקומת נפש רוח ה״ס ה \u0003אויר\u0004 שנעשה בבינה מחמת כניסת ה \u0003י׳\u0004 שה״ס המלכות באור שלה. ומקום כניסת ה \u0003י׳,\u0004 דהיינו מקום סיום החדש, נקרא \u0003תהום.\u0004 ובינה עצמה נקראת הים הגדול. ואח״כ בסוד נקודת השורק נעשה קו שמאל בבינה, אשר ע״י הארת ע״ב ס״ג דא״ק חוזרת ויוצאת ה \u0003י׳\u0004 מן האויר, שה״ס התהום, ובינה ותו״מ חוזרים ומתחברים עם כו״ח, ויוצאים הג״ר דחכמה. שה״ס קו שמאל. ואז נעשית מחלוקת בין ב׳ הקוין, בין הימין שה״ס חולם, ובין השמאל שה״ס שורק. פעם גובר הימין, שה״ס ו״ק, שבו עוד נמצא הי׳ באויר, כי אינו רוצה להתחבר עם השמאל, ופעם גובר השמאל, שבו ה \u0003י׳\u0004 יוצאת מן האויר, והג״ר דחכמה חוזרים ומאירים. וע״כ נבחן אור נקודת השורק בשם מטלטלים, כי מטולטלים מרחמים לדין ומדין לרחמים. עד שבא הקו האמצעי ועושה שלום ביניהם בסוד נקודת החירק (כמ״ש לעיל ב״א ט״ו ד\"ה ההוא) וכ״ז הוא בכללות."],[4,"","וז״ש \u0003כאבנא חד דנפיק מתהומא,\u0004 כי אבן ה״ס המלכות שנכנסה בבינה שה״ס ים, ועשתה בה סיום חדש, במקום בינה שבים, שסיום הזה נקרא \u0003תהום.\u0004 כנ״ל. ובעת הארת נקודת השורק יוצאת המלכות בחזרה מן תהום הזה שבאויר הבינה, ונגלו הג״ר דחכמה, שה״ס קו השמאל. \u0003חד זמן לאלף שנים,\u0004 היינו \u0003הזמן\u0004 של נקודת השורק שמגלה החכמה המכונה \u0003אלף שנים\u0004 בסו״ה ואאלפך חכמה. \u0003בימא רבא,\u0004 היינו בבינה הנקראת הים הגדול. \u0003וכד נפיק האי אבנא,\u0004 וכשאבן זו יוצאת מן התהום, והחכמה נגלית בימא רבא, שה״ס יציאת קו השמאל, \u0003אתי רגשא ותוקפא על ימא\u0004 שנעשה תיכף, רעש וזעף בים, מכח הדינים והמחלוקת של ימין ושמאל שבים, \u0003וקליה דימא וגלגלוהי אזלין,\u0004 שזסו״ה \u0003יעלו שמים ירדו תהומות,\u0004 כי פעם שולט השמאל, ואז \u0003יעלו שמים,\u0004 שנגלה החכמה, שהם מכונים גלי הים, מלשון גילוי. ופעם שולט הימין, שבו עוד הי׳ לא יצאה מאויר, אז מתבטל הגילוי של החכמה וגלי הים, שה״ס הג״ר דחכמה שנגלו ע״י השמאל חוזרים ויורדים אל התהום, שז״ס \u0003ירדו תהומות\u0004 ובשעת נפילת גלי הים, בחזרה לתהום, משמיעים קול. וז״ש, \u0003וקליה דימא וגלגלוהי,\u0004 כי פעם נשמע קול הים מנפילת גלי הים, ופעם מתגברים ועולים גלי הים. וכן חוזר חלילה, עד, \u0003ואשתמעו לנונא רבא דאקרי לויתן,\u0004 שה״ס קו האמצעי שבים, העושה שלום בין ימין ושמאל ויוצא מן התהום, כי הימין והשמאל מתיחדים. וחוזר לענין האבן, ואומר, \u0003והאי אבנא מתגלנלא בתוקפא דימא,\u0004 שהמלכות שיצאה מתהום, נעשתה אח״כ כמו חלק מן הים, דהיינו כמו שגם היא היתה חלק מבינה, וע״כ היתה מתגלגלת בזעף הים מדין לרחמים ומרחמים לדין, תחת שליטת השמאל דבינה, בסוד יעלו שמים ירדו תהומות, בשוה עם מי הים. עד שמתוך הדינים שקבלה מגלגולה במי הים, נגלה בה גם כן מדת הדין שבמלכות עצמה. ואז \u0003ונפיק לבר,\u0004 שיצאה לחוץ מן הים שהיא בינה, כי הוכר בה שהיא מלכות ולא בינה. \u0003והיא אוכמא, דכל אוכמין סתימין קמיה,\u0004 כי אז, מחמת הגילוי של תוספת דין שבה מבחינת מלכות דמדת הדין, נלקה גוון סומק שהיה בה משמאל שבים, ונעשה לגוון שחור. בסוד שאמרו חז״ל, שחור אדום הוא אלא שלקה. (נדה י\"ט) דהיינו שהאדום שבה, שה״ס דינין דדכורא מקו שמאל, נלקה בדינין דנוקבא שמבחינת מלכות דמדת הדין, ומכפילת הדינים נעשתה לשחורה כל כך עד, \u0003דכל אוכמין סתימין קמיה.\u0004"],[4,"","וע״כ ביאור סוד האוכמא שבמלכות מבחינת הכללות, דהיינו מבחינת עלית המלכות לבינה הנוהג בכל מדרגה ומדרגה, ועתה מדמה הכללות לפרטות דהיינו לעינים דז״א, ואומר, \u0003וכך הוא אוכמתא דעינא אוכמא, דכליל וסתים כל שאר אוכמין.\u0004 שהשחור שבעיני ז״א גם היא סוד המלכות שהיתה חלק מן האדום שבבינה, והוכרה שם בבחינת המלכות דמדת הדין, ויצאה לחוץ מבינה, שאז הושחרה בגוון שחור הזה מכפילת הדינים שבה, כנ״ל. אמנם אע״פ שיצאה לחוץ מבינה מחמת שהוכרה שהיא מלכות ולא בינה, עכ״ז, עוד בחינת בינה סובבת אותה סביב סביב, ומדת הדין שבה אינה נראה, וז״ש, \u0003וסוחרניה דהאי אוכמא אסחר חד חוטא סומקא ואקיף לההוא אוכמא,\u0004 באפן שעדיין אינה נבחנת למלכות ממש אלא ממותקת באדום דבינה."],[5,"גוונא תליתאה","וכו׳: הגוון השלישי שבעין, הוא ירוק שבירוק, הכולל וסותם כל הירוקים. ומסביב הירוק ההוא מסבבים ב׳ חוטים, חוט אדום לצד אחד, וחוט שחור לצד אחד, ומקיפים את ירוק ההוא."],[5,"","פירוש. הירוק שבעין, ה״ס קו האמצעי, שהוא כולל בתוכו ימין ושמאל, והדינים שבהם, ולהיות שיש בקו שמאל ב׳ מיני דינים, שהם סומק מחמת עצמו ואוכם מחמת המלכות שנתערבה בו, ע״כ כולל גם הוא את שניהם ויש לו ב׳ חוטים, אדום וירוק, וז\"ש, \u0003ובסוחרניה דההוא ירוקא אסחרו תרין חוטין\u0004 וכו'. ומה שהוא ירוק שבירוק הכולל בתוכו וסותם כל הירוקים, כבר נתבאר לעיל (אות רי״ג) בגוון סומק, שהוא מטעם שהגוונים דעין הם שורש כל הגוונים שבכל המדרגות, ע״ש."],[6,"וכד אתגלי חוורא","וכו׳: וכשנגלה הלבן שבעין, והעין נתגלגלה ובאה לשליטת הלבן, כל אלו הגוונים האחרים אינם נמצאים אז, ומשתקעים למטה, ולא נראה בעינים חוץ מגוון לבן ההוא המאיר מעיני עתיק יומין לעינים דז״א, ומאירים ממנו כל המדרגות שלמטה."],[6,"","פירוש. הלבן שבעין ה״ס קו ימין. וכבר נתבאר לעיל (אות ר\"ח) שהוא נגלה רק ע״י הסתכלות בלבן דעין א״א, ואין לבן בעינים מבחינתם עצמם, ע״ש."],[7,"ולית גוונא אתחזיא","וכו׳: ואין שום גוון נראה רק אותו גוון לבן בלבדו, ומשום זה נסתלקו כל בעלי האדום והשחור, שהם תאומים יחדיו. כלומר שנראית שוות זו לזו, ולא ניכר שהשחור הוא בחינה אחרת מאדום, כי הגוון השחור אינו מעיד רק על הליקוי הכפול שבו, ולא על מה שהוא בחינת מלכות ולא בינה, ז״ש, שניך כעדר הקצובות שעלו מן הרחצה שכלם \u0003מתאימות.\u0004 מהו \u0003מן הרחצה,\u0004 היינו מהרחיצה ההיא של העין הקדושה העליונה, דא״א, שעי״ז שולט הלבן לבד. \u0003שכלם מתאימות,\u0004 היינו שמתערבות זו בזו, ומתדבקות זו בזו, עד שנראות כתאומים, שאין הפרש ביניהן. ומה שאומר שניך כעדר הקצובות, שמשמע שיש קצבה והיכר לכל אחד מהם, ואתה אומר שכלם מתאימות שמשמע שאין היכר, הפירוש הוא שהכתוב בא לומר, שהלבן שבשינים הוא כמו הלבן שבעינים, בעת שרוחצות בלבן של העין העליונה, שאז נקראים, כעדר הקצובות. ואין פירושו שיש קצבה והיכר בין גוון לגוון."],[7,"","פירוש. כי הוקשה לו, כיון שהשחור שבעין ה\"ס גילוי המלכות דמדת הדין (כנ״ל באות רי״ד) הרי בכל מקום שמלכות זו מתגלה מסתלקים משם האורות, (כנ״ל ויצא י״ג ד״ה סתרא) ואיך יש אור חכמה בעין שה״ס הראיה. וז\"ש, \u0003ולית גוונא אתחזייא בר ההוא חוורא בלחודוי,\u0004 דהיינו שאין אז שליטה אלא לחסד לבד, \u0003ובג״כ אסתלקו כל מאריהון דסומקא ואוכמא, דאינון תאומין, כחדא.\u0004 שמחמת שליטת הלבן נסתלקו ביחד כל בעלי האדום והשחור, שהם תאומים ודומים זה לזה. כלומר, החסד והדין הם הפכים זה לזה, שבשליטת הדין מסתלק החסד ובשליטת החסד מסתלק הדין, ומבחינה זו אין הפרש מאיזה צורה הוא הדין, אם מדינין דדכורא או מדינין דנוקבא, או ממנעולא, שמבחינה זו כל מיני הדין הם שוים ותאומים, אשר בשליטת החסד הם מסתלקים יחד. ומשום זה, בעת שליטת הלבן אין בחינת מלכות דמדת הדין ניכרת כלל בשחור שבעין, אלא כל ההפרש מסומקא לאוכמא הוא, שהאוכמא, הוא ליקוי כפול מסומקא ולא יותר. וע״כ אין כח מדת הדין שבאוכמא ניכר ואין אור החכמה מסתלק בסבתו."],[7,"","וז\"ש, \u0003הה\"ד שניך כעדר הקצובות שעלו מן הרחצה שכלם מתאימות ושכלה אין בהם.\u0004 שהפירוש הוא, שהשינים דומות לגוונין שבעין הנקראים \u0003עדר הקצובות,\u0004 בעת שמקבלים הלבן מהעין העליונה דא״א הנבחן לרחיצת הגוונים שבעין, והיינו \u0003שעלו מן הרחצה.\u0004 שאז כל הגוונים שהם אדום ושחור וירוק שוים זה לזה, ובחינת מלכות דמדת הדין אינה ניכרת בגוון השחור, להיותם בבחינת הסתלקות מחמת שליטת הלבן כנ״ל. ולפיכך, \u0003ושכלה אין בהם,\u0004 כי אם המלכות דמדת הדין היתה ניכרת בשחור שבעין, היו כל האורות מסתלקים, וע״כ היא נבחנת \u0003לשכולה,\u0004 שמשכלת כל האורות, וכיון שאינה ניכרת מחמת שליטת הלבן אומר עליה הכתוב, \u0003ושכלה אין בהם.\u0004"],[7,"","ושואל, \u0003ומה דאמר שניך כעדר הקצובות,\u0004 שמשמע שיש קצבה לכל גוון וגוון שבעין, כי ע״כ נקראים קצובות, \u0003ואת אמרת שכלם מתאימות,\u0004 שיורה שאין בהם הפרש בין זה לזה. ומשיב, \u0003כלומר, חוורא דלהון כההוא חוורא דעיינין, כד אסחן בחוורתא דעינא עלאה.\u0004 כי שניך כעדר הקצובות, סובב על גווני העין בעת שהלבן שולט בכל אחד ואחד, ולא על היותם משונים זו מזו. וע״ז אומר שיניך וגו׳."],[8,"ודא זמינין למנדע","וכו׳: ואור הזה הלבן שבעין עתידים הצדיקים לדעת ולראות ברוח החכמה, כש״א, כי \u0003עין בעין\u0004 יראו, דהיינו הארת הלבן של \u0003עין\u0004 דא״א \u0003בעין\u0004 דז״א. מתי, בשוב ה׳ ציון. וכתוב, אשר \u0003עין בעין\u0004 נראה אתה ה'. ואז פקיחת עינים הוא לטיב."],[9,"ואית פקיחותא דעיינין","וכו׳: ויש פקיחת עינים לטוב, ויש פקיחת עינים לרע. כלומר, שבעת פקיחת העינים דז״א, יש אז פקיחה מצד אחד לטוב ופקיחה מצד אחד לרע. כמו שכתוב, פקח עיניך וראה שוממותינו וגו', והרי יש כאן פקיחת עינים לטוב ולרע. וכתוב, עיניך תראנה ירושלם נוה שאנן אהל בל יצען בל יסע יתדותיו לנצח, הרי יש כאן פקיחת עינים לטוב ולרע. כי אינם נעשים זה בלי זה."],[9,"","פירוש. באותה העת שהחכמה נגלית בשביל הצדיקים, באותה העת ממש, נגלו יחד עמה דינים קשים ומרים על הרשעים שרוצים להמשיכה ממעלה למטה. כמ״ש לעיל (פקודי אות שע״ו. צו אות קי״ד). וז״ש, \u0003ואית פקיחותא דעיינין לטב ואית פקיחותא דעיינין לביש.\u0004 שב׳ פקיחת עינים אלו נעשים בעת אחת, כנ״ל. שכתוב, \u0003פקח עיניך וראה שוממותינו והעיר אשר נקרא שמך עליה, ודא הכא לטב ולביש,\u0004 כי אומר \u0003וראה שוממותינו\u0004 שזו היא פקיחת עינים לרע, דהיינו לראות בשממה, שהיא מחמת מעשים של הרשעים. ואח״כ \u0003והעיר אשר נקרא שמך עליה,\u0004 שזו היא פקיחת עינים לטוב, דהיינו לראות העיר וגו׳. וכן כתוב, \u0003עיניך תראנה ירושלים נוה שאנן אהל בל יצען בל יסע יתדותיו לנצח, הא הכא לטב ולביש,\u0004 כי \u0003עיניך תראנה ירושלים,\u0004 היא פקיחת עינים לטוב. \u0003אהל בל יצען\u0004 וגו' היא פקיחת עינים לרע, והכתוב נותן טעם למה מגלה כאן השגחת הדינים, שהוא כדי ה \u0003אהל\u0004 שהיא השכינה \u0003בל יצען בל יסע יתדותיו לנצח,\u0004 דהיינו כדי להפיל אימה ופחד על הרשעים שלא יפגמו עוד בהשכינה ח\"ו. וז\"ש, \u0003דלא אתעביד דא בלא דא,\u0004 שלא נעשה גילוי החכמה לצדיקים בלי גילוי דינים הקשים על הרשעים, מטעם האמור."],[10,"תנא בצניעותא דספרא","וכו׳: למדנו בספרא דצניעותא, מהו, עיניך תראנה ירושלים נוה שאנן. וכי ירושלים היא נוה שאנן, והרי כתוב, צדק ילין בה, שהוא דינים הנקראים צדק. ובמקום שנמצא צדק אין שם שקט ולא שאנן. ומשיב, אלא עיניך תראנה ירושלים נוה שאנן, הנה \u0003נוה שאנן,\u0004 נאמר לעתיק יומין. כי העין ההיא של עתיק יומין שהיא כולה לבנה (כנ״ל אות מ״ו) היא שקטה ושאננה שאין משם דין כלל. שהיא עין הרחמים, עין שאינה נוסעת מהשגחה זו של רחמים להשגחה אחרת של דין. ומשום זה כתוב, \u0003עינך תראנה\u0004 חסר \u0003י',\u0004 ולא כתוב עיניך. כי שתי עינים דא״א נחשבות לאחת, (כנ״ל אות מ״ב) ושיעור הכתוב הוא, שעין א״א, שהיא נוה שאנן, תשפיע ותסתכל בירושלים, שהיא המלכות. ומה שאומר ירושלים, ולא ציון, דהיינו שאינו אומר, עיניך תראנה ציון. כך צריך להיות, כדי לכפות הדין הנמצא בה, ולרחם עליה. פי׳ כי מבחינת הרחמים שבמלכות היא נקראת ציון, ומבחינת הדין היא נקראת ירושלים. וכדי להמתיק מדת הדין שבמלכות, אומר עיניך תראנה ירושלים."]],[]],[["וְתָאנָא, כְּתִיב (דברים י״א:י״ב) עֵינֵי ה' אֱלֹהֶיךָ בָּהּ מֵרֵשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה, (הדא הוא דכתיב צדק ילין בה דבה אשתכחו גזרי דדינין יתיר מכל שאר אתרי) (נ\"א דכתיב צדק ילין בה דבה אשתכחו גזרי דדינין יתיר מכל שאר אתרי ותאנא, כתיב (דברים י״א:י״ב) עיני ה' אלהיך בה מרשית השנה ועד אחרית שנה) וּלְזִמְנָא דְּאָתֵי, יִשְׁתְּכַּח בָּהּ עֵינָא חַד דְּרַחֲמֵי. עֵינָא דְּעַתִּיקָא דְּעַתִּיקִין הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ד:ז׳) וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ. כֵּיוָן דְּאָמַר רַחֲמִים, מַהוּ גְּדוֹלִים. אֶלָּא אִית רַחֲמֵי, וְאִית רַחֲמֵי. רַחֲמֵי דְּעַתִּיק דְּעַתִּיקִין, אִינּוּן אִקְרוּן רַחֲמִים גְּדוֹלִים. רַחֲמֵי דִּזְעֵיר אַנְפִּין, אִקְרוּן רַחֲמִים סְתָם. (מהנ\"א הוא: משום דאית ביה ימינא ושמאלא, דינא ורחמי) וּבְגִין כָּךְ וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ, דְּעַתִּיק יוֹמִין.","תָּאנָא בְּהָנֵי עַיְינִין, בִּתְרֵין גַּוְונִין מִנַּיְיהוּ, בְּסוּמָקָא וְאוּכָמָא, שָׁרָאן תְּרֵין דִּמְעִין. וְכַד בָּעֵי קוּדְשָׁא דְּקוּדְשִׁין לְרַחֲמָא עַל יִשְׂרָאֵל, אָחִית תְּרֵין דִּמְעִין, לְאִתְבַּסְּמָא בְּיַמָּא רַבָּא. מַאן יַמָּא רַבָּא. יַמָּא דְּחָכְמְתָא עִלָּאָה. כְּלוֹמַר דְּיִתְסְחוּן בְּנַהֲרָא (ס\"א בחוורא) בְּמַבּוּעָא דְּנָפִיק מֵחָכְמָתָא רַבָּא, וּמְרַחֵם לְהוּ לְיִשְׂרָאֵל.","חוֹטָמָא. תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, חוֹטָמָא דִּזְעֵיר אַנְפִּין. בְּחוֹטָמָא אִשְׁתְּמוֹדַע פַּרְצוּפָא. בְּהַאי חוֹטָמָא אִתְפָּרְשָׁא מִלָּה דִּכְתִּיב, (שמואל ב כ״ב:ט׳) עָלָה עָשָׁן בְּאַפּוֹ וְגוֹ'. עָלָה עָשָׁן בְּאַפּוֹ, בְּהַאי תְּנָנָא, אִתְכְּלָלוּ אֶשָּׁא, וְגַחֲלֵי דְּנוּרָא. דְּלֵית (ס\"א בחוטמא אשתמודע פרצופא תלת שלהובין מתוקדן בנוקבוי מהאי חוטמא אתפשטן תלת גווני תננא ואשא וגחלי דנורא דכתיב, (שמואל ב כ״ב:ט׳) עלה עשן באפו. ולית) תְּנָנָא בְּלָא אֶשָּׁא, וְלָא אֶשָּׁא בְּלָא תְּנָנָא. וְכֻלְּהוּ אִסְתְּלִיקוּ (ס\"א אתדליקו) וְנָפְקֵי מֵחוֹטָמוֹי.","וְתָאנָא, כַּד אִתְחַבָּרוּ תְּלַת אִלֵּין, דִּכְלִילָן בְּהַאי תְּנָנָא, דְּנָפִיק מֵחוּטָמָא. אִתְקָמַט חוֹטָמָא, וְנָשִׁיב וְנָפִיק תְּנָנָא אוּכָמָא וְסוּמָקָא. וּבֵין תְּרֵי (נ\"א בתרי) גְּוָונֵי. וְקָרֵינָן לֵיהּ, אַף וְחֵימָה וּמַשְׁחִית. וְאִי תֵּימָא אַף וְחֵימָה כְּתִּיב, (דברים ט׳:י״ט) כִּי יָגוֹרְתִּי מִפְּנֵי הָאַף וְהַחֵימָה, דְּאִינּוּן תְּנָנָא אוּכָמָא וְסוּמָקָא, מַשְׁחִית מְנָא לָן. דִּכְתִּיב, (בראשית י״ג:י׳) לִפְנֵי שַׁחֵת יְיָ אֶת סְדוֹם וְאֶת עֲמוֹרָה. שַׁחֵת הַמַּשְׁחִית, בְּנוּרָא דָּלִיק מוֹקְדָא.","וְתָאנָא, חָמֵשׁ גְּבוּרָאן אִינּוּן, בְּהַאי זְעֵיר אַנְפִּין. וְאִסְתְּלָּקוּ לְאֶלֶף וְאַרְבַּע מְאָה גְּבוּרָאן. וּמִתְפַּשְׁטָאן בְּחוֹטָמוֹי. בְּפוּמָא. בִּדְרוֹעוֹי. בִּידִין. בְּאֶצְבְּעִין. וּבְגִין כָּךְ כְּתִיב, (תהילים ק״ו:ב׳) מִי יְמַלֵּל גְּבוּרוֹת יְיָ. גְבוּרֹת כְּתִיב, כְּתִיב הָכָא גְּבוּרוֹת, וּכְתִיב הָתָם, (דברי הימים א כ״ט:י״א) לְךָ יְיָ הַגְּדוּלָה וְהַגְּבוּרָה. אֶלָּא הָכִי תָּאנָא, כַּד אִתְחַבְּרָאן כֻּלְּהוּ גְּבוּרָאן כַּחֲדָא, אִתְקְרֵי גְּבוּרָה חֲדָא.","וְכֻלְּהוּ גְּבוּרָאן, שְׁרִיאָן לְנַחְתָּא מֵחוֹטָמוֹי. וּמֵהַאי תַּלְיָין, אֶלֶף (אלפין) וְאַרְבַּע מְאָה רִבּוֹא, לְכָל חַד מִנַּיְיהוּ. וּבְהַאי תְּנָנָא דְּאַפִּיק מֵחוֹטָמוֹי, תַּלְיָין אֶלֶף (אלפין רבוא) וְאַרְבַּע מְאָה (וחמש) דִּסְטַר גְּבוּרָה דָּא. וְכֻלְּהוּ גְּבוּרָאן תַּלְיָין מֵהַאי חוֹטָמָא, דִּכְתִּיב, (תהילים קמ״ה:ד׳) דּוֹר לְדוֹר יְשַׁבַּח מַעֲשֶׂיךָ וְגוֹ'. וְכַד שָׁארֵי גְּבוּרָה דָּא, כֻּלְּהוּ גְּבוּרָאן מִתְלַהֲטָן וְשָׁטָאן, (נ\"א ונחתין) עַד דְּנַחְתָּן לְלַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת.","כְּתִיב, (בראשית י״ט:י״ג) כִּי מַשְׁחִיתִים אֲנַחְנוּ אֶת הַמָּקוֹם הַזֶּה. וּכְתִיב (בראשית י״ג:י׳) לִפְנֵי שַׁחֵת יְיָ אֶת סְדוֹם אֶת עֲמוֹרָה. וּכְתִיב, (בראשית י״ט:כ״ד) וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה. אֶלָּא הָכִי תָּאנָא, לֹא דַּיָּין לָרְשָׁעִים וְכוּ', אֶלָּא דִּמְהַפְּכֵי מִדַּת רַחֲמִים לְמִדַּת הַדִּין.","וְהֵיאַךְ מְהַפְּכֵי, וְהָא כְּתִיב (מלאכי ג׳:ו׳) אֲנִי יְיָ לֹא שָׁנִיתִי. אֶלָּא בְּכָל זִמְנָא דְּעַתִּיק דְּעַתִּיקֵי, רֵישָׁא חִוָּורָא, (אתגלייא) רַעֲוָא דְּרַעֲוִין, אִתְגַּלְיָין, רַחֲמִין רַבְרְבִין אִשְׁתְּכָחוּ בְּכֹלָּא. וּבְשַׁעֲתָא דְּלָא אִתְגַּלְיָיא, כָּל זַיְּינִין (ס\"א דינין) דִּזְעֵיר אַפִּין זְמִינִין, וְכִבְיָכוֹל רַחֲמֵי, עָבִיד דִּינָא, הַהוּא עַתִּיקָא דְּכֹלָּא.","דְּתַנְיָא, כַּד אִתְגַּלְיָיא עַתִּיקָא דְּעַתִּיקִין, רַעֲוָא דְּרַעֲוִין, כֻּלְּהוּ בּוֹצִינֵי דְּאִתְקְרוּן בִּשְׁמָא דָּא, נְהִירִין. וְרַחֲמֵי אִשְׁתְּכָחוּ בְּכֹלָּא. וּבְשַׁעֲתָא דְּלָא אִתְגְּלֵי טְמִירָא דִּטְמִירִין, וְלָא אִתְנַהֲרָן אִלֵּין בּוֹצִינֵי. מִתְעָרִין דִּינִין, וְאִתְעָבִיד דִּינָא. מַאן גָּרִים לְהַאי דִּינָא. רַעֲוָא דְּרַעֲוִין דְּלָא אִתְגְּלֵי, וּבְגִין כָּךְ מְהַפְּכִין חַיָּיבַיָּא רַחֲמֵי לְדִינָא. וּמָה דְּאָמַר הָכָא, מֵאֵת יְיָ מִן הַשָּׁמָיִם. בִּזְעֵיר אַפִּין אִתְּמַר. וּמַשְׁמַע דִּכְתִּיב מִן הַשָּׁמָיִם, אֵשׁ וּמַיִם. רַחֲמֵי וְדִינָא. לְאַפָּקָא מַאן דְּלֵית בֵּיהּ דִּינָא כְּלַל."],[[0,"ותאנא כתיב עיני","וגו׳: ולמדנו, כתוב, עיני ה׳ אלקיך בה מרשית השנה ועד אחרית השנה. דהיינו עיני ז״א שיש בהם השגחה לטוב והשגחה לרע, שה״ס ב׳ עינים אחת לרחמים ואחת לדין, ולעתיד לבא תמצא בה, במלכות, עין אחת של רחמים, ולא ההשגחה של דין, שהוא העין של עתיקא דעתקין, דהיינו דא״א, ז״ש וברחמים גדולים אקבצך. שואל, כיון שאמר רחמים, למה נאמר גדולים. ומשיב, אלא יש רחמים ויש רחמים, יש רחמים דעתיקא דעתיקים והם נקראים רחמים גדולים. ויש רחמים דז״א, שהם נקראים רחמים סתם. ומשום זה, אומר הכתוב, \u0003וברחמים גדולים\u0004 אקבצך, דהיינו רחמים דעתיק יומין."],[1,"תאנא בהני עיינין","וכו׳: למדנו באלו עינים. דז״א, בשני גוונים שבהם, באדום ושחור, שורות שתי דמעות. וכשרוצה קדש הקדשים לרחם על ישראל מוריד שתי דמעות להתבשם בים הגדול. מהו ים הגדול. הוא ים החכמה העליונה, שה״ס הבינה החוזרת לחכמה, ושתי דמעות שמוריד שמה, כלומר, כדי שיתרחצו בלבן, במבוע היוצא מחכמה הגדולה, ומרחם על ישראל."],[1,"","פירוש. כי אומר לעיל (אות רט״ז) \u0003וכד אתגלי חוורא\u0004 וכו', \u0003כל אינון גוונין לא משתכחין, ומשתקעין לתתא,\u0004 וכן (באות רי\"ז) \u0003ובגין כך אסתלקו כל מאריהון דסומקא ואוכמא, דאינון תאומין, כחדא, וכו'. מתערבין דא בדא\u0004 וכו', ומשום שסומקא ואוכמא \u0003מתערבים\u0004 זה בזה הם נקראים שתי \u0003דמעות,\u0004 מלשון המדמע והמנסך, וז״ש, \u0003בסומקא ואוכמא שראן תרין דמעין,\u0004 דהיינו בשעה שנגלה עליהם הלבן מעין א״א, אז מסתלקים סומקא ואוכמא ומתערבים זה בזה בסו״ה \u0003שכלם מתאימות ושכלה אין בהם,\u0004 ונעשים \u0003שתי דמעות.\u0004 וז״ש כאן, \u0003וכד בעי קודשא דקודשין\u0004 שהוא א״א, לרחם על ישראל, \u0003אחית תרי דמעין,\u0004 שהם סומקא ואוכמא, מעיני ז״א, עי״ז שמשפיע אליו מלבן שבעינא פקיחא שלו, והן מסתלקות ומתערבות זו בזו בתוך הים הגדול, שהוא הבינה, ואז מתגלה הארת החכמה לישראל. וז״ש \u0003דיתסחון בחוורא במבועא דנפיק מחכמתא רבא,\u0004 שע״י רחיצת העינים בלבן דעין א״א, הנה נעשות למבוע, שיוצאת ממנו חכמה גדולה, ובזה נמצא, \u0003ומרחם להו לישראל.\u0004"],[2,"חוטמא, תאנא בצניעותא","וכו׳: החוטם דז״א. למדנו בספרא דצניעותא, החוטם דז״א. בחוטם ניכר הפרצוף. בחוטם הזה נתבאר דבר הכתוב, עלה \u0003עשן\u0004 באפו \u0003ואש\u0004 מפיו תאכל \u0003גחלים\u0004 בערו ממנו. \u0003עלה עשן באפו,\u0004 הנה \u0003בעשן\u0004 הזה נכללו \u0003אש, וגחלי\u0004 אש. כי אין עשן בלא אש ואין אש בלא עשן, וכולם עולים ויוצאים מן החוטם."],[2,"","פירוש. ב׳ עינים וחוטמא, ה״ס ג׳ קוין של הארת החכמה המכונים עינים, והחוטם הוא הקו האמצעי המיחד ימין ושמאל דעינים זו בזו ועושה שלום ביניהם שהימין יאיר ממעלה למטה והשמאל ממטה למעלה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) ומשום שנתמעט השמאל ממטה למעלה, ירדה החכמה מג״ר לו\"ק, וג' קוין של העינים ירדו מבחינת חב״ד לבחינת חג״ת. באפן שאין הארת החכמה מושפעת מעינים לתחתונים אלא על ידי החוטם, שהוא ת״ת. והקו האמצעי."],[2,"","ומטעם זה מתקבצים כל הדינים בחוטם, כי אין גילוי חכמה אלא עם דינים דקו שמאל (כנ״ל אות רי״ט) בסוד פקיחת עינים לטוב ולרע \u0003דלא אתעביד דא בלא דא,\u0004 ע״ש. ונמצא מקום כל אלו הדינים הם בחוטם, כי שם מקום גילוי של החכמה. וכללות הדינים הם שלשה בחינות, שה״ס סומקא, ואוכמא, המבוארים בגווני העינים (לעיל אות רי״ד) ועוד יש בחינה שלישית שה״ס פנימיות גוון אוכמא, שה״ס מלכות דמדת הדין (כמ״ש באות רי״ז) וז״ש, \u0003בחוטמא אשתמודע פרצופא,\u0004 שהחוטם הוא קו אמצעי שבו נודעים הפנים. כלומר סוד החכמה המאירה בסו״ה חכמת אדם תאיר פניו, אינה נודעת, אלא ע״י החוטם, להיותו קו האמצעי המיחד ימין ושמאל דחכמה, המכונים עינים. כנ״ל. \u0003בהאי חוטמא אתפרשא מלה דכתיב, עלה עשן באפו אש וגו׳ גחלים\u0004 וגו׳, שכל ג׳ מיני דינים אלו המובאים בכתוב הזה, שהם עשן, אש, וגחלים, מתפרשים מן החוטם, להיותו קו אמצעי כנ״ל. כי ה \u0003עשן\u0004 הנאמר באפו, כולל בתוכו \u0003אש וגחלים, דלית תננא בלא אשא ולא אשא בלא תננא,\u0004 כי האש מוכרחת להאחז באיזה דבר, כי בלי אחיזה באיזה דבר אי אפשר לה להגלות. וכשנאחזת ושורפת באיזה דבר, אז עולה עשן, נמצאים כאן ג׳ דברים, הדבר שהאש נאחזת בו, שה״ס גחלים, ואש הנדלק בגחלים. והעשן העולה מהם. הרי שאין אש בלי עשן הכולל את הגחלים המעלים העשן, ואין עשן בלי אש הנאחזת בגחלים (כנ״ל בראשית א׳ שי״ב) ונמצא שהעשן כולל את כולם. כי אין \u0003עשן\u0004 אלא ע״י \u0003אש\u0004 הנאחזת ב \u0003גחלים.\u0004 וכשהכתוב אומר, עלה עשן באפו, הרי הוא כולל כל ג׳ מיני דינים אלו, אשר סומקא ה״ס \u0003אש,\u0004 ואוכמא ה״ס \u0003עשן,\u0004 שהאש כלול בו. ופנימיות האוכמא, שה״ס המלכות דמדת הדין ה״ס \u0003גחלים,\u0004 שבו נאחזת האש דסומקא ונעשה עשן, שה״ס אוכמא. וז״ש \u0003וכלהו,\u0004 אש ועשן וגחלים, \u0003אסתליקו ונפקי מחוטמוי,\u0004 כי בעת גילוי החכמה מן החוטם מתעוררים כל הדינים האלו, עד שהשמאל מתיחד עם הקו הימיני, והחכמה מתלבשת בחסדים ואז מתבטלים הדינים."],[3,"ותאנא כד אתחברו","וכו': ולמדנו, כשנתחברו ג׳ אלו, הכלולים בעשן הזה היוצא מן החוטם, החוטם נקמט ונעשה קצר, שזה רומז, שהחכמה שה״ס ארוך אינה מאירה בו, וע״כ הוא קצר. ונושב ויוצא עשן שהוא אוכמא וסומקא, ובין שני הגוונים, (המבוארים לעיל אות רי״ג ורי״ד ורי״ז ע״ש) וקוראים אותם אף וחמה ומשחית. ואם תאמר, אף וחמה כתוב, כי יגורתי מפני האף והחמה, שהם העשן האדום והשחור, משחית מאין לנו. ומשיב, שכתוב לפני \u0003שחת\u0004 ה׳ את סדום ואת עמורה, שהמשחית שחת את סדום ועמורה, במדורת אש שורפת, \u0003אתקמט\u0004 הוא מלשון הקמטים שבצואר (נגעים ו')."],[3,"","פירוש. בשעה שג׳ דינים הנ״ל מתחברים בחוטם אין החכמה יכולה להאיר שם עד שנמשך הלבן, שה״ס החסדים, מעינא פקיחא (כנ\"ל אות רי״ד) ולפיכך \u0003אתקמט חוטמא,\u0004 שנסתלקה אריכות החוטם, שה״ס חכמה המכונה ארוך. \u0003ונשיב ונפיק תננא אוכמא וסומקא,\u0004 שהם דינים של המלכות שהם שחור, ודינין של קו שמאל דבינה, שהם אדום (כנ״ל אות רי״ד) \u0003ובין תרי גווני,\u0004 היינו פנימית האוכמא שאינה נראית לחוץ, וכלולה בין ב׳ גוונים, שה״ס המלכות דמדת הדין (כנ״ל אות רי״ז). \u0003וקרינן ליה אף וחימה ומשחית\u0004 אשר אף, ה״ס סומקא, חימה, ה״ס אוכמא, ומשחית ה״ס מלכות דמדת הדין. וז״ש, \u0003שחת המשחית בנורא דליק מוקדא,\u0004 כי ה״ס המדורה, שבה האש שורף ומשחית הכל. דהיינו המלכות דמדת הדין שהיא שורש כל הדינים, והיא סוד הגחלים שבהם האש שורף וע״כ נבחנת כמדורת אש."],[4,"ותאנא חמש גבוראן","וכו׳: ולמדנו, חמש גבורות הן בז״א, ועולים לאלף ות׳ גבורות. ומתפשטות בחוטם, בפה, בזרועות, בידים, ובאצבעות. ומשום זה כתוב, מי ימלל גבורות ה'. גבורת כתוב, בלא \u0003ו׳\u0004 המורה על רבים, כתוב כאן גבורת בלא \u0003ו',\u0004 וכתוב שם, לך ה׳ הגדולה והגבורה, שכתוב ג״כ גבורה, בלשון יחידה, ואתה אומר שיש אלף ות׳ גבורות. ומשיב, אלא כך למדנו, כשמתחברות כל הגבורות יחד נקראות גבורה אחת. וע״כ נאמר גבורה בלשון יחידה."],[4,"","פירוש. ה׳ גבורות הן כנגד חג״ת נ״ה, ובסוד נקודת השורק שנמשכות ג״ר דשמאל, הן אז קו א׳ וחצי קו שבשמאל דג״ר, שהם בינה וחציה השמאלי של הדעת (כנ״ל אות ר״ז) וג״ר דחכמה ה״ס ג׳ אלפים, וחצים ה״ס אלף וחצי, והמלכות דשמאל דדעת חסרה ע״כ עולים אלף ות׳ גבורות. וז\"ש, \u0003חמש גבוראן וכו' ואסתלקו לאלף וארבע מאה.\u0004 ומקום התפשטותם הוא בו״ק דראש, שה״ס חוטם פה, וכן בידים, שבסוד שאו ידיכם קודש נעשים לבחינת חב״ד, וכל יד נכללה מחב״ד, שהאצבעות הן חכמה, והיד היא בינה, והזרוע ה״ס דעת. כי בכל מקום שיש בחינת ג״ר מתפשטות בהכרח הגבורות, שה״ס קו וחצי דשמאל, שהחכמה נמשכת מהם, כי החכמה דאו״י נסתמה בחכמה סתימאה דא״א, וכל החכמה שבג\"ר נמשכת רק מקו שמאל דבינה שחזרה לחכמה. שה״ס אלף ות׳ גבורות. כנ״ל. וז״ש, \u0003ומתפשטאן בחוטמוי, בפומא, בדרועוי, בידין, באצבען.\u0004 דהיינו בכל מקום שמאירים הג״ר, מתפשטים קו וחצי דצד שמאל הנ״ל, שה״ס אלף ת׳ גבורות."],[5,"וכלהו גבוראן שריאן","וכו׳: וכל הגבורות מתחילות לצאת מן החוטם. ומן החוטם תלויות אלף ות׳ רבוא לכל אחד מה׳ גבורות שבחוטם. ובעשן הזה שמוציא מן החוטם, תלויות אלף ות׳ של צד הגבורה הזו. וכל הגבורות תלויות מחוטם הזה, שכתוב דור לדור ישבח מעשיך וגבורותיך יגידו. וכששורה גבורה זו שבחוטם, כל הגבורות מתלהטות ומשוטטות עד שיורדות ללהט החרב המתהפכת."],[5,"","פירוש. כבר נתבאר שאין החכמה דקו שמאל מאירה אלא עם גילוי דינים. וכיון שתחלת גילוי החכמה היא מהחוטם, להיותו קו אמצעי דעינים, כנ״ל, נמצא שתחילת הדינים נמצאים ג״כ מן החוטם. וז״ש, \u0003וכלהו גבוראן שריאן לנחתא מחוטמוי,\u0004 דהיינו משום שמשם מתחילה הארת החכמה. \u0003ומהאי תליין אלף ות' רבוא לכל חד מנייהו.\u0004 היינו כשהחכמה דקו וחצי שבשמאל, שה״ס אלף ות׳. מתלבשים בחסדים הנמשכים מעין א״א, ואז נעשים בסוד \u0003רבוא,\u0004 והם אלף ות׳ רבוא. אמנם מטרם שמתלבשים בחסדים שיוצאים הדינים בסוד עשן ואש מחוטם, אז אינם אלא \u0003אלף ות׳\u0004 בלבד, ואינם במספר \u0003רבוא.\u0004 וז״ש, \u0003ובהאי תננא דאפיק מחוטמוי\u0004 שהחכמה שבחוטם היא אז משמאל בלבד בלא לבוש מן החסדים, \u0003תליין אלף ות׳ דסטר גבורה דא,\u0004 אין בהם רבוא, אלא אלף ות׳ של צד השמאל דג״ר בלבד."],[6,"כתיב בי משחיתים","וגו׳: כתוב, כי משחיתים אנחנו את המקום הזה, דהיינו המלאכים דמדת הדין. וכתוב, לפני שחת ה׳ את סדום ואת עמורה. שנאמר הויה, שהוא מדת הרחמים. וכתוב והויה המטיר על סדום ועל עמורה, שה״ס ז\"א ובית דינו, הנקראים והויה. למה נאמר פעם מדת הדין ופעם מדת הרחמים. ומשיב. אלא כך למדנו, לא די לרשעים וכו' אלא שמהפכים מדת הדין למדת הרחמים, שמדת הרחמים פועלת בהם דינים."],[7,"והאיך מהפכי והא","וכו׳: שואל, ואיך מהפכים מדת הדין למדת הרחמים, והרי כתוב, אני הויה לא שניתי. ומשיב, אלא בכל זמן שעתיק דעתיקין, ראש הלבן שה״ס כתר דא״א, רעוא דרעוין, שה״ס מצח דא״א, מתגלים, נמצאים רחמים גדולים בכל. ובשעה שאינם מתגלים, כל הדינים דז״א מוכנים, וכביכול, ז״א, שהוא רחמים העתיק מכל עושה אותו דין."],[8,"דתניא כד אתגליא","וכו׳: כי למדנו, כשמתגלה עתיק דעתיקין, רעוא דרעוין, כל הנרות הנקראות בשם הזה של עתיק, מאירים, ורחמים נמצאים בכל. ובשעה שאינו מתגלה הנסתר שבנסתרים ואלו הנרות, דהיינו הספירות שלו, אינם מאירים, דינים מתעוררים ונעשה דין. מי גרם את הדין הזה. הוא רעוא דרעוין שלא נגלה. ומשום זה מהפכים הרשעים הרחמים לדין, כי מפאת חטאם לא נגלה עתיק יומין על ז״א, ואז ז״א שנקרא הויה, פועל דינים. ומה שאמר כאן, והויה המטיר על סדום וגו׳ מאת הויה מן השמים. נאמר בז״א, וזה משמע משכתוב \u0003מן השמים\u0004 שהוא ז״א הנקרא שמים, כי שמים הוא אותיות אש ומים, שמורים על רחמים ודין. להוציא מי שאין בו דין כלל שאינו מהפך לדין."]],[]],[["תָּאנָא, הַאי חוֹטָמָא זְעֵיר. וְכַד שָׁארֵי תְּנָנָא לְאַפָּקָא, נָפִיק בִּבְהִילוּ, וְאִתְעָבֵד דִּינָא. וּמַאן מְעַכֵּב לְהַאי חוֹטָמָא דְּלָא יָפִיק תְּנָנָא, חוֹטָמָא דְּעַתִּיקָא קַדִּישָׁא, דְּהוּא אִקְרֵי אֶרֶךְ אַפַּיִם מִכֹּלָּא.","וְהַיְינוּ רָזָא דְּתָנֵינָן, (שמות לד) יְיָ יְיָ פָּסִיק טַעֲמָא בְּגַוַויְיהוּ. בְּכֻלְּהוּ אֲתָר דִּשְׁמָא אַדְכַּר תְּרֵי זִמְנֵי, פָּסִיק טַעֲמָא בְּגַוַויְיהוּ, כְּגוֹן (בראשית כ״ב:י״א) אַבְרָהָם אַבְרָהָם. (בראשית מ״ו:ב׳) יַעֲקֹב יַעֲקֹב. (שמואל א ג׳:י׳) שְׁמוּאֵל שְׁמוּאֵל. כֻּלְּהוּ פָּסִיק טַעֲמָא בְּגַוַויְיהוּ. חוּץ מִמֹּשֶׁה מֹשֶׁה, דְּלָא פָּסִיק טַעֲמָא בְּגַוַויְיהוּ. מַאי טַעְמָא. אַבְרָהָם אַבְרָהָם, בַּתְרָאָה שְׁלִים, קַדְמָאָה לָא שְׁלִים, דְּהַשְׁתָּא שְׁלִים בְּעֶשֶׂר נִסְיוֹנֵי, וּבְגִין כַּךְ פָּסִיק טַעֲמָא בְּגַוַויְיהוּ, דְּהַשְׁתָּא לָא הֲוָה אִיהוּ כִּדְקַדְמֵיתָא.","יַעֲקֹב יַעֲקֹב, בַּתְרָאָה שְׁלִים, קַדְמָאָה לָא שְׁלִים, דְּהַשְׁתָּא אִתְבָּשָּׂר בְּיוֹסֵף, וְשָׁרַאת עָלֵיהּ שְׁכִינְתָּא. וְעוֹד, דְּהַשְׁתָּא אִשְׁתְּלִים בְּאַרְעָא, אִילָנָא קַדִּישָׁא כְּגַוְונָא דִּלְעֵילָּא, בִּתְרֵיסַר תְּחוּמִין, בְּשִׁבְעִין עַנְפִין, מַה דְּלָא הֲוָה בְּקַדְמִיתָא. וּבְגִינֵי כַּךְ, בַּתְרָאָה שְׁלִים, קַדְמָאָה לָא שְׁלִים, וּפָסִיק טַעֲמָא בְּגַוַויְיהוּ. שְׁמוּאֵל שְׁמוּאֵל, טַעֲמָא פָּסִיק בְּגַוִיהּ. מַאי טַעְמָא. בַּתְרָאָה שְׁלִים, קַדְמָאָה לָא שְׁלִים, דְּהַשְׁתָּא הוּא נְבִיאָה, וְקוֹדֶם לָכֵן לָא הֲוָה נְבִיאָה. אֲבָל מֹשֶׁה מֹשֶׁה, לָא אַפְסִיק טַעֲמָא בְּגַוַויְיהוּ, דְּמִיּוֹמָא דְּאִתְיְלִיד, שְׁלִים הֲוָה. דִּכְתִּיב, (שמות ב׳:ב׳) וַתֵּרֶא אוֹתוֹ כִּי טוֹב הוּא.","אוּף הָכָא יְיָ יְיָ, פָּסִיק טַעֲמָא בְּגַוַּויְיהוּ, קַדְמָאָה שְׁלִים, בַּתְרָאָה שְׁלִים בְּכֻלְּהוּ. וּמֹשֶׁה, בַּאֲתָר דִּינָא אָמַר, לְנַחְתָּא לוֹן מֵעַתִּיקָא קַדִּישָׁא, רַחֲמִין לִזְעֵיר אַנְפִּין. דְּהָכִי תָּנֵינָן, כַּמָה חֵילָא דְּמֹשֶׁה, דְּאָחִית מְכִילָן דְּרַחֲמֵי לְתַתָּא. וְכַד אִתְגְּלֵי עַתִּיקָא בִּזְעֵיר אַפִּין, כֹּלָּא בְּרַחֲמֵי אִתְחָזוּן. וְחוֹטָמָא אִשְׁתְּכִיךְ, וָאֶשָּׁא וּתְנָנָא לָא נָפִיק, כְּמָה דְאַתְּ אָמֵר (ישעיהו מ״ח:ט׳) וּתְהִלָּתִי אֶחטָם לָךְ.","וְתָאנָא, בִּתְרֵין נוּקְבִין דְּחוֹטָמָא, בְּחַד נוּקְבָּא נָפִיק תְּנָנָא, לָהִיט, וּמִשְׁתַּקְּעָא בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא. וּמֵחָד נוּקְבָּא, נָפִיק אֶשָּׁא דְּאוֹקִיד בְּשַׁלְהוֹבוֹי, וּמִתְלַהֲטָא (בארבע אלף) בְּאֶלֶף וְאַרְבַּע מְאָה עָלְמִין דְּבִסְטַר שְׂמָאלָא. וּמַאן דְּגָרִים לְקָרְבָא בְּהַאי, אִקְרֵי אֵשׁ יְיָ. אֶשָּׁא דְּאַכְלָא וְאוֹקִיד כָּל שְׁאַר אֶשִּׁין. וְהַאי אֶשָּׁא לָא אִתְבְּסָם, אֶלָּא בְּאֶשָּׁא דְּמַדְבְּחָא. וְהַאי תְּנָנָא דְּנָפִיק מִנּוּקְבָא אַחֲרָא, לָא אִתְבְּסָם אֶלָּא בִּתְנָנָא דְּקָרְבְּנָא. (דמדבחא).","וְכֹלָּא תַּלְיָיא בְּחוֹטָמָא, בְּגִין כַּךְ כְּתִיב, (בראשית ח׳:כ״א) וַיָּרַח יְיָ אֶת רֵיחַ הַנִּיחֹחַ. דְּכֹלָּא בְּחוֹטָמָא תַּלְיָין, לְאָרְחָא הַאי חוֹטָמָא, בִּתְנָנָא, וְאֶשָּׁא סוּמָקָא. וּבְגִין כַּךְ אִתְקַבָּל בְּרַעֲוָא. וְהַאי (הוא) דִּכְתִּיב, (במדבר י״ב:ט׳) וַיִּחַר אַף יְיָ. (דברים י״א:י״ז) וְחָרָה אַף יְיָ. (שמות כ״ב:כ״ג) וְחָרָה אַפִּי. (דברים ו׳:ט״ו) פֶּן יֶחרֶה אַף יְיָ. כֹּלָּא בִּזְעֵיר אַפִּין אִתְּמַר, וְלָא בְּעַתִּיקָא. תָּאנָא, כְּתִיב (דניאל ט׳:י״ח) הַטֵּה אֱלֹהַי אָזְנְךָ וּשֲׁמַע הַאי (ס\"א תאנא בצניעותא דספרא דרגא (ס\"א עקימא) עמיקא למשמע טב וביש ודא) אִיהוּ אוּדְנָא דְּאִתְעָבִיד תְּחוֹת שַׂעְרֵי. וְשַׁעְרֵי תַּלְיָין עָלֵיהּ. (ואודנא הוא למשמע) וְאוּדְנָא אִתְעָבִיד בְּרִשׁוּמֵי רְשִׁימִין לְגָאוּ. כְּמָה דְּעֲבִיד (ס\"א דכארי) דַּרְגָּא בְּעַקִימָא, (להאי ולהאי) מַאי טַעְמָא בְּעַקִימָא. (ס\"א בגין דיתעכב קלא לאעלא למוחא ויבחין במוחא ולא בבהילו) בְּגִין לְמִשְׁמַע טַב וּבִישׁ וְתָאנָא, מֵהַאי עֲקִימָא דִּבְגוֹ אוּדְנִין, תַּלְיָין כָּל אִינּוּן מָארֵי דְּגַדְפִין, דִּכְתִּיב בְּהוּ, (קהלת י׳:כ׳) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר.","בְּגוֹ אוּדְנָא, נָטִיף מִג' חַלְלֵי דְּמוֹחָא, לְהַאי נוּקְבָּא דְּאוּדְנִין. וּמֵהַהוּא נְטִיפָא, עָיֵיל קָלָא בְּהַהוּא עֲקִימָא, וְאִתְצְרִיף בְּהַהוּא נְטִיפָא, בֵּין טַב וּבֵין בִּישׁ. טָב, דִּכְתִּיב, (תהילים ס״ט:ל״ד) כִּי שׁוֹמֵעַ אֶל אֶבְיוֹנִים יְיָ. בִּישׁ, דִּכְתִּיב, (במדבר י״א:א׳) וַיִּשְׁמַע יְיָ וַיִּחַר אַפּוֹ וַתִּבְעַר בָּם אֵשׁ יְיָ.","וְהַאי אוּדְנָא סָתִים לְבַר. וַעֲקִימָא עָיֵיל לְגוֹ, לְהַהוּא נוּקְבָּא דִּנְטִיפָא מִן מוֹחָא, בְּגִין לְמִכְנַשׁ קָלָא לְגָאוּ, דְּלָא יִפּוּק לְבַר, וִיהֵא נָטִיר וְסָתִים מִכָּל סִטְרוֹי. בְּגִין כָּךְ הוּא רָזָא. וַוי לְהַהוּא דִּמְגַלֵי רָזִין, דְּמַאן דִּמְגַלֵי רָזִין כְּאִילּוּ אַכְחִישׁ תִּקּוּנָא דִּלְעֵילָּא. דְּאִתְתְּקַן לְמִכְנַשׁ רָזִין, וְלָא יִפְּקוּן לְבַר.","תַּנְיָא, בְּשַׁעֲתָא דְּצַוְוחִין יִשְׂרָאֵל בְּעָאקָא, וְשַׂעְרֵי מִתְגַּלְיָין מֵעַל אוּדְנִין, כְּדֵין עָיֵיל קָלָא בְּאוּדְנִין, בְּהַהוּא נוּקְבָּא דְּנָטִיף מִמּוֹחָא, וְכָנַשׁ (ובטש) בְּמוֹחָא. וְנָפִיק בְּנוּקְבֵי דְּחוֹטָמָא. וְאִתְזְעַר חוֹטָמָא, וְאִתְחַמָּם, (ס\"א ואתקמט) וְנָפִיק אֶשָּׁא וּתְנָנָא מֵאִינּוּן נוּקְבִין, וּמִתְעָרִין כָּל גְּבוּרָאן, וְעָבִיד נוּקְמִין."],[[0,"תאנא האי חוטמא","וכו׳: למדנו חוטם זה דז״א, הוא קצר, וכשהעשן מתחיל לצאת הוא יוצא בחפזון, והדין נעשה. ומי מעכב את החוטם שהדין לא יצא, הוא החוטם של עתיקא קדישא, שהוא נקרא ארך אפים לכל. הן לצדיקים והן לרשעים."],[0,"","פירוש. כמו העינים דז״א, שהם חסרים מקו ימין שהוא חסדים, משום שאצילותן מתחילה מעת שיוצאת הי׳ מאויר, ונתגלה הקו השמאלי, ושולט בלי ימין, (כנ״ל אות ר\"ח) אף החוטם דז״א הוא כך, שמתחיל מקו שמאל, מטעם היותו כולל את העינים, וע״כ כמו שהעמים ממשיכים החסדים מעינא פקיחא דא״א, אף החוטם ממשיך החסדים מחוטם דא״א, כי כל בחינה מקבלת מבחינה שכנגדה בעליון. וז״ש \u0003האי חוטמא זעיר,\u0004 כי מטרם שהחוטם מקבל החסדים מחוטם דא״א להלביש החכמה, אין החכמה מאירה בו, והוא קצר, כי החכמה היא ארוכה. \u0003וכד שארי תננא לאפקא, נפיק בבהילו ואתעביד דינא.\u0004 ואי יוצאים רק הדינים המחוברים עם החכמה, שנקראים כאן עשן, שהם יוצאים להעניש הרשעים הממשיכים החכמה ממעלה למטה, כנ״ל בגוון סומקא שבעינים (באות ר״י) וכמו שהם נקראים שם ז׳ \u0003רהיטין,\u0004 בסו״ה רצוא ושוב, (ע״ש), אף כאן \u0003נפיק בבהילו ואתעביד דינא.\u0004 וז״ש, \u0003ומאן מעכב להאי חוטמא דלא יפיק תננא, חוטמא דעתיקא קדישא,\u0004 כי כל בחינה מקבלת מבחינתו בעליון, וכשהוא מקבל ממנו החסדים מתלבשת בהם החכמה ואז היא מאירה גם בחוטם דז״א, וגם החוטם דז״א נקרא עתה, \u0003ארך אפים\u0004 כמו החוטם דעתיקא קדישא, כי החכמה שה״ס אורך, מאירה בו."],[1,"והיינו רזא דתנינן","וכו׳: והיינו הסוד שלמדנו. הויה הויה, מפסיק טעם ביניהם, דהיינו שיש קו מפסיק בין הויה הא' להויה הב'. וכן בכל מקום שנזכר \u0003שם\u0004 ב׳ פעמים פוסק טעם ביניהם, כמו, אברהם אברהם, יעקב יעקב, שמואל שמואל בכלם מפסיק טעם ביניהם, בין שם הא׳ לשם הב'. חוץ ממשה משה, שאין טעם מפסיק בין משה הא׳ למשה הב׳. מהו הטעם. הוא כי אברהם אברהם הנזכר ב׳ פעמים, יורה, שאברהם הב׳ שלם, ואברהם הא׳ אינו שלם. כי עתה נשלם בעשרה נסיונות. ומטרם זה לא היה שלם. ומשום זה מפסיק הטעם ביניהם, להורות, כי עתה אינו כמו מקודם לכן."],[2,"יעקב יעקב בתראה","וכו׳: וכן יעקב יעקב, יורה שיעקב הב׳ שלם והא׳ אינו שלם. כי עתה נתבשר שיוסף חי, ושרתה עליו השכינה. משא״כ כשהתאבל על יוסף נסתלקה ממנו שכינה. ועוד, כי עתה נשלם בארץ אילן הקדוש, שהוא יעקב, כעין של מעלה, כמו ז״א שיש בו י״ב תחומין, שה״ס י״ב צרופי הויה, וע׳ ענפים, כי י״ב הצרופים מאירים בכל קצה מששה קצוות שלו, והם ע״ב, שה״ס ע׳ סנהדרין וב' עדים. וע' סנהדרין נק׳ ע׳ ענפין. אף האילן הקדוש שבארץ, שה״ס יעקב, כבר הוליד י״ב שבטים שנתפשטו מהם ע׳ נפש, מה שלא היה לו מקודם לכן, ומשום זה, יעקב הב׳ שלם, יעקב הא׳ אינו שלם, וע״כ מפסיק טעם ביניהם. \u0003וכן שמואל שמואל,\u0004 מפסיק טעם ביניהם, מהו הטעם. הוא משום ששמואל הב׳ שלם, שמואל הראשון אינו שלם. כי עתה הוא נביא ומקודם לכן לא היה נביא. אבל \u0003משה משה,\u0004 אין טעם מפסיק ביניהם, כי מיום שנולד היה שלם. שכתוב ותרא אותו כי טוב הוא. דהיינו שתיכף כשנולד שרתה עליו שכינה, שעליה נאמר כי טוב."],[3,"אוף הכא הויה הויה","וכו׳: אף כאן הויה הויה, טעם מפסיק ביניהם, כי הויה הא׳ שלם, אבל הויה הב׳ שלם בכל השלמות, כי הויה הב׳, הוא ז״א בזמן שמקבל מי״ג תקוני דיקנא דא״א ויש לו ג״כ י״ג תקוני דיקנא כמוהו. ומשה, במקום הדין, שהוא ז״א, אמר להוריד י״ג מדות מעתיקא קדישא שהוא רחמים, לז״א. כי כך למדנו. כמה יפה כחו של משה שהוריד י״ג מדות הרחמים מעתיקא קדישא למטה. וכשנגלה עתיקא קדישא בז״א, הכל נראים ברחמים, והחוטם נשקט, ואש ועשן אינם יוצאים. כמש״א ותהלתי א \u0003חטם\u0004 לך. שיורה על הזמן, שהחוטם דז״א הוא ברחמים."],[4,"ותאנא בתרין נוקבין","וכו׳: ולמדנו, בב׳ נקבים של החוטם, בנקב אחד יוצא עשן לוהט ומשתקע בנקב של התהום הגדול. ומנקב אחד יוצא אש שורף בלהביו, ומתלהט באלף ות׳ עולמות שבצד שמאל, דהיינו בקו וחצי דג״ר דשמאל, שהם אלף ות׳ (כנ״ל באות ר״ז) ומי שגורם לקרב לזה, נקרא אש ה'. שהוא אש אוכלת ושורפת כל שאר אשים. ואש זה אינו מתבשם אלא באש המזבח. ואותו העשן היוצא מהנקב האחר של החוטם, אינו מתבשם אלא בעשן הקרבן."],[4,"","פירוש. כבר נתבארו לעיל ג׳ בחינות הדין שישנם בחוטם, שהם סומקא, ואוכמא, ובין תרי גווני. ש \u0003סומקא\u0004 ה״ס אש של השמאל, שה״ס דינין דדכורא. \u0003ואוכמא,\u0004 ה״ס המלכות שמתוך ליקוי הכפול שבה קבלה גוון אוכמא, \u0003ובין ב׳ גווני,\u0004 היינו פנימיות האוכמא שה״ס המלכות דמדת הדין (ע״ש באות רכ״ד). ואותם הדינים מכנה כאן הזהר בשם \u0003אש ועשן, ומאן דגרים לקרבא,\u0004 אשר סומקא ה״ס \u0003אש.\u0004 הנמשך מקו שמאל, \u0003ועשן,\u0004 ה״ס אוכמא. שהיא מלכות הנאחזת באש השמאל. \u0003ומאן דגרים\u0004 למלכות שתאחז באש השמאל, ה״ס מדת הדין שבמלכות דהיינו פנימיות האוכמא. וז״ש \u0003בחד נוקבא נפיק תננא להיט,\u0004 שה״ס המלכות הממותקת שנקראת אוכמא. \u0003ומשתקעא בנוקבא דתהומא רבא.\u0004 כי נקב הוא מלכות, התהום הגדול הוא מלכות שעלתה במקום בינה שה״ס הים הגדול, והגבול שנעשה, ה״ס תהום הגדול (כנ״ל אות רי״ד ע״ש) \u0003ומחד נוקבא נפיק אשא דאוקיד בשלהובי ומתלהטא באלף ות׳ עלמין דבסטר שמאלא,\u0004 שה״ס סומקא שבצד שמאל שעולים אלף ות׳ (כנ״ל באות ר״ז) \u0003ומאן דגרים לקרבא בהאי,\u0004 ה״ס פנימיות של גוון אוכמא, שה״ס מלכות דמדת הדין (כנ״ל באות רי״ד) וז״ש \u0003שהוא אשא דאכלא ואוקיד שאר אשין,\u0004 כי כל הדינים נמשכים ממנו. \u0003ומתבשם באשא דמדבחא,\u0004 שה״ס דינין דשמאל. \u0003והאי תננא\u0004 וכו' \u0003בתננא דקרבנא,\u0004 כי אש המזבח הנאחז בקרבן הוא מעלה עשן, בסוד ריח ניחח (כמ״ש לפנינו)."],[5,"","[א] \u0003וכלא תלייא בחוטמא\u0004 וכו׳: וכל המיתוקים של הדינים תלוים בחוטם, משום זה כתוב, וירח ה׳ את ריח הניחח. כי הכל תלוי בחוטם שהחוטם הזה יריח בעשן ובאש האדום, העולים מן הקרבן. ומשום זה מתקבל הקרבן ברצון. וז״ש ויחר אף ה׳. וחרה אף ה'. וחרה אפי. פן יחרה אף ה׳. הכל נאמר בז״א, ולא בעתיקא. שהוא א״א."],[5,"","פירוש, שהכהן המקריב את הקרבן ממשיך הארת חוטם א״א לחוטם דז״א, שאז מתהפכים כל הדינים לרחמים, ואז מעלה אש ועשן העולים מקרבן, המעוררים הדינים דאש ועשן שבחוטם, שכבר נמתקו ונעשו לרחמים, שפירושו שהחכמה דשמאל כבר נתיחדה עם החסדים שבימין, שאז אותם הדינים דשמאל נעשו לממשיכי החכמה, אלא בסוד ו״ק דחכמה הנקראים \u0003ריח\u0004 והחסדים המלבישים ה״ס ניחוח. וז״ס \u0003וירח ה׳ את ריח הניחח.\u0004 כי נתעוררה השפעת החכמה שנקראת ריח. וז״ש, \u0003דכלא בחוטמא תליין לארחא\u0004 וכו', כי אין החכמה מושפעת אלא מן החוטם כנ״ל, והיינו בזמן שמקבל הארת חוטם דא״א. ונמצא שכל הארת חכמה שיש בעולמות, המכונה \u0003ריח\u0004 תלוי בחוטם."],[5,"","[ב] \u0003תאנא כתיב הטה\u0004 וכו׳: למדנו, כתוב, הטה אלקי אזנך ושמע. זו היא אזן שנעשתה מתחת השערות, והשערות תלויות עליה. והאזן נעשתה ברשומי רשומות בפנימיותה, במי שעושה מדרגה באלכסון. מהו הטעם שהיא באלכסון. הוא כדי לשמוע טוב ורע. ולמדנו מאלכסון הזה שבתוך האזנים, תלוים כל אלו בעלי כנפים, שכתוב בהם, כי עוף השמים יוליך את הקול ובעל כנפים יגיד דבר."],[5,"","פירוש. כבר נתבאר, כמו שיש ע\"ס בפנימיות הראש, שהם המוחין, כך יש ע״ס בחצוניות הראש, הנקראים גולגלתא עינים אזן חוטם פה. וההפרש ביניהם הוא, כי הע״ס דפנימיות הם לעצם הפרצוף, ומה שיוצא מהן לחוץ לאחרים, נקראים גו״ע אח״פ. שה״ס ד׳ החושים, ראיה, שמיעה, ריח, ודבור, היוצא מן הפרצוף להאיר לתחתונים. וע״כ יש הבדל גדול בין חכמה ובינה דפנימיות הראש לחו״ב החיצוניות הראש, כי החו״ב דפנימיות החכמה היא למעלה מבינה, והחו״ב דחיצוניות הראש, הבינה שה״ס אזנים היא למעלה מחכמה שה״ס עינים. והוא מטעם, כי החכמה ממש אינה מאירה כלום מחוץ לפרצוף, מטעם שהיא נסתמה עוד בחכמה סתימאה דא״א, ומה שמאיר בחיצוניות בסוד חוש הראיה, היא רק מבינה שחזרה לחכמה בסוד ה \u0003י'\u0004 דנפיק מאויר, ונמצא שהאזנים והעינים שניהם הם בינה, אלא האזנים הן ג\"ר דבינה, שה״ס או״א עלאין, שבהם אין החכמה מאירה לחוץ, והעינים, הן ו״ק דבינה, שה״ס ישסו״ת שבהם ה \u0003י'\u0004 יוצאת מאויר, והחכמה מתגלה. ולפיכך האזנים שהן ג״ר הן למעלה מעינים שהן ו״ק. אמנם אין הפירוש, שהעינים הן עצם הבינה, אלא הפירוש, אותו שיעור החכמה המתגלה בו״ק דבינה, ה״ס העינים. באפן, שהעינים הן חכמה ולא בינה, אלא שמתגלה מן ו\"ק דבינה, מסוד הבינה שחזרה לחכמה. ולפיכך הג״ר של ראש דז״א, דהיינו החב\"ד, נקראות אזנים, והחג״ת של ראש ז״א נקראות עינים. ונודע שכל מה שיש בפרצוף נמשך מבחינה עליונה שבו, נמצא, שכל מה שיש בז״א נמשך מן האזנים. ולפיכך נתתקן שם שורש התקון של עלית המלכות. לבינה בסוד ה \u0003י'\u0004 הנכנסת לאור הבינה ונעשתה אויר. שמכאן נעשה באזנים, סוד פרסא באלכסון באמצע המדרגה. כי תקון זה הוא שורש כל התקעים, כי עי״ז אפשר לתחתונים לקבל אור העליון, ולולא קבלו הקטנות מבינה לא יכלו לקבל גם הגדלות. (כנ״ל ב״א דף ז׳ ד\"ה וכבר) וכן עי״ז נעשית אפשרות שהתחתון יוכל לעלות למקום העליון. (כמ״ש בויקהל אות קל״א)."],[5,"","וז״ש, \u0003אודנא דאתעביד תחות שערי ושערי תליין עליה,\u0004 היינו בעת קטנות מטרם שה \u0003י'\u0004 יוצאת מאויר הבינה, אז השערות, שה״ס הדינים, מכסות את האזנים, ואין בהן שמיעת התפלה. \u0003ואודנא אתעביד ברשומי רשימין לגאו כמה דעביד דרגא בעקימא,\u0004 דהיינו התקון של עלית מלכות בבינה, שנקרא \u0003דרגא בעקימא,\u0004 דהיינו מדרגה באלכסון, כי כל מדרגה יש בה ד׳ רוחות חו״ב תו״מ לד׳ רוחות דרום צפון מזרח מערב, שה״ס צורת מרובע. וכשנעשה התקון של עלית מלכות שה״ס מערב אל הבינה שה״ס צפון, נתחברו המערב והצפון ונעשו צלע אחת באלכסונא, שה״ס משולש. (כמ״ש לעיל לך דף ח׳ ד״ה ומכח, עש״ה) ומכאן יצאו י״ב גבולי אלכסון כמ״ש שם. וז״ס שכל הפרסאות שנעשו במדרגות מכח עלית המלכות לבינה, הם פרושים באלכסון."],[5,"","וז״ש, \u0003מ״ט בעקימא. בגין למשמע טב וביש.\u0004 כי מתחילת עלית המלכות לבינה, מתמעטת הבינה מג״ר, בסוד שה \u0003אור\u0004 נעשה ל \u0003אויר.\u0004 שהיא לכאורה \u0003ביש.\u0004 אמנם בשביל זה אח״כ כשיוצאת ה \u0003י׳\u0004 מאויר והבינה חוזרת לאור נמשכת ממנה הגדלות לכל הפרצופין, והוא \u0003טב.\u0004 ונמצא שכניסת ה \u0003י׳\u0004 לאור היא שמועה לא טובה. ויציאת ה \u0003י׳\u0004 מאויר היא שמועה טובה. אמנם באמת גם כניסת ה \u0003י'\u0004 לאור היא שמיעה טובה, כי לולא זה, לא היו נמצאים מוחין בזו\"ן ובבי״ע, (כנ״ל ב״א דף ז׳ ד\"ה וכבר) וז״ש, \u0003מהאי עקימא וכו' תליין כל מארי דגדפין, דכתיב כהו כי עוף השמים\u0004 וגו׳. שכל המלאכים בעלי כנפים, דהיינו אותה הקטנות המכונה כנפים המכסים האור, וכן לפרוח בהם, בעת גדלות, בסוד מגדל הפורח באויר, נמשכים \u0003מהאי עקימא,\u0004 שהיא הפרסא באלכסון, \u0003דכתיב בהו, כי עוף השמים יוליך את הקול,\u0004 דהיינו הקול דקטנות, ואז, \u0003בעל כנפים,\u0004 אותו שקבל הקטנות הזו, \u0003יגיד דבר,\u0004 יקבל אח״כ הגדלות שנקרא הגדה. כי החכמה נקראת הגדה."],[6,"בגו אודנא נטיף","וכו׳: בתוך האזן, נוטף מג' חללי המוח דז״א, שהם חב״ד, לנקב הזה שבאזנים. ומנוטפים האלו, נכנס הקול באלכסון ההוא, ונצרף בנוטפים האלו, אם לטוב ואם לרע. טוב, שכתוב, כי שומע אל אביונים ה'. רע, שכתוב, וישמע ה׳ ויחר אפו ותבער בם אש ה'."],[6,"","פירוש. כבר ידעת שהאזנים ה״ס ג״ר דראש, דהיינו חב״ד, וז\"ש, \u0003בגו אודנא נטיף מג׳ חללי דמוחא להאי נוקבא דאודנין,\u0004 דהיינו שחב״ד דמוחא שהם ג\"ר הפנימים מאירים ונוטפים בנקבי האזנים, שה״ס חב״ד חיצונים כנ״ל. \u0003ומההוא נטיפא עייל קלא\u0004 וכו', זה יתבאר בדבור הסמוך."],[7,"והאי אודנא סתים","וכו׳: ואזן זו סתומה מבחוץ, והאלכסון נכנס בפנים לנקב האזן שבו הנוטפים מן המוח, כדי להכניס הקול לפנים, שלא יצא לחוץ, ויהיה שמור וסתום מכל צדדיו. משום זה הוא סוד. אוי למי שמגלה סודות, כי מי שמגלה סודות, הוא כאלו גורע תקון העליון, שנתתקן לאסוף הסודות בפנים שלא יצאו לחוץ."],[7,"","פירוש. כי האזן משונה משאר החושים, כי היא מקבלת בלבד, אבל אינה משפעת לחוץ כמו העינים והחוטם והפה. והוא מטעם כי אע״פ שמקור יציאת ה \u0003י'\u0004 מאויר וגילוי החכמה, נעשה באזנים, שהם הג״ר דראש המשפיעים לו\"ק דראש ולכל הגוף, עכ״ז משם אין מגולה כלום לחוץ, כי הג״ר דחכמה נגנזו ואינם מושפעים אלא ו\"ק דחכמה, שמקומם בעינים והחוטם כנ״ל. וז״ש \u0003והאי אודנא סתים לבר,\u0004 שאין דבר מושפע ממנו לחוץ, \u0003ועקימא עייל וכו׳ דלא יפוק לבר ויהא נטיר וסתים מכל סטרוי,\u0004 כי אם היה יוצא מן האזן לחוץ היו מתגלות ג״ר דחכמה, משום שהאזן היא ג״ר, \u0003בג״כ הוא רזא,\u0004 כי הג״ר הן סוד. ואסור שתשפענה לחוץ. וז״ש, \u0003ווי לההוא דמגלי רזין\u0004 וכו׳ \u0003כאלו אכחיש תקונא דלעילא\u0004 וכו' כי נעשה תקון למעלה לגנוז הג״ר, והוא רוצה לגלותם ולהכחיש תקון זה."],[7,"","ומ״ש, \u0003ועקימא\u0004 וכו׳ \u0003בגין למכנש קלא לגאו,\u0004 הענין הוא, שבעקימא זו שה״ס הפרסא, יש ב׳ תקונים, א) שבו הגבול שאור העליון לא יתפשט ממנו ולמטה, מחמת שעלתה לשם המלכות המסיימת האור. ב) שהוא מעלה את התחתון לעליון. והיינו בעת שה \u0003י'\u0004 חוזרת ויוצאת מן האויר, והמלכות יורדת ממקום הפרסא למקומה, הנה אז מתקיים ג״כ גבול הפרסא שאינו נותן לאור שיתפשט מפרסא ולמטה, אלא הבינה ותו״מ שירדו ממדרגה בוקעים הפרסא והם עולים ומתחברים עם כתר וחכמה שלמעלה מפרסא, כמ״ש זה באורך (לעיל ויקהל דף ל״ט ד״ה וזהו שאומר באות, ע״ש) ובדרך זה הפרסה מעלה את התחתון לעליון, כי בינה ותו״מ שנפלו מן המדרגה הם נופלים למדרגה שלמטה ממנה, ואח״כ בעת שהפרסא מחזירה אותם אל המדרגה והם עולים למעלה מפרסא ולוקחים עמהם גם את המדרגה התחתונה ומעלים אותה למעלה מפרסא (כנ״ל ב״א דף צ׳ ד\"ה בגין) ובדרך זה עולה התפלה מעשיה עד אצילות ונעשית מ״ן לז״א ומלכות. (כנ״ל ויקהל בהסולם אות קל״א, עש״ה כי הוא אריכות גדול ואין להכפיל הדברים) וז״ש, \u0003ועקימא עייל לגו, לההוא נוקבא דנטיפא מן מוחא, בגין למכנש קלא לגאו,\u0004 כי קול התפלה שעלה מן עשיה עד ז״א למ״ן, לא יוכל לקבל כלום כשנמצא למטה מפרסא דאודנין, אלא הפרסא דאודנין מעלה את קול התפלה לפנים מן הפרסא, בנקב האזן, ששם יש נטיפא דג' מוחין חב״ד, ומשם הוא מקבל הארת המוחין ההם. \u0003דלא יפיק לבר,\u0004 והקול אינו יכול לרדת דרך האזן לחוץ, משום שהאזנים הם בחינת ג״ר המאירים ממעלה למטה. והפרסה מגבילם, שמעכב האור שלא לרדת אלא ממטה למעלה. אלא שמחויב לצאת דרך העיינין וחוטמא כמ״ש לפנינו."],[8,"תניא בשעתא דצווחין","וכו׳: למדנו בשעה שישראל צועקים מתוך צרתם, והשערות מתגלות מעל האזנים, אז נכנס הקול באזנים באותו הנקב שהמוח נוטף שמה, ואוסף מן המוח, ויוצא דרך נקבי החוטם, ומתקצר החוטם ומתחמם, ויוצא אש ועשן מנקבי החוטם אלו, ומתעוררות כל הגבורות, ועושות נקמות."]],[]],[["וְעַד לָא נָפְקִין מֵאִינּוּן נוּקְבִין אֶשָּׁא וּתְנָנָא\"סָלִיק הַהוּא קָלָא לְעֵילָּא, וּבָטַשׁ בְּרֵיחָא דְּמוֹחָא (ס\"א ברישא במוחא), וְנַגְדִּין תְּרֵין דִּמְעִין מְעַיְּינִין, וְנָפַק מִנְּחִירוֹי תְּנָנָא וְאֶשָׁא, בְּהַהוּא קָלָא דְּנָגִיד לוֹן לְבַר.","בְּהַהוּא קָלָא דְּעָיִיל בְּאוּדְנִין, אִתְמַשְּׁכָאן וּמִתְּעָרָן (ס\"א מתערבין) כּוּלֵי הַאי, בְּגִין כַּךְ כְּתִיב, וַיִּשְׁמַע יְיָ וַיִּחַר אַפּוֹ וַתִּבְעַר בָּם אֵשׁ יְיָ. בְּהַהִיא שְׁמִיעָה דְּהַהוּא קָלָא, אִתְּעַר מוֹחָא. (כלא) תָּנָא, כְּתִיב הַטֵּה אֱלֹהַי אָזְנְךָ, כְּלוֹמַר אַרְכִּין (ס\"א אודנין). שִׁית מְאָה אֶלֶף רִבּוֹא אִינּוּן מָארֵיהוֹן דְּגַדְפִין, דְּתַּלְיָין בְּאִלֵּין אוּדְנִין. וְכֹלָּא אִתְקְרוּן אָזְנֵי יְיָ. וּמַה דְּאִתְּמַר הַטֵּה יְיָ אָזְנְךָ, אָזְנְךָ בִּזְעֵיר אַפִּין אִתְּמַר.","מִסִּטְרָא דְּחַד חַלָּלָא דְּמוֹחָא תַּלְיָין אוּדְנִין. וּמֵחַמְשִׁין תַּרְעִין דְּנָפְקִין מֵהַהוּא חַלָּלָא, דָא הוּא (ס\"א אית) תַּרְעָא חַד, דְּנָגִיד וְנָפִיק וְאִתְפְּתַח בְּהַהוּא נוּקְבָּא דְּאוּדְנָא, דִּכְתִּיב, (איוב ל״ד:ג׳) כִּי אֹזֶן מִלִּין תִּבְחָן. וּכְתִיב (תהילים ז׳:י׳) וּבוֹחֵן לִבּוֹת וּכְלָיוֹת. וּמִסִּטְרָא דְּאִתְפַּשְּׁטוּתָא דְּהַהוּא חַלָּלָא, דְּחַמְשִׁין תַּרְעִין דְּאִתְפַּשְּׁטוּתָא בְּגוּפָא, בַּאֲתָר דְּלִבָּא שַׁארֵי, מִתְפָּשַּׁט הַהוּא חַלָּלָא דְּחַמְשִׁין תַּרְעִין, וְאוּדְנָא קָרֵי בֵּיהּ בְּחִינָה, וּבְלִבָּא קָרֵי בֵּיהּ בְּחִינָה, מִשּׁוּם דְּמֵאֲתָר חַד מִתְפַּשְּׁטִין. (ס\"א בההוא נוקבא דאודנא ומסטרא דאתפשטותא דההוא חללא דחמשין תרעין אתפשט בגופא באתר דלבא שארי ועל דא באודנא קרי ביה בחינה ובלבא קרי ביה בחינה דכתיב כי אזן מלין תבחן וכתיב בוחן לבות וכליות משום דמאתר חד מתפשטין)","תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, כְּמָה דְּאוּדְנָא דָּא אַבְחִן בֵּין טַב וּבֵין בִּישׁ, כַּךְ כֹּלָּא. דְּבִזְעֵיר אַפִּין אִית סִטְרָא דְּטָב וּבִישׁ. יְמִינָא וּשְׂמָאלָא. רַחֲמֵי וְדִינָא. וְהַאי אוּדְנָא כְּלִיל בְּמוֹחָא וּמִשּׁוּם דְּאִתְכְּלִל בְּמוֹחָא ובַּחֲלָלָא חַד. אִתְכְּלִיל בְּקָלָא דְּעָיִיל בֵּיהּ. וּבְאוּדְנָא קָרֵי בֵּיהּ שְׁמִיעָה. וּבִשְׁמִיעָה אִתְכְּלִיל בִּינָה. שְׁמַע: כְּלוֹמַר, הָבֵן אִשְׁתְּכַח (ס\"א ואסתכל) דְּכֹלָּא בְּחַד מַתְקְלָא אִתְקַל. וּמִלִּין אִלֵּין לְמָארֵיהוֹן דְּמָארִין אִתְיְהָבָן, לְמִשְׁמַע וּלְאִסְתַּכְּלָא וּלְמִנְדַּע.","תָּא חֲזֵי, כְּתִיב, (חבקוק ג׳:ב׳) יְיָ שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי וְגוֹ', הַאי קְרָא אִשְׁתְּמוֹדַע, דְּכַד נְבִיאָה קַדִּישָׁא, (ס\"א מהימנא) שָׁמַע, וְאִסְתָּכַּל, וְיָדַע, וְקָאִים עַל תִּקּוּנִין אִלֵּין, כְּתִיב יָרֵאתִי, תַּמָּן יָאוּת הוּא לְדַחֲלָא וּלְאִתַבָּר קַמֵּיהּ, הַאי בִּזְעֵיר אַפִּין אִתְּמַר.","כַּד אִסְתָּכַּל וְיָדַע מַה כְּתִיב. יְיָ פָּעָלְךָ בְּקֶרֶב שָׁנִים חַיֵּיהוּ. הַאי לְעַתִּיק יוֹמִין אִתְּמַר. וּבַכֹּל אֲתָר דְּיִשְׁתְּכַח, יְיָ יְיָ, בְּיוֹ\"ד הֵ\"א תְּרֵי זִמְנֵי, אוֹ בְּאָלֶף דָּלֶ\"ת, וְיוּ\"ד הֵ\"א, חַד לִזְעֵיר אַפִּין, וְחַד לְעַתִּיקָא דְּעַתִּיקִין. וְאַף עַל גַּב דְּכֻלְּהוּ חַד, וְחַד שְׁמָא אִקְרוּ.","וְתָנֵינָן אֵימָתַי אִקְרֵי שֵׁם מָלֵּא. בְּזִמְנָא דִּכְתִּיב יְיָ אֱלֹהִים. דְּהַאי הוּא שֵׁם מָלֵּא דְּעַתִּיק דְּכֹלָּא, וְדִזְעֵיר אַנְפִּין. וְכֹלָּא הוּא שֵׁם מָלֵּא אִקְרֵי. וּשְׁאַר לָא אִקְרֵי שֵׁם מָלֵּא, כְּמָה דְּאוֹקִימְנָא, (בראשית ב׳:ח׳) וַיִּטַּע יְיָ אֱלֹהִים, שֵׁם מָלֵּא בִּנְטִיעוֹת גִּנְתָּא. וּבְכָל אֲתָר, יְיָ אֱלֹהִים, אִתְקְרֵיא שֵׁם מָלֵּא. יְיָ יְיָ, כֹּלָּא הוּא בִּכְלָלָא. וְהַהוּא זִמְנָא אִתְּעָרוּן רַחֲמִין בְּכֹלָּא.","יְיָ פָּעָלְךָ בְּקֶרֶב שָׁנִים חַיֵּיהוּ, לְעַתִּיק יוֹמִין אִתְּמַר. מַאן פָּעָלְךָ. זְעֵיר אַפִּין. בְּקֶּרֶב שָׁנִים, אִינּוּן שָׁנִים קַדְמוֹנִיּוֹת, דְּאִקְרוּן יְמֵי קֶדֶם, וְלָא אִקְרוּן שְׁנוֹת עוֹלָם. שָׁנִים קַדְמוֹנִיּוֹת אִינּוּן יְמֵי קֶדֶם. שְׁנוֹת עוֹלָם אִלֵּין יְמֵי עוֹלָם. וְהָכָא בְּקֶרֶב שָׁנִים, מַאן שָׁנִים. שָׁנִים קַדְמוֹנִיּוֹת. חַיֵּיהוּ לְמַאן. חַיֵּיהוּ לִזְעֵיר אַפִּין. דְּכָל נְהִירוּ דִּילֵיהּ מֵאִינּוּן שָׁנִים קַדְמוֹנִיּוֹת אִתְקָיָּימוּ, וּבְגִין כָּךְ אָמַר חַיֵּיהוּ. בְּרוֹגֶז רַחֵם תִּזְכּוֹר, לְהַהוּא חֶסֶד עִלָּאָה דְּעַתִּיקָא דְּעַתִּיקִין, דְּבֵיהּ אִתְּעַר רַחֲמִין לְכֹלָּא, לְמַאן דְּבָעֵי לְרַחֲמָא, וּלְמַאן דְּיֵאוֹת לְרַחֲמָא.","תָּאנָא, אָמַר רַבִּי שִׁמְעוֹן, אַסְהַדְנָא עָלַי שְׁמַיָא, וּלְכָל אִלֵּין דְּעָלָנָא קַיְימִין. דְּחַדָּאן מִלִּין אִלֵּין, בְּכֻלְּהוּ עָלְמִין. וְחַדָּאן בְּלִבָּאִי מִלָּי, וּבְגוֹ פָּרוֹכְתָּא עִלָּאָה דִּפְרִיסָא עֲלָנָא, מִתְטַמְּרִין, וְסַלְּקִין, וְגָנִיז לְהוּ עַתִּיקָא דְּכֹלָּא, גָּנִיז וְסָתִים מִכֹּלָּא. וְכַד שָׁרֵינָא לְמַלְּלָא, לָא הֲווֹ יַדְעִין חַבְרַיָּא, דְּכָל הָנֵי מִלִּין קַדִּישִׁין מִתְעָרִין הָכָא. זַכָּאָה חוּלָקֵיכוֹן חַבְרַיָּיא דְּהָכָא. וְזַכָּאָה חוּלָקִי עִמְּכוֹן, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלֹהֵיכֶם וְגוֹ'. מַאן עַמָּא קַדִּישָׁא כְּיִשְׂרָאֵל, דִּכְתִּיב בֹּהוּ (דברים ל״ג:כ״ט) אַשְׁרֶיךָ יִשְׂרָאֵל מִי כָמוֹךָ, דִּכְתִיב (שמות ט״ו:י״א) מִי כָמֹכָה בָּאֵלִם יְיָ. מִשּׁוּם דְּאִתְדַּבְּקוּתָא דִּלְהוֹן הוּא בִּשְׁמָא קַדִּישָׁא בְּעָלְמָא דֵּין. וּבְעָלְמָא דְּאָתֵי יַתִּיר מֵהָכָא. דְּהָתָם לָא מִתְפָּרְשָׁן מִנֵּיהּ, מֵהַהוּא צְרוֹרָא דִּצְרִירִין בֵּיהּ צַדִּיקַיָּא, הֲדָא הוּא דִכְתִיב וְאַתֶּם הַדְּבֵקִים בַּיְיָ, וְלָא כְּתִיב הַדְּבֵקִים לַיְיָ, אֶלָּא בַּיְיָ מַמָּשׁ."],[[0,"ועד לא נפקין","וכו׳: ומטרם שאש ועשן יוצאים מנוקבי החוטם, עולה הקול ההוא למעלה, ובוטש בריח של המוח, ונוזלות שתי דמעות מן העינים, ויוצאים מן נחיריו עשן ואש בקול ההוא הממשיך אותם לחוץ. פירוש. בשעה שה \u0003י'\u0004 יוצאת מאויר הבינה ויוצאות הג״ר דחכמה, בסוד האויר שחזר להיות אור. אז שולט קו השמאל בסוד נקודת השורק (כנ״ל ב״א דף ט״ו ד״ה ההיא) ונמשכים משליטתו דינים קשים על ישראל. וז״ש \u0003בשעתא דצווחין ישראל בעאקא, ושערי מתגליין מעל אודנין,\u0004 כי עם יציאת ה \u0003י'\u0004 מאויר הבינה נפנות השערות מעל האזנים, שאז שולט השמאל בדינים קשים, וע״כ צריכים לז״א שיעלה לבינה בסוד קו האמצעי וייחד ב׳ הקוין זה בזה, והחכמה שבשמאל הבינה תתלבש בחסדים שבימין הבינה, אז מסתלקים הדינים דקו השמאל, ומאירים שניהם בסוד דרחמים, דהיינו בסוד ג׳ קוין חב״ד, אמנם אין ז\"א עולה ליחד ב׳ קוי הבינה אלא ע״י אתערותא דלתתא, דהיינו ע״י קול תפלת ישראל העולה מלמטה ממדרגה למדרגה בדרך בקיעות הפרסאות (המבואר לעיל ויקהל אות קל״א) עד שגם העקימא דאודנין נבקע ומעלה קול התפלה לפנים לנקב האזן, ושם נעשה הקול למ\"ן לז״א, וז״א עולה לבינה ומיחד ב׳ קוין של הבינה זה בזה, ויוצאים ג׳ קוי חב״ד בתוך הבינה, ומשום שז״א גרם יציאתם, מקבל אותם גם הוא, בסוד תלת נפקי מחד חד בתלת קיימא. (כנ״ל ב״א דף רפ״ז ד״ה תלת ע״ש) והם נמשכים לג' חללי גולגלתא דז״א. וכיון שקול התפלה גרם שז״א יעלה למ״ן לבינה ויקבל ג׳ מוחין חב״ד, זכה בהארתם גם הקול, כי זה הכלל שכל שיעור האור שהתחתון גורם לעליון זוכה בו גם התחתון, ולפיכך אלו ג׳ מוחין חב״ד שקיבל ז״א ע״י קול התפלה נוטפים משם אל נקב האזן ששם קול התפלה, וגם הקול מקבל הארת ג׳ מוחין אלו. וז״ש, \u0003כדין עייל קלא באודנין בההוא נוקבא דנטיף ממוחא,\u0004 שאז עולה קול תפלת ישראל המתפללים מתוך צרתם, באותו נקב האזן שנוטף בו מן המוח. ונעשה שם מ\"ן לז״א שז״א יעלה לבינה וייחד שם השמאל עם הימין ויוצא שם ג׳ קוין חב״ד, ובסוד חד בתלת קיימא נמשכים לג' חללי גולגלתא דז״א, וכיון, שקול התפלה גרם ג׳ מוחין אלו לז״א זוכה בו גם הקול, וע״כ נוטפים ג׳ מוחין אל נקב האזן ששם קול התפלה והקול מקבל אותם, וז״ש \u0003וכנש במוחא\u0004, שהקול אוסף הארת המוח, אמנם אינו יורד למקומו דרך נקב האזן, כי האזן סתים הוא לבר (כנ״ל אות רל״ז) אלא שיוצא דרך החוטם שהוא בחינת ו״ק דחכמה, וז״ש, \u0003ונפיק בנוקבי דחוטמא.\u0004 שמדת הקבלה אינה בחינת אזן, שהוא ג\"ר דחכמה, אלא בחינת חוטם שהוא ו״ק דחכמה."],[0,"","וכבר ידעת, שאין החכמה מתגלית אלא בזמן ירידת הדינים על הרשעים הממשיכים החכמה ממעלה למטה (כנ״ל אות רי״ט) ולפיכך בעת שקול התפלה עם הארת המוחין שאסף בנקב האזן, רוצה לרדת דרך נוקבי החוטם, מתעוררים אז בחוטם הדינים דסומקא ואוכמא שיש בה מקו השמאל, (כנ״ל אות רכ\"ד) וז״ש, \u0003ואתזער חוטמא ואתחמם ונפיק אשא ותננא מאינון נוקבין ומתערין כל גבוראן מאינון נוקבין,\u0004 ואז יחד עם כל אלו הגבורות והנקמות היוצאים מן החוטם, שיורדים על הרשעים, יורד ג״כ קול התפלה עם הארת החכמה והרחמים שבה, ומגיע אל ישראל. שז״ס שמרחם על ישראל."],[0,"","ובכדי שלא נטעה לומר, שישר מן האודנין יוצא הקול לחוטם, שזה אינו בסדר המדרגה, כי הסדר הוא שמאודנין שהן חב״ד בא הקול לעיינין, שהם חו״ג, ומעיינין בא הקול לחוטם, ומחוטם יורד למטה. וז״ש, \u0003ועד לא נפקין\u0004 וכו׳ \u0003סליק ההוא קלא לעילא ובטש בריחא דמוחא,\u0004 דהיינו שהקול מקבל ו\"ק דחכמה מן המוחין, הנקראים ריח של המוח, כי ו\"ק דחכמה נקראים ריח. ואח״כ, \u0003ונגדין תרין דמעין מעיינין,\u0004 שה\"ס הדינים דעינים המתגלים עם גילוי החכמה, הנקראים סומקא ואוכמא (כנ״ל אות רכ״ב) שהקול נכלל בהן, ואח״כ \u0003ונפק מנחירוי תננא ואשא,\u0004 שהם הדינין דחוטם (כנ״ל אות רכ״ג) והם יוצאים עם הקול תפלה ההוא המושך אותם לחוץ ע״י המ״ן שלו. וז״ש, \u0003בההיא קלא דנגיד לון לבר,\u0004 ועמהם יורד קול התפלה הכלול במוחין דחב״ד, שהם רחמים, אל ישראל, והם נושעים מצרותיהם. והדינים המלוים אותה, מביאים נקמות על המצירים לישראל."],[1,"בההוא קלא דעייל","וכו׳: בקול ההוא שנכנס באזנים נמשכים ומתעוררים כל זה הנ״ל, משום זה כתוב, וישמע ה׳ ויחר אפו ותבער בם אש ה'. כי בשמיעה ההיא, של הקול שנכנס באזן מתעורר המוח, שמשם מושך הקול, רחמים לצדיקים, ונקמות על הרשעים. למדנו, כתוב, הטה אלקי אזנך וראה. כלומר השפל. דהיינו שיוריד וישפיל העקימא שבאזן, למקום הקול ויעלה את קול התפלה לתוך פנימיות האזן ששם המוחין (כנ״ל אות רל״ז) שש מאות אלף רבוא הם בעלי כנפים התלויים באלו אזנים וכולם נקראים אזני ה׳. ומה שנאמר הטה ה׳ אזנך, אזנך, בז״א נאמר. כי מעשי התחתונים מגיעים כך עד ז״א."],[1,"","פירוש. כבר ידעת שהחכמה הנמשכת בעולמות הוא מבינה החוזרת לראש א״א, ומקבלת ממנו חכמה. ולפיכך נבחנת הארת החכמה על שם א״א, שספירותיו בסוד מאה אלף, וכיון שמקובלים ממנו רק ו״ק דחכמה, הם שש מאות אלף. ועם החסדים הנמשכים מעתיק, שספירותיו בסוד רבוא רבבן, הם נעשים שש מאות אלף רבוא. וזהו חשבון כללי של כל המוחין היוצאים למטה ע״י העקום שבאודנין, שבז״א, במשך שתא אלפי שני עד גמר התקון. וז״ש \u0003שית מאה אלף רבוא אינון מאריהון דגדפין.\u0004 ונקראים בעלי כנפים, על שם הכיסוים שהם מקבלים מן הפרסה דז״א, שה״ס עקימא דאודנין, שבהם יורדים ועולים באויר, שבעת קטנות נכנסת הי׳ באור, והם יורדים לבחינת ו״ק, ובעת גדלות יוצאת הי׳ מאויר והורד הפרסא, והם עולים ומקבלים על ידה בחינת ג״ר. ונמצא שהן פורחים על ידה באויר כמו בכנפים, וע״כ נקראים המוחין מאריהון דגדפין \u0003דתליין באינון אודנין,\u0004 כלומר בעקימו דאודנין."],[2,"מסטרא דחד חללא","וכו׳: מצד חלל אחד של המוח דז״א, שהוא צד השמאל, תלוים ממנו האזנים, ומן חמשים השערים שיוצאים מחלל ההוא (כנ״ל אות קצ״א) זה הוא שער אחד הנמשך ויוצא ומתפתח בנקב ההוא של האזן. שכתוב, כי אזן מלין תבחן. וכתוב, ובוחן לבות וכליות, כי מצד התפשטות של המוח שבחלל בחמשים השערים המתפשטים בגוף, הנה במקום שהלב שורה מתחיל להתפשט המוח שבחלל ההוא דחמשים שערים. וע״כ באזן נאמר בה \u0003בחינה,\u0004 ובלב נאמר בו \u0003בחינה,\u0004 משום שמתפשטים ממקום אחד."],[2,"","פירוש. ב׳ פרסאות עקריות הם בז״א, בראש, המבדלת בין ג״ר דראש לו\"ק דראש, שה״ס העקימא דאודנין. ופרסא ב', הוא בגוף, המבדלת בין ג״ר דגוף שהן חג״ת ובין ו״ק דגוף שהם נה״י, דהיינו הפרסא שבמקום החזה דז״א, שבפנימית הגוף הוא מקום הלב. ולפיכך נוהג באודנין, ובלבא, סוד ההבחנה, דהיינו להבחין, אם להוציא ה \u0003י׳\u0004 מן האויר, ולהחזיר את בינה ותו״מ שנפלו מן המדרגה, שעל ידיהם יוצא קו השמאל, שה״ס המוח שבחלל השמאלי דז״א. כנ״ל. או שלא להוציא ה \u0003י'\u0004 מן האויר, ולא להחזיר הבינה ותו\"מ אל המדרגה. שאז אין גילוי למוח השמאל דז״א. באפן, שיציאת ה \u0003י׳\u0004 מן האויר, הוא שער א׳ הראשון מן חמשים שערים שבמוח השמאלי דז״א. וכן אח״כ, כשמבחין בין דינין דשליטת השמאל, נכנס בו קו אמצעי ומיחד הימין והשמאל זה בזה, ואז מבחין בין החסדים שבימין ובין הדינין שבשמאל."],[2,"","וז״ש, \u0003מסטרא דחד חללא דמוחא תליין אודנין,\u0004 כלומר, שיציאת ה \u0003י׳\u0004 מן האויר הנעשה בעקימא דאודנין מוציאה מוח השמאל דז״א שיש בו חמשים שערים, \u0003ומחמשין תרעין דנפקין מההוא חללא דא הוא תרעא חד,\u0004 דהיינו שער הראשון, \u0003דנגיד ונפיק ואתפתח בההוא נוקבא דאודנין\u0004 דהיינו ע״י יציאת ה \u0003י'\u0004 מאויר הנוהג בעקימא דאודנין, מתגלה שער הא׳ דחלל השמאל דז״א שראשית הגילוי של חמשים שערים דמוח השמאל שלו, נמשך ויוצא ונפתח ע״י יציאת ה \u0003י׳\u0004 מן הפרסא שבאודנין. \u0003ומסטרא דאתפשטותא\u0004 וכו׳ \u0003באתר דלבא שארי,\u0004 דהיינו כנגד מקום החזה שבגוף ששם שורה הלב, ושם ישנה הפרסא המבדלת בין ג״ר דגוף לו״ק דגוף כנ״ל, \u0003מתפשט ההוא הללא דחמשין תרעין,\u0004 דהיינו ע״י יציאת ה \u0003י׳\u0004 מן הפרסא מתגלה הקו השמאלי, והמוח השמאלי שיש בו חמשים שערים מתפשט לתוך הגוף. ולפיכך, \u0003ואודנא קרי ביה בחינה,\u0004 דהיינו אזן מלין תבחן. \u0003ובלבא קרי ביה בחינה,\u0004 דהיינו ובוחן לבות וכליות. דהיינו ששם הוא ההבחנה של יציאת ה \u0003י׳\u0004 מן האויר, הממשיך ומגלה המוח השמאלי דז״א, משום ששם עומדות הפרסאות. וכן אחד היחוד דקו האמצעי, הוא מבחין בין הרחמים דקו ימין ובין הדינים דקו שמאל."],[3,"תאנא בצניעותא דספרא","וכו׳: למדנו בספרא דצניעותא, כמו שאזן זו מבחינה בין טוב לרע, כך הכל. דהיינו בכל הספירות דז״א. כי בז״א יש צד טוב וצד רע, שהם ימין ושמאל, רחמים ודין. ואזן זו כלולה במוח. ומשום שנכללה במוח ובחלל אחד, נכללה בקול הנכנס בה, שבאזן הוא נחשב לשמיעה. ובשמיעה נכללה הבינה. שמע, פירושו הבן. דהיינו בינה. נמצא שהכל במשקל אחד נשקל. ודברים אלו ליושבים על כסא מדין נתנו, לשמוע ולהסתכל ולדעת."],[3,"","פירוש. כמו אחר ביאת הקו האמצעי ומיחד הימין והשמאל, יש באזן הבחנה בין ימין לשמאל בסוד רחמים על ישראל ונוקמין על המצירים לישראל, כך בכל ספירות דז״א יש צד של טוב וצד של רע דהיינו קו ימין וקו שמאל שיש בכל ספירה וספירה דז״א וז״ש \u0003כמה דאודנא דא אבחן בין טב ובין ביש כך כלא, דבז״א אית סטרא דטב וביש, ימינא ושמאלא, רחמי ודינא.\u0004 ונתבאר לעיל שבעת יציאת הי׳ מן האויר, אז נמשך באזן מוח השמאל, בסוד נקודת השורק. וכן אז, העוקמא דאודנין מעלה את הקול לתוך נקב האודנין (כנ״ל אות רל״ז) וז״ש, \u0003משום דאתכלל במוחא ובחללא חד,\u0004 דהיינו שהי' יצאה מאויר הפרסא שבאודנין, ונגלה מוח השמאל, שאז נכלל באזן כנ״ל, \u0003אתכליל בקלא דעייל ביה,\u0004 נכלל בעת הזאת בקול תפלה הנכנס באזן, כי בעת הזאת מעלה הפרסא שבאזן את הקול. כנ״ל. ואז היא שמיעת התפלה, וז״ש \u0003ובאודנא,\u0004 כיון שקול התפלה נכנס באזן, \u0003קרי ביה שמיעה,\u0004 ששומע התפלה, \u0003ובשמיעה אתכליל בינה,\u0004 כי החכמה נקראת ראיה, והבינה נקראת שמיעה, \u0003אשתכח דכלא בחד מתקלא אתקל,\u0004 שהרי האזן היא בינה, ובה נכלל המוח השמאלי שהוא בינה, ובו השמיעה, שהיא בינה. והכל הוא במשקל הבינה."],[4,"ת״ח כתיב ה׳","וגו׳: בוא וראה כתוב, \u0003ה׳ שמעתי שמעך\u0004 יראתי. מקרא נודע, בעת שהנביא הקדוש שמע, והסתכל, וידע, ועמד על אלו התקונים שבאזן ששם סוד, שמעתי שמעך, כתוב \u0003יראתי.\u0004 כי שם יפה הוא לירא ולהשבר לפניו. מחמת הגילוי של קו השמאל, הנוהג שם כנ״ל. וזה נאמר באודנין דזעיר אנפין."],[5,"כד אסתכל וידע","וכו׳: אחר שהסתכל וידע, מה כתוב, ה׳ פעלך בקרב שנים חייהו. זה נאמר לעתיק יומין. כי בכל מקום שנמצא הויה הויה, בי״ה ב׳ פעמים. או אחד באלף דלת, ואחד בי״ה, שם אחד הוא לזעיר אנפין, ושם אחד הוא לעתיקא דעתיקין. ואע״פ שז״א ועתיקא הכל אחד, ובשם אחד נקראים."],[6,"ותנינן אימתי אקרי","וכו׳: ולמדנו מתי נקרא שם מלא. הוא בזמן שכתוב הויה אלקים שזה הוא שם מלא דעתיק מכל, ודזעיר אנפין. כי הויה ה״ס עתיק ואלקים הוא ז״א. וכולו הוא נקרא שם מלא. ושאר השמות אינם נקראים שם מלא. כמו שהעמדנו, ויטע הויה אלקים, הוא שם מלא שנטע בנטיעות הגן. ובכל מקום הויה אלקים נקרא שם מלא. הויה הויה ב״פ, הכל הוא בכלל, דהיינו ז״א ועתיקא. כנ״ל, אבל עוד לא נקרא שם מלא, כי בעת ההיא מתעוררים הרחמים בכל. ואינו נכלל בדין, אבל הויה אלקים נכלל מרחמים ודין, כי אלקים מורה על דין, וע״כ הוא שם מלא."],[7,"ה׳ פעלך בקרב","וגו׳: המקרא, ה׳ פעלך בקרב שנים חייהו, נאמר לעתיק יומין. שואל, מי הוא \u0003פעלך.\u0004 ומשיב, הוא ז״א, הנאצל מעתיק יומין, \u0003בקרב שנים,\u0004 אלו הם שנים קדמוניות, הנקראות ימי קדם, ואינן נקראות שנות עולם. כי \u0003שנים קדמוניות\u0004 הן ימי קדם, דהיינו ספירות עתיק יומין. \u0003שנות עולם\u0004 הן ימי עולם, שהם ספירות ז״א. וכאן שכתוב, \u0003בקרב שנים,\u0004 מי הן השנים. שנים קדמוניות דעתיק יומין. \u0003חייהו,\u0004 למי. חייהו היינו לזעיר אנפין, שכל האור שלו, מאלו שנים קדמוניות דעתיק יומין מתקיים. ומשום זה אמר, חייהו. \u0003ברוגז רחם תזכיר,\u0004 היינו שיזכור בחסד עליון הזה של עתיק דעתיקין שבו מתעוררים הרחמים לכל, למי שצריך רחמים, ולמי שראוי לרחמים."],[8,"תאנא אר״ש אסהדנא","וכו׳: למדנו, א\"ר שמעון מעיד אני עלי את השמים, וכל אלו העומדים עלינו, דהיינו כל המרכבות ומחנות המלאכים, שדברים אלו שמחים בכל העולמות, והדברים שמחים בלבי, ומסתתרים ועולים בתוך פרוכת העליונה הפרושה עלינו (כנ״ל אות קס״ו) ומסתיר אותם העתיק מכל הגנוז וסתום מכל. וכשהתחלתי לדבר לא ידעו החברים שכל אלו הדברים הקדושים מתעוררים כאן. אשרי חלקכם החברים שבכאן. ואשרי חלקי עמכם בעולם הזה ובעולם הבא."],[9,"פתח ר\"ש ואמר","וכו׳: פתח ר״ש ואמר, ואתם הדבקים בה׳ אלקיכם וגו׳. מי הוא עם קדוש כישראל, שכתוב בהם אשריך ישראל מי כמוך. שכתוב, מי כמוכה באלים ה'. משום שהדבקות שלהם היא בשם הקדוש בעולם הזה, ובעולם הבא עוד יותר מבכאן מבעוה״ז, כי שם אינם נפרדים מצרור ההוא שצרורים בו הצדיקים. דהיינו צרור החיים שה״ס המלכות הקשורה בעץ החיים, שהוא ז״א. ז״ש, ואתם הדבקים בה׳. ולא כתוב הדבקים לה׳, אלא בה׳ ממש."]],[]],[["תָּאנָא, כַּד נָחִית מִן דִּיקְנָא יַקִּירָא עִלָּאָה, דְּעַתִּיקָא קַדִּישָׁא, סָתִים וְטָמִיר מִכֹּלָּא, מִשְׁחָא דִּרְבוּת קַדִּישָׁא, לְדִיקְנָא דִּזְעֵיר אַפִּין. אִתְתָּקַּן דִּיקְנָא דִּילֵיהּ, בְּתִשְׁעָה תִּקּוּנִין. וּבְשַׁעֲתָא דְּנָהִיר דִּיקְנָא יַקִּירָא דְּעַתִּיקָא דְּעַתִּיקִין, בְּהַאי דִּיקְנָא דִּזְעֵיר אַפִּין, נַגְדִּין תְּלֵיסַר מַבּוּעִין דְּמִשְׁחָא עִלָּאָה, בְּהַאי דִּיקְנָא. וּמִשְׁתַּכְחִין בֵּיהּ, עֶשְׂרִין וּתְרֵין תִּקּוּנִין. וּמִנֵּיהּ נַגְדִּין, עֶשְׂרִין וּתְרֵין אַתְוָון (ס\"א דאורייתא) דִּשְׁמָא קַדִּישָׁא. (מתחיל מסוף קל\"ח ע\"ב) (נ\"א ובעלמא דאתי, משום דאתדבקותא דילהון הוא בשמא קדישא בעלמא דין ובעלמא דאתי יתיר מהכא דהתם לא מתפרשין מההוא צרורא דחיי דצרורין ביה צדיקייא הדא הוא דכתיב ואתם הדבקים ביי ביי ממש עלייכו כתיב אשריך ישראל מי כמוך עם נושע ביי וכתיב מי כמוך באלים יי השתא אתכוונו דעתא לאוקורי למלכא ולאוקיר יקרא דדיקנא קדישא דמלכא, תנא מתתקן דיקנא עלאה דיקנא קדישא בט' תקונין ודא איהו דיקנא דזעיר אנפין וכד נחית מן דיקנא יקירא עילאה דעתיקא קדישא בהאי דיקנא דזעיר אנפין נגדין י\"ג מבועין דמשחא עילאה בהאי דיקנא ומשתכחין ביה כ\"ב תקונין ומניה נגדין כ\"ב אתוון דש\"ק) וְאִם תֹּאמַר דִּיקְנָא לָא אִשְׁתְּכַח, וְלֹא אָמַר שְׁלֹמֹה אֶלָּא (שיר השירים ה) לְחָיָיו. (ולא קארי דיקנא) אֶלָּא הָכִי תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, כָּל מַה דְּאַטְמָר וְגָנִיז, וְלָא אִדְכַּר וְלָא אִתְגַּלְיָיא. הַהוּא מִלָּה הֲוִי עִלָּאָה וְיַקִּירָא מִכֹּלָּא, (משום) וּבְגִין דָּא הוּא סָתִים וְגָנִיז. וְדִיקְנָא מִשּׁוּם דְּהוּא שְׁבָחָא וּשְׁלֵימוּתָא, וְיַקִירוּתָא מִכָּל פַּרְצוּפָא, גַּנְזֵיהּ קְרָא, וְלָא אִתְגַּלְיָיא.","וְתָאנָא, הַאי דִּיקְנָא דְּאִיהוּ שְׁלֵימוּתָא דְּפַרְצוּפָא וְשַׁפִּירוּתָא דִּזְעֵיר אַפִּין, נָפִיק מֵאוּדְנוֹי, וְנָחִית וְסָלִיק וְחָפֵי, בְּתַקְרוֹבָא דְּבוּסְמָא. מַאי תַּקְרוּבָא דְּבוּסְמָא. כְּמָה דְאַתְּ אָמֵר (שיר השירים ה׳:י״ג) לְחָיָיו כַּעֲרוּגַת הַבּוֹשֶׂם (ולא ערוגות). בְּתִשְׁעָה תִּקּוּנִין, אִתְתָּקַּן הַאי דִּיקְנָא דִּזְעֵיר אַנְפִּין. בְּשַׂעֲרֵי (דדיקנא) אוּכָמֵי, מִתַּתְקְנָא בְּתִקּוּנָא שַׁפִּיר. כְּגִבָּר תַּקִּיף שַׁפִּיר לְמֵחֱזֵי. דִּכְתִּיב, (שיר השירים ה׳:ט״ו) בָּחוּר כָּאֲרָזִים.","תִּקּוּנָא קַדְמָאָה. מְתַּתְקָּן שַׂעֲרָא מִלְּעֵילָּא, וְנָפִיק הַהוּא נִיצוֹצָא (בראשית ט' ע\"א) בּוּצִינָא דְּקַרְדִּינוּתָא, וְנָפִיק מִכְּלָלָא דַּאֲוִירָא דַּכְיָא, וּבָטַשׁ בִּתְחוֹת שַׂעֲרָא דְּרֵישָׁא, מִתְּחוֹת קוֹצִין דְּעַל אוּדְנִין. וְנָחִית מִקַּמֵּי פִּתְחָא דְּאוּדְנִין נִימֵי עַל נִימֵי, עַד רֵישָׁא דְּפוּמָא.","תִּקּוּנָא תִּנְיָינָא. נָפִיק שַׂעֲרָא, וְסָלִיק מֵרֵישָׁא דְּפוּמָא, עַד רֵישָׁא אַחֲרָא דְּפִתְחָא דְּפוּמָא. וְנָחִית מִתְּחוֹת פּוּמָא, עַד רֵישָׁא אַחֲרָא, נִימִין עַל נִימִין, בְּתִקּוּנָא שַׁפִּירָא.","תִּקּוּנָא תְּלִיתָאָה. מֵאֶמְצָעִיתָא דִּתְחוֹת חוֹטָמָא, מִתְּחוֹת תְּרֵין נוּקְבִין, נָפִיק חַד אָרְחָא, וְשַׂעֲרִין זְעִירִין תַּקִּיפִין, מַלְיָין לְהַהוּא אָרְחָא, וּשְׁאַר שַׂעֲרִין מַלְיָין מֵהַאי גִּיסָא, וּמֵהַאי גִּיסָא, סוֹחֲרָנֵיהּ דְּהַהוּא אָרְחָא. וְאָרְחָא לָא אִתְחֲזֵי לְתַתָּא כְּלַל, אֶלָּא הַהוּא אָרְחָא דִּלְעֵילָּא, דְּנָחִית עַד רֵישָׁא דְּשִׂפְוָותָן, וְתַמָּן שְׁקִיעָא הַהוּא אָרְחָא.","תִּקּוּנָא רְבִיעָאָה. נָפִיק שַׂעֲרָא, וְאִתְתָּקַּן, וְסָלִיק וְחָפֵּי בְּעִלְעוֹי דְּתִקְרוֹבָא דְּבוּסְמָא. תִּקּוּנָא חֲמִשָׁאָה. פָּסִיק שַׂעֲרָא, וְאִתְחַזְיָין תְּרֵין תַּפּוּחִין, מִכָּאן וּמִכָּאן, סוּמָקָן כְּהַאי וַרְדָא סוּמָקָא. וּמִתְלַהֲטָן בְּמָאתָן וְשִׁבְעִין עָלְמִין, דְּמִתְלַהֲטִין מִתַּמָּן (ס\"א מנהון). תִּקּוּנָא שְׁתִיתָאָה. נָפִק שַׂעֲרָא כְּחַד חוּטָא בְּסַחֲרָנֵיהּ דְּדִיקְנָא, וְתַּלְיָין עַד רֵישָׁא דְּמֵעוֹי, וְלָא נָחִית עַד טַבּוּרָא. תִּקּוּנָא שְׁבִיעָאָה. דְּלָא תַּלְיָין שַׂעְרֵי עַל פּוּמָא, וּפוּמָא אִתְפְּנֵי מִכָּל סִטְרוֹי. וְיַתְבִין שַׂעְרֵי בְּתִקּוּנָא סְחוֹר סְחוֹר לֵיהּ.","תִּקּוּנָא תְּמִינָאָה. דְּנַחְתִּין שַׂעְרֵי בִּתְחוֹת דִּיקְנָא, דִּמְחַפְּיָין קְדָלָא, דְּלָא אִתְחַזְיָא. כֻּלְּהוּ שַׂעְרֵי דְּקִיקִין, נִימִין עַל נִימִין. מַלְיָין מִכָּל סִטְרוֹי. תִּקּוּנָא תְּשִׁיעָאָה. (מתערבין שערי עם אינון) דְּמִתְחַבְּרָן (נ\"א אתמשכן) שַׂעְרֵי כֻּלְּהוּ בְּשִׁקּוּלָא מְעַלְּיָיא, (ס\"א מלייא) עַד (נ\"א עם) אִינּוּן שַׂעְרֵי דְּתַלְיָין. כֻּלְּהוּ בְּשִׁקּוּלָא שַׁפִּיר, כְּחַד גִּיבָּר תַּקִּיף, מָארֵי נָצַח קְרָבִין.","בְּתִשְׁעָה תִּקּוּנִין אִלֵּין, נַגְדִּין וְנָפְקִין ט' מַבּוּעִין דִּמְשַׁח רְבוּת דִּלְעֵילָּא. וּמֵהַהוּא מְשַׁח רְבוּת, נַגְדִּין לְכָל אִינּוּן דִּלְתַּתָּא. ט' תִּקּוּנִין אִלֵּין אִשְׁתְּכָחוּ בְּדִיקְנָא דָּא. וּבִשְׁלֵימוּת תִּקּוּנָא דְּדִיקְנָא דָּא, אִתְקְרֵי (בר נש לתתא) גִּיבָּר תַּקִּיף. דְּכָל מַאן דְּחָמֵי דִּיקְנָא קַיְּימָא בְּקִיּוּמֵיהּ, תַּלְיָיא בֵּיהּ גְּבוּרָה תַּקִיפָא. עַד כָּאן תִּקּוּנָא דְּדִיקְנָא עִלָּאָה דִּזְעֵיר אַפִּין.","אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרֵיהּ, קוּם בְּרִי (קדישא), סַלְסֵל תִּקּוּנָא דְּדִיקְנָא (נ\"א דמלכא) קַדִּישָׁא, בְּתִקּוּנוֹי אִלֵּין. קָם רִבִּי אֶלְעָזָר, פָּתַח וְאָמַר, (תהילים קי״ח:ה׳) מִן הַמֵּצַר קָרָאתִי יָהּ עָנָנִי בַמֶרְחָב יָהּ וְגוֹ'. עַד מִבְּטוֹחַ בִּנְדִיבִים. תָּנָא, הָכָא ט' תִּקּוּנִין דִּבְדִּיקְנָא דָּא. לְהָנֵי תִּקּוּנִין אִצְטְרִיךְ דָּוִד מַלְכָּא, בְּגִין לְנַצְחָא לִשְׁאַר מַלְכִין, וְלִשְׁאַר עַמִּין."],[[0,"תאנא כד נחית","וכו׳: למדנו, כשמדיקנא היקר העליון של עתיקא קדישא הסתום והנסתר מכל, יורד שמן המשחה הקדוש על הדיקנא דזעיר אנפין, מתתקן הדיקנא דז״א בתשעה תקונים. ובשעה שהדיקנא היקר של עתיק דעתיקין מאיר בעצמו בדיקנא הזה דז״א, נמשכים י״ג מבועים משמן העליון, בדיקנא דז״א, ונמצאים בו כ״ב תקונים, וממנו נמשך כ״ב אותיות התורה."],[1,"וא״ת דיקנא לא","וכו׳: ואם תאמר, שלא נמצא זקן, ושלמה לא אמר אלא לחייו, ואינו אומר דיקנא. ומשיב, אלא כך למדנו בספרא דצניעותא, כל מה שנסתר וגנוז אינו נזכר ואינו מתגלה. דבר זה, הדיקנא, הוא עליון ויקר מכל, ומשום זה הוא סתום וגנוז. ומשום שהדיקנא הוא השבח והשלמות והיקר מכל הפרצוף, ע״כ גנזו הכתוב, ואינו נגלה. ולמדנו, דיקנא הזו שהיא שלמות הפרצוף והיופי של ז״א, הוא יוצא מאזניו, ויורד ועולה ומכסה במנחת בשמים. מהו מנחת בשמים. הוא כש״א לחייו כערוגת הבושם. בתשעה תקונים נתתקן הדיקנא הזה דז״א, בשערות שחורות מתתקנות בתקון יפה, כגבור אמיץ יפה מראה. שכתוב, בחור כארזים."],[1,"","סוד השערות, כבר נתבאר לעיל בשערות רישא ודיקנא דא״א (לעיל באות כ״ד) ונתבאר שם שהן פרצוף שלם, מכו״ח בינה ותו״מ, ולפי שמקורם מפרסא שבתוך הראש, ע״כ נחלקו לכו״ח שה״ס שערות רישא המסתיימים בפאתי הראש, ולבינה ותו״מ שה״ס שערות דיקנא. וז\"ש, \u0003נפיק מאודנוי,\u0004 כי שם באזנים ה״ס הפרסא הנקראת עקימא דאודנין, והן שחורות, מטעם שגנוזה בהם המלכות דמדת הדין, שה״ס גוון אוכמא, (כנ״ל אות רי״ד) וז״ש \u0003בשערי אוכמא מתתקנא כגבר תקיף,\u0004 כי ה״ס קו האמצעי הצריך ליחד הימין והשמאל, אשר כל גבורתו היא ע״י מדת הדין שבמסך דחירק, (כנ״ל פרשת לך דף י״ג ד״ה ונתבאר ע״ש) וע״כ שערותיו שחורות. משא״כ הנוקבא שאין בה מלכות זו דמדת הדין, שערותיה אדומות. כמ״ש במקומו."],[2,"תקונא קדמאה","וכו׳: התקון הראשון. השערות מתתקנות מלמעלה, מפאתי הראש, ויוצא ניצוץ ההוא, ניצוץ הקשה, ויוצא מכלל אוירא דכיא, ובוטש מתחת שערות הראש, מתחת קווצות השער שעל האזנים, ויורד נימין על נימין, לפני פתח האזנים, עד תחלת הפה."],[2,"","פירוש. שיש ב׳ מיני מוחין בז״א, יש ד׳ מוחין שהם בבחינת או״א עלאין, שחו״ב שלהם נבחנים לאוירא דכיא ואשא דכיא, והדעת לאשא סתם ואוירא סתם, מטעם שהי׳ שנכנסה באור בינה והיתה לאויר, אינה יוצאת משם לעולם. ויש בחינת ג׳ מוחין. שהם בבחינת ישסו״ת, שהי׳ יוצאת מאויר, והבינה חוזרת להיות אור החכמה. (כנ״ל אות קפ״א וקפ״ב ע״ש). גם ידעת שהשערות נמשכות מפנימיות הראש בסוד מותרי מוחא, שהיו שם לבושין דג״ר דחכמה, ומכח המלכות שעלתה לבינה בסוד הפרסא, שמיעטה קו השמאל מג\"ר נסתלק אור הג\"ר ההוא לשורשו, והלבושים שהיו או״ח נשארו ויצאו מראש בבחינת פסולת להיותם ריקנים מאורותיהם. ונבחן שהמסך הזה ששימש בבינה עלאה, בסוד או״א עלאין, שבינה היתה שם בכלל אוירא דכיא והיתה נקראת אשא דכיא, נפרדה מבחינת אוירא דכיא, וירדה לאויר סתם, שהיא בימין ושמאל שבדעת הנקראים אוירא סתם ואשא סתם, דהיינו לבחינת הפרסא המבדלת ומסיימת את או״א, ששם עלתה המלכות דמדת הדין ונכללה בבינה. ומשם בטש ניצוצא דמדת הדין באמצע פרצוף השערות דהיינו מתחת שערות רישא, ונחלקו השערות לכו״ח עד פאתי הראש, שה״ס שערות רישא, ומפאתי הראש ולמטה ירדו בינה ותו״מ ונעשו לשערות דיקנא."],[2,"","וז״ש, \u0003מתתקן שערא מלעילא,\u0004 ששערות דיקנא מתתקנות משערות רישא, ומפרש, \u0003ונפיק ההוא ניצוצא בוצינא דקרדינותא\u0004 דהיינו ניצוץ המסך דבינה עלאה הנקראת אשא דכיא מטעם שמחוברת באוירא דכיא, \u0003ונפיק מכללא דאוירא דכיא,\u0004 שהניצוץ יורד מבינה עלאה למקום הפרסא שמתחת חו״ב עלאין, ששם כלולה המלכות דמדת הדין, שאינה בבחינת אוירא דכיא, \u0003ובטש בתחות שערא דרישא מתחות קוצין דעל אודנין,\u0004 שבוטש באמצע פרצוף השערות שהוא בסיום שערות ראש תחת קווצות השער שעל האזנים, ונבקע פרצוף השערות לב' חצאים לכו״ח, ולבינה ותו״מ, שכו״ח נעשו לשערות ראש ונסתיימו \u0003מתחות קוצין דעל אודנין,\u0004 ובינה ותו״מ דפרצוף השערות נעשו לשערות דיקנא, \u0003ונחית מקמי פתחא דאודנין נימי על נימי עד רישא דפומא\u0004 וירד, תקון הא' דשערות דיקנא, מלפני פתח האזן עד תחלת הפה. כי שערות רישא, שהם כו״ח דשערות נדבקו בגלגלתא דהיינו בראש ז״א, ובחינת בינה ותו״מ דשערות יצאו מבחינת ראש ונדבקו בתחילת הגוף שה״ס הלחי התחתונה דראש ז״א. (ע״ד שנתבאר לעיל באות צ״ה ע׳יש) וע״כ נתפשט תקון הא׳ דדיקנא בלחי התחתונה מפתח האזנים עד תחילת הפה."],[3,"תקונא תנינא","וכו׳: התקון השני. השערות יוצאות ועולות מתחילת הפה, דהיינו השפה העלאה, עד ראש האחר דפתח הפה. ויורדות גם מתחת הפה מראש אחד עד ראש האחר של השפה תתאה, נימין על נימין בתקון יפה. (הביאור של ט׳ תקוני דיקנא תמצא מאות רנ״ז ואילך)."],[4,"תקונא תליתאה","וכו׳: התקון השלישי. מן האמצע שמתחת החוטם מתחת ב׳ נקבי החוטם, יוצא דרך אחד פנוי משערות, אבל שערות קטנות קשות ממלאות דרך ההוא. ושאר השערות מלאות מצד זה ומצד זה מסביב אותו הדרך. ולמטה, בשפה תתאה, לא נראה דרך כלל שיהיה פנוי משערות, אלא שנראה רק אותו הדרך שלמעלה, על שפה עלאה, היורד עד תחילת חיבור השפות, ושם נשקע אותו הדרך. ואינו נמשך למטה תחת השפה התחתונה כמו בא״א. (לעיל אות קל״א)."],[5,"תקונא רביעאה","וכו׳: התקון הרביעי. שערות יוצאות ומתתקנות ועולות ומכסות בלחייו, במנחת הבושם. שהסו״ה לחייו כערוגת הבושם. \u0003התקון החמשי.\u0004 השערות נפסקות מלצמוח, ונראים ב׳ תפוחי הפנים, הפנויות משערות, מכאן ומכאן, אדומות כשושנה אדומה. ומתלהטים בר״ע עולמות, הלוהטים משם. \u0003התקון הששי.\u0004 השערות יוצאות כחוט אחד מסביב הדיקנא, ותלויות עד תחילת מעיו, דהיינו עד החזה, ואינו יורד עד הטבור. \u0003התקון השביעי.\u0004 השערות אינן תלויות על הפה, והפה פנוי משערות מכל הצדדים, והשערות יושבות בתקון סביב סביב לו."],[6,"תקונא תמינאה","וכו׳: התקון השמיני. השערות יורדות תחת הדיקנא, ומכסות העורף שלא יהיה נראה. כל השערות דקות נימין על נימין מלאים מכל הצדדים. \u0003התקון התשיעי.\u0004 השערות מתחברות כולן במשקל שוה עם אלו שערות התלויות. כולן במשקל יפה כגבור אמיץ בעל נוצח מלחמות."],[7,"בתשעה תקונין אלין","וכו׳: בט' תקונים אלו נמשכים ויוצאים ט׳ מבועים של שמן המשחה שלמעלה. ומשמן המשחה ההוא נמשך לכל אלו שלמטה. ט׳ תקונים אלו נמצאים בדיקנא זו דז״א, ובשלמות תקון של דיקנא זה, הוא נקרא גבור אמיץ, שכל מי שרואה הדיקנא עומד בקיומו, תלויה בו גבורה אמיצה. עד כאן תקון דיקנא העליונה דזעיר אנפין."],[8,"אמר ר׳ שמעון","וכו׳: אר״ש לר׳ אלעזר בנו, קום בני, סלסל תקון הדיקנא הקדוש באלו התקונים. קם ר׳ אלעזר, פתח ואמר, מן המצר קראתי יה ענני במרחב יה וגו' עד מבטוח בנדיבים. למדנו כאן, במקרא הזה, תשעת התקונים שישנם בדיקנא זה דז״א לאלו התקונים היה צריך דוד המלך כדי לנצח שאר המלכים ושאר העמים."]],[]],[["תָּא חֲזֵי, כֵּיוָן דְּאָמַר הָנֵי ט' תִּקּוּנִין, לְבָתַר אָמַר כָּל גּוֹיִם סְבָבוּנִי בְּשֵׁם יְיָ כִּי אֲמִילַם. אָמַר, הָנֵי תִּקּוּנִין דַּאֲמֵינָא, לְמַאי אִצְטְרִיכְנָא. מִשּׁוּם דְּכָל גּוֹיִם סְבָבוּנִי. וּבְתִקּוּנָא דְּדִיקְנָא דָּא, ט' תִּקּוּנִין, דְּאִינּוּן שֵׁם יְיָ, אַשֵצִינוּן מִן עָלְמָא, הֲדָא הוּא דִכְתִיב בְּשֵׁם יְיָ כִּי אֲמִילַם.","וְתָנָא בִּצְנִיעוּתָא דְּסִפְרָא, תִּשְׁעָה תִּקּוּנִין אָמַר דָּוִד, הָכָא, שִׁיתָא אִינּוּן בִּשְׁמָא קַדִּישָׁא. דְּשִׁית שְׁמָהָן הֲווֹ, וּתְלַת אָדָם. וְאִי תֵּימָא תְּרֵין אִינּוּן. תְּלָתָא הֲווֹ, דְּהָא נְדִיבִים בִּכְלַל אָדָם הֲווֹ.","תָּנָא שִׁיתָא שְׁמָהָן, דִּכְתִּיב: מִן הַמֵּצַר קָרָאתִי יָהּ, חַד. עָנָנִי בַמֶרְחָב יָהּ, תְּרֵין. יְיָ לִי לֹא אִירָא, תְּלַת. יְיָ לִי בְּעוֹזְרָי, אַרְבַּע. טוֹב לַחֲסוֹת בַּיְיָ, חֲמִשָּׁה. טוֹב לַחֲסוֹת בַּיְיָ, שִׁיתָא. אָדָם תְּלַת, דִּכְתִּיב: יְיָ לִי לֹא אִירָא מַה יַעֲשֶׂה לִי אָדָם, חַד. טוֹב לַחֲסוֹת בַּיְיָ מִבְּטוֹחַ בָּאָדָם, תְּרֵי. טוֹב לַחֲסוֹת בַּיְיָ מִבְּטוֹחַ בִּנְדִיבִים, תְּלַת.","וְתָּא חֲזֵי רָזָא דְּמִלָּה, דִּבְכָל אֲתָר דְּאִדְכַּר אָדָם הָכָא, לָא אִדְכַּר אֶלָּא בִּשְׁמָא קַדִּישָׁא. דְּהָכִי אִתְחֲזֵי. מִשּׁוּם דְּלָא אִקְרֵי (הוה) אָדָם, אֶלָּא בְּמָה דְּאִתְחֲזֵי לֵיהּ. וּמַאי אִתְחֲזֵי לֵיהּ. שְׁמָא קַדִּישָׁא. דִּכְתִּיב, (בראשית ב׳:ז׳) וַיִּיצֶר יְיָ אֱלֹהִים אֶת הָאָדָם, בְּשֵׁם מָלֵא, דְּהוּא יְיָ אֱלֹהִים. כְּמָה דְּאִתְחֲזֵי לֵיהּ וּבְגִין כָּךְ הָכָא לָא אִדְכַּר אָדָם אֶלָּא בִּשְׁמָא קַדִּישָׁא.","וְתָנָא, כְּתִיב מִן הַמֵּצַר קָרָאתִי יָהּ עָנָנִי בַמֶרְחָב יָהּ, תְּרֵי זִמְנֵי יָ\"הּ יָ\"הּ, לָקֳבֵיל תְּרֵי עִלְעוֹי, דְּשַׂעְרֵי אִתְאַחֲדָן בְּהוּ. וּמִדְחָמָא דְּשַׂעְרֵי אִתְמַשְּׁכָאן וְתַלְיָין, שָׁארֵי וְאָמַר יְיָ לִי לֹא אִירָא. יְיָ לִי בְּעוֹזְרָי. בִּשְׁמָא דְּלָא חָסֵר. בִּשְׁמָא דְּהוּא קַדִּישָׁא. וּבִשְׁמָא דָּא, אַדְכַּר אָדָם.","וּמַה דְּאָמַר מַה יַּעֲשֶׂה לִי אָדָם, הָכִי הוּא. דְּתָנָא כָּל אִינּוּן כִּתְרִין קַדִּישִׁין דְּמַלְכָּא, כַּד אִתְתַּקְנָן בְּתִקּוּנוֹי. אִתְקְרוּן אָדָם. דִּיּוּקְנָא דְּכָלִיל כֹּלָּא. וּמַה דְּמַשְׁלְפָא בְּהוּ, אִתְקְרֵי שְׁמָא קַדִּישָׁא. וְתַּעְרָא וּמַה דְּבֵיהּ, אִתְקְרֵי ידו\"ד, וְאִתְקְרֵי אָדָם בִּכְלָלָא דְּתַּעְרָא, וּמַה דְּבֵיהּ.","וְאִלֵּין תִּשְׁעָה תִּקּוּנִין דְּאָמַר דָּוִד הָכָא, לְאַכְנְעָא שַׂנְאוֹי בְּגִין דְּמַאן דְּאָחִיד דִּיקְנָא דְּמַלְכָּא, וְאוֹקִיר לֵיהּ בְּיָקִירוּ עִלָּאָה, כָּל מַה דְּבָעֵי מִן מַלְכָּא. מַלְכָּא עָבִיד בְּגִינֵיהּ. מַאי טַעְמָא דִּיקְנָא, וְלָא גּוּפָא. אֶלָּא גּוּפָא אָזִיל בָּתַר דִּיקְנָא, וְדִיקְנָא לָא אָזִיל בָּתַר גּוּפָא. (ס\"א ומה דאשתליף מתערא אתקרי שמא קדישא, תערא ומה דביה אתקרי יהו\"ה אתקרי אדם בכלא תערא ומה דביה) (ול\"ג מן ודיקנא עד וגופא)","וּבִתְרֵי גְּוָונֵי אָתֵי הַאי חוּשְׁבָּנָא, חַד כִּדְקַאמְרָן. תְּרֵין: מִן הַמֵּצַר קָרָאתִי יָּהּ, חַד. עָנָנִי בַמֶרְחָב יָהּ, תְּרֵי. ה' לִי לֹא אִירָא, תְּלַת. מַה יַּעֲשֶׂה לִי אָדָם, אַרְבַּע. ה' לִי בְּעוֹזְרָי, חָמֵשׁ. וַאֲנִי אֶרְאֶה בְּשוֹנְאָי, שִׁיתָא. טוֹב לַחֲסוֹת בַּה', שִׁבְעָה. מִבְּטוֹחַ בָּאָדָם, תְּמַנְיָיא. טוֹב לַחֲסוֹת בַּיְיָ מִבְּטוֹחַ בִּנְדִיבִים, תִּשְׁעָה. (ס\"א טוב לחסות בה', מבטוח באדם. ז. טוב לחסות בה'. ח. מבטוח בנדיבים)","מִן הַמֵּצַר קָרָאתִי יָּ\"הּ, מַאי קָא מַיְירֵי אֶלָּא דָּוִד, כָּל מָה דְּאָמַר הָכָא, עַל תִּקּוּנָא דְּדִיקְנָא דָּא קָאָמַר. (רבי יהודה אמר) מִן הַמֵּצַר קָרָאתִי יָהּ, מֵאֲתָר דְּשָׁארִי דִּיקְנָא לְאִתְפַּשְׁטָא, דְּהוּא אֲתָר דָּחִיק, מִקַּמֵּי פִּתְחָא דְּאוּדְנִין מֵעֵילָּא, תְּחוֹת שַׂעְרֵי דְּרֵישָׁא. וּבְגִין כָּךְ אָמַר יָ\"הּ יָ\"ה תְּרֵי זִמְנֵי. וּבַאֲתָר (ס\"א ובתר) דְּאִתְפְּשַׁט דִּיקְנָא, וְנָחִית מֵאוּדְנוֹי, וְשָׁארִי לְאִתְפַּשְׁטָא, אָמַר יְיָ לִי לֹא אִירָא, דְּהוּא אֲתָר דְּלָא דָּחִיל (ס\"א דחיק) וְכָל הַאי אִצְטְרִיךְ וְכוּ', (אדם אתקרי ועל אתפשטותא האי אצטריך) דָּוִד לְאַכְנָע תְּחוֹתֵיהּ מַלְכִין וְעַמִּין, בְּגִין יְקָרָא דְּדִיקְנָא דָּא.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, כָּל מַאן דְּחָמֵי בְּחֶלְמֵיהּ דְּדִיקְנָא דְּבַר נָשׁ עִלָּאָה אָחִיד בִּידֵיהּ, אוֹ דְּאוֹשִׁיט יְדֵיהּ לֵיהּ. יִנְדַּע דִּשְלִים הוּא עִם עִלָּאֵי, וְאַרְמֵיה תְּחוֹתֵיהּ אִינּוּן דִּמְצַעֲרִין לֵיהּ. תָּנָא, מְתַּתְקָּן דִּיקְנָא עִלָּאָה בְּתִשְׁעָה תִּקּוּנִין, וְהוּא דִּיקְנָא דִּזְעֵיר אַפִּין, בְּט' תִּקּוּנִין מְתַּתְקָּן."],[[0,"ת״ח כיון דאמר","וכו׳: בוא וראה כיון שאמר אלו ט׳ תקונים לבסוף, אמר, כל גוים סבבוני בשם ה׳ כי אמילם. אמר אלו תקונים שאמרתי למה אני צריך להם, הוא משום דכל גוים סבבוני. שבתקון דיקנא הזה ט׳ תקונים, שהם שם הויה, ועל ידיהם אכלם מן העולם, ז״ש בשם ה׳ כי אמילם."],[1,"ותנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא, ט׳ תקונים אמר דוד כאן, במקראות מן המצר וגו׳, ששה הם בשם הקדוש, שיש במקראות אלו ששה שמות. וג׳ פעמים אדם. ואם תאמר, שתי פעמים אדם הם, לא כן, אלא ג׳ הם, כי נדיבים בכלל אדם הם, ונחשבת המלה נדיבים, כמו שהיה אומר, אדם, ויש ג״פ אדם. כמו שהולך ומפרש לפנינו."],[2,"תנא שיתא שמהן","וכו׳: למדנו, ששה שמות הם, שכתוב: א) מן המצר קראתי \u0003יה\u0004. ב) ענני במרחב \u0003יה.\u0004 ג) \u0003ה׳\u0004 לי לא אירא. ד) \u0003ה׳\u0004 לי בעוזרי. ה) טוב לחסות ב \u0003ה׳\u0004. ו) טוב לחסות ב \u0003ה׳.\u0004 שבמקרא הב'. הרי שיש כאן ששה שמות. ג׳ פעמים אדם, שכתוב: א) ה׳ לי לא אירא מה יעשה לי \u0003אדם.\u0004 ב) טוב לחסות בה׳ מבטוח ב \u0003אדם. ג) טוב לחסות בה׳ מבטוח בנדיבים.\u0004 כי נדיבים, הם כמו שאומר, אדם, כנ״ל. הרי שיש כאן ג׳ פעמים אדם."],[2,"","פירוש. עקרו של ז״א הוא ו״ק, והשאר בא לו בתקונים בסוד תוספת על העיקר. ולפיכך מבחינת עיקרו של ז״א, אין בדיקנא שלו אלא ששה תקונים, כנגד ו״ק. אמנם ע״י תקונים, נוספים לו בחינת ו״ק דג׳ מוחין חב״ד, והם ט׳ תקונים. וז״ש \u0003שיתא אינון בשמא קדישא,\u0004 דהיינו בז״א שנקרא הויה, \u0003דשית שמהן הוו\u0004 וע״כ יש ששה שמות במקראות של מן המצר, שהם כנגד ו״ק שבדיקנא, \u0003ותלת אדם,\u0004 וג״פ אדם שהם כנגד ו״ק דחב״ד שבו, הנקראים אדם. בסוד הויה במילוי אלפין שבגי׳ אדם. וז״ש \u0003תנא שיתא שמהן דכתיב מן המצר\u0004 וכו', היינו ששה תקונים הראשונים כנגד ו״ק דז״א. \u0003אדם תלת\u0004 וכו', היינו כנגד ו״ק דג״ר דז״א."],[3,"ות״ח רזא דמלה","וכו׳: ובוא וראה סוד הדבר, שבכל מקום שנזכר כאן אדם לא נזכר אלא בשם הקדוש, כלומר, שבאותו פסוק שנזכר בו אדם נזכר בו הויה. משום שכך ראוי להיות, משום שלא נקרא אדם אלא במה שראוי לו. ומה ראוי לו לשם אדם. הוא השם הקדוש הויה. כלומר מטרם שנשלם השם הקדוש הויה, אין המוחין הקרואים אדם מתלבשים בו. שכתוב, וייצר \u0003הויה אלקים\u0004 את האדם, שהויה אלקים ה״ס חכמה ובינה, את האדם, היינו המוחין דצלם דז״א, המכונים אדם. והיינו, בשם מלא שהוא הויה אלקים, כמו שראוי לו לשם אדם. ומשום זה לא נזכר אדם אלא ביחד עם השם הקדוש."],[4,"ותנא כתיב מן","וכו׳: ולמדנו, כתוב מן המצר קראתי יה ענני במרחב יה, דהיינו ב״פ יה יה. והוא כנגד ב׳ לחיים שהשערות מתאחזות בהם. ומשראה דוד, שהשערות נמשכות ותלויות, פתח ואמר הויה לי לא אירא הויה לי בעוזרי, דהיינו בשם שלם הויה. בשם שלא חסר בו ו״ה, בשם שהוא קדוש. ובשם מלא זה נזכר אדם. כי אין המוחין שורים אלא בשם מלא כנ״ל."],[4,"","פירוש תקון א׳ דדיקנא, ה״ס מן המצר קראתי יה, ששם השערות קצרות מאד, שזה מורה שאין החסדים נמשכים מהם בהרבה. והוא משום ששם כלולה המלכות דמדת הדין, כמ״ש בתקון א׳ דדיקנא דא״א (כנ״ל אות צ׳) ושערות קצרות אלה הן אחוזות בתחילת הלחי התחתונה תחת פאתי הראש. ואח״כ בתקון הרביעי עולות השערות מהלחי התחתונה, על הלחי העליונה שה״ס בינה כלומר, שנמתקו בבינה הנקראת רחובות ומתמתקים שם ומתפשטים במרחב הזקן, וה״ס ענני במרחב יה, שה״ס מרחב הזקן, ומרחב. וז״ש, \u0003מן המצר\u0004 וגו׳ \u0003תרי זמני יה יה, לקבל תרי עלעוי,\u0004 שהם כנגד ב׳ הלחיים, שהשם יה הראשון הוא בלחי העליונה, ושם יה השני הוא בלחי התחתונה כנ״ל. ואח״כ התחילו השערות להתפשט במרחב הזקן, וז״ש \u0003ומדחמא דשערי אתמשכאן ותליין, שארי ואמר הויה\u0004 וגו׳. שאז נשלם שם המלא הויה, ואינו חסר עוד ו״ה. כי התרחבות השערות מורה על ריבוי החסדים."],[5,"ומה דאמר מה","וכו׳: ומה שאומר מה יעשה לי אדם, שהוא שם תקון של התפשטות המוחין כנ״ל. כך הוא פירושו. שלמדנו, כל אלו הספירות הקדושות של המלך כשנתקנו בתקונים, דהיינו שנמשכים בהן המוחין, נקראים \u0003אדם,\u0004 שהוא צורה הכוללת כל הצורות, כי ג׳ הצורות אריה שור נשר כלולות בצורת אדם. שה״ס המלכות הכוללת בתוכה כל ג׳ הקוין. וע״כ יחוד ג׳ מוחין חב״ד, שהם כנגד אריה שור נשר, אינם אלא בצורת אדם. וע״כ נבחן לו\"ק דמוחין דחב״ד, כי המלכות היא אור נקבה המאירה רק ממטה למעלה שה״ס ו״ק דמוחין. ומה שיוצא מהם מן המוחין, דהיינו המושג לתחתונים, נקרא שם הקדוש. כי שם פירושו השגה. והנרתיק, שה״ס המלכות, המכונה נרתיק, ומה שבו, שהם המוחין: נקראים הויה, ונקראים אדם, דהיינו בכלל הנרתיק ומה שבו."],[5,"","פירוש. שיעור המוחין המקובל בנרתיק, שה״ס המלכות עם הנרתיק, שניהם ביחד נקראים \u0003אדם,\u0004 ונקראים שם שלם \u0003הויה.\u0004 השם \u0003אדם\u0004 הוא על מה שבו, דהיינו על מציאות המוחין בז״א עצמו. והשם \u0003הויה,\u0004 הוא על היוצא, ומושג ממנו לתחתונים, כי כל שם פירושו השגה."],[6,"ואלין תשעה תקונין","וכו׳: ואלו ט׳ תקונים שאמר דוד כאן, הוא כדי להכניע שונאיו. משום שמי שנאחז בדיקנא של המלך ומוקירו ביקר העליון, כל מה שרוצה מן המלך, המלך עושה בשבילו. שואל, מה הטעם שצריך להתאחז בדיקנא, ולא בגופו. ומשיב, אלא הגוף הולך אחר הדיקנא, שכל אורות הגוף נמשכים מן הדיקנא, אבל הדיקנא אינו הולך אחר הגוף. ולפיכך כשנאחז בדיקנא אחוז גם בגוף וכשנאחז בגוף עוד לא נאחז בדיקנא."],[7,"ובתרי גווני אתי","וכו׳: ובב׳ אפנים בא חשבון ההוא של ט׳ תקוני דיקנא במקראות של מן המצר. א׳. כמו שאמרנו. שמן המצר קראתי יה הוא תקון א׳ וענני במרחב יה, הוא תקון הרביעי הנקרא כאן בחשבון שלפנינו מה יעשה לי אדם. ב׳ הוא החשבון שלפנינו. אשר מן המצר קראתי יה, הוא תקון א'. ב) ענני במרחב יה. ג) ה׳ לי לא אירא. ד) מה יעשה לי אדם. ה) ה׳ לי בעוזרי. ו) ואני אראה בשונאי. ז) טוב לחסות בה׳. ח) מבטח באדם. ט) טוב לחסות בה׳ מבטוח בנדיבים."],[8,"מן המצר קראתי","וכו׳: שואל, תקון הא׳ שנקרא, מן המצר קראתי יה, מה זה אומר, למה נקרא כך. ומשיב, אלא דוד, כל מה שאמר כאן, דהיינו, כל שאר ח׳ תקוני דיקנא, אמר על תקון זה של הדיקנא הראשון, \u0003מן המצר קראתי יה,\u0004 היינו ממקום שהדיקנא מתחיל להתפשט שהוא מקום \u0003צר,\u0004 למעלה לפני פתח האזנים תחת שערות ראש. כלומר, ששם השערות קצרות והשטח צר, שמורה על מדת הדין שיש בדיקנא וע״כ נקרא, מן המצר, ומשום זה, אמר \u0003יה יה\u0004 ב׳ פעמים, דהיינו בתקון א׳ ובתקון ב׳, מטרם שמתחיל הדיקנא להתרחב. כי \u0003י״ה\u0004 מורה שהשם חסר ו\"ה. אלא במקום שנתפשט הדיקנא, שירד מאזניו ומתחיל להתפשט, דהיינו בתקון הג', אמר, הויה לי לא אירא דהיינו שם שלם י״ה ו״ה, משום שהוא מקום שאינו צר. ולפיכך כל התקונים באים להמתיק הדין שבתקון הא׳, שהשם אינו שלם בו. וכל אלו התקונים היה צריך דוד כדי להכניע תחתיו מלכים ועמים על ידי היקר של דיקנא זה."],[9,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בסד״צ, כל מי שרואה בחלומו, שידו אוחזת בזקן של אדם חשוב, או ששולח ידו לאחוז בו, ידע שהוא בשלמות עם העליונים, וישליך תחתיו כל אלו המצערים אותו. כי הדיקנא מורה, על הכנעת השונאים ועל השלמות, כנ״ל. למדנו, הדיקנא העליון מתתקן בט' תקונים, והוא דיקנא דזעיר אנפין, המתתקן בט' תקונים. כי דיקנא דא״א מתתקן בי״ג תקונים."]],[]],[["תִּקּוּנָא קַדְמָאָה. מְתַּתְקָּן שַׂעֲרָא מֵעֵילָּא, וְנָפִיק מִקַּמֵּי פִּתְחָא דְּאוּדְנִין, מִתְּחוֹת קוֹצֵי דְּתַּלְיָין עַל אוּדְנִין, וְנַחְתִּין שַׂעְרֵי, נִימִין עַל נִימִין, עַד רֵישָׁא דְּפוּמָא. תָּאנָא, כָּל אִלֵּין נִימִין דִּבְדִיקְנָא, תַּקִּיפִין יַתִּיר מִכָּל נִימִין דְּקוֹצִין דְּשַׂעְרֵי דְּרֵישָׁא, וְשַׂעְרֵי דְּרֵישָׁא אֲרִיכִין (וכפיין), וְהָנֵי לָאו אֲרִיכִין, וְשַׂעְרֵי דְּרֵישָׁא, מִנְּהוֹן שְׁעִיעֵי, וּמִנְהוֹן קְשִׁישִׁין.","וּבְשַׁעֲתָא דְּאִתְמַשְּׁכָן שַׂעְרֵי חִוָּורֵי דְּעַתִּיק יוֹמִין, לְשַׂעְרֵי דִּזְעֵיר אַפִּין, כְּתִיב, (משלי א׳:כ׳) חָכְמוֹת בַּחוּץ תָּרֹנָּה. מַאי בַּחוּץ. בְּהַאי זְעֵיר אַפִּין. דְּמִתְחַבְּרַן תְּרֵי מוֹחֵי.","תְּרֵי מוֹחֵי סַלְּקָא דַּעְתָּךְ. אֶלָּא אֵימָא אַרְבַּע מוֹחֵי. תְּלַת מוֹחֵי דַּהֲווֹ בִּזְעֵיר אַפִּין, וְאִשְׁתְּכָחוּ בִּתְלַת חַלָלֵי דְּגוּלְגַּלְתָּא דְּרֵישָׁא. וְחַד מוֹחָא שָׁקִיט עַל בּוּרְיֵיהּ, דְּכָלִיל כָּל תְּלַת מוֹחֵי. דְּאִתְמְשָׁךְ מִנֵּיהּ מְשִׁיכָן כְּלִילָן שְׁקִילָן, בְּשַׂעֲרֵי חִוָּורֵי. לְהַאי זְעֵיר אַפִּין לִתְלַת מוֹחֵי דְּבֵיהּ.","וּמִשְׁתַּכְחָן אַרְבַּע מוֹחֵי בְּהַאי זְעֵיר אַפִּין. בְּגִין כַּךְ אִשְׁתְּלִימוּ אַרְבַּע פָּרָשִׁיּוֹת דִּכְתִּיבִין בַּתְּפִילִּין, דְּאִתְכְּלִיל בְּהוּ שְׁמָא קַדִּישָׁא דְּעַתִּיק יוֹמִין, עַתִּיקָא דְּעַתִּיקִין, וּזְעֵיר אַפִּין. דְּהַאי הוּא שְׁלֵימוּתָא דִּשְׁמָא קַדִּישָׁא. דִּכְתִּיב, (דברים כ״ח:י׳-י״א) וְרָאוּ כָל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ נִקְרָא עָלֶיךָ וַיִּרְאוּ מִמֶּךָּ. שֵׁם יְיָ. שֵׁם יְיָ מַמָשׁ, דְּאִינּוּן אַרְבַּע רְהִיטֵי בָּתֵּי דִּתְפִילִּין.","וּבְגִין כָּךְ, (קל\"א ע\"ב, רס\"ב ע\"א) חָכְמוֹת בַּחוּץ תָּרֹנָּה. דְּהָכָא מִשְׁתַּכְּחִין. דְּהָא עַתִּיקָא דְּעַתִּיקִין, סְתִימָא דִּסְתִּימִין, לָא אִשְׁתְּכַח, וְלָא זַמִּין חָכְמְתָא דִּילֵיהּ, מִשּׁוּם דְּאִית חָכְמְתָא סְתִימָא דְּכֹלָּא וְלָא אִתְפְּרַשׁ. וּבְגִין דְּאִתְחַבָּרוּ אַרְבָּעָה מוֹחִין בְּהַאי זְעֵיר אַפִּין. אִתְמַשְּׁכָן אַרְבַּע מַבּוּעִין מִנֵּיהּ לְאַרְבַּע עִיבָר, וּמִתְפָּרְשָׁן מֵחַד מַבּוּעָא, דְּנָפִיק מְכֻּלְּהוּ. וּבְגִין כָּךְ אִינּוּן אַרְבַּע.","וְתָאנָא, הַאי חָכְמְתָא דְּאִתְכְּלִילָא בְּאַרְבַּע, אִתְמַשְּׁכָא בְּהָנֵי שַׂעְרֵי, דְּאִינּוּן תַּלְיָין תִּלִּין עַל תִּלִּין. (נ\"א הוא) וְכֻלְּהוּ קַשְׁיָין וְתַקִיפִין, וְאִתְמַשְּׁכוּ וּנְגִידוּ כָּל חַד לְסִטְרוֹי. וְאֶלֶף אַלְפִין וְרִבּוֹא רִבְּבָן תַּלְיָין, מִנַּיְיהוּ דְּלֵיתְהוֹן בְּחוּשְׁבָּנָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:י״א) קְווּצּוֹתָיו תַּלְתַּלִּים. תִּלֵי תִּלִּים. וְכֻלְּהוּ קַשְׁיָין וְתַקִיפִין לְאִתְחַבְּרָא, כְּהַאי חַלָּמִיש תַּקִּיף. וּכְהַאי טִנְרָא דְּאִיהִי תַּקִּיפָא. עַד דְּעַבְדִין נוּקְבִין וּמַבּוּעִין מִתְּחוֹת שַׂעֲרָא, וְנַגְדִּין מַבּוּעִין תַּקִּיפִין לְכָל עִיבָר וְעִיבָר לְכָל סְטָר וּסְטָר. וּבְגִין דְּהָנֵי שַׂעְרֵי אוּכָמֵי וַחֲשׁוֹכָן, כְּתִיב (איוב י״ב:כ״ב) מְגַלֶּה עֲמוּקוֹת מִנִּי חֹשֶׁךְ וַיּוֹצֵא לָאוֹר צַלְמָוְת.","וְתָנָא, הָנֵי שַׂעְרֵי דְּדִיקְנָא תַּקִּיפִין (בלחודי) מִשְּׁאַר שַׂעְרֵי דְּרֵישָׁא, מִשּׁוּם דְּהָנֵי בִּלְחוֹדַיְיהוּ מִתְפָּרְשָׁן וּמִשְׁתַּכְחָן, וְאִינּוּן תַּקִּיפִין בְּאוֹרְחַיְיהוּ.","אֲמַאי תַּקִּיפִין. אִי תֵּימָא, מִשּׁוּם דְּכֻלְּהוּ דִּינָא, לָאו הָכִי, דְּהָא בְּתִקוּנִין אִלֵּין אִשְׁתְּכָחוּ רַחֲמֵי (ודינא). וּבְשַׁעֲתָא דְּנַחְתִּין תְּלֵיסַר מַבּוּעֵי נַהֲרֵי דְּמִשְׁחָא, אִלֵּין כֻּלְּהוּ רַחֲמֵי.","אֶלָּא תָּאנָא, כָּל הָנֵי שַׂעְרֵי דְּדִיקְנָא, כֻּלְּהוּ תַּקִּיפִין. מַאי טַעְמָא. כָּל אִינּוּן דְּרַחֲמֵי, בַּעְיָין לְמֶהֱוִי תַּקִּיפִין. לְאַכְפְּיָיא לְדִינָא. וְכָל אִינּוּן דְּאִינְהוּ דִּינָא, הָא תַּקִּיפִין אִינּוּן. וּבֵין כַּךְ וּבֵין כַּךְ בַּעְיָין לְמֶהֱוִי תַּקִּיפִין, מִתְּרֵין סִטְרִין. כַּד בָּעֵי עָלְמָא רַחֲמִין, רַחֲמֵי תַּקִּיפִין וְנַצְחִין עַל דִּינָא. וְכַד בָּעֵי דִּינָא, דִּינָא תַּקִּיף, וְנָצַח עַל רַחֲמֵי. וּבְגִין כָּךְ בַּעְיָין לְמֶהֱוִי תַּקִּיפִן מִתְּרֵין סִטְרִין, דְּכַד בָּעוּ רַחֲמֵי, שַׂעְרֵי דְּאִינּוּן בְּרַחֲמֵי, קַיְימִין וּמִתְחַזְיָא (ס\"א מתאחדא) דִּיקְנָא בְּאִינּוּן שַׂעְרֵי, וְכֹלָּא הֲווֹ רַחֲמֵי. וְכַד בַּעְיָיא דִּינָא, אִתְחַזְיָיא דִּיקְנָא בְּאִינּוּן שַׂעְרֵי. וְכֹלָּא אִתְקַיָּים בְּדִיקְנָא.","וְכַד אִתְגַּלְיָיא דִּיקְנָא קַדִּישָׁא חִוָּורָא, כָּל הָנֵי וְכָל הָנֵי מִתְנַהֲרִין וּמִסְתַּחְיָין, כְּמַאן דְּאִסְתְּחֵי בְּנַהֲרָא עֲמִיקָא מִמָּה דְּהֲוָה בֵּיהּ. וְאִתְקְיָימוּ כֻּלְּהוּ בְּרַחֲמֵי, וְלֵית דִּינָא אִשְׁתְּכַח, וְכָל הָנֵי תִּשְׁעָה כַּד נַהֲרִין כַּחֲדָא, כֻּלְּהוּ אִסְתַּחְיָין בְּרַחֲמֵי.","וּבְגִין כָּךְ אָמַר מֹשֶׁה זִמְנָא אַחֲרָא, (במדבר י״ד:י״ח) יְיָ אֶרֶךְ אַפַּיִם וְרַב חֶסֶד. וְאִלּוּ אֱמֶת לָא קָאָמַר. מִשּׁוּם דְּרָזָא דְּמִלָּה, אִינּוּן תִּשְׁעָה מְכִילָן דְּנַהֲרִין מֵעַתִּיק יוֹמִין לִזְעֵיר אַפִּין. וְכַד אָמַר מֹשֶׁה זִמְנָא תִּנְיָינָא, תִּשְׁעָה תִּקּוּנִין אָמַר. וְאִינְהוּ תִּקּוּנֵי דִּיקְנָא דְּמִשְׁתַּכְּחֵי בִּזְעֵיר אַפִּין, וְנַחְתִּין מֵעַתִּיק יוֹמִין וְנַהֲרִין בֵּיהּ. וּבְגִין כָּךְ אֱמֶת תַּלְיָיא בְּעַתִּיקָא, וְהַשְּׁתָּא לָא אָמַר מֹשֶׁה וְאֱמֶת."],[[0,"תקונא קדמאה","וכו׳: התקון הראשון. השערות מתתקנות מלמעלה, ויוצאות לפני פתח האזנים מתחת קווצות שערות הראש התלויות על האזנים, והשערות יורדות נימין על נימין עד תחילת הפה. למדנו, כל אלו השערות שבדיקנא קשות יותר מכל הנימין של הקווצות דשערות ראש. ושערות ראש הן ארוכות, ואלו שבדיקנא, אינן ארוכות. ושערות ראש, יש מהן שהן חלקות, ויש מהן שהן קשות."],[0,"","תקון זה כבר בארתי (באות רנ״א ע״ש) ונתבאר שם שמחמת כח הפרסה שבראש, נבקע פרצוף השערות לכו״ח ולבינה ותו״מ, שכו״ח דשערות נשארו בבחינת ראש, והן \u0003שערות רישא.\u0004 ובינה ותו״מ דשערות יצאו מבחינת הראש, ונתדבקו בתחילת הגוף שהוא הלחי התחתונה והגרון, ונקראים \u0003שערות דיקנא.\u0004 וז\"ש \u0003כל אלין נימין דבדיקנא תקיפין יתיר\u0004 וכו', כי קשיות השערות מורה על הדינים שבהם, ומתוך ששערות דיקנא יצאו מראש, מחמת המסך המסיים שבפאתי הראש, ע״כ כח הדינים שבמסך ההוא רוכב עליהם והן קשות יותר משערות ראש, וכן, \u0003ושערי דרישא אריכין והני לאו אריכין,\u0004 כי אריכות מורה על הארת חכמה, כי חכמה מכונה אורך. וכיון ששערות דיקנא יצאו מראש לבחי׳ גוף, ע״כ אינן ארוכות. \u0003ושערי דרישא מנהון שעיעין מנהון קשישין,\u0004 מטעם שיש בהם ימין ושמאל, והנמשכות משמאל יש בהן דינים דשמאל וע״כ הן קשות, משא״כ שערות דיקנא כולן קשות, מכה המסך דפאתי הראש הנמשך מפרסא שבראש, שהוא הוציאן לבחינת גוף."],[1,"ובשעתא דאתמשכן שערי","וכו׳: ובשעה שנמשכות שערות לבנות של עתיק יומין לשערות זעיר אנפין, כתוב, הכמות בחוץ תרונה. מהו בחוץ, היינו בז״א הזה, המלביש לנה\"י דא״א, הנחשב לבחינת חוץ. כי כל נה״י לבר מגופא הוא, שמתחברים בו ב׳ מוחין, מוח דא״א, במוח ח״א שמבחוץ לא״א, שעליהם אומר \u0003חכמות\u0004 בחוץ תרונה."],[2,"תרי מוחי ס״ד","וכו׳: שואל, שני מוחין, איך עולה על דעתך. הרי בז״א בלבד יש ג׳ מוחין. ומשיב, אלא אמור, ארבעה מוחין. ג׳ מוחין שהם בז״א הנמצאים בג׳ חללי הגולגלתא בראש. ומוח אחד של א״א השוקט על מכונו, הכולל בתוכו כל ג׳ מוחין, ונמשכות ממנו ממוח א״א, המשכות שלמות שקולות בתוך שערות לבנות, דא״א, לזעיר אנפין הזה, לשלשה מוחין שבו. \u0003כלילן,\u0004 פירושו שלמות. מלשון כליל יופי."],[3,"ומשתכחן ארבע מוחי","וכו׳: ונמצאים ארבעה מוחין בזעיר אנפין הזה. שהם חכמה ובינה וימין דדעת ושמאל דדעת, כי מחמת הארת מוח דא״א בג׳ מוחין שלו מתחלקים ג׳ מוחין שלו לד׳ מוחין. משום זה נשלמו ארבע פרשיות הכתובים בתפילין. כי פרשיות התפילין ה״ס או״מ דג׳ מוחין חב״ד דז״א, ומחמת ההכללות המוח דא״א בהם, נחלק מוח הדעת דז״א לב׳ מוחין, לימין ולשמאל, ונשלמו לארבע פרשיות. דהיינו ד׳ מוחין. כי נכלל בהם השם הקדוש של עתיק יומין עתיקא דעתיקין שהוא מוח א׳. שהוא א״א, ושל ז״א, שבו ג׳ מוחין. וזו היא שלמות השם הקדוש, שכתוב, וראו כל עמי הארץ כי \u0003שם ה׳\u0004 נקרא עליך ויראו ממך. \u0003שם ה',\u0004 הוא שם ה׳ ממש, שהם ארבעה חללים שבבתים דתפילין. כי המוחין ה״ס הויה, והבתים של המוחין, ה״ס המלכות הנקראת, שם ה'."],[4,"ובג\"כ חכמות בחוץ","וכו': ומשום זה אוה״כ, חכמות בחוץ תרונה, שהן החכמות דז״א ודא״א, שכאן בז״א, שהוא בחוץ מא״א, הן נמצאות. כי עתיק דעתיקין סתום הסתומים, החכמה שלו אינה נמצאת ואינה מוכנה להמצא, משום שהיא חכמה סתומה מכל ואינה מפורשת, ומשום שנתחברו ארבעה מוחין בז״א נמשכים ממנו ארבעה מבועים לכל צד, שהם ד׳ מוחין חכמה בינה וימין דדעת, ושמאל דדעת ואלו ד׳ מתחלקים ממבוע אחד היוצא מכולם, דהיינו מוח \u0003החכמה,\u0004 היוצא ומתחלק לד׳ מוחין (כנ״ל אות ק״צ) שה״ס ל״ב נתיבות החכמה המתגלות לתחתונים. ומשום זה הם ארבע מוחין בחכמה דז״א, מטעם שחכמה דא״א נכלל בהם, כדי שיהיו מושפעים ממנו לתחתונים. כי במוחא סתימאה ממקומו אינה נגלית כלל, וע״כ אוה״כ חכמות בחוץ תרונה, כי רק בחוץ במקום ז״א הן תרונה, דהיינו שמתגלות."],[5,"ותאנא האי חכמתא","וכו׳: ולמדנו, חכמה זו הכלולה בארבע, דהיינו מוח החכמה דז״א, נמשכת באלו השערות דז״א שהן תלויות תלים על תלים, וכולם קשות וחזקות, ונמשכות ובאות כל אחת לצד שלו, ואלף אלפים ורבוא רבבות תלויות, ומהם שאין להם חשבון. דיש קווצותיו תלתלים, תלי תלים, וכולן קשות וחזקות להתחבר כמו חלמיש חזק, וכאבן הזאת שהיא חזקה, עד שעושים נקבים ומבועים מתחת השערות, ונמשכים מבועים חזקים לכל עבר ועבר ולכל צד וצד. ומשום שאלו השערות הן שחורות וחשכות, כתוב בהן, מגלה עמוקות מני חשך ויוצא לאור צלמות."],[5,"","פירוש. נודע שאין החכמה נמשכת אלא עם גילוי דינים (כנ״ל פקודי אות שע״ו) ולפיכך אין חכמה דז״א נמשכת אלא ע״י השערות ראש דז״א שה״ס דינים קשים, וז\"ש, \u0003דאי חכמתא\u0004 וכו' \u0003אתמשכא בהני שערי,\u0004 דהיינו עם הדינים שלהם, \u0003וכלהו קשיין ותקיפין,\u0004 אבל אותן השערות שבראש שאינן קשים ותקיפין, אין החכמה נמשכת עמהם, והן עשויות רק להמשכת החסדים. כי יש ג׳ בחינות השפעות ע״י השערות, א) היא השפעת החכמה. ב) היא השפעת החסדים להלביש החכמה, כי אין החכמה מאירה בלי חסדים. ושתים אלו מושפעות ע״י השערות הקשות. ג) היא השפעת חסדים בלי חכמה, ומושפעים ע״י שערות הרכות. וז״ש. \u0003ואלף אלפים.\u0004 שה״ס חכמה המכונה אלפים בסו\"ה ואאלפך חכמה. \u0003ורבוא רבבן,\u0004 ה״ס החסדים המלבישים את החכמה המכונים רבבות. ושתי השפעות אלו ה״ס חשבון, כי שפע החכמה מכונה חשבון. (כנ״ל פקודי אות כ״ח) \u0003מנייהו דליתהון בחושבנא,\u0004 היינו השפעה הג', שהיא חסדים בלי חכמה, המכונה שאין להם חשבון."],[5,"","ונודע שמטרם ביאת קו האמצעי הממעט הג״ר דשמאל ע״י מסך דחירק שבו, אין החכמה יכולה להאיר מטעם חוסר חסדים להלביש החכמה (כנ״ל לך דף י״ג ד״ה ונתבאר) וז״ש, \u0003וכלהו קשיין ותקיפין לאתחברא,\u0004 דהיינו השערות הנמשכות מקו שמאל הן קשות ותקיפות מלהתחבר בימין, ולהתלבש בחסדים. כי מטרם שנתמעטו הג״ר דשמאל, נמצא השמאל במחלוקת עם הימין ואינו רוצה להתחבר עמו (כנ״ל ב״א דף נ״ז ד״ה והנה ובד\"ה וזה) \u0003עד דעבדין נוקבין ומבועין מתחות שערא,\u0004 דהיינו עד שבא קו האמצעי, וממעט הג״ר דקו שמאל שבמוחין, ואז נעשו נקבים תחת שערות הראש הנמשכות מקו שמאל, כי מיעוט הג״ר שקבלו, מכונה נקבים תחת השערות, שע״י המיעוט הזה נתחבר קו שמאל עם הימין והחכמה נתלבשה בחסדים והחכמה מאירה בכל השלמות בבחינת ו״ק דחכמה. וע״כ נבחן שהנקבים, דהיינו המיעוטים נעשו למבועים של השפעה. וז\"ש, \u0003עד דעבדין נוקבין ומבועין מתחות שערא,\u0004 וז״ש, \u0003לכל עיבר ועיבר,\u0004 דהיינו הן לפנים והן לאחור, \u0003לכל סטר וסטר,\u0004 דהיינו הן לימין והן לשמאל. ונמצא שהדינים שבשערות, שקבלו מן מסך דחירק שבקו אמצעי דמוחין, גרמו לכל השלמות, דהיינו לחבור ימין ושמאל, כנ״ל. וז״ש, \u0003ובגין דהני שערי אוכמי וחשוכן,\u0004 דהיינו מחמת ב׳ הפעולות שבמסך דחירק, (כנ״ל לך י״ג ד״ה ונתבאר) מפעולה דמנעולא נעשו שחורות, ומפעולה דמפתחא, נעשו חשכות. משום זה כתוב, \u0003מגלה עמוקות מני חשך,\u0004 דהיינו שהחכמה נגלית מחמת הדינים שבשערות, שמבחינת החשך, דהיינו ממפתחא, \u0003ויוצא לאור צלמות,\u0004 שהחכמה נגלתה ויצאה לאור מחמת השחרות שבשערות, שהיא נמשכת ממנעולא, הנקראת צלמות. כי ע״י שתי פעולות אלו נכנע קו השמאל להתחבר עם קו הימין, שע״י החשך והצלמות, נגלתה העמוקה דהיינו החכמה, ויצאה לאור."],[6,"ותאנא הני שערי","וכו׳: ולמדנו אלו השערות שבדיקנא הן יותר קשות מהשערות שבראש, משום שאלו, שערות דיקנא, בלבד מפורשות ונמצאות. וע״כ הן קשות בדרכן."],[6,"","פירוש. אע״פ שמקור גילוי החכמה הוא בשערות ראש, כנ״ל, עכ״ז התחתונים אינם יכולים לקבל מראש, שה״ס ג״ר, אלא משערות דיקנא שיצאו מראש, והן בחינת ו״ק. והוא מטעם שאם היו מקבלים משערות ראש, היו ממשיכים ממעלה למטה, כמדת הג״ר, וע״כ השערות ראש רק משפיעות לשערות דיקנא, שהן ו״ק והתחתונים מקבלים משערות דיקנא. שמשם מקובלת רק הארת ממטה למעלה. וז״ש \u0003הני שערי דדיקנא תקיפין\u0004 וכו', \u0003משום דהני בלחודייהו מתפרשן ומשתכחן\u0004 וכו'. כי מבחינת שערות ראש אין החכמה נמצאת לתחתונים אלא מבחינת שערות דיקנא, וכיון שהן משפיעות לתחתונים ע״כ עיקר תוקף הדין צריך להמצא בהן. וז״ש, \u0003ואינון תקיפין באורחייהו,\u0004 דהיינו בדרך ההשפעה שלהם הן מחויבות להיות תקיפין, כמ״ש לפנינו."],[7,"אמאי תקיפין","וכו׳: שואל, למה הן קשות, אם תאמר, מפני שכולן הן דין, הלא אינו כן, כי בתקונים אלו נמצאים רחמים גם כן, ובשעה שיורדים י״ג מבועי נהרות שמן, דהיינו י״ג תקוני דיקנא דא״א היורדים לדיקנא דז״א, הם כולם רחמים, וא״כ למה הן קשות."],[8,"אלא תאנא כל","וכו׳: ומשיב, אלא למדנו, כל אלו שערות דיקנא כולן קשות. מהו הטעם. הוא, כי כל אלו של רחמים, דהיינו הנמשכות מקו האמצעי שהוא רחמים, צריכות להיות קשות, דהיינו מדינים דמסך דחירק (כנ\"ל אות רע״ג) כדי להכניע הקו שמאל שהוא דין ולחברו בימין (כמ״ש שם) וכל אלו שהם דין, דהיינו הנמשכות מקו שמאל, שהם דינים קשים, הרי קשות הן מצד עצמן. ובין כך ובין כך צריכות להיות קשות מב' הצדדים, הן מצד הרחמים והן מצד הדין. וכשהעולם צריך לרחמים, הנה שערות הרחמים מקו האמצעי הן קשות ונוצחות את הדין, כי מיחדות השמאל עם קו הימין שהוא חסדים. ומתגלים המוחין שהם רחמים. וכשהעולם צריך דין, דהיינו בעת הארת החכמה, שאינה מאירה אלא עם גילוי דינים, (כנ״ל פקודי אות שע״ו) אז הדין קשה, ונוצח על הרחמים. ומשום זה צריכות להיות קשות משני הצדדים, כשצריכים רחמים, השערות שהן ברחמים עומדות, והדיקנא נראה בשערות אלו, והאחרות אינן נראות, והכל הוא ברחמים. וכשצריכים דין, נראה הדיקנא רק באלו השערות של דין, והאחרות אינן נראות. והכל, בין רחמים ובין דין, מתקיים על ידי הדיקנא."],[9,"וכד אתגלייא דיקנא","וכו׳: וכשמתגלה דיקנא הקדוש הלבן, דא״א, כל אלו וכל אלו מאירות ומתרחצות בחסדים דדיקנא דא״א, כמי שמתרחץ מנהר עמוק מן העכירות שהיה בו, דהיינו מן הדינים, ומתקיימות כולן ברחמים, והדין אינו נמצא, וכל אלו תשעה תקוני דיקנא כשמאירים יחד, כולן מתרחצות ברחמים."],[9,"","פירוש. כי כשהשערות מאירות בזו אחר זו, נמצאים דינים בב׳ צדדים, כי אז השערות דדינים דשמאל קשות מצד עצמן, והשערות דרחמים הבאות אח״כ, קשות, כדי להכניע השמאל וליחדו עם הימין כנ״ל. אבל כשמאירים יחד הנה השערות דשמאל כבר נטהרו מדינים ע״י התיחדותן עם הימין, ושערות דרחמים אחר שעשו פעולתן הן כולן רחמים והדין אינו ניכר בהן."],[10,"ובג\"כ אמר משה","וכו׳: ומשום זה אמר משה, את המדות, פעם שנית, ה׳ ארך אפים ורב חסד, דהיינו בפרשת שלח, ואלו \u0003אמת,\u0004 אינו אומר שם, כמו שאומר בי״ג מדות שבפרשת כי תשא, והוא משום שסוד הדבר הוא, אלו תשע מדות, דהיינו ט׳ תקוני דיקנא דז״א, הם מאירים מעתיק יומין לז״א. וכשאמר משה, המדות פעם שנית בפרשת שלח, אמר תשעה תקונים, שהם תקוני דיקנא הנמצאים בזעיר אנפין, שיורדים מעתיק יומין, ומאירים בו. ומשום זה לא אמר בהן, ואמת, כי אמת תלויה בעתיקא קדישא. שה״ס תקון הז' של י\"ג תקוני דיקנא דא״א, שה״ס הארת פנים דא״א, ועתה כשלא קבל מעתיק רק ט׳ תקונים, לא אמר משה ו \u0003אמת.\u0004 כי תקון הזה דעתיק, אינו מאיר בו עתה."],[10,"","פירוש. לעולם אין בז״א כי אם ט׳ תקוני דיקנא, אלא שפעם מאירים בהן י״ג מדות דא״א, ופעם רק ט׳ מדות מא\"א. וכשמאירים י\"ג מדות דא״א בט׳ תקוני דיקנא דז״א, אז יש בז״א י״ג מדות הרחמים, דהיינו י״ג הארות מא״א, ואלו הם י״ג מדות הרחמים הנזכרים בז״א בפרשת כי תשא, שכתוב בהם ואמת. ואם לא כל י״ג דא״א מאירים בט' תקוני דיקנא דז״א, רק ט׳ הארות בלבד, אין תקון ואמת בכללם, שה״ס הארת הפנים דא״א, ואינם אלא ט׳ מדות הנאמרים בפרשת שלח."]],[]],[["תָּנָא, שַׂעְרֵי דְּרֵישָׁא דִּזְעֵיר אַפִּין, כֻּלְּהוּ קְשִׁישֵׁי, תִּלִּין עַל תִּלִּין. וְלָא שְׁעִיעִין. דְּהָא חֲמֵינָא דִּתְלַת מוֹחֵי בִּתְלַת חֲלָלֵי מִשְׁתַּכְּחִין בֵּיהּ, וּנְהִרִין מִמּוֹחָא סְתִימָאָה. וּמִשּׁוּם דְּמוֹחָא דְּעַתִּיק יוֹמִין, שָׁקִיט וְשָׁכִיךְ כַּחֲמָר טַב עַל דּוּרְדְּיֵיהּ, שַׂעֲרוֹי כֻּלְּהוּ שְׁעִיעִין, וּמְשִׁיחִין בְּמִשְׁחָא טַב. וּבְגִין כָּךְ כְּתִיב, (דניאל ז׳:ט׳) רֵאשֵׁהּ כַּעֲמַר נְקֵא.","וְהַאי דִּזְעֵיר אַפִּין, קְשִׁישִׁין וְלָא קְשִׁישִׁין. דְּהָא כֻּלְּהוּ תַּלְיָין וְלָא מִתְקַמְטֵי, וּבְגִין כָּךְ חָכְמְתָא נָגִיד וְנָפִיק. אֲבָל לָא חָכְמְתָא דְּחָכְמְתָא, דְּאִיהִי שְׁכִיכָא וּשְׁקִיטָא. דְּהָא תָּנֵינָא דְּלֵית דְּיָדַע מוֹחֵיהּ דְּעַתִּיק יוֹמִין, בַּר אִיהוּ. וְהַאי דִּכְתִּיב, (איוב כ״ח:כ״ג) אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ, (קכ\"ט ע\"ב) בִּזְעֵיר אַפִּין אִתְּמַר. אָמַר רִבִּי שִׁמְעוֹן, בְּרִיךְ בְּרִי לְּקוּדְשָׁא בְּרִיךְ הוּא, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","תִּקּוּנָא תִּנְיָינָא. נָפִיק שַׂעֲרָא, וְסָלִיק מֵרֵישָׁא דְּפוּמָא, עַד רֵישָׁא אַחֲרָא דְּפִתְחָא דְּפוּמָא, וְנָחִית מִתְּחוֹת פּוּמָא, עַד רֵישָׁא אַחֲרָא, נִימִין עַל נִימִין, בְּתִקּוּנָא שַׁפִּיר.","קוּם רִבִּי אַבָּא. קָם רִבִּי אַבָּא, פָּתַח וְאָמַר, כַּד תִּקּוּנָא דְּדִיקְנָא דָּא מִתְתָּקַּן בְּתִקּוּנָא דְּמַלְכָּא, (ס\"א בתיקוני מלכין) (ס\"א כד תקונא דא מתתקן בדיקנא דמלכא אתחזי) כְּגִבָּר תַּקִּיף שַׁפִּיר לְמֵחזֵי, רַב וְשָׁלִיט, הֲדָא הוּא דִכְתִיב, (תהילים קמ״ז:ה׳) גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ. וְכַד אִתְבְּסָם בְּתִקּוּנָא דִּיקְנָא יַקִּירָא קַדִּישָׁא, וְיִשְׁגַּח בֵּיהּ, אִקְרֵי בִּנְהִירוּ דִּילֵיהּ, אֵל רַחוּם וְגוֹ'. וְהַאי תִּקּוּנָא תִּנְיָינָא אִתְתָּקַּן, כַּד נָהִיר בִּנְהִירוּ דְּעַתִּיק יוֹמִין, אִקְרֵי רַב חֶסֶד. וְכַד מִסְתַּכְּלֵי דָּא בְּדָא, אִתְקְרֵי בְּתִקּוּנָא אַחֲרָא וְאֱמֶת. דְּהָא נְהִירוּ אַנְפֵּיה. (ס\"א דא נהירו דאנפין)","וְתָאנָא, נוֹשֵׂא עָוֹן אִתְקְרֵי דָּא תִּקּוּנָא תִּנְיָינָא, כְּגַוְונָא דְּעַתִּיקָא קַדִּישָׁא. אֲבָל מִשּׁוּם הַהוּא אוֹרְחָא דְּנָפִיק, בְּתִקּוּנָא תְּלִיתָאָה תְּחוֹת תְּרֵין נוּקְבִין דְּחוֹטָמָא, וְשַׂעֲרִין תַּקִּיפִין זְעִירִין מַלְיָין לְהַהוּא אוֹרְחָא. לָא אִתְקְרוּן הָכָא נוֹשֵׂא עָוֹן וְעוֹבֵר עַל פֶּשַׁע, וְאִתְקְיָימוּ בְּאֲתָר אַחֲרָא.","וְתַנְיָא, תְּלַת מְאָה וְשִׁבְעִין וְחָמֵשׁ חֲסָדִים, כְּלִילָן בְּחֶסֶד דְּעַתִּיק יוֹמִין, וְכֻלְּהוּ אִקְרוּן חַסְדֵּי קַדְמָאֵי. דִּכְתִּיב, (תהילים פ״ט:נ׳) אַיֵּה חֲסָדֶיךָ הָרִאשׁוֹנִים. וְכֻלְּהוּ כְּלִילָן בְּחֶסֶד דְּעַתִּיקָא קַדִּישָׁא, סְתִימָא דְּכֹלָּא. וְחֶסֶד דִּזְעֵיר אַפִּין אִקְרֵי חֶסֶד עוֹלָם.","וּבְסִפְרָא דִּצְנִיעוּתָא, (שמות קע\"ז ע\"ב) קְרֵי בֵּיהּ לְחֶסֶד קַדְמָאָה דְּעַתִּיק יוֹמִין רַב חֶסֶד. וּבִזְעֵיר אַפִּין, חֶסֶד סְתָם. וּבְגִין כָּךְ כְּתִיב הָכָא, (שמות לד) וְרַב חֶסֶד. וּכְתִיב, (שמות ל״ד:ו׳-ז׳) נוֹצֵר חֶסֶד לַאֲלָפִים סְתָם. וְאוֹקִימְנָא, הַאי רַב חֶסֶד, מַטֵּה כְּלַפֵּי חֶסֶד, לְנַהֲרָא לֵיהּ, וּלְאֲדְלָקָא בּוֹצִינֵי.","דְּתָנָא הַאי אוֹרְחָא דְּנָחִית תְּחוֹת תְּרֵין נוּקְבִין דְּחוֹטָמָא, וְשַׂעְרִין זְעִירִין מַלְיָין לְהַהוּא אָרְחָא, לָא אִקְרֵי הַהוּא אָרְחָא עוֹבֵר עַל פֶּשַׁע, דְּלֵית אֲתָר לְאַעְבְּרָא לֵיהּ בִּתְרֵי גְּוָונֵי. חַד מִשּׁוּם שַׂעְרֵי דְּאִשְׁתְּכַח בְּהַהוּא אָרְחָא, הוּא אֲתָר קַשְׁיָא לְאַעְבְּרָא. וְחַד, מִשּׁוּם דְּנָחִית אַעְבְּרָא דְּהַהוּא אוֹרְחָא עַד רֵישָׁא דְּפוּמָא, וְלָא יַתִּיר.","וְעַל דָּא כְּתִיב, (שיר השירים ה׳:י״ג) שִׂפְתוֹתָיו שׁוֹשַׁנִּים, סוּמָקִין כְּוַרְדָא, נוֹטְפוֹת מוֹר עוֹבֵר, סוּמָקָא תַּקִּיף, וְהַאי אוֹרְחָא דְּהָכָא, בִּתְרֵי גְּוָונֵי לֹא (ס\"א בתרי גווני אגזים ולא) אִתְבְּסָם. מִכָּאן מַאן דְּבָעֵי לְאַגְזְמָא, תְּרֵי זִמְנֵי בָּטַשׁ בִּידֵיהּ בְּהַאי אוֹרְחָא.","תִּקּוּנָא רְבִיעָאָה נָפִיק שַׂעֲרָא, וְאִתְתָּקַּן, וְסָלִיק וְחָפֵּי בְּעִלְעוֹי, בְּתִקְרוּבְתָּא דְּבוּסְמָא. הַאי תִּקּוּנָא יָאֶה וְשַׁפִּירָא, לְאִתְחַזְיָא הוֹד וְהָדָר הוּא (ס\"א הוד עלאה). וְתַנְיָא, הוֹד עִלָּאָה, נָפִיק וְאִתְעַטָּר וְנָגִיד לְאִתְאַחֲדָא (ס\"א ליאה דעלעין) בְּעִלְעוֹי, וְאִתְקְרֵי הוֹד זָקָן. וּמֵהַאי הוֹד וְהָדָר, תַּלְיָין אִלֵּין לְבוּשֵׁי, דְּאִתְלָבַּשׁ בְּהוּ, וְאִינּוּן פּוּרְפִּירָא יַקִּירָא דְּמַלְכָּא. דִּכְתִּיב, (תהילים ק״ד:א׳) הוֹד וְהָדָר לָבָשְׁתָּ, תִּקּוּנִין דְּאִתְלָבַּשׁ בְּהוּ, וְאִתְתָּקַּן בְּהַאי דִּיּוּקְנָא דְּאָדָם, יַתִּיר מִכָּל דִּיוּקְנִין."],[[0,"תאנא שערי דרישא","וכו׳: למדנו, שערות ראש דז״א, כולן קשות תלים על תלים ואינן חלקות כמו שערות דא״א, שהרי אני רואה שג' מוחין נמצאים בו בג' חללים, ומאירים ממוחא סתימאה דא\"א. ומשום שהמוח דעתיק יומין, דהיינו מוחא סתימאה, שקט ושכך כיין טוב על שמריו, שהשמרים אינם מקלקלים היין אלא להיפך שמחזקים אותו, כך הדינים שבמו״ס אינם דינים שימעטו במשהו את המוחא סתימאה בבחינתו עצמו, אלא להיפך הם מחזקים אותו. וע״כ שערותיו דא״א כולן חלקות ומשוחות בשמן טוב. ומשום זה כתוב, ראשה כעמר נקא."],[1,"והאי דזעיר אפין","וכו׳: ואלו של ז״א, הן קשות ולא קשות. כי כולן תלויות ואינן נכפפות, ומשום זה החכמה נמשכת ויוצאת בהן, דהיינו הארת החכמה מבינה החוזרת לחכמה, שה״ס ל״ב נתיבות החכמה (כנ״ל אות ק״צ ע״ש) וה״ס בינה דחכמה, שאין חכמה זו נמשכת אלא ע״י דינים וע״כ השערות צריכות להיות קשות (כנ״ל אות רע״ג) אבל לא חכמה דחכמה, דהיינו חכמה דאור ישר בעצמה, שהיא שוככת ושקטה, במוחא סתימאה דא״א, כי למדנו, שאין מי שידע מוחו של עתיק יומין, חוץ ממנו, ומה שכתוב, אלהים הבין דרכה והוא ידע את מקומה, נאמר רק בחכמה דז\"א, הנגלית, ולא בחכמה דא״א הסתום ואינו מתגלה כלל. א\"ר שמעון, ברוך בני לקב״ה בעולם הזה ובעולם הבא."],[2,"תקונא תנינא נפיק,","וכו': התקון השני. השערות יוצאות ועולות מתחלת הפה עד הראש האחר של פתח הפה. דהיינו מן הקצה אל הקצה על שפה עלאה. ויורדות מתחת הפה, דהיינו תחת שפה תתאה, מתחלתו עד ראש האחר, ויורדות נימין על נימין בתקון יפה."],[2,"","פירוש. בתקון הראשון היתה יציאת בחינת המלכות דמדת הדין, כמ״ש שם, ועתה בתקון הזה נעשה התקון של עלית המלכות לבינה, שע״י עליה זו נעשתה המלכות ראויה לקבל המוחין דג״ר מבינה (כמ״ש לעיל ב״א דף ז׳ ד״ה וכבר). וז״ש \u0003נפיק שערא וסליק,\u0004 דהיינו שיוצאות ועולות מלחי התחתון על שפה עליונה של הפה שהיא הלחי העליונה ובחינת בינה. דהיינו ע\"ד שנתבאר בתקון ב' די״ג ת״ד דא״א (באות קט״ז ע״ש) \u0003וסליק מרישא דפומא עד רישא אחרא דפתחא דפומא,\u0004 שכל המקום הזה הוא לחי העליון ובחינת בינה. ונמתקו שערות דמלכות בבחינת בינה, ואח״כ ירדו משם למקומן בלחי התחתונה, שהוא תחת שפה תתאה. וז״ש \u0003ונחית מתחות פומא עד רישא אחרא\u0004 וכו', שהוא מקום המלכות עצמה ומעתה היא ראויה לקבל המוחין ג״כ מבינה. כמ״ש בת״ד דא״א בתקון השביעי. ולולא קבלה מיתוק הזה מבינה לא היתה ראויה למוחין ההם."],[3,"קום ר' אבא","וכו׳: אר״ש לר״א, קום ר׳ אבא. קם ר׳ אבא. פתח ואמר, כשתקון זה מתתקן בתקון המלך, הוא כגבור אמיץ יפה מראה רב ושליט. ז\"ש גדול אדוננו ורב כח. וכשנתבשם בתקון הדיקנא היקר הקדוש דא״א, ומסתכל בו, נקרא התקון הזה בהאור שלו, אל רחום וגו׳. דהיינו בעת שי״ג ת״ד דא״א מאירים בט׳ ת\"ד דז״א נקרא בו תקון הב' בשם \u0003רחום\u0004 (כנ״ל אות קי\"ט) ותקון השני הזה נתתקן אז בתקון אחר של י״ג ת״ד דז״א, ונקרא \u0003ואמת,\u0004 דהיינו תקון הז' דת״ד דז״א האלו. כי פניו מאירים, דהיינו שיש בו אז ג״ר שה״ס חכמת אדם תאיר פניו."],[3,"","פירוש. שר׳ אבא מגלה מעלתו הגדולה של תקון ב׳ זה שה״ס עלית המלכות לבינה, ואומר \u0003כד תקונא דא\u0004 וכו' \u0003כגבר תקיף שפיר למחזי\u0004 כי אע״פ שעתה בתקון הזה לא קבל על ידי עליה זו דמלכות לבינה, אלא בחינת ו\"ק בלבד ממוחין דבינה, משום שגם הבינה נתמעטה לו״ק מחמת הדינין דמלכות, אמנם כיון שעתה נבחנו הדינים בבחינת בינה הוא נבחן מחמת הדינים ההם שהוא \u0003גבור תקיף.\u0004 דהיינו שינצח ע״י גבורות אלו את כל המקטריגים. וימשיך ג\"ר דבינה, ויהיה \u0003רב ושליט.\u0004 וז״ש \u0003שפיר למחזי,\u0004 כי להיותו ראוי משום זה לקבלת ג״ר שנקראים ראיה. ע״כ נקרא עי״ז \u0003יפה מראה.\u0004"],[3,"","ובי״ג דתשא נקרא תקין הזה בשם ורחום (כנ״ל אות קי״ט) וז״ש, \u0003וכד אתבסם\u0004 וכו' \u0003אקרי בנהירו דליה אל רחום,\u0004 כמ״ש שם. עתה מבאר החשיבות הגדולה של התקון הזה בי״ג מדות דתשא שע\"י תקון זה נעשה ראוי לקבל הארת הפנים דתקון הז', שה״ס ג״ר, וז״ש, \u0003והאי תקונא תניינא אתתקן בתקונא אחרא ואמת\u0004 שעל ידו נעשה ראוי לקבל התקון ואמת, \u0003דהא נהירו אנפיה,\u0004 דהיינו שהשיג הג״ר הנקראות הארת הפנים. ולפיכך נקרא כאן התקון הזה בשם \u0003אפים,\u0004 כי ממנו יבא הארת הפנים. כי סדר ט׳ הקונים אלו הם: א׳, ארך. ב', אפים. ג׳. ורב חסד. ד', נושא עון. ה׳. ופשע. ו׳. ונקה לא ינקה. ז', פוקד עון אבות על בנים. ח׳, על שלשים. ט', ועל רבעים."],[4,"ותאנא נושא עון","וכו׳: ולמדנו, נושא עון היה צריך להקרא התקון הזה כמו תקון הב׳ בעתיקא קדישא, שהפירוש הוא שהבינה נושאת עון של המלכות, כי נתמעטה על ידה מג\"ר, כדי לעבור על פשע, בתקון הג', דהיינו כדי להמתיק דיני המלכות הנקראים פשע (כנ״ל אות קכ״ז) אבל משום האורח הזה היוצא כאן בתקון הג', תחת ב׳ נקבי החוטם, ששערות קשות קטנות ממלאות את האורח הזה ואינו פנוי משערות, כתקון הג׳ דא״א, ע״כ לא נקרא כאן נושא עון ועובר על פשע, והוא מתקיים במקום אחר דהיינו בתקון הד׳ (להלן אות רפ״ח)."],[4,"","פירוש. כי בתקון ב', שהמלכות עלתה לבינה, קבלה הבינה דיני המלכות ונתמעטה מחמתה מג\"ר. כנ״ל. וכדי לתקן זה, נעשה זווג עליון דע״ב ס\"ג דא״ק, שהארת זווגם מוריד ומוציא דיני המלכות מן הבינה, והבינה חוזרת לחכמה, (כנ״ל ויקהל דף מ״א ד״ה והארה) אשר תקון הג' שנעשה אורח פנוי משערות באמצע שערות השפה, כי שערות השפה הן מעלית דיני המלכות בתוך הבינה (כנ״ל אות רפ״א) אשר עתה בתקון ג', שהמלכות חזרה וירדה מבינה, נקרחו השערות שם, וחזרה שם בבינה בחינת ג״ר כמקודם עלית השערות דמלכות (כמ״ש באורך לעיל אות קכ״ז ע״ש), אמנם יש שינוי כאן בתקון ג׳ דז״א, אשר ארח הפנוי משערות שנעשה, אינו פנוי לגמרי כמו בתקון ג׳ דא״א, אלא יש כאן שערות קצרות וקשות בתוך הארח, שזה מורה שעוד לא ירדו הדינים לגמרי כמו בארח שתחת החוטם דא\"א. וז״ש, \u0003אורחא דנפיק בתקונא תליתאה תחות תרין נוקבין דחוטמא,\u0004 דהיינו האורח הפנוי משערות שבאמצע שערות השפה העליונה מתחת ב׳ נקבי החוטם, \u0003ושערין תקיפין זעירין מליין לההוא אורחא,\u0004 כי לא נתפנו השערות לגמרי, שזה מורה שעוד יש שם היכר הדינים של התערבות המלכות בבינה. וז״ש, \u0003לא אתקרון הכא נושא עון ועובר על פשע,\u0004 כי שם בא״א, נקרא התקון הב׳ נושא עון, ותקון הג׳ ועובר על פשע. שפירושו, שעי״ז שהבינה קבלה בתוכה את העון דהיינו הדינים של המלכות בתקון הב׳, ע״כ כשבא תקון הג׳ והבינה נטהרה מן הדינים נעבר בזה גם הפשע של מלכות עצמה, מחמת התערבותה למדרגה אחת עם הבינה. אבל כאן, שנשארו עוד שערות קצרות באותו אורח, הרי עוד ניכר הפשע, ולא נסלח. וע״כ לא נקרא תקון זה ועובר על פשע, ומשום זה לא נקרא גם תקון הב׳, נושא עון. כי נושא עון פירושו שהבינה נושאת העון של המלכות כדי לעבור אח״כ בתקון הג', על הפשע של המלכות ולטהרה, וכיון שאינו מתקיים בתקון הג', ועובר על פשע, אין תקון הב׳ נקרא נושא עון. \u0003ואתקיימו באתר אחרא,\u0004 דהיינו בתקון ד'."],[5,"ותניא תלת מאה","וכו׳: ולמדנו, שע״ה חסדים כלולים בחסד דעתיק יומין. שה״ס ואל קין ואל מנחתו לא שע״ה, שלא זכה לחסדים אלו דעתיק יומין, וכולן נקראים חסדים הראשונים. שכתוב, איה חסדיך הראשונים, וכולם כלולים בחסד דעתיקא קדישא הסתום מכל. וחסד דז״א, נקרא \u0003חסד עולם.\u0004"],[6,"ובספרא דצניעותא","וכו׳: ובספרא דצניעותא (אות ל״ז) קורא את החסדים הראשונים דעתיק יומין \u0003רב חסד,\u0004 ובזעיר אנפין נקראים החסדים \u0003חסד\u0004 סתם. ומשום זה כתוב כאן בתקון הג׳ דז״א \u0003ורב חסד,\u0004 כי תקון א׳ הוא, ארך. ותקון ב׳ הוא, אפים. ותקון הג׳ הוא ורב חסד, כנ״ל. כי הוא מקבל כאן מחמדים הראשונים דא״א, ונקרא גם הוא ורב חסד. וכתוב, נוצר חסד לאלפים סתם, ולא כתוב ורב חסד, כי מדבר שם מחסד דז״א עצמו. שנקרא חסד סתם, והעמדנו, רב חסד זה, דא״א, מטה כלפי חסד דז״א, להאיר לו ולהדליק הנרות, דהיינו הספירות דז״א."],[7,"דתנא האי אורחא","וכו׳: כי למדנו, האורח הזה היורד תחת ב׳ נקבי החוטם דז״א, ושערות צרות ממלאים האורח ההוא, לא נקרא אורח ההוא \u0003ועובר על פשע,\u0004 כי אין מקום להעביר הפשע משום ב׳ טעמים, א', משום השערות הנמצאות באורח ההוא, הוא מקום קשה מלהעביר שם חכמה. וב', משום שהמעבר של האורח ההוא, יורד רק עד תחילת הפה ולא יותר."],[8,"וע״ד כתיב שפתותיו","וגו׳: וע״כ כתוב, \u0003שפתותיו שושנים,\u0004 דהיינו אדומות כשושנים. \u0003נוטפות מור עובר,\u0004 היינו אדום, קשה, שהיא דין. כי האורח הזה שבכאן שממעל השפות, בב׳ אפנים לא נתבשם כנ\"ל, וע״כ ניכר הדין על השפות, שה״ס גוון אדום. ומכאן, שמי שרוצה להפחיד את חבירו בשיעור יוצא מן הכלל, מכה בידו ב׳ פעמים באורח הזה."],[8,"","פירוש בתקון הג׳ דא״א, יש ב׳ מעלות באורח הזה שתחת נקבי החוטם. א׳, שהמלכות ירדה מבינה לגמרי, עד שהאורח ההוא פנוי לגמרי משערות. ב׳, שהאורח ההוא עובר ובא עד מתחת השפה התחתונה, באמצע השערות של שבולת הזקן, בתקון ד׳ דא״א. שמב' אלו נעשו ב׳ תקונים אל המלכות, א', שהבינה נטהרה מדינים לגמרי, ונגלית החכמה באורח העליון, ובסוד ועובר על פשע נטהרה ג״כ המלכות עם הבינה. ומה שנשאר מן המלכות שלא נמתק בסו״ה לשארית הנמצאה, נמתק בארח התחתון שמתחת שפה תתאה, שהוא מתוק המלכות במקום מציאותה בלחי התחתונה כנ״ל (באות ק״ל) בתקון ד׳ דא״א. וכאן בז״א חסרים ב׳ תקונים אלו. וז״ש, \u0003לא אקרי ההוא ארחא, עובר על פשע, דלית אתר לאעברא ליה בתרי גווני,\u0004 דהיינו משום שחסר בו ב׳ תקונים הנ״ל שבא״א. \u0003חד, משום שערי דאשתכח\u0004 וכו', ונמצא שאפילו הבינה לא נטהרה לגמרי, ומכ״ש המלכות. \u0003וחד, משום דנחית אעברא דההוא אורחא עד רישא דפומא ולא יתיר,\u0004 כי אינו יורד להעשות גם אורח בשבולת הזקן, ששם המלכות במקומה. \u0003וע״ד כתיב, שפתותיו שושנים, סומקין\u0004 וכו', שיש בחינת דין בשפתותיו דז״א, מאותם ב׳ המיעוטים שנעשו באורח ההוא שעל השפות שלו."],[9,"תקונא רביעאה","וכו׳: התקון הרביעי. השערות יוצאות ומתתקנות, ועולות ומכסות על לחייו, במנחת הבושם. התקון הזה נאה ויפה למראה, הוד והדר הוא. ולמדנו, הוד העליון יוצא ומתעטר ונמשך להתאחז בלחייו, ונקרא הוד זקן. ומההוד וההדר הזה תלוים אלו הלבושים שז״א מתלבש בהם, שהם הלבוש היקר של המלך. שכתוב, הוד והדר לבשת. היינו התקונים שנתלבש בהם, ונתתקן בצורת אדם הזה, יותר מבכל הצורות."],[9,"","פירוש. כבר נתבאר שלולא עלית המלכות לבינה לא היו זו״ן ראוים לקבל מוחין, מפני שהמלכות שלהם היא מדת הדין שעליה היה הצמצום והמסך שלא לקבל בתוכה אור העליון. אלא ע״י עלית המלכות לבינה, קבלה המלכות הכלים דבינה, ואז ראוים זו\"ן לקבל אור העליון (כנ״ל ב״א דף ז׳ ד״ה וכבר). והנה עליה זו דמלכות לבינה נבחנת כמו עיבור במעי אמו. ונוהג בכל מדרגה ומדרגה, כי בכל המדרגות יש ע״ס מחמת שכלולות זו מזו. וע״כ צריכים לעיבור הזה אפילו בג״ר. אמנם בג״ר אין צריכים לעיבור הזה מחמת עצמותם אלא מחמת התכללותם בספירות דזו״ן. משא״כ בזו\"ן, שהם צריכים לעיבור זה בבחינת עצמותם, שלולא העיבור אינם ראוים לקבל אור העליון. ולפיכך בדיקנא דז״א צריכים לב׳ עבורים, עבור א׳ לצורך יציאת ו\"ק. ועיבור ב׳ לצורך יציאת ג״ר דו״ק. וזה דוקא בז״א. אבל בדיקנא דא״א היה עיבור א׳ מספיק לו\"ק ולג\"ר דו״ק. כי תקון ב׳ היא עיבור א׳ שתיכף יצא בא״א בתקון הג', אורח פנוי משערות שהיה מספיק גם לתקון ד', שהוא האורח הפנוי משערות שבתוך שבולת הזקן (כמ״ש באות רפ״ז). אבל כאן לא יצא אורחא בשבולת הזקן, מחמת שגם ארח העליון שבשפה עלאה אינו נקי משערות, כנ״ל בדבור הסמוך. ולפיכך תקון הד׳ שבכאן, הוא עבור ב׳ לצורך קבלת ג״ר דו״ק."],[9,"","וז״ש, \u0003תקונא רביעאה נפיק שערא ואתתקן וסליק וחפי בעלעוי\u0004 שהשערות עלו פעם ב׳ לבינה, ללחי העליונה, להתתקן שיהיו ראוים לקבל ג״ר, הנקראים, \u0003תקרובתא דבוסמא,\u0004 וע״י עליה זו קבלו הלבושים מבינה שאור העליון יוכל להתלבש בהם (כנ״ל ב״א דף ז׳ ד״ה וכבר) ולבושים אלו נקראים נה\"י דבינה, וז״ש, \u0003האי תקונא יאה ושפירא לאתחזיא, הוד והדר הוא.\u0004 כי ע״י תקון זה של עלית המלכות לבינה, קבל הדיקנא בחינת נה״י דבינה, כי הוד והדר הם נצח והוד (כנ״ל משפטים אות פ״ד) גם היסוד נקרא הדר. וע״כ הן רומזים על נה״י דבינה שקבל הדיקנא בתקון הזה. וז״ש ותניא \u0003הוד עלאה,\u0004 דהיינו נה״י דבינה, אלא להיות כאן העיבור לג״ר דו״ק שהוא שליטת השמאל, ע״כ נכללים כולם בהוד לבד שהוא שמאל. \u0003נפיק ואתעטר ונגיד לאתאחדא בעלעוי,\u0004 בלחייו, היינו תרין תפוחין המתגלים בתקון החמישי, כי ע״י עבור הזה מתגלים תרין תפוחין דז״א. וע״כ אומר נפיק ואתעטר, \u0003נפיק,\u0004 היינו בתקון רביעי, \u0003ואתעטר,\u0004 היינו בתקון החמישי. ואז \u0003ונגיד ואתאחד בעלעוי.\u0004"],[9,"","וז״ש, \u0003ומהאי הוד וחדר תליין אלין לבושי דאתלבש בהו ואינון פורפירא\u0004 וכו', כי מאלו נה״י דבינה הנקראים הוד והדר, הם הלבושים שהאורות דדיקנא מתלבשים בהם שעל ידיהם יכולים לקבל האור העליון. ועליהם כתוב, \u0003הוד והדר לבשת,\u0004 שהמוחין דז״א, מתלבשים בהוד והדר דבינה האלו. וז״ש, \u0003תקונין דאתלבש בהו,\u0004 שהמוחין דז״א מתלבשים בהם, \u0003ואתתקן בהאי דיוקנא דאדם,\u0004 שהוא ז״א, \u0003יתיר מכל דיוקנין,\u0004 יותר מבכל שאר המדרגות. כי כל מדרגה מקבלת האורות בלבוש, נה״י העליונה ממנה. אבל בהן היא מטעם התכללות זו״ן בהן, כי מבחינת עצמן היו יכולים לקבל אור העליון גם בכלים שלהן עצמן בלי לבושי נה\"י העליון, משא״כ ז״א, הרי מבחינת עצמו אינו ראוי לקבל אור העליון בכלים שלו, והוא צריך ללבושי נה״י דבינה לקבל בהם אור העליון, מבחינת עצמותו. וז״ש \u0003ואתתקן\u0004 וכו' \u0003יתיר מכל דיוקנין.\u0004 כלומר, שהוא צריך להם יותר מכל המדרגות."]],[]],[["וְתָאנָא הַאי הוֹד, כַּד אִתְנְהַר בִּנְהִירוּ דְּדִיקְנָא עִלָּאָה, (נ\"א דא) וְאִתְפָּשַּׁט בִּשְׁאַר תִּקּוּנִין נְהִירִין. הַאי הוּא נוֹשֵׂא עָוֹן מֵהַאי גִּיסָא, וְעוֹבֵר עַל פֶּשַׁע מֵהַאי גִּיסָא. וּבְגִין כָּךְ, (שיר השירים ה) לְחָיָיו כְּתִיב. וּבִצְנִיעוּתָא דְּסִפְרָא אִקְרֵי, הוֹד וְהָדָר וְתִפְאֶרֶת. דְּהָא תִּפְאֶרֶת הוּא עוֹבֵר עַל פֶּשַׁע, שֶׁנֶּאֱמַר (משלי י״ט:י״א) וְתִפְאַרְתּוֹ עֲבוֹר עַל פֶּשַׁע. אֲבָל הַאי תִּפְאֶרֶת לָא אוֹקִימְנָא, אֶלָּא בְּתִקּוּנָא תְּשִׁיעָאָה, כְּמָה דְאַתְּ אָמֵר וְתִפְאֶרֶת בַּחוּרִים כֹּחָם. וְתַמָּן אִקְרֵי תִּפְאֶרֶת. וְכַד אִתְתְּקַל (ס\"א אסתכל), בְּמַתְקְלָא חַד סַלְּקִין. אָמַר רַבִּי שִׁמְעוֹן, יֵאוֹת אַנְתְּ רִבִּי אַבָּא, לְאִתְבָּרְכָא מֵעַתִּיקָא קַדִּישָׁא, דְּכָל בִּרְכָאן נָפְקִין מִנֵּיהּ.","תִּקּוּנָא חֲמִישָׁאָה. פָּסִיק שַׂעֲרָא, וְאִתְחָזוּן תְּרֵין תַּפּוּחִין מִכָּאן וּמִכָּאן, סוּמָקָן כְּהַאי וַרְדָא סוּמָקָא. וּמִתְלַהֲטָן בְּמָאתָן וְשִׁבְעִין עָלְמִין, הָנֵי תְּרֵי תַּפּוּחִין, כַּד נְהַרִין (מתרין סטרין) מִנְּהִירוּ דִּתְרֵין תַּפּוּחִין קַדִּישִׁין עִלָּאִין דְעַתִּיקָא, אִתְמְשַׁךְ סוּמָקָא, וְאָתֵי חִיוָּרָא. בְּהַאי כְּתִיב, (במדבר ו׳:כ״ה) יָאֵר יְיָ פָּנָיו אֵלֶיךָ וִיחֻנֶּךָ. דְּכַד נְהַרִין מִתְבְּרָךְ עָלְמָא. וּבְשַׁעֲתָא דְּאִתְעֲבִדוּ סוּמָקָא, כְּתִיב יִשָּׂא יְיָ פָּנָיו אֵלֶיךָ, כְּלוֹמַר יִסְתָּלַק. וְלָא יִשְׁתְּכַּח רוּגְזָא בְּעָלְמָא. תָּאנָא, כֻּלְּהוֹן נְהוֹרִין דְּאִתְנַהֲרָן מֵעַתִּיקָא קַדִּישָׁא, אִתְקְרוּן חַסְדֵּי קַדְמָאֵי. וּבְגִין אִינּוּן, נַהֲרִין כָּל אִינּוּן חַסְדֵּי עוֹלָם.","תִּקּוּנָא שְׁתִיתָאָה. נָפִיק שַׂעֲרָא, כְּחַד חוּטָא דְּשַׂעֲרֵי בְּסַחֲרָנֵיהּ דְּדִיקְנָא. (ס\"א ותליין עד רישא דמעוי ולא נחית עד טבורא, תנא תקונא דא הוא דאקרי) פְּאַת הַזָּקָן וְאִיהוּ חַד מֵחָמֵשׁ פֵּאִין, דְּתַלְיָין בְּחֶסֶד (וברחמי), וְלָא אִבְעֵי לְחַבְּלָא הַאי חֶסֶד, כְּמָה דְּאִתְּמַר. וּבְגִין כַּךְ, (ויקרא י״ט:כ״ז) לֹא תַּשְׁחִית אֵת פְּאַת זְקָנֶךָ כְּתִיב.","תִּקּוּנָא שְׁבִיעָאָה. דְּלָא תַּלְיָין שַׂעֲרָא עַל פּוּמָא, וּפוּמָא אִתְפְּנֵי מִכָּל סִטְרוֹי, וְיַתְבִין שַׂעְרִין בְּתִקּוּנָא סְחוֹר סְחוֹר לֵיהּ. קוּם רִבִּי יְהוּדָה. קָם רִבִּי יְהוּדָה, פָּתַח וְאָמַר, (דניאל ד׳:י״ד) בִּגְזֵירַת עִירִין פִּתְגָּמָא. כְּמָה אֶלֶף רִבְּבָן מִתְנְשָׁן (ס\"א מתישבן) וּמִתְקַיְּימָן בְּהַאי פּוּמָא, וְתַלְיָין מִנֵּיהּ, וְכֻלְהוֹן אִקְרוּן פֶּה. הֲדָא הוּא דִכְתִיב, (תהילים ל״ג:ו׳) וּבְרוּחַ פִּיו כָּל צְבָאָם. וּמֵהַהוּא רוּחָא דְּנָפִיק מִפּוּמָא, מִתְלַבְּשָׁן.","כָּל אִינּוּן דִּלְבַר, תַּלְיָין מֵהַאי פּוּמָא. וּמֵהַאי פּוּמָא (ס\"א רוחא) כַּד אִתְפָּשָׁט הַאי רוּחָא, מִתְלַבְּשָׁן בֵּיהּ כַּמָה נְבִיאֵי מְהֵימְנָא, וְכֻלְּהוּ פֶּה יְיָ אִתְקְרוּן. וּבַאֲתָר דְּרוּחָא נָפִיק, לָא אִתְעָרְבָא מִלָּה אַחֲרָא וְכֻלְּהוּ (פיות) מְחַכָּאן לְאִתְלַבְּשָׁא בְּהַהוּא רוּחָא דְּנָפִיק. וְהַאי תִּקּוּנָא שַׁלִּיטָא עַל כֻּלְּהוּ שִׁיתָא. מִשּׁוּם דְּהָכָא מִתְקַיְּימָן כֻּלְּהוּ וּמִתְאַחֲדָן. וּבְגִינֵי כַּךְ שַׂעְרוֹהי שְׁקִילִין סוֹחֲרָנֵיהּ דְּפוּמָא. וְאִתְפְּנֵי מִכָּל סִטְרוֹי, וְהַאי תִּקּוּנָא שַׁלִּיטָא עַל כֻּלְּהוּ מִשּׁוּם דְּהָכָא מִתְקַיְּימָן כֻּלְּהוּ וּמִתְאַחֲדָן. אָמַר רַבִּי שִׁמְעוֹן, בְּרִיךְ אַנְתְּ לְעַתִּיקָא קַדִּישָׁא.","תִּקּוּנָא תְּמִינָאָה דְּנַחְתִּין שַׂעְרֵי בִּתְחוֹת דִּיקְנָא, מְחַפְּיָין קְדָלָא דְּלָא אִתְחֲזֵי. דְּתַנְיָא, אֵין לְמַעְלָה לֹא עֹרֶף וְלֹא עִפוֹי, וּבְזִמְנָא דְּאַגָּח (ס\"א דנצח) קְרָבֵי אִתְחֲזֵי. מִשּׁוּם לְאַחֲזָאָה גְּבוּרְתָּא. דְּהָא תָּנֵינָן, אֶלֶף עָלְמִין אִתְאַחֲדָין מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:ד׳) אֶלֶף הַמָּגֵן תָּלוּי עָלָיו כֹּל שִׁלְטֵי הַגִּבּוֹרִים. וְאֶלֶף הַמָּגֵן רָזָא הוּא. בִּצְנִיעוּתָא דְּסִפְרָא, כֹּל שִׁלְטֵי הַגִּבּוֹרִים דְּאָתוּ מִסְּטַר גְּבוּרָה חַד, מֵאִינּוּן גְּבוּרָאן.","תִּקּוּנָא תְּשִׁיעָאָה. דְּאִתְמַשְּׁכָן (ס\"א דמתחברן) שַׂעְרֵי בְּשִׁקּוּלָא מַלְיָא, עִם אִינּוּן שַׂעְרֵי דְּתַּלְיָין, כֻּלְּהוּ בְּשִׁקּוּלָא שַׁפִּיר, כְּחַד גִּיבָּר תַּקִּיף, מָארֵי נַצְחָן קְרָבַיָּיא. מִשּׁוּם דְּכֻלְּהוּ שַׂעְרֵי אִתְמַשְּׁכָן בָּתַר אִינּוּן דְּתַלְיָין. וּכְלָלָא דְּכֻלְּהוּ בְּאִינּוּן דְּתַלְיָין. וְכֹלָּא אִתְמְשַׁךְ, (חסר כאן) וְעַל דָּא כְּתִיב, (משלי כ׳:כ״ט) תִּפְאֶרֶת בַּחוּרִים כֹּחָם. (ונראה על הים כבחור טוב הדא הוא דכתיב) כְּתִיב (שיר השירים ה׳:ט״ו) בָּחוּר כָּאֲרָזִים, כְּגִיבָּר עָבִיד גְּבוּרָאן, וְדָא הוּא תִּפְאֶרֶת, חֵילָא וּגְבוּרְתָּא וְרַחֲמֵי.","תָּנָא, אָמַר רַבִּי שִׁמְעוֹן כָּל הָנֵי תִּקּוּנִין, וְכָל הָנֵי מִלִּין, בָּעֵינָא לְגַלָּאָה לְמָארֵיהוֹן דְּאִתְּקָלוּ בְּמַתְקְלָא, וְלָא לְאִינּוּן דְּלָא עָאלוּ (נ\"א דעאלו ולא נפקו) אֶלָּא לְאִלֵּין דְּעָאלוּ וְנַפְקוּ, דְּכָל מָאֵן דְּעָיִיל וְלָא נָפִיק, טַב לֵיהּ דְּלָא אִבְרֵי.","כְּלָלָא דְּכָל מִלִּין, עַתִּיקָא דְּעַתִּיקִין, וּזְעֵיר אַפִּין, כֹּלָּא חַד. כֹּלָּא הֲוָה. כֹּלָּא הֲוִי. כֹּלָּא יְהֵא. לָא יִשְׁתַּנֵי. וְלָא מִשְתָּנֵי. וְלָא שְׁנָא. אִתְתָּקַּן בְּתִקוּנִין אִלֵּין. אִשְׁתְּלִים דִּיּוּקְנָא דְּכָלִיל כָּל דִּיוּקְנִין. דִּיּוּקְנָא דְּכָלִיל כָּל שְׁמָהָן. דִּיּוּקְנָא דְּאִתְחֲזֵי בְּגווַֹנֵיה כְּהַאי דִּיּוּקְנָא (נ\"א בגוויה כל דיוקנין) לָאו הַאי דִּיּוּקְנָא הֲוִי, אֶלָּא כְּעֵין הַאי דִּיּוּקְנָא."],[[0,"ותאנא האי הוד","וכו׳: ולמדנו, הוד הדיקנא הזה, כשהאיר באור הדיקנא עליונה דא״א, ונתפשט בשאר התקונים המאירים, דהיינו גם בתקון החמישי, זה הוא נושא עון מצד זה, ועובר על פשע מצד זה. ומשום זה כתוב לחייו, שהוא כולל הן השערות שעל הלחיים שהן תקון ד', והן תרין תפוחין הפנוים משערות שהן תקון ה׳. ובצניעותא דספרא, נקרא התקון הזה הרביעי, הוד והדר ותפארת. כי תפארת הוא עובר על פשע, שנאמר ותפארתו עבור על פשע. אבל התפארת הזו לא העמדנו אלא בתקון התשיעי, כמש\"א תפארת בחורים כחם. ושם בתקון התשיעי נקרא תפארת. וכשנשקל, במשקל אחד עולים שניהם. אר״ש, ראוי אתה ר\"א, להתברך מעתיקא קדישא, שכל הברכות יוצאות ממנו."],[0,"","פירוש. כבר נתבאר, שתקון ד׳ ה״ס עבור ב׳ לג\"ר דו״ק, שהמלכות עלתה ונתערבה בבינה. שעי״ז, אחר שחזרו הג״ר לבינה, חזרו ג״כ למלכות ונתקנו בתקון החמישי ב׳ תפוחין פנוים משערות ששם הארת הג\"ר דו״ק. וז״ש, \u0003האי הוד כד אתנהיר בנהירו דדיקנא עלאה,\u0004 שעי״ז יצאה ה \u0003י׳\u0004 מאויר \u0003ואתפשט בשאר תקונין נהירין,\u0004 דהיינו התקון דב׳ תפוחין קדישין שבתקון ה', שה״ס הארת ג״ר דדיקנא, המאיר גם לשאר תקוני דיקנא. \u0003האי הוא נושא עון מהאי גיסא,\u0004 שמצד תקון הד׳, שהוא עלית השערות לבינה, נקרא תקון זה בשם \u0003נושא עון,\u0004 כי הבינה נושאת בקרבה עון וקלקול שבמלכות. עון, הוא מלשון מעות. \u0003ועובר על פשע מהאי גיסא,\u0004 שמצד התקון החמישי, שהוא ב׳ תפוחין הפנוים משערות, שיצאו והאירו בהם הג״ר דו״ק אפילו במלכות, אז נקרא תקון ה׳ הזה, בשם \u0003ופשע,\u0004 שפירושו, עובר על פשע, שהארת הג״ר מבינה עוברים על פשע של המלכות והג״ר מאירים בה, כמו שלא היה בה שום פשע. ומטעם זה נקראים ב׳ תקונים אלו הרביעי והחמישי בפרשת שלח, בשמות, נושא עון, ופשע. כי ארך, הוא תקון א'. אפים, היא תקון ב׳. ורב חסד, הוא תקון ג'. נושא עון, הוא תקון ד'. ופשע, הוא תקון ה'. וכו' כנ״ל. וז״ש \u0003ובג״כ לחייו כתיב,\u0004 שכולל ב׳ תקונים אלו הרביעי והחמישי, דהיינו השערות שעל הלחיים, ותפוחין הפנוים משערות."],[0,"","ומה שאמרנו לעיל בדבור הסמוך, שהלבושים שזו״ן מקבלים מבינה, נקראים הוד והדר, שהם נצה הוד יסוד, אינו בדיוק, כי הם כוללים גם חצי תפארת שמחזה ולמטה, כי תנה״י דעליון מתלבשים בתחתון. שבלבושים אלו מקבל התחתון האורות דג״ר כנ״ל. ולא עוד אלא שורש התקון הוא בתפארת דעליון, שה״ס בינה דעליון, כי חג\"ת הם כח\"ב אלא מחמת שירדו לבחינת חסדים נקראים חג״ת, הרי שת\"ת היא בינה שבה עיקר התקון של ועובר על פשע, כנ״ל. וז״ש \u0003ובצניעותא דספרא אקרי הוד והדר ותפארת,\u0004 דהיינו תנה״י דעליון, \u0003דהא תפארת הוא עובר על פשע,\u0004 כי עיקר התקון של קבלת הג״ר שה״ס ועובר על פשע הוא בתפארת, להיותו בינה דעליון. ומה שקוראים אותו רק הוד והדר לבד, הוא משום \u0003דהאי ת״ת לא אוקימנא אלא בתקונא תשיעאה,\u0004 כי עיקר הת״ת הוא מחציתו העליון שהוא מתבאר בתקון ט'. וז״ש, \u0003ותמן אקרי ת״ת,\u0004 ולא כאן שהוא רק מחציתו התחתון שמחזה ולמטה, ומה שבספרא דצניעותא חושב אותו לת״ת, אין קושיא כי, \u0003וכד אתתקל במתקלא חד סלקין,\u0004 כלומר, שגם מחזה ולמטה אפשר לכנותו ת״ת. כי עולים במשקל אחד."],[1,"תקונא חמישאה","וכו׳: התקון החמישי. השערות נפסקות, ונראים ב׳ תפוחין, פנוים משערות, מכאן ומכאן, אדומים כמו שושנה אדומה, ומתלהטן בר״ע עלמין. אלו ב׳ תפוחין כשמאירים מאור של ב׳ תפוחין קדישין העליונים דעתיקא שהוא א״א, שהם תקון ז׳ שלו, הולך מהם הגוון אדום ובא גוון לבן, בזה כתוב, יאר ה׳ פניו אליך ויחנך. וכשמאירים מתברך העולם. ובשעה שנעשו אדום, כתוב, ישא ה׳ פניו אליך. כלומר שיסתלק פניו, ולא ימצא רוגז בעולם. למדנו, כל האורות המאירים מעתיקא קדישא, דהיינו מא״א, נקראים חסדים הראשונים ובשביל אלו חסדים הראשונים מאירים כל אלו חסדי עולם, שהם חסדים שבז״א."],[1,"","תקון ה׳ הזה כבר נתבאר היטב בדבור הסמוך, שה״ס יציאת ה \u0003י'\u0004 מאויר, שאז חוזרים להאיר הג״ר דו״ק, שה״ס נקודת השורק, שנתבאר לעיל (ב״א ט״ו ד״ה ההיא) ותקון הזה נקרא בפרשת שלח, ופשע, שפירושו ועובר על פשע, שהג״ר דחכמה מאירים במלכות כמו שלא היה בה שום פשע. וז״ש \u0003תקונא חמישאה, פסיק שערא ואתחזון תרין תפוחין,\u0004 כי מקור השערות הוא מכניסת ה \u0003י'\u0004 באויר, וכיון שהי׳ יצאה מאויר בתקון הזה, ע״כ נפסקו בו השערות. \u0003סומקן כהאי ורדא סומקא,\u0004 כי אז היא שליטת השמאל, שנמשכים ממנו דינים, וע״כ נבחן בו גוון אדום, שהם סוד שליטת הדינין דשמאל."],[1,"","ועיקר הארת הדינים דשמאל, הוא בב׳ שלישי ת״ת שמחזה ולמטה, ובנצח, ובהוד. שהם נכללים שם עם הדינין הנמשכים ממסך דחזה. וז״ש, \u0003ומתלהטין במאתן ושבעין עלמין,\u0004 כי כל אחת מג׳ ספירות הנ״ל ה״ס מאה, והיו צריכים להיות ג׳ מאות, אלא לפי שחסר שליש עליון שמחזה ולמעלה דת״ת, אין בת״ת אלא שבעים, וע״כ הם רק מאתים ושבעים. ששם מתלהטים בעיקר הדינים דשמאל. אבל כשב׳ תפוחין דז״א מקבלים הארת הפנים דא״א, \u0003אתמשך סומקא ואתי חיורא,\u0004 כי נתבטלו הדינים דקו שמאל. \u0003בהאי כתיב יאר ה׳ פניו\u0004 וגו׳. שגם הפנים דז״א מאירים. שמהם מקבלים התחתונים. \u0003ובשעתא דאתעבדו סומקא,\u0004 דהיינו מטרם שקבלו הארת פנים דא״א, \u0003כתיב ישא ה׳ פניו אליך,\u0004 שפירושו, \u0003יסתלק ולא ישתכח רוגזא בעלמא,\u0004 כי פנים, פירושו ג״ר. \u0003ישא\u0004 הוא מלשון, ונשא שה מהעדר. כי כל עוד שנמצא בהם הג״ר של שליטת השמאל, נמשכים מהם דינים לעולם."],[2,"תקונא שתיתאה","וכו׳: התקון הששי. השערות יוצאות כמו חוט אחד של שערות מסביב הדיקנא. דהיינו השטח העליון של הדיקנא הנמשך עד החזה, בדומה לתקון השמיני דא״א (לעיל אות קמ״ח ע״ש) וזהו נקרא אחת מחמש פאות שבזקן (מכות ב.) התלויות בחסד, ולא צריכים להשחית חסד הזה, כמו שלמדנו. ומשום זה, לא תשחית פאת זקנך, כתוב."],[2,"","תקון זה נקרא \u0003ונקה לא ינקה,\u0004 שפירושו, כי אחר שיצאו הג״ר בבחינת ב׳ תפוחין, ונפסקו השערות, היו צריכות להתבטל כל השערות, שהרי כבר יצאה ה \u0003י'\u0004 מן האויר, שהיא מקור השערות. אמנם לא היה כן, אלא לא לבד שהשערות של תקונים הקודמים נשארו, אלא גם יצאו חדשות, דהיינו שערות ארוכות הנמשכות עד החזה. שז״ס \u0003ונקה לא ינקה\u0004 שאע״פ שב׳ תפוחים כבר נעשו נקיים משערות, \u0003לא ינקה את כולן,\u0004 אלא להיפך שנמשכים ומקיפים הפנים כמו בחוט של שערות. וז״ש, \u0003תקונא שתיתאה, נפיק שערא, כחד חוטא דשערי, בסחרניה דדיקנא,\u0004 אע״פ שכבר נפסקו בב׳ תפוחין, \u0003ואיהו חד מחמש פאין דתליין בחסד,\u0004 כי יש בדיקנא ה׳ פאות, שתים מכאן ושתים מכאן ואחת מלמטה, (מכות ב׳ ע״א) והן כנגד ה׳ ספירות חג״ת נ״ה שבקו ימין הנקראים ה׳ חסדים, \u0003ולא אבעי לחבלא האי חסד,\u0004 ולפיכך נשארו כל תקוני השערות בסוד \u0003ונקה לא ינקה,\u0004 להיותם המקורות של החסדים."],[3,"תקונא שביעאה","וכו׳: התקון השביעי. השערות אינן תלויות על הפה, והפה נתפנה מכל צדדיו, והשערות יושבות מתוקנות סביב סביב לו. קום ר׳ יהודה. קם ר׳ יהודה. פתח ואמר, בגזירת עירין פתגמא. כמה אלף רבבות מתישבים ומתקיימים מפה הזה, ותלוים ממנו, וכולם נקראים פה. ז״ש וברוח פיו כל צבאם, ומרוח ההוא היוצא מן הפה הם מתלבשים."],[4,"כל אינון דלבר","וכו׳: כל אלו שמבחוץ תלוים מפה הזה. ומפה הזה, כשמתפשט ממנו רוח הזה, מתלבשים בו כמה נביאים נאמנים, וכולם נקראים פה ה'. ובמקום שהרוח יוצא, דהיינו הפה, לא מתערב שם דבר אחר. וכולם מחכים להתלבש ברוח ההוא היוצא מן הפה. ותקון זה שולט על כל ששת התקונים הקודמים לו, משום שכאן כולם מתקיימים ומתאחזים. ומשום זה, השערות שוות מסביב הפה, והפה נתפנה משערות מכל צדדיו. אמר ר׳ שמעון, ברוך אתה לעתיקא קדישא."],[4,"","פירוש. תקין זה שהפה נתפנה משערות נעשה ג\"כ מכח יציאת ה \u0003י'\u0004 מאויר, כמ״ש לעיל בתקון החמישי בב׳ תפוחין. ע״ש. והוצרך לתקון זה מחדש, משום שב' תפוחין דאתפנו משערות עומדים בלחי העליון ששם מקום בינה, כי הפרסא, שבתוכה המלכות, עומדת בפאתי הראש מתחת הלחי העליונה. ואע״פ שיש שם התכללות המלכות, כי ע\"כ נקרא התקון ועובר על פשע, כי פשע הוא בחינת הדינין שבמלכות, מ״מ כיון שהמלכות היא למטה מלחי העליונה, אין דינין דמלכות פוגמים מלמעלה ממקום מציאותה, והוא שם רק מבחינת התכללות. וכדי שתתמתק גם המלכות מבחינתה עצמה ותהיה ראויה לקבל ג״ר דחכמה, נעשתה יציאת \u0003י׳\u0004 מאויר במקום הפה, ששם יש גם הלחי התחתונה שהוא מלכות, כי שפה תתאה, היא הלחי התחתונה הנמצאת מפרסא דראש ולמטה, ששם המלכות, שע״כ ה\"ס בינה ותו״מ שיצאו מראש לבחינת גוף. וכיון שנעשה התקון במקום המלכות, אז נתקנה לגמרי. וראויה לקבל ג״ר דחכמה."],[4,"","ולפיכך נקרא תקון זה בפרשת שלח, בשם \u0003פוקד עון אבות על בנים.\u0004 כי כל מדרגה תחתונה נקראת בן כלפי העליונה ממנה. והנה השם \u0003עון\u0004, מורה על דינים שבבינה שקבלה ממלכות שנכללה בה, שמורה שהיתה ישרה אלא שנעשתה מעוותת מחמת גורם אחר. והדינים שבמלכות נקראים \u0003פשע,\u0004 כי הדינים הם מעצמותה. אלא מכח עלית המלכות לבינה, ומכח התקון שנעשתה בב׳ תפוחין בסוד ועובר על פשע (כמ\"ש לעיל באות ר״צ) נגנזה הפשע שבמלכות לגמרי, ובחינת העון שבבינה נמשכה גם על המלכות, באפן, שבאותו זמן שה \u0003י'\u0004 יצאה מאויר, והבינה נטהרה מן העון, נטהרה עמה יחד גם המלכות, משום שפקד העון דבינה על מלכות. וז״ס, שתקון הפה, נקרא \u0003פוקד עון אבות על בנים,\u0004 כי העון שהיה בלחי העליונה שבו בחינת אבות, נפקד על בנים, שהוא הלחי התחתונה, שבינה ותו״מ שלו נקראים בנים ללחי העליונה, כי מתוך זה, בשעה שנטהרה הבינה מן העון שבה בסוד יציאת ה \u0003י'\u0004 מאויר, נטהרה ג״כ המלכות, כי להיותה נפקדת בעון האבות וקבלה הקטנות מבינה, קבלה ג״כ הגדלות מבינה. ע״י טהרת העון."],[4,"","וז״ש, \u0003תקונא שביעאה, דלא תליין שערא על פומא ופומא אתפני מכל סטרוי,\u0004 שהוא מטעם, כי הפסק השערות הנעשה בבינה, בלחי העליונה, מחמת יציאת ה \u0003י'\u0004 מאויר, עברה ג״כ אל המלכות הנמצאת בלחי התחתונה, \u0003ופומא אתפני מכל סטרוי,\u0004 כמו בב׳ תפוחין. \u0003ויתבין שערא בתקונא סחור סחור ליה,\u0004 כי השערות שיצאו מקודם לכן אינן בטלות, להיותן ממשיכות חסדים כנ״ל. וז״ש \u0003כמה אלף רבבן מתישבן ומתקיימן בהאי פומא ותליין מניה.\u0004 המספר \u0003אלף,\u0004 מורה על חכמה, בסו״ה, ואאלפך חכמה. \u0003ורבבה,\u0004 מורה על חסדים. וכיון שנמשכים חכמה וחסדים, אומר, אלף רבבן, שיוצאים ותלוים ומתקיימים מפה זה. כי מפומא דאתפני משערות יוצאת חכמה, ומשערות שמסביב הפה יוצאים חסדים. וז״ש, \u0003וכלהון אקרון פה.\u0004 שהן החכמה והן החסדים נקראים פה. ונתבאר לעיל שע״כ צריכים לתקון הפה נוסף על תקון ב׳ תפוחין, משום שהתקון הנעשה במקום הלחי העליונה, אינו מועיל לבינה ותו״מ שיצאו מן הראש, להיותם נמצאים למטה ממלכות שבפרסא דראש. וע״כ נעשה להם תקון מיוחד בלחי התחתונה שנקרא פה. וז\"ש, \u0003כל אינון דלבר תליין מהאי פומא,\u0004 דהיינו כל אלו שהם בבחינת בינה ותו״מ שיצאו \u0003לבר\u0004 מראש מקבלים מתקון הפה. וז״ש \u0003ומהאי פומא\u0004 וכו' \u0003וכלהו פה הויה אתקרון,\u0004 שאין שם שום דין כי נתפנה משערות. \u0003ובאתר דרוחא נפיק לא אתערבא מלה אחרא,\u0004 דהיינו שום דין, כי אם היו נראות שם איזו שערות שהן דין לא היה יכול רוח הויה לצאת משם. וז״ש \u0003והאי תקונא שליטא על כלהו שיתא, משום דהכא מתקיימן כלהו ומתאחדן,\u0004 כי כל התקונים שקדמו לתקון ז׳ הזה, לא היו אלא כדי להביא תקון הזה על שלמותו. דהיינו לתקן את המלכות במקומה שתוכל לקבל ג״ר כנ״ל. וע״כ נאחזים כולם בשלמות תקון הז׳ הזה ומתקיימים על ידו. כי לא באו אלא להשלמת תקון הזה."],[5,"תקונא תמינאה","וכו׳: התקון השמיני. השערות יורדות תחת הדיקנא ומכסות העורף שלא יהיה נראה, שלמדנו, אין למעלה לא עורף ולא עייפות. ובזמן שעושה מלחמה נראה העורף, כדי להראות גבורה, כי למדנו, אלף עולמות נאחזים ממנו. ז״ש אלף המגן תלוי עליו כל שלטי הגבורים. ואלף המגן הוא סוד. ויש בצניעותא דספרא, כל שלטי הגבורים. היינו הבאים מצד גבורה אחת מאלו הגבורות."],[5,"","פירוש. אחר שכבר נעשו כל התקונים בבחינת הלחי העליונה והלחי התחתונה, ירדו התקונים לבחינת גוף ממש, דהיינו הגרון והעורף, ותקון הזה יש לו ב׳ משמעות, א) לכסות את העורף, כי המוחין דחכמה הבאים מקו שמאל, נבחנים שהם באחורים ולא פנים, דהיינו בעורף, וכיון שדינים נמשכים ממוחין דחכמה אלו, ע״כ צריכים לכסות העורף, שז״ס התקון השמיני שיצאו שערות למטה מראש וכיסו את העורף, כי הדין שבשערות מכסות על החכמה אשר בעורף ואינה מאירה. ב) שהם מגלים את העורף בשעת מלחמה, שאין החצונים נכנעים אלא ע״י גילוי חכמה, ואז מתפנים השערות מן העורף והחכמה נגלית לכלות את הקליפות והס״א."],[5,"","וז״ש \u0003תקונא תמינאה, דנחתין שערי בתחות דיקנא מחפיין קדלא דלא אתחזי,\u0004 דהיינו הדינים שבשערות מעכבים על החכמה שבעורף שלא תאיר. \u0003ובזמנא דאגח קרבי אתחזי,\u0004 דהיינו הפעולה הב׳ הנ״ל שבשערות שמגלות העורף בעת מלחמה כדי לכלות ולהשבית הקליפות. וז״ש \u0003משום לאחזאה גבורתא,\u0004 דהיינו להראות החכמה שבקו שמאל, שנקראת גבורה. שאין הקליפות נכנעות רק ע״י גילויה. \u0003דהא תנינן אלף עלמין אתאחדין מניה.\u0004 דהיינו חכמה, המרומזת באלף, בסוד ואאלפך חכמה. \u0003הה״ד אלף המגן תלוי עליו כל שלטי הגבורים. ואלף המגן רזא הוא,\u0004 שמורה על השערות האלה שבעורף המגינות על החכמה, שנקראת אלף. \u0003כל שלטי הגבורים,\u0004 מה מוסיף הכתוב בזה, הוא, \u0003דאתו מסטר גבורה חד מאינון גבוראן,\u0004 דהיינו הבאים מגבורה אחרונה שבגבורות שה״ס המלכות, וע״כ אוה״כ, כל שלטי הגבורים."],[5,"","ותקון זה נקרא בפרשת שלח, \u0003על שלשים,\u0004 כי נתבאר לעיל שכל מדרגה תחתונה נחשבת בבחינת בן למדרגה עליונה. והנה מקור התקון של נושא עון ועובר על פשע, הוא בלחי העליונה, ומשם נפקד העון על בחינת הלחי התחתונה שהיא בבחינת \u0003בן\u0004 ללחי העליונה, בסוד תקון הז' ע״ש. ועתה עבר אותו התקון על בחינות הגרון והעורף שהוא גוף, והוא בן ללחי התחתונה, \u0003ושלשים\u0004 ללחי העליונה. ולפיכך נקרא תקון הז', פוקד עון אבות על בנים, ותקון הח׳, הוא פוקד עון אבות על בני שלשים. ונעשו ראוים עי״ז לגלות החכמה שבעורף, בעת מלחמה, כנ\"ל, כי בעת שיצא העוז \u0003מהאבות,\u0004 שהם, ב׳ תפוחין שבלחי העליונה, יצא העון ג״כ \u0003מהבנים\u0004 בתקון הז', ומבני \u0003שלשים\u0004 בתקון הח'. כמ״ש בתקון הז' ע״ש."],[6,"תקונא תשיעאה","וכו׳: התקון התשיעי. השערות מתחברות במשקל מלא עם אלו השערות התלויות, וכולן במשקל יפה כגבור אמיץ בעל נוצח מלחמות. משום שכל השערות נמשכות אחר אלו התלויות, וכללות כולן הן באלו התלויות, וכולן נמשכות עד החזה. ועל כן כתוב, \u0003תפארת\u0004 בחורים כחם. וכתוב, בחור כארזים, דהיינו כגבור עושה גבורות. וזו היא \u0003תפארת,\u0004 הכולל, כח וגבורה ורחמים."],[6,"","פירוש. תקון זה הוא ליחד השערות דימין ושמאל דדיקנא עם השערות הנמשכות ותלויות למטה באמצע הדיקנא, כי יש דינין בקו ימין מבחינת נקודת החולם, שה\"ס דינין דנוקבא, ויש דינין דקו שמאל מבחינת נקודת השורק, וה״ס דינין דדכורא. (כנ״ל ב״א דף ט״ו ד״ה ההוא) ובעת שהקו האמצעי מיחד ימין ושמאל זה בזה, נמצאים הדינים משלימים זה את זה, כי הדינים דימין ממעטים הג״ר דחכמה דקו שמאל, כדי שיתיחד עם קו הימין, כי זולת זה אין קו שמאל רוצה להתיחד עם קו הימין (כנ״ל לך דף י״ג ד״ה ונתבאר) והדינים דקו שמאל מבטלים הדינים דקו ימין, כי קו הימין מקבל חכמה מקו שמאל ע״י התכללותו בו. וזה נבחן, כאלו השערות דיקנא שמימין הפנים ומשמאל הפנים נמשכות ומתחברות עם השערות האמצעיות התלויות למטה מן הראש, ונעשים כולם כלל אחד ונמשכים עד החזה, כדי לבטל הדינים של המלכות הנמצאת בנקב החזה."],[6,"","וז״ש תקונא תשיעאה, \u0003דמתחברן שערי בשקולא מליא,\u0004 שהשערות דימין ושמאל דדיקנא מתחברים במשקל מלא, \u0003עם אינון שערי דתליין,\u0004 עם השערות התלויות באמצע, למטה מהפנים. אשר אז השערות, שהם הדינים דנוקבא שמימין, והשערות שהם דינים דדכורא שמשמאל, משלימים אלו את אלו, בהתיחדם בקו האמצעי, כנ״ל. וז״א נבחן אז על ידיהן, \u0003כחד גיבר תקיף מארי נצחן קרבייא,\u0004 כי הדינים דימין נוצחים כל החצונים המתאחזים בדינים דשמאל, ודינים דשמאל נוצחים כל הקליפות המתאחדות בדינין דימין, כנ״ל, והוא, \u0003משום דכלהו שערי אתמשכן בתר אינון דתליין,\u0004 משום שכל השערות שהן בימין ושמאל של הפנים נמשכים אחר אלו שערות התלויות למטה מן הפנים. ומתחברות בהן לאחד. \u0003וע״ד כתיב, תפארת בחורים כחם,\u0004 שהדין הנמצא בשערות דימין, הוא כל \u0003הכח\u0004 שבימין, שהת״ת משמש עמו כדי ליחד השמאל עם הימין (כנ״ל לך דף י״ג ד״ה ונתבאר) שהת״ת מעוררם בסוד המסך דחירק, כמ״ש שם. וכתיב \u0003בחור כארזים, כגבור העושה גבורות,\u0004 שה״ס ההשלמה שקו ימין מקבל ע״י הגבורות דקו שמאל כנ״ל, \u0003ודא הוא תפארת,\u0004 שיחוד הזה שבשערות דיקנא נקרא בשם ת״ת, הכולל בזה, \u0003חילא וגבורתא ורחמי,\u0004 כי דינין דימין נקראים עתה \u0003כח,\u0004 שהוא כל כח היחוד דימין ושמאל כנ״ל. והדינים דשמאל נקראים \u0003גבורה,\u0004 שעל ידם מתגבר על כל הקליפות לכלותם, והקו האמצעי עצמו המיחד אותם נקרא \u0003רחמים.\u0004"],[6,"","וז״ש \u0003וכלא אתמשך,\u0004 ויש כאן חסר, וצריך לומר, \u0003וכלא אתמשך עד טבורא דלבא,\u0004 שבכח היחוד הנעשה ע״י שערות התלויות, נמשכות כל השערות עד טבור הלב, שהוא נקב החזה ששם בחינת המלכות דמדת הדין הנכללת בפרסה שבחזה, והמלכות הזאת מקבלת ומתמתקת ע״י כללות שערות דיקנא, כמ״ש \u0003וכללא דכלהו באלין דתליין.\u0004 ולפיכך נקרא תקון הזה בפרשת שלח \u0003ועל רבעים,\u0004 כי עתה עבר התקון על דור רביעי, כי התקון הא׳ היה בב' תפוחין, שהוא נקרא \u0003ופשע,\u0004 בסוד ועובר על פשע, ששם קבלה המלכות תקונה הראשון, וב' תפוחין אלו להיותם נמצאים בלחי העליונה, שה״ס בינה, הם נקראים \u0003אבות.\u0004 ואח״כ בתקון ז׳ קבלה המלכות תקין בלחי התחתונה, דהיינו בשפה תתאה. ששם בחינת בנים, כי הלחי התחתונה היא בחינת בן ללחי העליונה וע״כ נקרא התקון בשם \u0003פוקד עון אבות על בנים\u0004 (כנ״ל אות רצ\"ב) ואח״כ בתקון ח׳ קבלה המלכות תקונה בבחינת גוף ממש בגרון ובעורף, וע״כ נקרא \u0003על שלשים.\u0004 שהוא דור שלישי ללחי העליונה. (כנ\"ל אות רצ״ד) ועתה קבלה המלכות תקונה בבחינת החזה, שהוא מדרגה תחתונה מגרון, וע״כ נבחנת לדור רביעי ללחי העליונה, וע״כ נקרא \u0003ועל רבעים.\u0004"],[7,"תנא אר״ש כל","וכו׳: למדנו, א\"ר שמעון, כל אלו תקונים, וכל אלו הדברים רוצה אני לגלות לאותם שנשקלו במשקל, דהיינו להדבקים בקו האמצעי שבו סוד המתקלא (כנ״ל ספד״צ אות ג׳) ולא לאלו שנכנסו לפרדס החכמה ולא יצאו ממנו בשלום, אלא לאלו שנכנסו ויצאו ממנו בשלום, כי כל מי שנכנס ולא יצא, טוב לו שלא נברא."],[8,"כללא דכל מלין","וכו׳: הכלל של כל הדברים, עתיק דעתיקין וזעיר אנפין הכל אחד, בבחינת עצמותם, והכל הוא למעלה מן הזמן מבחינת עצמותם, שהיה הוה ויהיה, שוים בהם, והכל הוא בהוה, והכל היה, והכל יהיה. שאין באלקיות ענין קודם ואח״כ. וכן אין שם כלל שינוי מעשה מבחינת עצמותם, כגון מרחמים לדין וכדומה, כי לא ישתנה בעתיד ולא נשתנה בעבר, ואינו משונה בהוה. אלא שנתתקן בתקונים אלו בשביל התחתונים. ונשלמה הצורה הכוללת כל הצורות דהיינו ז״א. שה״ס צורת אדם, הכולל דכר ונוקבא. הצורה הכוללת כל השמות, כי ז״א נקרא הויה, שהוא שם, הכולל כל השמות. הצורה, שנראות בתוכה כל הצורות, ולא שהוא צורה ממש, אלא כעין צורה זו."]],[]],[["כַּד אִתְחַבְּרָן עִטְרִין וְכִתְרִין, כְּדֵין הוּא אַשְׁלְמוּתָא דְּכֹלָּא. בְּגִין, דְּדִיּוּקְנָא דְּאָדָם, הֲוִי דִּיּוּקְנָא דְּעִלָּאִין וְתַתָּאִין דְּאִתְכְּלָלוּ בֵּיהּ. וּבְגִין דְּהַאי דִּיּוּקְנָא כָּלִיל עִלָּאִין וְתַתָּאִין, אַתְקִין עַתִּיקָא קַדִּישָׁא תִּקּוּנוֹי, וְתִקּוּנָא דִּזְעֵיר אַפִּין, בְּהַאי דִּיּוּקְנָא וְתִקּוּנָא.","וְאִי תֵּימָא מַה בֵּין הַאי לְהַאי. כֹּלָּא הוּא בְּמַתְקְלָא חֲדָא, אֲבָל מִכָּאן (נ\"א מנן) אִתְפָּרְשָׁן אָרְחוֹי. (נ\"א אתפשטן רחמי) וּמִכָּאן (נ\"א ומנן) אִשְׁתְּכַח דִּינָא. וּמִסִּטְרָא דִּילָן הֲווֹ שַׁנְיָין דָּא מִן דָּא. וְרָזִין אִלֵּין לָא אִתְמְסָרוּ, בַּר לִמְחַצְּדֵי חַקְלָא קַדִּישָׁא. וּכְתִיב (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו.","כְּתִיב (בראשית ב׳:ז׳) וַיִּיצֶר יְיָ אֱלֹהִים אֶת הָאָדָם, בִּתְרֵי יוֹדִי\"ן. אַשְׁלִים תִּקּוּנָא גּוֹ תִּקּוּנָא, טַבְרְקָא דְּגוּשְׁפַּנְקָא. וְדָא הוּא וַיִּיצֶר. תְּרֵין יוֹדִין לָמָּה. רָזָא דְּעַתִּיקָא קַדִּישָׁא, וְרָזָא דִּזְעֵיר אַפִּין. וַיִּיצֶר, מַאי צָר. צָר צוּרָה בְּגוֹ צוּרָה. (ודא הוא וייצר) וּמַהוּ צוּרָה בְּגוֹ צוּרָה. תְּרֵין שְׁמָהָן, דְּאִתְקְרֵי שֵׁם מָלֵּא, יְיָ אֱלֹהִים. וְדָא הוּא רָזָא דִּתְרֵין יוֹדִי\"ן דְּוַיִּיצֶר, דְּצָר צוּרָה גּוֹ צוּרָה. תִּקּוּנָא דִּשְׁמָא שְׁלִים, יְיָ אֱלֹהִים.","וּבְמָה אִתְכְּלִילוּ. בְּדִיּוּקְנָא עִלָּאָה דָּא, דְּאִקְרֵי אָדָם. דְּכָלִיל דְּכַר וְנוּקְבָּא. וְעַל דָּא כְּתִיב אֶת הָאָדָם דְּכָלִיל דְּכַר וְנוּקְבָּא. אֶת: לְאַפָּקָא וּלְמִסְגֵּי זִינָא דְּנָפִיק מִנֵּיהּ. (מדכר ונוקבא)","עָפָר מִן הָאֲדָמָה: דִּיּוּקְנָא בְּגוֹ דִּיּוּקְנָא. וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים: טַבְרְקָא דְּגוּשְׁפַּנְקָא גּוֹ בְּגוֹ. וְכָל דָּא לָמָּה. בְּגִין לְאִשְׁתַּלְּפָא וּלְעַיְּילָא בֵּיהּ סָתִים דִּסְתִּימָא עִלָּאָה, עַד סוֹפָא דְּכָל סְתִימִין. (הדא הוא דכתיב (בראשית ב׳:ז׳) ויפח באפיו נשמת חיים) נִשְׁמְתָא, דְּכָל חַיֵּי דְּעֵילָּא וְתַתָּא תַּלְיָין מֵהַהִיא נִשְׁמְתָא, וּמִתְקַיְימֵי בָּהּ.","וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, לְאַתְּרְקָא, וּלְעַיְּילָא בְּתִקוּנִין כְּגַוְונָא דָּא, וּלְאַשְׁלְפָא לְהַהִיא (נ\"א מההיא) נִשְׁמְתָא. מִדַּרְגָּא לְדַרְגָּא עַד סוֹפָא דְּכָל דַּרְגִּין. בְּגִין דִּיהֱוִי הַהִיא נִשְׁמְתָא מִשְׁתַּכְּחָא בְּכֹלָּא, וּמִתְפַּשְּׁטָא בְּכֹלָּא. וּלְמֶהֱוִי כֹּלָּא בְּיִחוּדָא חַד. וּמַאן דְּפָסִיק הַאי יִחוּדָא מִן עָלְמָא, כְּמַאן דְּפָסִיק נִשְׁמְתָא דָּא, וּמְחזֵי דְּאִית נִשְׁמְתָא אַחֲרָא, בַּר מֵהַאי. וּבְגִין כַּךְ, יִשְׁתְּצֵי הוּא וְדוּכְרָנֵיה מִן עָלְמָא לְדָרֵי דָּרִין.","בְּהַאי דִּיּוּקְנָא דְּאָדָם, שַׁארִי וְתָקִין כְּלָלָא דְּכַר וְנוּקְבָּא. כַּד אִתְתָּקַּן הַאי דִּיּוּקְנָא בְּתִקּוּנוֹי, שָׁארֵי מֵחַדּוֹי, מִבֵּין תְּרֵין דְּרוֹעִין. בְּאֲתָר דְּתַּלְיָין שַׂעְרֵי דְּדִיקְנָא, דְּאִתְקְרוּן (נ\"א דאתקרי) תִּפְאֶרֶת. וְאִתְפָּשַּׁט הַאי תִּפְאֶרֶת, וְתָקִין תְּרֵין חַדִּין, וְאִשְׁתְּלַיף לַאֲחוֹרוֹי, וְעֲבַד גּוּלְגַלְתָּא דְּנוּקְבָּא. כֹּלָּא סְתִימָא מִכָּל סִטְרוֹי. בְּשַׂעְרָא בְּפַרְצוּפָא דְּרֵישָׁא. וּבִכְלָלָא חֲדָא אִתְעָבִידוּ בְּהַאי תִּפְאֶרֶת, וְאִקְרֵי אָדָם דְּכַר וְנוּקְבָּא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ד:י״ג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת.","כַּד אִתְבְּרֵי פַּרְצוּפָא דְּרֵישָׁא דְּנוּקְבָּא, תַּלְיָיא חַד קוֹצָא דְּשַׂעְרֵי מֵאֲחוֹרוֹי דִּזְעֵיר אַפִּין, וְתָלֵי עַד רֵישָׁא דְּנוּקְבָּא. וְאִתְּעֲרוּ שַׂעְרֵי בְּרֵישָהָא, כֻּלְּהוּ סוּמָקֵי דִּכְלִלָן בְּגוֹ גְּוָונֵי, הֲדָא הוּא דִכְתִיב, (שיר השירים ז׳:ו׳) וְדַלַּת רֹאשֵׁךְ כָּאַרְגָמָן. מַהוּ אַרְגָּמָן. גְּוָונֵי דִּכְלִילָן בְּגוֹ גְּוָונֵי.","תָּאנָא, אִתְפָּשַׁט הַאי תִּפְאֶרֶת מִטַבּוּרָא דְּלִבָּא, וְנָקִיב וְאִתְעֲבָר בְּגִיסָא אַחֲרָא, וְתָקִין פַּרְצוּפָא דְּנוּקְבָּא עַד טַבּוּרָא. וּמִטַבּוּרָא שָׁארֵי, וּבְטַבּוּרָא שְׁלִים.","תּוּ אִתְפְּשָׁט הַאי תִּפְאֶרֶת, וְאַתְקִן מֵעוֹי דִּדְכוּרָא, וְעָיִיל (ואתתקן) בְּהַאי אֲתָר כָּל רַחֲמִין, וְכָל סִטְרָא דְּרַחֲמֵי. וְתָאנָא, בְּהָנֵי מֵיעַיין אִתְאַחֲדָן, שִׁית מֵאָה אֶלֶף רִבּוֹא מָארֵי דְּרַחֲמֵי. וְאִתְקְרוּן בַּעֲלֵי מֵיעַיין. דִּכְתִּיב, (ירמיהו ל״א:כ׳) עַל כֵּן הָמוּ מֵעַי לוֹ רַחֵם אַרַחֲמֶנוּ נְאֻם יְיָ.","תָּאנָא, הַאי תִּפְאֶרֶת, כָּלִיל בְּרַחֲמֵי, וְכָלִיל בְּדִינָא, וְאִתְפָּשַּׁט רַחֲמֵי בִּדְכוּרָא, וְאִתְעֲבָר וְנָקִיב (ס\"א ונהיר) לִסְטַר אַחֲרָא, וְתָקִין מֵיעוֹי דְּנוּקְבָּא, וְאִתְתְּקָנוּ מְעָהָא בְּסִטְרָא דְּדִינָא.","תָּאנָא, אִתְתָּקַן דְּכוּרָא בְּסִטְרֵיה, בְּמָאתָן וּתְמַנְיָא וְאַרְבְּעִין תִּקּוּנִין דִּכְלִילָן בֵּיהּ, וּמִנְהוֹן לְגוֹ, וּמִנְּהוֹן לְבַר. מִנְּהוֹן רַחֲמֵי. וּמִנְּהוֹן דִּינָא. כֻּלְּהוּ דְּדִינָא, אִתְאֲחָדוּ בְּדִינָא דַּאֲחוֹרוֹי, דְּנוּקְבָּא אִתְפַּשָּׁטַת תַּמָּן. וְאִתְאַחֲדוּ וְאִתְפָּשָׁטוּ בְּסִטְרָהָא."],[[0,"כד אתחברן עטרין","וכו׳: כשמתחברים בז״א העטרות והכתרים, דהיינו המוחין דג״ר, אז הוא השלמת הכל, של כל העליונים והתחתונים. משום שצורת אדם, היא צורה שעליונים ותחתונים נכללים בה. ומשום שצורה זו כוללת עליונים ותחתונים, התקון עתיקא קדישא את תקוניו, ותקון ז״א, בצורה זו ובתקון זה."],[0,"","פירוש. כל התקונים הנמצאים בעולמות לא באו אלא לתקן המלכות דצמצום א׳ (כמ״ש בתע״ס שיעור א') ועיקר תקונה הוא בסוד תקון אדם, שיורה על התכללות כל הצורות, וה״ס המלכות המקבלת מג׳ הקוין, כי המלכות ה״ס פני אדם, וג׳ הקוין ה״ס אריה שור נשר, הכוללים כל הצורות, והמלכות מקבלתם ונכללת מהן. ותקון אדם זה, התחיל בעתיקא קדישא, שה״ס כל המספרים י״ג שנאמר בו, י״ג חוורתא י״ג נימין, י״ג תקוני דיקנא וכו׳ כי חו״ב תו״מ שבכל אחד ג׳ קוין ה״ס י״ב. ועם מלכות המקבלתם הכוללת כולם, הם י״ג. אמנם עיקר תקון אדם נעשה בז״א ומלכות. שז״א ה״ס ג׳ קוין, ופרצוף המלכות הוא המקבלת אלו ג׳ הקוין. שעי״ז הולכת ומתתקנת המלכות לאט לאט עד גמר התקון, שאז, על ידי כל האורות שקבלה המלכות בשיתא אלפי שני, מתתקנת המלכות דצמצום א'."],[0,"","וז״ש, \u0003אתתקן בתקונין אלין אשתלים דיוקנא דכליל כל דיוקנין,\u0004 שכל אלו התקונים דעתיקא ודז״א, משלימים צורת אדם הכוללת כל הצורות. שהן אריה שור נשר. וכשז״א מקבל תקונים אלו נקרא גם הוא אדם. והוא \u0003דיוקנא דכליל כל שמהן,\u0004 כי השם של ז״א שהוא הויה, כולל בשביל זה את כל השמות. \u0003דיוקנא דאתחזי בגוויה כל דיוקנין,\u0004 כלומר, שגם מלכות נראית שמה, עד שהתקון מגיע למלכות דצמצום א'. וז\"ש, \u0003דיוקנין דעלאין ותתאין אתכללו ביה,\u0004 כי פני האדם כוללים בתוכם את כל העליונים, הנכללים בג׳ קוין המכונים אריה שור נשר, וכן כוללים צורת עצמם, שממנה נמשכים כל התחתונים, וע״כ התקון המגיע לפני אדם נתתקן עמו כל העליונים וכל התחתונים. וז״ש, \u0003ובגין דהאי דיוקנא כליל עלאין ותתאין, אתקין עתיקא קדישא תקונוי, ותקונא דז״א, בהאי דיוקנא ותקונא.\u0004 כדי שיוכל לתקן בזה כל המציאות עד גמר התקון כנ״ל."],[1,"ואי תימא מה","וכו׳: ואם תאמר, מה בין זה לזה. בין עתיקא לז״א, ומשיב, הכל הוא במשקל אחד. אבל, מכאן, מעתיקא, מתחלקים דרכיו. ומכאן, מז״א, נמצא הדין ורק מצדינו הם משונים זה מן זה. וסודות אלו אינם נמסרים חוץ מלקוצרי השדה הקדוש. דהיינו אותם שזכו לתקן את המלכות הנקראת שדה וכבר קוצרים תבואתה. וכתוב סוד ה׳ ליראיו."],[1,"","פירוש. עיקר דרכי התקון באים בסדר חסד דין ורחמים שה״ס ג׳ קוין. ואלו חד״ר מקור מציאותם הם בז״א, אלא בדרך התכללות שהג״ר כלולים מז״א ומלכות, נמצאים הם גם בג״ר. וז״ס שאמר לעיל (אות ל״א) \u0003לית שמאלא בהאי עתיקא.\u0004 ועכ״ז כיון שיש שם בחינת התכללות מזו״ן, היה אפשר שיתוקנו שם ג׳ קוין, כדי להמתיק ג׳ הקוין שבז״א. וז״ש, \u0003אבל מכאן אתפרשן ארחוי,\u0004 שג' קוין שהם בעתיקא, אינם אלא לחלק הדרכים בין ימין ושמאל ואמצע, כדי שז״א יקבל מהם. אבל בעתיקא עצמו, אין ימין ושמאל. \u0003ומכאן אשתכח דינא,\u0004 אבל בז״א יש שמאל, שהוא דין במציאות ממש, ונמצאים בו משום זה ג׳ קוין חסד דין ורחמים במציאות ממש. נמצא, \u0003ומסטרא דילן הוו שניין דא מן דא.\u0004 כי אותם ההבחנות אם יש דין או אין דין הן רק כלפי התחתונים אבל מבחינת העצמות הכל הוא אלקיות, למעלה מן הזמן למעלה מן המקום למעלה מכל שינוי. וכל אותם המדרגות והתקונים שאנו מבחינים באלקיות, הם כולם רק מיני העלמות וכיסוים כלפי התחתונים, כי המספר עשר ספירות הוא כמו שאתה אומר, עשר מיני כסוים, על עצמותו ית'. וכן כל התמונות המדומים מזמן ומקום וממעשים, כולם אינם רק מיני כסוים על אלקותו ית׳, הנראים כך לעיני התחתונים. וכמו האדם אינו מתפעל ואינו משתנה במשהו מחמת הכסוים שהוא מתעלם בהם, כי רק חבריו מתפעלים מהעלמתו או מהתגלותו, כך אלקותו ית׳ אינו משתנה ואינו מתפעל ח״ו משהו מתוך אלו המדרגות והתקונים והשמות שבזמן ומקום ושינוי מעשה, שהתחתונים מבחינים בכסוים שלו (ועי׳ בזה במבוא לספר הזהר, שנדפס בחלק א') אלא שיש לדעת שכסוים אלו משמשים ג״כ לגילוים, ע״ד שיסד האריז״ל בזמירות, במלין סתימין תתגלון פתגמין. ולא עוד אלא לפי מדת הכסוי שיש בכל שם ותקון, כך היא מדת הגילוי הנמצא בו. ומי שזוכה לקבל מדת הכסוים כהלכתם, זוכה אח״כ שהכסוים נעשו לו למדות גילוים. והלומד צריך לזכור דברים אלו בזמן הלימוד, ולא יכשל במחשבתו."],[2,"כתיב וייצר ה׳","וגו׳: כתוב, \u0003וייצר\u0004 ה׳ אלקים את האדם. בשתי יודין השלים תקון בתוך תקון, שהוא חותם הטבעת, וזה הוא \u0003וייצר,\u0004 עם ב׳ יודין. ומפרש דבריו. ב׳ יודין למה. הוא, כי הן, סוד עתיקא קדישא וסוד ז״א. \u0003וייצר,\u0004 מה צר. ומשיב, צר צורה בתוך צורה. שואל, מהו צורה בתוך צורה. ומשיב, היינו ב׳ שמות הנקראים שם מלא, שהם הויה אלקים. וזה הוא סוד ב׳ יודין של \u0003וייצר,\u0004 שצר צורה בתוך צורה, שהוא התקון של שם מלא הויה אלקים. \u0003טברקא דגושפנקא\u0004 פירושו לפי הענין חותם הטבעת."],[2,"","פירוש. ר״ש מביא כאן כעין הקדמה על מעלת המלכות, ומהותה, מטרם שבא לפרש פרטיות עניני המלכות. ונודע שהמלכות נקראת חכמה תתאה, משום שאין גילוי החכמה בשום ספירה מע״ס אלא בה, (כנ״ל ב״א דף רע״ו ד״ה ועוד כמה) והיינו בשעה שהמלכות מקבלת מג׳ קוין דז״א, ואז נקראת המלכות, טברקא דגושפנקא. כי המלכות עצמה ה״ס טבעת המלך, וג' קוין שמקבלת מז\"א, ה״ס החותם שנחקק בה, ששם מגולה בה החכמה."],[2,"","וז״ש \u0003בתרי יודין אשלים תקונא גו תקונא,\u0004 דהיינו שהשלים תקון ג׳ קוין שיאירו בתקון המלכות. \u0003ודא הוא וייצר,\u0004 שענין זה מרומז בהמלה וייצר. שואל, \u0003תרין יודין למה,\u0004 מה מרמזים ב׳ יודין דוייצר. ומשיב \u0003רזא דעתיקא קדישא ורזא דזעיר אפין,\u0004 שה״ס חכמה סתימאה, שבא״א הנקרא עתיקא קדישא, וחכמה דל״ב נתיבות של ז״א. וע״כ אומר \u0003רזא\u0004 דעתיקא קדישא, \u0003ורזא\u0004 דז״א. ואינו אומר, עתיקא קדישא, וז״א, כי מרמז לבחינת החכמות שבהם. שבב׳ חכמות אלו צר נשמת האדם, דהיינו הג״ר דז״א המכונים אדם, כמ״ש והולך. וז\"ש, \u0003ומהו צורה בגו צורה.\u0004 ומשיב, \u0003תרין שמהן דאתקרי שם מלא הויה אלקים, ודא הוא רזא דתרין יודין דוייצר,\u0004 כי ב׳ שמות הויה אלקים רומזים על א״א וז״א (כנ״ל אות רמ\"ה), והיינו \u0003דצר צורה גו צורה,\u0004 שצר צורת חכמה סתימאה דא״א בפנימיות צורת החכמה דל״ב נתיבות דז״א. וזה הוא, \u0003תקונא דשמא שלים הויה אלקים.\u0004 שהויה רומזת על ח״ס דא״א, ואלקים על חכמה דז״א. והוא מטעם, כי חכמה דא״א נסתמה, ואינה מאירה אלא חכמה דל״ב נתיבות דז״א, וכיון שהרצון המאציל היה שתתגלה גם הארת חכמה סתימאה בעולמות, ע״כ צר אותה בבחינת צורה תוך צורה בפנימיות חכמה דל״ב נתיבות, ועי״ז מגיעה הארת חכמה סתימאה לעולמות, שהיא שורש כל המציאות."],[3,"ובמה אתכלילו בדיוקנא","וכו׳: שואל, ובמה נכללו אלו ב׳ צורות חכמה הנ״ל שצר צורה תוך צורה. ומשיב, בדמות העליונה הזו שנקראת אדם, הכולל זכר ונקבה, דהיינו ז״א הכולל ז״א ומלכות, וע״כ כתוב \u0003את האדם\u0004 שכולל זכר ונקבה, \u0003את,\u0004 שאומר את האדם, הוא להוציא ולרבות המין שיוצא ממנו, דהיינו המלכות שהיא הנוקבא דז״א ויוצאת ממנו. שבמלכות הזו מתלבשות ב׳ צורות הנ״ל, צורה תוך צורה. שה״ס ב׳ יודין דוייצר. שה״ס חכמה עלאה דא\"א בתוך חכמה תתאה דמלכות. שה״ס החכמה דל״ב נתיבות היוצאת בז״א ומקום גילויה היא רק במלכות דהיינו בנוקבא דז״א. וע״כ נקראת חכמה תתאה, כנגד חכמה דא״א, שהארתה מלובשת בתוכה."],[4,"עפר מן האדמה:","היינו דמות בתוך דמות. \u0003ויפח באפיו נשמת חיים,\u0004 היינו החותם של הטבעת לפני ולפנים. וכל זה למה. כדי להוציא ולהכניס בו, סתים דסתימא עלאה, שהוא חכמה סתימאה דא״א, עד סוף דכל סתימין, שהיא החכמה דל״ב נתיבות, שבז״א, שהוא סוף ההעלם, כי אחר שתגיע חכמה זו דל״ב נתיבות מז״א אל הנוקבא דז״א, היא מתגלית, ואינה עוד סתומה, וע״כ נבחן ז״א לסוף דכל סתימין. והיא נשמה שכל החיים שלמעלה ושלמטה, דהיינו המוחין של ז״א, ושל הנוקבא הכוללת התחתונים, תלוים מנשמה ההיא ומתקיימים בה."],[4,"","פירוש. עפר מן האדמה, הוא סוד מיתוק המלכות בבינה, שעי״ז נעשית מוכשרה לקבל אור העליון (כנ\"ל ב״א דף ז׳ ד״ה כבר). וז״ש, \u0003עפר מן האדמה דיוקנא בגו דיוקנא,\u0004 דהיינו שנכללה צורת המלכות דז״א הנקראת \u0003עפר,\u0004 בצורת הבינה הנקראת \u0003אדמה. ויפח באפיו נשמת חיים טברקא דגושפנקא גו בגו,\u0004 דהיינו המוחין דבינה שה״ס המלכות הכוללת בתוכה ג׳ הקוין, אז נקראת \u0003טברקא דגושפנקא,\u0004 ואור הזה דמלכות וג' קוין, נקרא נשמה דז״א, משום שמקבלו מבינה, ואור הבינה נקרא נשמה. \u0003וז״ש, וכל דא למה בגין לאשתלפא,\u0004 וכו'. דהיינו שתכלול חכמה דא״א בתוך חכמה דל״ב נתיבות דז״א, ואח״כ ישפיע אותם אל הנוקבא שלו הנקראת חכמה תתאה ששם מקום הגילוי."],[5,"ויהי האדם לנפש חיה:","היינו להיות מושפע ולהכנס בתקונים כעין זה, דטברקא דגושפנקא, ולהוציא נשמה ההיא ממדרגה למדרגה עד סוף כל המדרגות, דהיינו מח״ס דא״א עד המלכות שהיא סוף המדרגות, כדי שתהיה נמצאת הנשמה ההיא בכל המדרגות, ותתפשט בכל, ויהיה הכל ביחוד אחד. ומי שמפסיק יחוד זה מן העולם, דהיינו שמפריד המלכות מיחוד ג׳ קוין, הוא כמי שמפסיק נשמה זו, דהיינו כמי שפוגם במוחין דז\"א, ומראה שיש נשמה אחרת חוץ מזו. דהיינו שמתדבק בסטרא אחרא, ומשום זה, יכלה הוא וזכרונו מן העולם לדורי דורות."],[6,"בהאי דיוקנא דאדם","וכו׳: בצורת אדם זו, התחיל ותקן הכלל של זכר ונקבה, דהיינו ז״א שכולל דכר ונוקבא. ואח״כ כשנתתקנה צורה זו דאדם בתקוניו, התחיל ז״א להתפשט מחזה שלו, מבין שתי זרועות, במקום ששערות דיקנא שלו תלויות, שמקום זה נקרא תפארת, ונתפשטה התפארת הזו, ותקן ב׳ חזות, ונשלף לאחוריו ועשה גולגלתא דנוקבא, שהיא המלכות, וכולה סתומה מכל צדדיה, בשערות ובפרצוף פנים של הראש."],[6,"","פירוש. כי מתחיל לפרש כאן סדר תקון הנוקבא דז״א שהיא המלכות. ומפרש ב׳ המצבים שבנוקבא, מצב א׳ כשהיא בבחינת אחורים דז\"א, שיש בהם ג׳ מדרגות שהם נפש רוח ונשמה דאחור דז״א. מצב ב', כשהיא בבחינת פנים דז״א. שיש לה נפש רוח נשמה דפנים דז״א. ובמצב א׳, עוד לא נחשבת לנוקבא נפרדת מז״א, אלא בבחינת דו פרצופין, כלומר שז״א ונוקביה כלולים יחד בפרצוף אחד, ז״א, הוא צד הפנים של אותו הפרצוף, והנוקבא, היא צד האחור. אלא במצב הב׳, היא ננסרת מז״א, כלומר שנפרדה ממנו לפרצוף מיוחד בפני עצמה, ואז הן נבחנים לדכר ונוקבא ממש. כמ״ש לפנינו (באות שכ״ד)."],[6,"","וז״ש, \u0003בהאי דיוקנא דאדם, שארי ותקין כללא דכר ונוקבא,\u0004 דהיינו שבא לפרש עתה המצב הא', שאז נתתקנו דכר ונוקבא בכלל אחד, דהיינו בפרצוף אחד, שהפנים ה״ס ז״א, והאחור ה״ס הנוקבא, וז״ש, \u0003כד אתתקן האי דיוקנא בתקונוי\u0004 כשדיוקנא דאדם, הכולל ז״א ונוקביה, נתתקן בתקונוי, שהוא עד הת״ת שלו, דהיינו שנתקנו בהפרצוף, חב״ד חג״ת עד החזה, מבחינת הכלים, ונפש רוח מבחינת האורות, ונודע שת״ת ה״ס קו אמצעי, הכולל ימין ושמאל, שה״ס ב׳ זרועות, וע״כ אחר שנסתיימה אצילות התפארת במקום החזה, הוא נחלק לבחינת ימין ושמאל הכלולים בתוכו, אשר בחינת הימין שבת״ת נשאר לז״א, ובחינת השמאל שבו נתרחק ממנו ונעשה לאחורים, דהיינו שנעשה לחב״ד חג״ת דאחורים, וממנו נעשה חב״ד חג״ת דנוקבא עד החזה."],[6,"","וז״ש \u0003שארי מחדוי מבין ב׳ דרועין,\u0004 שתקון הנוקבא מתחיל מחזה דז\"א, דהיינו ממקום סיום הת״ת שלו, הכולל בתוכו ב׳ דרועין, שהם ב׳ קוין ימין ושמאל, \u0003באתר דתליין שערי דדיקנא דאתקרי ת״ת,\u0004 כי שם במקום החזה, נשלמו ג״כ המשכות השערות (כנ״ל אות רצ\"ה) \u0003ואתפשט האי תפארת ותקין תרין חדין,\u0004 היינו שנחלק לבחינות ימין ושמאל הכלולים בו, ותקן ב׳ בחינות חזה, דהיינו ב׳ סיומים המכונים חזה, חזה א׳ מימין הת״ת, וחזה א׳ משמאל הת״ת, \u0003ואשתליף לאחורוי,\u0004 שבחינת החזה דשמאל הת״ת, נעשה לבחינת אחור של הפרצוף, \u0003ועבד גולגלתא דנוקבא,\u0004 ומאחור הזה של הפרצוף, עשה המאציל את הראש של הנוקבא דז״א. דהיינו חב״ד דכלים ואור הנפש מבחינת האורות. \u0003כלא סתימא מכל סטרוי, בשערא בפרצופא דרישא.\u0004 כלומר כיון שהאור שבראש קטן הוא, ע״כ לא ניכרו עוד הצדדים שבראש, ובחינת פנים ואחור שבו. כי שערות ראש ה״ס אחור הראש, ופרצוף פנים ה״ס הפנים שבראש. שכל אלו עוד סתומים בו. \u0003ובכללא חדא אתעבידו בהאי ת״ת,\u0004 שזכר ונקבה אלו נחשבים שנעשו בכלל אחד מן התחלקות הת״ת לימין ושמאל, כלומר, שאינם זכר ונקבה נפרדים בב׳ פרצופין. \u0003ואקרי אדם דכר ונוקבא,\u0004 ששניהם בכלל אחד נקראים אדם. \u0003הה״ד, כתפארת אדם לשבת בית.\u0004 כלומר שהנוקבא היא כאן כמו בית לאדם, ואינה נחשבת למדרגה מיוחדת."],[7,"כד אתברי פרצופא","וכו׳: כשנברא פרצוף פנים של הראש דנוקבא, תולה קווצה של שערות מאחוריו של ז״א, ותולה עד הראש של הנוקבא, ונתעוררו שערות ראשה, כולן אדומות הכלולות מכל גוונים, ז״ש ודלת ראשך כארגמן. מהו ארגמן, היינו גוונים הכלולים בתוך גוונים."],[7,"","פירוש. עתה מדבר מיציאת אור הרוח דנפש, שאז נעשה היכר פנים ואחור, ויצאו שערות באחורי הראש. וכמו שהכלים דנוקבא הם באחוריו של ז״א, כן השערות שלה נמשכו מאחורי הראש שלי ז״א. וז״ש, \u0003כד אתברי פרצופא דרישא דנוקבא,\u0004 דהיינו כשנעשה היכר בין הפנים דראש ובין אחורי הראש, שהיא בביאת אור הרוח אל ראשה, \u0003תלייא חד קוצי דשערי מאחורוי דז״א ותלי עד רישא דנוקבא,\u0004 דהיינו שהשערות שמאחורי הראש דז״א העירו יציאת השערות על ראש הנוקבא. והנה שערות דז״א שחורות (כנ״ל אות מ״ח) בסו\"ה שחורות כעורב. והוא מטעם המלכות דמדת הדין הגנוזה בדיא, שהגוון שלה אוכמא (כנ״ל אות קצ״ו) אמנם בנוקבא כיון שנמשכת מצד שמאל דז״א, הנמשך מצד שמאל דבינה, שאין בו כלום ממלכות דמדת הדין, שה״ס אדום, ע״כ גם שערות המלכות הן אדומות. וז״ש, \u0003ואתערו שערי ברישהא כלהו סומקי,\u0004 ואין בהם מגוון שחור כלום, אלא שהן כלולות מלבן וירוק, וז״ש, \u0003דכללן בגו גווני.\u0004 דהיינו בלבן וירוק. וז״ש \u0003מהו ארגמן, גווני דכלילן בגו גווני,\u0004 שהאדום כלול מלבן וירוק."],[8,"תאנא אתפשט האי","וכו׳: למדנו, תפארת הזה נתפשט מטבור הלב, דהיינו מנקב החזה, ונקב ועבר בצד האחר, דהיינו באחור, ותקן פרצוף הנוקבא עד הטבור. ומטבור היא מתחילה ובטבור היא נגמרת."],[8,"","פירוש. מביא מלואים לדבריו מן הברייתא. שאומרת, \u0003אתפשט האי ת״ת מטבורא דלבא,\u0004 דהיינו מנקב החזה, ומבחינת שמאל אשר שם. \u0003ונקיב,\u0004 היינו שעושה בית קבול חדש לבחינת השמאל בלבד. כי נקב, פירושו בית קבול. \u0003ואתעבר בגיסא אחרא,\u0004 שתקן את השמאל, שיהיה בבחינת אחור, \u0003ותקין פרצופא דנוקבא עד טבורא,\u0004 דהיינו הכלים דחב״ד חג״ת עד החזה, עם האורות דנפש רוח דנפש. ומפרש הטעם שמסתיימת בחזה, שהוא, \u0003ומטבורא שארי, ובטבורא שלים,\u0004 כיון שהיא מתחילה לצאת מן החזה דז״א, דהיינו מן הסיום של חב״ד חג״ת דז״א, ע״כ יצאה גם היא באותו השיעור, חב״ד חג״ת עד החזה באחוריו של ז״א. ולפיכך חסר לנוקבא נה״י דנפש וט״ס תחתונות דרוח. ולז״א חסרים הכלים שמחזה ולמטה, שהם נקראים נה״י, והאורות דנשמה. שה״ס המוחין. וצריך שתזכור כאן ערך ההפכי בין כלים לאורות (כנ״ל בפתיחה לחכמת הקבלה אות כ״ד)."],[9,"תו אתפשט האי","וכו׳: עוד נתפשט ת״ת הזה, ותקן מעיים של הזכר, והכניס באותו מקום כל הרחמים, וכל צד של רחמים. ולמדנו, באלו מעיים מתאחזים שש מאות אלף רבוא בעלי הרחמים, ונקראים בעלי מעיים שכתוב, על כן המו מעי לו רחם ארחמנו נאם ה׳."],[9,"","פירוש. מבאר כאן המוחין דג״ר של ז״א והשלמת הכלים דנה״י, התלוים זה בזה כנ״ל, וע״כ מכנה אותם \u0003מעיים,\u0004 שה״ס הפנימיות של למטה מחזה דז״א. שהפנימיות הזו מכונה מעיים ורומז על המוחין. כי ג׳ פרצופין דנפש רוח נשמה מלבישים זה על זה, והפנימיות של כולם הוא פרצוף הנשמה, שהוא המוחין. וז״ש, \u0003תו אתפשט האי ת״ת,\u0004 דהיינו שנתפשט מחזה שלו ולמטה עד סיום נה״י, \u0003ואתקן מעוי דדכורא,\u0004 דהיינו המוחין דג״ר המרומזים במעיים. שכל הרחמים נמשכים מהם. וז״ש, \u0003ועייל בהאי אתר כל רחמין וכל סטרא דרחמי,\u0004 כלומר בחינת הימין שבהם ה״ס רחמים, ובחינת הדין שבהם נתהפכו ונעשו לגורמים אל הרחמים, וע״כ הימין הוא רחמים, והשמאל, הוא סטרא דרחמים, דהיינו גורם לרחמים. באפן, שאין בהם בחינת דין כלל. וז\"ש, \u0003בהני מעיין אתאחדן שית מאה אלף רבוא מארי דרחמי.\u0004 כי המוחין דז״א הם בחינת ו״ק דג״ר מאמא, וע״כ הם \u0003שש מאות,\u0004 שספירות דאמא הן במספר מאה. והחכמה הכלולה בהם מכונה \u0003אלף,\u0004 והחסדים שבהם, ה״ס \u0003רבוא,\u0004 וע״כ הם שש מאות אלף רבוא מארי דרחמי."],[10,"תאנא האי תפארת","וכו׳: למדנו, התפארת הזה כלול ברחמים, וכלול בדין. והרחמים נתפשטו במוחין של הדכר שהוא ז״א, כנ״ל. ועבר והאיר לצד האחר, דהיינו לאחוריו של ז״א, ותקן המעיים של הנוקבא, דהיינו המוחין שלה. ונתתקנו המעיים שלה בצד הדין."],[10,"","פירוש. המוחין הנ״ל באים מאמא, ומתחלקים לימין ושמאל, דהיינו א׳ וחצי קו לימין, שהם קו ימין, שהוא חכמה, וימין הדעת, וא' וחצי קו לשמאל, שהם קו שמאל, שהיא בינה, וחצי הדעת השמאל, והם מתחלקים בין ז״א לנוקבא, שקו וחצי דימין לוקח ז״א, וקו וחצי דשמאל לוקחת הנוקבא. וז״ש, \u0003האי תפארת,\u0004 היינו המוחין שתפארת דז״א קבל ונתפשט על ידם מטבור ולמטה כנ״ל, \u0003כליל ברחמי וכליל בדינא,\u0004 שיש בהם קו וחצי דימין שהם רחמים, ויש בהם קו וחצי דשמאל שהם דינים, \u0003ואתפשט רחמי בדכורא,\u0004 שקו וחצי של רחמים נתפשטו בז״א. \u0003ואתעבר ונהיר לסטר אחרא ותקין מעוי דנוקבא,\u0004 והקו וחצי של הדין, עבר והאיר לצד האחור ותקן המוחין של הנוקבא, \u0003ואתתקנו מעהא בסטרא דדינא.\u0004 ונתקנו המוחין דנוקבא מצד הקו וחצי של הדין בלבד. ואין בהם רחמים כלל. וע״כ נקראים מוחין אלו דנוקבא בשם מוחין דאחור. ותדע שבמצב הזה היתה הנוקבא ביום ד׳ דמעשה בראשית, בסוד שני המאורות הגדולים, כי במצב הזה, הנוקבא מתחברת עם הנוקבא שבגופו דז״א, ונעשו שתיהן לנוקבא אחת, והיא גדולה כמו ז״א, שז״א לוקח קו וחצי דימין, והנוקבא קו וחצי דשמאל, ושניהם שוים. אמנם הנוקבא לא יכלה לעמוד באלו מוחין דאחור, להיותם כולם דין בלי רחמים כלל, דהיינו שמאל בלי ימין שאז גם הארת חכמה שבשמאל היא חשך ולא אור. וע״כ קטרגה הלבנה. כמ״ש זה (לעיל ב״א מאות ק״י עד אות קט״ו ע״ש) והתקון לזה נעשה בסוד הנסירה שיתבאר לפנינו (באות שכ\"ד ע״ש)."],[11,"תאנא אתתקן דכורא","וכו׳: למדנו, הדכר, שהוא ז״א, נתתקן בהצד שלו, שהוא ימין, ברמ״ח תקונים הכלולים בו. מהם הם בפנימיות ז״א, ומהם בחצוניות שלו, מהם רחמים, ומהם דין. וכולם של דין נתאחזו בדינים דאחורים דז״א שהנוקבא מתפשטת שם, והן נתאחזו ונתפשטו. בצד שלה."],[11,"","פירוש. ענין רמ״ח תקונים כבר נתבאר לעיל, (בהר אות נ') וז\"ל, \u0003ובגין דא יהיב לון אורייתא משמיה, זה שמי לעלם וזה זכרי לדר דר, והא אוקמוה, י\"ה עם שמי שס״ה, ו״ה עם זכרי, רמ״ח.\u0004 והפירוש הוא. כי מקור כל העבירות ונתינת כח לסטרא אחרא הוא גילוי הג״ר ממעלה למטה, שזו היתה הסבה לשבירת הכלים, וזה היה חטא של עצה״ד דהיינו שגילה הג״ר של השם מה שצריכים להעלים. ומקור כל המצות הוא להעלות מ״ן להמשכת המוחין בדרך ג׳ קוין, הממשיכים רק ו״ק דג״ר, כי הקו האמצעי ממעט הג״ר דקו שמאל שלא תמשכנה ממעלה למטה. (כנ\"ל ב״א דף ס׳ ד\"ה מחלוקת) הרי שכל התורה היא תקונים של השם הויה, אשר שס״ה לא תעשה הם תקונים להעלמת הג״ר שה\"ס \u0003י״ה.\u0004 ורמ״ח מצות עשה הן תקונים להמשיך ולגלות הו\"ק דג״ר, שה״ס \u0003ו״ה.\u0004 וז״ש, \u0003יהיב לון אורייתא משמיה,\u0004 דהיינו לתקון שם הויה. \u0003י״ה עם שמי, שס\"ה.\u0004 כלומר, שהכתוב זה \u0003שמי\u0004 לעלם, סובב על הג״ר דג\"ר שצריכים להעלים והרמז על זה ש \u0003שמי\u0004 עם י״ה גימטריא שס״ה, שעל ידיהם בא התקון של העלם \u0003י״ה. ו״ה עם זכרי, רמ\"ח,\u0004 כי זכרי, היינו מה שמצוה להזכיר ולגלות, שזה סובב על הו\"ק דג״ר, שה״ס \u0003ו״ה,\u0004 ובא הרמז, אשר ו״ה עם זכרי, הם סוד רמ״ח מצות עשה, שנתנו לנו לגלות ולהמשיך המוחין דו״ק דג״ר."],[11,"","וז״ש \u0003אתתקן דכורא בסטריה,\u0004 שה״ס ז״א, \u0003ברמ\"ח תקונין דכלילן ביה,\u0004 שה״ס רמ״ח מצות עשה, הממשיכים בו המוחין דו״ק דג״ר. \u0003מנהון לגו ומנהון לבר,\u0004 שיש מצות התלויות במחשבה ודבור, שהם תקונים לפנימיות ז״א, ויש מצות התלויות במעשה, שהם תקונים לחצוניות ז״א. \u0003מנהון רחמי,\u0004 דהיינו התלויות בקו ימין דז״א, \u0003מנהון דינא,\u0004 דהיינו התלויות בקו שמאל דז״א, ואומר, \u0003כלהו דדינא אתאחדו בדינא דאחורוי,\u0004 כלומר שדינין דשמאל נעשו בו לדינין דאחורים, \u0003דנוקבא אתפשטת תמן, ואתאחדו ואתפשטו בסטרהא.\u0004 שע״י תקון זה שהשמאל נעשו בו לאחור, נתדבקו כל הדינים בסטרהא דנוקבא, וז\"א נשאר כולו רחמים."]],[]],[["וְתָאנָא, חֲמִשָׁה עֶרְיָיתָא (נ\"א תקונין) אִתְגַּלְּיָין בָּה, בְּסִטְרָא דְּדִינִין חֲמִשָּׁה. וְדִינִין ה' (נ\"א בסטרא דדינא ודינהא) אִתְפַּשְּׁטָן, בְּמָאתָן וְאַרְבְּעִין וּתְמַנְיָא אָרְחִין. וְהָכִי תָּאנָא, קוֹל בְּאִשָּׁה עֶרְוָה. שֵׂעָר בְּאִשָּׁה עֶרְוָה. שׁוֹק בְּאִשָּׁה עֶרְוָה. יַד בְּאִשָּׁה עֶרְוָה. רֶגֶל בְּאִשָּׁה עֶרְוָה. דְּאַף עַל גַּב דִּתְרֵין אִלֵּין לָא שַׁנְיוּהָ חַבְרָנָא, וּתְרֵין אִלֵּין יַתִּיר מֵעֶרְוָה אִינּוּן.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, אִתְפָּשַׁט דְּכוּרָא וְאִתְתָּקַּן בְּתִקּוּנוֹי. אִתְתָּקַּן תִּקּוּנָא דִּכְסוּתָא דַּכְיָא. וְהָאַי הַוְיָא אַמָּה דַּכְיָא. אָרְכֵיהּ דְּהַהוּא אַמָּה, מָאתָן וְאַרְבְּעִין וּתְמַנְיָא עָלְמִין. וְכֻלְּהוּ תַּלְיָין בְּפוּמָא דְּאַמָּה, דְּאִתְקְרֵי יוֹ\"ד. וְכֵיוָן דְּאִתְגַּלְיָיא יוֹ\"ד פּוּמֵיהּ דְּאַמָּה, אִתְגְּלֵי חֶסֶד עִלָּאָה. וְהַאי אַמָּה חֶסֶד הוּא דְּאִתְקְרֵי, וְתָלֵי (נ\"א והאי חסד הוא תלי) בְּהַאי פּוּם אַמָּה. וְלָא אִקְרֵי חֶסֶד, עַד דְּאִתְגַּלְיָיא יוֹ\"ד דְּפוּם אַמָּה.","וְתָּא חֲזֵי, דְּלָא אִתְקְרֵי אַבְרָהָם שְׁלִים בְּהַאי חֶסֶד, עַד דְּאִתְגַּלְיָיא יוֹ\"ד דְּאַמָּה. וְכֵיוָן דְּאִתְגְּלֵי אִקְרֵי שְׁלִים, הֲדָא הוּא דִכְתִיב, (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וְהְיֵה תָמִים, תָמִים מַמָּשׁ. וּכְתִיב (שמואל ב כ״ב:כ״ד) וָאֶהְיֶה תָמִים לוֹ וָאֶשְׁתַּמְּרָה מֵעֲוֹנִי. מַאי קָא מַיְירֵי, רֵישָׁא וְסֵיפָא. אֶלָּא כָּל דְּגַלֵּי הַאי יוֹ\"ד, וְאִסְתְּמַר דְּלָא עַיְילֵיהּ לְיוֹ\"ד בִּרְשׁוּתָא אַחֲרָא. לִיהֱוִי שְׁלִים לְעָלְמָא דְּאָתֵי, וְלֶהֱוִי צָרִיר בִּצְרוֹרָא דְּחַיֵּי. מַאי בִּרְשׁוּתָא אַחֲרָא. דִּכְתִּיב, (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נֵכָר. וּבְגִין כַּךְ כְּתִיב, וָאֶהְיֶה תָמִים לוֹ, דְּכֵיוָן דְּהוּא תָּמִים בְּגִלּוּיָיא דְּיוֹ\"ד, וָאֶשְׁתַּמְּרָה מֵעֲוֹנִי.","וְכֵיוָן דְּאִתְפְּשַׁט אַמָּה דָּא, אִתְפְּשָׁט סְטָר גְּבוּרָה מֵאִינּוּן גְּבוּרָאן (בשמאלא) דְּנוּקְבָּא, וְאִשְׁתְּקַע בְּנוּקְבָּא בַּאֲתָר חַד, וְאַרְשִׁם בְּעֶרְיָיתָא, כְּסוּתָהּ דְּכָל גּוּפָא דְּנוּקְבָּא. וּבְהַהוּא אֲתָר אִקְרֵי עֶרְוָה דְּכֹלָא. אֲתָר לְאַצְנְעָא לְהַהוּא אַמָּה, דְּאִקְרֵי חֶסֶד. בְּגִין לְאִתְבַּסְּמָא גְּבוּרָה דָּא דְּכָלִיל חָמֵשׁ גְּבוּרָאן, בְּהַאי חֶסֶד דְּכָלִיל בְּחָמֵשׁ חֲסָדִין. חֶסֶד יְמִינָא, גְּבוּרָא שְׂמָאלָא. אִתְבְּסָם דָּא בְּדָא, וְאִקְרֵי אָדָם, כָּלִיל מִתְּרֵין סִטְרִין. וּבְגִין כַּךְ, בְּכֻלְּהוּ כִּתְרִין אִית יְמִינָא וּשְׂמָאלָא, דִּינָא וְרַחֲמֵי.","תָּאנָא, עַד לָא זַמִּין תִּקּוּנוֹי דְּמַלְכָּא, עַתִּיקָא דְּעַתִּיקִין, בָּנָה עָלְמִין, וְאַתְקִין תִּקּוּנִין לְאִתְקַיְּימָא. הַהוּא נוּקְבָּא לָא אִתְבַּסְמָא, וְלָא אִתְקְיָימוּ, עַד דְּנָחִית (רפ\"ט ע\"ב) חֶסֶד עִלָּאָה וְאִתְקְיָימוּ, וְאִתְבְּסָמוּ תִּקּוּנֵי נוּקְבָּא, בְּהַאי אַמָּה דְּאִקְרֵי חֶסֶד. הֲדָא הוּא דִכְתִיב, (בראשית ל״ו:ל״א) וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם, אֲתָר דְּכָל דִּינִין מִשְׁתַּכְּחִין תַּמָּן (ואינון תקוני אתתא, אשר היו לא כתיב אלא אשר מלכו) וְלָא אִתְבְּסָמוּ, עַד דְּאַתְקָן כֹּלָּא, וְנָפִיק הַאי חֶסֶד, וְאִתְיְשָׁב בְּפוּמָא דְּאַמָּה. הֲדָא הוּא דִכְתִיב, וַיָּמָת וַיָּמָת, דְּלָא אִתְקְיָימוּ, וְלָא אִתְבְּסָמוּ, דִּינָא בְּדִינָא.","וְאִי תֵּימָא אִי הָכִי דְּדִינָא כֻּלְּהוּ, וְהָא כְּתִיב וַיִּמְלוֹך תַחְתָּיו שָׁאוּל מֵרְחוֹבוֹת הַנָּהָר, וְהָא לָא אִתְחֲזֵי דִּינָא. דְּתָנֵינָן, רְחוֹבוֹת הַנָּהָר אִיהוּ בִּינָה, דְּמִינָהּ מִתְפַּתְּחִין חַמְשִׁין תַּרְעִין דִּנְהוֹרִין וּבוּצִינִין, לְשִׁית סִטְרֵי עָלְמָא. תָּאנָא, כֻּלְּהוּ דִּינָא, בַּר מֵחָד דְּאִתְקַיָּים בַּתְרָאָה, וְהַאי שָׁאוּל מֵרְחוֹבוֹת הַנָּהָר, דָּא הוּא חַד סִטְרָא, דְּאִתְפָּשָׁט וְנָפִיק מֵרְחוֹבוֹת הַנָּהָר.","וְכֻלְּהוּ לָא אִתְקָיָימוּ, לָא תֵּימָא דְּאִתְבָּטָלוּ, אֶלָּא דְּלָא אִתְקָיָימוּ בְּהַהוּא מַלְכוּ, (ובסטר נוקבא) עַד דְּאִתְּעַר וְאִתְפָּשַּׁט הַאי בַּתְרָאָה מְכֻּלְּהוּ, דִּכְתִּיב וַיִּמְלוֹךְ תַחְתָּיו הֲדַר. מַאי הֲדַר. חֶסֶד עִלָּאָה. וְשֵׁם עִירוֹ פָּעוּ, מַאי פָּעוּ. בְּהַאי פָּעִי בַּר נָשׁ דְּזָכֵי לְרוּחָא דְּקוּדְשָׁא וְשֵׁם אִשְׁתּוֹ מְהֵיטַבְאֵל, בְּכָאן אִתְבְּסָמוּ דָּא בְּדָא, וְאִתְקְרֵי אִשְׁתּוֹ, מַה דְּלָא כְּתִיב בְּכֻלְּהוּ.","מְהֵיטַבְאֵל, אִתְבַּסְמוּתָא דְּדָא בְּדָא. בַּת מַטְרֵד, תִּקּוּנִין דְּמִסְּטַר גְּבוּרָה. בַּת מֵי זָהָב, אִתְבְּסָמוּ וְאִתְכְּלִילוּ דָּא בְּדָא, מֵי זָהָב: רַחֲמֵי וְדִינָא. כָּאן אִתְדַּבְּקוּ אִתְּתָא בִּדְכוּרָא."],[[0,"ותאנא חמשה ערייתא","וכו׳: ולמדנו, חמשה עריות נגלו בה, מצד חמשה דינים, שהם חג״ת נ״ה שבקו שמאל שנתדבקו בנוקבא. וחמישה דינים נתפשטו ברמ״ח דרכים. והכי תאנא קול באשה ערוה, שער באשה ערוה, שוק באשה ערוה, יד באשה ערוה, רגל באשה ערוה. ואע״פ שאלו השנים, יד ורגל, לא שנו חברינו, אבל שנים אלו הם עוד יותר מערוה."],[0,"","פירוש. כבר נתבאר בדבור הסמוך, סוד רמ״ח, שהם סוד גילוי המוחין דו״ק דג״ר שמצוה לגלותם. ונודע שבחינת הג״ר והחכמה נמשכים מקו שמאל, ואפילו הו״ק דג״ר שמצוה לגלות, אין גילוי החכמה שבהם אלא ביחד עם הדינין דשמאל להעניש הרשעים (כנ״ל אות רי״ט) וז\"ש, \u0003ודינין חמשה אתפשטן במאתן וארבעין ותמניא ארחין\u0004 כי אין רמ״ח דרכים, שה״ס גילוי ו״ק דחכמה, יכולים להתגלות, זולת ע״י חמשה דינים דקו שמאל המתגלים עמהם להעניש הרשעים."],[0,"","וכנגד ה׳ דינין אלו, שהם חג״ת נ״ה דקו שמאל יש באשה ה׳ עריות. שההסתכלות בהם מעוררת דינים. וז״ש, \u0003חמשה ערייתא אתגליין בה בסטרא דדינין חמשה\u0004 והם \u0003קול שער שוק,\u0004 כנגד חג\"ת דשמאל, \u0003ויד ורגל,\u0004 כנגד נ״ה דשמאל. וז\"ש \u0003דאע\"ג דתרין אלין לא שניוה חברנא,\u0004 כי חז\"ל לא אסרו אלא ג׳ עריות שהם בחג״ת דשמאל, כי חג״ת בחינת ג\"ר הוא, שאינם נמתקים לעולם, אבל נו״ה דשמאל, שהם נמתקים ע״י קו האמצעי, ואז אין בהם דינים, לא אסרו חז״ל. \u0003ותרין אלין יתיר מערוה אינון,\u0004 כי יש בהם אחיזה לקליפות החמורות יותר מערוה. כי להיותם נו״ה, שהם לבר מגופא, מתדבקים בהם הקליפות."],[1,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו, בספרא דצניעותא, הזכר נתפשט ונתתקן בתקונין שלו. ונתתקן התקון דכסות נקיה, וזו נעשית אמה נקיה, ארכו של אמה ההיא, רמ״ח עולמות. וכולם תלוים בפי האמה הנקרא \u0003י׳,\u0004 וכיון שנגלית ה \u0003י׳\u0004 שהיא פי האמה, נגלה החסד העליון. ואמה זו נקראת חסד, ותלויה בפי אמה הזו, ואינה נקראת חסד, עד שנגלית ה \u0003י׳\u0004 של פי האמה."],[1,"","פירוש. אחר שביאר גדלות א׳ דז״א, שה״ס התפשטות נה״י שלו (המובא לעיל אות ש״ז) וביאר בנין הנוקבא במצב הא' שהיא כולה ה׳ גבורות דשמאל (כנ״ל אות ש״ח) מבאר עתה גדלות ב׳ דז״א, הנבחן בעיקר בתקון היסוד, שיהיה ראוי להולדת נשמות ע״י זווגו עם הנוקבא. ומקור ההפרש הוא, כי נה״י דגדלות א', הם כולם רק חסדים ואין בהם גילוי חכמה שבשמאל. (כמ״ש לעיל אות ש\"ז) \u0003ועייל בהאי אתר כל רחמין וכל סטרא דרחמי,\u0004 שפירושו שאפילו צד שמאל שבו נעשה לסטרא דרחמי, דהיינו לגורם יציאת החסדים. אבל עתה בגדלות ב׳ דז״א, נעשה תקון היסוד, שה״ס קו אמצעי שבנה״י אלו דגדלות ב׳, שתגלה גם חכמה עם החסדים. ותקון זה נקרא גילוי פי האמה, שה״ס עטרת היסוד, הנקראת \u0003י׳,\u0004 שהיא בחינת המלכות המקבלת מג׳ קוין הנקראים נה״י. ונודע, שבמלכות מתגלה החכמה. ע״כ נקראת עטרת יסוד, \u0003י׳,\u0004 הרומזת על חכמה תתאה. אמנם עיקר השם חכמה תתאה אינו בעטרת היסוד דז״א, אלא בנוקבא הנפרדת. כמ״ש לפנינו."],[1,"","והנה נתבאר שעיקר ההפרש מגדלות א׳ לגדלות ב׳, הוא, שבנה״י דגדלות א', אין שם גילוי כלל לחכמה שבשמאל, כי אפילו השמאל אינו משמש שם אלא גורם לחסדים. אבל בנה\"י דגדלות ב׳ יש שם גילוי הן לחסדים והן לחכמה. גם נודע שגילוי הארת החכמה שבשמאל מביא טהרה (כמ״ש לעיל תזריע דף מ״ה ד\"ה אמנם. ע״ש)."],[1,"","וז״ש, \u0003אתפשט דכורא ואתתקן בתקונוי.\u0004 דהיינו בתקונים דגדלות ב׳ הנ״ל. \u0003אתתקן תקונא דכסותא דכיא.\u0004 כי הקו האמצעי המשפיע חכמה אינו משפיע אלא \u0003בכסות,\u0004 המכסה את הג״ר דחכמה, כי הכסות אינה משפיעה רק ממטה למעלה שהוא ו״ק דחכמה (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) וזה נבחן \u0003לכסותא דכיא.\u0004 אבל אם הכסות מעכבת לגמרי על השפעת החכמה, היא נקראת כסותא סתם. ולא כסותא דכיא. \u0003והאי הויא אמה דכיא,\u0004 והיסוד עצמו שה״ס חסד, נקרא אמה דכיא, אחר שמשפיע גם חכמה. כי הטהרה באה רק ע״י גילוי החכמה. ולפיכך, בגדלות א׳, לא היו נחשבים לכסותא דכיא ולאמה דכיא, משום שהחכמה נעלמת שם לגמרי כנ״ל."],[1,"","וכבר נתבאר סוד המספר רמ״ח, שה״ס גילוי מוחין דו\"ק, בסוד זכר, עם ו״ה, שמצוה לגלותם (כנ״ל אות ש״ט). אמנם יש להבין למה בת״ת, קורא אותם רמ\"ח תקונים, ובנוקבא קורא אותם, רמ\"ח אורחין (כנ״ל אות ש״י) וכאן ביסוד, קורא אותם רמ״ח עלמין, והענין הוא, כי שם בז״א, עוד לא פעלו כלל רמ״ח אלו, כי שם עוד אין מתגלה החכמה, המרומזת ברמ״ח, אלא שם נעשו שורש התקונים לאלו הרמ״ח, שבשעה שיגלו החכמה לא יגלו אלא ע״י תקונים אלו. אבל עוד לא פעלו להעלים הג״ר דחכמה. כי גם ו״ק דחכמה לא נגלו שם. וע״כ נקראים שם \u0003רמ\"ח תקונים.\u0004 אבל כאן ביסוד דגדלות ב׳, שכבר פועלים לגלות הו\"ק דחכמה, ע״כ מכונים \u0003רמ\"ח עלמין,\u0004 מלשון העלם, על שהם מעלימים הג״ר דחכמה. אמנם מקום גילוי ו״ק דחכמה אינו ביסוד אלא במלכות, וע״כ הם נקראים בה \u0003ו״ק אורחין.\u0004 כי בה הם עושים דרכים לגלות ו״ק דחכמה."],[1,"","וז״ש \u0003ארכיה דההוא אמה,\u0004 היינו מדת החכמה הנגלית על ידי היסוד, כי אורך רומז על חכמה. הוא \u0003רמ״ח עלמין,\u0004 שה״ס השיעור של ו\"ק דחכמה, בסוד שמי עם זכרי, הוא רמ״ח, כנ״ל \u0003וכלהו תליין בפומא דאמה דאתקרי י',\u0004 דהיינו בעטרת יסוד, הנבחנת למלכות, שהיא מקבלת מכל ג׳ קוין נה\"י כנ״ל. ובה מקום גילוי של רמ״ח עלמין, שע״כ הם נקראים בה רמ״ח אורחין כנ״ל. \u0003וכיון דאתגליא י׳ פומיה דאמה, אתגלי חסד עלאה,\u0004 היינו חסד דאו״א עלאין, הנקרא אוירא דכיא. כי אחר שנגלה החכמה נמצא החסד שביסוד בבחינת אוירא דכיא. אבל מטרם שנגלית החכמה, אפילו שהוא מקבל חסד דאו״א עלאין, שהוא אוירא דכיא, הוא נעשה בו לחסד סתם, שאינו דכיא, משום שחסר מחכמה. וז״ש, \u0003ולא אקרי חסד,\u0004 דהיינו חסד עלאה הטהור, \u0003עד דאתגליא י׳ דפום אמה,\u0004 דהיינו אחר שמתגלה עטרת היסוד שהיא נקראת פי האמה, שה״ס גילוי החכמה, אז נקרא היסוד עצמו בשם חסד עלאה השלם."],[2,"ות״ח דלא אתקרי","וכו׳: ובוא וראה, שאברהם לא נקרא שלם בחסד הזה, עד שנתגלתה הי׳ של האמה, דהיינו עטרת יסוד, וכיון שנתגלתה נקרא שלם, ז\"ש התהלך לפני והיה תמים, תמים ממש. (כמ״ש לעיל בסמוך) וכתוב ואהיה תמים לו ואשתמרה מעוני. שואל, מה זה אומר, היחס של ראש הכתוב אל סופו. ומשיב, אלא כל מי שמגלה \u0003י׳\u0004 ההיא, דהיינו שמגלה החכמה שבעטרת יסוד, ונשמר שלא יכניס את ה \u0003י׳\u0004 לרשות אחר, דס״א, יהיה שלם לעולם הבא, ויהיה צרור בצרור החיים. דהיינו שנשמתו תכלל במלכות הנקראת צרור החיים, משום שג' הקוין מתקשרים בה לצרור אחד. מהו ברשות אחר. היינו שכתוב, ובעל בת אל נכר. דהיינו המלכות דס״א המושכת החכמה ממעלה למטה. ומשום זה כתוב, \u0003ואהיה תמים לו,\u0004 כיון שהוא תמים בגילוי ה \u0003י׳\u0004, דהיינו בבחינת עטרת יסוד, המאירה ממטה למעלה. אז \u0003ואשתמרה מעוני,\u0004 שלא להתדבק בבת אל נכר. כנ״ל."],[3,"וכיון דאתפשט אמה","וכו׳: וכיון שנתפשט אמה זו נתפשט צד הגבורה מגבולות השמאל שבנוקבא, שהן ה׳ גבורות חג״ת נ״ה דשמאל, ונשתקע במקום אחד בנוקבא, ונרשם בהעריה, הכסות של כל גוף הנוקבא. ובמקום זה נקרא ערות הכל, שהיא מקום להצניע אותה האמה הנקראת חסד, כדי להמתיק גבורה זו הכוללת ה׳ גבורות, בחסד הזה הכולל ה׳ חסדים. חסד הוא ימין, גבורה היא, שמאל, נתבשם זה בזה ונקרא אדם, הכלול מב׳ צדדים. ומשום זה בכל הספירות, יש ימין ויש שמאל, דין ורחמים."],[3,"","פירוש. כבר ידעת שיש ב׳ מצבים בנוקבא דז״א, מצב א', הוא בהיותה בבחינת נר״ן דאחור דז״א, שאז יש לה צד שמאל בלי ימין, שפירושו, חכמה בלי חסדים, שאז אפילו החכמה שיש לה לא תוכל להאיר. שז״ס קטרוג הלבנה. מצב הב', הוא אחר הנסירה ואחר שנתמעטה לבחינת נקודה, ונבנית מחדש בבחינת דלית לה מגרמה ולא מידי, שאפילו החכמה דצד שמאל אין לה, והיא צריכה לקבל הכל מז״א (כנ״ל אות ש\"ד ע\"ש) וכאן מדבר ממצב הב', שאפילו החכמה שבשמאל היא צריכה לקבל מיסוד דז״א."],[3,"","וז״ש, \u0003וכיון דאתפשט אמה דא,\u0004 דהיינו שנתפשט לרמ״ח עלמין, כנ״ל, בסוד זכרי עם ו\"ה, \u0003אתפשט סטר גבורה מאינון גבוראן בשמאלא דנוקבא,\u0004 שנתפשט מן היסוד, בתחילה, צד הגבורה מאלו הגבורות השייכים לנוקבא, דהיינו הארת החכמה שבקו שמאל, \u0003ואשתקע בנוקבא באתר חד,\u0004 שנתקבל צד השמאל מן היסוד, במקום אחר, בנוקבא, דהיינו ביסוד דנוקבא, ששם תקון המסך דמלכות המעכב מלהאיר ממעלה למטה, אלא רק ממטה למעלה, בסוד כסות על האור, ונמצא, שהארת החכמה דצד שמאל שהשפיע לה היסוד דז״א, מאירה מיסוד דנוקבא ולמעלה בכל הגוף שבנוקבא. ויחד עם הארת החכמה העולה מיסוד דנוקבא ממטה למעלה, נמשכה ג״כ כסות מן המסך שביסוד דנוקבא המכסה את האורות שלא יחזרו להמשך ממעלה למטה (כמ״ש לעיל באות שי״א) בסוד כסותא דכיא. וז״ש, \u0003וארשם בערייתא,\u0004 דהיינו בהמסך שביסוד דנוקבא, \u0003כסותא דכל גופא דנוקבא,\u0004 שיחד עם הארת החכמה המאירה מיסוד דנוקבא ממטה למעלה בכל הגוף שלה, עולה ג״כ כסות ממסך דיסוד הנוקבא השומר על האורות שלא ימשכו ממעלה למטה. \u0003ובההוא אתר אקרי ערוה דכלא.\u0004 כלומר שיש שם מקום אחיזה לחצונים, שלא ימשכו הארת החכמה ממעלה למטה. וע״כ צריכה להיות מכוסה ושמורה, שלא תבוא לגילוי עתה, ויאחזו בה החיצונים. \u0003אתר לאצנעא לההוא אמה דאקרי חסד,\u0004 שצריכה להצניע המקום, שיהיה מיוחד רק ליסוד דזי׳א, שה״ס קו האמצעי, שישפיע בה חסד. ואם יהיה חשש לאחיזת החצונים לא יתיחד עמה היסוד דז״א. \u0003בגין לאתבסמא גבורה דא דכליל ה׳ גבוראן, בהאי חסד דכליל ה' חסדין,\u0004 כדי שתתלבש החכמה בחסדים, שאז נשלמים שניהם. ויסוד דז״א כליל ה׳ חסדים, ויסוד דנוקבא כליל ה׳ גבורות. וז\"ש \u0003אתבסם דא בדא ואקרי אדם כליל מתרין סטרין,\u0004 דהיינו מימין ומשמאל, מזכר ונקבה. \u0003ובגין כך בכלהו כתרין\u0004 וכו'. שכל פרט ופרט כלול משניהם."],[4,"תאנא עד לא","וכו׳: למדנו, מטרם שהוכנו תקוני המלך, היה עתיקא דעתיקין דהיינו המאציל העליון, בונה עולמות ומתקן תקונים להתקיים. נוקבא ההיא לא נתבסמה ולא נתקיימה עד שירד החסד העליון ונתקיימו, כי להיותה חכמה דשמאל שאין לו קיום זולת בהתלבשות עם החסד שבימין. כנ״ל. ונתבסמו תקונים דנוקבא ביסוד הזה שנקרא חסד, ז״ש, ואלה המלכים אשר מלכו בארץ אדום, דהיינו המקום אשר כל הדינים נמצאים שם, כי אדום מורה על דינים. ולא נתבסמו עד שהתקין הכל, ויצא החסד הזה ונתישב בפי היסוד, שהוא עטרת היסוד ששם נגלה החכמה, (כנ״ל אות שי״א) וז״ש וימת וימת, בי לא נתקיימו ולא נתבסמו להיותם דין בדין בלי חסד."],[4,"","פירוש. כי סוד שביה״כ היה בכל ספירה, וע״כ מזכיר אותם בעתיקא, ובז״א, ובנוקבא. ואומר, שע״כ נשברו ז׳ מלכים דנוקבא להיותם חכמה בלי חסדים. עד שיצא מלך הדר, שה״ס חסדים ואז נתקיימו. כמ״ש לפנינו."],[5,"ואי תימא אי","וכו׳: ואם תאמר א״כ שהם כולם דינים, והרי כתוב, וימלוך תחתיו שאול מרחובות הנהר, ולא נראה שיהיה דין. כי למדנו, רחובות הנהר, הוא בינה שממנה נפתחים חמשים שערים של אורות ונרות לששה קצוות העולם, שהוא ז״א שנקרא עולם. ומשום זה נקראת רחובות הרי ששאול מרחובות הנהר אינו דין. ומשיב, למדנו, שכולם הם דין חוץ מאחד, שהוא מלך האחרון שנתקיים, דהיינו הדר. ושאול הזה מרחיבות הנהר, זה היא רק צד אחד, דהיינו צד שמאל, שנתפשט ויצא מרחובות הנהר, וע״כ הוא ג״כ דין."],[6,"וכלהו לא אתקיימו","וכו': וכולם לא נתקיימו, ואל תאמר שנתבטלו, אלא שלא נתקיימו במלוכה ההיא של דין, עד שנתעורר ונתפשט זה האחרון מכולם. שכתוב, \u0003וימלוך תחתיו הדר.\u0004 מהו הדר. הוא חסד עליון. \u0003ושם עירו פעו,\u0004 מהו פעו. היינו, שעל ידו פועה אדם, שזוכה לרוח הקודש. ועירו, הוא מלשון התעוררות. \u0003ושם אשתו מהיטבאל.\u0004 כאן נתבסמו זה בזה, והמלכות נקראת אשתו, מה שלא כתוב בכולם \u0003שם אשתו.\u0004 [1]"],[7,"מהיטבאל אתבסמותא","וכו׳: מהיטבאל, מורה התבשמות זה בזה, של דכר ונוקבא. כי ז״א ה״ס הויה דאלפין שבגי׳ מ״ה, והנוקבא, ה״ס הויה דההין שבגימטריא ב״ן. ומהיטבאל הוא בגי׳ מ״ה וב״ן. \u0003בת מטרד,\u0004 היינו על שם התקונים שבה מצד הגבורה, ומטרד הוא מלשון טרדות. \u0003בת מי זהב,\u0004 היינו שנתבשמו ונתכללו זה בזה מי זהב הרחמים והדין, כי \u0003זהב,\u0004 מורה על דין, דהיינו הארת החכמה, \u0003ומי\u0004 ה״ס חסדים. וכלולים יחד. כאן נתדבקו, האשה בדבר. מהיטבאל בהדר."]],[]],[["בְּסִטְרוֹי, אִתְפָּרְשָׁן בִּדְרוֹעִין, בַּשׁוֹקִין. דְּרוֹעִין דִּדְכוּרָא, חַד יְמִינָא, חַד שְׂמָאלָא דְּרוֹעָא קַדְמָאָה (ס\"א קדישא) תְּלַת קִשְׁרִין אִתְקָשָּׁרוּ בֵּיהּ, וְאִתְכְּלִילוּ ב' דְּרוֹעִין. וְאִתְכְּלִילוּ סַלְּקָא דַּעְתָּךְ. אֶלָּא ג' קִשְׁרִין בִּימִינָא, וְג' קִשְׁרִין בִּשְׂמָאלָא. ג' קִשְׁרִין דִּימִינָא, אִתְכְּלִילָן בְּג' קִשְׁרִין דִּשְׂמָאלָא. וּבְגִין כָּךְ, דְּרוֹעָא לָא כְּתִיב אֶלָּא חַד. אֲבָל יְמִינָא, לָא כְּתִיב בֵּיהּ זְרוֹעַ, אֶלָּא (שמות ט״ו:ו׳) יְמִינְךָ יְיָ. (תהילים קי״ח:ט״ו) יְמִין יְיָ אִתְקְרֵי, בְּג' קִשְׁרִין דַּאֲבָהָתָא דְּאַחֲסִינוּ לְחוּלָקֵיהוֹן.","וְאִי תֵּימָא הָא בִּתְלַת חֲלָלִין מוֹחָא דְּגוּלְגַּלְתָּא מִשְׁתַּכְּחִין. תָּאנָא, כֻּלְּהוּ ג' מִתְפַּשְּׁטִין, וּמִתְקַשְּׁרָן בְּכָל גּוּפָא, וְכָל גּוּפָא אִתְקְשַׁר בְּהָנֵי תְּלַת, וּמִתְקַשְּׁרָן בִּדְרוֹעָא יְמִינָא. וּבְגִין כַּךְ תָּאִיב דָּוִד וְאָמַר, (תהילים ק״י:א׳) שֵׁב לִימִינִי. מִשּׁוּם דְּהוּא אִתְחַבָּר עִמְּהוֹן דַּאֲבָהָתָא, וְיָתִיב תַּמָּן לְכוּרְסְיָא שְׁלֵימָתָא. וּבְגִין כַּךְ כְּתִיב (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים וְגוֹ', מִשּׁוּם דְּיָתִיב לִימִינָא. הַיְינוּ דִּכְתִּיב, (דניאל י״ב:י״ג) וְתָנוּחַ וְתַעֲמוֹד לְגוֹרָלְךָ לְקֵץ הַיָּמִין, כְּלוֹמַר, כְּמַאן דְּזָכֵי לַחֲבִיבוּתָא דְּמַלְכָּא. זַכָּאָה חוּלָקֵיהּ, דְּמַאן דְּפָרִישׂ מַלְכָּא יְמִינֵיהּ. וְקָבִּיל לֵיהּ תְּחוֹת יְמִינֵיהּ. וְהַאי יְמִינָא כַּד יְתִיב, קִשְׁרִין אִתְפַּשְּׁטָא.","וּדְרוֹעָא לָא אוֹשִׁיט יְדֵיהּ (ס\"א וקשרין לא אתפשטו ודרועא לא אושיט יתיב) בִּתְלַת קְשִׁירִין דְּאַמָרָן. וְכַד מִתְעָרִין חַיָּיבַיָּא, וּמִתְפַּשְּׁטָן בְּעָלְמָא, מִתְעָרִין תְּלַת אַחֲרָנִין, דְּאִינּוּן דִּינָא קַשְׁיָא, וְאוֹשִׁיט דְּרוֹעָא וְכַד אוֹשִׁיט דְּרוֹעָא, יַד יְמִינָא הוּא, אֲבָל אִתְקְרֵי (ישעיהו נ״א:ט׳) זְרוֹעַ יְיָ, (דברים ט׳:כ״ט) זְרוֹעֲךָ הַנְטוּיָה (נ\"א תלת קשרין אתקשרו ביה ואתכלילו תלת קשרין דימינא ותלת קשרין דשמאלא בג' קשרין דאבהתא דאחסינו לחולקיהון. ואי תימא הא בג' חללי מוחא דגולגלתא משתכחין. תאנא כולהו ג' מתפשטין ומתקשרין בכל גופא וכל גופא אתקשר בהני תלתא ומתקשרין בדרועא ימינא. והאי ימינא כד יתיב (קשרין לא אתפשטו ודרועא לא אושיט ויתיב) בתלת קשרין דאמרן. וכד חייביא מתערין. מתערין תלת אחרנין דאינון דינא קשיא ואושיט דרועא ואתקרי זרוע יי זרועך הנטויה) בְּזִמְנָא דְּג' אִלֵין אִתְכְּלִילָן בג' אַחֲרָנִין, אִקְרֵי כֹּלָּא יְמִינָא, וְעָבִיד דִּינָא בְּרַחֲמֵי, הֲדָא הוּא דִּכְתִּיב, יְמִינְךָ יְיָ נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב, בְּגִין דְּמִתְעֲרִן רַחֲמֵי בְּהוּ.","וְתָאנָא, בְּהַאי יְמִינָא מִתְאַחֲדָן תְּלַת מְאָה וְשִׁבְעִין אֶלֶף רִבּוֹא, דְּאִקְרוּן יְמִינָא. וּמְאָה וְתִמְנִין וַחֲמִשָּׁה אֶלֶף רִבּוֹא, מִזְּרוֹעַ דְּאִקְרֵי זְרוֹעַ יְיָ. מֵהַאי וּמֵהַאי תַּלְיָיא זְרוֹעָא, וְהַאי וְהַאי אִקְרֵי תִּפְאֶרֶת, דִּכְתִּיב, (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין מֹשֶׁה, הָא יְמִינָא. זְרוֹעַ, הָא שְׂמָאלָא. דִּכְתִּיב, (ישעיהו ס״ג:י״ב) זְרוֹעַ תִּפְאַרְתּוֹ, דָּא בְּדָא.","וְתָאנָא, בִּידָא שְׂמָאלָא, מִתְאַחֲדָן אַרְבַּע מְאָה וְחַמְשִׁין רִבּוֹא מָארֵי תְּרִיסִין, מִתְאַחֲדָן בְּכָל אֶצְבְּעָא וְאֶצְבְּעָא. וּבְכָל אֶצְבְּעָא וְאֶצְבְּעָא עֶשֶׂר אַלְפִין מָארֵי תְּרִיסִין מִשְׁתַּכְּחִין. פּוּק וַחֲשׁוֹב, כַּמָה אִינּוּן דְּבִידָא. וְהַהוּא יְמִינָא אִקְרֵי סִיּוּעָא קַדִּישָׁא, דְּאָתִי מִדְּרוֹעָא דִּימִינָא, מִתְּלַת קִשְׁרִין. (ואף על גב דאקרי יד הוי סיועא) דִּכְתִּיב (וכתיב) (שמואל ב ג׳:י״ב) וְהִנֵּה יָדִי עִמָּךְ. וּמִתְאַחֲדָן מֵהַאי, אֶלֶף וְאַרְבַּע רִבּוֹא, וּתְמַנְיָא, וְחָמֵשׁ מְאָה אַלְפִין מָארֵיהוֹן דְּסִיּוּעִין בְּכָל עָלְמָא. וְאִקְרוּן יַד יְיָ עִלָּאָה. יַד יְיָ תַּתָּאָה. וְאַף עַל גַּב דִּבְכָל אֲתָר יַד יְיָ שְׂמָאלָא. זָכוּ יְמִין יְיָ, אִתְכְּלִל יְדָא בִּזְרוֹעָא, וַהֲוִי סִיּוּעָא, וְאִקְרֵי יָמִין. וְאִי לָאו, יַד יְיָ תַּתָּאָה. תָּאנָא, כַּד מִתְעָרִין דִּינִין קַשְׁיָין לְאַחֲתָא בְּעָלְמָא, הָכָא כְּתִיב, (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, דְּכָל דִּינִין דְּמִשְׁתַּכְחִין מִדְּכוּרָא, תַּקִּיפִין בְּרֵישָׁא, וְנַיְיחִין בְּסוֹפָא. וְכָל דִּינִין דְּמִשְׁתַּכְחִין מִנּוּקְבָּא, נַיְיחִין בְּרֵישָׁא, וְתַקִּיפִין בְּסוֹפָא. וְאִלְמָלֵא דְּאִתְעָבֵידוּ כַּחֲדָא, לָא יַכְלִין עָלְמָא לְמִסְבַּל. עַד דְּעַתִּיק דְּעַתִּיקֵי סְתִימָא דְּכֹלָּא, פָּרִישׁ דָּא מִן דָּא, וְחָבַר לוֹן לְאִתְבַּסְּמָא כַּחֲדָא.","וְכַד פָּרִישׁ לוֹן, אָפִּיל דּוּרְמִיטָא לִזְעֵיר אַפִּין, וּפָרִישׂ לְנוּקְבָּא מֵאֲחוֹרוֹי דְּסִטְרוֹי, וְאַתְקִין לָהּ כָּל תִּקּוּנָהָא, וְאַצְנְעָא לְיוֹמָא דִּילֵיהּ, לְמֵיתָהָא לִדְכוּרָא. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:כ״א) וַיַּפֵּל יְיָ אֱלֹהִים תַּרְדֵּמָה עַל הָאָדָם וַיִּישָׁן. מַהוּ וַיִּישָׁן. הַאי הוּא דִּכְתִּיב, (תהילים מ״ד:כ״ד) עוּרָה לָמָּה תִּישָׁן יְיָ. וַיִּקַּח אַחַת מִצַּלְעוֹתָיו, מַאי אַחַת. דָּא הִיא נוּקְבָּא. כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי, וְסַלְּקָא, וְאִתְתַּקְנָא. וּבְאַתְרָהָא שְׁקִיעַ רַחֲמֵי וְחֶסֶד, הֲדָא הוּא דִכְתִיב, (בראשית ב׳:כ״א) וַיִסְגוֹר בָּשָׂר תַּחְתֶּנָּה. וּכְתִיב (יחזקאל ל״ו:כ״ו) וַהֲסִירוֹתִי אֶת לֵב הָאֶבֶן מִבְּשַׂרְכֶם וְנָתַתִּי לָכֶם לֵב בָּשָׂר.","וּבְשַׁעֲתָא דְּבָעָא לְמֵיעַל שַׁבְּתָא הֲוָה בָּרֵי רוּחִין וְשֵׁדִין וְעִלְעוּלִין, וְעַד לָא סִיֵּים לוֹן, אָתַת מַטְרוֹנִיתָא בְּתִקּוּנָהָא, וְיָתִיבַת קַמֵּיהּ. בְּשַׁעֲתָא דְּיָתִיבַת קָמֵּיהּ, אֲנָח לוֹן לְאִינּוּן בִּרְיָיאן, וְלָא אִשְׁתְּלִימוּ. כֵּיוָן דְּמַטְרוֹנִיתָא יַתְבַת עִם מַלְכָּא, וְאִתְחַבָּרוּ אַפִּין בְּאַפִּין, מַאן יֵיעוּל בֵּינַיְיהוּ, מַאן הוּא דְּיִקְרַב בַּהֲדַיְיהוּ. (בגין כך סתימא דמלה עונתן של תלמידי חכמים דידעין רזא דנא משבת לשבת.) וְכַד אִתְחַבְּרוּ, אִתְבְּסָמוּ דָּא בְּדָא. יוֹמָא דְּכֹלָּא אִתְבְּסָם בֵּיהּ. וּבְגִין כָּךְ, אִתְבְּסָמוּ דִּינִין דָּא בְּדָא, וְאִתְתְּקָנוּ עִלָּאִין וְתַתָּאִין."],[[0,"בסטרוי אתפרשן בדרועין","וכו׳: בצדדיו מתחלק בזרועות בשוקים. זרועות הזכר, אחד הוא ימין, ואחד שמאל. זרוע הא׳ הימנית, ג׳ קשרים נקשרו בו ונכללו בב' זרועות. שואל, היעלה על דעתך שנכללו, והיה צריך לומר, שהם בב׳ זרועות. ומשיב, אלא ג׳ קשרים יש בזרוע הימנית, וג' קשרים בשמאלית ונכללו ג׳ קשרים שבימין בג׳ קשרים שבשמאל. ומשום זה, לא כתוב זרוע אלא אחד, דהיינו על השמאל, אבל הימין לא כתוב בו זרוע, אלא ימינך ה'. ימין ה׳ נקרא כשיש בו ג׳ קשרים של האבות שהנחילו לחלקם."],[0,"","פירוש. אחר שביאר סוד דכר ונוקבא, שהם ימין ושמאל שבקו האמצעי דז״א, ת״ת, הדבוקים זה בזה, והנוקבא הוא באחור הדכר. מבאר עתה ימין ושמאל שבב' קוין שבז״א, שהם פרודים זה מזה ואינם פרצוף אחד. ועומדים בימין ושמאל, שהם חסד וגבורה דז״א, הנקראים זרועות. אמנם ג׳ קוין, חג״ת דז״א, כלולים יחד, ובכל אחד מג׳ קוין כלולים כל ג׳ קוין, והם נקראים ג׳ קשרים. ויש ג׳ קשרים בחסד, וכן ג׳ קשרים בגבורה, וכן ג׳ שלישים בת״ת. והזהר מדבר כאן רק מג׳ קשרים שבב׳ דרועין, שהן חסד וגבורה. ואלו הקוין נמשכים מן המוחין דז״א, ויש בהם ב׳ בחינות, א׳ מוחין דו״ק, אשר קו השמאל שולט, ודינים נמשכים ממנו, ואין שם חסדים כלום. ויש מוחין דג״ר, אשר הימין שולט, והם חסדים ורחמים."],[0,"","וז״ש, \u0003ואתכלילו ב׳ דרועין\u0004 וכו׳ \u0003ג׳ קשרין דימינא אתכלילן בג' קשרין דשמאלא,\u0004 והיינו במוחין דו״ק, שאז נכלל הכל בשמאל והשמאל שולט עם הדינים שלו. וז״ש, \u0003ובג״כ דרועא לא כתיב אלא חד,\u0004 דהיינו זרוע ה׳, \u0003אבל ימינא לא כתיב ביה זרוע.\u0004 כי אינו נקרא זרוע אלא בזמן שליטת השמאל, דהיינו במוחין דו״ק. \u0003ימין ה׳ אתקרי, בג' קשרין דאבהתא, דאחסינו לחולקיהון.\u0004 דהיינו ג׳ מוחין חב״ד, שהם ג״ר דפנים, שהם מתפשטים בחלקם, כי המוחין מתפשטים בכל הגוף."],[1,"ואי תימא הא","וכו׳: ואם תאמר, הרי בג׳ חללי המוח שבגלגלת הם נמצאים, ולא בגוף. כי אין חב״ד אלא בראש. ומשיב, למדנו, כל ג׳ מוחין חב״ד מתפשטים ומתקשרים בכל הגוף, וכל הגוף נקשר באלו שלשה, והם מתקשרים בזרוע הימנית. ומשום זה חמד דוד ואמר, שב לימיני. משום שהוא נתחבר עם האבות, שהם חג״ת שנעשו לחב״ד, ונקשרו בימין, כנ״ל, ודוד יושב שם לכסא שלם. כלומר, שדוד ה״ס מלכות, שהוא רגל לכסא, שחג״ת ה״ס ג׳ רגלי הכסא והוא רביעי להם ומשלים הכסא. ומשום זה כתוב, אבן מאסו הבונים היתה לראש פינה, שזה נאמר על המלכות הנקראת דוד, והוא משום שישב לימין. והיינו שכתוב, ותנוח ותעמוד לגורלך לקץ הימין. והזכיר לו לקץ הימין, כלומר, שהודיעו שהוא כמי שזכה לאהבת המלך, שהמלך מקבל אותו לימין. אשרי חלקו של מי שהושיט לו המלך את ימינו לקבלו תחת ימינו. וימין הזה כשיושב ג׳ הקשרים שלו מתפשטים ומאירים לתחתונים."],[2,"ודרועא לא אושיט","וכו׳: והזרוע, אינו מושיט ידו, בג׳ קשרים שאמרנו, דהיינו במוחין דחב״ד. כי שם שליטת הימין. וע״כ נקרא, ימין ה׳, כנ״ל. וכשמתעוררים רשעים ומתפשטים בעולם, מתעוררים ג׳ קשרים אחרים, שהם דין קשה, ומושיט הזרוע. וכשמושיט הזרוע, הוא יד ימין, אבל נקרא זרוע ה׳, זרועך הנטויה. בזמן שג' קשרים אלו שבימין נכללים בג׳ קשרים האחרים שהם דין קשה, נקרא הכל ימין, ועושה הדין ברחמים. ז״ש, ימינך ה׳ נאדרי בכח ימינך ה׳ תרעץ אויב. משום שמתעוררים בהם, בהדינים, הרחמים."],[2,"","פירוש. כבר ידעת שאין המוחין דחכמה מאירים אלא ביחד עם גילוי דינים על הרשעים הרוצים להמשיך החכמה ממעלה למטה (כנ״ל אות רי״ט). וז״ש, \u0003וכד מתערין חייביא\u0004 וכו' \u0003מתערין ג' אחרנין דאינון דינא קשיא, ואושיט דרועא,\u0004 דהיינו שמושיט הזרוע לדון הרשעים בדינים קשים על שממשיכים החכמה ממעלה למטה, כי לולא הושטת הזרוע לענוש הרשעים אי אפשר שתתגלה החכמה (כמ״ש שם). וז\"ש, \u0003וכד אושיט דרועא,\u0004 לענוש הרשעים, אז מתגלים המוחין דג״ר, \u0003יד ימינא הוא,\u0004 כי גילוי הג״ר הם ג׳ קשרים המתקשרים ביד ימין. \u0003אבל אתקרי זרוע ה׳. זרועך הנטויה,\u0004 כי פעולת גילוי הדינים בשעת הופעת החכמה נבחנת \u0003לזרוע הנטויה\u0004 כמי שנוטה זרוע להעניש את אויביו. אמנם אז מתגלים ג\"ר דפנים, שה״ס ג׳ קשרין דימינא. כי זרוע נקרא, רק מוחין דו״ק, שהם פועלים דינים, וחסד לא נמצא שם כלל, משא״כ כאן במוחין דג״ר עיקר הפועל והשולט הוא החסד, והזרוע אינה פועלת דינים אלא בבחינת זרוע הנטויה, שהיא רק נטויה להעניש הרשעים, כדי לשמור על החכמה, אבל לא בפועל ממש, כי אז שליטת הימין. וז״ש \u0003בזמנא דג׳ אלין,\u0004 דיד ימין, \u0003אתכלילן בג׳ אחרנין,\u0004 דהיינו בעת הופעת החכמה, שצריכים להכלל בזרוע הנטויה, כדי להשמר מחצונים, כנ״ל \u0003אקרי כלא ימינא,\u0004 כי אז מתגלים המוחין דג״ר, \u0003ועביד דינא ברחמי,\u0004 כי גילוי הדין שבזרוע הנטויה, נעשה כדי שיתגלו הרחמים. הה״ד \u0003ימינך ה׳ נאדרי בכח,\u0004 כי הימין מתאזר ע״י הכח של הזרוע הנטויה. \u0003ימינך ה׳ תרעץ אויב,\u0004 ונבחן אשר הימין מרחיק האויבים ומכניעם, ולא השמאל, כי השמאל רק מסייע לשליטת הימין."],[3,"ותאנא בהאי ימינא","וכו׳: ולמדנו, בימין הזה מתאחזים ש״ע אלף רבוא הנקראים ימין, שהם מספר כללות המוחין (כנ״ל אות י״ט) וקפ״ה אלף רבוא מזרוע דאקרי זרוע ה', שה״ס קפיאת האורות שבקו שמאל לרשעים, וקפ״ה ה״ס קפיאת האורות (כנ״ל ב״א דף מ״ז ד\"ה ימא) שזהו ימינא ונקרא זרוע ה׳ כנ״ל בדבור הסמוך. שה״ס ימין ושמאל שהם ימין. מהאי ומהאי תלייא זרועא, שגם הזרוע כלולה מימין ושמאל. והאי והאי נקרא תפארת, שגם הת״ת כלול מימין ושמאל, שכתוב, \u0003מוליך לימין משה,\u0004 הרי ימין. \u0003זרוע,\u0004 הרי שמאל, וכתוב, \u0003זרוע תפארתו,\u0004 הרי שכלולים זה בזה."],[4,"ותאנא בידא שמאלא","וכו׳: ולמדנו, ביד שמאל מתאחזים ת״ן רבוא בעלי מגינים, ומתאחזים בכל אצבע ואצבע. ובכל אצבע ואצבע נמצאים עשרת אלפים בעלי מגינים. צא וחשוב, כמה הם בכל היד. והימין ההוא נקרא עזרה קדושה הבאה מזרוע ימנית מג׳ קשרים שבו. שכתוב, והנה ידי עמך. ומתאחזים מזה, אלף וד׳ רבוא, וח' רבוא וחמש מאות אלף בעלי עזרה בכל העולם. ונקראים יד ה׳ עליונה, ויד ה׳ תחתונה, כי אע״פ שבכל מקום יד ה׳ היא שמאל, אם זכו היא ימין ה׳, שנכללה היד בזרוע ונעשה עזרה ונקרא ימין. ואם לא, יד ה׳ תחתונה, שהיא שמאל. למדנו כשמתעוררים דינים קשים לרדת לעולם, כאן כתוב, סוד ה׳ ליראיו."],[4,"","פירוש. כי יש ב׳ בחינות הארות בשמאל בזמן הארת הג״ר. א) גילוי הדינין שבו בסוד הזרוע הנטויה, שהוא מזמן המוחין דו״ק. והן במספר ת״נ רבוא, כנגד חג״ת נ״ה שבו. וכל מה שבכלל יש ג״כ בפרט בכל אצבע ואצבע. וז״ש, \u0003בידא שמאלא מתאחדן ת״נ רבוא מארי תריסין,\u0004 שהם מגינים על החכמה מפני הרשעים שלא ימשיכו ממעלה למטה, \u0003מתאחדן בכל אצבעא ואצבעא,\u0004 שהכלל מאיר בכל פרט. ובחינה ב) החכמה הנמשכת עם הדינים ההם. שה״ס עשר ספירות שבכל אחת מאירה החכמה, הנקראת אלף. וז״ש, \u0003ובכל אצבעא ואצבעא עשר אלפין מארי תריסין משתכחין.\u0004 שה״ס עשר ספירות דחכמה. כי גילוי חכמה היא בסוד האצבעות (כנ״ל ב״א אות ק״ל)."],[4,"","ויש ב׳ בחינות בימין, בזמן הארת הג״ר, א) שהשמאל משמש לימין, והימין הוא השולט. שאז נקראים שניהם ימין ה'. כנ״ל. ב) שהימין מסייע שיתגלו אורות החכמה שבשמאל, דהיינו שמלביש החכמה בחסדים שלו, כדי שהחכמה תוכל להאיר. ואז נבחן הימין לסיוע ועזרה לשמאל. וז״ש, \u0003וההוא ימינא אקרי סיועא קדישא, דאתי מדרועא ימינא מתלת קשרין\u0004 דהיינו שמסייע להארת החכמה שבשמאל. ואז שאותם חג״ת נ״ה דשמאל, שה״ס ה׳ דינין שהשמאל מעניש הרשעים בעת שהוא במוחין דו״ק, הם נגדלים עתה ע״י העזרה שבימין, ונעשים חמש מאות אלף, שמאות הם חסדים ואלף הוא חכמה, וכשה׳ דינים מתלבשים בחסדים נעשים חמש מאות אלף. ובחינת המוחין דימין עצמו, הם בסוד י״ב בחינות, וחד דכליל לון. דהיינו חו״ב תו״מ שבכל אחד ג׳ קוין ומלכות המקבלת כולם, והיינו ג׳ הויות שבכל אחת ד׳ אותיות, ומלכות המקבלתם. אשר מלכות המקבלתן ה״ס \u0003אלף,\u0004 שבה מתגלה החכמה, וד׳ אותיות הויה האמצעית הן ד׳ רבוא. וז״ש, \u0003ומתאחדן מהאי אלף וארבע רבוא,\u0004 אשר אלף, ה״ס מלכות, וארבע רבוא ה״ס הויה אמצעית, והם שניהם הם סוד הדעת. \u0003ותמניא,\u0004 היינו עוד שמונה רביא, מב' הויות ימין ושמאל, שהם חכמה ובינה. וכל זה הוא במוחין דיד ימין עצמה, שהם חב״ד ומלכות המקבלתם. ונוסף עליהם, \u0003וחמש מאה אלפין,\u0004 שהם ה׳ דינים דיד שמאל, שאחר התלבשותם בהסיועא דחסדים, נעשו לחמש מאה אלף. שהם חכמה וחסדים יחדיו, המכונים מאה אלף, בכל א׳ מה׳ דינים. וז״ש, \u0003כד מתערין דינין קשיין לאחתא בעלמא,\u0004 דהיינו בזמן שזרוע ה׳ מגלה ה׳ דינים שלה להורידם על הרשעים, \u0003כאן, סוד ה׳ ליראיו.\u0004 שכאן, אם הימין מסייע להלבישם בחסדים דג' קשרין שלו, מתגלה בהם \u0003סוד ה',\u0004 שהוא החכמה, \u0003ליראיו,\u0004 לאותם שיראים מפני הדינים ההם, ונזהרים שלא להמשיך החכמה ממעלה למטה."],[5,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא. שכל הדינים הנמצאים מן הדכר, מז״א, קשים בתחילתם ונוחים בסופם. וכל הדינים הנמצאים מן הנוקבא, נוחים בתחילתם וקשים בסופם. ואם לא שהיו נעשים כאחד לא היה העולם יכול לסבול. עד דעתיק דעתיקין הסתום מכל, הפרישם זה מזה, ואח״כ חיבר אותם שיתבשמו יחד."],[5,"","פירוש. כי ידעת, שז״א ה\"ס קו ימין, והנוקבא ה״ס קו שמאל, ונודע שהקו הימיני נמשך מסוד נקודת החולם, שה״ס \u0003י׳\u0004 הנכנסת באור, וז״ש, \u0003דכל דינין דמשתכחין מדכורא, תקיפין ברישא\u0004 דהייני הדינין דמסך דמלכות שנכנסו בבינה. אבל ונייחין בסופא, כי אח״כ מתגלים חסדים על המסך הזה, והדינים נחים. והנוקבא היא נמשכת מקו שמאל, שתחילתו היא יציאת ה \u0003י׳\u0004 מאויר, שנתבטלו הדינין דמסך, אבל לבסוף הם קשים, כי משליטת השמאל נמשכים כל הדינים. וז״ש, \u0003וכל דינין דמשתכחין מנוקבא נייחין ברישא ותקיפין בסופא.\u0004 אמנם שניהם מחוברים יחדיו בקו אמצעי, שהוא ת״ת, (כנ״ל אות ש״ח) וע״כ הדינים דדכורא נחלשים ע״י הנוקבא, שבה יצא ה \u0003י׳\u0004 מאויר. והדינים דנוקבא נחלשים ע״י הדבר, כי נותן אותם לאחוריו, ומבטל את שליטתם בזה. וז״ש, \u0003ואלמלא דאתעבידו כחדא, לא יכלין עלמא למסבל.\u0004 כי ע״י התדבקותם יחד נחלשים הדינים שבהם. ונמשכים הדינים שבהם \u0003עד דעתיק דעתיקי סתימא דכלא, פריש דא מן דא,\u0004 שה״ס הנסירה שנסרם זה מזה, כמ״ש לפנינו, ואח״כ \u0003וחבר לון לאתבסמא כחדא,\u0004 דהיינו שנתחברו פנים בפנים, ונתבשמו כל הדינים שבהם. כמו שנתבאר לפנינו."],[6,"וכד פריש לון","וכו׳: וכשהפריש ביניהם, הפיל תרדמה על ז״א, והפריד הנוקבא מאחורי צדדיו, והתקין אותה בכל התקונים, והצניע אותה ליום שלו, לשבת, להביאה לדכר, לז״א, ז״ש, \u0003ויפל ה׳ אלקים תרדמה על האדם ויישן.\u0004 מהו ויישן היינו שכתוב, עורה למה תישן ה'. \u0003ויקח אחת מצלעותיו.\u0004 מהו אחת. זו היא הנוקבא כש״א אחת היא יונתי תמתי. ועלתה, לאו״א, ונתתקנה. ובמקומה שקועים רחמים וחסד. ז״ש ויסגור בשר תחתנה. וכתוב, והסירותי את לב האבן מבשרכם ונתתי לכם לב בשר."],[6,"","פירוש. שורש הנוקבא, ה״ס המלכות דצמצום ב׳ שסיימה ו״ק דנקודים, דהיינו מלך אחרון אשר שם, שממנו ולמטה היה בי״ע דפרודא, ונבחן אז, שז״א היה בחב״ד חג״ת דכלים ונפש רוח דאורות, ועולם אצילות דנקודים היה מסתיים בנקודת החזה שבת״ת דז״א, דהיינו מחמת המלכות שעלתה במקום בינה של ז״א, שהוא ת״ת וסיימה אור האצילות שלא יתפשט יותר, וכל הכלים שהם ב׳ שלישי התחתונים דת״ת דז״א שמחזה ולמטה, וכל ג׳ ספירות נה״י יצאו מאצילות והיו לבי״ע. (כמ״ש בתע״ס שיעור ט״ז דף א׳ תל״ו ע״ש) וכל מה שבבי״ע לקחה המלכות לרשותה, כי היא שהוציאה אותם לחוץ בעת הקטנות דנקודים, וגם היא שהחזירה אותם לאצילות בעת הגדלות שמקודם שבירת הכלים, כי אז ירד הצמצום של המלכות מבינה דז״א שהוא ת״ת, אל מקומה בנקודה דעוה״ז, ובי״ע שהם תנה״י דז\"א שיצאו ממדרגת ז״א למתחת המלכות המסיימת, חזרו שוב לבחינת ז״א דאצילות. ומתוך שאין העדר ברוחני נבחן שגם המלכות המסיימת נשארת גם עתה במקום החזה דז״א, אלא רק כח הצמצום שבה ירד לנקודה דעוה״ז, ואותם בי״ע שהיו מקודם לכן בעת קטנות תחת רשותה, נתחברו עתה אליה לבחינת אצילות, ונעשו לט׳ ספירות תחתונות שלה. כי נקודה המסיימת שבחזה דז״א נעשתה לכתר, ותנה״י דז״א נעשו לחו״ב וחג״ת נהי״מ שלה. באפן שבעת גדלות נקודים קודם השבירה, נעשו מבי״ע שחזרו לאצילות, ב׳ מדרגות, אחת שחזרו לבחינת תנה״י דז״א, כמו שהיו מטרם צמצום ב'. ואחת, שנבנה מהם כל פרצוף המלכות דז״א, ונעשו מאותם תנה״י דז\"א, ט״ס חו״ב חג״ת נהי״מ שלה. ומכאן, בעולם התקון, כל אימת שז״א מברר נה״י שלו וקונה נה״י חדשים דכלים, שה״ס ג\"ר דאורות, באותו זמן משגת גם הנוקבא ט״ס חו״ב חג״ת נהי״מ דכלים. ונבנית לפרצוף שלם של ע״ס. וכן אם חטאים התחתונים גורמים חזרת ז״א לבחינת ו״ק ומתבטלים נה\"י החדשים שנבררו לו מבי״ע, הנה באותה העת מתבטלים ג״כ ט\"ס תחתונות דמלכות, כי שורש אחד לשניהם. וע״כ דברנו מנוקבא הנפרדת דז״א, ששורשה היא מלכות המסיימת דנקודים. והיא אינה בחינת שמאל דז״א, אלא מלכות המסיימתו לגמרי. ונקראת מלכות הנפרדת מז״א, כלומר שהיא מדרגה אחרת שמתחת ז״א, ומקבלת ממנו כל ט״ס חו״ב חג\"ת נהי״מ שלה, דהיינו מבחינת תנהי\"מ שלו כמבואר. ושורשה הקבוע בז״א ה״ס נקודת החזה שלו מבחינת הכלים כנ״ל. ומבחינת האורות, שהם רק נפש רוח, דהיינו חג״ת נה״י, נבחנת שורש המלכות הקבוע בז״א בנקודה תחת היסוד שלו. וב' יחסים אלו הם רק מטעם ערך ההפכי בין כלים לאורות, אבל הן נקודה אחת, שהיא נקודת הסיום דו״ק שלו. ע״ד שהיו בנקודים בעת הקטנות."],[6,"","ויש גם כן נוקבא שבגופו דז״א, ואינה נפרדת ממנו לעולם, והוא צד השמאל שלו, כי הדעת כלול מימין ושמאל, מטעם שמכריע ב׳ הקוין ימין ושמאל, הנה הימין שבו הוא ז״א עצמו, והשמאל שבו היא המלכות הנקראת נוקבא שבגופו. וכן בת״ת וכן ביסוד. כי הקו האמצעי בכל מקום שהוא, כולל בתוכו ימין ושמאל, אשר הימין הוא ז״א, והשמאל הוא נוקבא שבגופו, ושניהם הם מדרגה אחת וקומתם שוה, וכל מה שאמרנו בנוקבא הנפרדת, אינו נוהג בנוקבא זו שבגופו."],[6,"","ובתחילת התקון של הנוקבא הנפרדת, חיבר אותה המאציל עם נוקבא שבגופו דז״א, וז״ש (לעיל אות ש״ז) \u0003אתפשט האי תפארת מטבורא דלבא,\u0004 דהיינו מבחינת נקב החזה, שנקראת טבורא דלבא, ששם מלכות הנפרדת דז״א, העומדת בפנים דז״א. \u0003ונקיב ואתעבר בגיסא אחרא,\u0004 שעשה אותה בית קבול והעביר אותה לצד האחר, דהיינו לצד האחור דז״א. שהיא נעשתה בזה, לבחינת שמאל שלו, הנקראת נוקבא שבגופו. ובזה ערב נוקבא הנפרדת בנוקבא שבגופו, ונעשו שתיהן לנוקבא אחת. שמקום מצבה אינה עוד בנקב החזה, שה״ס נקב הפנים שבז״א, אלא בקו האמצעי בנקב האחור, שהיא עירוב של בחינת נוקבא שבגופו עם נוקבא הנפרדת. ובמצב הזה יצאו נפש רוח דנפש דנוקבא בכלים דחב״ד חג״ת עד החזה, וז״ש \u0003ותקין פרצופא דנוקבא עד טבורא,\u0004 דהיינו עד החזה שלה מבחינת נפש."],[6,"","ואח״כ כשיצאו ג\"ר דנשמה דז״א, עם נה״י חדשים דכלים, אז כלולים בנה״י אלו, ט\"ס תחתונות דבחינת אור הרוח של הנוקבא, ונבנו כל ע״ס דרוח דנוקבא, דהיינו גם המוחין דרוח, שה״ס מוחין דשמאל, דהיינו שקבלה אור החכמה הנמשכת בקו שמאל."],[6,"","ואם הנוקבא לא היתה עוברת לצד האחור להתאחד עם נוקבא שבגופו דז״א, אלא היתה עומדת במקומה בנקודת נקב החזה בצד הפנים של ז״א, היה יוצא, שבעת שיצאו לנוקבא המוחין דשמאל, שהם ג״ר דרוח, היתה מקבלת אותם מז״א, ככל מדרגה תחתונה המקבלת מעליונה, ומכל שכן שט\"ס שלה באים מתנה״י החדשים דז״א. ואז היה השמאל ממותק בחסדים, כי ז״א ה״ס קו אמצעי, שימין ושמאל מיוחדים בו. ואז היתה הנוקבא יכולה לקבלם. משא״כ, עתה שעומדת בצד האחור דז״א, שפירושו, שנתערבה יחד עם הנוקבא שבגופו, כנ״ל, נמצא בעת שיצאו המוחין מקו שמאל מאמא, לקחה אותם הנוקבא הנפרדת ישר מקו שמאל דאמא, כמו הנוקבא שבגופו דז״א, ונעשו בזה לדו פרצופין, שפרצוף ז״א כולו ימין, שמקבל רק מקו ימין דאמא, ופרצוף נוקבא הנפרדת שנתדבקה בו באחור, הוא כולו שמאל, כי לוקח רק קו שמאל מאמא, כמו הנוקבא שבגופו. והבן היטב כי נוקבא שבגופו דז״א לפי עצמה, אע״פ שמקבלת מאמא, שמאל בלבד, אין זה פוגע כלום בתקון קו אמצעי, כי אדרבא, שכל צד שמאל שלו בא לו מחמת שהוא מיחד קו ימין וקו שמאל באמא, שמתוך כך יש לו עצמו ג״כ ימין ושמאל, בסוד תלת נפקי מחד, חד בתלת קיימא (כנ״ל ב״א דף רפ״ז ד״ה תלת). הרי שהנוקבא שבגופו שהיא צד השמאל, כבר ממותקת יפה יפה בימין, ואין בה שום דין. שהרי אפילו הזרוע השמאלית דז״א נקראת ג״כ ימין ה׳ (כנ״ל אות ש״כ). משא״כ נוקבא הנפרדת שקבלה עתה מוחין דשמאל מחדש, מחמת שנעשתה כנוקבא שבגופו, הנה מוחין אלו עוד לא קבלו שום מיתוק מחסדים דקו אמצעי, כי עוד לא הגיעו אליו כלל, אלא הגיעו ישר מקו שמאל דאמא אל הנוקבא הנפרדת הדבוקה באחור. וכיון שאין בה היחוד דקו אמצעי, היא נמצאת בבחינת שמאל בלי ימין, שהם דינים קשים, ולא היתה יכולה לעמוד בהם."],[6,"","והנה כל התקון שצריכים כאן אינו, אלא להפריד הנוקבא מבחינת אחורי ז״א, ולהחזירה לבחינת פנים דז״א, דהיינו במקום נקב החזה דז״א. כדי שכל מה שתקבל לא תקבל אלא מז״א, שה״ס קו האמצעי, ואז יהיו לה חכמה וחסדים יחדיו, שהם כל השלמות."],[6,"","וזהו שמבאר כאן, איך הפריד הנוקבא מאחורי ז״א, והשיבה לבחינת פנים. וז\"ש, \u0003וכד פריש לון,\u0004 כשהפריד ז\"א ונוקבא מדביקות של אחורים, \u0003אפיל דורמיטא לז\"א,\u0004 דהיינו שנסתלקו ממנו המוחין דנשמה, שה״ס חכמה וחסדים, שז״א נאחז בהם, והשאיר בו רק צד השמאל של המוחין, שהם בינה וגבורה אשר הנוקבא נאחזה בהם. שמוחין אלו הם שינה. וסתימת עינים, מפני שהחכמה שה״ס עינים נסתמים מחמת שאינם יכולים להאיר בלי חסדים. שזסו״ה ויפל ה׳ אלקים תרדמה על האדם ויישן. \u0003ופריש לנוקבא מאחורוי דסטרוי,\u0004 דהיינו שהמאציל עורר את המסך בסוד החזרת הי׳ לאור, ונסתלקו המוחין דאחור של הנוקבא, שהסתלקות זו של המוחין דאחור, נבחנת ללקיחת הצלע מן הז״א, כי נתבטלה הארתה, ואז חזרה לבחינת נקודת החזה, כמו שהיתה מטרם העברתה לאחורי ז״א. שזסו״ה \u0003ויקח אחת מצלעותיו,\u0004 ואח״כ עלו ז״א ונוקבא לאו״א, שז״ס ויבן ה׳ אלקים, שהם או״א, את הצלע, דהיינו הנוקבא, שהם המשיכו מוחין חדשים לזי׳א ונה״י חדשים שמהם מוחין דנוקבא חדשים. וז״ש, \u0003ואתקין לה כל תקונהא,\u0004 דהיינו כל המוחין. \u0003ואצנעא ליומא דיליה,\u0004 דהיינו שהכין אותה לזווג ביום השבת שאז יש לזו״ן מוחין דחיה, הראוים להולדה."],[7,"ובשעתא דבעא למיעל","וכו׳: ובשעה שהשבת רצתה להכנס, דהיינו בין השמשות, היה בורא רוחות ושדים וסערות, שהם מזיקי עולם, ומטרם שגמרם, באה המלכה בכל התקונים שלה מן השבת, וישבה לפניו. כי ביום הזה משגת ג״ר דחיה המכניעות ומבטלות כל המזיקים והסטרא אחרא, שאין אז ממשלה בעולם חוץ ממנה. בשעה שישבה לפניו הניח אלו הבריות ולא נשלמו. כי מאחר שהמלכה יושבת עם המלך ונתחברו פנים בפנים, מי יכנס ביניהם ומי הוא שיקרב אליהם. (ועי׳ לעיל בהקסה״ז דף קצ״א ד״ה וכי) וכשנתחברו, נתבשמו זה בזה, משום שהשבת הוא יום שהכל נתבשם בו. ומשום זה נתבשמו הדינין אלו באלו, כי דינין דדכורא התקיפין ברישא מתבשמין ברישא דנוקבא. ששם נייחין הדינים. ודינין דנוקבא התקיפין בסיפא מתבשמין בסיפא דדכורא ששם הדינין נייחין (כנ״ל אות שכ״ג). ונתקנו העליונים והתחתונים."]],[]],[["וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, בָּעָא עַתִּיקָא קַדִּישָׁא לְמֵחֱזֵי, אִי אִתְבְּסָמוּ דִּינִין, וְאִתְדְּבָקוּ תְּרֵין אִלֵּין דָּא בְּדָא, וְנָפַק מִסִּטְרָא דְּנוּקְבָּא דִּינָא תַּקִּיפָא, (דלא יכיל עלמא למסבל) דִּכְתִּיב, (בראשית ד׳:א׳) וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן וַתֹּאמֶר קָנִיתִי וְגוֹ'. וְלָא הֲוָה יָכִיל עָלְמָא לְמִסְבַּל, מִשּׁוּם דְּלָא אִתְבַּסְּמַת, וְחִוְיָא תַּקִּיפָא אַטִּיל בָּה זוּהֲמָא דְּדִינָא קַשְׁיָא, וּבְגִין כָּךְ לָא הֲוָה יָכִיל לְאִתְבַּסְּמָא. וְכַד נָפִיק דָּא קַיִן מִסְּטַר דְּנוּקְבָּא, נָפַק תַּקִּיף קַשְׁיָא, תַּקִּיף בְּדִינוֹי, קַשְׁיָא בְּדִינוֹי. כֵּיוָן דְּנָפַק אִתְחֲלָשָׁת וְאִתְבַּסְּמַת. בָּתַר דָּא, אַפִּיקַת אַחֲרָא בְּסִימָא יַתִּיר, וְסָלִיק קַדְמָאָה דְּהֲוָה תַּקִּיפָא קַשְׁיָא, וְכָל דִּינִין לָא אִתְעָרְבוּ (ס\"א אתערעו) קָמֵיהּ (ס\"א וכל דינין (לא) אתערו) עִמֵּיהּ.","תָּא חֲזֵי, מַה כְּתִיב, (בראשית ד׳:ח׳) וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה. בַּשָּׂדֶה: דְּאִשְׁתְּמוֹדַע לְעֵילָּא. בַּשָּׂדֶה דְּאִקְרֵי שָׂדֶה דְּתַפּוּחִים. וְנָצַח הַאי דִּינָא לַאֲחוּה, מִשּׁוּם דְּהֲוָה קַשְׁיָא מִנֵּיהּ, וְאַכְפְּיֵיהּ וְאַטְמְרֵיהּ תְּחוֹתֵיהּ. עַד דְּאִתְּעַר בְּהַאי קוּדְשָׁא בְּרִיךְ הוּא, וְאַעְבְּרֵיהּ מִקַּמֵּיהּ. וְשַׁקְעֵיהּ בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא. וְכָלִיל לַאֲחוּי בְּשִׁקּוּעָא דְּיַמָּא רַבָּא, דִּמְבַסֵּם דִּמְעִין עִלָּאִין. וּמִנְּהוֹן נַחְתִין נִשְׁמָתִין לְעָלְמָא, אֱינָשׁ לְפוּם אוֹרְחוֹי.","וְאַף עַל גַּב דִּטְמִירִין אִינּוּן. מִתְפַּשְּׁטִין דָּא בְּדָא, וְאִתְעֲבִידוּ גּוּפָא חַד וּמֵהַאי גּוּפָא, נַחְתִּין נִשְׁמָתְהוֹן דְּרַשִׁיעַיָּיא חַיָּיבַיָּא, תַּקִיפֵי רוּחָא. מִתַּרְוִויהוֹן כַּחֲדָא סַלְּקָא דַּעְתָּךְ. אֶלָּא דָּא לְסִטְרוֹי, וְדָא לְסִטְרוֹי. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דִּמְשַׁלְפֵי נִשְׁמָתְהוֹן מֵהַאי גּוּפָא קַדִּישָׁא דְּאִקְרֵי אָדָם, דְּכָלִיל כֹּלָּא, אֲתָר דְּעִטְרִין וְכִתְרִין קַדִּישִׁין מִתְחַבְּרָאן תַּמָּן, בִּצְרוֹרָא דְּאַתְקְלָא (ס\"א דאתכלא).","זַכָּאִין אִינּוּן צַדִּיקַיָּיא, (ס\"א אתון חברייא) דְּכָל הָנֵי מִלִּין קַדִּישִׁין, דְּאִתְמָרוּ בְּרוּחַ קַדִּישָׁא עִלָּאָה, רוּחַ דְּכָל קַדִּישִׁין עִלָּאִין אִתְכַּלְּלָן בֵּיהּ, אִתְגַּלְיָין לְכוּ. מִלִּין דְּעִלָּאִין וְתַתָּאִין צַיְיתִין לְהוּ, זַכָּאִין אַתּוּן מָארֵיהוֹן דְּמָארִין, מְחַצְדֵּי חַקְלָא, דְּמִלִּין אִלֵּין תִּנְדְּעוּן וְתִסְתַּכְּלוּן בְּהוּ, וְתִנְדְּעוּן לְמָארֵיכוֹן אַפִּין בְּאַפִּין, עֵינָא בְּעֵינָא. וּבְהָנֵי מִלִּין תִּזְכּוּן לְעָלְמָא דְּאָתֵי, הֲדָא הוּא דִכְתִיב, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ וְגוֹ'. יְיָ: עַתִּיק יוֹמִין הוּא הָאֱלֹהִים. וְכֹלָּא הוּא חַד, בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא.","אָמַר רַבִּי שִׁמְעוֹן, חֲמֵינָא עִלָּאִין לְתַתָּא, וְתַתָּאִין לְעֵילָּא. עִלָּאִין לְתַתָּא, דִּיּוּקְנָא דְּאָדָם, דְּהוּא תִּקּוּנֵי עִלָּאָה, כְּלָלָא דְּכֻלְּהוּ. (חסר)","תָּאנָא, כְּתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, דְּכָלִיל שִׁית בְּקַרְטוּפָא כַּחֲדָא. וְהַאי הוּא דִּכְתִּיב, (שיר השירים ה׳:ט״ו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, בָּאָדָם אִתְכְּלִילוּ כִּתְרִין עִלָּאִין, בִּכְלַל וּבִפְרַט. וּבְאָדָם אִתְכְּלִילוּ כִּתְרִין תַּתָּאִין, בִּפְרָט וּכְלָל. כִּתְרִין עִלָּאִין בִּכְלַל, כְּמָה דְּאִתְּמַר בְּדִיּוּקְנָא דְּכָל הָנֵי תִּיקּוּנִין (ס\"א דיוקנין). בִּפְרָט: בְּאֶצְבְּעָן דִּיְדִן, חָמֵשׁ כְּנֶגֶד חָמֵשׁ. כִּתְרִין תַּתָּאִין, בְּאֶצְבְּעִין דְּרַגְלִין דְּאִינּוּן פְּרָט וּכְלָל. דְּהָא גּוּפָא לָא אִתְחֲזֵי בַּהֲדַיְיהוּ. דְּאִינּוּן לְבַר מִגּוּפָא. וּבְגִין כָּךְ לָא הֲווֹ בְּגוּפָא. דְּגוּפָא אַעְדִּיוּ מִנַּיְיהוּ.","אִי הָכִי, מַאי (זכריה י״ד:ד׳) וְעָמְדוּ רַגְלָיו בַּיוֹם הַהוּא. אֶלָּא רַגְלָיו דְּגוּפָא, מָארֵיהוֹן דְּדִינִין (ס\"א דמארין) לְמֶעְבַּד נוּקְמִין וְאִקְרוּן בַּעֲלֵי רַגְלַיִם. וּמִנְּהוֹן תַּקִּיפִין. וּמִתְאַחֲדָן מָארֵיהוֹן דְּדִינִין דִּי לְתַתָּא, בְּכִתְרִין תַּתָּאִין.","תָּאנָא, כָּל אִינּוּן תִּקּוּנֵי דִּלְעֵילָּא, דִּבְגוּפָא קַדִּישָׁא, (בדכר ונוקבא) כְּלָלָא דְּאָדָם, אִתְמְשִׁיךְ דָּא מִן דָּא, וּמִתְאַחֲדָן דָּא בְּדָא, וְאַשְׁקוּן דָּא לְדָא. כְּמָה דְּאִתְמְשָׁךְ דָּמָא בְּקִטְפִין דְּוָרִידִין לְדָא וּלְדָא, לְהָכָא וּלְהָכָא, מֵאֲתָר דָּא לְאֲתָר אַחֲרָא, וְאִינּוּן מַשְׁקִין (ס\"א קסטין) דְּגוּפָא (נ\"א לגופא). אַשְׁקְיָין דָּא לְדָא, מְנַהֲרִין דָּא לְדָא. עַד דְּאַנְהִירוּ כֻּלְּהוּ עָלְמִין, וּמִתְבָּרְכָאן בְּגִינֵיהוֹן."],[[0,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא. עתיקא קדישא רצה לראות אם הדינים נתבשמו, נתדבקו ב׳ אלו, אדם וחוה, זה בזה, ויצא מצד הנוקבא דין קשה. שכתוב, והאדם ידע את חוה אשתו ותהר ותלד את קין ותאמר קניתי וגו׳. כי העולם לא היה יכול לסבול, משום שחוה עוד לא נתבשמה והנחש הקשה הטיל בה זוהמא של דין קשה, ומשום זה לא היתה יכולה להתבשם. וכשיצא קין זה מצד הנוקבא, יצא חזק וקשה, חזק בדיניו, קשה בדיניו. כיון שקין יצא ממנה, נחלשה ונתבשמה. אחר זה ילדה נשמה אחרת שהיא ממותקת יותר, ועלה עליו הראשון, קין, שהוא יותר חזק, שכל הדינים נתחברו עמו."],[0,"","פירוש. אחר שביאר אצילות הנוקבא, והנסירה, והזווג השלם דפנים בפנים שביום השבת, מבאר עתה, ענין הזווג דחול, שהיה אחר אכילת עצה״ד. שזווג הזה היה כבר אחר הנסירה, בהיות זו\"ן פנים בפנים, אלא קודם יום השבת. והנה ע״י החטא דעץ הדעת, שפירושו התעוררות המשכת החכמה ממעלה למטה, כרצון הנחש וכל הקליפות, גרם למעלה סוד ביאת נחש על חוה. כלומר שהקליפה הנקראת הנחש העליון, קבלה כח ע״י חטא התחתונים בעץ הדעת, להתדבק בנוקבא כדי להמשיך ממנה החכמה ממעלה למטה, כמו שהיתה לפני הנסירה, ובזה עורר כח השמאל והאחור של הנוקבא, והטיל זוהמא בנשמות הכלולות בנוקבא, שזוהמא זו פירושו, שהטיל עליהן שליטת השמאל, שלא תרצנה להכלל בימין."],[0,"","וע״כ נבחן זווג הזה (כמ\"ש לעיל בראשית א׳ אות תנ״ה) שאומר שם, \u0003תרין אתו עלה דחוה,\u0004 כי מצד אחד נתדבקה הנוקבא עם ז״א שהוא קו אמצעי, המתקן את החכמה, שלא תאיר אלא ממטה למעלה, (כנ״ל ב״א דף ס׳ ד\"ה מחלוקת) שעי״ז מיחד ב׳ הקוין ומלביש החכמה בחסדים. ומצד הב׳ נתדבק בה הנחש, המעורר המשכת ג\"ר דשמאל, דהיינו ממעלה למטה, ולהפרידה מן הימין שהוא חסדים, בהתנגדות לקו האמצעי, וז״ש שם, \u0003ואולידת תרין, דא נפק לזיניה ודא נפק לזיניה,\u0004 וכו'. שהולידה ב׳ נשמות קין והבל, שקין נולד מזוהמת הנחש, והבל נולד מחסדים דז״א."],[0,"","וז״ש כאן, \u0003בעא עתיקא קדישא למחזי אי אתבסמו דינין,\u0004 דהיינו אחר חטא של עצה״ד, רצה המאציל לראות אם הדינים שבנוקבא נתבשמו בז״א, כלומר, שרצה לראות אם החטא דעצה״ד לא פגם בדינים דנוקבא. \u0003ואתדבקו תרין אלין דא בדא,\u0004 דהיינו שעורר את ז״א ונוקביה, שיתחברו זה עם זה. \u0003ונפק מסטרא דנוקבא דינא תקיפא,\u0004 כי זוהמת הנחש התגברה על הנשמה, ויצאה הנשמה כולה מבחינת הנוקבא וזוהמא דחויא, דהיינו מבחינת מלמעלה למטה של החכמה, שהוא דין קשה, שאין רצונו להתחבר עם הימין. \u0003הה״ד והאדם\u0004 וגו׳ \u0003ותהר ותלד את קין,\u0004 ולא היה העולם יכול לסבול משום שהנוקבא לא נתבשמה בז״א, אלא שהולידו בשליטת השמאל בלבד. ומהו הטעם שלא נתבשמה בז״א, הרי נתחברה עמו. הוא משום, \u0003וחויא תקיפא אטיל בה זוהמא דדינא קשיא,\u0004 שבסבת חטא התחתונים בעצה״ד קבל הנחש כח להטיל זוהמא בנשמות, כמ״ש לעיל. \u0003ובג״כ לא הוה יכיל לאתבסמא\u0004 כי הטיל בה כח שליטת השמאל על הימין שנקרא זוהמא כנ״ל. \u0003כיון דנפק,\u0004 אחר שיצא ממנה קין, שהוא זוהמת הנחש ושליטת השמאל, \u0003אתחלשת ואתבסמת\u0004 נחלשה כח השמאל שבה, ונתחברה ונתבשמה בימין, בז״א. \u0003בתר דא, אפיקת אחרא בסימא יתיר,\u0004 דהיינו נשמת הבל, שהוא יצא מז״א מן החסדים."],[1,"ת״ח מה כתיב","וכו׳: בוא וראה מה כתוב, ויהי בהיותם בשדה, היינו בשדה הנודע שלמעלה, בשדה שנקרא שדה תפוחים, דהיינו המלכות. שמשם נולדו. ונצח הדין הזה דקין את אחיו, משום שהיה קשה ממנו, והכניעו והסתירו תחתיו. עד שהקב״ה נתעורר על זה והעביר את קין מפניו, והשקיעו בנקב של התהום הגדול. והוא כולל את אחיו בשקיעה של הים הגדול המבשם דמעות העליונות. ומהם יורדות נשמות לעולם, לכל איש לפי דרכו."],[1,"","פירוש. לפי המתבאר שקין והבל הם שמאל וימין שבמלכות, א״כ צריכים לדעת איך יתבארו ענין הריגת קין להבל ושאר הכתובים באותו ענין. וז\"ש, \u0003ויהי בהיותם בשדה,\u0004 וכו' \u0003בשדה דאקרי שדה תפוחים,\u0004 דהיינו למעלה במלכות. והיו ביניהם מחלוקת כדרך ימין ושמאל (כנ״ל ב״א דף נ״ז ד\"ה וזה) \u0003ונצח האי דינא לאחוה,\u0004 שהשמאל שהוא קין נצח את הימין שהוא הבל. אבל יש לשאול, הלא בכל מקום שהימין והשמאל נלחמים זה בזה, פעם מתגבר הימין ופעם מתגבר השמאל, כמ״ש לעיל בסו\"ה יעלו שמים ירדו תהומות, כי כשהשמאל נוצח אז \u0003יעלו שמים,\u0004 שמושך ג\"ר. שה״ס גלי הים, וכשהימין נוצח, אז \u0003ירדו תהומות,\u0004 שגלי הים שעלו עד השמים שיאם בכח השמאל שהשיגו ג\"ר דשמאל, חוזרים ונופלים לנקבי תהומות, שחוזרים ואובדים הג״ר שלהם ונופלים לו\"ק שהיא \u0003נוקבא דתהומא רבא,\u0004 ששם עלתה המלכות לבינה ונתמעטה מג\"ר. כמ״ש זה לעיל באורך (באות רי״ד ע״ש כל ההמשך) וא״כ למה נאמר כאן שקין הרג את הבל, שמשמע שהשמאל ניצח את הימין. וז״ש, \u0003ונצח האי דינא לאחוה משום דהוה קשיא מניה,\u0004 כי כאן משונה, משום שקין היה דין קשה ביותר ששלטה עליו זוהמא דחויא, כנ״ל, וע״כ התגבר על הימין, שהוא הבל, \u0003ואכפייה ואטמריה תחותיה,\u0004 שהכניעו והסתירו, שלא תהיה ניכרת מציאותו. כי למעלה ברוחניות לא שייך הריגה באפן אחר."],[1,"","ונמשך שליטתו דקין, \u0003עד דאתער בהאי, קב\"ה,\u0004 דהיינו עד שנתעורר הקו האמצעי, שה״ס קב״ה, \u0003ואעבריה מקמיה, ושקעיה בנוקבא דההומא רבא,\u0004 דהיינו שהעביר ממנו הג״ר, והשקיע אותו בו״ק בלי ג\"ר ע״י שהפילו בנקב התהום הגדול, שה״ס המסך דחירק מבחינת מלכות שעלתה לבינה, כמ״ש לעיל בסוד ירדו תהומות, (וכמ״ש באות רי״ד) כי כן דרכו של הקו האמצעי, למעט הג״ר דשמאל ע״י מסך דחירק, ואז נכנע להכלל עם הימין (כנ״ל לך דף י״ג ד״ה ונתבאר) וז״ש, \u0003וכליל לאחוי בשקועא דימא רבא,\u0004 כי עתה שנתמעט ונפל לשקוע דים הגדול, דהיינו לבחינת ו\"ק, אז הוא נכלל עם אחיו, עם הימין. והיינו רק בזמן, \u0003דמבסם דמעין עלאין.\u0004 דהיינו כנ״ל (אות רכ״ב) שתחילה מוציא את האבן מתוך נקב התהום, דהיינו שמוריד המלכות מן הבינה, ומתגלות שוב הג״ר דשמאל, ואז מתחדשת המחלוקת דימין ושמאל, ויוצאים סומקא ואוכמא, שה״ס הדינים שבקו שמאל (כמ״ש לעיל אות רי״ד ע״ש) והם נקראים ב׳ דמעות (כנ\"ל אות רכ״ב) וכשהקב״ה שהוא קו האמצעי ממשיך הלבן שה״ס החסדים, אז נופלים הדמעות לתוך ים החכמה ומתנשמות כי נכללים בימין. וז\"ש \u0003וכליל לאחוי בשקועא דימא רבא, דמבסם דמעין עלאין.\u0004 כלומר בעת שהים מבשם ב׳ הדמעות עם החסדים, אז נכלל קין עם אחיו הבל, שה״ס ימין. ואחר שנכללו, \u0003מנהון נחתין נשמתין לעלמא,\u0004 יורדות מהם נשמות לעולם \u0003אינש לפום ארחוי,\u0004 אם מעשיו הם בבחינת הימין, ממשיך נשמה מהבל. ואם מעשיו הם בבחינת השמאל, הוא ממשיך נשמה מקין."],[2,"ואע\"ג דטמירין אינון","וכו׳: חוזר למטרם שנכללו זה עם זה, שאז היו מכוסים, כי קין אכפייה \u0003ואטמריה\u0004 להבל קמיה, וכן קין היה טמיר, שנאמר ומפניך אסתר. ואומר, אע״פ שהיו נסתרים, התפשטו זה בזה, ונעשו גוף אחד, והיינו בשליטתו של קין, ומהגוף הזה, יורדות נשמות הרשעים החטאים אמיצי רוח. משום שהוא בשליטתו של קין. שואל, וכי משניהם ביחד יורדות נשמות, הלא המה ב׳ קצוות. ומשיב, אלא זה אל הצד שלו וזה אל הצד שלו. כלומר שמקין נמשכות נשמות רשעים הדבקים בפסולת השמאל, ומהבל נמשכות נשמות לרשעים הדבקים בפסולת הימין. וכל זה מטרם שנכללו זה עם זה בשקיעא דימא ובא דמבסם דמעות עלאין. אבל אחר שנמתקו, נמשכות מהם נשמות צדיקים, שאינם כל כך צדיקים (כנ״ל ב״א אות תנ״ו) אשרי הם הצדיקים שנשמותיהם נמשכות מהגוף הזה הקדוש שנקרא אדם, הכולל הכל, שהוא מקום, שהעמדות שה״ס הג״ר והספירות הקדושות מתחברות יחד. בצרור האשכול. כלומר, שכל הספירות הג״ר והו\"ק, הימין והשמאל הכל כלולים בו יחד."],[3,"זכאין אינון צדיקיא","וכו׳: אשרי הם הצדיקים שכל אלו הדברים הקדושים הנאמרים ברוח הקודש העליון, רוח, שכל קדושים העליונים נכללו בו, נתגלו לכם. שהם דברים שעליונים ותחתונים מקשיבים להם. אשרי לכם מארי מדין, דהיינו היושבים על כסא מדין, קוצרי השדה, אשר תדעו דברים אלו ותסתכלו בהם, ותדעו את אדוניכם פנים בפנים, עין בעין. ובדברים אלו תזכו לעולם הבא. ז״ש, וידעת היום והשבות אל לבבך וגו׳. הויה, שהוא עתיק יומין, הוא האלקים. שהוא ז״א, והכל הוא אחד, ברוך שמו לעולם ולעלמי עולמים."],[4,"אמר ר״ש חמינא","וכו׳: אר״ש אני רואה עליונים למטה ותחתונים למעלה. עליונים למטה ותחתונים למעלה, הוא צורת אדם, שהוא תקון עליון, כלל כולם."],[4,"","פירוש. כי תקון אדם, שה״ס הקו האמצעי, מיעט הג״ר דשמאל שהם עליונים, ונתנם למטה, כלומר שאין בהם חפץ. ואת הדינים שיצאו בעת הארת הג״ר דשמאל, שהם היו \u0003למטה\u0004 משמאל, הגביה אותם \u0003למעלה,\u0004 כלומר, שאין הארת חכמה זולת בגילוי דינים ההם (כנ״ל אות רי״ט) הרי שמתקון אדם נמשך שיהיו העליונים למטה ותחתונים למעלה."],[5,"תאנא כתיב וצדיק","וכו׳: למדנו, כתוב, וצדיק יסוד עולם. שכולל ששה במקור אחד. וזהו שכתוב, שוקיו עמודי שש."],[5,"","פירוש. כי כל שוק יש בו ג׳ קשרים, כמ״ש לעיל (אות שי״ח) אצל הזרועות, ע״ש, וב' שוקים הם ששה קשרים. וכיון שהיסוד כולל בתוכו נצח והוד, שהם ב׳ שוקים, נמצא שהיסוד כולל ששה קשרים כאחד. וז״ש וצדיק יסוד עולם דכליל שית בקרטופא כחדא. דהיינו ששה קשרים שבנצח והוד שהם ב׳ שוקים, \u0003והאי הוא דכתיב, שוקיו עמודי שש,\u0004 כלומר שבב׳ שוקים יש שש, ג׳ בכל אחד. והיסוד כולל כולם."],[6,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא, באדם נכללו ספירות העליונות שמחזה ולמעלה, בכלל ובפרט, ובאדם נכללו ספירות התחתונות, דהיינו שמחזה ולמטה, בפרט וכלל. ומפרש, ספירות עליונות בכלל, הוא כמו שלמדנו, בצורה של כל הצורות, שהיא צורת אדם. בפרט, היינו באצבעות הידים, שהם חמש כנגד חמש. ספירות התחתונות, באצבעות הרגלים הם פרט וכלל, כי הגוף שהוא ת״ת, אינו נראה עמהם, כי הם לחוץ מגוף. ומשום זה אינם בגוף, כי הגוף הוסר מהם."],[6,"","פירוש. ב׳ קוין ימין ושמאל הם \u0003פרט,\u0004 שהם ב׳ קצוות רחוקים זה מזה. וקו אמצעי הוא \u0003כלל,\u0004 שהוא כולל בתוכו ב׳ הקצוות יחד. וכלל קודם לפרט, פירושו, שתחילה נאצל הכלל, הקו האמצעי, ואח״כ נתחלקו מהקו האמצעי ב׳ הפרטים. וזהו בספירות עליונות מחזה ולמעלה דז״א, שתחילה יצא הת״ת, שהוא גוף וקו אמצעי, ומן הת״ת נתפצלו ב' זרועות, שהם הפרט. שהוא מטעם, כי מכח שהת״ת עלה והכריע בין ב׳ קוין דבינה, הרויח הוא עצמו ג׳ קוין (כנ\"ל ב״א דף רפ״ז ד״ה תלת) ע״כ נבחן שב׳ קוין חסד וגבורה נתפצלו ממנו."],[6,"","וז״ש, \u0003באדם אתכלילו כתרין עלאין\u0004 שהם חג״ת שלמעלה מחזה, \u0003בכלל ובפרט,\u0004 שתחילה יצא הת״ת הנקרא גוף, ואח״כ הידים עם ה׳ אצבעות, שהם, חסד וגבורה, ימין ושמאל, וז״ש, \u0003כתרין עלאין בכלל, כמה דאתמר בדיוקנא דכל הני דיוקנין,\u0004 שהוא ת״ת הקו האמצעי הנקרא אדם הכולל כל הצורות. והקו אמצעי נקרא, כלל. \u0003בפרט, באצבען דידין חמש כנגד חמש,\u0004 דהיינו המש אצבעות דימין שהם כנגד חמש דשמאל נבחנים לפרט. וז״ש, \u0003ובאדם אתכלילו כתרין תתאין,\u0004 דהיינו נה״י שמחזה ולמטה, \u0003בפרט וכלל.\u0004 שתחילה יצאו נצח והוד, הנקראים ב׳ רגלים שהם ימין ושמאל הנקראים פרט. ואח״כ יצא הקו האמצעי המיחד אותם שהוא יסוד. וז\"ש, \u0003כתרין תתאין באצבעין דרגלין דאינון פרט וכלל,\u0004 שתחילה יצא הפרט, שהם הרגלין, משום \u0003דהא גופא לא אתחזי בהדייהו, דאינון לבר מגופא,\u0004 וע״כ אינם נבחנים שנתפצלו מן הגוף כמו הידים, אלא שיצאו בלי התכללות מוקדמת של הגוף שהוא ת״ת, ואח״כ בא היסוד ומיחדם זה בזה. ונמצא הכלל אחר הפרט."],[6,"","וההפרש גדול מאד, שאם הכלל קודם לפרט, לא נראה בשמאל שים דין, כי כבר היה מתחילתו ממותק בתוך הכלל, מטרם שיצא לבחי׳ פרט. משא״כ אם הפרט קודם לכלל, הרי נגלה הדין והמחלוקת שבין ימין לשמאל, עד שבא הכלל ומיחד אותם. והטעם שמחזה ולמעלה נבחן שהכלל יצא קודם הפרט הוא, משום שז״א מקבל ג׳ הקוין מאמא, בסוד תלת מחד נפקי חד בתלת קיימא (כנ\"ל ב״א דף רפ״ז דייה תלת) ונמצא שקו אמצעי משך אצלו גם ב׳ קוין ימין ושמאל דאמא, הרי שקו אמצעי דז״א קודם וגורם לב׳ הקוין ימין ושמאל שלו. וכל זה מחזה ולמעלה, משא״כ בנה״י שהם לבר מגופא, אין מיתוק הגוף שהוא ת״ת יכול להגין עליהם, וע״כ יצא הפרט בלתי ממותק בקו אמצעי. ואח״כ הכלל, שהוא יסוד."],[7,"אי הכי מאי","וכו׳: שואל, א״כ מהו ועמדו רגליו ביום ההוא. הרי שאינם לחוץ מן הגוף שהוא ז״א, שהרי מיוחסים לו. ומשיב, אלא רגליו של הגוף, פירושו, בעלי הדין לעשות נקמות ברשעים, ונקראים בעלי רגלים, שמהם דינים קשים. ומתאחזים בעלי הדין שלמטה, בספירות תחתונות שנקראים רגלים. וע״ז כתוב, ועמדו רגליו וגו'."],[8,"תאנא כל אינון","וכו׳: למדנו כל אלו התקונים שלמעלה, שהם בגוף הקדוש שהוא כלל האדם, נמשכים זה מן זה ומתאחזים זה בזה, ומשקים זה את זה, כמו הדם הנמשך בקלוח הגידים לכאן ולכאן, ממקום זה למקום אחר, והם משקים את הגוף. אף כאן, משקים זה לזה ומאירים זה לזה, עד שמאירים כל העולמות, ומתברכים בשבילם. \u0003קטפין\u0004 פירושו קלוחים, מלשון הניצוק וקטפרס (טהרות ח')."]],[]],[["תָּאנָא, כָּל אִינּוּן כִּתְרִין דְּלָא אִתְכְּלִלוּ בְּגוּפָא, כֻּלְּהוּ רְחִיקִין וּמְסָאֲבִין, וּמְסַאֲבָן כָּל מַאן דְּיִקְרַב לְגַבֵּיהוֹן, לְמִנְדַּע מִנְּהוֹן מִלִּין.","תָּאנָא, מַאי תִּיאוּבְתָא דִּלְהוֹן לְגַבֵּי תַּלְמִידֵי חֲכָמִים. אֶלָּא מִשּׁוּם דְּחָמָן בְּהוּ גּוּפָא קַדִּישָׁא, וּלְאִתְכַּלְלָא בְּהוּ בְּהַהוּא גּוּפָא. וְכִי תֵּימָא, אִי הָכִי, הָא מַלְאָכִין קַדִּישִׁין וְלֵיתְהוֹן בִּכְלָלָא דְּגוּפָא. לָא. דְּחַס וְשָׁלוֹם אִי לֶיהֱווֹן לְבַר מִכְּלָלָא דְּגוּפָא קַדִּישָׁא, לָא הֲווֹ קַדִּישִׁין וְלָא מִתְקַיְימֵי. וּכְתִיב (דניאל י׳:ו׳) וּגְוִיָּיתוֹ כְתַרְשִׁישׁ. וּכְתִיב (יחזקאל א׳:י״ח) וְגַבּוֹתָם מְלֵאוֹת עֵינַיִם. (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל. כֻּלְּהוּ בִּכְלָלָא דְּאָדָם. בַּר מֵהָנֵי דְּלֵיתְהוֹן בִּכְלָלָא דְּגוּפָא, דְּאִינּוּן מִסְאֲבִין, וּמְסַאֲבָן כָּל מַאן דְּיִקְרַב בַּהֲדַיְיהוּ.","וְתָאנָא, כֻּלְּהוּ מֵרוּחָא דִּשְׂמָאלָא, דְּלָא אִתְבְּסָם בְּאָדָם מִשְׁתַּכְּחִין, וְנַפְקוּ מִכְּלָלָא דְּגוּפָא קַדִּישָׁא, וְלָא אִתְדָּבָקוּ בֵּיהּ. וּבְגִין כָּךְ כֻּלְּהוּ מִסְאֲבִין וְאַזְלִין וְטָאסִין עָלְמָא, וְעַיְילִין בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא, לְאִתְדַּבְּקָא בְּהַהוּא דִּינָא קַדְמָאָה דְּאִקְרֵי קַיִן, דְּנָפִיק בִּכְלָל דְּגוּפָא דִּלְתַּתָּא. וְשָׁאטִין וְטָאסִין כָּל עָלְמָא, וּפַרְחָן וְלָא מִתְדַּבְּקָאן בִּכְלָלָא דְּגוּפָא, וּבְגִינֵי כַּךְ אִינּוּן לְבַר, מִכָּל מַשִׁרְיָין דִּלְעֵילָּא וְתַתָּא. מִסְאֲבִין אִינּוּן. בְּהוּ כְּתִיב (ויקרא י״ג:מ״ו) מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ.","וּבְרוּחָא דְּאִקְרֵי הֶבֶל, דְּאִתְבָּסָּם יַתִּיר בִּכְלָלָא דְּגוּפָא קַדִּישָׁא. נָפְקִין אַחֲרָנִין דְּמִבַּסְמָן יַתִּיר, וּמִתְדַּבְּקָן בְּגוּפָא, וְלָא מִתְדַּבְּקָן. כֻּלְּהוּ תַּלְיָין (ע\"ו ע\"ב) בַּאֲוִירָא וְנָפְקִין מֵהַאי כְּלָלָא דְּאִלֵּין מִסְאֲבִין. וְשַׁמְעִין מַה דְּשַׁמְעִין מֵעֵילָּא, וּמִנַּיְיהוּ יַדְעֵי לְתַתָּא דְּקָאַמְרֵי לְהוּ.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, כֵּיוָן דְּאִתְבְּסָמוּ לְעֵילָּא כְּלָלָא דְּאָדָם, גּוּפָא קַדִּישָׁא, דְּכַר וְנוּקְבָּא. אִתְחַבָּרוּ זִמְנָא תְּלִיתָאָה, וְנָפַק אִתְבַּסְּמוּתָא דְּכֹלָּא. וְאִתְבְּסָמוּ עָלְמִין עִלָּאִין וְתַתָּאִין. וּמִכָּאן אִשְׁתָּכְלָל עָלְמָא דִּלְעֵילָּא וְתַתָּא, מִסִּטְרָא דְּגוּפָא קַדִּישָׁא. וּמִתְחַבְּרָן עָלְמִין, וּמִתְאַחֲדָן דָּא בְּדָא, וְאִתְעָבִידוּ חַד גּוּפָא. (ובגין דכלהו חד גופא, שכינתא לעילא, שכינתא לתתא, קודשא בריך הוא לעילא, קודשא בריך הוא לתתא') וּמְשַׁלְּפָא רוּחָא, וְעַיְילָא בְּחַד גּוּפָא. וּבְכֻלְּהוּ לָא אִתְחֲזֵי אֶלָּא חַד. (ישעיהו ו׳:ג׳) קָדשׁ קָדשׁ קָדשׁ יְיָ צְבָאוֹת מְלֹא כָּל הָאָרֶץ כְּבוֹדוֹ. דְּכֹלָּא הוּא חַד גּוּפָא.","תָּאנָא, כֵּיוָן דְּאִתְבְּסָמוּ דָּא בְּדָא, (כתיב (שיר השירים א׳:י״א) תורי זהב נעשה לך עם נקודות הכסף) אִתְקָשָּׁרוּ דִּינָא וְרַחֲמֵי. (אתבסמא דינא ברחמי) וְאִתְבַּסְּמַת נוּקְבָּא בִּדְכוּרָא. וּבְגִינֵי כַּךְ לָא סַלְּקָא דָּא בְּלֹא דָּא, כְּהַאי תָּמָר, דְּלָא סַלְּקָא דָּא בְּלֹא דָּא. וְעַל הַאי תָּנֵינָן, מַאן דְּאַפִּיק גַּרְמֵיהּ בְּהַאי עָלְמָא מִכְּלָלָא דְּאָדָם, לְבָתַר כַּד נָפִיק מֵהַאי עָלְמָא, לָא עָיֵיל בִּכְלָלָא דְּאָדָם, דְּאִקְרֵי גּוּפָא קַדִּישָׁא. אֶלָּא בְּאִינּוּן דְּלָא אִקְרוּן אָדָם, וְנָפִיק מִכְּלָלָא דְּגוּפָא.","תַּנְיָא, תּוֹרֵי זָהָב נַעֲשֶׂה לָּךְ עִם נְקוּדוֹת הַכָּסֶף, דְּאִתְבְּסָמוּ דִּינָא בְּרַחֲמֵי. וְלֵית דִּינָא, דְּלָא הֲווֹ בֵּיהּ רַחֲמֵי. וְעַל הַאי כְּתִיב, (שיר השירים א׳:י׳) נָאווּ לְחָיַיִךְ בַּתּוֹרִים צַוָּארֵךְ בַּחֲרוּזִים. בַּתּוֹרִים: כְּמוֹ דִּכְתִּיב, תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ וְגוֹ'. בַּחֲרוּזִים: כְּמָה דִּכְתִּיב, עִם נְקוּדוֹת הַכָּסֶף. צַוָּארֵךְ, בִּכְלָלָא דְּנוּקְבָּא, דָּא מַטְרוֹנִיתָא אִשְׁתְּכַח בֵּי מַקְדְּשָׁא דִּלְעֵילָּא, וִיְרוּשָׁלַם דִּלְתַּתָּא (ס\"א ומקדשא דכלא) וּמַקְדְּשָׁא. וְכָל דָּא מִדְאִתְבְּסָמַת בִּדְכוּרָא, וְאִתְעָבִיד כְּלָלָא דְּאָדָם, וְדָא הוּא כְּלָלָא דִּמְהֵימְנוּתָא. מַאי מְהֵימְנוּתָא. דִּבְגַוִּיהּ אִשְׁתְּכַח כָּל מְהֵימְנוּתָא.","(שייך פרשת כי תצא) וְתָאנָא, מַאן דְּאִקְרֵי אָדָם, וְנִשְׁמְתָא נַפְקַת מִנֵּיהּ, וּמִית. אָסִיר לְמֵיבַת לֵיהּ בְּבֵיתָא, לְמֶעְבַּד לֵיהּ לִינָה עַל אַרְעָא, מִשּׁוּם יְקָרָא דְּהַאי גּוּפָא, דְּלָא יִתְחֲזֵי בֵּיהּ קְלָנָא, דִּכְתִּיב, (תהילים מ״ט:י״ג) אָדָם בִּיקָר בַּל יָלִין, אָדָם דְּהוּא יָקָר מִכָּל יְקָרָא, בַּל יָלִין. מַאי טַעְמָא. מִשּׁוּם דְּאִי יַעַבְדוּן הָכִי, נִמְשַׁל כַּבְּהֵמוֹת נִדְמוּ. מַה בְּעִירֵי לָא הֲווֹ בִּכְלָלָא דְּאָדָם, וְלָא אִתְחֲזֵי בְּהוּ רוּחָא קַדִּישָׁא, אוּף הָכָא כִּבְעִירֵי, גּוּפָא בְּלָא רוּחָא, וְהַאי גּוּפָא, דְּהוּא יְקָרָא דְּכֹלָּא, לָא יִתְחֲזֵי בֵּיהּ קְלָנָא.","וְתָאנָא בִּצְנִיעוּתָא דְּסִפְרָא, כָּל מַאן דְּעָבִיד לִינָה לְהַאי גּוּפָא קַדִּישָׁא, בְּלָא רוּחָא, עָבִיד פְּגִימוּתָא בְּגוּפָא דְּעָלְמִין. דְּהָא בְּגִין דָּא, לָא עָבִיד לִינָה בְּאַתְרָא קַדִּישָׁא, בְּאַרְעָא דְּצֶדֶק יָלִין בָּהּ, (ס\"א דכתרא קדישא דמלכא בארעא דכתיב (ישעיהו א׳:כ״א) צדק ילין בה) מִשּׁוּם דְּהַאי גּוּפָא יְקָרָא, אִתְקְרֵי דִּיּוּקְנָא דְּמַלְכָּא. וְאִי עָבִיד בֵּיהּ לִינָה, הֲוִי כְּחַד מִן בְּעִירֵא. (הדא הוא דכתיב, (תהילים מ״ט:י״ג) נמשל כבהמות (ע\"כ) נדמו)"],[[0,"תאנא כל אינון","וכו׳: למדנו כל אלו הספירות שלא נכללו בגוף, שהוא הקו האמצעי, אלא שהם נמשכים מקו שמאל, כולם מתועבים וטמאים ומטמאים כל מי שיקרב אליהם לדעת דברים מהם."],[1,"תאנא, מאי תיאובתא","וכו׳: למדנו, מה היא תאותם של הקליפות, לתלמידי חכמים. ומשיב, אלא משום שרואים בהם גוף קדוש, ורוצים להתכלל, דהיינו לינק, מהגוף ההוא. ואם תאמר, אם כן, הרי מלאכים הקדושים שאינם בכלל גוף. ומשיב, לא. אם היו, חס ושלום, לחוץ מכלל גוף הקדוש, שה״ס הקו האמצעי, לא היו קדושים, ולא היו מתקיימים. כי כתוב, וגוייתו כתרשיש. וכתוב, וגבותם מלאות עינים. והאיש גבריאל. הרי שכולם הם בכלל אדם, בקו האמצעי. חוץ מאלו שאינם בכלל הגוף, אלא מקו שמאל, שהם טמאים ומטמאים, כל מי שיקרב אצלם."],[2,"ותאנא כלהו מרוחא","וכו׳: ולמדנו כולם נמצאים מריח שמאל שאינו נמתק באדם, שהוא קו אמצעי, ז״א, ויצאו מכלל גוף הקדוש, ולא נתדבקו בו. ומשום זה, כולם טמאים. והולכים ומשוטטים בעולם, ובאים בנקב התהום הגדול, ששם השקיע את קין (כנ״ל אות שכ״ז) להתדבק בדין ההוא הראשון הנקרא קין, שיצא מכלל הגוף למטה, כי היה שמאל בלי ימין (כנ״ל אות שכ״ז) והם מעופפים ומשוטטים בכל העולם, ופורחים ואינם מתדבקים בכלל הגוף, דהיינו בקו האמצעי, ומשום זה, הם לחוץ מכל המחנות שלמעלה ושלמטה, והם טמאים. בהם כתוב, מחוץ למחנה מושבו."],[3,"וברוחא דאקרי הבל","וכו׳: וברוח הנקרא הבל, שהוא יותר מבושם בכלל גוף הקדוש, יוצאים רוחות אחרים המבושמים יותר, והם מתדבקים בגוף ולא מתדבקים. כולם תלוים באויר (כנ״ל ויקרא אות תל״ב) והם יוצאים מכלל רוחות הטמאות הנ״ל. ושומעים מה ששומעים למעלה ומהם יודעים הרוחות שלמטה, כי הם אומרים להם. (כמ״ש שם)."],[4,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא, כיון שנתבשמו למעלה הכלל של אדם, גוף הקדוש, שהוא זכר ונקבה. דהיינו ז״א ונוקביה נתחברו פעם שלישית, ויצאה התבשמות הכל, שהיא שת, ונתבשמו העולמות העליונים והתחתונים, ומכאן נשתכלל העולם שלמעלה ושלמטה, שהם זו״ן מצד הגוף הקדוש, שהוא קו האמצעי, ומתחברים העולמות ומתאחזים זה בזה, ונעשו גוף אחד. שהוא שת, ונמשך רוח ונכנס בגוף ההוא. ובכולם אינה נראה אלא אחד. קדוש קדוש קדוש ה׳ צבאית מלא כל הארץ כבודו. שהכל הוא גוף אחד. כי ג״פ קדוש ה״ס ג׳ קוין שנעשו אחד."],[5,"תאנא כיון דאתבסמו","וכו׳: למדנו, כיון שנתבשמו ז״א ונוקביה זה בזה. נקשר הדין ברחמים, והנוקבא נתבשמת בדכר, שהוא ז\"א. ומשום זה אינם עולים זה בלא זה כאותו תמר, שאינו עולה ועושה פירות, זה בלא זה, נקבה בלי זכר, ועל זה למדנו מי שמוציא עצמו בעולם הזה מכלל אדם, שהוא קו האמצעי, אח״כ כשיוצא מעולם הזה, אינו נכנס בכלל אדם הנקרא גוף קדוש, שהוא ז״א, ובי״ע דקדושה, אלא שנכנס באלו שאינם נקראים אדם, דהיינו בי״ע דטומאה, שיצאו מכלל הגוף, שהוא קו אמצעי."],[6,"תניא תורי זהב","וכו׳: למדנו, תורי זהב נעשה לך עם נקודות הכסף היינו שנתבשם הדין הנקרא זהב, שה״ס הארת החכמה שבשמאל, ברחמים, הנקראים נקודות הכסף. דהיינו שנתלבשה החכמה בחסדים, ואין דין שלא יהיה בו רחמים, כי נכללו זה מזה. ועל זה כתוב, נאוו לחייך בתורים צוארך בחרוזים. \u0003בתורים\u0004 פירושו, כמו שכתוב, תורי זהב. שהם משמאל, \u0003בחרוזים,\u0004 פירושו כמ\"ש, עם נקודות הכסף, דהיינו ימין, חסד. \u0003צוארך,\u0004 הוא בכלל הנוקבא זו היא המטרוניתא, שהיא מלכות, כי נמצא בו, בצואר, המקדש שלמעלה. שהוא יסוד דמלכות. וירושלים של מטה והמקדש שבו, נקרא ג״כ צואר. (כנ\"ל וישלח אות קכ״ב) וכל זה אחר שהנוקבא נתבשמת בדכר, ונעשה כלל אדם, וזה הוא כלל האמונה. מהו אמונה. היינו משום שבתוכו, בכלל אדם, נמצאת כל שלימות האמונה."],[7,"ותאנא מאן דאקרי","וכו׳: ולמדנו, מי שנקרא אדם, והנשמה יצאה ממנו, ומת. אסור להלין אותו בבית לעשות לו לינה על הארץ, משום כבוד הגוף הזה שלא יהיה נראה בו הבזיון, שהוא גוף בלא נשמה. שכתוב, \u0003אדם ביקר בל ילין,\u0004 שפירושו, \u0003אדם\u0004 שהוא יקר מכל יקר, \u0003בל ילין,\u0004 אחר מיתתו, מה הטעם. הוא משים שאם יעשו כך, \u0003נמשל כבהמות נדמו,\u0004 שלאחר מיתתו נמשל לבהמה, מה בהמות לא היו בכלל אדם, שע״כ לא נראה בהם רוח קדוש, אף כאן, באדם המת, הוא כבהמה, גוף בלא רוח. וע״כ, הגוף הזה, שהוא יקר מכל, לא יהיה נראה בו בזיון."],[8,"ותאנא בצניעותא דספרא","וכו׳: ולמדנו בספרא דצניעותא, כל מי שעושה לינה לגוף הקדוש הזה כשהוא בלא רוח, עושה פגם בגוף שבעולמות, דהיינו באדם העליון, כי משום זה אסור לעשות לינה במקום קדוש, בארץ אשר צדק ילין בה, שהיא ארץ ישראל, שכתוב בה, לא תלין נבלתו וגו' ולא תטמא את אדמתך. משום שגוף יקר זה נקרא צורת המלך. ואם עושה בו לינה, הוא נראה כאחת מן הבהמות, דהיינו בלא רוח כבהמה. כנ״ל בסמוך."]],[]],[["תָּאנָא, (בראשית ו׳:ב׳) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. (ס\"א בני האלהים) אִינּוּן (ס' ע\"ב) דְּאִטְמַרוּ, וְנָפְלוּ בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא. אֶת בְּנוֹת הָאָדָם, (האדם הידוע). וּכְתִיב וְיָלְדוּ לָהֶם הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם וְגוֹ'. מֵהַהוּא דְּאִקְרֵי עוֹלָם. כִּדְתָּנֵינָן יְמֵי עוֹלָם. אַנְשֵׁי הַשֵּׁם, מִנְּהוֹן נַפְקוּ רוּחִין וְשֵׁדִין לְעָלְמָא, לְאִתְדַּבְּקָא בְּרַשִׁיעַיָיא.","הַנְּפִילִים הָיוּ בָאָרֶץ, לְאַפָּקָא אִלֵּין אַחֲרָנִין. דְּלָא הֲווֹ בָּאָרֶץ. הַנְּפִילִים: עַזָּ\"א וְעַזָּאֵ\"ל הֲווֹ בָּאָרֶץ. בְּנֵי הָאֱלֹהִים לָא הֲווֹ בָּאָרֶץ. וְרָזָא הוּא וְכֹלָּא אִתְּמַר.","כְּתִיב (בראשית ו׳:ו׳) וַיִּנָּחֵם יְיָ כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ, לְאַפָּקָא אָדָם דִּלְעֵילָּא, דְּלָא הֲוִי בָּאָרֶץ. וַיִּנָחֶם יְיָ הַאי בִּזְעֵיר אַפִּין אִתְּמַר. וַיִּתְעַצֵּב אֶל לִבּוֹ, וַיֶּעְצַב לֹא נֶאֱמַר. אֶלָּא וַיִּתְעַצֵּב, אִיהוּ אִתְעֲצָּב, דְּבֵיהּ תַּלְיָיא מִלְּתָא. לַאֲפּוּקֵי מִמַּאן דְּלָא אִתְעֲצָּב. אֶל לִבּוֹ, בְּלִבּוֹ לָא כְּתִיב, אֶלָּא אֶל לִבּוֹ. כְּמַאן דְּאִתְעֲצָּב (ומקבל) לְמָארֵיהּ, דְּאַחְזֵי הַאי לְלִבָּא דְּכָל לִבִּין.","וַיֹּאמֶר יְיָ אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה וְגוֹ'. לְאַפָּקָא אָדָם דִּלְעֵילָּא. וְאִי תֵּימָא אָדָם דִּלְתַּתָּא בִּלְחוֹדוֹי. לָאו לְאַפָּקָא כְּלָל. מִשּׁוּם דְּלָא קָאִים דָּא בְּלָא דָּא.","וְאִלְמָלֵא חָכְמָה סְתִימָא דְּכֹלָּא, כֹּלָּא אִתְתָּקַּן כְּמֵרֵישָא. הֲדָא הוּא דִכְתִיב, (משלי ח׳:י״ב) אֲנִי חָכְמָה שָׁכַנְתִּי עָרְמָה. אַל תִּקְרֵי שָׁכַנְתִּי, אֶלָּא שְׁכִינָתִּי (ס\"א שיכנתי).","וְאִלְמָלֵא הַאי תִּקּוּנָא דְּאָדָם, לָא קָאִים עָלְמָא. הֲדָא הוּא דִּכְתִּיב, (משלי ג׳:י״ט) יְיָ בְּחָכְמָה יָסַד אָרֶץ. וּכְתִיב (בראשית ו׳:ח׳) וְנָח מָצָא חֵן בְּעֵינֵי יְיָ.","וְתָאנָא, כֻּלְּהוּ מוֹחִין תַּלְיָין בְּהַאי מוֹחָא. וְהַחָכְמָה הוּא כְּלָלָא דְּכֹלָּא הוּא. וְדָא חָכְמָה סְתִימָא, דְּבָהּ אִתְתָּקִיף וְאִתְתָּקַּן תִּקּוּנָא דְּאָדָם, לְאִתְיַישְּׁבָא כֹּלָּא עַל תִּקּוּנֵיהּ, כָּל חַד בְּאַתְרֵיהּ. הֲדָא הוּא דִכְתִיב, (קהלת ז׳:י״ט) הַחָכְמָה תָּעוֹז לֶחָכָם מֵעֲשָׂרָה שַׁלִּיטִים, דְּאִינּוּן תִּקּוּנָא שְׁלֵימָא דְּאָדָם. וְאָדָם הוּא תִּקּוּנָא דִּלְגוֹ, מִנֵּיהּ קָאִים רוּחָא. (הדא הוא דכתיב, (שמואל א ט״ז:ז׳) כי האדם יראה לעינים ויהוה יראה ללבב, דאיהו בלגו לגו)","וּבְהַאי תִּקּוּנָא דְּאָדָם, אִתְחֲזֵי שְׁלֵימוּתָא מְהֵימְנוּתָא דְּכֹלָּא, דְּקָאִים עַל כּוּרְסְיָּיא. דִּכְתִּיב, (יחזקאל א׳:כ״ו-כ״ז) וּדְמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. וּכְתִיב (דניאל ז׳:י״ג) וַאֲרוּ עִם עֲנָנֵי שְׁמַיָא כְּבַר אֱנָשׁ אָתֵה הֲוָא וְעַד עַתִּיק יוֹמַיָּא מְטָה וּקְדָמוֹהִי הַקְרְבוּהִי. עַד כָּאן סְתִימָאן מִלִּין. וּבְרִירָן טַעֲמִין. זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּיָדַע וְיַשְׁגַח בְּהוֹן. וְלָא יִטְעֵי בְּהוֹן. דְּמִלִּין אִלֵּין לָא אִתְיְהִיבוּ, אֶלָּא לְמָארֵי מְדִין וּמְחַצְדֵּי חַקְלָא, דְּעָאלוּ וְנַפְקוּ. דִּכְתִּיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְצַדִּיקִים יֵלְכוּ בָם וּפוֹשְׁעִים יִכָּשְׁלוּ בָם.","תָּאנָא, בָּכָה רַבִּי שִׁמְעוֹן, וְאָרִים קַלֵיהּ וְאָמַר, אִי בְּמִלִּין דִּילָן, דְּאִתְגַּלְּיָין הָכָא, אִתְגְּנִיזוּ חַבְרַיָּיא בְּאִדָּרָא דְּעָלְמָא דְּאָתֵי, וְאִסְתְּלָּקוּ מֵהַאי עָלְמָא, יָאוּת וְשַׁפִּיר הֲוָה, בְּגִין דְּלָא אִתְגַּלְּיָין לְחַד מִבְּנֵי עָלְמָא. הָדָר וְאָמַר, הַדְרִי בִּי, דְּהָא גַּלֵּי קָמֵּיהּ דְּעַתִּיקָא דְּעַתִּיקִין, סְתִימָא דְּכָל סְתִימִין, דְּהָא לָא לִיקָרָא דִּילִי עֲבִידְנָא, וְלָא לִיקָרָא דְּבֵית אַבָּא, וְלָא לִיקָרָא דְּחַבְרַיָּיא אִלֵּין, אֶלָּא בְּגִין דְּלָא יִטְעוּן בְּאוֹרְחוֹי, וְלָא יַעֲלוּן בְּכִסּוּפָא לְתַרְעֵי פַּלְטְרוֹי, וְלָא יִמְּחוּן בִּידֵיהוֹן. זַכָּאָה חוּלָקִי עִמְּהוֹן, לְעָלְמָא דְּאָתֵי.","תָּנָא, עַד לָא נַפְקוּ חַבְרַיָיא מֵהַהוּא אִדָּרָא, מִיתוּ (צ\"ע ע\"א ע\"א) רִבִּי יוֹסֵי בַּרִבִּי יַעֲקֹב, וְרִבִּי חִזְקִיָּה, וְרִבִּי יֵיסָא. וְחָמוּ חַבְרַיָּיא, דַּהֲווֹ נַטְלִין לוֹן מַלְאֲכִין קַדִּישִׁין בְּהַהוּא פַּרְסָא. וְאָמַר רַבִּי שִׁמְעוֹן מִלָּה, וְאִשְׁתְּכָכוּ. צָוַוח וְאָמַר, שֶׁמָּא חַס וְשָׁלוֹם גְּזֵרָה אִתְגְּזַר עֲלָנָא לְאִתְעַנְּשָׁא, דְּאִתְגְלֵי עַל יְדָנָא מַה דְּלָא אִתְגְּלֵי מִיּוֹמָא דְּקָאִים מֹשֶׁה עַל טוּרָא דְּסִינַי, דִּכְתִּיב, (שמות ל״ד:כ״ח) וַיְהִי שָׁם עִם יְיָ אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה וְגוֹ'. מַה אֲנָא הָכָא. אִי בְּגִין דָּא אִתְעֲנָשׁוּ.","שָׁמַע קָלָא, זַכָּאָה אַנְתְּ רַבִּי שִׁמְעוֹן, זַכָּאָה חוּלָקָךְ וְחַבְרַיָּיא, אִלֵּין דְּקַיְימִין בַּהֲדָךְ, דְּהָא אִתְגְּלֵי לְכוֹן מַה דְּלָא אִתְגְּלֵי לְכָל חֵילָא דִּלְעֵילָּא, אֲבָל תָּא חֲזֵי, דְּהָא כְּתִיב, (יהושע ו׳:כ״ו) בִּבְכוֹרוֹ יְיַסְּדֶנָּה וּבִצְעִירוֹ יַצִּיב דְּלָתֶיהָ. וְכָּל שֶׁכֵּן דְּבִרְעוּ סַגִּי וְתַקִּיף, אִתְדָּבָקוּ נַפְשַׁתְהוֹן בְּשַׁעֲתָא דָּא דְּאִתְנְסִיבוּ. זַכָּאָה חוּלָקֵיהוֹן, דְּהָא בִּשְׁלֵימוּתָא אִסְתָּלָקוּ. (דלא הוה כן לאינון דהוו קמייהו, אמאי מיתו)"],[[0,"תאנא ויראו בני","וגו׳: למדנו, ויראו בני האלקים את בנות האדם. הם אלו שנסתרו, דהיינו שנתרחקו מהקדושה, ונפלו בנקב התהום הגדול. דהיינו כנ״ל (באות של״ז). את בנות האדם. האדם הידוע, שהוא ז״א, שהן מבחינת הבל, שאומר עליהן לעיל (אות של\"ח) דאתבסם יתיר בכללא דגופא קדישא, שהוא ז״א. ע״ש. וכתוב וילדו להם המה הגבורים אשר מעולם וגו׳. היינו שהם מההוא שנקרא \u0003עולם,\u0004 כמו שלמדנו (לעיל אות קס״ב) ימי עולם, שהוא ז״א. אלא שהם מסטרא אחרא, שפעם הם מתדבקים בז״א ופעם לא. (כמ״ש לעיל אות של״ח) ומתדבקן בגופא ולא מתדבקן. כלהו תליין באוירא. ע״ש. \u0003אנשי השם,\u0004 היינו ממלכות, הנקראת \u0003שם,\u0004 ואינם מז״א שנקרא עולם. והם הרוחות דשמאלא דלא אתבשם באדם (כנ״ל אות של״ג) וע״כ מהם יוצאים רוחית ושדים לעולם להתדבק ברשעים."],[1,"הנפילים היו בארץ:","בא להוציא האחרים שלא היו בארץ, שאינם מבחינת המלכות הנקראת ארץ. \u0003הנפילים,\u0004 שהם עזא ועזאל, היו בארץ. שהם מבחינת הרוחות דשמאל שאינם מתדבקים כלל בגופא, שהוא ז״א (כנ״ל אות של״ג) אלא במלכות הנקראת ארץ, שהיא שמאל. בני האלהים, לא היו בארץ, שהוא מלכות. אלא שהם מתדבקים ולא מתדבקים בגופא קדישא, שהוא ז״א. כנ״ל בדבור הסמוך. והוא סוד. והכל למדנו."],[2,"כתיב וינחם ה׳","וגו׳: כתוב, וינחם ה׳ כי עשה את האדם בארץ. בא להוציא אדם שלמעלה שלא היה בארץ. דהיינו שאינו מבחינת מלכות שנקראת ארץ. כי כל דין המבול לא היה אלא בבחינת מלכות שה״ס ארץ, ולא למעלה ממנה. \u0003וינחם ה',\u0004 זה נאמר בז\"א, (כנ״ל אות ר״ד). \u0003ויתעצב אל לבו,\u0004 ויעצב לא נאמר, אלא ויתעצב, הוא נתעצב, כי בו תלוי הדבר, כלומר, שמעשה התחתונים מגיעים לז״א, להוציא ממי שאינו מתעצב ממעשה התחתונים, כי התחתונים אינם פוגמים בהם. והיינו למעלה מז״א. \u0003אל לבו,\u0004 בלבו לא כתוב, אלא, אל לבו. כמי שמתעצב לאדונו, כי הראה זה להלב של כל הלבבות. שהוא א״א. המלובש בפנימיות ז״א."],[3,"ויאמר ה׳ אמחה","וגו׳: ויאמר ה׳ אמחה את האדם אשר בראתי מעל פני האדמה וגו׳. מעל פני \u0003האדמה\u0004, בא להוציא אדם שלמעלה מן המלכות שנקראת אדמה. ואם תאמר, אדם שלמטה בלבד, ואדם שלמעלה לא נפגם כלום מחמת זה, אין להוציא ולחלק בין זה לזה כלל. משום שאינו עומד זה בלא זה. וכשנמחה אדם שלמטה נפגם גם אדם שלמעלה."],[4,"ואלמלא חכמה סתימא","וכו׳: ואם החכמה סתימאה מהכל, דהיינו חכמה דא״א, היתה מאירה אל המלכות, היה הכל מתוקן כבתחילה, ולא היה מבול, ז״ש אני חכמה שכנתי ערמה, אל תקרי שכנתי, אלא שיכנתי. פירוש. חכמה סתימאה אומרת על המלכות שנקראת ערמה, שהיא חכמה תתאה, אני חכמה שיכנתי ויסדתי הערמה שהיא המלכות. וכיון שהיה מבול על הארץ, שה״ס המלכות, בהכרח שהחכמה סתימאה לא האירה בה."],[5,"ואלמלא האי תקונא","וכו׳: ולולא תקון אדם לא היה העולם מתקיים. ז״ש, ה׳ בחכמה יסד ארץ. וכתוב, ונח מצא חן בעיני ה׳. פירוש, בתקון אדם נמשכת החכמה. ובחכמה יסד ארץ, ע״כ לולא תקון אדם לא היתה הארץ מתקיימת. ונח, שהיה בו תקון האדם, נתקיימה על ידי הארץ. דכתיב, ונח מצא חן בעיני ה', שהצילו, ועל ידו נתקיים כל העולם."],[6,"ותאנא כלהו מוחין","וכו׳: ולמדנו, כל המוחין תלוים במוח ההוא, דהיינו בחכמה סתימאה, והחכמה כלל הכל היא. וחכמה סתימאה זו, בה נתתקף ונתתקן תקון אדם, שיתישב הכל על תקונו, כל אחד במקומו, ז״ש החכמה תעוז לחכם מעשרה שליטים דהיינו ע״ס שהם תקון השלם של אדם. ואדם הוא תקון שבפנימיותם. כי המוחין שהם בפנימיות מכונים אדם (כנ״ל אות רס״ג) שממנו מתקיים הרוח."],[7,"ובהאי תקונא דאדם","וכו׳: ובתקון הזה של אדם נראית שלמות אמונת כל אותו העומד על הכסא, שכתוב, ודמות כמראה אדם עליו מלמעלה. וכתוב, וארו עם ענני שמיא כבר אנש אתה הוא ועד עתיק יומיא מטא וקדמוהי הקרבוהי. עד כאן סתומים הדברים, והטעמים ברורים. אשרי חלקו של מי היודע ומסתכל בהם, ואינו טועה בהם. כי דברים אלו לא נתנו אלא ליושבים על כסא מדין, וקוצרי השדה שנכנסו ויצאו. שכתוב, כי ישרים דרכי ה׳ וצדיקים ילכו בם ופושעים יכשלו בם."],[8,"תאנא בכה ר״ש","וכו׳: למדנו, בכה ר׳ שמעון, והרים קולו ואמר, אם בדברים שלנו שנתגלו כאן, היו נגנזים החברים באדרא דעולם הבא, והיו מסתלקים מעולם הזה, טוב ויפה היה, משום שלא נגלו עוד לאחד מבני עולם הזה. חזר ואמר. אני מתחרט על דברי, אלא שיזכו להתקיים עוד בעולם הזה. כי גלוי לפני עתיקא דעתיקין סתימא דכל סתימין, כי לא לכבודי עשיתי, ולא לכבוד בית אבי, ולא לכבוד החברים האלו, אלא כדי שלא יטעו בדרכיו, ולא יכנסו בבזיון לשערי היכלו, ולא ימחו בידם, מלהכנס. אשרי חלקי עמהם לעולם הבא."],[9,"תנא עד לא","וכו׳: למדנו, מטרם שיצאו החברים מן האדרא ההוא, מתו ר׳ יוסי ב״ר יעקב, ור׳ חזקיה, ור׳ ייסא. וראו החברים, שהיו נושאים אותם מלאכים הקדושים בפרסא ההיא. וא\"ר שמעון דבר ונשתככו החברים. צעק ואמר, אולי ח\"ו נגזרה גזרה עלינו להענש, כי נגלה על ידינו מה שלא נגלה מיום שעמד משה על הר סיני. שכתוב, ויהי שם עם ה׳ ארבעים יום וארבעים לילה וגו׳. מה אני כאן, אם משום זה נענשו."],[10,"שמע קלא זכאה","וכו׳: שמע קול, אשרי אתה ר׳ שמעון ואשרי חלקך וחלק החברים החיים עמך, כי נגלה לכם מה שלא נגלה לכל צבאות מעלה. אבל בוא וראה, כי כתוב, בבכורו ייסדנה ובצעירו יציב דלתיה. וכ״ש החברים, שברצון גדול ואמיץ נתדבקו נפשותיהם בשעה ההיא שנלקחו ע״י המלאכים. אשרי חלקם, כי מתוך השלמות נסתלקו."],[10,"","פירוש. ירחו, היא אחורים של המלכות ששם הקללה. וקלל יהושע שכל הבונה האחורים שלה ימותו כל בניו. וז״ש, \u0003דהא כתיב בבכורו ייסדנה\u0004 וגו׳ ואם הבונה ומשלים האחורים דמלכות כן, שצריך למסור כל בניו בשבילה. \u0003וכ״ש דברעו סגי ותקיף\u0004 וכו', שהם השלימו בנין הפנים של המלכות, ששם הברכה, לא כל שכן ששכרם רב מאד, ואם נסתלקו, הרי כל השלמות הגיעה להם עם ההסתלקות. \u0003זכאה חולקהון דהא בשלמותא אסתלקו.\u0004 שנסתלקו מחמת השלמות."],[10,"","וטעם הסתלקותם כבר נתבאר (לעיל אחרי אות שצ״ח ע״ש) כי בסוף האדרא הגיעו למדרגת גמר התקון, שאז מתבטלת הפרסא וכל ההבדל שמחזה ולמטה למחזה ולמעלה מתבטל. ולפיכך, אלו ג׳ החברים שהיו נשמותיהם מבחינות מחזה ולמטה, נתבטלו, ועלו למדרגה יותר גבוהה, דהיינו שנעשו כמדרגת למעלה מחזה, ומתוך שמבחינת הכלל עוד לא הגיע הזמן לתקון זה, ע״כ היו צריכים להסתלק מעולם הזה ולעלות למעלה. וז״ש לעיל \u0003וחמו חברייא דהוו נמלין לון מלאכין קדישין בההוא פרסא.\u0004 כלומר, שנסתלקו מתוך ביטול הפרסא, ונבחן שמלאכים לקחו אותם בפרסא ההיא שנסתלקה. וז״ש כאן, \u0003זכאה חולקהון דהא בשלמותא אסתלקו,\u0004 כי השלמות שזכו אליה, שהיא ביטול הפרסא, שאחרים יזכו לזה רק בגמר התקון, זו היא שגרמה להסתלקותם."]],[]],[["תָּאנָא, בְּעוֹד דְּאִתְגַּלְּיָין מִלִּין, אִתְרְגִישׁו עִלָּאִין וְתַּתָּאִין, (דאינון רתיכין) וְקָלָא אִתְּעַר בְּמָאתָן וְחַמְשִׁין עָלְמִין דְּהָא מִלִּין עַתִּיקִין לְתַתָּא אִתְגַּלְיָין, וְעַד (נ\"א ועוד) דְּאִלֵּין מִתְבַּסְּמָן נִשְׁמָתַיְיהוּ בְּאִינּוּן מִלִּין, נַפְקָא נִשְׁמָתַיְיהוּ בִּנְשִׁיקָה, וְאִתְקַשָּׁר בְּהַהוּא פַּרְסָא, וְנַטְלִין לְהוּ מַלְאֲכֵי עִלָּאֵי, וְסַלְּקִין לוֹן לְעֵילָּא. וַאֲמַאי אִלֵּין. מִשּׁוּם דְּעָאלֻן וְלָא נַפְקוּ זִמְנָא אַחֲרָא מִן קַדְמַת דְּנָא, וְכֻלְּהוּ אַחֲרִינֵי עָאלוּ וְנַפְקוּ.","אָמַר רַבִּי שִׁמְעוֹן, כַּמָה זַכָּאָה חוּלָקֵיהוֹן דְּהָנֵי תְּלָתָא, וְזַכָּאָה חוּלָקָנָא לְעָלְמָא דְּאָתֵי בְּגִין דָּא. נָפַק קָלָא תִּנְיָינוּת וְאָמַר, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלֹהֵיכֶם חַיִּים כֻּלְכֶם הַיּוֹם. קָמוּ וְאַזְלוּ. בְּכָל אֲתָר דַּהֲווֹ מִסְתַּכְּלֵי סָלִיק רֵיחִין. אָמַר רַבִּי שִׁמְעוֹן שְׁמַע מִינָּהּ, דְּעָלְמָא מִתְבְּרָךְ בְּגִינָן. וַהֲווּ נַהֲרִין אַנְפּוֹי דְּכֻלְּהוּ, וְלָא הֲווֹ יַכְלִין בְּנֵי עָלְמָא לְאִסְתַּכְּלָא בְּהוּ.","תָּאנָא, עֲשָׂרָה עָאלוּ, וְשֶׁבַע נַפְקוּ, וַהֲוָה חַדֵּי רַבִּי שִׁמְעוֹן. וְרִבִּי אַבָּא עָצִיב. יוֹמָא חַד הֲוָה יָתִיב רַבִּי שִׁמְעוֹן וְרִבִּי אַבָּא עִמֵּיהּ, אָמַר רַבִּי שִׁמְעוֹן מִלָּה, וְחָמוּ לְאִלֵּין תְּלָתָא דַּהֲווֹ מַיְיתִין לְהוֹן מַלְאֲכִין עִלָּאִין, וּמְחַזְיָין לְהוּ גְּנִיזִין וְאִדָּרִין דִּלְעֵילָּא, בְּגִין יְקָרָא דִּלְהוֹן. וַהֲווּ עַיְילֵי לוֹן בְּטוּרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא. נַח דַּעְתֵּיהּ דְּרִבִּי אַבָּא.","תָּאנָא, מֵהַהוּא יוֹמָא לָא אַעְדּוּ חַבְרַיָּיא מִבֵּי רַבִּי שִׁמְעוֹן. וְכַד הֲוָה רַבִּי שִׁמְעוֹן מְגַלֶּה רָזִין, לָא מִשְׁתַּכְּחִין תַּמָּן אֶלָּא אִינּוּן. וַהֲוָה קָארֵי לְהוּ רִבִּי שִׁמְעוֹן, שִׁבְעָה אֲנָן עֵינֵי יְיָ. דִּכְתִּיב, (זכריה ד׳:י׳) שִׁבְעָה אֵלֶּה עֵינֵי יְיָ וְעָלָן אִתְּמַר. אָמַר רִבִּי אַבָּא, אֲנָן שִׁיתָא בּוֹצִינֵי, דְּנַהֲרָאן מִשְּׁבִיעָאָה. אַנְתְּ הוּא שְׁבִיעָאָה דְּכֹלָּא. דְּהָא לֵית קִיוּמָא לְשִׁיתָא, בַּר מִשְּׁבִיעָאָה. דְּכֹלָּא תָּלֵי בִּשְׁבִיעָאָה. רִבִּי יְהוּדָה קָארֵי לֵיהּ שַׁבָּת, דְּכֻלְּהוּ שִׁיתָא מִנֵּיהּ מִתְבָּרְכִין, דִּכְתִּיב, (שמות כ׳:י׳) שַׁבָּת לַיְיָ, קֹדֶשׁ לַיְיָ, מַה שַׁבָּת לַיְיָ קֹדֶשׁ, אוּף רַבִּי שִׁמְעוֹן שַׁבָּת לַיְיָ קֹדֶשׁ.","אָמַר רַבִּי שִׁמְעוֹן, תַּוַּוהְנָא עַל הַהוּא חַגִיר חַרְצָן, מָארֵיהּ דְּשַׂעְרֵי, אֲמַאי לָא אִשְׁתְּכַח בְּבֵי אִדָּרָא דִּילָן, בְּזִמְנָא דְּאִתְגַּלְּיָין מִלִּין אִלֵּין קַדִּישִׁין. אַדְּהָכִי, אָתָא אֵלִיָּהוּ, וּתְלַת קַטְפוֹרֵי נְהִירִין בְּאַנְפּוֹי. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, מַאי טַעְמָא לָא שְׁכִיחַ מֹר בְּקַרְדוּטָא (ס\"א בקרטמא) גְּלִיפָא דְּמָארֵיהּ, בְּיוֹמָא דְּהִלּוּלָא.","אָמַר לֵיהּ, חַיֶּיךָ רִבִּי שֶׁבַע יוֹמִין אִתְבְּרִירוּ קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, כָּל אִינּוּן דְּיֵיתוּן וְיִשְׁתַּכְחֻן עִמֵּיהּ, עַל לָא עַיִילְתּוּן בְּבֵי אִדָּרָא דִּלְכוֹן, וּבָעֵינָא לְאִשְׁתַּכְּחָא, זַמִּין קָטִיר בְּכַתְפוֹי (ס\"א נ\"ל שכן צריך לומר, ואנא הוה זמין תמן, ובעינא קמיה לאשתכחא, וכדין קטיר בכתפוי) וְלָא יָכִילְנָא, דְּהַהוּא יוֹמָא שָׁדַרְנִי קוּדְשָׁא בְּרִיךְ הוּא, לְמֶעְבַּד נִסִּין לְרַב הַמְנוּנָא סָבָא וְחַבְרוֹי, דְּאִתְמְסָרוּ בְּאַרְמוֹנָא (ס\"א בקרוניא) דְּמַלְכָּא, וְאַרְחִישְׁנָא לְהוּ בְּנִסָּא, דְּרָמֵינָא לְהוּ כּוֹתָלָא דְּהֵיכָלָא דְּמַלְכָּא, וְאִתְקְטָרוּ בְּקִטְרוֹי, דְּמִיתוּ אַרְבָּעִים וַחֲמִשָּׁה פַּרְדַּשְׁכֵּי. וַאֲפִּיקְנָא לְרַב הַמְנוּנָא וְחַבְרוֹי וְרָמֵינָא (ס\"א ואוליכנא) לוֹן לְבִקְעַת אוֹנוֹ, וְאִשְׁתְּזִיבוּ. וְזַמִינְנָא קַמַּיְיהוּ נָהֲמָא וּמַיָּיא, דְּלָא אַכְלוּ תְּלָתָא יוֹמִין. וְכָל הַהוּא יוֹמָא לָא בָּדִילְנָא מִנַּיְיהוּ.","וְכַד תַּבְנָא, אַשְׁכַּחְנָא פַּרְסָא דְּנָטְלוּ כָּל אִינּוּן סַמְכִין, וּתְלַת מִן חַבְרַיָּיא עֲלָהּ, וְשָׁאִילְנָא לוֹן. וְאָמְרוּ חוּלָקָא דְקוּדְשָׁא בְּרִיךְ הוּא, מֵהִלּוּלָא דְּרַבִּי שִׁמְעוֹן וְחַבְרוֹי. זַכָּאָה אַנְתְּ רַבִּי שִׁמְעוֹן, וְזַכָּאָה חוּלָקָךְ, וְחוּלָקָא דְּאִינּוּן חַבְרַיָּיא דְּיַתְבִין קַמָּךְ. כַּמָה דַּרְגִּין אִתְתָּקָנוּ לְכוֹן לְעָלְמָא דְּאָתֵי. כַּמָה בּוֹצִינִין דִּנְהוֹרִין זְמִינִין לְנַהֲרָא לְכוּ.","וְתָּא חֲזֵי, יוֹמָא דֵּין בְּגִינָךְ אִתְעַטָּרוּ חַמְשִׁין כִּתְרִין לְרִבִּי פִּנְחָס בֶּן יָאִיר חָמוּךְ. וַאֲנָא אֲזִילְנָא עִמֵּיהּ בְּכָל אִינּוּן נַהֲרֵי דְּטוּרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא, וְהוּא בָּרִיר דּוּכְתֵּיהּ, וְאִתְתָּקַּן. (ס\"א ואנא הא חזינא דהא בריר וכו') אָמַר לֵיהּ, קְטוּרִין צַדִּיקַיָּיא בְּקַרְטוּפָא דְּעִטְרִין, בְּרֵישׁ יַרְחֵי וּבִזְמַנֵּי וְשַׁבָּתֵי, יַתִּיר מִכָּל שְׁאַר יוֹמִין."],[[0,"תאנא בעוד דאתגליין","וכו׳: למדנו, בעוד שנגלו הדברים נתרגשו העליונים והתחתונים, וקול נתעורר והכריז בר״נ עולמות, כי דברים עתיקים נתגלו למטה. ובעוד שאלו היו מבשמים נשמותיהם באלו הדברים יצאה נשמתם בנשיקה ונתקשרה בפרסא ההיא, ולקחו אותם המלאכים העליונים והעלו אותם למעלה, מן ואמאי אלין, עד, עאלו ונפקי, ל״ג, כי גליון היה והמעתיקים הכניסו אותו בפנים."],[0,"","פירוש החלק שמחזה ולמטה דז״א, נבחן לר״נ עולמות. כי נצח והוד הם מאתים, וחצי ת״ת, הוא חמשים. וכבר נתבאר שסבת פטירתם היתה משום שהחלק שמחזה ולמטה קבל עם סיום האדרא כל תקונו ונתבטלה הפרסא, כנ״ל. וז״ש, \u0003אתרגישו עלאין ותתאין,\u0004 שגילוי הסודות תקנו כל הפרצוף הן מחזה ולמעלה והן מחזה ולמטה. \u0003וקלא אתער בר״נ עלמין,\u0004 דהיינו מחזה ולמטה, \u0003דהא מלין עתיקין לתתא אתגליין,\u0004 שמתגלים כל התקונים השייכים למחזה ולמטה, וכיון שאלו ג׳ החברים היו מבחינת מחזה ולמטה, ע״כ, \u0003ועד דאלין מתבסמן נשמתייהו באינון מלין,\u0004 דהיינו עם שהתקונים של נשמותיהם הולכות ונגמרות, \u0003נפקא נשמתייהו בנשיקה, ואתקשר בההוא פרסא,\u0004 יצאה נשמתם בנשיקה, ונקשרו בפרסא ההיא. כי משום שנשמותיהם היו מבחינת הפרסא ע״כ אחר שנשלמו ר״נ עולמות, ונתבטלה הפרסא, עלו נשמותיהם למעלה ביחד עם הפרסה. כנ״ל בדבור הסמוך."],[1,"אר\"ש כמה זכאה","וכו׳: א״ר שמעון, כמה מאושר חלקם של אלו השלשה, ואשרי חלקנו לעולם הבא בשביל זה. יצא קול שני ואמר, ואתם הדבקים בה׳ אלקיכם חיים כלכם היום. קמו והלכו. בכל מקום שהיו מסתכלים עלו ריחות. א\"ר שמעון, משמע מזה, שהעולם מתברך בשבילנו. ופניהם של כולם היו מאירים, ובני העולם לא יכלו להסתכל בהם."],[2,"תאנא עשרה עאלו","וכו׳: למדנו, עשרה נכנסו, באדרא, ושבעה יצאו ממנו. והיה ר״ש שמח, ורבי אבא עצב. יום אחד היה ר״ש יושב ור׳ אבא עמו. א\"ר שמעון דבר. וראו אלו שלשת החברים, שהיו מביאים אותם מלאכים עליונים, ומראים להם אוצרות וחדרים של מעלה, משום כבודם, והיו מכניסים אותם בהרי אפרסמון הטהור, נחה דעתו של ר׳ אבא."],[3,"תאנא מההוא יומא","וכו׳: למדנו, מהיום ההוא לא זזו החברים מבית ר׳ שמעון. וכשהיה ר״ש מגלה סודות, לא היו נמצאים שם אלא הם. והיה קוראם ר\"ש, שבעה אנו עיני ה׳. שכתוב, שבעה אלה עיני ה'. שעלינו נאמר. א״ר אבא, אנו ששה נרות המאירים משביעי, שה״ס בינה, אתה הוא שביעי של כולם, כי אין קיום לששה, שהם חג״ת נה״י, אלא משביעי, שהוא בינה. כי הכל תלוי בשביעי, ר׳ יהודה היה קוראו שבת, שכל ששת הימים מתברכים ממנו. שכתוב, שבת לה׳. קדש לה׳. מה שבת לה׳ קדש, אף ר״ש שבת לה׳ קדש."],[4,"אר״ש תווהנא על","וכו׳: א״ר שמעון, תמה אני על אותו חגור מתנים, בעל השער, שהוא אליהו, למה לא נמצא באדרא שלנו, בזמן שנתגלו אלו הדברים הקדושים. בתוך כך בא אליהו, ושלש טפות אור מאירים בפניו. א״ל ר״ש מה הטעם, לא היה נמצא אדוני במשתה היין החקוק וערוך לאדונו, ביום השמחה. \u0003קטפורי,\u0004 מורכבת מב׳ מלות קטפי אורה. דהיינו טפות אור. \u0003קרדוטא,\u0004 הוא מלשון קריריטון, שפירושו יין ערוך לבריאות (שבת י״ד)."],[5,"א\"ל חייך רבי","וכו׳: אמר לו אליהו, חייך רבי, ז׳ ימים מטרם שנכנסתם לאדרא שלכם, בחרו לפני הקב״ה כל אלו שיבואו ויהיו נמצאים עמו באדרא, ואני הייתי מוכן שם, ורציתי להמצא לפניו באדרא, ואז קשרוני בכתפי, ולא יכולתי ללכת, כי ביום ההוא שלחני הקב״ה לעשות נסים לרב המנונא סבא וחבריו, שנמסרו לארמון המלך, ועשיתי להם נס, שהפלתי בשבילם, הכותל של היכל המלך, ונסתבכו בקשרי הכותל ונפלו עמו, ומתו ארבעים וחמשה שרים. והוצאתי את רב המנונא וחבריו, והשלכתי אותם לבקעת אונו, וניצולו. וערכתי לפניהם לחם ומים, כי לא אכלו שלשה ימים. וכל אותו היום, שהייתם באדרא, לא נפרדתי מהם."],[6,"וכד תבנא אשכחנא","וכו׳: וכשחזרתי, מצאתי הפרסא, שלקחו אותה כל אלו העמודים דהיינו המלאכים, וג׳ מן החברים עליה. ושאלתי אותם, את המלאכים, ואמרו לי שזה הוא חלק הקב״ה משמחת ר״ש וחבריו. אשרי אתה ר״ש, ואשרי חלקך, וחלק החברים היושבים לפניך. כמה מדרגות נתתקנו לכם לעולם הבא. כמה מאורות המאירים עתידים להאיר לכם."],[7,"ות״ח יומא דין","וכו׳: ובוא וראה, יום הזה, העטירו בשבילך, המשים כתרים לר׳ פנחס בן יאיר חותנך, ואני הלכתי עמו בכל אלו נהרות של הרי אפרסמון הטהור. והוא בחר מקומו, ונתתקן. אמר לו, ר״ש, קשורים הצדיקים במקור העטרות, בראשי חדשים ובזמנים ושבתות, יותר מבכל שאר הימים."]],[]],[["אָמַר לֵיהּ, וְאַף כָּל אִינּוּן דִּלְבַר, דִּכְתִּיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ וְגוֹ'. אִי אִלֵּין אַתְיָין, כָּל שֶׁכֵּן צַדִּיקַיָּיא. מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ, לָמָּה. מִשּׁוּם דְּמִתְעַטְּרֵי אֲבָהָתָא רְתִיכָא קַדִּישָׁא. וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ, דְּמִתְעַטָּר שְׁבִיעָאָה דְּכָל אִינּוּן שִׁיתָא יוֹמִין, דִּכְתִּיב, (בראשית ב׳:ג׳) וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי וְגוֹ'.","וְאַנְתְּ הוּא רַבִּי שִׁמְעוֹן, שְׁבִיעָאָה דְּשִׁיתָא, תְּהֵא מִתְעַטָּר וּמִתְקַּדָּשׁ יַתִּיר מִכֹּלָּא. וּתְלַת עִדּוּנִין דְּמִשְׁתַּכְחִין בִּשְׁבִיעָאָה, זְמִינִין חַבְרַיָיא אִלֵּין צַדִּיקַיָּיא לְאִתְעַדְּנָא בְּגִינָךְ לְעָלְמָא דְּאָתֵי. וּכְתִיב (ישעיהו נ״ח:י״ג) וְקָרָאתָ לְשַׁבָּת עֹנֶג לִקְדוֹשׁ יְיָ מְכוּבָּד. מַאן הוּא קְדוֹשׁ יְיָ. דָּא רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, דְּאִקְרֵי מְכוּבָּד בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. (עד כאן האדרא קדישא רבא)"],[[0,"א״ל ואף כל","וכו׳: א״ל אליהו, ואף כל אלו שמבחוץ, יש להם אז עליה, שכתוב והיה מדי חדש בחדשו ומדי שבת בשבתו יבא כל בשר וגו׳. דהיינו אלו שמבחוץ, שאינם צדיקים, שע״כ קוראם הכתוב כל בשר אם אלו באים כל שכן הצדיקים. \u0003מדי חדש בחדשו,\u0004 למה. משום שאז מתעטרים האבות שהם מרכבה הקדושה. כלומר שאז חג״ת דז״א, הנקראים אבות, מתעלים ונעשו חב״ד. \u0003ומדי שבת בשבתו,\u0004 שאז מתעטר השביעי של ששת הימים, שאז קונה המלכות ג״ר. שכתוב ויברך אלקים את יום השביעי."],[1,"ואנת הוא ר״ש","וכו׳: ואתה הוא ר׳ שמעון, השביעי של הששה, תהיה מתעטר ומתקדש יותר מכל. וג' עדונים, דהיינו ג׳ סעודות, הנמצאים בשביעי עתידים החברים, הצדיקים האלו, להתעדן בשבילך לעולם הבא, וכתוב, וקראת לשבת ענג לקדוש ה׳ מכובד. מי הוא קדוש ה'. זה הוא ר׳ שמעון בן יוחאי, שנקרא מכובד בעולם הזה, ובעולם הבא."]],[]]]};
